window.RB_SHARDS=window.RB_SHARDS||{};window.RB_SHARDS[12]=[{"i":28800,"n":"מ' חיים מהורדנא וירושלים","f":"אברהם מהורדנא","dt":"תרלד - כג טבת","dp":"ירושלים","b":"עלה לירושלים."},{"i":28801,"n":"מאגדעבורג, דוד","b":"תלמיד ר יונתן איבשיץ. הו\"ל ספר רבו \"אהבת יהונתן\"."},{"i":28802,"n":"מאגולה, אברהם מאזמיר","dt":"תקכג - יד ניסן","dp":"אזמיר","b":"מחכמי איזמיר"},{"i":28803,"n":"מאגולה, חיים מקושטא","k":"בעל תוכחת מגולה","b":"מחכמי קושטא-שנות ה-תק'. חיבר גם \"קצות הארץ\", ועוד."},{"i":28804,"n":"מאג'ורו, אברהם משאראי","b":"דיין בשאראי אצל ר שם טוב בן יצחק צבי."},{"i":28805,"n":"מאג'ורו, אברהם פלטיאל מאיטליה","dt":"תעג - בערך","dp":"פדובה","b":"מחכמי איטליה."},{"i":28806,"n":"מאג'ורו, יהושע יצחק מאישפלאטו","b":"דיין באישפלאטו או סרייבו-תקד עם ר יעקב פרץ, ר אברהם מאיסטרו."},{"i":28807,"n":"מאג'ורו, משה מונציה","f":"דניאל","b":"רב בונציה בזמן ר יצחק חיים כהן מהחזנים. כתב בהקדמת שו\"ת ר יו\"ט צהלון. תשובה ממנו ב\"לקט הקמח\"."},{"i":28808,"n":"מאג'ורו, שלמה משלוניקי","dt":"שלז - ז שבט","dp":"שלוניקי","b":"מחכמי שלוניקי."},{"i":28809,"n":"מאגיליאנער, מנחם מאיר מירושלים","b":"תלמיד ישיבת \"שפת אמת\" בירושלים. פרסם מאמרים ב\"תורה מציון\" - ירושלים תרצה - בהוצאת ישיבת \"שפת אמת\"."},{"i":28810,"n":"מאגריסו, אברהם מאדרינופול","b":"רב באדרינופול-שנות ה-ת'."},{"i":28811,"n":"מאגריסו, יהושע מבלגרד","dt":"תקמח - בערך","b":"רב הכולל בבלגרד-תקמח, וקרובו ר עזריאל יחיאל מאגריסו על מקומו אחריו."},{"i":28812,"n":"מאגריסו, יצחק מקושטא","f":"משה","k":"בעל מעם לועז","b":"רב בקושטא. המשיך את כתיבת \"מעם לועז\" לר יעקב כולי. (מפרשת תרומה ועד סוף במדבר). אחיו ר רפאל סייע לו בהדפסת ספרו."},{"i":28813,"n":"מאגריסו, עזריאל יחיאל מבלגרד","dp":"בלגרד","b":"רב בבלגרד-תקס על מקום ר ישכר אבולעפיה (ולפי רוזניס על מקום ר יהושע מאגריסו) ובנו ר רפאל על מקומו אחריו, ונזכר ב\"קהילת יעקב\" לר יעקב משה חי אלטראץ מבלגרד, שהעיד שראה את מצבתו בבלגרד."},{"i":28814,"n":"מאגריסו, רפאל","f":"משה","b":"אחיו של ר יצחק בעל מעם לועז, וסייע לו בהדפסת ספרו."},{"i":28815,"n":"מאגריסו, רפאל מבלגרד","f":"עזריאל יחיאל מבלגרד","b":"רב בבלגרד-תקץ על מקום אביו. נזכר ב\"קהילת יעקב\" לרי\"מ אלטארץ."},{"i":28816,"n":"מאדאוויץ, שמואל מלודז","b":"פרסם הספד לבן האדמור מאלכסנדר ב\"נהור שרגא\" - אלכסנדר תרצט."},{"i":28817,"n":"מאדאר, חיים מג'רבה","bt":"תרצג","bp":"ג'רבא","dt":"תשסה - כ כסלו","b":"מרביץ תורה,רב ראש של ג'רבא ותוניסיה"},{"i":28818,"n":"מאדורא פישוטו, משה לוי מקורסאו","bt":"תקכז","bp":"קורסאו","dt":"תקפח - ו אב","dp":"ניו יורק","b":"רב בקורסאו, הגיע לניו יורק-תקסז וכיהן כרב \"שארית ישראל\" בניו יורק, על מקום ר גרשום מינדיס סייקסאס. קרוב של ר שלמה ליוואי (הלוי) מאדורא."},{"i":28819,"n":"מאדורא, מרדכי מקורסאו","b":"רב ודיין בקורסאו-תקלד אצל ר יעקב לופיס די פונסיקא."},{"i":28820,"n":"מאדורא, שלמה הלוי מקורסאו","b":"רב בקורסאו-תקצז. קרובו של ר משה מאדורו."},{"i":28821,"n":"מאדיבורג, אליהו מגעטינגען","b":"גביר בגעטינגען-תצז. סייע לר בנימין וולף גינצבורג שלמד רפואה באוניברסיטה שם."},{"i":28822,"n":"מאדל, אליהו הלוי מוינה","b":"דיין או מנהיג קהלת וינה, לאחר הגירוש-תל הגיע לאלטונא."},{"i":28823,"n":"מאדן, בן ציון","dt":"תשד","b":"רב בגלאגוב"},{"i":28824,"n":"מאהליבסקי, אברהם יצחק","f":"מרדכי משוינציאן"},{"i":28825,"n":"מאהלר, זלמן","b":"רב בציפער-תרל\"ג,דומ\"צ בפרשבורג"},{"i":28826,"n":"מאהלר, זלמן מפרשבורג","b":"גיסו של ר יהודה אסאד. רב בציפר-ליד פרשבורג, דיין בקהלה הניאולוגית בפרשבורג-תרלג אצל ד\"ר יוליוס דוד."},{"i":28827,"n":"מאהלר, יצחק איזיק מפרג","k":"בעל מפלשי השמות","b":"מדקדק מחכמי פרג. חיבר \"מפלשי השמות\" פרג 1829, \"מנחה בלולה\"."},{"i":28828,"n":"מאהלר, מנחם אליעזר מצאנז","f":"יצחק אשר","k":"בעל תולדות החסידים","bt":"תרב","bp":"צאנז","dt":"תרפב","b":"מחכמי צאנז. בעל חנות ספרים ומהדיר ספרים וביניהם: \"שפת אמת לר משה חגיז, \"תולדות המחקוקים הנוצרים\", \"תולדות החסידים\" קראקא תרנא."},{"i":28829,"n":"מאהצאר, מסעוד מג'רבה","b":"פרסם מאמרים ב\"הירח\" - ג'רבה תשח."},{"i":28830,"n":"מאהר, אברהם מנדל","k":"בעל ערוגת הבשם","b":"תרגם \"קולומבוס\" מגרמנית. חיבר \"ערוגת הבשם\". בעיר וילנא ב' - מעיר כי הוא חשוד בהעתקה מ\"לקוטי פרחים\" לדוקעס, ועוד."},{"i":28831,"n":"מאהר, אברהם מצילץ","b":"רב בצילץ. היה מהמערערים על הגט מקליווא-תקכו."},{"i":28832,"n":"מאהר, זאב וולף","b":"רב במיכלשטט-תר\"ה"},{"i":28833,"n":"מאהר, זליג מראב","f":"יהודה ליב ממאר","dt":"תקצז","dp":"ראב","b":"נכד ר פנחס זליג מפאפא. תלמיד החת\"ס. מחכמי טעט, ראב-תקעח."},{"i":28834,"n":"מאהר, מנחם מנדל מזבלטוב","bt":"תקפו","dt":"תרמח","b":"רב בפטשניזין-תרך, זבלטוב."},{"i":28835,"n":"מאהר, מרדכי אריה","f":"חיים אברהם","k":"אדמור מלמברג","b":"נכד ר מאיר מפרימישלן. אדמור בלמברג-תרצב."},{"i":28836,"n":"מאהר, נפתלי מטורנא","f":"שלמה","bt":"תרסז","bp":"טורנא","dt":"תשב","b":"חתן ר אורי קאנט מבובוב. רב בפטשניזין-תרך. מחכמי בובוב ואח\"כ גורליץ. נספה בשואה."},{"i":28837,"n":"מאהר, שלמה מבראילוב","f":"מנחם מנדל מזבלטוב","k":"בעל דברי שלמה","bt":"תרי","dt":"תרעה","b":"נסמך מאת: ר יוסף שאול נתנזון מלבוב. רב בזבלטוב-תרך, גלעץ, ברילוב(=בריולוב, בראיולוב)-תרלג. בנו ר צבי הירש על מקומו אחריו. חיבר \"דברי שלמה\" סיגט תרסו."},{"i":28838,"n":"מאהר, שלמה עזרא מפוניבז","b":"מיסד וראש הישיבה הקטנה בפוניבז - שישבה ב\"קלויז גליקל\" - תרס בערך."},{"i":28839,"n":"מאהרשן, יצחק","k":"בעל פרשנדתא","bt":"תרנב","dt":"תשג","b":"דיין באמסטרדם-תרע\"ט,רב בהאג-תרפ\"ה"},{"i":28840,"n":"מאונן, אברהם מירושלים","b":"בשנת תקמא חתום כסופר הקהלה בירושלים"},{"i":28841,"n":"מאור קטן, יהודה ליב","f":"משה מאור קטן","k":"י' ליב רופא מאור קטן","dt":"שצה - ח אייר","b":"רופא מומחה,עשיר,רב פעלים,רב בווינה,עבר לפוזנא-ת\"ל(בגירוש)"},{"i":28842,"n":"מאור קטן, מאיר","k":"חתן הלבוש","b":"מגדולי חכמי ווילנה-שנת ת'"},{"i":28843,"n":"מאור קטן, משה","dt":"שסח - ב אדר","b":"רופא,רב בפפד\"מ-ש\"מ,ווינה"},{"i":28844,"n":"מאז, מרדכי מפפד\"מ","f":"נתן בעל בנין שלמה","dt":"תקנט","b":"מראשי קהילת פפד\"מ-תקלח, ממנהלי קרן הצדקה של ליב רייס. בנו - ר שלמה."},{"i":28845,"n":"מאז, נתן מפפד\"מ - א","b":"מראשי קהילת פפד\"מ. היה במשלחת יהודי פפד\"מ אל הקיסר יוזף-תסב."},{"i":28846,"n":"מאז, שלמה מפפד\"מ","f":"מרדכי מפפד\"מ","dt":"תקנו","b":"מחכמי פפד\"מ."},{"i":28847,"n":"מאז, שלמה מפפד\"מ","f":"נתן","dt":"תקכד - טז אד\"ב","dp":"פפד\"מ","b":"מחכמי פפד\"מ."},{"i":28848,"n":"מאזך, שמואל מספרד","b":"מחכמי ספרד, תלמיד הרא\"ש, חברו של ר אלעזר הכהן."},{"i":28849,"n":"מאטארון (מטרין), יוסף","k":"ר יוסף מטרין","b":"מחכמי צפת, בשנת תכה בשליחות, אולי הוא נכדו של ר יוסף בן אליעזר מאטארון תלמידו של ר משה אלשיך."},{"i":28850,"n":"מאטארון, אליעזר","f":"יוסף","b":"ראש הרבנים בצפת בשנת תכד, תלמידו של ר משה אלשיך, נזכר בתעודה משנת תכד"},{"i":28851,"n":"מאטלה, שמואל ממצרים","b":"מחכמי מצרים, תלמיד הרדב\"ז."},{"i":28852,"n":"מאטלין, ברוך מרדכי משוערסקא","b":"רב בשבדסקה(=שוערסקא)-מחוז סוראז-תרמ, וחתנו ר יעקב ישראל פלוטקין על מקומו אחריו."},{"i":28853,"n":"מאטלין, יהושע הכהן מסלוצק","f":"עקיבא הכהן מסלוצק","b":"אביו היה תלמיד הגר\"א. ר\"מ בישיבת סלוצק. בנו - ר עקיבא מטלין(=מאטלין)."},{"i":28854,"n":"מאטלין, מיכל אשר הכהן מדברלין","f":"עקיבא מהיינא-פלך מינ","bt":"תרמ","b":"תלמיד ישיבת סלוצק, מיר. נסמך מאת: ר אבא ורנר מלונדון, ר מנחם דב דאניצקא ממנצסטר. חתן ר יצחק מאיר יוסלזון מדבלין-אירלנד. רב בדובלין(=דבלין)-תרסט לצד חותנו."},{"i":28855,"n":"מאטלין, עקיבא הכהן מהיינה","f":"יהושע מסלוצק","b":"נכד ר עקיבא הכהן מסלוצק. רב בהיינא-פלך מינסק-תרנה. חתנו - ר ניסן עסקין מהורודוק. בנו - ר אשר מטאלין."},{"i":28856,"n":"מאטלין, פסח פנחס הכהן ממינסק","f":"שאול","dt":"תרנו - טו אלול","dp":"מינסק","b":"מחכמי מינסק."},{"i":28857,"n":"מאטצל, אשר משטמפן","b":"מחכמי שטמפן, חתם-תקנט על מינוי ר לוי פולק לרב בשטמפן."},{"i":28858,"n":"מאי, אריה מפרשבורג","b":"ר\"מ בישיבת פרשבורג. נספה בשואה."},{"i":28859,"n":"מאיו די, אלברט משלוניקי","b":"רופא בשלוניקי-תרס."},{"i":28860,"n":"מאיו, אברהם מאזמיר","b":"מרבני איזמיר-תרל\"ו"},{"i":28861,"n":"מאיו, יצחק מלארסו(=לאריסה)","dt":"תצא - אחרי","b":"חתן הגביר אברהם (או יוסף) סידיס מלאריסה. גביר בלאריסה, הבנקאי של אוסמן פאשה בלאריסה. תמך בהדפסת \"טירת כסף\" לר אברהם גטניו-תצד."},{"i":28862,"n":"מאיו, יצחק מקאשטוריאה ואזמיר","f":"משה בן שמעיה","b":"גביר מחכמי קאשטוריאה-שנות ה-ת', עבר לאזמיר. סייע בהדפסת \"כנסת הגדולה\"."},{"i":28863,"n":"מאיו, יצחק מקושטא","b":"גביר בקושטא. יסד את ישיבת \"נוה שלום\" בירושלים-תקיח בערך."},{"i":28864,"n":"מאיו, מרדכי נחום מאזמיר","b":"בנו חורגו ותלמידו של ר רפאל יצחק מאייו בעל \"שרשי הים\", ו\"דרכי הים\". מתורתו בספר \"דרכי הים\"."},{"i":28865,"n":"מאיו, משה מאלכסנדריה","b":"מחכמי אלכסנדריה-שסב, ומובא בשו\"ת ר יעקב קשטרו."},{"i":28866,"n":"מאיו, משה ממונשטיר וקאסטוריה","b":"דיין במונשטיר-שנות ה-ת' אצל ר בנימין די מדינה, קאסטוריה על מקום ר מנחם רוסו, ובנו - ר שמעיה על מקומו אחריו."},{"i":28867,"n":"מאיו, משה מקאשטוריא - הנכד","f":"שמעיה","b":"נכד ר משה ממונשטיר וקאשטוריאה. רב בקאשטוריאה על מקום אביו-שנות ה-ת' (ולפי רוזניס-ה רב על מקום ר אברהם גראסיאני)."},{"i":28868,"n":"מאיו, משה משלוניקי","b":"רב בשלוניקי-שפ."},{"i":28869,"n":"מאיו, רפאל יעקב מרודוס","b":"תלמיד ר עזרא מלכי מצפת ורודוס, והו\"ל את ספרי רבו, וחיבר הקדמה ל\"עין משפט\" לרבו - קושטא תקל. רב ברודוס-תקן בערך."},{"i":28870,"n":"מאיו, רפאל יצחק מאזמיר","f":"אהרן","k":"בעל שרשי הים","r":"רב הכולל באיזמיר בתקופת היר\"ח – החק\"ל","bt":"תע","bp":"קושטא","dt":"תקע - כא אלול","b":"ראש ישיבה באזמיר, דיין, רב באזמיר-תקנד על מקום ר חיים מודעי - שעלה לארץ, אחד מדייני בית דינו היה ר יוסף חזן. חיבר \"שפת הים\", \"דרכי הים\", \"פאת ים\". נפטר ללא בנים. מתלמידיו ר מרדכי נחום שסייע בהדפסת ספריו. לפי רוזניס נתמנה בידי ר חיים דוד אבולעפיה לרב אחריו יחד עם ר יוסף חזן והיה מחלוקת על כך.","bk":[["שרשי הים [על רמב\"ם]",""],["פאת ים –– דרכי הים, שרשי הים",""]]},{"i":28871,"n":"מאיו, שלמה די מוינה","b":"גביר מראשי קהלת הספרדים בוינה-תקס בערך. סייע לר יהודה ן סיד בהדפסת ספרו \"נר מצוה\"."},{"i":28872,"n":"מאיו, שמעיה מקאסטוריא","f":"משה ממונשטיר","b":"רב בקאשטוריה(=קאסטוריא)-שנות ה-ת' על מקום אביו, ובנו - ר משה על מקומו אחריו."},{"i":28873,"n":"מאיור ן, דוד משלוניקי ובאזארג'","f":"דניאל","b":"רב בבאזארג'יק-ליד שלוניקי-תקס."},{"i":28874,"n":"מאיור ן, יצחק מיוזיל-היסאר","b":"מראשי קהלת יוזיל-היסאר-ליד אזמיר-שנות ה-ת'."},{"i":28875,"n":"מאיור ן, ישעיה משלוניקי","dt":"תקכב","dp":"שלוניקי","b":"מחכמי שלוניקי. נפטר במגפה-תקכב."},{"i":28876,"n":"מאיור ן, משה משלוניקי","f":"שלמה","b":"מחכמי שלוניקי-שץ, תלמיד בישיבת אביו."},{"i":28877,"n":"מאיור ן, שאול משלוניקי","f":"ישעיה","dt":"תקכד","dp":"שלוניקי","b":"מחכמי שלוניקי. הניח פסקים בכת\"י (ונמצאים בספריה הלאומית בירושלים)."},{"i":28878,"n":"מאיור ן, שלמה משלוניקי - א","dt":"שצג-ה","dp":"שלוניקי","b":"תלמיד המהרש\"ך משלוניקי. ראש ישיבת \"בעלי תשובות\" בשלוניקי. ק\"ק \"מאיור\" בשלוניקי נקראה גם ק\"ק \"בעלי תשובה\", משום מוצאם מאנוסי מאיורקה. מתלמידיו ר יוסף פלורנטין, ר שמואל הכהן, ר אברהם פאלקון, ר חיים הלוי, ר משה די אבילה ועוד. בנו ר משה ן מאיור. תשובה ממנו בשות ר ברוך אנג'יל."},{"i":28879,"n":"מאיור ן, שלמה משלוניקי - ב","dt":"שצד - כב תמוז","dp":"שלוניקי","b":"מחכמי שלוניקי."},{"i":28880,"n":"מאיי, משה ממיץ","b":"מדפיס במיץ, הו\"ל-תקכח תלמוד עם רי\"ף ומפרשים נוספים והספיק להדפיס 4 מסכתות."},{"i":28881,"n":"מאייר, אברהם הלוי","b":"רב מזמנו של החת\"ס. מתורתו ב\"שערי אורה\" - מיהאלביץ תרץ-תרצד."},{"i":28882,"n":"מאייר, אברהם מאנדאק","f":"אליעזר מבודפשט","k":"בעל נפש לאברהם","bt":"תרסד","bp":"בודפשט","dp":"אושוויץ","b":"תלמיד הדעת סופר, ור יהושע בוקסבוים מגאלאנטא. חתן ר משה חיים ליטש-רוזנבוים מקלינורדין. רב במאנדאק-תרצח. נספה בשואה."},{"i":28883,"n":"מאייר, אברהם מצרפת ואלגיר","b":"רב בתלמסאן מטעם הקונסיסטואר-תרן, אלמעסכר-תרסב. חיבר ספר בצרפתית לתולדות רבני תלמסאן והקהלה."},{"i":28884,"n":"מאייר, אברהם סגל מנעמש-סאלק","b":"אב\"ד נעמעש-סאלוק. חתנו - ר משה לינק מפאפא. פרסם מאמרים ב\"הנשר\" - טירנוי תרצג-תשד."},{"i":28885,"n":"מאייר, אהרן אריה מרוזניאטוב","f":"ישראל מנוביסליץ","k":"אדמור מפרימישלן","bt":"תקף","dt":"תרמג","b":"רב ואדמור מפרימישלן-נדבורנה ברוזניאטוב. חתן ר אהרן שמואל מקיזמון."},{"i":28886,"n":"מאייר, אלעזר מטרניץ","b":"חתן ר משה יצחק טאכוי מאיזנשטט. חתנו - ר שמואל גרינולד משופרון."},{"i":28887,"n":"מאייר, אשר מטורנא","b":"מחכמי טורנא - ממשתתפי \"אסיפת חכמים-תרעד."},{"i":28888,"n":"מאייר, בונונטורה","b":"מומר. פרופסור ללשון בוינה. ביקר במזרח אירופה-1825 וחיבר ספר בגרמנית \"היהודים בזמננו\" ובו מתאר באהדה את החברה החסידית."},{"i":28889,"n":"מאייר, זאב אלעזר מסנוק","b":"פרסם מאמרים ב\"אסיפת חכמים\" - אטיניא-בויאן תרע-תרעד."},{"i":28890,"n":"מאייר, זאב דב אלתר מסנוק","f":"ישראל הלוי","k":"בעל לא תענה על רב","bt":"תרנא","bp":"סנוק","dt":"תשכו","b":"חתן ר קלמן ליברייך. מחכמי מנוסטרישץ ועוסק במסחר. רב בבסוקוביץ בזמן מלחמת העולם הראשונה. עלה לארץ תרצג, התפרנס ממסעדה בתל אביב ופרסם בעתונים שונים. חיבר \"לא תענה על רב\" פרשבורג תרעח, ועוד. פרסם מאמרים ב\"אסיפת חכמים\" - אטיניא-בויאן תרע-תרעד."},{"i":28891,"n":"מאייר, חיים ברוך","f":"משה","k":"בעל אוצר המדרש","b":"חיבר \"אוצר המדרש\"."},{"i":28892,"n":"מאייר, חנוך הניך מקרצקי","f":"יוסף דוד מסאסוב","k":"אדמור מסאסוב","r":"אב\"ד סאסוב ובסוף ימיו בקערעצקיא","bt":"תרמד","bp":"סאסוב","dt":"תשג - ז חשון","b":"לאחר שנתייתם גדל אל זקנו ר שלמה מאייר מסאסוב. חתן ר חנניה יו\"ט ליפא מסיגט בעל \"הקדושת יו\"ט\", ובזיוו\"ש חתן ר יצחק מאיר הגר מסטנוביץ. רב בסאסוב-תרסד עם גיסו ר יצחק מושקוביץ. ואדמור בסאסוב-תרעט על מקום זקנו. עבר לקרצקי-קרפטרוס-תרפג (בגלל רדיפות הפולנים), ובזמן השואה ברח אל בנו בסטמר, נספה בשואה. בנו ר יצחק מאיר על מקומו אחריו. חיבר הגהות למדרש רבה, \"עיר חנוך\" ירושלים תשלח, ו\"עין חנוך\".","bk":[["יד חנוך","שו\"ת - אחרונים"],["יד חנוך - שו\"ת",""],["מפענח נעלמים - ביאורים ובירורים בעיניינים שונים",""],["עין חנוך - רמב\"ם ושו\"ע",""],["עיר חנוך - על התורה",""],["עיר חנוך - על התורה , יד חנוך - שו\"ת , מפענח נעלמים - ביאורים ובירורים בעיניינים שונים, עין חנוך - רמב\"ם ושו\"ע",""]]},{"i":28893,"n":"מאייר, חנניה יום טוב ליפא","f":"חנוך הניך מסאסוב","bt":"תרסה","dt":"תשכו - יב אדר","dp":"טבריה","b":"תלמיד דודו בעל \"עצי חיים\" בסיגט. חתן דודו ר יואל טיטלבוים בעל \"ויואל משה\", ועבר עמו מקרולה לסטמר, ובזיוו\"ש חתן ר יוסף שטרום. נבחר לרב בסמיהאלי אך נשאר ליד חותנו בסטמר וניהל את הישיבה שם וכיהן כדיין אצל ר משה דוד וינטרניץ. ניצל מהשואה ואחריה הגיע לירושלים, וכיהן כאדמור מסאסוב - החליף שמו לטיטלבוים כשם אמו וחותנו. עבר לנ\"י עם חותנו-תשח, חזר לארץ-תשכג והקים קריה חרדית - \"ישמח משה\" בקרית אונו. חיבר \"מנחת יום טוב\"."},{"i":28894,"n":"מאייר, יואל מאלסק-יאס","f":"יחיאל מאלסק","bt":"תרסו","b":"חתן ר שמואל שמלקא טויביש מיאס. רב ביאס, עלה לארץ-תשד, היגר לארה\"ב-תשט."},{"i":28895,"n":"מאייר, יוסף דוד מסאסוב","f":"שלמה מסאסוב","bt":"תרכב","dt":"תרן - כה שבט","b":"חתן ר יעקב מרדכי סגל ליברמן מטופורוב. נפטר בחיי אביו. חתניו: ר שמשון איכנשטין מאלסק, ר זינדל באבד מברוד, ר יצחק מוסקוביץ משאץ."},{"i":28896,"n":"מאייר, יוסף מקראקא","b":"מחכמי קראקא - ממשתתפי \"אהל מועד\"."},{"i":28897,"n":"מאייר, יחיאל מיכל מסאסוב","f":"שלמה מסאסוב","k":"אדמור מסאסוב בלמברג","bt":"תרל","dt":"תרף","b":"אדמור בלבוב-תרעט."},{"i":28898,"n":"מאייר, יצחק זאב ממונט קיסקא","k":"בעל מהרש\"א הארוך","b":"ר\"מ בישיבת נייטרא במאונט קיסקא. חתן ר דוד צבי פעטעני הי\"ד מפ\"ב - אשר התחיל לחבר \"מהרש\"א הארוך\" וחתנו ר יצחק זאב השלימו. פרסם מאמרים ב\"הלכות החדש\" - טירוני תרצא - קובץ מאת תלמידי ר שמואל דוד אונגר מטירנוי."},{"i":28899,"n":"מאייר, יצחק מאיר מקרצקי","f":"חנוך הניך מקרצקי","bt":"תרפט","dt":"תשה - כז אייר","dp":"מחנה אבנזע - טבריה","b":"רבה האחרון של קרצקי על מקום אביו. נספה בשואה. מתורתו ב\"עיר חנוך\"."},{"i":28900,"n":"מאייר, יצחק מאלסק","f":"חנוך הניך מאלעסק","k":"אדמור מסאסוב באלסק","bt":"תקפט","dt":"תרסד - כד אדר","b":"נכדו של השר שלום מבלז. רב ואדמור באלסק על מקום אביו. חתן ר יוסקא מאולשקוביץ(=לאשקוביץ). בנו ר שמשון על מקומו אחריו באלסק. חתנו ר אהרן מנחם אייכנשטיין על מקומו אחריו כאדמור."},{"i":28901,"n":"מאייר, יצחק מקלוש","f":"אהרן אריה מרוזניאטוב","k":"בעל גדולים צדיקים","bt":"תרך","dt":"תש","b":"רב ברוזניאטוב על מקום אביו, רב ואדמור בקאלוש על מקום סבו, מגדבורג. חיבר \"גדולים צדיקים\" סטרי תרצב."},{"i":28902,"n":"מאייר, ישראל איסר מפרשבורג","b":"מחכמי פרשבורג. חתן ר מרדכי אפרים פישל סופר מפרשבורג. חתנו - ר מרדכי וינר מפרשבורג, ר אהרן הלוי וייס משוראן, ור שמואל פידנטל מגאיטיין."},{"i":28903,"n":"מאייר, ישראל מסנוק","f":"זאב דב אלתר","bt":"תרכה","bp":"סנוק","dt":"תשה","dp":"ירושלים","b":"חתן ר משה אהער מחירוב. התישב בחירוב ועסק בצרכי צבור. עלה לארץ-תרפז."},{"i":28904,"n":"מאייר, ישראל מקלוש","f":"יצחק מקלוש","k":"אדמור מקלוש","bt":"תקס","dt":"תרם - כה אדר","b":"נינו של ר מאיר מפרמישלן. רב בנובוסליץ. אדמור בקאלוש-תר על מקום אביו."},{"i":28905,"n":"מאייר, מרדכי יוסף מצורטקוב","f":"מאיר אריה מצורטקוב","k":"בעל מאמר מרדכי","bt":"תרעה","bp":"צורטקוב","dt":"תשמב","b":"תלמיד ישיבת חכמי לובלין. חתן ר אלימלך פורילה מהוסיאטין. רב בניו יורק. חיבר \"מאמר מרדכי\" ניו יורק תשא. ?? לא באוצר ??"},{"i":28906,"n":"מאייר, שלום שכנא מסנוק","f":"ישראל מסנוק","bt":"תרמו","dt":"תרץ","dp":"וינה","b":"חתן הגביר ר שניאור זלמן שכטר מפולטושן. עבר לפולטושן ועסק במסחר. עלה לארץ-תרף ועסק בפעילות צבורית. על שמו הישוב \"תל שלום\" ובניו קראו למגדל שהקימו - שלום מאיר לזכרו."},{"i":28907,"n":"מאייר, שלמה זלמן מקראקא","b":"מחכמי קראקא-תרנו."},{"i":28908,"n":"מאייר, שלמה מסאסוב","f":"חנוך הניך דב מאלסק","k":"אדמור מסאסוב","bt":"תקצה-ט","dt":"תרעט - יב אד\"ב","dp":"לבוב","b":"נכד השר שלום מבלז, וגדל אצלו. מקורב לאדמורים ר אליעזר מדזיקוב, ר יצחק מאיר מזינקוב, ר אברהם מסטרטין. חתן ר צבי אריה ברנדויין מפלשטין (דודה היה ר ישראל מרוזין). רב ואדמור בסאסוב-תרמד על מקום אביו - האדמור מאלסק, עבר לאושפיצין-תרעד, לאחר מלחמת העולם הראשונה עבר ללבוב. חיבר \"מנחה חדשה\". היה בעל כח זכרון מיוחד וזכר את כל מי שבא אליו. חתניו: ר אלעזר רובין, ר אברהם מרדכי שלום טויב מפמורין. נקבר ליד ידידו ר יצחק שמלקיס בלבוב. לתולדותיו ב\"מעולפת ספירים\"-לבוב תרץ.","bk":[["מנחה חדשה",""]]},{"i":28909,"n":"מאייר, שם טוב מדברצין","b":"תלמיד ר שמואל דוד אונגר בישיבת טירנוי. פרסם מאמרים ב\"הלכות החדש\" - טירוני תרצא - קובץ מאת תלמידי ר שמואל דוד אונגר מטירנוי, \"משא ומתן\" - טירנוי תרצא."},{"i":28910,"n":"מאייר-טיטלבוים, יואל מקירלהאז","f":"חנוך הניך מססוב קרנצ","b":"חתן ר יוסף לעווי מקיראלהאזא. עזר לאביו בניהול הישיבה בקרענצקי, רב בחוסט, קיראלהאזא על מקום חותנו. עבר לאמריקה וכיהן כרב בניו יורק. הו\"ל ספרי אביו."},{"i":28911,"n":"מאיירס, אברהם מארה\"ב","b":"עסקן מחכמי ניו יורק."},{"i":28912,"n":"מאיירס, פנחס אברהם מהאג","b":"רב בהאג."},{"i":28913,"n":"מאיית יעיש","b":"למדן, צדיק במרוקו"},{"i":28914,"n":"מאיסטרו, אברהם מאישפלאטו","b":"דיין באישפלאטו-תקד עם ר יעקב פרץ, ר יהושע יצחק מאג'ורו."},{"i":28915,"n":"מאיסטרו, ברוך מטבריה","k":"בעל חידות ושירים","dp":"וינה","b":"מחכמי טבריה-שנות ה-תק'. בשליחות באיטליה. חיבר חידות ושירים - פדובה. הגהות על שו\"ע בכת\"י."},{"i":28916,"n":"מאיסטרו, ברוך מטבריה - א","k":"בעל הגהות על שו\"ע","b":"רב בטבריה-ת' ור יעקב אבולעפיה על מקומו אחריו, בשליחות באירופה. חיבר הגהות לשו\"ע - בכת\"י."},{"i":28917,"n":"מאיסטרו, חיים ברוך","dp":"וינה","b":"מחכמי צפת וסופר הקהל, בשנת תקס שליח צפת וטבריה באירופה. בתקסה היה בפיורדא, בתקסח יצא בשליחות ירושלים. בשנת תקעד בשליחות חברון ואז ביקר כתשעים קהלות. היה בקי בשיר, והוא שר בחתונת ר עזריאל בן יעקב טריאסטי, (נדפס ב\"שבלים בודדות\" לדיינרד). פנקסו בספריה הלאומית עם חתימות רוב ראשי הקהלות בגרמניה. נפטר בשליחותו"},{"i":28918,"n":"מאיקא, יעקב","dt":"תשג","b":"רב בווארענא"},{"i":28919,"n":"מאיר","b":"רב-שנת תק\"נ. אביו של ר אליעזר ליפא"},{"i":28920,"n":"מאיר","b":"רב-שנת תק\"כ. בנו ר פנחס אליהו"},{"i":28921,"n":"מאיר","f":"פתחיה","k":"בעל הגהות לילקוט שמע","b":"חיבר הגהות לילקוט שמעוני - לובלין תג. עם הסכמת ר יהושע השל מלובלין ובריסק."},{"i":28922,"n":"מאיר אברהם מטשאבא","k":"בעל פרי צדיק","dt":"תקפט - כו אדר","b":"רב בטשאבא(=האיו-צ'אבא). חתניו - ר משה ליברמן מאבראהאם, ר פנחס דוד קליין מבוקין, ר שמעון ליברמן משעניא, ר יוסף פינקלשטין ממישקולץ, ר נתן מטשאבא, ר יצחק יוסף בליך מגאווע, ור ישכר דב בר קאהן מסנזשארץ."},{"i":28923,"n":"מאיר אברהם ממאנדוק","dt":"תשד","b":"רב במאנדוק. נספה בשואה."},{"i":28924,"n":"מאיר אנטעקאליער מוילנא","f":"שלמה זלמן","dt":"תקפב - יט ניסן","dp":"וילנא","b":"מלמד תורה בוילנא."},{"i":28925,"n":"מאיר אריה מירושלים","b":"מחכמי ירושלים, בשנת תקסא חתם על תקנת היורדים."},{"i":28926,"n":"מאיר בן יצחק איזיק מקופנהגן","bt":"1737","dt":"ה'תקסט 1809","bk":[["קולי יעקב",""],["קרן אור פני משה",""]]},{"i":28927,"n":"מאיר בן לוי יצחק מברדיצ’ב","bt":"1760","dt":"ה'תקסה 1805","bk":[["כתר תורה",""]]},{"i":28928,"n":"מאיר בנימין","b":"רב-שנת תר\"ל. אביו של ר צבי חיים פרידמן."},{"i":28929,"n":"מאיר גאון מארץ ישראל","f":"אהרן בן מאיר","b":"גאון ארץ ישראל אחרי שנת ד'תרצב (932)."},{"i":28930,"n":"מאיר דרשן מקראקא","b":"דרשן בקרקא-ת\"ל"},{"i":28931,"n":"מאיר הכהן מאויבן","b":"מו\"צ באויבן-ר\"י"},{"i":28932,"n":"מאיר הכהן מאשכנז","k":"בעל הגהות מיימוני","b":"מגדולי הפוסקים של חכמי אשכנז-שנת ל'. חיבר הגהות מיימונית\". גיסו של ה\"מרדכי\"."},{"i":28933,"n":"מאיר הכהן מהנובר","f":"ישכר בער הכהן מהמבור","b":"רב בהנובר-תק."},{"i":28934,"n":"מאיר הכהן מלוטימורסק","dt":"תקצב","b":"חתן ר יהודה ליב קמפנר מפלוצק. רב בלוטימורסק. הניח חיבור על כמה מסכתות ושו\"ת."},{"i":28935,"n":"מאיר הכהן ממגנצא","f":"שמואל","k":"ר' מאיר הכן מנורטהוי,ופפד\"מ","b":"רב במגנצא-קכה - יחד עם זקנו ר יעקב, קלן, פפד\"מ-קמה. בנו - ר יעקב מקלן."},{"i":28936,"n":"מאיר הכהן מנרבונא","f":"שמעון","k":"בעל ספר המאורות","dt":"כד - ח חשון","b":"מגדולי חכמי פרובינציה בטולידו שבספרד-שנת ס'. חיבר \"ספר המאורות\"."},{"i":28937,"n":"מאיר הכהן מסופיה","f":"אברהם מסופיה","b":"גביר בסופיה-שנות ה-ת'-תק'. בנו - אליעזר מסופיה."},{"i":28938,"n":"מאיר הכהן מסרגוסה","k":"הרמ\"ך","b":"מגדולי הראשונים,מרביץ תורה בסרקוסטה-ד'תתקצ\"ה. חיבר שיטה על השס"},{"i":28939,"n":"מאיר הכהן מקאליש","b":"רב בקאליש. מנהיג ארבע ארצות, חתם-תמז ביריד ירוסלב."},{"i":28940,"n":"מאיר הכהן משיניבה","b":"רב בשיניבה-תריט."},{"i":28941,"n":"מאיר הכהן מתילית-מרוקו","b":"מחכמי תילית-מרוקו, חתם-תרס בערך על תקנה של השד\"ר ר מסעוד אדהאן."},{"i":28942,"n":"מאיר הלוי מאוסטרהא","f":"אהרן","dt":"תקנב - יז סיון","dp":"אוסטרהא","b":"דיין או ספרא באוסטרהא. חתם על תוספת כתובה לר אשר ענזיל בעל \"ברול מבנים אשר\"."},{"i":28943,"n":"מאיר הלוי מאיכיהויזן","b":"תלמיד ר נתן אדלר בפפד\"ם. דיין באיכיהויזן. רשם בפנקס מתורת רבו ומתורת ר פנחס הורביץ בעל ההפלאה."},{"i":28944,"n":"מאיר הלוי מדוקלא","f":"יעקב יצחק מדוקלא","b":"רב-שנת תק\"מ"},{"i":28945,"n":"מאיר הלוי מוילנא","k":"ר' מאיר הלוי מבולדא","b":"רב בווילנה-ק\"מ"},{"i":28946,"n":"מאיר הלוי מזמושט","f":"משה הלוי","dt":"תנא","b":"רב בזאמוטשט. חתן ר שלמה רופא. אביו של ר יחזקאל הלוי."},{"i":28947,"n":"מאיר הלוי מלבוב","f":"אברהם","dt":"תג - ב כסלו","b":"דיין ור\"מ בלבוב. חתם על פסק דין-שצט עם ר יוסף בן מאיר שלי\"ט."},{"i":28948,"n":"מאיר הלוי מלבוב","f":"מנחם חזן","dt":"תכד - ח אייר","dp":"לבוב","b":"מחכמי לבוב. נהרג עק\"ה."},{"i":28949,"n":"מאיר הלוי ממוסט","f":"יוסף","k":"חותן החוזה מלובלין","dt":"תקנא - ד תשרי","b":"רב במוסט. חתנו היה החוזה מלובלין. - יתכן והיה רב בנדבורנה."},{"i":28950,"n":"מאיר הלוי מנירנברג וסופיה","b":"מחכמי אשכנז, לאחר הגירוש-רל הגיע לסופיה-בולגריה."},{"i":28951,"n":"מאיר הלוי מספרד","f":"יוסף ן מיגש הראשון","b":"מגדולי חכמי ספרד-ד'תת\"מ. אביו של הר\"י מיגש."},{"i":28952,"n":"מאיר הלוי מערפורט","f":"ברוך הלוי","b":"מגדולי חכמי אשכנז, רב בערפורט(=ארפורט), פפד\"מ, נירנברג-קמג, פפד\"מ - פעם שניה, וינה-קנז. נאסר בעלילה בפפד\"מ ושוחרר בהתערבות המלך ונצל-קנב. בנו ר דוד מפפד\"מ. ש הטוענים שר מאיר היה הרב הבכיר באשכנז בדורו והוא שחידש את סמיכת החכמים והנהיג את התואר מורנו."},{"i":28953,"n":"מאיר הלוי משלוניקי","f":"שמעון","dt":"רעט","dp":"שלוניקי","b":"נכד המהרי\"ל, התישב בשלוניקי והיה רב הקהלה האשכנזית \"וארנבוק\" בשלוניקי-רץ."},{"i":28954,"n":"מאיר הלל מווערטעש","b":"רב בווערטעש-תר\"ס"},{"i":28955,"n":"מאיר העכעל","f":"שלמה","k":"מפפד\"מ","b":"חתן ר שמעון מפוזנא, וגירשה ונשאה, ואז טען ר מאיר כי הגט היה פסול, והרמ\"א עם ר אייזיק הלוי מגינצבורג הכשירו את הגט."},{"i":28956,"n":"מאיר זאב מפלשאבאניא","b":"רב בפעלשאבאניא-תרע\"ד"},{"i":28957,"n":"מאיר חיים מברדיטשוב","b":"בן אחותו של ר לוי יצחק מברדיטשוב, ודודו של ר פיבל מגריצא. מראשוני מפיצי החסידות בפולין המרכזית."},{"i":28958,"n":"מאיר חנוך הניך דב בן שמואל","f":"שמואל מבלז","k":"אדמור מאלעסק","r":"האדמו\"ר מאלעסק, חתנו של השר שלום מבעלזא","bt":"תקס","dt":"תרמד - א אלול","b":"נכד ר מאיר מבלז-תלמיד הבעשט. חתן השר שלום מבלז, ובזיוו\"ש חתן ר מאיר בן ר לוי יצחק מברדיטשוב. תלמיד החוזה מלובלין. רב בסטנוב, רב ואדמור באלסק-תרי ובנו ר יצחק על מקומו אחריו. חיבר \"לב שמח\" למברג תרכב. מתולדותיו ב\"לב שמח החדש\". חתניו: ר חיים אליהו ליברמן מזולקוא, ר צבי רוקח-נכד השר שלום, ר משה זילברפרב.","bk":[["לב שמח (דרך התפילה, אור חדש) - תפילה ח\"ת וסיפורים",""],["לב שמח",""],["לב שמח החדש",""]]},{"i":28959,"n":"מאיר חסיד","dt":"תיב - יג תמוז","b":"דיין בווילנה"},{"i":28960,"n":"מאיר חריף","b":"תלמיד הבעשט. האחראי על גביית הכספים לישוב החסידי בארץ ישראל."},{"i":28961,"n":"מאיר יהושע מקלימנטוב","b":"חתן ר יהודה אריה ליב אפשטין הלוי האדמור מאוזרוב ואופולא. רב בקלימנטוב, רייויץ, וטארלא."},{"i":28962,"n":"מאיר יואל משלוניקי","b":"רופא בשלוניקי-תרס."},{"i":28963,"n":"מאיר יוחנן מליפאנטו","b":"רב בליפאנטו(=ליפנטו)-יוון עם ר משה רוסו, היה מחלוקת כנגדו מצד ר יוסף פורמון רב במחוז המוריאה-יוון, והמהרשד\"ם הגן עליו ועל חברו ר משה רוסו."},{"i":28964,"n":"מאיר יונה מג'רבה","k":"בעל בית מאיר","dt":"תשמד - כב אד\"ב","b":"רב בג'רבא. עלה לארץ וכיהן כרב במגדל העמק. חיבר גם \"מי ומי\" על ההגדה.","bk":[["בית מאיר",""]]},{"i":28965,"n":"מאיר יוסף גבריאל אליהו מבגדד","b":"סופר ביה\"ד בזמן ה\"בן איש חי\", חתם עם רבני בבל בכמה מקומות."},{"i":28966,"n":"מאיר יחיאל מאחאטע","b":"אב\"ד אחאטא. הסכים על תהלות חיים לר חיים פלטרוביץ."},{"i":28967,"n":"מאיר יחיאל מחודרוב","f":"אבי עזרא זליג מקלשין","b":"רב בחודרוב."},{"i":28968,"n":"מאיר יחיאל ממגרוב","b":"רב במגרוב-תרכט."},{"i":28969,"n":"מאיר יחיאל מנבריה","b":"רב בנבריה-תריז."},{"i":28970,"n":"מאיר יחיאל מצפת","dt":"תקפד","dp":"בומביי","b":"מחכמי צפת-תקפד, בשליחות בארצות ערב והודו."},{"i":28971,"n":"מאיר יחיאל מרדחוב","b":"רב בראדחוב-תר\"מ. חתן ר יצחק רובין."},{"i":28972,"n":"מאיר ליב מוינה וירושלים","dt":"תרט - כז אלול","dp":"ירושלים","b":"מחכמי ירושלים."},{"i":28973,"n":"מאיר ליב מקראקא","b":"רב בקראקא - תשובה אליו ב\"טוט\"ד\"."},{"i":28974,"n":"מאיר ליבוש","f":"יחיאל מיכל","k":"מלבי\"ם","r":"המלבי\"ם","bt":"תקס-ט","bp":"ואלטשישוק(=וולוציסק)","dt":"תרמ - א תשרי","dp":"קיוב","b":"נתייתם בילדותו וגדל אצל אביו חורגו ר יהודה ליב-רבה של וולוציסק-פלך ווהלין. תלמיד ר משה בן יהודה הורביץ בעל \"עמק השידים\", ולמד קבלה אצל ר הירש מזידיטשוב, היה חתן הגביר ר פיבל אופיצינסקי מלונטשיץ - שהיתה אלמנת ר יקיר ליפשיץ מוארשא בעל \"עטרת צבי\". התחתן והתגרש עבר לוארשא וכונה \"העילוי מוואלין\", בזיוו\"ש חתן ר חיים אוירבך בעל \"דברי משפט\". רב בוערשנא-תקצח-ט, קעמפנא-תרה, בוקרשט-תרך - סבל מהלשנה וישב במאסר עד ששוחרר בהתערבות מונטיפיורי, פאריס, לונטשיץ - והיה במחלוקת עם החסידים עד שנאלץ לעזוב, מוהילוב - וסבל מהלשנה וגורש בידי השלטון הרוסי, קניגסברג, קוברין, סירב לרבנות קרמנצוג וניו יורק, הסכים להצעת רבנות וילנא - אך לא הסתייע בגלל מלשינות. (וב\"מוריה\" - הסכים לקרמנצוג ונפטר בדרכו לשם), נפטר בדרכו לחתונת נכדתו. פרסם מאמרים ב\"כבוד הלבנון\" - ירושלים-פאריס תרכג-תרמב, \"פליטת סופרים\" - וילנא תרכג. מאמר ב\"כבוד הלבנון\" - פאריס תרכה מאת ר שניאור זק\"ש - ובו מתאר את נסיבות עזיבתו את פאריס ומעברו ללונטשיץ-פולין. גיסו - הגביר ר שמואל אפוטשינסקי - סייע לו בהדפסת ספריו. נספד ב\"אבל יחיד\" לר אפרים ויטעס מוילקומיר. חתן הגביר ר פיבל אופיצינסקי מלונטשיץ - שהיתה אלמנת ר יקיר ליפשיץ מוארשא בעל \"עטרת צבי\". התחתן והתגרש עבר לוארשא וכונה \"העילוי מוואלין\", בזיוו\"ש חתן ר חיים אוירבך בעל \"דברי משפט\". רב בוערשנא-תקצח-ט, קעמפנא-תרה, בוקרשט-תרך - סבל מהלשנה וישב במאסר עד ששוחרר בהתערבות מונטיפיורי, פאריס, לונטשיץ - והיה במחלוקת עם החסידים עד שנאלץ לעזוב, מוהילוב - וסבל מהלשנה וגורש בידי השלטון הרוסי, קניגסברג, קוברין, סירב לרבנות קרמנצוג וניו יורק, הסכים להצעת רבנות וילנא - אך לא הסתייע בגלל מלשינות. (וב\"מוריה\" - הסכים לקרמנצוג ונפטר בדרכו לשם), נפטר בדרכו לחתונת נכדתו. פרסם מאמרים ב\"כבוד הלבנון\" - ירושלים-פאריס תרכג-תרמב, \"פליטת סופרים\" - וילנא תרכג. מאמר ב\"כבוד הלבנון\" - פאריס תרכה מאת ר שניאור זק\"ש - ובו מתאר את נסיבות עזיבתו את פאריס ומעברו ללונטשיץ-פולין. גיסו - ר הגביר שמואל אפוטשינסקי - סייע לו בהדפסת ספריו. נספד ב\"אבל יחיד\" לר אפרים ויטעס מוילקומיר.","bk":[["ארץ חמדה – דרשות",""],["ארצות החיים – או\"ח",""],["ארצות השלום – דרשות",""],["מלבי\"ם – תנ\"ך",""],["משל ומליצה - תשובה בדרך שיר על ספר שפירסם איזה משכיל",""],["עלה לתרופה - פירוש על פרק אחד מהלכות דעות להרמב\"ם",""],["ארצות החיים",""],["חומש ונ\"ך עם פירוש המלבי\"ם",""]],"e":"תקס\"ט-תר\"מ","rb":"בוקרשט, קליניגרד","co":{"a":"54.733333,20.483333","b":"50.73889;25.32333."}},{"i":28975,"n":"מאיר מאוסטרהא","f":"פנחס","dt":"תק.. - ט אייר","dp":"אוסטרהא","b":"פרנס באוסטרהא-תפח עם ר מרדכי הלפרין."},{"i":28976,"n":"מאיר מאינגליטירה-אנגליה","b":"מגדולי בעלי התוספות באנגליה-ד'תתק\"צ"},{"i":28977,"n":"מאיר מאלטשנטאט","b":"אב\"ד אלטשנטאט, מכתב המלצה ממנו-תר לר אריה ליב נכדו של השאגת אריה."},{"i":28978,"n":"מאיר מאניפולי","b":"תלמיד הבעשט."},{"i":28979,"n":"מאיר מבגדד והודו","f":"יעקב הרופא מבגדד","b":"אביו מגדולי חכמי בבל. רב ורופא מבגדד, עבר לבומבי-הודו, ועסק רבות בהלכות שחיטה."},{"i":28980,"n":"מאיר מביחוב","f":"יעקב","dp":"טבריה","b":"מחכמי טבריה, בשנת תקנא בשליחות, ולאחר מכן עוד שליחויות ברוסיה. היה מראשי עדת החסידים, בשנת תקמו חתם על אגרת לר מנחם מ נדל מויטבסק."},{"i":28981,"n":"מאיר מבייאה","f":"משה מבאייה","b":"תלמיד החת\"ס-תקפ."},{"i":28982,"n":"מאיר מבלז","k":"רבי מאיר הקדוש","b":"תלמיד הבעשט. אב\"ד בלז. מתורתו בספר בנו ר פסח מנמירוב - \"חדושי מהר\"פ\"."},{"i":28983,"n":"מאיר מבנדין","b":"רב בבנדין-תק\"ל"},{"i":28984,"n":"מאיר מברוד","k":"ר' מאיר מסקאלי","dt":"תצח - ח אייר","b":"מגיד בבראדי"},{"i":28985,"n":"מאיר מברזאן","b":"רב בברזאן-תרג - תשובה אליו ב\"שואל ומשיב\"."},{"i":28986,"n":"מאיר מבריינסק","dt":"תריג - לפני","b":"אב\"ד בריינסק. נספד מאת ר חנוך זונדל מביאליסטוק ב\"אבל כבד\" - תריג."},{"i":28987,"n":"מאיר מבריסק","f":"יצחק חריף","b":"רב בבריסק,לודמיר-תמ\"ה"},{"i":28988,"n":"מאיר מגיד מישרים מוזעלווא","f":"שלמה זלמן מליטא","b":"הסכים על \"שבחי הבעשט\"."},{"i":28989,"n":"מאיר מגלינא","b":"רב בגלינא,התיישב בברוד-תק\"פ"},{"i":28990,"n":"מאיר מדמשק","b":"ראש ישיבה בדמשק בזמן הרמבם."},{"i":28991,"n":"מאיר מהוסקוב","f":"משה מזאמוטשט","b":"רב בהוסאקוב-תקל\"ה. אביו של הקדושת לוי."},{"i":28992,"n":"מאיר מהליטש","b":"רב בהליטש - תשובה אליו ב\"שואל ומשיב\"."},{"i":28993,"n":"מאיר מהמבורג","f":"יום טוב ליפמן הקדוש","b":"דיין באה\"ו-תקל אצל ר דוד ברלין, חתם עמו ועם ר אביגדור בן משה."},{"i":28994,"n":"מאיר מווערצקי","b":"רב בווערעצקי-תר\"ס"},{"i":28995,"n":"מאיר מוילנא","f":"קלונימוס קלמן","dt":"תקמט - כב אייר","dp":"וילנא","b":"דיין בוילנא."},{"i":28996,"n":"מאיר מוילנא","f":"רפאל","dt":"תקעה","dp":"וילנא","b":"נכד בעל סדר הדורות. גביר מחכמי וילנא."},{"i":28997,"n":"מאיר מוילנא","dt":"תיט - כב אב","b":"דיין בוילנא, גלה מוילנא לאשכנז ונהרג בדרכו מוילספורג לנערמושס. נזכר ב\"חוט השני\"."},{"i":28998,"n":"מאיר מוילנא","f":"הלל","dt":"תקע - א אלול","dp":"וילנא","b":"מחכמי וילנא."},{"i":28999,"n":"מאיר מוישניצא","f":"אליעזר ליפא","b":"דיין בוישניצא-תרן עם ר חיים ברוך וולף, ור צבי יונה. תשובה אליו במהרשם-תרנה. חתם-תרנו עם ר אלתר יחיאל נבנצל."},{"i":29000,"n":"מאיר מזולקוא","f":"יוסף יוזפא","b":"מחכמי זולקוא, חתם-תסד בפנקס הקהלה על תקנה שלא יהיו קרובי הרב בתוך מנהיגי הקהל."},{"i":29001,"n":"מאיר מזולקוא","f":"לוי","k":"בעל אדני פז","b":"מחכמי זולקוא. חיבר \"אדני פז\" ונדפס בשם \"לקוטי שושנים\" ו\"מקשה זהב\", \"גלילי זהב\" - זולקוא תקיג."},{"i":29002,"n":"מאיר מחיידאב","b":"אב\"ד חיידאב. פרסם מאמרים ב\"העץ\" - לובלין תרצג."},{"i":29003,"n":"מאיר מטנהוזן","b":"מגדולי חכמי אשכנז-ש\"י. בניו - ר אליקים גץ, ר ליב חנלש, ר עקיבא מהוצפלץ."},{"i":29004,"n":"מאיר מטנהויזן","b":"רב בטנהויזן"},{"i":29005,"n":"מאיר מיאנישוק - אחי הגר\"א","f":"שלמה זלמן מוילנא","b":"רב ביאנישוק."},{"i":29006,"n":"מאיר מיכל מבריסק","f":"מרדכי","b":"מחכמי בריסק-תקסה."},{"i":29007,"n":"מאיר מירושלים","f":"חיים","b":"נזכר בשו\"ת רלב\"ח, לדעת רוזניס היה מחכמי ירושלים, לדעת רבלין יתכן שהיה בשלוניקי."},{"i":29008,"n":"מאיר מלבוב","f":"נפתלי הירץ (הירצקי)","dt":"שפט - ב טבת","dp":"לבוב","b":"מרביץ תורה בלבוב"},{"i":29009,"n":"מאיר מלדומיר ואוסטרהא","f":"יוסף","dt":"שצח - ב תשרי","dp":"לבוב","b":"אב\"ד בלובלין, לודמיר, אוסטרהא בזמן שהשל\"ה כיהן כר\"מ שם, לבוב. חתם-תח עם הדיינים ר יעקב בן אברהם קצנלנבוגן, ר יהודה ליווא אפשטין. הסכים-תה על \"ילקוט שמעוני\" עם ר השל. נספד ב\"איתן האזרחי\" ומאת בעל \"תפארת ישראל\". (בובר מעיר שתאריכי החתימות לא מסתדרים עם תאריך פטירתו כפי שמופיע במצבות קודש)."},{"i":29010,"n":"מאיר מלובלין","f":"מאיר","dt":"תקטו - יז אלול","dp":"לובלין","b":"מחכמי לובלין."},{"i":29011,"n":"מאיר מלובלין","f":"נפתלי הירש","dt":"תקכט - יא תשרי","dp":"לובלין","b":"מראשי קהילת לובלין."},{"i":29012,"n":"מאיר מלובלין","f":"אברהם","dt":"תקמג - כו תמוז","dp":"לובלין","b":"אחיינו של ר יעקב חיים אב\"ד לובלין. אחיו של ר צבי הירש מלוקאבי. מחכמי לובלין."},{"i":29013,"n":"מאיר מלובלין","f":"א. פישל","b":"סו\"ד בלובלין. חתם על פסק דין-תקנו בפנקס ביהכ\"נ ר צבי הירש בן משה דאקטאר."},{"i":29014,"n":"מאיר מלובלין","f":"מרדכי","dt":"תקפג - כא חשון","dp":"לובלין","b":"דיין בלובלין. חתם-תקמב על פס\"ד יחד עם האב\"ד ר שאול מרגליות."},{"i":29015,"n":"מאיר מלובלין","f":"ישראל איסר מלובלין","dt":"תקס","dp":"לובלין","b":"גביר מחכמי לובלין."},{"i":29016,"n":"מאיר מלובלין ואפטין (הלברשטט)","f":"אריה ליב מדובנקא","b":"ספרא ודיינא בלובלין, אב\"ד אפטין. נזכר ב\"עטרת צבי\"."},{"i":29017,"n":"מאיר מלובלין וקראקא","f":"גדליה","k":"מהר\"מ מלובלין-מאיר ע","r":"ראש ישיבה בלובלין","bt":"שיח","bp":"לובלין?","dt":"שעז - טז אייר","dp":"לובלין","b":"גדול חכמי דורו, תלמיד וחתן ר יצחק שפירא מקראקא-חתן המהר\"ל מפרג. ובזיוו\"ש חתן ר פנחס בן נפתלי הכהן מפולדא וקרעמזיר. עשיר, מרביץ תורה, ראש ישיבה בלובלין-שמב, רב בקרקא-שמז על מקום חותנו, לבוב-שנט, לובלין-שעג. חיבר \"מאיר עיני חכמים\", ועוד. בניו: ר גדליהו, ר יצחק, ר אהרן מטולטשין, חתנו - ר יוסף אב\"ד דחוץ לעיר לבוב. מתלמידיו: ר יהושע מקראקא בעל \"מגינת שלמה, ר ישעיה הורביץ בעל השל\"ה, ר אברהם בעל \"משאת בנימין\", ר זנוויל-שהיה גם מחותנו, ר נתן שפירא מלובלין, ר דוד טעביל שפירא דיין בקראקא, ר יעקב מפינטשוב. (נאלץ לעזוב את לבוב - לאחר שר אברהם שרענציל שהיה תלמיד בעל הב\"ח - הגן על כבוד רבו שנפגע מהמהר\"ם - וגרם לועד ארבע ארצות לגרשו מלבוב). מחותן עם - המהר\"ל מפרג, ר ישכר מורמיזא, ר אבא מקראקא. גיסו - ר גבריאל. בניו - ר גדליה מלובלין, ר יצחק שהו\"ל את ספרי אביו והוסיף הקדמה. חתניו - ר יוסף מלבוב (8066) (רב חוץ לעיר), ר מרדכי מבערזאן (13854) בעל \"צאן קדשים\", ר אליעזר ליפמן סגל. (יש אומרים שהיה חתן ר יצחק אחר ולא חתן המהר\"ל).","bk":[["מאיר עיני חכמים \\ מהר\"ם מלובלין - על הש\"ס",""],["מנהיר עיני חכמים - שו\"ת",""],["מהר\"ם לובלין (שו\"ת)",""],["מהר\"ם (לובלין)",""],["מהר\"ם מלובלין",""]],"e":"שי\"ח-שע\"ו"},{"i":29018,"n":"מאיר מלודז","b":"מו\"צ בלודז-תר\"צ"},{"i":29019,"n":"מאיר מלמברג","b":"רב בגליל לבוב-תקי\"ז"},{"i":29020,"n":"מאיר מלקנבך","b":"רב בלקנבך-תק."},{"i":29021,"n":"מאיר ממארצאלי","b":"רב במארצאלי-תק\"נ"},{"i":29022,"n":"מאיר ממיטאוי","f":"אליעזר זערף","bp":"בריינסק-פלך הורדנא","dt":"תרסה - אלול","dp":"מיטאוי","b":"גביר, ועסקן צבור במיטאוי, יסד חברה הכנסת אורחים-תרכו."},{"i":29023,"n":"מאיר ממינסק","f":"יוסף","dt":"תקלה - ד כסלו","dp":"מינסק","b":"רב במינסק."},{"i":29024,"n":"מאיר ממראקש","f":"יאיר","dt":"תרץ","b":"רב במראקש."},{"i":29025,"n":"מאיר ממרוקו","f":"אלישע","k":"בעל לב אבות","bt":"תרסה","bp":"קצאר-שיק - מרוקו","dt":"תשמו","dp":"ירושלים","b":"רב ומלמד במרוקו. עלה לירושלים."},{"i":29026,"n":"מאיר מנאדאוודוואר","b":"רב בנאדאודוואר-קעה."},{"i":29027,"n":"מאיר מנורטהויזן","f":"שמואל הקדוש","k":"מפפד\"מ","b":"רב בפפד\"מ-קמ, על מקום ר אשר, ור זוסלין משפירא על מקומו אחריו. חתם באסיפת רבנים במגנצא-קמא בשם מאיר מנורט הויזן. בניו: ר שמואל, ר שמעון."},{"i":29028,"n":"מאיר מסופיה","f":"יעקב","b":"רב בסופיה-קלב. אחיו - ר ראובן מסופיה וצפת."},{"i":29029,"n":"מאיר מסטבניץ","b":"אדמו\"ר בסטבניץ-תר\"נ"},{"i":29030,"n":"מאיר מסט'גראד","b":"רב בסט'גראד-תקס\"ח"},{"i":29031,"n":"מאיר מסעטשין.","b":"רב בסעטשין-תקפד."},{"i":29032,"n":"מאיר מסעמניץ","b":"רב בסעמניץ. נזכר אצל החת\"ס."},{"i":29033,"n":"מאיר מספרד","f":"ששת בר שלמה הנשיא","b":"מחכמי ספרד מתרגם ומשורר. בן דורו של ר יהודה אלחריזי."},{"i":29034,"n":"מאיר מעדנבורג","b":"רב בעדנבורג-ק\"צ. נזכר במנהגי מהרי\"ל."},{"i":29035,"n":"מאיר מעלקיש","dt":"תיח - ו סיון","b":"עק\"ה,רב בעלקיש"},{"i":29036,"n":"מאיר מפדובה","k":"בעל רמזי התגים","b":"רב וסופר סתם בפדובה ומנטובה. חיבר \"רמזי התגים\". רבו של בעל \"שער אריה\" - שהזכירו בספרו. מוזכר ב\"שלטי הגבורים\" - והעיד עליו שכתב מג ספרי תורה כשרים ללא ערעור.."},{"i":29037,"n":"מאיר מפוזנא","f":"אליקים גץ מפוזנא","dt":"תיד - כט אלול","b":"מגדולי חכמי דורו, ראש ישיבת המהרש\"א בפוזנא, רב בפילא."},{"i":29038,"n":"מאיר מפרגה (ורשא)","dt":"תרכג - כה אדר","b":"דיין בפרגה ליד וורשה"},{"i":29039,"n":"מאיר מפרוסטיץ","b":"רב בפרוסטיץ. תשובה שלו ב\"חכם צבי\"."},{"i":29040,"n":"מאיר מפרמישלן - א","f":"יעקב תם מפרמישלן","k":"אדמור מפרמישלן","bt":"תסג-עא","dt":"תקלג-מא - כב אב","b":"תלמיד הבעשט, ועזר לו להכניע את שרידי כת ש\"צ. חיבר \"תורתו של רבי מאיר\" וציוה לא להדפיסו. בנו ר אהרן אריה."},{"i":29041,"n":"מאיר מפרמישלן - ג","f":"מרדכי אריה","k":"אדמור מפרמישלן","b":"ממשפחת אדמורי פרמישלן. ממונה על הציון של סבו האדמור ר מאיר מפרמישלן."},{"i":29042,"n":"מאיר מפרשבורג","f":"שמעון מיכל מפרשבורג","b":"בנו של ראש היהודים מפרשבורג. ראש קהלת פרשבורג ושופט היהודים (מטעם השלטון) על מקום אביו. רכש עבור הקהלה את בית הקברות הראשון בשלוסגרונד-פרבר פרשבורג, ממיסדי החברא קדישא בפרשבורג יחד עם אחיו ר מיכל לעזר."},{"i":29043,"n":"מאיר מצרפת","f":"משה","b":"מגדולי הראשונים,מחכמי צרפת-ד'תתק\"פ"},{"i":29044,"n":"מאיר מקוואהל","b":"מגדולי החבורה בפשיסחא, בין הראשונים שהכתירו את ר מנחם מנדל מקוצק כאדמור."},{"i":29045,"n":"מאיר מקוריסטשוב","f":"נתן מנמירוב","k":"בעל מאיר עיני חכמים","dt":"תקפב - לפני","b":"תלמיד ר זאב וולף מזיטומיר. רב בחודרקוב, קוריסטשוב(=קרסטשוב)-תקעז. חתנו ר אברהם אביש איזיק רפפורט מראדומישל."},{"i":29046,"n":"מאיר מקידאן","f":"בנימין","b":"דיין בקידאן. חתם-תקעד בערך בענין עגונה."},{"i":29047,"n":"מאיר מקמינקא","f":"דוד מרבינו","k":"אדמור מקמינקא","dt":"תקמג","b":"תלמיד הבעשט - אחד מ\"האחים הקדושים מקמינקא\"."},{"i":29048,"n":"מאיר מקראקא","k":"בעל תקון הבית","b":"שו\"ב מומחה בקראקא-ש\"מ"},{"i":29049,"n":"מאיר מקראקא","b":"רב בקראקא-תרלג - תשובה אליו ב\"מהרש\"ם\"."},{"i":29050,"n":"מאיר מקרוטושין","b":"רב בקאראטשין"},{"i":29051,"n":"מאיר מקרמניץ","b":"רב בקרמניץ-ת\"צ"},{"i":29052,"n":"מאיר מקרקסונה","k":"בעל העזר","b":"מגדולי חכמי צרפת הדרומית-ד'תת\"ק"},{"i":29053,"n":"מאיר מראסיין","bp":"ראסיין","b":"תלמיד הגר\"א. נכדו - ר אליהו סטומלער מנובוגרד-ליד וילנא."},{"i":29054,"n":"מאיר מרובשוב","b":"רב ברובאשוב"},{"i":29055,"n":"מאיר מרוטנבורג","f":"רבינו ברוך","k":"מהר\"ם מרוטנבורג","bt":"ד'תתקפ","dt":"נג - יט אייר","b":"תשובותיו של המהר\"ם מרוטנבורג נדפסו בכמה מהדורות, בכל מהדורה חלק אחר מתשובותיו. מקובל להגדירן בשם הדפוס, לדוגמה: מהר\"ם מרוטנבורג ד\"פ [=דפוס פראג], או: ד\"ל [=דפוס לבוב], וכן לגבי שאר הדפוסים. מחבוריו הנוספים: תוספות למס' יומא – התוספות המודפסים בש\"ס וילנא (ראה יד מלאכי ח\"ב כללי התוספות אות יז); פירוש למשניות [מסדר טהרות. על מס' אהלות ונגעים נדפס במשניות וילנא, בשאר המסכתות התוי\"ט הביא לקוטים מדבריו. פירוש המהר\"ם למס' כלים, בני ברק תשנג]; ברכות מהר\"ם [הל' ברכות, מהדו' מכון ירושלים, ירושלים תשמ\"ח]; הלכות שמחות; פסקי עירובין. מרבותיו של המהר\"ם מרוטנבורג: ר' יחיאל מפריז; ה\"אור זרוע\"; ר' אביגדור כהן צדק. מתלמידיו המובהקים: ה\"תשב\"ץ [קטן]\"; הרא\"ש; המרדכי; ר' מאיר הכהן מרוטנבורג, בעל \"הגהות מימוניות\" [יש מי שהחליף בטעות בינו לבין המהר\"ם מרוטנבורג].","bk":[["תוספות מהר\"ם מרוטנבורג","מפרשי ש\"ס - ראשונים"],["הלכות שמחות השלם",""],["מהר\"ם מרוטנבורג (שו\"ת)",""],["מהר\"ם מרוטנבורג",""],["מהר\"ם רוטנבורג",""],["מהר\"ם מרוטנבורג – שו\"ת, הלכות שמחות",""],["ברכות מהר\"ם","הלכה ומנהג - ראשונים"],["מנהגים דבי מהר\"ם","הלכה ומנהג - ראשונים"],["הלכות שמחות","הלכה ומנהג - ראשונים"],["מהר\"ם מרוטנבורג","שו\"ת - ראשונים"],["מהר\"ם מרוטנבורג וחבריו","שו\"ת - ראשונים"]],"e":"ד'תתק\"פ~-ה'נ\"ג"},{"i":29056,"n":"מאיר מרומבורג - חתן רש\"י","k":"רבינו מאיר,חתן רש\"י","bt":"ד'תתכ","b":"מגדולי התורה ברומבורג. אביהם של רבינו תם, הרשב\"ם והריב\"ם."},{"i":29057,"n":"מאיר מרוסג'וק","f":"אהרן","b":"היהודי הראשון בעיר רוסג'וק-תקנז."},{"i":29058,"n":"מאיר מרינטל מברלין","f":"יעקב","b":"מראשי הקהילה בברלין-תע, והיה מתומכי ר מרדכי ראנבאך בזמן המחלוקת אודות ביהכ\"נ בברלין. חתם על מינוי ר משה בן אהרן מלבוב ולייפניק לרבה של ברלין-תפט."},{"i":29059,"n":"מאיר מרנדסבורג","f":"אורי פיבש יעקב","b":"חתן ר מיכל היימן בעל \"אוצרות חיים\". דרשן ברנדסבורג-ליד אלטונא, ומוהל במדינת שלזויג."},{"i":29060,"n":"מאיר משדליץ","b":"תלמיד החוזה מלובלין, היהודי הקדוש מפשיסחא, ור שמחה בונם מפשיסחא. עסק במסחר ונחשב לאחד מגדולי החסידים בפשיסחא."},{"i":29061,"n":"מאיר משה מוילקוטש","b":"רב בוילקוטש."},{"i":29062,"n":"מאיר משה מסמרגון","k":"ליבלי סמארגאנער","b":"ר\"מ ומו\"צ בסמרגון-שנות ה-תר בזמן ר אריה ליב שפירא מקובנא וסמרגון."},{"i":29063,"n":"מאיר משוורזנץ","k":"ר' מאיר מפוזנא","b":"רב בשוורזנץ-ת\"כ"},{"i":29064,"n":"מאיר משילווצרי","b":"רב בשידלווצי"},{"i":29065,"n":"מאיר משלוניקי","f":"יעקב נחום","dt":"תקי","dp":"שלוניקי","b":"דיין בשלוניקי-תצח."},{"i":29066,"n":"מאיר ן, שלמה משלוניקי","b":"מגדולי חכמי שאלוניקי-ש\"פ"},{"i":29067,"n":"מאיר סגל מברלין","b":"ממנהיגי קהילת ברלין. חתם על מינוי ר משה בן אהרן מלבוב ולייפניק לרבה של ברלין-תפט."},{"i":29068,"n":"מאיר פיבל מזסלב","f":"יעקב","b":"רב בזסלב(=זאסלב) ומדינת וואהלין-תק\"ע"},{"i":29069,"n":"מאיר צבי מאזור","b":"רב באזור. פרסם מאמרים ב\"בית אברהם\" - וארשא תרצד."},{"i":29070,"n":"מאיר צבי מזאמושט","f":"יעקב יצחק בן מאיר","k":"בעל יד אבי שלום","bt":"תקצג","b":"תלמיד ר מנחם מנדל מקוצק. שו\"ב בזאמושט."},{"i":29071,"n":"מאיר צדוק הכהן מאלטונה","f":"בנימין בן מאיר","bt":"תקכה","bp":"אלטונא","dt":"תר - טו אדר","dp":"אלטונא","b":"תלמיד ר רפאל הכהן. פרנס מחכמי אלטונא, ונציג קהלת אלטונא-תקעב לאחר היפרדות קהלות אה\"ו, ראב\"ד על מקום ר עקיבא ורטהיימר ור יעקב עטלינגר על מקומו אחריו. סייע ליהודי המבורג לאחר גירושם בזמן נפוליאון-תקעד."},{"i":29072,"n":"מאיר קארעליצער מוילנא","b":"מחכמי \"ישיבת הארבעים\" בוילנא-תקפז."},{"i":29073,"n":"מאיר ר זלמנ'ס מלובלין","b":"גביר מחסידי החוזה מלובלין, ומעשירי פולין. חתן הגביר ר אפרים זלמן מרגליות מלובלין - וע\"ש נקרא \"זלמנ'ס\". בהשפעתו הביא את החוזה מלובלין ללובלין. נזכר ב\"קשות מיושב\". מחותן עם ר עזריאל \"ראש הברזל\" מלובלין."},{"i":29074,"n":"מאיר רופא מחברון","f":"חייא","bt":"שע","bp":"צפת","dt":"תמט","b":"מחכמי חברון, בשנת תיב בשליחות והדפיס בונציה את ספר אביו \"מעשה חייא\"."},{"i":29075,"n":"מאיר רפאל'ס מוילנא","f":"רפאל יפה","b":"תלמיד בעל התניא, עמד בראש הקהלה בוילנא - לאחר ניצחון החסידים - לתקופה קצרה. היה מחלוקת כנגדו בגלל חסידותו. חתם שמו \"מאיר בן רפאל יפה\"."},{"i":29076,"n":"מאיר שלום הכהן מבריינסק","f":"שאול בנימין","k":"בעל מלחמת שלום","bt":"תרמה - ב שבט","b":"רב בבריינסק. בנו - ר ברוך קאהן הו\"ל את ספרו. (ראה גם קרליץ, מאיר שלום)."},{"i":29077,"n":"מאיר שמחה הכהן מדוינסק","f":"שמשון קלמן הכהן","k":"בעל אור שמח","r":"רבה של דווינסק","bt":"תרג","bp":"בוטרימאנץ(=באלטרימאנץ)","dt":"תרפו - ד אלול","dp":"ריגה - דוינסק","b":"מגדולי חכמי דורו. תלמיד ר משה דנישבסקי, חתן הגביר ר הירש פלטיאל מביאליסטוק, ועבר לשם. רב בדוינסק(=דינבורג)-תרמח על מקום ר ראובן הלוי כ-40 שנה, ונשאר גם בזמן מלחה\"ע ה-I. דחה הצעה לרבנות ירושלים לבקשת בני עדתו. חיבר גם \"משך חכמה\". תשובה ממנו ב\"המאסף\" - ירושלים-אלכסנדריה תרנו-תרעג, \"קובץ דרושים\" - פיעטרקוב תרפג. חתנו - ר אברהם לופטביר.","bk":[["משך חכמה","מפרשי תורה"],["אור שמח – רמב\"ם",""],["חדושי רבנו מאיר שמחה",""],["שו\"ת אור שמח",""],["אור שמר משך חכמה",""],["שו\"ת אור שמח , אור שמח – רמב\"ם, חדושי רבנו מאיר שמחה, משך חכמה",""],["אור שמח",""],["חי' ר' מאיר שמחה",""],["אור שמח","מפרשי רמב\"ם"],["אור שמח","שו\"ת - אחרונים"]],"e":"תר\"ג-תרפ\"ו","rb":"דווינסק","co":{"b":"54.5,24.25"}},{"i":29078,"n":"מאיר ש\"ץ","k":"בעל אקדמות","dt":"ד'תתנו","b":"עק\"ה,מגדולי חכמי וורמייזא"},{"i":29079,"n":"מאיר, זיגמונד מפרשבורג","k":"בעל איין יידישער קאו","b":"חיבר ספר זכרונות - \"איין יידישער קאופמאן\", ובו חומר רב לתולדות קהלת פרשבורג."},{"i":29080,"n":"מאיר, ישכר מנתיבות","b":"ראש ישיבת הנגב."},{"i":29081,"n":"מאיר, מאיר","k":"בעל מאיר נתיב","b":"חיבר \"מאיר נתיב\" קרימונה שד."},{"i":29082,"n":"מאיר, משה זכריה מסנוק","f":"אברהם צבי","dt":"תשה - יח אב","dp":"סיביר","b":"חסיד צורטקוב בסנוק. חתנו - ר יצחק גליקמן מברזוב. נספה בסיביר."},{"i":29083,"n":"מאירוביץ, אברהם","bt":"1891","bp":"יאנובה","dt":"1948","dp":"ניו יורק","b":"רופא פסיכיאטר בבוסטון. חיבר באנגלית ספר על יהודי גרמניה THE GERMAN JEW."},{"i":29084,"n":"מאירוביץ, אברהם מסקימייאן","f":"משה","k":"בעל דרוש לפי רוח הזמ","bt":"תרלד","bp":"קרליץ","dt":"תשא","b":"תלמיד ישיבות מיר, ולוזין, סלובודקה. חתן ר בצלאל בן יוסף כץ - רבה של הקהלה החסידית בראקישוק. רב בסקימיאן-תרסט, ראקישוק על מקום חותנו, אבאל-תרפח. נסמך מאת: ר צבי הירש רבינוביץ מקובנא, ר משה דנישבסקי, ר מרדכי וייצל מסלונים, ר יצחק יעקב רבינוביץ מפוניבז. מראשי ה\"מזרחי\". ממיסדי הבנק העממי היהודי בראקישוק. חיבר ספר דרושים \"דרוש לפי רוח הזמן\" - בכת\"י."},{"i":29085,"n":"מאירוביץ, אברהם נחום מארה\"ב","k":"בעל ילקוט ההדרנים-כת","bt":"תרמט","bp":"פוניבז","b":"תלמיד ר נפתלי הרץ קרצמר. היגר לניו יורק, וכיהן כרב, יסד-תרעט חברת \"מחזיקי תורה\". היה בעל ספריה חשובה, חיבר \"ילקוט ההדרנים\" שאסף על סיומי ש\"ס. הסכים על \"גרן שלמה\"."},{"i":29086,"n":"מאירוביץ, דוד זאב","k":"בעל אונטער דער זון","bt":"1908","bp":"וילקומיר","dt":"1941","b":"פרסם שירים באידיש בעתוני התקופה - בעלי אופי מהפכני. חיבר גם \"און קומען וועט דער טאג\". נספה בשואה. ?? לא באוצר ??"},{"i":29087,"n":"מאירוביץ, יצחק מהידאלמאש","f":"רש\"י מטשעטשאויץ","bp":"טשעטשאביץ","dt":"תרף-תרץ","dp":"גרוסורדין","b":"תלמיד השב\"ס, ור אליעזר חיים דייטש מבאניהאד ועוד. חתן ר יחיאל מאיר פנט מהידאלמאש - נכד הכת\"ס. רב בהידאלמאש-תרסב לצד חותנו זקנו - ר אשר שמואל פנט. נפטר בדמי ימיו."},{"i":29088,"n":"מאירוביץ, נחמן ראובן מדוקשיץ","f":"אליהו","k":"בעל חלקת ראובן","b":"רב בסמרגון, דאקשיץ(=דוקשיץ)-תרל."},{"i":29089,"n":"מאירוביץ, שאול","b":"פרסם מאמרים ב\"כנסת ישראל\" - וילנא תרץ."},{"i":29090,"n":"מאירוביץ, שלום דוב","k":"בעל אהבת דוד","b":"רב בוועגער(=ואגר)-תרל על מקום ר נחום שפירא \"העילוי מדוקשיץ\"."},{"i":29091,"n":"מאירוביץ, שלמה מארה\"ב","k":"בעל דברי שלמה","b":"רב בארה\"ב. חיבר \"דברי שלמה\" נ\"י תרעא."},{"i":29092,"n":"מאירוביץ, תודרס (פיודר)","f":"מנחם","bp":"טאווריג","dt":"1920-אחרי","dp":"קובנא","b":"רופא ראשי בביה\"ח היהודי \"ביקור חולים\" בקובנא. פעל במוסדות רבים ובעיקר בבית היתומים ע\"ש ר יצחק אלחנן בקובנא."},{"i":29093,"n":"מאירי-פוירוורגר, מאיר","k":"בעל אוצר האגדה","bt":"תרסד","bp":"טרנוב","dt":"תשכח - שבט","b":"תלמיד ישיבות חוסט, סעליש, אונסדורף, סטמר. רב הקהילה החרדית בפפד\"מ-תרפט. ברח לבגליה-תרצט והתישב בבריסל, בזמן השואה עסק בפעילות הצלה. ניצל מהשואה אך איבד את משפחתו. אחרי השואה עיה חבר בית הדין בבריסל שאעסק בשאת העגונות. עבר ללונדון-תשטו וניהל בי\"ס מונטיפיורי. חיבר גם \"עזרת נשים\" בריסל תשיא, \"בעקבתא דמשיחא\".","bk":[["אוצר האגדה",""],["בעקבתא דמשיחא",""],["עזרת נשים ספר א",""],["עזרת נשים ספר ב",""],["עזרת נשים ספר ג",""],["תורת האגדה",""]]},{"i":29094,"n":"מאירס, אריה ליב מאמריקה","b":"פרנס ביהכ\"נ נווי צדק בסן פרנציסקו-תרם בערך."},{"i":29095,"n":"מאירסון, אריה ליב מליסקוב","f":"יום טוב ליפמן מליסקא","bt":"תרכ","dt":"תרצא - יב שבט","b":"רב בליסקבה(=ליסקאווא)-פלך גרודנא-תרסו על מקום אביו."},{"i":29096,"n":"מאירסון, זרח מניו יורק","k":"בעל טוב ויפה","b":"רב בניו יורק-תרע."},{"i":29097,"n":"מאירסון, חיים","b":"חתן מהרי\"א איטינגא."},{"i":29098,"n":"מאירסון, יום טוב ליפמן מליסקוב","dt":"תרסו - בערך","b":"רב בליסקאווא(=ליסקוב)-פלך גרודנא-תרל ובנו ר אריה ליב על מקומו אחריו-תרסו."},{"i":29099,"n":"מאירסון, מאיר מבוטושן","f":"חיים יצחק","bt":"תרכא","bp":"ברזאן","dt":"תרצו","b":"חתן הגביר ר משה מאניס זינקוב מסטאוויטש. רב בבוטושן (והיה במחלקות עם הרבנים טויבש בעיר), פאקשן, וינה. שימש כבורר בין בנק רוטשילד לבנק אחר על פי הזמנת ממשלת אוסטריה - וכך התעשר מהבוררות. שהה בירושלים-תרצג וקנה בית כהכנה לעלייתו - ולא הספיק לעלות."},{"i":29100,"n":"מאירסון, צבי הירש","f":"יעקב פישל","b":"חתן ר יצחק בעל \"מנחת יצחק\" (איזה?)"},{"i":29101,"n":"מאירסון, שלום הלוי","b":"רב-שנת תרכ\"ו"},{"i":29102,"n":"מאירשיק, ישראל מלובלין","b":"פרסם מאמרים ב\"מאסף דרושי\" - וילנא תרסט."},{"i":29103,"n":"מאך, חיים מצוזמיר ולבוב","k":"חיים ר בודן מא\"ך","b":"ראש מדינה בגליל לבוב. חתם-תן על תקנת זולקוא שנעשו בקוליקוב, חתם ביריד ירוסלב-תנג, בלבוב עם ר משה חריף, ובלבוב-תנה עם ר פנחס משה ועוד."},{"i":29104,"n":"מאך, משה משאריגרד","f":"שמואל הפרנס מבריסק","b":"רב בשאריגרד-תי, זולקוא. אחיו - ר נפתלי הרץ-אביו של בעל בית הלל. גיסו - ר יהושע חריף בעל \"מגיני שלמה\". בנו - ר יעקב אליהו חריף."},{"i":29105,"n":"מאך, שמואל מבריסק","f":"משה ר הללס מבריסק","dt":"שפט","b":"פרנס ועד ארבע ארצות בבריסק-שפ (קראקא?). חתנו - ר יהושע חריף בעל מגיני שלמה. בניו - ר משה מאך משאריגארד, ר נפתלי הרץ מזולקווא, ונכדו - ר הלל בעל \"בית הלל\". (באוצר הרבנים מופיע גם כרב בקראקא)."},{"i":29106,"n":"מאלאטין, ישעיה מארה\"ב","f":"משה יחזקאל","bt":"תרסב","bp":"וישנובה-פלך וילנא","b":"תלמיד ישיבות ראדין, מיר, ישיבת רבי יצחק אלחנן בניו יורק. נסמך מאת: ר שלמה פוליאצוק ממייצט. חתן ר זאב ראגין מבוסטון. רב בקהלת \"מסלת ישרים\" בניו יורק-תרצא. חבר אגודת הרבנים באמריקה."},{"i":29107,"n":"מאלאסטאווקער, פסח","b":"תלמיד בעל התניא. מכתב ממנו ב\"התמים\" - וארשא תרצה - קובץ חסידי חב\"ד."},{"i":29108,"n":"מאליא, יוסף הרופא משלוניקי","dt":"תלז - ג אב","dp":"שלוניקי","b":"רופא בשלוניקי."},{"i":29109,"n":"מאליא, משה משלוניקי וקושטא","dp":"קושטא","b":"מחכמי שלוניקי-שנות ה-ת', עבר לקושטא. תשובה ממנו ב\"פני משה\". בנו - ר יוסף מאליא הרופא."},{"i":29110,"n":"מאלין, שמחה מביאליסטוק","b":"מחכמי ביאליסטוק, מכתב ממנו-תרצו בעניני גיטין."},{"i":29111,"n":"מאליר, אברהם מפרג ואיטינגן","b":"אב\"ד באיטינגן. הסכים על \"בעל הטורים לתורה\" - פיורדא תקיג."},{"i":29112,"n":"מאלצאוו, שמואל מבלבנווקא","f":"יעקב שלמה","bt":"תרכו","b":"מו\"צ בדאשיב-תרנז, בלבנווקה(=באלאבאנווקע)-פלך קיוב-תרסד."},{"i":29113,"n":"מאמאלך, יעקב משה הלוי מלודז","b":"בהיותו בחור פרסם מאמרים ב\"יגדיל תורה\" - פראגא-וארשא תרפז."},{"i":29114,"n":"מאמאן, אבא מירקדו","f":"משה מצפת","bt":"תרמו","bp":"צפת","dt":"תרפח - יח שבט","dp":"צפת","b":"עסקן פעיל ציבור בצפת."},{"i":29115,"n":"מאמאן, אברהם מטבריה","dp":"טבריה","b":"מחכמי טבריה"},{"i":29116,"n":"מאמאן, אברהם ממראקש-מרוקו","dt":"תצג - א אב","dp":"מקנאס-מרוקו","b":"מו\"ץ במראקש-תצב, חתם-תעב עם ר דוד בנבנשתי, ר יוסף סעדון."},{"i":29117,"n":"מאמאן, אהרן מצפרו-מרוקו","b":"מחכמי צפרו, נזכר ב\"נועם שיח\" לר שמואל אלבאז ושם שיר לכבודו."},{"i":29118,"n":"מאמאן, אליהו מאיר מטבריה","dt":"תרך - יז תמוז","b":"מרבני טבריה"},{"i":29119,"n":"מאמאן, דוד ממראקש","f":"אברהם","b":"מו\"צ במראקש, חתם באגרת תנחומים לפטירת היעב\"ץ-תקיג עם ר יעקב בן יצחק פינטו, ור דוד יוסף סעדון."},{"i":29120,"n":"מאמאן, דוד ממרוקו","f":"ישועה","dt":"תשט - ז כסלו","b":"מחכמי מרוקו, רב בצפרו"},{"i":29121,"n":"מאמאן, חיים","f":"ישועה","bt":"תרכב","dt":"תרצא - כא חשון","b":"רב בצפרו"},{"i":29122,"n":"מאמאן, חיים יוסף מטבריה","f":"שלמה","bt":"תריח (או תרל)","bp":"טבריה","dt":"תרפה - כב אלול","dp":"טבריה או צפרו","b":"נכד ר רפאל מצפת. מחכמי טבריה, בשנת תרנח בשליחות במרוקו, בשנת תרסו נתמנה לרב בעיר אוראן(=אמראן)-אלגיר, תמושנת-תרסז, ווהראן-תרסט, לאראש וקזבלנקא. בשנת תרעב הדפיס באלגיר \"קול ריחים\", \"משמרות החיים\" - בענין המחלוקת על טחינת חטים במכונה לפסח. כמה מתשובותיו בספר \"תועפות ראם\" לר רפאל אנקואה. בשנת תרפד חזר לטבריה. השאיר שות וספר דרושים בכתב יד"},{"i":29123,"n":"מאמאן, יהושע אהרן מצפרו","b":"מחכמי צפרו."},{"i":29124,"n":"מאמאן, יוסף דוד מצפת","f":"אהרן","k":"בעל המשקיף","bt":"תרמה","bp":"צפת","b":"פרסם מאמרים ב\"החרות\". עסק בהוראה ומסחר באנגליה ובצרפת, התישב בירושלים-תרצד והיה בועד העדה הספרדית. חיבר קונטרס \"המשקיף\"."},{"i":29125,"n":"מאמאן, יוסף ממרוקו וצפת","f":"משה","bt":"תקיב","bp":"מרוקו","dt":"תקפג","dp":"בוכרה","b":"מו\"ץ במרוקו - טיטואן או מכנאס, עלה לארץ והתישב והיה מחכמי צפת. בשליחות בבוכרה ונשאר שם לכהן כרב. מתורתו ב\"זכר צדיק\", נזכר ב\"יסוד מערבי\"."},{"i":29126,"n":"מאמאן, יוסף מצפרו-מרוקו","f":"רפאל","k":"בעל חירגא דיומ\"א","b":"מחכמי צפרו-שנות ה-תק'-תר'. בנו - ר רפאל. הניח חדושים ומאמרים בשם \"חירגא דיומ\"א (ר\"ת יוסף מאמאן)."},{"i":29127,"n":"מאמאן, יצחק מצפת","f":"שלמה","bt":"תרמד","bp":"צפת","dt":"תרפט - כג אב","dp":"צפת","b":"חתן ר אברהם הכהן-קונסול פרס בצפת, אביו ואחיו נרצחו ע\"י ערבים. פעיל ציבור בצפת. נהרג עק\"ה בפרעות תרפט."},{"i":29128,"n":"מאמאן, מרדכי מצפת","k":"בעל זכרון משה","dt":"תרמה","dp":"צפת","b":"דיין בצפת-תרלג, חתנו של ר שמואל עבו, רב בצפת על מקום חותנו. בשנת תריח בשליחות באדרינופול. חיבר \"זכרון משה\" ירושלים תרסז."},{"i":29129,"n":"מאמאן, משה ממכנאס","dt":"תקכג - כד שבט","dp":"מכנאס","b":"גביר מחכמי מכנאס. נרצח ע\"י ערבי בתוך ביתו. נספד ע\"י בי\"ד של ארבעה בפאס והם ר שאול ן דנאן, ר רפאל עובד ן צור, ר אליהו הצרפתי, ור מתתיהו סירירו."},{"i":29130,"n":"מאמאן, משה מפאס","b":"מחכמי פאס-תצב, חתם עם השוחטים בפאס ר יוסף הכהן בן זבולון ור עזוז בן למדאלסי, ור אברהם אדארוקי. נזכר ב\"עדות ביהוסף\"."},{"i":29131,"n":"מאמאן, משה מצפת","dt":"תרסט","b":"רב בצפת-תרנד. בנו - אבא מירקדו."},{"i":29132,"n":"מאמאן, נסים אליהו מטבריה","dt":"תרצה - כא אב","dp":"טבריה","b":"מחכמי טבריה."},{"i":29133,"n":"מאמאן, עזוז מפאס","b":"סופר שטרות בפאס-תקצז, וחתם עם ר רחמים חיים דודו ן זמרא."},{"i":29134,"n":"מאמאן, רפאל - א ממכנאס וטבריה","f":"שלמה","k":"בעל מרפא לנפש-תרנד","bt":"תקע","bp":"מכנאס","dt":"תרם או תרמב","dp":"טבריה","b":"עלה לארץ בנערותו, והתישב בטבריה. רב בטבריה-תרו, צפת-תרי, אב\"ד טבריה-תרלה . חיבר שו\"ת ודרושים בכת\"י, ומתשובות נדפס \"מרפא לנפש\". בנו ר שלמה."},{"i":29135,"n":"מאמאן, רפאל עמרם מצפרו","bt":"תרלא","bp":"צפרו","dt":"תש..","dp":"צפרו","b":"גביר מחכמי צפרו-מרוקו, שו\"ב, מוהל, גזבר הקהילה ואחראי על הצדקה לעניים. תלמיד ר שלום אזולאי ודיין בבית דינו עם ר אלישע אפרייאט וחברו ר ישמ\"ח עובדיה. אפוטרופוס בי\"ד ליתומים ואלמנות. ראש ישיבת עמור. מומחה לעיבור וללוח העברי והכין לוח שנה בשנה, הכריע להמשיך לנהוג כמנהג הגאונים בענין השקיעה וצאת הכוכבים - ולא כר\"ת. היה מגיע לגיברלטר לרגל מסחרו. בנו - הקדוש ר יוסף."},{"i":29136,"n":"מאמאן, שלום מאלג'יר","f":"רפאל","k":"בעל אמרי שפר","b":"רב באלג'יר-תקפג. חיבר \"אמרי שפר\" על מנהגי השחיטה בצפון אפריקה."},{"i":29137,"n":"מאמאן, שלם מצפרו-מרוקו","b":"מחכמי צפרו-מרוקו."},{"i":29138,"n":"מאמאן, שלמה מטבריה","f":"רפאל מצפת","bt":"תקפח","bp":"טבריה","dt":"תרמו","dp":"טבריה","b":"מחכמי טבריה"},{"i":29139,"n":"מאמאן, שמואל יהודה","f":"שלמה מאמן","bt":"תרטז","bp":"טבריה","dt":"תרנו","dp":"טבריה","b":"מגדולי רבני טבריה"},{"i":29140,"n":"מאמו, כמוס (מימאס) מג'רבה","bt":"תרנב","dt":"תשז - י סיון","b":"מחכמי ג'רבא ומפקח על הישיבות. הגהות ממנו ב\"ברכת אברהם\" למהר\"א מגוץ הכהן, ונדפסו בסוף \"פרחי כהונה\". מחדושיו נאסף \"מעט מים\" ו\"בני מכיר\". פרסם מאמרים ב\"הירח\" - ג'רבה תשח.","bk":[["מעט מים",""]]},{"i":29141,"n":"מאמין, אברהם מירושלים","b":"פרסם מאמרים ב\"תורת ירושלים\" - \"תפארת ירושלים\"- \"תורה מציון\" ירושלים תרצו."},{"i":29142,"n":"מאנאזאניק, אברהם דובער מברדיטש","b":"גביר מחכמי ברדיטשוב. נספד מאת ר שמואל אבא הורודצקי ב\"אבל יחיד\" - ברדיטשוב תרנה."},{"i":29143,"n":"מאנגארה, אליעזר מקושטא","b":"רב בקושטא-שנות ה-ש', היה מעורב במחלוקת בענין מקוה והובאה השאלה אל ר יוסף טרני."},{"i":29144,"n":"מאנדיל, בנימין משלוניקי","dt":"תכב","b":"רב בשלוניקי. חתם-שפא עם ר בנימין עשאל, ור יצחק ליריאה."},{"i":29145,"n":"מאנדיל, חסדאי משלוניקי","dt":"תג - כח אלול","dp":"שלוניקי","b":"מחכמי שלוניקי."},{"i":29146,"n":"מאנדיל, יצחק מאישקופיה","b":"גביר באישקופיה-תלו, קנה מהקהלה את בית ההקדש \"בית יעקב\" והיה מחלוקת על כך, וחכמי שלוניקי ר אליהו קובו ור אהרן פרחיה הצדיקו אותו."},{"i":29147,"n":"מאנדיל, יצחק משלוניקי","dt":"שעז - יד אלול","dp":"שלוניקי","b":"מהרוגי דולייא."},{"i":29148,"n":"מאנדיל, משה משלוניקי","dt":"תיט - יא אלול","dp":"שלוניקי","b":"מחכמי שלוניקי."},{"i":29149,"n":"מאנדיל, נחמיה מדרעא-מרוקו","f":"ישראל","b":"מחכמי דרעא-מרוקו, נזכר אודות סגולה ממנו."},{"i":29150,"n":"מאנדיל, ראובן","b":"חכם בזמן ר חיים פלאג'י."},{"i":29151,"n":"מאנו, לנקה מלאפוש","b":"רב ניאולוגי בלאפוש על מקום הירש אופנהיימר, ומנהל ביה\"ס במקום."},{"i":29152,"n":"מאנוש לוקניקער","b":"מתושבי טלז בזמן המרד הפולני-1831, בנו - הגנרל הרוסי ראזען. נהרג בידי הפולנים."},{"i":29153,"n":"מאנוש, שלמה מירושלים","dp":"צפת","b":"רב בירושלים, מובא במכתב השלה, ברח בזמן אבן פארוך לצפת. (לדעת פרומקין זו טעות בשם וצ\"ל ר שלמה סאגיש)."},{"i":29154,"n":"מאניזון, יוסף","k":"חתן ר' ישראל מרוזין","b":"רב-שנת תר\"ל"},{"i":29155,"n":"מאנילה, רפאל מקושטא","b":"גביר בקושטא ומקורב לשלטון, השפיע על הוזיר לאלץ את רבני קושטא להתיר את החרם על נחמיה חייא חיון."},{"i":29156,"n":"מאניש הלוי ממזריטש","dt":"תקצב - כב אלול","b":"מו\"צ במזריטש"},{"i":29157,"n":"מאנן, אברהם מארה\"ב","dt":"תרפט - ה כסלו","dp":"ניו יורק","b":"רב ודרשן בניו יורק. ממיסדי אגודת כנסת הרבנים."},{"i":29158,"n":"מאנס, אברהם","f":"שמואל","bt":"1897","bp":"גרודנא","b":"למד היסטוריה בברלין. פרסם מאמרים וספרים על התנ\"ך ועוד. מעורכי האנציקלופדיה הכללית באידיש בפאריס. ערך כרך מיוחד של \"שריפטן\" של \"ייוו\"א\" המוקדש לתולדות תנועת הפועלים היהודית. היגר לניו יורק-1940. פרסם ב\"צוקונפט\", ועוד."},{"i":29159,"n":"מאנס, ישראל משה מנייא-ביחוב","f":"יוסף מרדכי הלוי","bt":"תרכט","bp":"סטאראבין","b":"בן למשפחת שמעלקין-מצד אמו, ודור שישי לר שמואל שמלקא הורביץ מניקלשבורג. תלמיד ישיבת וולוזין, כולל קובנא. רב בביחאוו-חדשה(=נייא-ביחאוו)-פלך וילנא-תרסג. נסמך מאת: ר יצחק אלחנן מקובנא, ר מרדכי דב מהורנסטיפל."},{"i":29160,"n":"מאנס, שלמה הכהן משואבאך","f":"יהודה","bt":"תרלא","b":"רב בשוובך(=שוואבאך)-תרסא."},{"i":29161,"n":"מאנסאנו, אברהם מפאס","f":"יונתן","k":"בעל ברית אבות","dt":"תקמא - ט אלול","dp":"פאס","b":"תלמיד ר שמואל אלבז מפאס. מחכמי פאס, כתב ספרים רבים, ביניהם\"ברית אבות\" ו\"זרע אברהם\". חתנו - ר חיים דוד סירירו. אחיו - ר עמנואל, ר חיים, ר אליהו."},{"i":29162,"n":"מאנסאנו, אליהו מפאס","f":"עמנואל","b":"מחכמי פאס"},{"i":29163,"n":"מאנסאנו, אליהו מפאס","f":"יונתן","dt":"תקעג - ג אלול","b":"מחכמי פאס-תצז, פגש את בעל \"אור החיים\". אחיו של ר אברהם. התאריכים לא מסתדרים - כנראה המדובר בשני חכמים שונים באותו השם."},{"i":29164,"n":"מאנסאנו, בצלאל מפאס","k":"בעל מבשר טוב - כת\"י","dt":"תקפו - יח אדר","b":"דרשן מחכמי פאס-תקסט. הניח כתבים בכת\"י והיו בידי ר מימון מאנסאנו. בנו - ר יונתן חיים."},{"i":29165,"n":"מאנסאנו, ברוך מפאס","b":"מחכמי פאס-שנות ה-ת', חתם עם ר אלעזר בהלול."},{"i":29166,"n":"מאנסאנו, חיים מפאס","f":"יונתן","b":"מחכמי פאס-שנות ה-תק', חתם על פס\"ד עם ר מתתיה סירירו, ר\"מ ן עטר, ור מנחם סירירו. אחיהם של: ר עמנואל ור אברהם."},{"i":29167,"n":"מאנסאנו, יהודה ממרוקו","f":"עמנואל","b":"מחכמי מרוקו, אחיו של ר יונתן וחתנו - ר עמנואל בן יונתן-אחיו."},{"i":29168,"n":"מאנסאנו, יהונתן מפאס","f":"עמנואל","b":"מחכמי פאס. בניו: ר עמנואל, ר אברהם, ר חיים."},{"i":29169,"n":"מאנסאנו, יהונתן מפאס","f":"חיים","dt":"תקפב - ו אב","b":"מחכמי פאס. בנו - ר בצלאל הזכירו בספר דרושים שלו."},{"i":29170,"n":"מאנסאנו, יוסף מפאס","b":"מחכמי פאס."},{"i":29171,"n":"מאנסאנו, יעקב ממרוקו","f":"אברהם","b":"מחכמי מרוקו-תקסה."},{"i":29172,"n":"מאנסאנו, יצחק מפאס","f":"יונתן","b":"מחכמי פאס-תקעו."},{"i":29173,"n":"מאנסאנו, עמנואל הזקן מפאס","f":"יוסף","dt":"תקל או תקכז","b":"מחכמי פאס וסופר בית הדין, נזכר ב\"זכות אבות\" וב\"משפט וצדקה ביעקב\". נקרא הזקן כדי להבדילו מר עמנואל בן יהונתן שהיה מחכמי פאס גם הוא."},{"i":29174,"n":"מאנסאנו, עמנואל מפאס - ב","f":"יונתן","b":"מחכמי פאס-תצד. חיבר דרושים."},{"i":29175,"n":"מאנסאנו, עמנואל מפאס - ג","f":"אליהו","b":"מחכמי פאס-תקף. חיבר דרושים."},{"i":29176,"n":"מאנסאנו, שמואל ממרוקו","f":"אברהם","b":"מחכמי פאס - בשנות ה-תק'. (ואולי יש המחליפים אותו בר עמנואל)."},{"i":29177,"n":"מאנסירי, אפרים מקושטא ודמשק","dt":"שפ","dp":"דמשק","b":"מסעוד - שהיה רב קהלת סיצילה), מקובל, רופא, מחכמי קושטא, רב קהלת הספרדים בדמשק - לצד ר יהודה . נקבר ליד ר חיים ויטאל."},{"i":29178,"n":"מאנסנאו, יהונתן חיים ציון מפאס","f":"בצלאל","b":"תלמיד ר רפאל יעקב ן שמחון. מחכמי פאס-שנות ה-תר'-תש'. העתיק כמה מספרי הקדמונים."},{"i":29179,"n":"מאנעהל, נתן צבי מלעטניא","b":"רב בלעטניא. פרסם מאמרים ב\"אסיפת חכמים\" - אטוניא-בויאן תרע-תרעד."},{"i":29180,"n":"מאנעוויץ, שלמה מקסטיקוביטש","f":"דובער בן אשר","b":"נכד ר אשר ממסטיסלב. רב בקסטיקוביץ. חתנו - ר משה צבי אלטשול מבאקו."},{"i":29181,"n":"מאנשס, חיים","b":"מחכמי לובלין"},{"i":29182,"n":"מאסבך, אשר ענזיל מגראבפלד","b":"רב בגראבפלד-תק\"ס"},{"i":29183,"n":"מאפו, אברהם","f":"יקותיאל","k":"בעל אהבת ציון","bt":"1808","bp":"סלובודקה","dt":"1867","dp":"קניגסברג","b":"התפרסם בילדותו כעילוי, למד קבלה והיה מקורב לחסידות. תלמיד ר אליהו רגולר. בגיל 20 החל ללמוד שפות והתקרב למשכילים והתקרב לשניאור זקש מראסיין (ששימשה אז כמרכז למשכילים), התקרב למשכילי וילנא אד\"ם הכהן, ק. שולמן ואחרים. חיבר גם \"עיט צבוע\" ובו על המחלוקת בין המשכילים לקנאים, ועוד."},{"i":29184,"n":"מאפנהויזן, שלמה זלמן צבי","k":"בעל יודשער טיריאק","b":"חכם וסופר - שנות ה-ש'. חיבר בלשון אשכנז \"יודישער טיריאק\" (צרי היהודים)-האנוי שעה - כנגד ספרו של המומר סמואל פרידריך ברנצי מאיטינגא \"דער יידיש שלאנגען באלג )חמת נחש של היהודים)."},{"i":29185,"n":"מאצאר, מסעוד","b":"פרסם מאמרים ב\"הירח\" - ג'רבה תשח."},{"i":29186,"n":"מאקאהן, יוסף מואפניארקע","b":"פרסם מאמרים ב\"קול תורה\" - וארשא תרסח."},{"i":29187,"n":"מאראז, חיים (או חיים מאראז)","b":"פרסם מאמרים ב\"כנסת חכמי ישראל\" - אודסה-פיעטרקוב-ברדיטשוב תרנג-תרס."},{"i":29188,"n":"מאראן, משה מוונדין","k":"בעל אוהב מוסר","dt":"תשג","b":"רב בוונדין"},{"i":29189,"n":"מאראק, שמואל משאודין","dt":"תג","b":"רב בשאודין"},{"i":29190,"n":"מאראקא, אברהם מרדכי מזלוטשוב","b":"רב בזלוטשוב. עורך \"דגל הצעירים\" - וארשא תרפה, \"דגל הרבנים\" - וארשא תרפו."},{"i":29191,"n":"מאראקא, מרדכי דוד מבורזנין","b":"חסיד אלכסנדר, רב בבורזנין. פרסם מאמרים ב\"בית ישראל\"-\"בית שמואל\" - לודז תרץ, \"כרמנו\" - אלכסנדר-לודז תרצג. פרסם הספד לבן האדמור מאלכסנדר ב\"נהור שרגא\" - אלכסנדר תרצט."},{"i":29192,"n":"מאראש, אברהם מויריאה","b":"רב בויריאה-שנות ה-ת'."},{"i":29193,"n":"מארגי, אברהם מאזמיר","b":"מחכמי אזמיר-תקן בערך."},{"i":29194,"n":"מארגי, דוד ממרוקו וחברון","f":"מרגי","bp":"מרוקו","dt":"תקלח - כב חשון","dp":"טבריה","b":"מחכמי מרוקו שעלה לחברון, בשנת תקכג חתם על כתב שליחות ר חיים רחמים באג'איו ור יצחק זאבי. בשנת תקכט בשליחות חברון לצפון אפריקה. במרוקו חיבר לכבודו הפייטן ר דוד בן חיון שיר"},{"i":29195,"n":"מארגי, יוסף מצפת וטבריה","f":"נתן ממכנאס וצפת","b":"מחכמי טבריה-תקצג."},{"i":29196,"n":"מארגי, יעקב מטיטואן","b":"מקובל מחכמי טיטואן שנות ה-ת', הגיה את \"אוצרות חיים\" יחד עם ר אברהם ן מוסא - ונדפסו. חיבר פירוש על האדרות ונדפסו בוינה."},{"i":29197,"n":"מארגי, יעקב מראבאט","b":"מחכמי ראבאט-שנות ה-ת'."},{"i":29198,"n":"מארגי, יצחק מראבאט-מרוקו","f":"משה","b":"מחכמי ראבאט-תקעד."},{"i":29199,"n":"מארגי, מאיר מפאס","bp":"מרוקו","b":"מחכמי פאס, ממשפחת המקובל ר יעקב בן מרגי, עלה לארץ ישראל בשנת תקטו."},{"i":29200,"n":"מארגי, מאיר משלוניקי","b":"רב בשלוניקי. תלמידו ר חיים יצחק מוספיא מזכירו בספרו \"חיים וחסד\"."},{"i":29201,"n":"מארגי, משה מפאס","b":"מחכמי פאס, חתם על הסכמה-רפו בענין הנפיחה."},{"i":29202,"n":"מארגי, משה מראבאט","b":"מחכמי רבאט-מרוקו-שנות ה-תק'. בנו ר יצחק שהיה מחכמי העיר-תקעד."},{"i":29203,"n":"מארגי, נתן ממכנאס וצפת","f":"יוסף","b":"מחכמי מכנאס-מרוקו, עלה לצפת וטבריה, בשליחות באיטליה-תקפט. בנו - ר יוסף."},{"i":29204,"n":"מארגי, סעדיה ממרוקו","b":"מחכמי ארבאט-מרוקו. רבו של ר דוד ן שמעון שהביא ממנו בספרו \"שער החצר\"."},{"i":29205,"n":"מארגי, שמואל ממכנאס-מרוקו","b":"מחכמי מכנאס - בשנות ה-ת'. נזכר בהקדמת \"מלאכת הקדש\". תלמידו ר משה טולדנו בעל \"מלאכת הקדש\"."},{"i":29206,"n":"מארגרטן, יואל מערלוי","f":"יצחק צבי מאבראהאם","dt":"תרע - יא חשון","dp":"ערלוי","b":"רב בדיוסג-ליד גרוסורדין-תרכה, דיין בערלוי(=אויהל)-תרנה."},{"i":29207,"n":"מארדעל, פנחס הכהן מפילדלפיה","bt":"תרכא","bp":"שאט-פלך קובנא","b":"היגר לארה\"ב-תרמא, מורה בפילדלפיה בבתי העשירים. חיבר מאמרים בלשון העברית ב\"השלוח\". חיבר ביאור לספר יצירה - בכת\"י, וספרים שונים בדקדוק."},{"i":29208,"n":"מארוני, דוד יעקב מאיטליה","bt":"תקע","dt":"תרמח","b":"רב בצנטו, פיזרו, אנקונה, פירנצה, ועוד. חיבר שירים ועוד. תרגם מורה נבוכים לאיטלקית. התערב במחלוקת רבני מנטובה בענין יו\"ט שני - התנגד לביטולו."},{"i":29209,"n":"מארט, שמואל נחום מארה\"ב","k":"בעל דברי שמואל","b":"רב בארה\"ב-תרסד. חיבר \"דברי שמואל\" נ\"י תרסז, \"חשבון קץ הגאולה\"."},{"i":29210,"n":"מאריו, משה","b":"מגדולי רבני איטליה-ש\"פ"},{"i":29211,"n":"מארלי, שמואל ממנטובה","b":"רב במנטובה. נזכר ב\"שלטי גבורים\" לר אברהם שער אריה. תשובה ממנו ב\"פלגי מים\" בענין המקוה ברוויגו. חיבר פסק בענין הקהלה."},{"i":29212,"n":"מארקן, חיים ליב מוילנא","f":"מאיר אברהם","b":"למד אצל חכמי ומשכילי וילנא. עוזר בהוצאת \"הכרמל\". פרסם מאמרים בכתבי עת שונים. עסקן במוסדות הצדקה בוילנא וממנהלי ספריית שטרשון. בעל ספריה חשובה."},{"i":29213,"n":"מארשילי, אברהם משלוניקי","dt":"תסה","dp":"שלוניקי","b":"רב בשלוניקי."},{"i":29214,"n":"מארשילי, חיים משלוניקי","dt":"תנא","dp":"שלוניקי","b":"רב ומלמד תורה בשלוניקי."},{"i":29215,"n":"מארשלקוביץ-פרנס, יצחק מדובנא","f":"צדוק מדובנא","k":"איציקל ר צדוק'ס","b":"גביר בדובנא. בנו - ר מרדכי צבי מארשלקוביץ, חתנו - ר שמואל בירנבוים מדובנא."},{"i":29216,"n":"מאשיץ, אלחנן מהידודישק","dt":"תשג","b":"רב בהידודישק"},{"i":29217,"n":"מאשיץ, יהודה מוילייקא","k":"בעל מחנה יהודה","dt":"תשג","b":"חתן ר שלום מוילייקא, רב בווילייקא(=וילקי) על מקום דודו. נספה בשואה."},{"i":29218,"n":"מאשיץ, יהושע יהודה מויליקי","b":"רב בוילייקי"},{"i":29219,"n":"מאשעלעס, איגנץ מוינה","bt":"תקנד","bp":"פרג","dt":"1870","b":"מוסיקאי, עבר לוינה והיה מיודד עם בטהובן, מלמד מוסיקה בלייפציג. אשתו חברה ספר תולדותיו \"אויס מאשעלעס לעבען נאך בריעפען...\"."},{"i":29220,"n":"מבורך הכהן מאשקלון","f":"נתן","b":"מחכמי אשקלון ודיין, בשנת ד'תתצה (1135) חתם על שטר חכירה."},{"i":29221,"n":"מבורך הנגיד ממצרים","f":"סעדיה","b":"רופא ונגיד במצרים-ד'תשפ על מקום ר יהודה בן ישעיה, ור מרדכי בן אלהרביה על מקומו אחריו."},{"i":29222,"n":"מבורך ממצרים","f":"נתן","b":"רב במצרים בזמן הרמב\"ם. חתם על תקנות בענין טבילות לצד הרמב\"ם."},{"i":29223,"n":"מבורך, אברהם מניקופול","f":"חיים גליפפה-מבורך","b":"רב בניקופול-שנות ה-ת'."},{"i":29224,"n":"מבורך, אברהם שלמה","dt":"תרעז - ז אב","b":"דיין בירושלים אצל ר רפאל יצחק ישראל, חתם על פסק בענין מגרש מונטיפיורי. פרסם מאמרים ב\"המאסף\"."},{"i":29225,"n":"מבורך, ברוך מסופיה","f":"שלמה","b":"גביר בסופיה-תקן, תמך ברבנים ובהדפסת ספרים. אחיו - חיים מסופיה."},{"i":29226,"n":"מבורך, חיים מניש","f":"פסח","b":"דיין בניש-תקנח יחד עם ר יהודה ן עלי בעל \"קמח סולת\"."},{"i":29227,"n":"מבורך, חיים מסופיה","f":"שלמה","b":"גביר בסופיה-תקן, תמך ברבנים ובהדפסת ספרים. אחיו - ברוך מסופיה."},{"i":29228,"n":"מבורך, משה משלוניקי","dt":"תקכא - ניסן","dp":"שלוניקי","b":"רב ופוסק בשלוניקי. חתם על פסק ר בנבנשתי גטניו לקהלת קורפו."},{"i":29229,"n":"מבורך, עזרא מסופיה","b":"גביר בסופיה-תקן, תמך ברבנים ובהדפסת ספרים."},{"i":29230,"n":"מבורך, פסח מסופיה","b":"גביר בסופיה-תקן, תמך ברבנים ובהדפסת ספרים."},{"i":29231,"n":"מבורך, שלמה מסופיה וקאשטוריה","bp":"סופיה","dp":"קאשטוריה","b":"רב בסופיה, קאשטוריה על מקום ר יוסף אלמיטרי."},{"i":29232,"n":"מבטאן, אליהו מפאס","b":"מחכמי פאס-תר.."},{"i":29233,"n":"מבריק, דוד משלוניקי","dt":"שצה - טו אייר","dp":"שלוניקי","b":"מחכמי שלוניקי."},{"i":29234,"n":"מבשר הכהן","f":"טוביה","b":"מחכמי רמלה, בשנת ד'תשצט (1059) תחם על מעשה בית דין."},{"i":29235,"n":"מבשר הלוי מבבל","k":"בעל האגרון","b":"מחכמי בבל בזמן רב סעדיה גאון. חיבר השגות על רב סעדיה בשם \"האגרון בשרשי הלשון\"."},{"i":29236,"n":"מג'אג'ון, אליהו","dt":"תקיג","dp":"צפת","b":"מחכמי שאלוניקי, רב בירושלים, עבר לצפת"},{"i":29237,"n":"מג'אג'ון, מצליח מסרייבו","dt":"תא - בערך","dp":"סרייבו","b":"רב בסרייבו עם ר שמואל בן ברוך משלוניקי וחתמו יחד כמה פעמים. לאחר פטירתו לא נתמנה רב על מקומו ובני העיר מסרו דינם לרבני שלוניקי, או רבנים זמניים, עד שנת תן שאז נבחר ר יצחק צבי משלוניקי."},{"i":29238,"n":"מגאצי, יעקב הכהן מגרבה","b":"פרסם מאמרים ב\"מקבציאל\" - גרבה תרצה."},{"i":29239,"n":"מגארי, שלמה הכהן מתימן","bt":"תרסד","bp":"צנעא","dt":"תשו","dp":"צנעא","b":"מחכמי צנעא, תלמיד ר יחיא קאפח. מלמד לתלמידים ובקי גם במדעים. חיבוריו אבדו ונותר חיבור בענין הלוח ועיבור השנים."},{"i":29240,"n":"מגד, אברהם זאב","b":"אדמו\"ר מטישטין בקרקא"},{"i":29241,"n":"מגדולי האחרונים","bk":[["כ\"י איטליאני לאחד קדוש מדבר",""]]},{"i":29242,"n":"מגדורה, אהרן הכהן","b":"מרבני תונס"},{"i":29243,"n":"מגוטי, יוסף - יוסף בן מגוטי","b":"מחכמי ירושלים, מראשי עדת המערבים וחתם עמם בשנת שץ על כתב שליחות לר אברהם ביטון ור שמואל רימון."},{"i":29244,"n":"מגיד (שטינשנידר), הלל נח","f":"שלום ישראל","k":"בעל עיר וילנא","bt":"1829","bp":"שניפישוק","dt":"תרסד - ח חשון","dp":"וילנא","b":"נכד ר פנחס-מגיד בפלאצק. חתן ר ר יעקב גורדון. ביוגרף וגניאולוג. מקור שמו מקצועו - סתת אבנים ועסק כל חייו בחריטת מצבות, ובניסוח כתובות מליציות בדרך שיר על מצבות. פרסם מאמרים שונים בנושאים אלו - לעתים בקורתיים (כנגד סדורי הקבורה ואי הסדר בבית העלמין) שעורר מחלוקת כנגדו וגרם לו לפרסם לעתים בעלום שמו. חיבר ביוגרפיה של ד. אופנהים ב\"גן הפרחים\"-1882, \"אנשי השם\" - רשימות היסטורית על קהלת למברג. השתתף עם רש\"י פין ב\"קריה נאמנה\". בניו: דוד מפטרבורג, יהודה אליעזר מוילנא, מרדכי ממינסק.","bk":[["עיר ווילנא",""],["תולדות משפחות גינצבורג",""]]},{"i":29245,"n":"מגיד ,יהושע ממעטש","b":"רב במעטש-הונגריה. פרסם מאמרים ב\"אסיפת חכמים\" - אטוניא-בויאן תרע-תרעד."},{"i":29246,"n":"מגיד, אהרן","k":"בעל בית אהרן","b":"חיבר כללי הש\"ס בשם \"בית אהרן\". נ\"י תשכה."},{"i":29247,"n":"מגיד, אלתר","b":"פרסם מאמרים ב\"כנסת חכמי ישראל\" - אודסה-פיעטרקוב-ברדיטשוב תרנג-תרס."},{"i":29248,"n":"מגיד, אשר מוועסלי","bt":"תרכט","dt":"תרסח - ג כסלו","b":"חתן ר שמריה מרובזעביץ, ובזיוו\"ש חתן ר שמעיה יונביץ מקערץ. רב בוואסלי-פלך יקטרינסלב, גניצעסק-פלך טבריא. הניח חדושים בהלכה ואגדה - בכת\"י."},{"i":29249,"n":"מגיד, דוד מוילנא","f":"הלל נח מגיד-שטינשניד","k":"בעל מרדכי אנטוקולסקי","bt":"1862","bp":"וילנא","dt":"1940","b":"מזכירו של רש\"י פין וסייע לו בכתיבת \"האוצר\", ו\"כנסת ישראל\". פרסם מאמרים ב\"היום\", \"המליץ\", ועוד. השתתף באנציקלופדיה היהודית רוסית. ספרן בפטרוגרד-1918. תרגם את \"טביחת הבהמה\" לד\"ר דמבו, ערך את הספר הקראי \"צמח דוד\". חיבר גם \"תולדות משפחת גינצבורג\", חיבור על יהודי קווקז."},{"i":29250,"n":"מגיד, יעקב מגרוסורדין","b":"מתורתו ב\"קובץ מפרשי התורה\" - מארגרטן תרצג."},{"i":29251,"n":"מגיד, יעקב משה מארה\"ב","b":"פרסם מאמרים ב\"התבונה\" - נ\"י תשז - קובץ תלמידי ישיבת מיר, \"תורה אור\" - שנחאי תשו."},{"i":29252,"n":"מגיד, ירחמיאל מירושלים","k":"בעל תפלת ברכת החודש","b":"תלמיד ישיבת תורת חיים בירושלים. מחכמי ירושלים."},{"i":29253,"n":"מגיד, מאיר חיים מלאטשינא","b":"מלמד תורה בסלאטשינא-גרוזיה וכיהן כרב לא רשמי."},{"i":29254,"n":"מגיד, מאיר מבעדעווליא","b":"פרסם מאמרים ב\"דגל התורה\" - אויבר-וישווה תרפח."},{"i":29255,"n":"מגיד, משה ממעטש","b":"רב במעטש-הונגריה. פרסם מאמרים ב\"אסיפת חכמים\" - אטוניא-בויאן תרע-תרעד."},{"i":29256,"n":"מגיד, צבי הירש מסורדוק","dt":"תשד","b":"רב בסורדוק"},{"i":29257,"n":"מגיד, צבי הירש מסטרימטרע","dt":"תשג","b":"רב בסטרימטערע"},{"i":29258,"n":"מגיד, צבי הירש מקריסטישוב","b":"רב בקאריסטישוב"},{"i":29259,"n":"מגיד, קלמן מקרוז","f":"אליעזר מווארנא","bt":"תרלד","bp":"קובנא","dt":"תשא","dp":"ליד טירקשלה","b":"אביו היה מחכמי קובנא. נכד-אבי אמו ר צבי הירש דנילביץ מקרוז. תלמיד ישיבות סלובודקה, וטלז, ותלמיד ר יצחק רבינוביץ מפוניבז. רב מטעם בארמיאנסק-פלך טבריא-תרסב, פעל להצלת יהודים בזמן מלחה\"ע ה-I, ואחריה חזר לליטא וכיהן כרב בקרוז', רבה האחרון של ואקשנה. מראשי \"המזרחי\" בליטא, וחבר נשיאות אגודת הרבנים שם. נסמך מאת: ר חיים יהודה סוסניצר, ר שלמה הכהן מוילנא, ר צבי יעקב אפנהיים מקעלם. פרסם מאמרים ונאם באסיפות לטובת ארץ ישראל. נספה בשואה עם בני עדתו. פרסם מאמרים ב\"הלבנון\" - סטמר תרפח, \"מאסף דרושי\" - וילנא תרסט, \"שערי ציון\" - ירושלים תרפא. אחיו ר אשר מוועסלי - נפטר צעיר."},{"i":29260,"n":"מגיד, רי\"מ מזלוזיץ","k":"בעל ברית אברהם","b":"רב בזלוזיץ. פרסם מאמרים ב\"הנצח\" - לבוב תרפז."},{"i":29261,"n":"מגיד, שמעון אבא מלאזאוויע","f":"ישראל","bt":"תרלא","b":"נכד ר צבי הירש מגיד מקריסטישוב, ונכד ר שמואל אבא מסלאויטא. תלמיד ר צבי הירש מקארסין, תלמיד כולל קובנא. רב בלאזאוייע-פלך יקטרינסלב-תרנה. נסמך מאת: ר יצחק אלחנן מקובנא, ר מרדכי דב מהורנסטייפל."},{"i":29262,"n":"מגידיש, גבריאל מלוב","bt":"תרסח","dt":"תשנז","dp":"ישראל","b":"רב ביפרן-לוב, עלה לארץ וכיהן כרב במושב שלווה."},{"i":29263,"n":"מגידיש, יעקב מלוב","bt":"תרי","dt":"תרע - בערך","b":"רב וחכם באשי ביפרן-לוב."},{"i":29264,"n":"מגידיש, מסעוד מפאס","b":"מחכמי פאס-שנות ה-תק', נספד מאת ר חיים דוד סירירו."},{"i":29265,"n":"מגידיש, רחמים מלוב","bt":"תרל","dt":"תש - בערך","b":"רב בזאויה-לוב."},{"i":29266,"n":"מגילבסקי, נתן נטע מהורודישץ","f":"לוי יצחק","bt":"תרך","b":"רב בהורודישץ(=האראדישץ)-פלך קיוב-תרנח."},{"i":29267,"n":"מגילוואן, ליב נח מראסיין","b":"פרסם מאמרים ב\"שמעתתי דרבנן\" - אודסה תרמז."},{"i":29268,"n":"מגילניצקי יוסף בן יהודה","bt":"1870","dt":"ה'תשה 1945","bk":[["ליניען המכין לחומש",""],["פאלשטענדיגער ליניען־סדור לבתי־ספר ולעם",""]]},{"i":29269,"n":"מגילניצקי, יוסף מארה\"ב","f":"יוסף","k":"בעל הגדה לילדים","b":"רב בפילדלפיה. חיבר ספרי לימוד לילדים באידיש."},{"i":29270,"n":"מגינו צרפתי, מאיר מונציה","k":"בעל מחקר על המשי","b":"מחכמי ונציה, עבר לרומא-שמח. חיבר מאמר מחקרי על שזירת המשי - ושלחו במתנה לאפיפיור שיסטו החמישי (די רוסי)."},{"i":29271,"n":"מגיע, כלב יהודה מקושטא ואזמיר","f":"יהודה","b":"מדפיס בקושטא-תעג, אזמיר-תצג אצל ר יונה אשכנזי ור דוד חזן."},{"i":29272,"n":"מגיע, רפאל מקושטא ושלוניקי","b":"מדפיס בשלוניקי, עבר לקושטא-תקב לדפוס של בנימין בן משה רוסו."},{"i":29273,"n":"מגירגאנג, שלמה מפרס","f":"שמואל","k":"בעל אגרת המליצה","b":"מחכמי פרס - ה' אלפים (1240). חיבר אגרת המליצה-ד'תתקצט."},{"i":29274,"n":"מגירה, שם טוב מפאס","b":"רב בפאס, חתם-תנח על תקנה יחד עם ר מנחם סירירו, ר וידאל הצרפתי, היעב\"ץ, ועוד."},{"i":29275,"n":"מג'לד, יצחק מבגדד","f":"אברהם שלמה","k":"בעל לקוטי דינים","bt":"תקצה","bp":"בגדד","dt":"תרף - א אלול","b":"אחיו התאום של ר שמואל. למד בבית זילכה ואצל ר עבדאללה סומך. חכם באשי-תרנג. חיבר \"צלח רכב\", \"אלקים את יצחק\", \"תהלות ישראל\", ועוד. חתום על קבלת עדות עם הדיינים ר נסים חי הלוי ור אברהם יהושע."},{"i":29276,"n":"מגליד, צבי הירש","b":"רב בסנגרוד-תקפ\"ב"},{"i":29277,"n":"מגן אברהם - ישיבה בירושלים","b":"ישיבה בירושלים, נוסדה-תרעג בידי הגבירים ממשפחת אברהמוף, ור אברהם אמינוף. ראש הישיבה - ר אברהם חכם."},{"i":29278,"n":"מגן דוד - ישיבה בירושלים","b":"ישיבה בירושלים, נוסדה בידי דוד די פינטו מאמשטרדם-שנות ה-תק'."},{"i":29279,"n":"מגנאני, יוסף מטריפולי","bt":"תן","dt":"תקך - בערך","b":"סופר קהלת טריפולי, וחתם בפנקס בי\"ד טריפולי."},{"i":29280,"n":"מגנזן, ברוך","f":"דוד","k":"בעל גדולת מרדכי","b":"מחכמי אשכנז-שס. חיבר גם \"אגודת אזוב\"."},{"i":29281,"n":"מגנצא, בנימין מסובאלק","b":"מו\"ץ בסובאלק."},{"i":29282,"n":"מגנרי, פנחס מפדובה","b":"מחכמי פדובה. נזכר ב\"זכרון נשמות לפדובה\"."},{"i":29283,"n":"מג'ר - משפחה","b":"משפחה בירושלים - מוצאה אולי מהונגריה."},{"i":29284,"n":"מג'ר, אברהם מירושלים - א","f":"אליעזר משה","bp":"סופיה","dt":"תקס - כו אדר","dp":"ירושלים","b":"עלה לירושלים עם אביו, בשליחות ירושלים בטורקיה, נזכר בספר \"חסד לאברהם\" לר אברהם אלקלעי. הסכים על \"קול שמואל\" לר שמואל קונפורטי. (אצל רוזניס מופיע שעבר בדובניצה בשנת תקסד!)"},{"i":29285,"n":"מג'ר, אברהם מירושלים - ב","f":"דוד","dt":"תקצד - כח כסלו","dp":"ירושלים","b":"ראש ישיבת \"בית אל\" בירושלים על מקום ר אברהם שלום מזרחי שרעבי-תקפז, בספר \"שמש ומגן\" מתואר עליו. בין תלמידיו ר שאלתיאל ניניו, ר חיים דניאל פינסו בעל \"שם חדש\" ועוד. בניו - ר דוד בעל \"זהב שבא\"."},{"i":29286,"n":"מג'ר, אליהו מטבריה","b":"רב בטבריה, חתם-תקטו על כתב שליחות ר שמואל שלם, יחד עם ר יצחק אבולעפיה, ר יעקב בן חיים בירב ועוד מראשי הקהלה."},{"i":29287,"n":"מג'ר, אליעזר משה מירושלים","f":"יעקב","dt":"תקיב - כד סיון","dp":"ירושלים","b":"עלה מסופיה לירושלים. רב בירושלים. שלשת בניו ר יעקב, ר דוד ור אברהם - עסקו בקבלה."},{"i":29288,"n":"מג'ר, דוד ג'יליבון מירושלים -ב","f":"אליעזר משה","k":"בעל חסדי דוד","bp":"סופיה","dt":"תקס - כ אדר","dp":"ירושלים","b":"מחכמי ירושלים - \"בית אל\", היה עובר לפני התיבה אחר פטירת הרש\"ש, בזמנו של ר יום טוב אלגזי, בהשתדלותו הקדיש ר שם טוב ברוך מעשירי קושטא ישיבה וקרא לה קדושת יום טוב. חיבר ספר \"חסדי דוד\" ליוורנו תרג. בניו - ר אברהם על מקומו אחריו כש\"ץ, ר שמואל ראב\"ד, ר משה. חתנו - ר ראובן בן יעקב מסופיה העתיק את ספר חותנו בכת\"י וממנו העתיק ר יעקב שאלתיאל ניניו והדפיסו בליוורנו תקעא. (לפי רוזניס שם אביו ר שמואל, אחיו - ר יעקב ישראל מסופיה, חתניו - ר ראובן בן יעקב מסופיה וצפת, ר יחיאל יעקב אליקים מירושלים, ר משה גאגין. בניו - ר שמואל ור משה)."},{"i":29289,"n":"מג'ר, דוד מירושלים","f":"בכור שמואל","k":"בעל קורות משפחה","bp":"ירושלים","b":"מחכמי ירושלים, עבר לתל אביב-תרפט. חיבר גם \"שירי דוד\", ועוד."},{"i":29290,"n":"מג'ר, דוד מירושלים - א","b":"מחכמי ירושלים-תק\"כ. חותנו של ר משה גאגין. ראה גם: ר דוד בן אליעזר משה."},{"i":29291,"n":"מג'ר, דוד מירושלים - ג","f":"אברהם","k":"בעל זהב שבא","b":"מגדולי ירושלים-תר\"כ. חיבר \"זהב שבא\""},{"i":29292,"n":"מג'ר, דוד מירושלים - ד","f":"אברהם","dt":"תרא","dp":"ירושלים","b":"מחכמי ירושלים, בספר \"שמש ומגן\" מביא שני דרושים ממנו.."},{"i":29293,"n":"מג'ר, דוד מקושטא","b":"גביר בקושטא. הקדיש ישיבה בירושלים \"קדושת יום טוב\", בראשות ר יו\"ט ברוך."},{"i":29294,"n":"מג'ר, דוד משה מירושלים","f":"שמואל","b":"דיין בירושלים-תרי, חתם-תריט על שטר מכר."},{"i":29295,"n":"מג'ר, יהושע דוד מירושלים","b":"נכד ר דוד בעל \"חסדי דוד\". מחכמי ירושלים וחבר בית דינו של הראשון לציון ר יהודה נבון-תרד וחתם עמו על תעודת החצר העתיקה בחברון של ר חיים גדיליה."},{"i":29296,"n":"מג'ר, יעקב ישראל בכור מסופיה","f":"שמואל","k":"בעל חלק יעקב","dt":"תקסו","dp":"סופיה","b":"אב\"ד בסופיה-שנות ה-תק' בזמן רבנות ר ראובן בן יעקב ורב הכולל על מקומו אחריו-תקנה. חיבר \"חלק יעקב\" - קיצור פסקי התוספות - בכת\"י (שהיה בבית עקד ספרים בסופיה ונשרף-תרסה). אחיו - ר דוד."},{"i":29297,"n":"מג'ר, יעקב מירושלים","f":"אליעזר משה","dt":"תקלג - כ ניסן","dp":"ירושלים","b":"מחכמי ישיבת בית אל בירושלים-תקיח. אחיו - ר דוד."},{"i":29298,"n":"מג'ר, משה יעקב מירושלים","f":"דוד (או יעקב)","k":"בעל בני משה","b":"מחכמי ירושלים וטבריה, בשנת תקע חתם על תקנות ישיבת ייאני, בשליחות טבריה-תקעז, דיין בבית דינו של ר שלמה סוזין-תקפט, חתם אז על מינוי אפוטרופוס לנכדי ר אליעזר ירוחם-תקפט ובהם ר יעקב שאול אלישר (שנהיה לימים הראשון לציון).. חיבר \"בני משה\" בכתב יד. נספד מאת אחיינו ר יעקב ישראל מסופיה."},{"i":29299,"n":"מג'ר, שמואל מירושלים","f":"דוד","dt":"תרח - ו תמוז","dp":"ירושלים","b":"דיין בירושלים אצל ר אברהם חיים גאגין. בשליחות-תקסט עם ר מרדכי בעלול, אב\"ד אצל הרב אג\"ן. מראשי \"בית אל\", בשנת תקפז בשליחות בתונס. בשנת תקצט חתם על תזכיר לר משה מונטיפיורי, בשליחות-תקפז בתונס, בפאדובה-תרב. חתם על כתב שליחות ר זכריה זמירו. הסכים על \"מחנה לויה\", \"דברי שלום\"."},{"i":29300,"n":"מדאדסי, מסעוד ממרוקו","b":"מחכמי מרוקו, נזכר אצל היעב\"ץ."},{"i":29301,"n":"מדאר, אהרן","k":"בעל לב אהרן","bt":"תרלא","bp":"עדאן","dt":"תשכה","b":"עלה לא\"י-תרפ\"ד, חיבר \"לב אהרן\""},{"i":29302,"n":"מדווצקי, יהושע","bt":"תרטו","dt":"תרצה - כד אלול","b":"דומ\"צ בסטויבץ,ברנוביץ,עלה לא\"י תרצ\"ב"},{"i":29303,"n":"מדור ן, יוסף ממצרים","b":"רב במצרים בזמן ר שמואל ן סיד, והשתתף עמו ועם ר יעקב בירב, בדיון בענין עגונה."},{"i":29304,"n":"מדין, אברהם עוזיאל מציטוביאן","dt":"תש..","b":"רבה האחרון של ציטוביאן. נספה בשואה."},{"i":29305,"n":"מדינא די, אברהם מקושטא","b":"גביר מחכמי קושטא-שנות ה-תק'. אחיו - ר יצחק."},{"i":29306,"n":"מדינא די, יצחק מקושטא","b":"גביר מחכמי קושטא-שנות ה-תק'. אחיו - ר אברהם."},{"i":29307,"n":"מדינה די, אברהם ממצרים","dp":"ירושלים?","b":"רב בנא אמון(=אלכסנדריה)-תע, עלה לירושלים."},{"i":29308,"n":"מדינה די, אברהם ממצרים","b":"רב ברשיד(=רוזיתא)-מצרים-רפז."},{"i":29309,"n":"מדינה די, אברהם ממצרים","bp":"אדרינופול","b":"תלמיד ר שמואל פרימו. רב במצרים-תמ, בקי בחכמת ה\"זיירג'י\"-חיזוי עתידות. לדברי רוזניס נטה לשבתאות. פסקים ממנו ב\"כהונת עולם\", \"דרכי נעם\"."},{"i":29310,"n":"מדינה די, אליהו מאזמיר","dt":"תצג - א כסלו","dp":"אזמיר","b":"רב באזמיר-שנות ה-ת'."},{"i":29311,"n":"מדינה די, בנימין מאוילונה","b":"רב באוילונה-תן. אולי הוא שהיה רב במונסטיר."},{"i":29312,"n":"מדינה די, בנימין ממונשטיר","bp":"שלוניקי","b":"תלמיד ר דניאל אישטרושא. רב במונשטיר(=ביטולה)-שנות ה-ת', ותחתיו הדיינים ר משה די מאיו, ר יהודה קאסוטו, ר משלם הלוי."},{"i":29313,"n":"מדינה די, דוד ממצרים","b":"מגדולי דייני מצרים-תה. היה גם בארץ ישראל. תשובות ממנו ב\"דרכי נעם\", ועוד."},{"i":29314,"n":"מדינה די, דניאל משלוניקי","b":"מו\"צ בקהלת שלום בשלוניקי-תעה. מתורתו בספרי חכמי דורו - ר משה אמריליו, ר יצחק די בוזאלדו, ר יצחק ן חסון."},{"i":29315,"n":"מדינה די, יהודה קונפראדו משלונ","f":"משה","dt":"שעד - כא טבת","dp":"שלוניקי","b":"נכד מהרשד\"ם. דיין בשלוניקי. נהרג ע\"י גוי בשליחות יהודי (שכנראה הפסיד בדין) - והיהודים הצליחו להרוג את הרוצח. אחיו של ר שמעיה משלוניקי."},{"i":29316,"n":"מדינה די, יוסף משלוניקי","dt":"שעז - יד אלול","dp":"שלוניקי","b":"מהרוגי דולייא. מצאצאי מהרשד\"ם."},{"i":29317,"n":"מדינה די, מרדכי מקושטא","dt":"תפז - יד ניסן","dp":"קושטא","b":"גביר מחכמי קושטא."},{"i":29318,"n":"מדינה די, משה מקושטא וירושלים","f":"שלמה","b":"מחכמי ירושלים עלה מקושטא-שמ, בשנת שמז ובשנת תו חתם על תקנות בירושלים. נזכר בשו\"ת \"פני משה\" לר משה בנבנשתי. בנו - ר דוד בעל \"רוח דוד\". (אולי מדובר בשני רבנים באותו השם)"},{"i":29319,"n":"מדינה די, משה משלוניקי","f":"מהרשד\"ם","dt":"שסח - יח ניסן","dp":"שלוניקי","b":"דיין בשלוניקי, עשיר. הו\"ל ספר אביו שו\"ת מהרשד\"ם-שנו, הזמין את המדפיסים בני בת שבע מאיטליה להקים דפוס בשלוניקי. בניו ר יהודה שנרצח צעיר, ור שמעיה."},{"i":29320,"n":"מדינה די, שמעיה משלוניקי","dt":"תיג - ו תמוז","dp":"שלוניקי","b":"מחכמי שלוניקי."},{"i":29321,"n":"מדינה די, שמעיה משלוניקי - א","dt":"שעב - ט אב","dp":"שלוניקי","b":"מחכמי שלוניקי. אולי הוא נכד הרשד\"ם ואחיו של ר שלמה."},{"i":29322,"n":"מדינה די, שמעיה משלוניקי ונציה","f":"משה","k":"הו\"ל בן שמואל","bp":"שלוניקי","dt":"תח-תי - י סיון","dp":"ונציה","b":"נכד מהרשד\"ם. מחכמי שלוניקי, תלמיד ר שמואל חיון. עבר לונציה לאחר הריגת אחיו ר יהודה עק\"ה, וחתם עם שאר הרבנים על הסכמות שונות-שפח, חתם ראשון בשנים שצ-שצג. רב, מקובל, דרשן ומלמד בישיבה, מתלמידיו ר יעקב פראנסיס המזכירו בשירו. הו\"ל בונציה \"בן שמואל\" לזקנו עם שירים והקדמה ממנו - ומספר שם על קורותיו ושהוכרח לעזוב את שלוניקי ולעבור לאיטליה. חברו של ר עזריה פיגו. חיבר פיוטים רבים, מסדר \"אשמורת הבוקר\" ונציה, חיבר פירוש על משלי ומזכיר בו את ר יוסף סאמיג'ה, ונזכר אצל די רוסי. תשובה ממנו ב\"המאור\" - תל אביב תרצה. בניו ר משה ור שמואל."},{"i":29323,"n":"מדינה, אליה"},{"i":29324,"n":"מדינה, יוסף מקאסטוריה","b":"רב בקאסטוריה(=קאשטוריאה)-שנות ה-ת' בזמן ר מנחם רוסו."},{"i":29325,"n":"מדינה, יצחק חיים מאיטליה","k":"בעל סדר זמירות ולימו","b":"רב בסיינה, חיבר סדר זמירות ולימוד לחנוכת בית הכנסת בסיינה-ליוורנו תקמו, יחד עם ר ידידיה הלוי בן רפאל שלמה.."},{"i":29326,"n":"מדינה, יצחק מלוב","b":"רב בכפר ג'בל-יפרן-לוב, ונזכר אצל הנוסע ישראל בנימין ב\"מסעי ישראל\" ליק 1859 - בשם \"מעדינא\" (נ' סלושץ כתב ב\"רשומות\"-תרפו ששם משפחתו מעדוזא)."},{"i":29327,"n":"מדינה, ישראל ממצרים","b":"מחכמי מצרים בזמן ר מאיר גאביזון ונזכר בשות מהרם גאביזון."},{"i":29328,"n":"מדינה, משה מקושטא וירושלים","b":"מחכמי קושטא, עלה לירושלים, וכיהן כדיין-תז. חתם בהסכמת המסים-תז."},{"i":29329,"n":"מדיני, אברהם יצחק ממנטובה","b":"רבו של בעל \"עדן ערוך\". נספד ע\"י בעל \"פחד יצחק\"."},{"i":29330,"n":"מדיני, משה מפאס","f":"מרדכי","b":"מחכמי פאס, חתם-רפו בענין הנפיחה."},{"i":29331,"n":"מדיני, נסים שמואל מקושטא וחברו","f":"רפאל אליהו","b":"מחכמי חברון. תלמיד ר יצחק קובו. אחיו של ר חזקיה בעל \"שדי חמד\". מחדושיו ב\"מלאכת שלמה\" לר\"ש קמחי ועוד, וכן נזכר בספרי אחיו."},{"i":29332,"n":"מדיני, רפאל אשר אליהו מירושלים","bt":"תקסה","bp":"ירושלים","dt":"תריג","dp":"בגדד","b":"למד בילדותו אצל חכמי קושטא. מחכמי ירושלים. בשליחות הקהלה בערב, בקושטא-תקצח, נפטר בדרכו לבגדד. בניו: בעל ה\"שדי חמד\", ור נסים שמואל שהיה רב בקושטא."},{"i":29333,"n":"מדיני, שמואל מאלגיר","f":"סעדיה","bt":"קך","dt":"קץ - בערך","b":"מחכמי מסתגאנם. שאלה ממנו לריב\"ש בשו\"ת הריב\"ש, ולרשב\"ץ."},{"i":29334,"n":"מדיני, שמעון מחברון","f":"חזקיה","bt":"תרכא","bp":"חברון","b":"רב בחברון-תרסה על מקום אביו."},{"i":29335,"n":"מדליה, הלל מאנגליה","f":"שמריהו יהודה","b":"רב בלידס-אנגליה."},{"i":29336,"n":"מדליה, מאיר","b":"רב-שנת תר\"נ"},{"i":29337,"n":"מדליה, שמריהו יהודה ליב מויטבס","f":"יעקב אידיל","dt":"תרצח","b":"רב בטולא, קרלביץ, ויטבסק-תרסה. פעל גם כעסקן ציבורי לצד הרש\"ב מלובאביץ ור חיים מבריסק, היה ציר פלך ויטבסק יחד עם ה\"אור שמח\" בפטרבורג-תרע, השתתף בועידת קטוביץ-תרעב של אגודת ישראל. נאסר ע\"י הקומוניסטים-תרצח ונהרג עק\"ה, למרות הנסיונות להצילו. לזכרו ספר זכרון \"שילה\" ירושלים תשמד."},{"i":29338,"n":"מדלסהיים, נפתלי הרץ","k":"מערף בער","bt":"תץ","bp":"בישא-אלזאס","dt":"תקנג","b":"גביר בבישא-אלזאס, שטרסבורג (בזמן שהיתה אסורה למגורי יהודים), מקורב למלך, סייע ליהודים, הו\"ל ספרים ובהם \"לחם סתרים\" לר שלמה אלגזי, היה בקשר עם מנדלסון ובאמצעותו עם החכם הנוצרי דאהם - שחיבר עבורו ספר אודות מעמד היהודים ושאותו הפיץ בין גדולי צרפת. שיר וחוברת לכבודו מאת ר אברהם אוירבך מבישא ונייויט. שיר לכבודו גם מאת נפתלי הרץ ויזל. נרדף בזמן המהפכה הצרפתית. גיסו - ר יוסף דוד זינצהיים בעל \"יד דוד\"."},{"i":29339,"n":"מדן, בן ציון מגלוגוב","dt":"תש..","b":"רב בגלוגוב. נספה בשואה."},{"i":29340,"n":"מדניק, דוד מנ\"י","b":"תלמיד ישיבת \"רבי יצחק אלחנן\". פרסם מאמרים ב\"הדנו\" - נ\"י תרפה."},{"i":29341,"n":"מדניק, חיים מפוהוסט וארה\"ב","f":"שמואל","k":"בעל מזכרת חיים","bt":"תרלז","dt":"תשטו - ו טבת","b":"רב במדוודיץ-תרסט, פוהוסט-ליד סלוצק-תרעז, שיקגו-תרפה. פרסם מאמר ב\"אהל יוסף\" - נ\"י תשו, \"כנסת ישראל\" - נ\"י תרצב - כתב עת הסתדרות תלמידי סלובודקה באמריקה, \"כרם ציון\" - ירושלים תרצה-תשיג - קובץ \"מדרש בני ציון\", \"שערי אורה\" - מיהאלביץ תרץ-תרצד, \"שערי ציון\" - ירושלים תרפא. חיבר \"מזכרת חיים\" ירושלים תשכב."},{"i":29342,"n":"מדפיס, אברהם יוסף מלמברג","f":"אהרן","bt":"תקן","dt":"תרל","b":"מדפיס בלמברג-תרח במשך כששים שנה."},{"i":29343,"n":"מדפיסי דפוס ראם וילנא ה'תרלה","bk":[["עיקר שפתי חכמים",""]]},{"i":29344,"n":"מדר, בן ציון מגלוגוב","f":"יצחק אריה","b":"תלמיד רד\"ב מטשבין. חתן רמ\"מ רובין מקולבסוב."},{"i":29345,"n":"מדרש, יוסף מירושלים","b":"מחכמי ירושלים-רפד, ומלמד לנערים. נזכר במכתב ר ישראל מפירושא."},{"i":29346,"n":"מה יפית, אפרים ניסן מדאוג","dt":"תשג","b":"רבה של דאוג על מקום ר אברהם צבי כץ, ור נחום שר על מקומו אחריו. רב בפאנימון."},{"i":29347,"n":"מה יפית, ישראל אברהם","f":"אפרים ניסן","k":"בעל אין בלוט און גיפ","bt":"1897","bp":"שאדובה","dt":"1930","b":"אביו היה רב בדאוג. בגיל בר מצוה היה בקי ב-700 דפי גמרא, תלמיד ר פולאצ'יק בישיבת לידא. למד מדעים ושפות. חיבר שירים. תרגם לאידיש שירי עם, ועוד. מזכירו של ר חיים עוזר גרודזנסקי בוילנא, עבר לקובנא. חיבר ספרים ומאמרים רבים."},{"i":29348,"n":"מה יפית, נפתלי הרץ מפרייל","b":"רב בפרייל-ליטא. בנו ר צבי הירש מאיישישוק."},{"i":29349,"n":"מה יפית, צבי הירש מאיישישוק","f":"נפתלי הרץ מפרייל","bt":"תר","bp":"פרייל","dt":"תרעט","dp":"ליפצק","b":"רב בליוונהוף-בהיותו בן 17, רב באיישישוק ועמד בראש הישיבה שם, לאחר שריפת איישישוק עבר לכהן כרב בוילקוביסק, בזמן מלחה\"ע ה-I גלה לליפצק-פלך טומשוב. השתתף בועידת רבני רוסיה-תרעא בוארשא. חתנו - ר ר יהושע מרדכי קלצקין מרסיין."},{"i":29350,"n":"מהאגר, יוסף מספרד","f":"מאיר","b":"פייטן מחכמי ספרד. פיוטים שלו במחזור טריפולי."},{"i":29351,"n":"מהאדומים, בנימין שאול מפיררה","b":"מוזכר ב\"שלטי הגבורים\" שהיה מסדר המזמורים והקריאות בביהכ\"נ איטליאני וכך נוהגים בפיררה."},{"i":29352,"n":"מהאדומים, יעקב אלישע","dt":"תקפט - כג תמוז","b":"משורר ודרשן בפיררה, פיסארו."},{"i":29353,"n":"מהאדומים, יצחק ברכיה","f":"הרמ\"ע מפאנו","b":"מחכמי איטליה."},{"i":29354,"n":"מהאדומים, משה ממודנא","b":"מחכמי מודנא, עלה לצפת בשנת רצה. גיסו של ר יעקב ברוך - שנקבר בצידון."},{"i":29355,"n":"מהאדומים, עזריה מפאנו","k":"בעל מאור עינים","bt":"רעד","bp":"מנטובה","dt":"שלט - יג כסלו","dp":"מנטובה","b":"גדול בתורה,חכמה ומדעים,מחכמי איטליה בבולוניה,אנקונה,פירארה"},{"i":29356,"n":"מהדאד, מסיעד מג'רבה","k":"בעל מסעד לבית ה'","bt":"תרפח","bp":"ג'רבא","dt":"תשיט - אלול","b":"רב בג'רבא, ושימש כפוסק בעניני טהרת המשפחה."},{"i":29357,"n":"מהדון, לוי מחידאן-תימן","f":"סעדיה","dt":"תשה - אחרי","b":"דיין בחידאן, עלה לארץ והתישב בשעריים, וכיהן כדיין-תרפט."},{"i":29358,"n":"מהודר, אברהם מבלז","f":"יעקב הלוי מאדער","k":"בעל זכרון אברהם","bt":"תרנב","bp":"בלז","dt":"תשלג","b":"חתן ר שלמה ישראל רמרז מליביטשוב. מחכמי ליביטשוב. עלה לירושלים-תרצג ושינה שמו למהודר, רב ביפו-תשח. חיבר \"זכרון אברהם\" ירושלים תשא."},{"i":29359,"n":"מהודר, אברהם מירושלים","dt":"תרסט - יא אדר","b":"רב בירושלים"},{"i":29360,"n":"מהודר, אברהם מירושלים","dt":"תקסה - יא אד\"א","dp":"ירושלים","b":"בשנת תקמא חתום על מכתב קהילת ירושלים, בשנת תקמט חתום על אגרת שליחות ר אברהם אזולאי. יתכן והוא \"הפקיד הר\"א מהודאר\" המופיע בספר התקנות בתקנת ירושלים."},{"i":29361,"n":"מהודר, אליהו יום טוב צמח","dt":"תרכג - ט אייר","dp":"ירושלים","b":"רב בירושלים. בשנת תרב חתם על מכתב רבני ירושלים עם ר יהודה נבון, בשנת תריד חתם על כתב שליחות ר נסים ברוך, ועוד. נספד בספר \"שמש ומגן\" דקל\"ד"},{"i":29362,"n":"מהודר, חיים","b":"שד\"ר ירושלים-תרנ\"א,מנהל ישיבת \"חסד לאברהם\" בירושלים-תר\"ע"},{"i":29363,"n":"מהודר, חיים יוסף","b":"מגדולי חכמי ירושלים-תרי\"ט"},{"i":29364,"n":"מהודר, יהושע שמואל מירושלים","dt":"תקצו - אחרי","dp":"ירושלים?","b":"מחכמי ירושלים-תקסז, חתם-תקצו על כתב מינוי ר יונה נבון, יחד עם ר בן ציון אברהם, ר חי בנימין זגביב, ר יוסף ן וינישתי, ר יעקב נסים רוסו, ר יצחק קאשטל, ר ישראל יהודה שולם, ר נסים שמריה ירושלמי, ר סעדיה ן בינישתי, ר שמואל בכר עזריאל, ר רפאל אברהם ישראל הלוי, ר רפאל אליעזר פראנקו, ר שמואל אשכנזי."},{"i":29365,"n":"מהודר, יצחק סעדיה מירושלים","dt":"תרכו - כג אייר","dp":"ירושלים","b":"מחכמי ירושלים."},{"i":29366,"n":"מהודר, רחמים מלוב","bt":"תרנד","dt":"תשלו","b":"דיין בבנגאזי, וסגן הרב-תש, רב ראשי-תשי על מקום ר יוסף ג'יאן שעלה לארץ, עזב את בנגאזי-תשכז, עלה לארץ-תשלד."},{"i":29367,"n":"מהודר, רפאל מיפו","bt":"תרמח","bp":"יפו","dt":"תרפד - כב אב","dp":"יפו","b":"רוקח ביפו, חבר באספת הנבחרים, פעיל ציבור."},{"i":29368,"n":"מהודר, רפאל משה","dt":"תרלט - כט חשון","b":"מרביץ תורה בירושלים"},{"i":29369,"n":"מהזקנים, אברהם ממנטובה","f":"שבתי","k":"דיל ויקייו","b":"רב במנטובה-שע\"ה. חיבר פירוש על הכתובה - בכת\"י. מתורתו בספר \"דבר שמואל\". ואולי הוא מחבר \"זרע אברהם\" (כת\"י - מופיע בסדר הדורות)."},{"i":29370,"n":"מהזקנים, שבתי אלחנן","b":"רב בליוורנו, אנקונה, מארקא, קסאלי-תצט, מונפיראטי. רבו של ר שלמה דוד מהזקנים מלוגו. חברו של ר יצחק למפרונטי. תשובותיו ב\"פחד יצחק\", \"שמש צדקה\" ועוד."},{"i":29371,"n":"מהזקנים, שלמה דוד מלוגו - א","f":"משה","b":"רב בלוגו-תעו. תשובה ממנו ב\"שמש צדקה\"."},{"i":29372,"n":"מהזקנים, שלמה דוד מלויקיו-לוגו","b":"רב בלוגו-תקכא. הסכים על \"יכין ובועז\" ליוורנו תקמב, \"אשל אברהם\" ליוורנו תקפט. חיבר נוסח תפלות למגפה עם ר מנחם עזריה מפאנו (בשנת תקכו)."},{"i":29373,"n":"מהזקנים, שמואל מאיטליה","k":"בעל לקוטי אורות","b":"מגדולי חכמי איטליה, רב בפירארה-של\"ד. ?? לא באוצר ??"},{"i":29374,"n":"מהחזנים, חיים משה כהן מפדובה","f":"יצחק מן החזנים","k":"בעל מראה הסנה","bt":"תכ","b":"נכד ר יצחק חיים כץ בעל \"פחד יצחק\", אחיינו של ר יצחק חיים מן החזנים.. רב ורופא בפדובה, ריוויגו. חיבר \"מראה הסנה\" בכת\"י עם שיר מדודו, ועוד."},{"i":29375,"n":"מהחזנים, יהודה קנטריני מפדובה","f":"שמואל","bt":"שנה","dt":"תיא","b":"רב רופא ופילוסוף בונציה ופדובה. נכדו - הרב יחכ\"ם - כותב עליו ב\"פחד יצחק\" ו\"לב חכם\"."},{"i":29376,"n":"מהחזנים, יצחק חיים מפדובה","f":"הכהן","k":"יחכ\"ם - בעל פחד יצחק","bt":"תד","dt":"תפג - ו סיון","b":"רב דרשן ורופא בפדובה. תלמיד ר שלמה ממריני בעל \"תיקון עולם\" ור משה קטאלאנו ור יהודה קציגין ור אברהם רומנין. מגדולי דורו. יצא נגד נחמיה חייא חיון בספר \"מלחמה לה'\". חיבר \"פחד יצחק\" לקורות קהילת פדובה, \"עת קץ\", \"פי ספרים\", ועוד גם בכת\"י. מתלמידיו - ר שבתי חיים מאריני, הרמח\"ל, ר שמריה קוניאן. בנה את ביהכ\"ס אשכנזים בפדובה עם ר שמעון אלפרון ור שמואל אופנהים ור מרדכי ק\"פ - כמופיע בשיר שכתב ר דוד אוטולינגו לחנוכת ביהכנ\"ס. קינה עליו מר יצחק פאציפיקו. פרסם מאמרים ב\"ראשית בכורי קציר\" - ונציה-פיררה תעה. (בגירונדי רשום תאריך פטירתו גם - ה סיון תקיג)."},{"i":29377,"n":"מהחזנים, עזריאל הכהן מפדובה","b":"רב בישיבת \"לקח טוב\" בפדובה. נזכר בספר \"זכרון נשמות לגאוני עירנו\" (פדובה)."},{"i":29378,"n":"מהחזנים, קלונימוס מפדובה","f":"שמואל","dt":"שצב - ב אב","b":"רב ורופא בפדובה. אחיינו של ר יהודה כץ. זקנו של הרב יחכ\"ם."},{"i":29379,"n":"מהחזנים, שמואל הכהן מפדובה","bt":"שכא","bp":"פדובה","dt":"שצא","b":"רב ופרנס בפדובה, אחיו של ר יהודה מהחזנים, ודודו של הרב יחכ\"ם."},{"i":29380,"n":"מהטוב, אליה דניאל מצינטו","k":"אד\"ם","b":"מחכמי צינטו-תכט - בזמן ר פלטיה מונסיליסי ור יהודה חיים ריקנטי. מובאים תשובות ממנו ב\"פחד יצחק\"."},{"i":29381,"n":"מהטוב, אליעזר דוד מפיררה","f":"יצחק","k":"אד\"ם - בעל עיר דוד","bp":"מנטובה","dt":"שצא","b":"ראש ישיבה במנטובה, ראש ישיבה בפירארה-שנח - בזמן ר חזקיה פינצי. פילוסוף, חיבר \"עיר דוד\". חיבר \"עיר דוד\". בנו בעל \"כסאות לבית דוד\"."},{"i":29382,"n":"מהטוב, יהודה עשהאל מאיטליה","f":"אליעזר דוד","k":"בעל כסאות לבית דוד","b":"מחכמי ורבני אורבינו-מזרח איטליה, רב באנקונה-תיד, פיררה-תכה, אורבינו-תל. חיבר \"כסאות לבית דוד\" - וירונה תו, \"יהודה מחוקק\". נדפסו הרבה משיריו."},{"i":29383,"n":"מהטוב, פלטיה מפיררה","f":"דוד","b":"רב בפיררה. תשובה ממנו ב\"באר עשק\" לאביו."},{"i":29384,"n":"מהכהנים, נחמיה","b":"מגדולי חכמי איטליה,מרביץ תורה בפירארה-תע\"ה"},{"i":29385,"n":"מהל\"א, משה","b":"מגדולי חכמי אשכנז-ר\"כ"},{"i":29386,"n":"מהלויים, יצחק","f":"יעקב","k":"ימ\"ה =יצחק מן הלויים","b":"רב בונציה, עם הרמ\"ז ור ישעיה ניצה ור ברוך לוצאטו. חתן ר יהודה אריה מודנא. חיבר קיצור הפרד\"ס לרמ\"ק בכת\"י. חיבר שירים שנדפסו ובכת\"י. חיבר \"מדבר תהפוכות\" בכת\"י, \"מעשי חכמים\". (היה במחלוקת עם ר שלמה פורטו, ר יהודה ויטירבו, ר רפאל פיקיוטי, ר יהושע סיצה, ר אברהם מונציליסי ועוד)."},{"i":29387,"n":"מהלויים, יצחק","b":"נכד ר יהודה אריה ממודנא. חתם ב\"דבר שמואל\" אודות נתן העזתי. חיבר דרוש לשבת הגדול, וחיבר שירים - חלקם בדפוס."},{"i":29388,"n":"מהלל העדני","bt":"1883","dt":"ה'תשי 1950","bk":[["אור החוזר",""]]},{"i":29389,"n":"מהמה, אברהם מטריפולי","dt":"תסא","b":"רב, ומשורר בטריפולי."},{"i":29390,"n":"מהענוים, אברהם מרומא","b":"רב ברומא-שנת ה'כ'"},{"i":29391,"n":"מהענוים, בנימין מרומא","f":"אברהם הרופא","k":"בעל שערי עץ חיים","b":"פייטן ובקי במדעים מחכמי איטליה אולי רומא. חיבר גם \"ידידות\", פירוש התפלות, כללי חשבונות העיבור, ועוד. אחיו של ר צדקיה בעל \"שבלי הלקט\". חיבר פיוטים ובהם על לקיחת ספרי התלמוד \"אבות עולם אמת אולם\"."},{"i":29392,"n":"מהענוים, יהודה מרומא","f":"בנימין","k":"ריבב\"ן-ר'יהודה הרופא","bt":"ד'תתקעה","b":"מגדולי הראשונים בחכמי איטליה, פוסק, מרביץ תורה ברומא. מתלמידיו - בן דודו - ר צדקיה בעל \"שבלי הלקט\" המזכירו בספרו. חיבר פירוש להלכות הרי\"ף."},{"i":29393,"n":"מהענוים, יחיאל מרומא","f":"יקותיאל בן בנימין","k":"בעל מעלות המדות","b":"מגדולי חכמי רומא הקדמונים-ה'קח. אולי הוא הפייטן שחיבר קינה על שרפת ביה\"כ הגדול ברומא-יז אלול ה'קח."},{"i":29394,"n":"מהענוים, ישעיה מגינשבורג","b":"השיב בענין המקוה ברוויגו."},{"i":29395,"n":"מהענוים, פנחס חי מפיררה","k":"בעל גבעת פנחס","bt":"תנב","dt":"תקכט","b":"מגדולי חכמי איטליה, רב בפירארה-תק\"י. תלמיד ר יצחק למפרונטי. חתנו של ר\"י צהלון, וגיסו של ר יעקב דניאל אולמו. היה אחד משלשה תלמידים שבחר רבו - לבחון את השליח ר אברהם יצחקי - בבואו בשליחות - ונסמך ממנו. חיבר \"גבעת פנחס\". מתשובותיו ב\"פחד יצחק\" לרבו. מאמר ממנו ב\"ראשית בכורי קציר\" - ונציה-פיררה תעה."},{"i":29396,"n":"מהענוים, צדקיה","f":"אברהם הרופא","k":"בעל שבלי הלקט","b":"מגדולי הפוסקים הראשונים,מחכמי איטליה-שנת כ'"},{"i":29397,"n":"מהריל, אהרן שלמה","f":"כתריאל","k":"בעל טועמיה חיים זכו","bp":"זאגר (ליטא)","dt":"תרצט - חשון","dp":"ירושלים","b":"עלה לירושלים בשנת תרסט (או תרסו), תלמיד חבר לבעל ה\"לשם,\" ונודע כאחד מגדולי המקובלים, ראש ישיבת שער השמים, חיבר ספר \"טועמיה זכו\" ירושלים תרפד, \"מנחה לה\" ירושלים תרעד, ועוד"},{"i":29398,"n":"מהרם, מאיר מרדכי מפילדלפיה","b":"רב בפילדלפיה. פרסם מאמרים ב\"בית ועד לחכמים\" - נ\"י תרסג."},{"i":29399,"n":"מהרם, שלמה חנוך הניך מדוינסק","f":"משה יהודה","bt":"תרלט","b":"תלמיד ישיבות סלובודקה, סלוצק (היה מ-14 התלמידים שהביא עמו ר איסר זלמן מלצר - כשהקים את הישיבה). רב בקאוונאט-פלך ויטבסק-תרסא, אפאצק-פלך פסקוב. נסמך מאת: ר מאיר שמחה בעל \"אור שמח\", ר יוסף רוזין-הרוגצובר. פרסם מאמרים ב\"תורה מציון\" - ירושלים תרנה-תרסה. הניח שו\"ת וחדושים על הש\"ס - בכת\"י."},{"i":29400,"n":"מהרשוב, אליעזר גדליה","b":"ר\"מ בהומל"},{"i":29401,"n":"מהתפוחים, דוד דה פומיס","f":"יצחק","k":"בעל צמח דוד","bt":"רפה","bp":"ספוליטה-איטליה","dt":"שנג","b":"למד רפואה ופילוסופיה אצל דודו - הרופא ר יחיאל מיכל רחביה אלטינו, ובפירושה. רופא במגליאנו-שיב, ולאחר הגירוש-שטו נדד במקומות שונים ולבסוף התישב ליד ונציה. רופא, חוקר, ובלשן בן למשפחה עתיקה באיטליה (גרו בספוליטי בגליל אומבריאה) - ממשפחת ר נתן בעל הערוך. חיבר \"צמח דוד\" - ונציה. נדד בכל רחבי איטליה וקורות חייו ונדודיו בהקדמת ספרו."},{"i":29402,"n":"מהתפוחים, נתן","f":"יחיאל מרומא","k":"בעל הערוך","bt":"ד'תצה","dt":"ד'תתסו","b":"ממשפחת התפוחים,משבט יהודה,מגדולי הראשונים,מרביץ תורה ברומא"},{"i":29403,"n":"מובחר ן, יוסף משלוניקי","dt":"שמו","b":"משורר, מחכמי קושטא, עבר לשלוניקי, היה גם בברושה ושם חיבר ר ישראל נג'ארה שיר לכבודו."},{"i":29404,"n":"מובחר ן, שלמה מקושטא","b":"משורר ורב בקושטא-שנות ה-ש'. נזכר אצל ר חיים שבתי, ואצל ר יוסף טרני, משיריו ב\"אהבת עולם\" ו\"זהב שבא\" לר שלמה אלגזי. מגיה בדפוס אברהם פרנקו בקושטא."},{"i":29405,"n":"מובחר ן, שלמה משלוניקי","b":"מגדולי רבני שאלוניקי-ש\"כ"},{"i":29406,"n":"מובשה, בנימין מבירז וקראקינובה","dt":"תשא - כו אב","b":"רב בבירז-תרצב וראש הישיבה שם, רבה האחרון של קראקינובה(=קרקאנאווע). נספה בשואה."},{"i":29407,"n":"מובשוביץ, בנימין","bt":"תרמז","dt":"תשיג - ג כסלו","b":"רב בהרצליה"},{"i":29408,"n":"מובשוביץ, דניאל הלוי","f":"מרדכי שלמה מובשוביץ","bt":"תרנט","dt":"תשלד - יח אייר","b":"רב בזורעביץ,מרבני תל אביב-ת\"ש"},{"i":29409,"n":"מובשוביץ, דניאל מקלם","bt":"תרמז","bp":"שידרא-פלך גרודנא","dt":"תשא - כז אלול","dp":"קלם","b":"אביו היה רבה של שידרא. תלמיד ישיבות סלובודקה, קלם. חתן ר נחום זאב זיו, וגיסו של ר אליהו דסלר. התפרסם כאחד מבעלי המוסר. ראש התלמוד תורה בקלם. כל אנשי עירו התיחסו אליו ביראת כבוד ולפעמים גם ה\"גויות\" שראוהו ברחוב היו נופלות על ברכיהן בדמותן שהנוצרי הופיע בפניהן. נספה בשואה עם תלמידיו."},{"i":29410,"n":"מובשוביץ, חיים אליהו","dt":"תשג","b":"רב בקוזלוב-רודא"},{"i":29411,"n":"מובשוביץ, יעקב מברסטוביץ","dt":"תשג","b":"רב בברסטוביץ"},{"i":29412,"n":"מובשוביץ, מרדכי שלמה מקניזיץ","f":"נח","bt":"תרכב","b":"רב בקניזין(=קניזיץ)-פלך מוהילוב-תרמט, זורביץ-פלך מוהילוב-תרנב, מלסטובקה(=מאלאסטווקא)-פלך מוהילוב-תרסב."},{"i":29413,"n":"מובשוביץ, משה גרשון","f":"בנימין","bt":"תרטו","bp":"דובראווא","dt":"תרצג - כג חשון","b":"חתן ר חיים שמחה משטאבין. רב בשידרה(=שידרא)-פלך גרודנא-תרן, דוברובה(=דובראווא). נסמך מאת: ר יצחק אלחנן מקובנא, ר יצחק מאיר מסלובודקא."},{"i":29414,"n":"מובשוביץ, משה מקשטיוקוביץ","f":"נח הלוי","bt":"תרלו","b":"רב בקאשטיוקאויץ-פלך מוהילוב-תרנו."},{"i":29415,"n":"מובשוביץ, נח סגל","b":"רב-שנת תר\"ס"},{"i":29416,"n":"מוג'אג'ון, אליהו מסרייבו","dt":"ת - אחרי","dp":"סרייבו","b":"רב בסרייבו."},{"i":29417,"n":"מוג'אג'ון, אליהו משלוניקי","dp":"צפת","b":"מחכמי שלוניקי, סרייבו, עלה לצפת. אחיו של ר מצליח."},{"i":29418,"n":"מוג'אג'ון, משה מפטרץ","f":"מצליח","dt":"שץ","dp":"ונציה","b":"עבר לונציה. חתם עם חכמי ונציה-שע על הגזירה שלא להוציא שם רע על ר ידידיה גלנטי."},{"i":29419,"n":"מוגדן, דוד","k":"בעל מגן דוד","bt":"תקיח","dt":"תקפח - כט אב","b":"ראב\"ד בקמפנא-תקל\"ח"},{"i":29420,"n":"מוגרבי, דוד ממצרים","b":"סופר סת\"ם מחכמי מצרים, ,גידם בידיו, חיגר ברגליו, וכתב ספרי תורה בפיו (הרמ\"ע פקפק בכשרותם) - ונזכר בבאר היטב על השו\"ע."},{"i":29421,"n":"מוגרבי, מנחם ממצרים","b":"מחכמי מצרים-סוף שנות ה-ש', וסופר סת\"ם למרות שהיה גדם וחיגר."},{"i":29422,"n":"מודון, שמשון הכהן מאיטליה - א","f":"יחיאל","b":"רב במנטובה-שץ."},{"i":29423,"n":"מודון, שמשון הכהן ממנטובה - ב","f":"יעקב שמשון","k":"בעל קול מוסר","bt":"תלט","bp":"מנטובה","dt":"תפז","dp":"מנטובה","b":"משורר מחמכי מנטובה, תלמיד ר יהודה בריאל ממנטובה, סופר הקהלה-תקפב, דיין במנטובה וחתם על תעודות רבות. חיבר גם \"ציר הצירים\", \"קול מוסר\" ועוד."},{"i":29424,"n":"מודיאנו, דוד משה משלוניקי","k":"בעל רוח דוד","b":"רב בשלוניקי-שנות ה-תק'."},{"i":29425,"n":"מודיל, דוד מפלוישט","bt":"תקצג","dt":"תרכח","b":"רב בפלוישט(=פלאיעשט)-רומניה ויסד שם תלמוד תורה וחברת ביקור חולים, רב ראשי בבוקרשט."},{"i":29426,"n":"מודיליאנו, אהרן מסופיה","b":"מחכמי שלוניקי, שו\"ב ומלמד בסופיה-תל."},{"i":29427,"n":"מודיליאנו, אליאס ביג משלוניקי","dt":"תרפה","dp":"קושטא","b":"רופא צבאי בשלוניקי."},{"i":29428,"n":"מודיליאנו, בנימין משלוניקי","f":"יצחק שמואל","dt":"שצה - כד אייר","dp":"שלוניקי","b":"גביר מחכמי שלוניקי."},{"i":29429,"n":"מודיליאנו, יהודה שאול משלוניקי","bt":"תקסח","dt":"תרמח","dp":"שלוניקי","b":"גביר בשלוניקי, ואחד משבעת טובי העיר."},{"i":29430,"n":"מודיליאנו, יהושע משלוניקי","f":"שאול","dt":"תריג","dp":"שלוניקי","b":"מחכמי שלוניקי."},{"i":29431,"n":"מודיליאנו, יום טוב משלוניקי","f":"שמואל","b":"מחכמי שלוניקי-שנות ה-ת'. עסק בהדפסת ספרי אביו."},{"i":29432,"n":"מודיליאנו, יוסף משה משלוניקי","dt":"תקלה","dp":"שלוניקי","b":"גביר בשלוניקי."},{"i":29433,"n":"מודיליאנו, יוסף משלוניקי","f":"יצחק","b":"מחכמי שלוניקי, אחיו של ר שמואל בעל \"נאמן שמואל\". בניו - משה, שמואל, אברהם, ר בונומו. עסקו בהדפסת ספרי אחיו-דודם - ר שמואל."},{"i":29434,"n":"מודיליאנו, יוסף שמואל משלוניקי","f":"שמואל יוסף","k":"בעל ראש משביר","bt":"תעד","dt":"תקמא - כו אב","dp":"שלוניקי","b":"תלמיד ר משה אמריליו. רב וראש ישיבת קהלת \"איטליה ישן\" בשלוניקי-תק, והתיר לבני הקהלה בשלוניקי לנהוג כמנהגם (להאכיל ציפורים שהחזיקו בביתם בשבת, לצייר את בני המשפחה, ועוד). פעל לשיקום הקהלה לאחר השריפה-תקיט. סבל מהלשנה של הגביר יצחק שלום ונאלץ לברוח לשירון, ובעזרת קשריו עם קונסול זר הצליח לחזור לשלוניקי. הו\"ל \"מזבח אדמה\" ו\"הון רב\" לקרובו ר יצחק שמואל מודיליאנו - עם הקדמות ממנו, ועוד. נספה במגפה-תקמא. מבניו: ר ישעיה, ר יעקב-הדיין."},{"i":29435,"n":"מודיליאנו, יוסף שמואל משלוניקי","b":"מחכמי שלוניקי-תקעב. הגיה את \"מחזיק ברכה\" לחיד\"א, יחד עם ר יצחק מולכו."},{"i":29436,"n":"מודיליאנו, יעקב יוסף משלוניקי","f":"יוסף","dt":"תרנא","dp":"שלוניקי"},{"i":29437,"n":"מודיליאנו, יעקב משלוניקי","f":"שמואל יצחק","dt":"תץ","dp":"שלוניקי","b":"מחכמי שלוניקי."},{"i":29438,"n":"מודיליאנו, יעקב משלוניקי","f":"יוסף שמואל-ראש משביר","dt":"תקעח","dp":"שלוניקי","b":"דיין בשלוניקי. מתשובותיו בספר אביו \"ראש משביר\"-תקפא, ובספרי חכמי דורו."},{"i":29439,"n":"מודיליאנו, יצחק יהודה משלוניקי","b":"גביר מראשי קהלת שלוניקי-תרלח."},{"i":29440,"n":"מודיליאנו, יצחק יהושע משלוניקי","b":"גביר בשלוניקי, ונמנה על שבעת טובי העיר-תריז."},{"i":29441,"n":"מודיליאנו, יצחק מרדכי משלוניקי","dt":"תקנ - בערך","dp":"שלוניקי","b":"מחכמי שלוניקי. תמך בשד\"ר ר חיים יהודה נבון."},{"i":29442,"n":"מודיליאנו, יצחק שמואל בכור משל","f":"שמואל","b":"גביר בשלוניקי-שנות ה-תק'. אירח את ר אברהם שמואל מיוחס מירושלים. סייע בהדפסת \"שעשוע התלמידים\"-תקנז, \"נר מצוה\"-תקעא יחד עם אחיו - ר מרדכי שמואל בזמן שהיה בוינה."},{"i":29443,"n":"מודיליאנו, יצחק שמואל משלוניקי","dt":"שצד - כד אד\"א","dp":"שלוניקי","b":"מחכמי שלוניקי. בנו - ר שמואל יצחק בעל \"נאמן שמואל\"."},{"i":29444,"n":"מודיליאנו, ליאון משלוניקי","b":"גביר מראשי קהלת שלוניקי-תרלח."},{"i":29445,"n":"מודיליאנו, ליאון משלוניקי","b":"רופא בשלוניקי-תרס."},{"i":29446,"n":"מודיליאנו, מואיז משלוניקי","b":"רופא בשלוניקי-תרס - בבית החולים האיטלקי (שהיה בו מחלקה כשרה). קיבל אות כבוד ממשלת איטליה."},{"i":29447,"n":"מודיליאנו, מרדכי שמואל משלוניק","f":"שמואל","dt":"תקעז","dp":"שלוניקי","b":"מחכמי שלוניק-תק.. רב באיסקופיה. חיבר הקדמה והגיה \"בני יצחק\". סייע עם אחיו ר יצחק שמואל בהדפסת \"נר מצוה\"."},{"i":29448,"n":"מודיליאנו, שאול יצחק משלוניקי","dt":"תקעח - תקפז","dp":"שלוניקי","b":"מחכמי שלוניקי-תקנז, והו\"ל \"שעשוע התלמידים\" לר שמואל יצחק מודיליאנו וחיבר לו הקדמה. פסקים ממנו בשו\"ת \"באר המים\" לר יעקב מנשה."},{"i":29449,"n":"מודיליאנו, שאול משלוניקי","f":"יצחק","dt":"תרמב","dp":"שלוניקי","b":"גביר בשלוניקי, ונמנה על שבעת טובי העיר-תריז - יחד עם ד\"ר משה אלאטיני. תרם לביה\"ס ת\"ת, ולעניני צבור בשלוניקי. לזכרו 2 קינות מאוטולינגי. בניו: יעקב, לוי ושמואל - גם הם גבירים בעלי חסד בשלוניקי."},{"i":29450,"n":"מודיליאנו, שמואל דניאל משלוניק","b":"נשיא הקהלה בשלוניקי-תרעג."},{"i":29451,"n":"מודיליאנו, שמואל יום טוב משלונ","dt":"תקטז - אחרי","dp":"שלוניקי","b":"גביר מחכמי שלוניקי. סייע בהדפסת \"ארוחת תמיד\" לר שמואל יצחק-תקטז."},{"i":29452,"n":"מודיליאנו, שמואל יוסף משלוניקי","b":"מחכמי שלוניקי. אביו של ר יוסף שמואל."},{"i":29453,"n":"מודילינו שמואל בן יצחק","dt":"ה'תסג 1703","bk":[["ארוחת תמיד",""],["נאמן שמואל",""],["שעשוע התלמידים",""]]},{"i":29454,"n":"מודלינגר, חיים דב בר מלמברג","k":"בעל דברי חיים","dt":"תרנח","b":"רב בלמברג. חתן נכדת התוי\"ט. חיבר \"דברי חיים\" למברג תרס."},{"i":29455,"n":"מודלינגר, חיים דב מלמברג -הנכד","f":"שמואל","k":"עורך אור תורה","b":"רב בלמברג. מעורכי \"אור תורה\" למברג תרפו. פרסם מאמרים ב\"אהל תורה\" - קראקא תרפח, \"שערי תורה\" - קראקא תרפה."},{"i":29456,"n":"מודלינגר, שמואל הלוי מלמברג","f":"חיים דב בר מלמברג","k":"בעל דברי שמואל","bt":"תרל","dt":"תש","b":"מחכמי סמבור, רב בלמברג, בנו ר חיים דב על מקומו אחריו. חיבר \"דברי שמואל\" למברג תרס. פרסם מאמרים ב\"אור תורה\" - לבוב תרפו, \"בית ועד לחכמים\" - סטמר תרפב, תלמיד אחיו ר ישכר בריש מבענדין, חתן ר אלכסנדר זיסקינד ליפשיץ מאוזארקוב. רב ביאנוב(=יאנווא-פאלאצק)-תרמד, מאדוב(מאקאווי)-תרמח, סטשוב-תרסא, גלה לרוסיה במלחמה העולם ה-I, וחזר לסטשוב. עבר לאמריקה, רב בטורונטו-תרף, סט לואיס-תרפז, טורונטו בשנית. פעל רבות למען שמירת השבת וגם פנה לממשלה לתת אפשרות ליהודים לשמור על השבת. תיקן עירוב בעיר (כנראה הראשון באמריקה). נספד ב\"הפרדס\". חיבר גם \"דברים ככתבם\" סט לואיס תרצב, \"יביע אומר\", חיבר זכרון ממלחמת העולם ה-I - לודז תרפו, פרסם מאמרים ב\"המגיד\" - סטמר תרפח, \"הפרדס\" פיעטרקוב-שיקגו תרעג-תרפז. \"שערי ציון\" - ירושלים תרפא, \"תורה מציון\" - ירושלים תרנה-תרסה."},{"i":29457,"n":"מודנא, דוד מירושלים","f":"משה מירושלים","k":"בעל נפש דוד","b":"רב ומקובל בצפת, ירושלים, בשלוניקי-תק והדפיס שם את ספריו. חיבר \"נפש דוד\" קושטא תצו, \"רוח דוד ונשמת דוד\" - פירוש לאדרא רבא - שלוניקי תקז. ועוד. בהקדמתו לספרו \"רוח דוד\" מספר על מאורעות חייו בארץ ישראל. בשנת תקז בשליחות בשלוניקי ודרש בפני הקהל ושומעיו התנדבו להדפיס את ספריו."},{"i":29458,"n":"מודנא, יצחק מבולוניא","f":"מרדכי","b":"אביו של ר יהודה אריה ממודנא."},{"i":29459,"n":"מודנא, יצחק מרדכי מצינטו","f":"אלישע יוסף","dt":"תקסח","dp":"צינטו -איטליה","b":"רב בצינטו."},{"i":29460,"n":"מודנא, מזל טוב ממודנא","f":"שמשון יעקב","k":"בעל פירורי לחם","b":"תלמיד ר ישמעאל הכהן בעל \"זרע אמת\". רב במודנא על מקום רבו. ממשתתפי אסיפת הרבנים (סנהדדרין) בפריז-תקסו. חיבר גם \"שערי דמעה\" ועוד. (רב בפריס על מקום רבו-תקסו?)"},{"i":29461,"n":"מודנא, מרדכי מבולוניה","dt":"רץ","b":"רב ורופא בבולוניה. זקנו של ר יהודה אריה ממודנא. התחיל בחיבור דומה לבית יוסף על הטור, כתב שו\"ת בכת\"י. הורעל ע\"י רופא נוצרי בגלל קנאת הרופאים הנוצרים. בניו ר יצחק, ר שלמה, ר שמעיה, ר אבטליון."},{"i":29462,"n":"מודנא, שאלתיאל חזקיה","b":"תשובה ממנו בשות הרמ\"ז-תלב."},{"i":29463,"n":"מודעי, חיים מאזמיר וצפת","k":"בעל טיב גיטין","r":"רב בקושטא צפת ואזמיר","bt":"תפ","bp":"צפת","dt":"תקנד","dp":"צפת","b":"תלמיד ר יעקב יקותיאל בן דוד הכהן. בשליחות צפת-תקט, והתישב בקושטא, רב באזמיר-תקלו, חזר לצפת-תקנג ור רפאל יצחק די מאיו על מקומו אחריו, רב בצפת, בשליחות בשנת תקט במצרים, וקושטא שם כיהן כדיין-תקטו, בשליחות נוספת לאיטליה בשנת תקכד, בפרג - ונפגש עם הנודע ביהודה - המזכירו בספרו, רב באזמיר-תקלו על מקום ר חיים אבולעפיה (והיה מחלוקת על המינוי בין אלה שהביאו שטר מצד ר חיים דוד אבולעפיה שמינהו לרב על מקומו אחריו ואחרים טענו שהשטר מזוייף), חזר לצפת-תקנג. הוציא לאור \"שערי צדק\" והם תשובות שמצא מגאוני בבל עם הערותיו, שלוניקי תקנב. בפרג פגש את ה\"נודע ביהודה\", חיבר \"טיב גיטין\" ירושלים תרלה, \"ברך משה\" ועוד. את הספר \"שערי צדק\" שלוניקי תקנב, הוציא לאור בנו ר נסים מודעי. בנו גם - ר רחמים, חתנו - ר יוסף משה אלגזי.","bk":[["טיב גיטין [מודעי]","הלכה ומנהג - אחרונים"],["חיים לעולם [שו\"ת]",""],["הגהות רבי חיים מודעי - או\"ח יו\"ד",""],["טיב גיטין - סדרי גיטין",""]]},{"i":29464,"n":"מודעי, נסים","f":"חיים-[טיב גיטין?]","b":"מחכמי ארץ ישראל, בשליחות באיטליה, הו\"ל שות מהר\"י ברמא."},{"i":29465,"n":"מודעי, נסים חיים משה מאזמיר","k":"בעל דרישה מחיים","dt":"תרנא - כו אייר","dp":"צפת","b":"נכד ר חיים מודעי מצפת ונכד ר יעקב סיד מירושלים. ראב\"ד אזמיר-תקלח, עלה לצפת. חיבר \"מימר חיים\" נדפס בתוך \"חיים לעולם\" לר חיים מודעי אזמיר תרלט, \"דרישה מחיים\" אזמיר תרמח. נספד על ידי ר חיים פלאג'י ב\"פדה את אברהם\"."},{"i":29466,"n":"מודרן, זנויל משטמפן","b":"מחכמי שטמפן, חתם-תקנט על מינוי ר לוי פולק לרב בשטמפן."},{"i":29467,"n":"מודרן, יהודה מסיגט","f":"ישעיה מסיגט","k":"בעל זכרון שמואל","r":"מגיה דתרומת הכרי","bt":"תקפ","bp":"פרשבורג","dt":"תרנד - ד חשון","dp":"סיגט","b":"נכד הסמיכת חכמים. תלמיד החת\"ס - עוד בהיותו כבן תשע וגדל בביתו לאחר שנתייתם. תלמיד הדברי חיים מצאנז, התקרב ל\"ישמח משה\" באוהל (=ערלוי(=אויהל)) ובהמלצתו חתן ר שמואל זנויל כהנא מסיגט - חתנו של \"קונטרס הספיקות\" ועבר לשם. מחכמי סיגט אך סירב לרבנות והיה במחלוקת עם ר יוסף שטרן רבה של סיגט. חיבר \"פרי העץ\". היה מקורב לחסידות - למרות שלא היה חסיד - וסיפר מעשה מופלא מר מאיר מפרימישלן. נשלח ע\"י האדמור ר ישראל מרוזין לבחון את חתנו המיועד ר מנחם מנדל הגר מויזניץ. ביקר בפרשבורג וסיפר לחת\"ס על החסידות והאדמורים כפי שהכירם. מתורתו ב\"המאסף\" - ירושלים-אלכסנדריה תרנו-תרעג.","bk":[["זכרון שמואל – גיטין",""],["פרי העץ – עה\"ת",""]]},{"i":29468,"n":"מודרן, יצחק מפרשבורג","b":"מחכמי פרשבורג, חתם-תקנז על חידוש תקנות החברא קדישא שתיקן ר יום טוב ליפמן מפרשבורג."},{"i":29469,"n":"מודרן, משה מפרשבורג","f":"לאזיל","b":"מחכמי פרשבורג, חתם-תקכח על תקנות החברא קדישא."},{"i":29470,"n":"מוהדא\"ר, יעקב מתוניס","b":"תלמידו בעל \"מקור ברוך\" הזכירו בספרו - והעמיד תלמידים רבים."},{"i":29471,"n":"מוהליבר, יהודה ליב","b":"גדול בנגלה ונסתר,רב בשאלאק-ת\"ר"},{"i":29472,"n":"מוזס, אליעזר מסמבור","bt":"תרנט","dt":"תשב","b":"רב בסמבור-תרצב. נספה בשואה."},{"i":29473,"n":"מוזס, דוד","dt":"תשד","b":"רב בטשעטשע"},{"i":29474,"n":"מוזס, דוד מטארדא","f":"יצחק מטארדא","bp":"טארדא","dp":"טורנא","b":"תלמיד הכת\"ס, ומהרם שיק, ור שמואל עהרנפלד ממטרסדורף. מחכמי טורנא."},{"i":29475,"n":"מוזס, זאב דב מטשעטשע","f":"יהודה מרוס-ליד ססרגן","k":"בעל שאגת זאב-תרסט","bt":"תרלח","bp":"כפר רוס-ליד סאסרגן","dt":"תרפג - כה ניסן","dp":"טשעטשע","b":"תלמיד השב\"ס. דיין ורב בכפר טשעיטשע, רב בלארינצי-מחוז נוגראד. נספה בשואה."},{"i":29476,"n":"מוזס, חיים מרישא","b":"מחכמי רישא - ממשתתפי \"אהל מועד\"."},{"i":29477,"n":"מוזס, יהודה כץ מרוס","b":"רב ברוס-ליד סאסרעגען. בנו - ר זאב דב מלארניצי בעל שאגת אריה."},{"i":29478,"n":"מוזס, יהונתן מסבאטיטש","b":"רב בסאבאטיטש-תקכ\"ה"},{"i":29479,"n":"מוזר, יוסף מברסלוב","b":"רב בברסלוב"},{"i":29480,"n":"מוזר, שמואל מאיר מיגולניצה","b":"רב ביגולניצה-תרלז."},{"i":29481,"n":"מוחא ן, אברהם ממרוקו","dp":"ירושלים","b":"דיין במראכש, עלה לירושלים"},{"i":29482,"n":"מוחא ן, ישראל ממראקש","b":"מחכמי מארקאש, חתם על פס\"ד-תרמא עם ר רפאל יוסף הרוש. אחיו של ר מסעוד ן מוחא."},{"i":29483,"n":"מוחא ן, מכלוף ממרוקו","f":"רפאל מסעוד ממראקש","dt":"תשיד - תשרי","dp":"קזבלנקה","b":"מחכמי מרוקו ועסקן ציבור מובהק."},{"i":29484,"n":"מוחראבי, ישכר מתימן","bt":"תר..","bp":"די סופל-חוגריה בתימן","b":"מגדולי המקובלים במחוזות חוגריה ושרעב. והסמיך רבנים ושוחטים רבים."},{"i":29485,"n":"מוחרר, סעדיה מתימן","f":"חיים","bp":"גבלה-תימן","dt":"תשיד","b":"תלמיד ר יהודה תירם. רב בגבלה-תימן, עלה לארץ-תשט."},{"i":29486,"n":"מוטאל, אברהם - הזקן","dt":"שא - טו שבט","dp":"שלוניקי","b":"מחכמי שלוניקי. נכדו כנראה - ר אברהם."},{"i":29487,"n":"מוטאל, אברהם משלוניקי","f":"יעקב","k":"בעל תורת נזיר","bt":"שכח","dt":"תיח - טז אד\"א","dp":"שלוניקי","b":"ראש ישיבת ק\"ק \"לישבון ישן\" בשלוניקי, רב ראשי בשלוניקי מקום ר חיים שבתי-תז (עם ר אברהם פרחיה הכהן). מתלמידיו: ר בנימין מלמד, ור אהרן לפפה מאמזיר, ר שמואל אדרבי, ר אברהם נחמיאש, ר יצחק אלקבץ, ר אשר זבולון מבלגרד, ר עמנואל זונאנה. מבניו: ר בנימין, ר גרשון מאזמיר, חתנו - ר משה די בוטון. נכדו - ר אליהו הלוי מירושלים הו\"ל את ספרו \"תורת נזיר\". חיבר גם \"מגן אברהם\". (באוצר הרבנים - תאריך הפטירה - תרח)."},{"i":29488,"n":"מוטאל, בנימין מקושטא","f":"אברהם","k":"בעל תומת ישרים","b":"מדקדק, מגדולי חכמי קושטא-תע, חיבר \"תומת ישרים\". הו\"ל \"לוית חן\" לר אליהו הלוי מקושטא - קושטא תם."},{"i":29489,"n":"מוטאל, גרשון מאזמיר","f":"אברהם","dt":"תכז - טו תמוז","dp":"אזמיר","b":"דיין באזמיר-תכא - בזמן שבתי צבי עם ר חיים בנבנישתי ור בנימין מלמד."},{"i":29490,"n":"מוטאל, חיים משלוניקי","dt":"רצח - ה סיון","dp":"שלוניקי","b":"מחכמי שלוניקי."},{"i":29491,"n":"מוטאל, יעקב משלוניקי","b":"רב בשלוניקי-שנה."},{"i":29492,"n":"מוטוט, שמואל מספרד","f":"סעדיה","k":"בעל מגילת סתרים","b":"מחכמי גודאלחגארה-קס, פילוסוף, מקובל, מפרש ומתרגם. חיבר \"משובב נתיבות\", \"מגלה עמוקות\", ועוד. תרגם לבקשת הריב\"ש את ספר \"אלעקידה אלרפיעה\" לר אברהם ן דאוד וקרא לו \"אמונה נשאה\", אולם התרגום נדחה מפני תרגומו של ר שלמה ן לביא \"האמונה הרמה\"."},{"i":29493,"n":"מוטס, שלמה מקוברין","dt":"תשג","b":"מרביץ תורה בקוברין"},{"i":29494,"n":"מוטקה חב\"ד","bp":"אושמיאנה-ליטא","dt":"1875","b":"בדחן פופולרי בחתונות. מעשיות רבות סופרו עליו."},{"i":29495,"n":"מוטרו ן, שבתי מקושטא","b":"ממונה על איסור והיתר בקושטא-תקנד."},{"i":29496,"n":"מוטרו, חיים מיפו","f":"יוסף","bt":"תרלח","bp":"יפו","b":"עסקן בועד העדה הספרדית ביפו, ציר באספת הנבחרים הראשונה מטעם יפו."},{"i":29497,"n":"מוטרו, יוסף מחברון","f":"רפאל?","dt":"תקצב-ג - ח אב","dp":"פיליבי","b":"מחכמי חברון, בשליחות בתורכיה בשנת תקץ, ועבר גם בפאדובה, נפטר בדרכו בבולגריה."},{"i":29498,"n":"מוטרו, יצחק מחברון","f":"יוסף","bt":"תקסט","bp":"ירושלים","b":"מחכמי חברון. בשליחות בצפון אפריקה-תרח יחד עם ר יצחק קוריאט בעל מעשה רוקם, על כתב שליחותו הממוען לגביר ר נסים שמאמא בתונס, חתמו ר חיים הלוי, ר יוסף הלוי, ר יעקב עבוד ועוד. בהיותו בטריפולי-תרל הסכים על \"מזמרת הארץ\" לר פרג'י בן רחמים נעים, חתם-תרכא על אגרת שליחות לבנית ביהכ\"נ תפארת ישראל בירושלים."},{"i":29499,"n":"מוטרפרל, אשר זעליג ממיכלפליא","f":"שלום מבאר","bt":"תרלב","b":"רב במיכלפליא(=מיכלפאליע)-פודוליה-תרנה. חיבר הלכות תפילין - בכת\"י."},{"i":29500,"n":"מוטרפרל, שלום מבאר","f":"משה ליב","bt":"תרי","b":"רב בבאר-פודוליה-תרמא. בנו - ר אשר זליג ממיכלפליא."},{"i":29501,"n":"מוטשניק, מרדכי יהודה ממרקיבקה","f":"חיים נחום","bt":"תרמ","b":"רב במרקיבקה(=מארקיווקע)-פודוליה-תרסד."},{"i":29502,"n":"מויאל, אברהם ממרוקו","f":"אהרן","bt":"תרי","bp":"ראבאט-מרוקו","dt":"תרמו - יב טבת","dp":"יפו","b":"עלה לארץ והתישב ביפו. חתן ר יוסף ן נון מיפו. פעיל צבור ציוני ובעל השפעה על עניני הברון רוטשילד והמושבות,"},{"i":29503,"n":"מויאל, אהרן מאיר מחברון","b":"מחכמי חברון. בשליחות קהלת חברון."},{"i":29504,"n":"מויאל, אהרן מאלגיר","bt":"תקץ","dt":"תרס - בערך","b":"שליח ירושלים, רב בתייארת-אלגיר, עבר לווהראן-תרל. ור דוד אשכנזי מווהראן כתב הזכירו בכתביו. שאלה ממנו לר' אב\"א ב\"כרם חמר\". הניח ספר דרושים על התורה - בכת\"י."},{"i":29505,"n":"מויאל, אלעזר","f":"מסעוד","b":"רב ומו\"ץ באלקאצאר"},{"i":29506,"n":"מויאל, דוד","dt":"תרמב","b":"למד במראקש, נפטר בגיל 20"},{"i":29507,"n":"מויאל, דוד מיפו","f":"יוסף","bt":"תרמא","bp":"יפו","b":"משפטן, ציר באספת הנבחרים, חבר הועד הלאומי."},{"i":29508,"n":"מויאל, יהודה ממוגאדור","f":"מכלוף","b":"מו\"ץ במוגאדור-מרוקו-שנות ה-תק-תר יחד עם ר שלמה אסבאג. בקי בחכמת החשבון, הניח תשובה ופסקים בכת\"י."},{"i":29509,"n":"מויאל, יהודה ממרוקו","k":"בעל שבט יהודה","bp":"תארודנת(מרוקו)","dt":"תרעא - כט טבת","dp":"ירושלים","b":"דיין ומו\"צ בסאפי-מרוקו, ראב\"ד במוגאדור, עלה לירושלים-תרע, חיבר \"שבט יהודה\"."},{"i":29510,"n":"מויאל, יוסף","k":"ביי מויאל","dt":"תרעד - טו אב","dp":"יפו","b":"חתן ר משה פארדו מאלכסנדריה. קונסול ספרד ופרס ביפו. רכש קרקעות להתישבות יהודים ביפו."},{"i":29511,"n":"מויאל, יצחק מאלקצר-מרוקו","dt":"תצז - ו תמוז","b":"מו\"ץ באלקצר-מרוקו, נזכר ב\"ויאמר יצחק\", ואצל היעב\"ץ."},{"i":29512,"n":"מויאל, מכלוף ממרוקו","b":"רב בפאס-תרם."},{"i":29513,"n":"מויאל, מכלוף מתארודנת-מרוקו","dp":"מוגאדור","b":"מחכמי מוגאדור, רב בתארודנת-מרוקו, בנו - ר יהודה בעל \"שבט יהודה\"."},{"i":29514,"n":"מויאל, מסעוד מטיטואן ואלקצר","dt":"תצ - טבת","b":"רב בטיטואן, אלקצר-מרוקו-תפט. תשובות ממנו ב\"משפט וצדקה ביעקב\", ונזכר ב\"ויאמר יצחק\"."},{"i":29515,"n":"מויאל, מסעוד ממרוקו","f":"יהודה","bt":"תרלב","bp":"מרוקו","dt":"תרעז - ה סיון","b":"דיין במרוקו על מקום אביו שעלה לארץ-תרע, עם ר יוסף ן עטר, ור דוד כנאפו. רב בקזבלנקא-תרעג."},{"i":29516,"n":"מויאל, משה מאלקצר-מרוקו","b":"מו\"ץ באלקצר-מרוקו-תפ. ב\"ויאמר יצחק\" שו\"ת ממנו, שאלה ממנו לר יהודה ן עטר."},{"i":29517,"n":"מויאל, משה ממרוקו","b":"מחכמי מרוקו, שאלה ממנו ליעב\"ץ."},{"i":29518,"n":"מויאל, שלמה","f":"אברהם","bt":"תרלט","bp":"יפו","b":"חתן שמעון רוקח מיפו. חבר בועד עדת הספרדים, השתתף באספת הנבחרים הראשונה בארץ."},{"i":29519,"n":"מויאל, שמעון מיפו","f":"יוסף","k":"בעל אל תלמוד","bt":"תרכו","bp":"יפו","dt":"תרעה - כא סיון","dp":"יפו","b":"רופא, עבר לקהיר, חזר ליפו. תרגם את התלמוד לערבית. הו\"ל עתון בערבית \"צות אל עותומניה\", ממיסדי \"אגודת המגן\" ביפו."},{"i":29520,"n":"מויז, משה הכהן מברלין","b":"מראשי הקהילה בברלין-תקד, חתם על כתב ההסכם עם ר דוד פרנקל הראב\"ד בברלין."},{"i":29521,"n":"מוייא, משה הלוי","b":"תשובה ממנו ב\"לקט הקמח\". הספידוהו הרב פאציפיקו, ור יהודה יוסף בן דוד הלוי ב\"כוס תנחומין\"."},{"i":29522,"n":"מוין, מאיר ליב","dt":"תרט","dp":"ירושלים","b":"מחכמי ירושלים"},{"i":29523,"n":"מוינשטר, אורי מארה\"ב","k":"בעל קרני ראם","b":"רב בארה\"ב-תשיא. פרסם מאמרים ב\"בית ועד לחכמים\" - נ\"י תשא, \"היכל התורה\" - נ\"י תרצג."},{"i":29524,"n":"מוינשטר, יעקב ליב מנ\"י","f":"משה אברהם מוינשטר","k":"בעל סדר המצות","bt":"תרנב","b":"רב בניו יורק-תרפח. פרסם מאמרים ב\"היהודי\" - נ\"י תרצו."},{"i":29525,"n":"מוינשטר, מאיר מירושלים","b":"פרסם מאמרים ב\"אור תורה\" - ירושלים תרנז."},{"i":29526,"n":"מוינשטר, מנדל מירושלים","b":"דיין בירושלים. פרסם מאמרים ב\"אור תורה\" - ירושלים תרנז, \"תורה מציון\" - ירושלים תרנה-תרסה."},{"i":29527,"n":"מוינשטר, משה אברהם מירושלים","f":"מנחם מנדל","k":"בעל גנון והצל","bt":"תרלב","bp":"ירושלים","dt":"תרצט","dp":"ירושלים","b":"נסע לאמריקה וכיהן כרב בערים ויניפג, דנוור וניו יורק, בשנת תרצב חזר לארץ. חיבר \"גנון והצל\" - נ\"י תרצד. פרסם מאמרים ב\"היכל התורה\" - נ\"י תרצג, \"יגדיל תורה\" - נ\"י תרעו, \"שערי ציון\" - ירושלים תרפא."},{"i":29528,"n":"מוכסן, בצלאל","f":"הקדוש נתן","k":"מרדכי השני","bt":"שמה","dt":"תכז - יט תשרי","b":"גדול ליהודים,קרוב למלכות,מנהיג המדינה בזלקווא"},{"i":29529,"n":"מוכר ירק, אברהם"},{"i":29530,"n":"מוכתר מטבריה","b":"מראשי הקהלה בטבריה בשנת ד'תתקכה (1165)."},{"i":29531,"n":"מוליאנר, יוסף","f":"משה","dt":"תקנג - לפני","b":"מחסידי טבריה, אחיו של ר יואל מראשי החבורה."},{"i":29532,"n":"מוליאר, יעקב","dt":"תשג","b":"רב ביאשון"},{"i":29533,"n":"מולין, יעקב הלוי - מהרי\"ל","f":"משה","k":"מהרי\"ל","bt":"קפ","dt":"קפז - כא אלול","b":"גדול הדור, פוסק ומעצב מנהגי בית הכנסת, מתקן תקנות לצבור, מרביץ תורה במגנצא-קמח, וורמייזא. אחיו - ר יקותיאל זלמן מאיטליה.","bk":[["מהרי\"ל (שו\"ת)",""],["מהרי\"ל החדשות (שו\"ת)",""],["מהרי\"ל מבוא וליקוטים",""],["ספרי מהרי\"ל - מנהגים",""],["מהרי\"ל","הלכה ומנהג - ראשונים"],["מהרי\"ל החדשות",""],["מהרי\"ל (מהר\"י סגל/מולין) [מנהגים",""],["שו\"ת]",""],["מהרי\"ל","שו\"ת - ראשונים"]],"e":"קט\"ו~-קפ\"ז"},{"i":29534,"n":"מולין, יקותיאל זלמן הלוי סגל","f":"משה הלוי","dt":"קמח - א תשרי","b":"אחיו הגדול של המהרי\"ל. מחכמי מגנצא ואיטליה-קן. הסכים על חרם ישיבת בבל לטובת רבנו שמואל שליטשטאט בעל \"קיצור מרדכי\" ועל כך ב\"מבוא לקיצור המרדכי\" בתוך \"מרדכי השלם\" ירושלים תשנב. בנו - ר יעקב מגיילנהויזן."},{"i":29535,"n":"מולין, משה הלוי","dt":"קמז","b":"מגדולי דורו בריינוס,מחכמי שו\"ם,רב במגנצא"},{"i":29536,"n":"מולינא - משפחה","dt":"תרנד - יא תשרי","dp":"טבריה","b":"מחכמי טבריה, שד\"ר למרוקו-תרי\"ז, תרכ\"ה עיראק, תרכ\"ז-טריפולי"},{"i":29537,"n":"מולינא די, יוסף משלוניקי","b":"מחכמי שלוניקי-רפ."},{"i":29538,"n":"מולינא די, יצחק ממצרים","f":"אברהם","k":"בעל בשמים ראש","bp":"ונציה","b":"רב במצרים-שכ, בזמן של ר יוסף קארו ור משה מטראני, והיה להם מחלוקת בענין אשכנזי שעבר על חרם דרבנו גרשום ונשא אשה נוספת. חיבר פירוש למשניות בכת\"י, מתורתו בספרי חכמי דורו. בשנת רפח עלה לירושלים. עשיר ובעל ספריה גדולה של כתבי יד. בשנת תקנג פרסם ר שאול ברלין ספר \"בשמים ראש\" וטען שהוא מלוקט על ידי ר יצחק מולינא, ודבר זה עורר פולמוס גדול בין הגדולים ויש שטענו כי המדובר בזיוף."},{"i":29539,"n":"מולינא די, יצחק מקושטא","f":"שלמה","k":"בעל אגודת אזוב","b":"רב בקושטא בזמן הרא\"ם."},{"i":29540,"n":"מולינא, אהרן מאלגיר","dt":"תשיב","b":"רב ודיין באלגיר אצל ר שמואל צרור."},{"i":29541,"n":"מולינה","k":"ראה: מולינא","b":"משפחה בספרד ושלוניקי."},{"i":29542,"n":"מולכו - משפחה","b":"משפחה מיוחסת משלוניקי. בני המשפחה החזיקו בחזקת השחיטה, במשך מאות שנים היו השוחטים בשלוניקי מבני 3 משפחות: ברכה - החל משנות ה-ש', מולכו, אישטרושה(=איסטרומסה) ורק להם היתה הזכות לכך."},{"i":29543,"n":"מולכו, אברהם מירושלים","dt":"תקלג - כג כסלו","dp":"ירושלים","b":"רב בירושלים. ממשפחת ר שלמה מולכו בעל \"שמן משחת קדש\". חתם-תקיו על שטר התקשרות עם חכמי ירושלים."},{"i":29544,"n":"מולכו, אברהם משלוניקי","f":"יוסף","bt":"תיו-ז","dt":"תצט - כו תשרי","dp":"שלוניקי","b":"ראש השוב\"ים בשלוניקי ובנו - ר יוסף על מקומו אחריו (והיה מחלוקת על כך עם בני משפחת ג'יראסי). מגדולי החכמים בשלוניקי. חתם על הסכמת ר יוסף קובו-תפה - בענין פטור תלמידי חכמים ממס. בניו: ר יוסף, ר שלמה השד\"ר, ר יצחק, ור שאול - עלו לירושלים."},{"i":29545,"n":"מולכו, אברהם משלוניקי","f":"שאול","b":"דיין בשלוניקי-תקצה."},{"i":29546,"n":"מולכו, אלעזר מירושלים","dt":"תרנו - כג אלול","b":"מרבני ירושלים"},{"i":29547,"n":"מולכו, אלעזר משלוניקי","f":"יצחק","dt":"תקסב - כו סיון","dp":"שלוניקי","b":"דיין בשלוניקי-תקסב."},{"i":29548,"n":"מולכו, אלעזר משלוניקי","b":"מחכמי שלוניקי-תרס."},{"i":29549,"n":"מולכו, דוד שלמה משלוניקי","b":"חזן להלויות מתים בשלוניקי. נספה בשואה."},{"i":29550,"n":"מולכו, דניאל מירושלים","dt":"תקנא - כה אדר","b":"מרבני ירושלים"},{"i":29551,"n":"מולכו, חיים יצחק מירושלים","f":"יצחק","dt":"תקעד - יז תשרי","dp":"ירושלים","b":"מחכמי שלוניקי, עלה לירושלים והיה פקיד בקהלה, נאלץ לברוח לחברון."},{"i":29552,"n":"מולכו, חיים משלוניקי","dt":"תרסד","dp":"שלוניקי","b":"מחכמי שלוניקי, וראש המוהלים. בנו - ר אברהם - רב בקאוואלה."},{"i":29553,"n":"מולכו, יוסף מאנקונא","dt":"שיו - יג אייר","dp":"אנקונא","b":"אחד מ-24 הרוגי אנקונא על פי עדות ר שלמה חזן מאנקונא. קינה לזכרם מאת ר אברהם דוד חי."},{"i":29554,"n":"מולכו, יוסף מחברון","b":"מחכמי חברון, בשנת תקפב בשליחות בארצות ערב."},{"i":29555,"n":"מולכו, יוסף מירושלים","b":"מחכמי ישיבת \"יפאר ענוים\" בירושלים-שנות ה-תק'."},{"i":29556,"n":"מולכו, יוסף משלוניקי","f":"יצחק","b":"אחיו של ר שאול-הרב הראשי בשלוניקי. מחכמי שלוניקי, ומדפיס-תקס יחד עם ר חיים אברהם נחמה, וסעדי יהודה הלוי אשכנזי, ואח\"כ לבדו. הו\"ל ספר אביו \"דברי חפץ|, ועוד."},{"i":29557,"n":"מולכו, יוסף משלוניקי","f":"אברהם","dt":"תרעד","dp":"שלוניקי","b":"נכד ר שאול-רבה של שלוניקי. רב בקאשטוריאה, רב בשלוניקי וראש המספידים."},{"i":29558,"n":"מולכו, יוסף משלוניקי","b":"ראש השו\"בים בשלוניקי-תפה, ראש הקהל ומו\"צ בדויראן במשך כשנתיים."},{"i":29559,"n":"מולכו, יוסף משלוניקי וירושלים","f":"אברהם","k":"בעל אהל יוסף","bt":"תמז או תנב","bp":"שלוניקי","dt":"תקכ-ח","dp":"ירושלים","b":"מחכמי שלוניקי, למד אצל ר יוסף דוד בעל \"בית דוד\", נשא את בת אחותו שהיתה ממשפחת קוזין. שימש כשו\"ב באדרינופול(=אידירני), היה מחלוקת בינו לבין ר אברהם גירון באדרינופול עד שחזר לשלוניקי, שירון (לשם ברח משלוניקי בזמן המגפה), ובערים נוספות, ולימים התמנה לראש השוחטים בשלוניקי על מקום ר יהודה ג'יראסי-תצג, ונחשב לפוסק האחרון בענינים אלו. ברח משלוניקי לדוייראן - בגלל רדיפת השלטונות שתבעו מס גם מתלמידי חכמים, עלה לירושלים-תקח והיה מחכמי \"ישיבת \"יפאר ענוים\" (של משפחת פרנקו מליוורנו). חיבר \"אוהל יוסף\" שלוניקי תקטז, ו\"שלחן גבוה\" שלוניקי תקטז, \"זובח תודה\" - שתורגם ללדינו, חיבר דרשות והספדים - ואבדו. מחבריו ר יוסף נבון \"נחפה בכסף\", ר יוסף חזן \"עין יוסף\" ועוד. אחיו: ר שלמה מירושלים, ור שאול המקובל מירושלים, ר יצחק משלוניקי (שהו\"ל לאור את ספרו). קרובו של ר\"א גטניו בעל \"טירת כסף\". (תאריכים לא מסתדרים - אולי חכם אחר?)"},{"i":29560,"n":"מולכו, יוסף משלוניקי וקושטא","f":"יצחק","b":"גביר בשלויקי, עבר לקושטא. סייע בהדפסת \"דברי חפץ\"-תקנה לר אהרן טולידו, ואחיו - ר שמואל מולכו הגיה את הספר."},{"i":29561,"n":"מולכו, יעקב מירושלים","f":"יוסף","b":"דיין בירושלים-תנב. תלמיד ר יעקב ישראל חגיז, גיסו של ר אברהם יצחקי. חיבר שו\"ת ודרושים בכתב יד וחלקם היו בידי החיד\"א. היה בשליחות. כתב בשנת תנה אגרת לר בנימין הכהן בריגיו אודות שליחות ר משה ששפורטש. לפי רוזניס היה אחיו של ר יוסף ולא בנו."},{"i":29562,"n":"מולכו, יעקב מצפת","b":"מחכמי צפת, חתם-תקפו אחרי ר אברהם אנהורי על כתב שליחות ר מסעוד פינטו."},{"i":29563,"n":"מולכו, יעקב משלוניקי","dt":"תקלה","dp":"שלוניקי","b":"מחכמי שלוניקי."},{"i":29564,"n":"מולכו, יצחק משלוניקי","f":"אליעזר","b":"מחכמי שלוניקי-תקעב. הגיה את \"מחזיק ברכה\" לחיד\"א, יחד עם ר יוסף שמואל מודיליאנו."},{"i":29565,"n":"מולכו, יצחק משלוניקי","f":"חיים","dt":"תש..","b":"מחכמי שלוניקי. נספה בשואה עם אחיו: ר רפאל ור שאול."},{"i":29566,"n":"מולכו, יצחק רפאל משלוניקי","bt":"תרנד","bp":"שלוניקי","b":"מלומד מחכמי שלוניקי, עלה לירושלים. חיבר מאמר \"תולדות יהודי שלוניקי\" ב\"איל אביניר\" בלאדינו. פרסם מאמרים ב\"מזרח ומערב\", ובהם על השבתאות וכת הדונמה."},{"i":29567,"n":"מולכו, מיכאל בכור משלוניקי","dt":"תרס","dp":"שלוניקי","b":"דיין בשלוניקי."},{"i":29568,"n":"מולכו, עזרא מיכאל מירושלים","k":"בעל ליקוט על התורה","dt":"תרכב - יח אב","dp":"ירושלים","b":"מחכמי ירושלים. חיבר ליקוטים על התורה בכתב יד."},{"i":29569,"n":"מולכו, רפאל משלוניקי","f":"חיים","dt":"תש..","b":"מחכמי שלוניקי. נספה בשואה עם אחיו: ר שאול ור יצחק."},{"i":29570,"n":"מולכו, שאול חיים משלוניקי","b":"מוהל מחכמי שלוניקי-תרע, עלה לירושלים."},{"i":29571,"n":"מולכו, שאול מירושלים","f":"אברהם","dt":"תקיח - אחרי","dp":"ירושלים","b":"מקובל מחכמי ירושלים, ממקורביו של ר שלום שרעבי בישיבת בית אל, וחבר בחברת המקובלים \"ברית שבעה עשר\"-תקיז. אחיו הגדול היה ר יוסף מולכו בעל \"אהל יוסף\" ואחיו השני היה ר יצחק בעל \"אורחות יושר\", ור שלמה מירושלים."},{"i":29572,"n":"מולכו, שאול משלוניקי","f":"יצחק","dt":"תרט - כד-ט סיון","dp":"שלוניקי","b":"נכד-אבי אמו ר אלעזר נחמיאש משלוניקי. דיין בשלוניקי-תקעח, רב הכולל בשלוניקי-תקצו יחד עם ר מרדכי מטלון, ורב ראשי יחידי - לאחר שר מרדכי הושעה ע\"י הגבירים. הו\"ל ספר אביו \"אורחות יושר\" יחד עם אחיו ר יוסף, ר אלעזר ור שמואל. הסכים על 5 ספרים בשנים תרג-תרח. נודע בתקיפותו (החרים את הגביר יעקב פרננדיס - ואף הפאשה שאליו הגיע הדבר הצדיק אותו). ביקש מהפאשה להוציא להורג יהודי מוסר - לאחר שהוזהר. בניו: ר יצחק, ר אברהם, ר אלעזר ור שלמה, חתנו - ר דוד אמריליו ובזיוו\"ש ר אהרן פיפאנו (זקנו של ר דוד פיפאנו). הגיה את הספר \"דברי חפץ\" לר אהרן די טולידו שהו\"ל אחיו - ר יוסף."},{"i":29573,"n":"מולכו, שאול משלוניקי","b":"מחכמי שלוניקי-תרס, וראש השוחטים."},{"i":29574,"n":"מולכו, שאול משלוניקי","f":"חיים","dt":"תש..","b":"מחכמי שלוניקי. נספה בשואה עם אחיו: ר רפאל ור יצחק."},{"i":29575,"n":"מולכו, שבתי יעקב מירקאדו מי-ם","dt":"תקעג - טו אב","dp":"ירושלים","b":"מחכמי ירושלים. (אצל פרומקין-ריבלין - תאריך פטירתו - תרג)."},{"i":29576,"n":"מולכו, שבתי מצפת","f":"יוסף","b":"רב בצפת, בשליחות הקהלה והיה בונציה-תכב. חתם על כתב שליחות ר חייא גבריאל-תלב, ועל כתב שליחות-תמו ר יוסף עאטוד למנטובה, ועל כתב שליחות ר שלמה אאיליון-תמח. נזכר ב\"אורחות יושר\". חתם-תמז על הספר \"שער אפרים\"."},{"i":29577,"n":"מולכו, שלמה בכור משלוניקי","dt":"תרעח","b":"דיין בשאלוניקי"},{"i":29578,"n":"מולכו, שלמה מאזמיר","b":"גביר באזמיר-תקג, מכתב אליו מר חיים ירוחם וילנא-אלישר."},{"i":29579,"n":"מולכו, שלמה משלוניקי","f":"אברהם","dt":"תקן - יא כסלו","dp":"שלוניקי","b":"מחכמי שלוניקי, אחיהם של ר יוסף בעל \"שלחן גבוה\" של ר יצחק ור שאול. עלה לירושלים, ובשנת תקמט בשליחות בתורכיה ונפטר בשליחותו.."},{"i":29580,"n":"מולכו, שלמה משלוניקי","f":"שאול","dt":"תרכג","dp":"שלוניקי","b":"דרשן מחכמי שלוניקי."},{"i":29581,"n":"מולכו, שלמה משלוניקי","dt":"תרמה","dp":"שלוניקי","b":"רב בשלוניקי. נשיא הכבוד של חברת \"לה אירמאנדאד\"."},{"i":29582,"n":"מולכו, שלמה משלוניקי - ב","f":"דוד","k":"בעל שושנת המלך","bt":"תקלט","bp":"שלוניקי","dt":"תקמח - ו חשון","dp":"ירושלים","b":"מצאצאי ר שלמה מולכו שנהרג על קדוש השם, תלמיד ר חיים די לה רוזה בירושלים. גביר ונשיא יהודי שלוניקי, גבאי כוללות חברון וירושלים. חברו של ר\"א טובייאנה. עלה לירושלים-תקם והיה מחברי \"בית אל\". חיבר \"שמן משחת קודש\" שלוניקי תקלט, \"שושנת המלך\", \"שמן זית זך\", ועוד. הסכים-תקלט על \"מרכבת המשנה\" לר שלמה חעלמא שעבר בשלוניקי."},{"i":29583,"n":"מולכו, שמואל","b":"הגיה את \"דברי חפץ\"-תקנה לר אהרן טולידו, אחיו - הגביר יוסף מולכו מקושטא היה המו\"ל."},{"i":29584,"n":"מולכו, שמואל משלוניקי","f":"יצחק","b":"אחיו של ר שאול-הרב הראשי בשלוניקי. מחכמי שלוניקי-תקף."},{"i":29585,"n":"מולנר, אריה ליב מקרוז'","b":"רב בקרוז"},{"i":29586,"n":"מומו ן, יהודה ממרוקו","dp":"מערת אופראן-מרוקו","b":"רב במרוקו."},{"i":29587,"n":"מומיליאנו, יהודה ממונדובי","b":"מחכמי מונדובי-איטליה."},{"i":29588,"n":"מומיליאנו, יעקב ממונדאוי-איטלי","b":"מאנשי מונדווי(=מונדאוי)-איטליה. חיבר זכרונות וצוואה-שנות ה-תר'."},{"i":29589,"n":"מונד, אברהם זאב וולף","f":"אליעזר ליבר ממיקוליב","b":"חתן ר שלמה ליב ויינשלבוים מטיטשין והוציא לאור את ספר חותנו הל\"ל. רב במיקולייב על מקום אביו, קראקא."},{"i":29590,"n":"מונד, אברהם זאב מרידיק","b":"פרסם מאמרים ב\"תורה מציון\" - ירושלים תרנה-תרסה."},{"i":29591,"n":"מונד, אהרן ממוסט","f":"יחיאל דב ממוסט","k":"אהרצ'ה דעם רב'ס","bt":"תרלז","dt":"תשב","b":"רב במוסט על מקום אביו וגיסו. חתן ר נחום אפרים לנגנויר מגרודזיסק. נספה בשואה."},{"i":29592,"n":"מונד, אליעזר ליבר ממיקוליב","f":"דניאל ממיקוליב","bt":"תרכה","dt":"תרץ","b":"חתן ר אלימלך פערן מרידיק. רב במיקוליב על מקום אביו. ובנו ר משה על מקומו אחריו."},{"i":29593,"n":"מונד, דניאל ממיקוליב","f":"שמחה מלמברג","bt":"תר","dt":"תרפב","b":"רב במיקוליב(=מיקאלאיוב)-תרע, ובנו ר אליעזר ליבר על מקומו אחריו. בנו גם הגביר ר שמחה מלמברג. אחיו של ר יחיאל ממוסט."},{"i":29594,"n":"מונד, יחיאל דב ממוסט","f":"שמחה","bt":"תרג","bp":"למברג","dt":"תרסו","b":"חתן נכדת ר שמריה שטיקלר ממוסט. רב במוסט על מקום הסב של אשתו - לאחר מחלוקת, בנו ר יצחק יהודה על מקומו אחריו."},{"i":29595,"n":"מונד, מנחם מנדל שלמה מזלוטניק","f":"אליעזר ליבר ממיקוליב","b":"מחכמי רידיק, רב בזלוטניק לפני השואה."},{"i":29596,"n":"מונד, משה ממיקוליב","f":"אליעזר ליבר ממיקוליב","bt":"תרנה","bp":"רידיק","dt":"תשיח","b":"רב במיקוליב-תרנה על מקום אביו. עבר לפריז-תרצה, שוויץ - ניצל מהשואה, פריז - אחרי השואה, לונדון-תשיב. חתן ר פיבל וקס מטיטשין. ערך \"עולת חדש\" ירחון תלמודי - פריז תשט."},{"i":29597,"n":"מונד, שמחה מטרנופול","b":"פרסם מאמרים ב\"אהל תורה\" - קראקא תרפח."},{"i":29598,"n":"מונד, שמחה מלמברג","b":"גביר ותעשיין מחכמי למברג, ראווא."},{"i":29599,"n":"מונדאוי, ראובן יוסף מאיטליה","b":"מקובל מחכמי איטליה בזמן הרמח\"ל."},{"i":29600,"n":"מונדה, יוסף","b":"מגדולי חכמי פאס-ש\"ה"},{"i":29601,"n":"מונדובי, חיים","b":"מחכמי איטליה, מתלמידי ר חיים בן עטר בישיבה בירושלים, ואחר כך בראש הישיבה אחרי ר יונה נבון. בשנת תקו בשליחות באיטליה."},{"i":29602,"n":"מונדולפו, יצחק מרומאנייה","b":"משורר ופייטן ברומאנייה בזמן ר נתנאל טרבוטו."},{"i":29603,"n":"מונדולפו, רפאל חי מפיסארו","b":"רב בפיסארו(=פיזרו)-איטליה. מובא ב\"באר עשק\" בשם הרב החריף."},{"i":29604,"n":"מונדיט, חיים מירושלים","b":"ראש ישיבת \"כנסת ישראל\" בירושלים-תקיח על מקום ר יונה נבון."},{"i":29605,"n":"מונדיכי, חיים מירושלים","b":"מחכמי ישיבת \"כנסת ישראל\" בירושלים-תקיח, וראש ישיבה."},{"i":29606,"n":"מונדין, יהודה ליב","f":"יואל","k":"בעל מלים לאלוה","b":"חיבר ספר השרשים בשם \"מלים לאלוה\" בעברית ובלשון אשכנז - ברלין תקנט."},{"i":29607,"n":"מונדרוביץ יצחק בן משה","bt":"1910","dt":"ה'תשסח 2008","bk":[["מי מעין",""]]},{"i":29608,"n":"מונדרוביץ, יצחק מכפר יונה ושיק","k":"בעל מי מעין","b":"פרסם מאמרים ב\"חידושי תורה\" - לודז תרצו - קובץ חבורת בני ישיבת מיר בלודז. רב בכפר יונה, שיקגו-תשכה. חיבר גם \"מעיני הישועה\"."},{"i":29609,"n":"מונדרי, ישעיה","bt":"תרעו","dt":"תשלג - יז תמוז","b":"דיין בתל אביב"},{"i":29610,"n":"מונדשיין, זליג צבי מבאלחוב","f":"אליעזר","k":"בעל גורל הצדקה","b":"מלמד תורה בבאלחוב."},{"i":29611,"n":"מונזון, אברהם יהודה ליב מירושל","dt":"תרץ - יד אדר","dp":"ירושלים","b":"בעל דפוס בירושלים."},{"i":29612,"n":"מונזון, דב בר מברוד","f":"חיים דוד אדמור מברוד","k":"אדמור מברוד","bt":"תרלה","dt":"תשב","b":"נינו של ר ישראל מרוזין. אדמור בברודי-תרצב על מקום אביו. חתן ר נתן דוד הולנדר מאמסנא. נספה בשואה."},{"i":29613,"n":"מונזון, חיים דוד מברוד","f":"יוסף מברדיטשוב","k":"אדמור מזלוטשוב-ברודי","bt":"תרי","dt":"תרצב - כו אדר","b":"נכד ר ישראל מרוזין. חתן ר בנימין זאב מאוזירן (שושלת זלוטשוב). אדמור בברודי והיה במחלוקת עם המשכילים - ולפני כן ברווה-רוסקה, סנדובה, ורדיחוב. בנו ר דב בר על מקומו אחריו."},{"i":29614,"n":"מונזון, יואל יוסף שמעון מירושל","f":"אברהם ליב","bp":"ירושלים","dt":"תרסו - יד חשון","dp":"ירושלים","b":"עסקן צבור בירושלים."},{"i":29615,"n":"מונזון, יוסף מברדיטשוב","f":"דוד מברדיטשוב","b":"חתן ר ישראל מרוזין. ארבעת בניו היו אדמורים. והם: ר לוי יצחק מיזירנה, ר חיים דוד מברודי, ר שמואל רופטשינסקי מקישינוב, ור אהרן שור מברדיטשוב."},{"i":29616,"n":"מונזון, ישראל מקליש","f":"חיים דוד מברודי","k":"אדמור מקליש בנ\"י","bt":"תרלט","bp":"יזירנה(=אוזראן)","dt":"תשיז - כז תמוז","dp":"ניו יורק","b":"מצאצאי האדמור מרוזין. חתן ר יצחק מאיר מסאווראן. אדמור בקאליש, בברודי על מקום אביו האדמור מברודי בניו יורק-תרצט. חיבר ליקוטים בכת\"י."},{"i":29617,"n":"מונזון, לוי יצחק מיזירנה","f":"יוסף מברדיטשוב","k":"אדמור מזוולוב","r":"אדמו\"ר מאוזיערנא","bt":"תרג-ד","dt":"תרעו - יח סיון","b":"נכד ר ישראל מרוזין. חתן ר יחיאל מיכל מושקוביץ מגלינא (שושלת זלוטשוב). אדמור בזוואלוב, יזירנה-תרמה. חיבר \"בך יברך ישראל\" פרמישלא תרסה.","bk":[["בך יברך ישראל - תורה",""],["זהב פנינים - ליקוטי אמרים על הזוה\"ק (כת\"י)",""]]},{"i":29618,"n":"מונזון, מנחם מנדל מניו יורק","f":"אברהם ליב","k":"בעל מפניני הרמבם","b":"רב בניו יורק-תרצד. חתן ר חיים זילברמן. חיבר \"מפניני הרמבם\" ניו יורק תרצא."},{"i":29619,"n":"מונזון, משה מיזירנא","f":"לוי יצחק מיזירנא","k":"אדמור מיזירנא בוינה","bt":"תרל","dt":"תרפז - י תשרי","b":"נינו של ר ישראל מרוזין. אדמור מיזירנא בוינה על מקום אביו."},{"i":29620,"n":"מונזלאוי, אלעזר","b":"מגדולי רבני מצרים-ש\"ע"},{"i":29621,"n":"מונטאלטו, אליהו מאיטליה ופריס","k":"הי\"ג לודוויקוס","dt":"שעז - כט שבט","dp":"טורן-צרפת או אמשטרדם","b":"נולד באיטליה למשפחת אנוסים ששבו לדת ישראל. רופא לדוכס ונציה או פירנצה, עבר לפאריס והיה רופא מלך צרפת לואי ה-יג והמלכה - והגיע לבקשתם וקיבל אישור מיוחד לשהות בפריז - שהיתה אסורה למגורי יהודים. פסק ממנו בתוך \"משפט שלום\" לר\"י פאציפיקו מונציה - ובו דן אם מותר לו ליסוע בשבת במרכבה אל המלך. חיבר ספרים בלטינית וספרדית בעניני אמונה וויכוח עם הנוצרים, חיבר ספר בפורטוגזית לתשובת המינים - בכת\"י, וספרי רפואה ותורה - מהם באוצה\"ס בעיר קולומביה-ארה\"ב. בפקודת המלכה נחנטה גופתו ונשלחה לקבורה באמשטרדם. תלמידו הש\"ר(=יש\"ר) מקנדיא מזכירו בספריו. בנו ר משה הרופא מלובלין. (יש רושמים פטירתו תב - טו שבט - \"קורות היהודים בלובלין\")."},{"i":29622,"n":"מונטאלטו, משה מלובלין","f":"אליהו מאיטליה","dt":"שצז - כד אייר","dp":"לובלין","b":"רופא מחכמי לובלין."},{"i":29623,"n":"מונטאלציאנו, בנימין","b":"מגדולי חכמי איטליה,רב בפירנצי-רי\"ב"},{"i":29624,"n":"מונטול, יחיאל מירושלים","b":"מחכמי ירושלים, בשליחות בשנת שסג, מוזכר על ידי ר חייא רופא בספרו \"מעשה חייא\" אודות מכתב ששלח לדמשק."},{"i":29625,"n":"מונטון די, יהושע מירושלים","b":"מחכמי ירושלים, בשנת תו חתם על התקנה לשחרור תלמידי חכמים ממס."},{"i":29626,"n":"מונטזינו, רפאל מאמשטרדם","b":"רב העדה הפורטוגזית באמסטרדם-ת\"ד"},{"i":29627,"n":"מונטיפושקולי, מלאכי","b":"מגדולי איטליה-ת\"כ"},{"i":29628,"n":"מונטיפיורי, יוסף סבאג'","f":"שלמה","bp":"לונדון","b":"בן אחות השר משה, ואפוטרופוס על עזבונו לטובת עניי ארץ ישראל."},{"i":29629,"n":"מונטיפיורי, יעקב מאיטליה","b":"חיבר פירוש למסורה - בכת\"י."},{"i":29630,"n":"מונטיפיורי, משה","bt":"תקמה","bp":"ליוורנו","dt":"תרמה - יט אב","dp":"רמסגאט-אנגליה","b":"רב פעלים לטובת אחיו בתפוצות ולישוב א\"י,פזר הונו לצדקה להחזקת התורה ולפדיון שבויים,ראש העיר בלונדון"},{"i":29631,"n":"מונטיפיורי, פרנסיס אברהם","bt":"תרצה","bp":"לונדון","dt":"תרצה","dp":"לונדון","b":"נכד אחיו של השר משה. ראש העדה הפורטוגזית בלונדון, ציר בקונגרס הציוני. נפטר ללא ילדים - והיה האחרון שהחזיק בתואר ברון."},{"i":29632,"n":"מונטישינו דון, יעקב מפלנדריה","b":"מאנוסי פורטוגל, מתושבי פלנדריה, וביתו שימש את האנוסים בדרכם מפורטוגל לתורכיה."},{"i":29633,"n":"מונטלבן, יעקב מאנקונא","dt":"שיו - ז תמז","dp":"אנקונא","b":"אחד מ-24 הרוגי אנקונא על פי עדות ר שלמה חזן מאנקונא. קינה לזכרם מאת ר אברהם דוד חי."},{"i":29634,"n":"מונטנר, זיסמן הלוי מירושלים","f":"יעקב חנוך","k":"הו\"ל תפלה למשה","b":"הו\"ל ספר הקצרת לרמב\"ם בשם תפלה למשה."},{"i":29635,"n":"מונטנר, יחיאל מנחם מנדל מבלז","dt":"תרן","b":"הגיע מרוסיה לברודי ושינה שמו למונטנר. דיין בבלז-תרי אצל השר שלום."},{"i":29636,"n":"מונטנר, לוי מליטוביסק ובלז","f":"יחיאל מנחם מנדל","k":"בעל בית לוי","bt":"תר - תריא","dt":"תרפז","b":"רב בואסילוביץ, ליטוביסק-תרנג, רב בבלז-תרס על מקום אביו. ישב בכלא במקום האדמור (לאחר שלקח על עצמו חרם שערך האדמור). חיבר \"בית לוי\" - בכתב יד. חתניו: ר אברהם לורברבוים מזולקוא, ר אריה יהודה ליב הוכברג מטפרוב."},{"i":29637,"n":"מונטפיורי, יעקב","k":"בעל פירוש למסורה","b":"מגדולי רבני איטליה-תק\"פ"},{"i":29638,"n":"מונטקייו - משפחה","b":"משפחה בשלוניקי - שמקורה בצרפת."},{"i":29639,"n":"מונטקייו, יוסף משלוניקי","f":"יצחק משלוניקי","k":"בעל כתונת יוסף","bt":"תל","dt":"תצח","dp":"שלוניקי","b":"מו\"ץ בקהלת פורטוגל בשלוניקי בזמן בעל \"טירת כסף\". חיבר \"כתונת יוסף\" - נדפס ע\"י בנו יצחק, \"יוסף עליו\", \"יוסף עליכם\", ועוד."},{"i":29640,"n":"מונטקייו, יצחק משלוניקי","f":"יוסף","b":"רב בשלוניקי. הדפיס ספר אביו \"כתונת יוסף\"."},{"i":29641,"n":"מונטקייו, רפאל משה מירושלים","f":"שמואל","dt":"תק","dp":"ירושלים","b":"עלה לארץ והתישב בירושלים."},{"i":29642,"n":"מונטקייו, שמואל ממצרים","b":"גביר במצרים-שנות ה-תק', סייע לר ידידיה שלמה ישראל בהדפסת ספרי אביו. חתנו - הגביר ר ישי הכהן."},{"i":29643,"n":"מוניון, חיים שבתי מירושלים","dt":"תקם - יב טבת","dp":"ירושלים","b":"מחכמי ירושלים, אשתו לאה - נפטרה בתקלג."},{"i":29644,"n":"מוניון, יצחק מאזמיר","b":"מחכמי אזמיר-שנות ה-ת', עסק גם במסחר המשי."},{"i":29645,"n":"מוניון, ישי מירושלים","b":"מחכמי ירושלים, חתם על התקנה לשחרור תלמידי חכמים ממס, ועל תקנה נגד הפירוד בשנת שפה. מוזכר ב\"חרבות ירושלים\" בין הסובלים בפרעות אבן פארוך."},{"i":29646,"n":"מוניון, משה מאישקופיה","b":"רב באישקופיה-שסז."},{"i":29647,"n":"מוניון, שלמה מבלגרד ורוסטיץ","b":"רב בבלגרד, גורש ע\"י האוסטרים ועבר לכהן כרב ברוסטיץ-תעז. הסכים על \"הסתערות מלך הנגד עם מלך הצפון\"."},{"i":29648,"n":"מונינה, גבריאל משלוניקי","b":"מחכמי שלוניקי-תרף."},{"i":29649,"n":"מוניצינוס, אנטוניו - אהרן הלוי","b":"מאנוסי פורטוגל, הגיע מברזיל לאמשטרדם-תד וסיפר לר מנשה בן ישראל שמצא את עשרת השבטים באמריקה, חזר לפארנאמבוק-ברזיל, נזכר ב\"מקוה ישראל\" לר מנשה בן ישראל."},{"i":29650,"n":"מונסביץ, מרדכי מנס","k":"בעל הדקדוק המעשי","bt":"1857","bp":"שאט","dt":"1928","b":"יסד בי\"ס בליבאו-1880. היגר לארה\"ב-1919 והיה מורה ומנהל בי\"ס. פרסם שירים ומאמרים. חיבר גם \"החבר הטוב\", \"מראה עינים\", ועוד."},{"i":29651,"n":"מונסה, אברהם","k":"בעל פדה את אברהם","bt":"תרעג-כסלו","b":"עלה לירושלים-תר\"פ, דיין, חיבר \"פדה את אברהם\""},{"i":29652,"n":"מונסה, יעקב יוסף מירושלים","bt":"תרם","dt":"תריד","b":"ראש ישיבת המקובלים \"אמת ושלום\" בירושלים-תשיב."},{"i":29653,"n":"מונסון, אברהם ב","k":"בעל תוצאות חיים","b":"חיבר גם \"מוצאי יום טוב\" על התוספות יום טוב, \"עץ הדעת\", ועוד. תשובותיו בספרי חכמי דורו ובהם - ר יונה נבון. שנת-תי."},{"i":29654,"n":"מונסון, אברהם מטיטואן","k":"בעל אשל אברהם","bp":"טיטואן","dt":"תקכ","b":"מחכמי טיטואן-מרוקו, אוראן-אלגיר, עבר למצרים. תשובה ממנו ב\"בית יהודה\" לר יהודה עיאש. חיבר גם \"שלחן שבת\", \"גט כריתות\", ועוד - בכת\"י, חלק מספריו היו בידי החיד\"א וחלק בידי ר שלמה חזן בעל המעלות לשלמה. גיסו - ר יצחק הלוי מטיטואן."},{"i":29655,"n":"מונסון, אברהם ממצרים - א","bt":"שכ","dt":"שצ","dp":"קושטא","b":"תלמיד הרדב\"ז ור בצלאל אשכנזי. רב ודיין במצרים-שנג, ר\"מ בקושטא-שסג בזמן המהרש\"ך. החיד\"א העיד עליו שראה ספרי תורה שכתב. חיבר קונטרס על המחלוקת שהיתה לו עם ר מנחם די לונזאנו אודות קבלת האר\"י. תשובות בספרי חכמי דורו."},{"i":29656,"n":"מונסון, משה מטיטואן","b":"מחמכי טיטואן, וסופר שטרות, חתם עם ר לוי פארדו ועם היעב\"ץ."},{"i":29657,"n":"מונסונגו רפאל אהרן בן ידידיה משה","dt":"ה'תר 1840","bk":[["מי השלח",""]]},{"i":29658,"n":"מונסונייגו, אברהם מטיטואן","f":"אפרים מפאס","b":"מחכמי טיטואן, חתם-תקנח עם ר משה ן צור ור משה הלוי."},{"i":29659,"n":"מונסונייגו, אברהם ממרוקו","f":"מנחם","b":"מרוקו"},{"i":29660,"n":"מונסונייגו, אברהם מפאס","f":"יהושע","dt":"תרלג","b":"מחכמי פאס, נפטר צעיר ללא ילדים."},{"i":29661,"n":"מונסונייגו, אברהם מפאס","b":"מחכמי פאס-תקמא. אחיו של ר ידידיה משה מפאס."},{"i":29662,"n":"מונסונייגו, אהרן מפאס","f":"יהושע","b":"רב בפאס"},{"i":29663,"n":"מונסונייגו, אליהו ממרוקו","b":"רב בפאס-תרם."},{"i":29664,"n":"מונסונייגו, אפרים מפאס","f":"אברהם","bt":"תע","dt":"תקם-ן","b":"נסמך מאת ר יעקב ן צור-היעב\"ץ. דיין בפאס-תקי, סגן ראב\"ד בטיטואן-מרוקו-תקיח אצל ר יעקב מלכא, אב\"ד על מקומו אחריו-תקלא יחד עם ר יהודה קורייאט. נסמך מאת היעב\"ץ. מתלמידיו - ר\"י בן נאיים בעל \"זרע יעקב\". נמנה בין חברי בית הדין של חמש בפאס (ר שאול שמואל דנון, ר אפרים בן אברהם מונסונייגו, ר רפאל עובד בן יעקב ן צור, ר אליהו בן יוסף הצרפתי, ר מתתיהו בן מנחם סירירו)."},{"i":29665,"n":"מונסונייגו, ידידיה משה מפאס-א","dt":"תקס - כח סיון","b":"דיין ומו\"ץ בפאס, אחיו ר אברהם מפאס. בנו - ר רפאל אהרן. הניח ספרים בכת\"י ואבדו. נספד ב\"דברי חכמים\" לר דניאל ן צולטאן."},{"i":29666,"n":"מונסונייגו, יהושע מפאס","f":"ידידיה","k":"בעל שבילי משפט","bt":"תקפו","dt":"תרנב - ח סיון","b":"מו\"ץ בפאס. חיבר \"שבילי משפט\" על חו\"מ, \"נשמת חיים\" על או\"ח, \"שבילי החיים\", ועוד."},{"i":29667,"n":"מונסונייגו, יוסף יצחק","f":"משה","k":"בעל משכיות לבב"},{"i":29668,"n":"מונסונייגו, יעקב מפאס","f":"ידידיה משה מפאס","b":"מחכמי פאס-תקנג. אחיו של ר רפאל אהרן."},{"i":29669,"n":"מונסונייגו, יצחק מפאס","f":"רפאל אהרן","b":"מחכמי פאס - שנות ה-תק'."},{"i":29670,"n":"מונסונייגו, משה מפאס","f":"מנחם","b":"מחכמי פאס, חתם-תקל עם ר יהושע בן מתתיה סירירו."},{"i":29671,"n":"מונסונייגו, נחמן מפאס","f":"יצחק"},{"i":29672,"n":"מונסונייגו, רפאל אהרן ממרוקו","f":"ידידיה משה","k":"הרא\"ם - בעל מי השלח","r":"החוזה מלובלין","bt":"תקכ","bp":"פאס","dt":"תר - ט אב","b":"תלמיד ר שאול סירירו. רב בפאס על מקום אביו. משורר פייטן ודרשן. חיבר גם \"משכיות לבב\". בניו ר שלמה, ר אליעזר, ר יצחק ור ידידיה שהיה רב בפאס על מקומו אחריו."},{"i":29673,"n":"מונסיליסי, אהרן מבוסיטו","dt":"תסז","dp":"בוסיטו","b":"רב בבוסיטו (איטליה). הספידו מהרב\"ך ב\"גבול בנימין\"."},{"i":29674,"n":"מונסיליסי, גמליאל מפארמה","f":"חנניה","k":"בעל שפתי רננות","b":"תלמיד ר מנחם עזריה. רב בפארמה. תשובה ממנו ב\"באר עשק\". אחיו - ר פלטיה בעל \"שפתי רננות\"."},{"i":29675,"n":"מונסיליסי, חנניה יגל החסיד","k":"בעל מספרים תהלות ה","b":"רב בפירארה-ת\"י. חיבר \"מספרים תהלות\". בניו - ר גמליאל ור פלטיה מפיררה שחיבר הקדמה לספר אביו. נכדו ר פנחס ברוך חיבר שיר על הספר, בנו ר יהודה רפאל יהושע מפירנצי - דור רביעי לרבנים."},{"i":29676,"n":"מונסיליסי, יהודה רפאל יהושע","f":"פלטיה ברוך","b":"רב בפירנצי. תשובה ממנו ב\"שמש צדקה\"."},{"i":29677,"n":"מונסיליסי, יצחק מפיררה","f":"יוסף","b":"רב בפיררה בזמן ר\"מ פרובנצאלי. תשובה ממנו ב\"פחד יצחק\"-שלג."},{"i":29678,"n":"מונסיליסי, פלטיה מפיררה","f":"חנניה","b":"רב בפיררה בזמן ר ידידיה בורגו ומהרם מריקטני - וחתם עמם על תשובות רבות. תשובה ממנו בשות הרמ\"ז. אחיו - ר גמליאל, ובנו - ר פנחס."},{"i":29679,"n":"מונסיליסי, פנחס","f":"פלטיה מפיררה","b":"מחכמי איטליה. שיר ממנו ב\"שפתי רננות\"."},{"i":29680,"n":"מונעס, שמואל משונציאן","b":"מחכמי שונציאן-תרס."},{"i":29681,"n":"מונק שלמה","bt":"1803","dt":"ה'תרכז 1867","bk":[["פלשתינה",""]]},{"i":29682,"n":"מונק, אליהו מאלטונא","f":"יחיאל אריה מדנציג","bt":"תקעח","bp":"אינאוורצלאוו","dt":"תרנט - כג אב","dp":"אלטונא","b":"מצאצאי ר מאיר מפוזנא בעל \"בית מאיר\". תלמיד ר עקיבא איגר, ר יעקב עטלינגר, ר מיכאל זאקס, למד באוני' ברלין. מלמד בבית הגביר ר אהרן הירש בהלברשטט, ושם התידד עם ר עזריאל הילדסהיימר שנעשה גיסו - התחתן עם אחותו של ר עזריאל, מלמד אצל ר שמואל ענאך באלטונא, וסייע לו בהוצאת \"שומר ציון הנאמן\", דיין על מקום ר אליעזר לאב, וממלא מקומו יחד עם ר יעקב כץ."},{"i":29683,"n":"מונק, אליהו מאנסבך ופאריס","f":"שמואל מונק","k":"בעל אור עולם","b":"רב באנסבך-תרפ\"ז,רב בפאריס. חתן ר ישראל יעקובוביץ מאנגליה."},{"i":29684,"n":"מונק, בער ממזריטש","f":"ליב מונק","b":"רב במזריטש"},{"i":29685,"n":"מונק, יהודה הכהן ממרבורג","f":"אליהו","k":"בעל אני לדודי","b":"נכד ר יחיאל אריה מונק מדנציג, ונכד-אבי אמו ר ליב הילדסהימר מהלברשטט. תלמיד ר יעקב עטלינגר מאלטונא, ביהמ\"ד לרבנים בברלין. רב במרבורג-תרלח."},{"i":29686,"n":"מונק, יהודה ליבוש","f":"יהושע גרשון","k":"בעל יגדיל תורה","b":"חתן מהר\"ש סגל שיעראדז. אחיו - ר צבי הירש מונק סייע בהוצאת ספרו.","bk":[["זכרון יהודה","פלפולים"]]},{"i":29687,"n":"מונק, יחיאל אריה הכהן","f":"מתתיהו מראביטש","k":"בעל מעלות יחיאל","b":"רב בדנציג. חתן ר ליזר בן יוסף הלפרין."},{"i":29688,"n":"מונק, יחיאל מיכל אריה מדנציג","f":"יהודה ליב הכהן","b":"רב בדנציג-תקצ. פרסם מאמרים ב\"שומר ציון הנאמן\" - אלטונא תרו-תרטז."},{"i":29689,"n":"מונק, ליב מגריידיץ","f":"צבי הירש תאומים","b":"רב בגריידיץ,קראטשין-ת\"ל"},{"i":29690,"n":"מונק, מאיר","f":"אליהו הכהן מאלטונה","k":"בעל בגדי שש","bt":"תרכט","bp":"אלטונה","dt":"תרפט","b":"רב וד\"ר למתמטיקה. חתן ר שמואל שמלקא רוקח מלמברג. אחיינו של ר עזריאל הילדסהימר. מראשי אגו\"י בגליציה. רב בברלין, ביקר בירושלים ונפטר שם. חיבר \"זה אלי ואנוהו\" בגרמנית (וציוה שלא לתרגמו). חיבר \"בגדי שש\" חיפה תשכט.","bk":[["זה א - לי ואנוהו - פילופספיא",""],["טו מעלות יחיאל - צוואת אבי אביו והקדמה וסדר היחוס משלו",""]]},{"i":29691,"n":"מונק, מתתיה הכהן מפוזנא","f":"יחיאל מיכל מדנציג","bt":"תקעד","dt":"תרטו","b":"מצאצאי בעל \"בית מאיר\". תלמיד ר עקיבא איגר, ר טוביה אשע בעל \"עט ברזל\". רב בכמה קהלות במחוז פוזנא. פרסם מאמרים ב\"שומר ציון הנאמן\". הניח חבורים בכת\"י. בניו - ר משה חריף הכהן מגאלוב, ר מיכל ליב (יחיאל אריה) בעל מאורן של ישראל."},{"i":29692,"n":"מונק, נתן פייטל מהוצפלוץ","dt":"תפד - ט אלול","b":"רב בהוצפלוץ-תמ\"ו,אוסרליץ-תנ\"ז"},{"i":29693,"n":"מונק, עזרא מברלין","b":"רב פעלים,רב בברלין,עלה לא\"י-תרצ\"ח"},{"i":29694,"n":"מונק, פנחס ליב מנייזץ ומטרסדור","bp":"לייפניק","dt":"תקצג","b":"תלמיד החת\"ס בדרזניץ. אשתו ממשפחת אשת החת\"ס שגדלה בביתו של החת\"ס, והיה סמוך על שלחן החת\"ס במטרסדורף - לפני תקסב. רב במטרסדורף. שליינינג-תקעא, נייזאץ(=נייזיץ)-תקעט. (השיג לחת\"ס - לבקשתו - הלכות רמב\"ן לנדרים)."},{"i":29695,"n":"מונק, צבי הירש מוארשא","f":"יהושע גרשון","k":"הו\"ל יגדיל תורה","b":"חתן האדמור מאמשינוב. הו\"ל ספר אחיו \"יגדיל תורה\"."},{"i":29696,"n":"מונק, צבי הירש ממזריטש","f":"בער מונק","b":"רב בשווערין,מזריטש-ת\"ק"},{"i":29697,"n":"מונק, שלמה","b":"מאמר עליו ב\"הלבנון\" - ירושלים-פאריס תרכג-תרמב - מאת ר שניאור זק\"ש."},{"i":29698,"n":"מונקאטש, יצחק מוערשאץ","k":"בעל אהל יצחק","b":"רב בווערשעץ-תק\"פ"},{"i":29699,"n":"מונש, משה מהולנד","b":"רב במעפיל(=מעפפל)-הולנד-תרע, אמערספורט-הולנד."},{"i":29700,"n":"מונשטר","k":"ראה: מוינשטר","b":"פרסם מאמרים ב\"אור תורה\" - ירושלים תרנז."},{"i":29701,"n":"מונשרוף, משה מבוכרה","f":"מאיר","dt":"תשיז","dp":"ירושלים","b":"רב בבוכרה, עלה לירושלים. מחכמי \"בית אל\". היה מקורב לר יוסף חיים זוננפלד. חתניו - ר יוסף בבליקי אב\"ד ירושלים, ור יעקב הכהן דוויק."},{"i":29702,"n":"מוס, ישראל יצחק","b":"ממקורבי ר שלמה מבובוב-תרנז (שהורה לו כיצד להתעשר מהגרלות פיס)."},{"i":29703,"n":"מוסא הלוי ממרוקו","f":"שלמה","b":"מחכמי מרוקו, התכתב עם ר יהודה ן עטר."},{"i":29704,"n":"מוסא מגרבה","f":"כמוס","b":"פרסם מאמרים ב\"קרן דוד\" - גרבה תרעו."},{"i":29705,"n":"מוסא ן, אברהם מסאלי","f":"שלמה","k":"בעל פירוש על נזיר","bt":"תכ","bp":"טיטואן","dt":"תסג - כא אדר","dp":"תוניס","b":"תלמיד ר מנחם עטייה. מקובל, רב בטיטואן, סאלי-תסו בזמן ר שלם ן צור ור אברהם בן מאיר ביבאס, עבר לפאס, ברח לתוניס, דרשן ודיין בתוניס. חיבר \"מקדש מלך\" על הזהר - עם 3 מחבריו, \"מנחת סוטה\". (באוצר הרבנים חי בשנת שס')"},{"i":29706,"n":"מוסא ן, דוד ממרוקו","b":"מחכמי מרוקו הקדומים."},{"i":29707,"n":"מוסא ן, חיים מספרד","f":"יהודה","k":"בעל מגן ורומח","bt":"קמ","bp":"ספרד","dt":"רכ","b":"רב בביגאר-ספרד, רופא מובהק, ומרביץ תורה בסלמנקה-רטו, והתווכח בארמונות עם חכמי הנוצרים, חיבר ספר \"מגן ורומח\" ובו תשובה לטענות נגד אמונת ישראל, בספר גם הדרכה כיצד להתווכח עם תיאולוגים נוצרים."},{"i":29708,"n":"מוסא ן, יהודה ממראקש","b":"רב במראקש, חתם על פס\"ד-תקמז."},{"i":29709,"n":"מוסא ן, יום טוב מספרד ושלוניקי","b":"חזן בספרד, לאחר הגירוש חזן בשלוניקי."},{"i":29710,"n":"מוסא ן, יצחק ממראקש","b":"מחכמי מראקש-מרוקו, עלה לארץ-שא, דרך מצרים - ושם נשא אשה."},{"i":29711,"n":"מוסא ן, יצחק מספרד","b":"מחכמי ספרד. הגיע לקושטא לאחר הגירוש-רנב."},{"i":29712,"n":"מוסא ן, משה ממרוקו ותונס","f":"אברהם","k":"בעל פלא יועץ","bt":"תן","bp":"מרוקו","dt":"תקטו - בערך","dp":"ירושלים","b":"מקובל, הגיע עם אביו ממרוקו לתונס, ולימד שם לתלמידים, עבר לאלגיר, עלה לצפת וירושלים. בשליחות הקהלה במרוקו, נשאר במצרים כמה שנים, חזר לירושלים. בימיו התארגן חוג מקובלים באלגיר והכניסו לעירם את נוסח האר\"י (ועל כך ב\"משחא דרבותא\" - לר מסעוד אלפסי). חיבר גם \"עובר לסוחר\", \"המלך שלמה\" ועוד. חיבר גם שירים."},{"i":29713,"n":"מוסא ן, משה מספרד","dt":"קפ","b":"מחכמי ספרד בזמן הריב\"ש שהביא ממנו בשו\"ת הריב\"ש. התגורר באוקליש, קלעת איוב. השתתף עם דון שמואל הלוי וחכמים נוספים, בויכוח בטורטושה-קעג עם המומר יהושע הלורקי. חיבר פירוש על יג מדות שהתורה נדרשת בהן."},{"i":29714,"n":"מוסא, יצחק מהמגרב","b":"מחכמי מארכש, עלה לארץ-שא. מכתב ממנו לאביו נתפרסם ע\"י מוהר\"י טולדנו בעל \"נר המערב\"."},{"i":29715,"n":"מוסאטי, יצחק חי מאנקונא","k":"בעל שירי זמרה","b":"גביר מחכמי אנקונא. חיבר \"שירי זמרה\" - ליוורנו. תלמיד ר יחיאל הכהן מאנקונא."},{"i":29716,"n":"מוסאיוף, שלמה מבוכרה","f":"יעקב","k":"בעל כל המצוה","r":"ראש ישיבת עץ חיים","bt":"תריב","bp":"בוכרה","dt":"תרפב - ח ניסן","dp":"ירושלים","b":"גביר מחכמי בוכרה, עלה לירושלים-תרן. ממיסדי שכונת רחובות הבוכרים בירושלים, את שטח השכונה קנה עם ר יוסף כוג'הינוף בעידודו של ר יעקב מאיר. הו\"ל סידור \"חקת עולם\". בעל ספריה ובה הרבה כתבי יד וספרים נדירים."},{"i":29717,"n":"מוסאפיר, יוסף מסרייבו","b":"דיין בסרייבו-תלב, עם ר יצחק ליווא ור דניאל קטן."},{"i":29718,"n":"מוסט, חיים שניאור זלמן","f":"משה יהודה","bt":"תרקמב","bp":"קרים","dt":"תשד","dp":"סלובודקה","b":"תלמיד ישיבת וולוזין. רב ביהכנ\"ס הויסמן בקובנא ב\"פלאן החדש\" והיה מורה ומטיף בחוגי המשכילים. עבר לוילנא בזמן מלחה\"ע ה-I וארגן משם יחד עם ד\"ר רחמילביץ את העזרה לפליטי קובנא. היה מראשוני החוזרים לקובנא - לאחר הכיבוש הגרמני, והחל בארגון הקהלה, פתח ת\"ת וניהלו, ולימד תלמוד בגמנסיה היהודית-של ד\"ר קרליבך. הקים עם פרופ' הרמן שטרוק את המועצה היהודית הדתית - נציגות יהודי ליטא בפני השלטון הגרמני. חבר באגו\"י וחובב ציון. נספה בשואה."},{"i":29719,"n":"מוסטובסקי, בנימין מנ\"י","b":"פרסם מאמרים ב\"נר מערבי\" - נ\"י תרפד - קובץ ישיבת ר יצחק אלחנן."},{"i":29720,"n":"מוסי (משה) מפאס","f":"מחפוטא (מדפוטא)","b":"מחכמי פאס-של. נזכר אצל ר משה אסולין בפאס, יחד עם ר משה אלשקר."},{"i":29721,"n":"מוסנזון, דב יהודה","f":"דוד מוסנזון","b":"רב בהידוצישאק-תר\"ל"},{"i":29722,"n":"מוסנזון, חיים גרשון","f":"נפתלי דוד מואראנאווא","b":"חתן ר שמואל חיים ויגרעראוויץ מקעלם."},{"i":29723,"n":"מוסנזון, ישראל מפיקאלן","b":"רב בפיקאלן."},{"i":29724,"n":"מוסנזון, נפתלי דוד (דב)","f":"דב יהודה מהידוצישוק","b":"נכד ר דוד מלצר (אחיו של ר מרדכי מלצר). מצאצאי האר\"י-מצד אמו. רב בפודזעלוי-פלך קובנא-תרמה, ואראנאווא-פלך וילנא. נסמך מאת: ר יצחק אלחנן מקובנא, ר שלמה הכהן מוילנא, ר מאיר מיכל משאט. בניו: ר חיים גרשון, ר שלמה מרדכי. חיבר חדושים על שו\"ע ודרושים - בכת\"י."},{"i":29725,"n":"מוסנזון, שלמה מרדכי","f":"נפתלי דוד מואראנאווא","b":"חתן הגביר ר אהרן נאוופרוצקי מואשלישוק."},{"i":29726,"n":"מוסנסון, דוד","b":"רב-שנת תר\"כ"},{"i":29727,"n":"מוססו, יעקב מאנקונא","dt":"שיו - יב תמז","dp":"אנקונא","b":"אחד מ-24 הרוגי אנקונא על פי עדות ר שלמה חזן מאנקונא. קינה לזכרם מאת ר אברהם דוד חי."},{"i":29728,"n":"מוספיה, אברהם חי","f":"חיים יצחק-חיים וחסד","k":"אחי\"ם-תהלה לדוד","bp":"ירושלים","b":"רב בספאלטו, מרבני ירושלים ויסד ישיבה \"שבת אחים\" (אחי\"ם = אברהם חי מוספיה) בעזרת הגביר משה פינצי מוינה ובראש הישיבה עמד ר אהרן עזריאל. חיבר \"תהלה לדוד\" ליוורנו תרכז. מחדושיו בספר אביו \"חיים וחסד\"."},{"i":29729,"n":"מוספיה, אברהם ממצרים","b":"גביר במצרים-שנות ה-תק'. אירח בביתו את ר חיים אביגדור בעל \"פרי עץ הדר\" בהיותו במצרים."},{"i":29730,"n":"מוספיה, אברהם משלוניקי","b":"גביר בשלוניקי, סייע בהדפסת \"בן ידיד\" - שלוניקי תקסו."},{"i":29731,"n":"מוספיה, בנימין דיאניזוס מספרד","f":"עמנואל","k":"בעל מוסף הערוך","bt":"שסו","bp":"ספרד","dt":"תלד-ה","dp":"אמשטרדם","b":"מאנוסי ספרד, רופא בהמבורג, גליקשטאדט, רופאו של מלך דניה ונורבגיה, עבר לאמשטרדם, רב שם, חיבר \"מוסף הערוך\" על ספר הערוך של רבי נתן איש רומי, \"זכר רב\" - לזכר אשתו. מתומכי ש\"ץ."},{"i":29732,"n":"מוספיה, דניאל חי מטימישואר","bp":"[שלוניקי]","dt":"תקיא - יט טבת","dp":"טימישואר","b":"מוצאו כנראה משלוניקי והגיע לטימישואר בתחילת המאה ה-18, מקובל חכמי הספרדים בטימישואר(=טמשוואר) והיה בחבורת המקובלים (שכל חכמיה היו ספרדים) והתקימה לפחות עד שנת תרב."},{"i":29733,"n":"מוספיה, חיים יצחק מאיטליה","k":"בעל חיים וחסד","bt":"תקך-ן תקיד","bp":"ירושלים","dt":"תקצז - ה-ז סיון","dp":"ספאלטרו","b":"נסע לבוסניה לטפל ברכוש אביו שנפטר, ושם היה תלמיד ר דוד פארדו בעל \"שושנים לדוד\", היה בשליחות ירושלים, נתמנה לרב בספאלטרו-איטליה-תקנו שם כיהן כששים שנה. חיבר \"חיים וחסד\" ליוורנו תרד - ובהקדמה רשם את קורותיו, ועוד בדפוס ובכתב יד, חיבר קונטרס \"מים חיים\" ובוא ספור התלאות שעברה על הקהלה בימי מלחמות נפוליאון. בניו: ר אברהם מטריאסט ור יעקב ירמיה על מקום אביו בספאלטרו."},{"i":29734,"n":"מוספיה, יהושע משלוניקי","k":"בעל שער יהושע","b":"מגדולי חכמי שלוניקי."},{"i":29735,"n":"מוספיה, יהושע שלומיאל עובדיה","f":"חיים","k":"בעל לב יהושע","b":"רב בשלוניקי. חיבר \"לב יהושע\" - נדפס בסוף \"ברכת יוסף\" שלוניקי."},{"i":29736,"n":"מוספיה, יוסף אליקים משלוניקי","k":"בעל שם יוסף","b":"מרבני שלוניקי-תק\"י"},{"i":29737,"n":"מוספיה, רפאל יעקב מסרייבו","b":"מראשי קהלת סרייבו-שנות ה-ת' - אחד משבעת טובי העיר."},{"i":29738,"n":"מוסקאטו, יוסף מאיטליה","b":"מחכמי איטליה-ש\"כ. בנו - ר יהודה."},{"i":29739,"n":"מוסקוביץ, אברהם חיים מברעזנא","b":"מחכמי ברעזנא-תרמב."},{"i":29740,"n":"מוסקוביץ, אברהם חיים מהערץ","f":"משה אריה ליב משאץ","k":"אדמור משאץ בהערץ","dt":"תשא - יב תמוז","b":"חתן ר יצחק איזיק מפודהייץ (זידיטשוב). רב ואדמור בהערץ-פלך דורוהוי-רומניה. נספה בשואה."},{"i":29741,"n":"מוסקוביץ, אלתר אהרן אריה","f":"יואל משאץ","k":"אדמור מפודול-אילואי","dt":"תרעא - ז אלול","b":"בן האדמור משאץ. חתן נכדת ר צבי אריה מאליק. אדמור בסוליצא בחיי אביו, עבר לפודול-אולואי. בנו ר בן ציון."},{"i":29742,"n":"מוסקוביץ, אפרים מסטמאר","f":"משה אהרן מטארקאן","b":"גביר בסטמאר. חתן ר יעקב גרינוולד."},{"i":29743,"n":"מוסקוביץ, בן ציון מפודול-אילוא","f":"אלתר אהרן אריה","k":"אדמור מפודול אילואי","dt":"תש..","dp":"יאסי","b":"חתן ר מנחם מנדל מאלסק. רב בפאדליא-תרע. נספה בשואה."},{"i":29744,"n":"מוסקוביץ, בצלאל יהושע מגלינא","f":"יחיאל מיכל מגלינא","k":"אדמור מגלינא","bt":"תר","dt":"תרעה - ה תמוז","dp":"בוליחוב","b":"חתן דודו ר חיים אברהם רדליך ממיקולייב (פרמישלן), ובזיוו\"ש חתן ר חיים מצאנז. תלמיד ר אברהם יעקב מסדיגורא. מקורב לאדמורי רוזין. נכד האדמור ר מאיר מפרימישלן ובנו של האדמור מגלינא. אדמור בגלינא-תרכז על מקום אביו. עבר לבוליחוב - בזמן מלחה\"ע ה-I. בנה בצפת בית מדרש והחזיק שם כולל. ההדיר \"לקוטי אמרים\" מרמ\"מ מויטבסק. וכן \"תוספתא למדרש פנחס\" עם הקדמה ממנו - למברג תרנו. חיבר \"ויעש בצלאל\" - בכתב יד. בנו ר חיים אדמור על מקומו אחריו, וחתנו ר יצחק צבי אפרתי על מקומו אחריו גם הוא."},{"i":29745,"n":"מוסקוביץ, גיטשא","f":"הדברי חיים","b":"אשת האדמור ר בצלאל יהושע מגלינא. בנה ר חיים האדמור מגלינא."},{"i":29746,"n":"מוסקוביץ, גרשון מנחם מטשטשוביץ","b":"חתן ר יהושע ברוך לנדא מביטשקוף. אב\"ד טשעטשוביץ. בנו - ר שמואל מפאלאד."},{"i":29747,"n":"מוסקוביץ, דוד מנאסוד ותל אביב","f":"אברהם יצחק","k":"בעל רגלי מבשר-תרפא","bt":"תרכט","bp":"כפר סקערניצא-מארמארוש","dt":"תשיט - ד אד\"א","b":"חתן ר מרדכי ורצברגר. שו\"ב בבורגו-פרונד-ליד ביסטריץ, רב בנאסוד-תרס, התקרב לציונות וסייע לר משה שמואל גלזנר מקלויזנבורג-מנהיג הציונים הדתיים, ועסק בהטפה לשיבת ציון ברחבי אירופה. היה במחלוקת עם האדמור והרב של נאסוד ר אברהם יהושע פריינד כאשר תמך בחסידי ויזניץ בנאסוד כנגד האדמור מנאסוב, ואף ערך חוברות \"משפט לעשוקים\" ו\"עקד הרועים\" - סאמאשאויואר-תרע בענין זה. עלה לארץ-תרצה והתישב בתל אביב, וכיהן כרב שכונת פלורנטין. חיבר גם \"\"גלילי זהב\" ועוד."},{"i":29748,"n":"מוסקוביץ, חיים זלמן מטאקאי","f":"צבי הירש","k":"בעל גיא חזיון","dt":"תרצו - א תמוז","dp":"טאקאי?","b":"תלמיד ר אלעזר לעוו בעל פקודת אלעזר, ותלמיד דודו בעל שמן אפרסמון בפוטנאק, תלמיד בעל שבילי דוד בוויצען, ר שמעון סופר מערלוי. חתן ר בנימין גרינפלד מבוסרמין וישב אצל חותנו 4 שנים והיה מקורב לבעל תשובות מוהרא\"פ שמינהו למו\"צ. נסמך מאת בעל יד יצחק ומבעל נחל שורק ומרבותיו בעל כתרי אפרסמון ובעל פקודת אלעזר. דיין ומו\"צ בטאקאי-תרנד עד פטירתו (כ-40 שנה). בנו - ר יעקב צבי הו\"ל את ספר אביו \"גיא חזיון\". גיסו ר צבי וייס מדאביאווא. בנו גם - ר ברוך. חתניו - ר מרדכי אפשטין מסילאדי קראסנא, ר אברהם רוזנבוים, ר מרדכי מאנדל, ר מנחם זאב שיק מטאקאי."},{"i":29749,"n":"מוסקוביץ, חיים יואל מסמבור","f":"מרדכי יוסף משה","k":"אדמור מסמבור","bt":"תרמח","dt":"תשא - ב אדר","dp":"טרבלינקה","b":"חתן ר יהודה צבי יולס מסמבור. אדמור מסמבור-תרעט על מקום חותנו. נספה בשואה."},{"i":29750,"n":"מוסקוביץ, חיים מגלינא","f":"בצלאל יהושע מגלינא","k":"אדמור מגלינא","bt":"תרמח","dt":"תרפא","b":"אדמור מגלינא-תרעה על מקום אביו. חתן דודו ר שלום הלברשטט מרצפרט."},{"i":29751,"n":"מוסקוביץ, יהודה ליב","dt":"תרסט","dp":"ברלין","b":"גיסו של ר חיים עוזר גרודזנסקי."},{"i":29752,"n":"מוסקוביץ, יהושע בצלאל מגלינא","f":"מיכל מגלינא","b":"רב בגלינא-תרע\"ד"},{"i":29753,"n":"מוסקוביץ, יואל משאץ א","f":"חיים מסטנוב","k":"אדמור משאץ","bt":"תקע","dt":"תרמו - יג ניסן","b":"נינו המגיד מזלטושוב. חתן ר מאיר מפרמישלן. אדמור בוורניפקא(=ויברניפקה)-ליד למברג, עבר לסוליצא-רומניה, שאץ-בוקובינה."},{"i":29754,"n":"מוסקוביץ, יואל משאץ ב","f":"מאיר משאץ","k":"אדמור משאץ-לונדון","r":"אדמו\"ר משאץ","bt":"תרסז","bp":"שאץ","dt":"תשם - יז תשרי","b":"נכד ר אברהם דוד מבוצאץ - והו\"ל את ספרי זקנו. עבר מדעש ללונדון-תרץ. וכיהן כרב ואדמור משאץ בלונדון, מונטריאול-תשט, עלה לירושלים-תשכח. חתן גיסו (או בן דודו) ר שלום מוסקוביץ משאץ-לונדון. ההדיר ספר זקנו - דעת קדושים - \"אשל אברהם\". בניו: ר משה מאיר ממונטריאול-חתן ר נחום אשכנזי מחאטין על מקומו אחריו במונטריאול, ר יעקב יצחק מירושלים-חתן ר אפרים רובין."},{"i":29755,"n":"מוסקוביץ, יוסף דוד משאץ","f":"יצחק משאץ","k":"אדמור משאץ-סאסוב נ\"י","bt":"תרסג","dt":"תשמו","dp":"ירושלים","b":"חתן ר שמואל מרעדים (דינוב). קרובו של ר יואל מוסקוביץ משאץ במונטריאול. אדמור משאץ-סאסוב בניו יורק. חיבר \"תיקון עירובין\" ניו יורק תשיט."},{"i":29756,"n":"מוסקוביץ, יוסף מאיסטריק","f":"מאיר מזבורוב","k":"אדמור מאיסטריק","bt":"תרל","dt":"תרץ","b":"רב ואדמור באיסטריק-תרס. בנו ר משה אפרים רב בסוקוליקי ויבורוזנה."},{"i":29757,"n":"מוסקוביץ, יוסף שמואל מאונגוואר","f":"צבי מפאלאץ","bt":"תרד","bp":"פאלאץ (פבלביץ)","dt":"תרצא - כז אלול","b":"תלמיד הכת\"ס, ו מנחם א\"ש מאונגוואר. חתן ר שמואל קרויס מואגאש. רב בטעגען-תרנח, אונגוואר."},{"i":29758,"n":"מוסקוביץ, יחזקאל מהורדנא","k":"בעל יד יחזקאל","b":"רב בהורדנא, ניו יורק-תרפז."},{"i":29759,"n":"מוסקוביץ, יחזקאל שרגא מטשעפרעג","f":"דוד הכהן ממאקווא","dt":"תשד","b":"רב בטשעפרעג. אביו נקרא גם בשם רפפורט."},{"i":29760,"n":"מוסקוביץ, יחיאל מיכל מגלינא","f":"משה בן חיים מסטנוב","k":"אדמור מגלינא-קב ונקי,אדמור מגלינא","bt":"תקעח בערך","dt":"תרכז - כו כסלו","b":"נכד המגיד מזלוטשוב. חתן ר מאיר מפרימישלן. אדמור בגלינא. בנו ר בצלאל יהושע על מקומו כאדמור גלינא. חיבר \"קב ונקי\" מונקטש תרסז. ?? לא באוצר ??","bk":[["קב ונקי - על התורה",""]]},{"i":29761,"n":"מוסקוביץ, יחיאל מיכל מהורודנקא","f":"מרדכי יוסף משה","k":"אדמור מהורודנקא","bt":"תרן","dt":"תשג - כז אלול","b":"חתן ר חיים לייפר מנדבורנא סטניסלב. אדמור בהורודנקא-תרפז. נספה בשואה."},{"i":29762,"n":"מוסקוביץ, יחיאל מיכל מניו יורק","f":"שלום משאץ-לונדון","k":"אדמור משאץ","r":"אדמו\"ר משאץ - מעליץ","bt":"תרסח","dt":"תשיז","b":"ניצל מהשואה ועבר למנצסטר. חתן ר אליעזר הורביץ ממעליץ. היה אדמור משאץ בניו יורק.","bk":[["דרך ים - ש\"ס ופוסקים רמב\"ם ונושאי כליו",""]]},{"i":29763,"n":"מוסקוביץ, יחיאל מיכל מקוזלוב","b":"נכד אדמור ר מאיר מפרימישלן. רב בקוזלוב-תרף."},{"i":29764,"n":"מוסקוביץ, יחיאל מיכל משאץ","k":"אדמור משאץ בניו יורק","b":"אדמור משאץ בנ\"י, אחיינו של האדמור יצחק מוסקוביץ מראדוויץ בניו יורק. חיבר \"דרך ים\"."},{"i":29765,"n":"מוסקוביץ, יעקב יצחק משאץ","f":"יואל משאץ","k":"אדמור משאץ בירושלים","b":"אדמור משאץ בירושלים על מקום אביו. חתן ר אפרים רובין."},{"i":29766,"n":"מוסקוביץ, יעקב צבי","f":"חיים זלמן-גיא חזיון","k":"הו\"ל גיא חזיון","b":"חתן ר יהודה אלטמן בעל \"ים של יהודה\". הו\"ל ספר אביו - גיא חזיון. בניו - יהודה, חיים שלמה זלמן."},{"i":29767,"n":"מוסקוביץ, יצחק זאב מחוסט","b":"מחכמי חוסט?"},{"i":29768,"n":"מוסקוביץ, יצחק מניו יורק","f":"מאיר","k":"בעל אמרי מאיר","b":"נכד ר דוד'ל מבריד."},{"i":29769,"n":"מוסקוביץ, יצחק מקראקא","f":"שלום משאץ","bt":"תרס","dt":"תרצא","dp":"לונדון","b":"חתן ר אריה ליבוש מרדכי הלברשטט משיניבה, התגורר בקראקא."},{"i":29770,"n":"מוסקוביץ, יצחק משאץ-רדוביץ","f":"מאיר משאץ","k":"אדמור מרדוביץ","bt":"תרלח-ם","dt":"תשיח - ל שבט","dp":"ניו יורק","b":"חתן ר יוסף דוד מייאר מסאסוב (אלעסק). תלמיד האדמור משינאווא. אדמור ברדוביץ-בוקובינה,.ניצל מהשואה ואחריה הגיע לארה\"ב וכיהן שם כאדמור משאץ-ראדוביץ. בניו - ר יוסף דוד, ר שלום שניהם על מקומו אחריו בניו יורק ובלוס אנג'לס. חתנו בזיוו\"ש - האדמור ר יוחנן פרלוב מקרלין-סטולין. צוואתו בספר בנו \"תקון עירובין\"."},{"i":29771,"n":"מוסקוביץ, ישעיה","f":"אברהם אבא מדרוהוביטש"},{"i":29772,"n":"מוסקוביץ, ישראל אלימלך מטורקא","f":"מאיר מזבורוב","k":"אדמור מטורקא","bt":"תרלז","dt":"תשיד - יח אד\"ב","b":"נסמך מאת: מהרש\"ם מברזאן, ר אברהם מנחם שטינברג מברודי, ר אברהם בנימין וייס מטשרנוביץ, ר ליב ברוידא מלבוב. חתן ר שלום יולס ממושציסק וסטרי (שושלת סמבור). עבר לסטרי עם חותנו והיה שם רב לצדו, רב בטורקא-תרסח, עבר להונגריה-במלחה\"ע ה-I וכיהן כאדמור, עבר לארה\"ב-תרפג וכיהן כאדמור מזבורוב בארה\"ב. חיבר \"נר ישראל\" ניו יורק תרצו. ?? לא באוצר ??"},{"i":29773,"n":"מוסקוביץ, ישראל יעקב מלונדון","f":"מאיר אדמור משאץ","k":"אדמור משאץ,בעל שארית יעקב","bt":"תרנג","bp":"שאץ","dt":"תשיד - כט אד\"א","dp":"לונדון","b":"חתן ר סיני הלברשטט מזמיגרוד (שושלת צאנז). אדמור משאץ על מקום אביו. ניצל מהשואה, עבר לפריס, עלה לארץ-תשי והתישב בחיפה."},{"i":29774,"n":"מוסקוביץ, כתריאל מזדונסקי-ואלי","b":"פרסם מאמרים ב\"כרמנו\" - אלכסנדר-לודז תרצג."},{"i":29775,"n":"מוסקוביץ, מאיר מזבורוב","f":"יחיאל מיכל מגלינא","k":"אדמור מזובורב","bt":"תרה","dt":"תרעה - כא חשון","dp":"אויהל","b":"חתן ר ישראל אלימלך אונגר מזבנא (דומברובא). אדמור בזבורוב-תרלד. ברח להונגריה במלחמת העולם הראשונה והיה בטורקא, קראלי-העלמיץ-הונגריה, ושם נפטר."},{"i":29776,"n":"מוסקוביץ, מאיר משאץ","f":"יואל משאץ","k":"אדמור משאץ","bt":"תריג","dt":"תרפא - כג אד\"א","dp":"שאץ","b":"נכד ר מאיר מפרימישלן, ומצאצאי ר יחיאל מיכל מזלוטשוב. חתן ר יצחק בצלאל רובין מברודי (שושלת רופשיץ) ונכדתו של השר שלום מבלז, ובזיוו\"ש חתן ר יעקב יצחק מפאלטישאן (בוצאץ). אדמור בשאץ-תרמה, ובנו ר יעקב על מקומו אחריו."},{"i":29777,"n":"מוסקוביץ, מיכל מגלינא","b":"אדמו\"ר בגלינא-תר\"ל"},{"i":29778,"n":"מוסקוביץ, מיכל מהורדנקה","f":"יהושע בצלאל מסקוביץ","dt":"תשג","b":"רב בהורדנקה"},{"i":29779,"n":"מוסקוביץ, מנחם גרשון מצצוביץ","f":"יעקב דוד","dt":"תשד","b":"תלמיד ר שמעון ארנפלד ממיהאלביץ. חתן ר יהושע ברוך רייניץ מצ'צ'וביץ גלאסץ (בחת\"ס ותלמידיו מופיע טשרנוביץ?). רב גליל צ'צ'נוביץ(=טשעטשעוויץ) על מקום חותנו."},{"i":29780,"n":"מוסקוביץ, מרדכי יוסף משה","f":"יואל משאץ","k":"אדמור מסוליצא בוטושן","bt":"תרך","dt":"תרפט - יא סיון","b":"אדמור בסוליצא ואדמור מסוליצא בבוטושאן. חתן ר נפתלי רובין מרדיכוב, ובזיוו\"ש חתן ר אליעזר צבי מקומרנא."},{"i":29781,"n":"מוסקוביץ, מרדכי מליפקן","dt":"תשג","b":"רב בליפקן"},{"i":29782,"n":"מוסקוביץ, מרים חיה משאץ","f":"מאיר מפרימישלן","k":"אדמורית משאץ","bp":"שאץ","dt":"תרסג - כה אדר","b":"אשת האדמור יואל בן חיים משאץ. נודע כחכמה וצדקת עוד בחיי אביה האדמור מפרימישלן, ולאחר פטירת בעלה נהגה אדמורות וצדיקי הדור נהגו למסור לה פתקאות ופדיונות."},{"i":29783,"n":"מוסקוביץ, משה אהרן מטארקאן","b":"גביר מחכמי טארקאן. בנו - הגביר ר אפרים מסטמאר (דודו של אשר אנשל גרינוולד בעל מטה אשר - הכותב עליו במכתב)."},{"i":29784,"n":"מוסקוביץ, משה אפרים מסוקוליק","f":"יוסף מזבורוב ואיסטרי","bt":"תרסט","bp":"איסטריק","dt":"תשב","dp":"קאשיצה-ליד גוסלב","b":"חתן ר שלמה חיים פרלוב מבוליחוב (שושלת נסכיז). עסקן באגודת ישראל, יסד את פרחי אגו\"י-תרצד, והקים את התנועה \"זריזים\" - לחיזוק הפעילות התורנית של אגו\"י, ויסד רשת ישיבת בשם \"נצח ישראל\" ובה כ-35 ישיבות קטנות. רב בסוקוליקי-תרצב, יבורוזנה(=יאבורנה)-תרצח. ייסד לימוד תנ\"ך יומי בפולין. נספה בשואה. פרסם במספר כתבי עת מאמרים ושירים. מספוריו ב\"אודים\" ירושלים תשך. עורך: \"תלפיות\" - טרנוב תרצח."},{"i":29785,"n":"מוסקוביץ, משה אריה ליב משאץ","f":"מאיר משאץ","k":"אדמור משאץ","bt":"תרמה","bp":"שאץ-פלך בוקובינה","dt":"תשיד - כד ניסן","b":"חתן ר נחום ברנדוין מבורשטין (שושלת סטרטין). אדמור משאץ בטשרנוביץ. ניצל מהשואה ועבר לארה\"ב-תש. בניו - ר אברהם חיים מהערץ הי\"ד, ר יואל-חתן האדמור משנדישוב הי\"ד - נספו בשואה."},{"i":29786,"n":"מוסקוביץ, משה מאיר משאץ","f":"יואל משאץ","k":"אדמור משאץ","b":"אדמור משאץ במונטריאול על מקום אביו. חתן ר נחום אשכנזי אדמור בחאטין."},{"i":29787,"n":"מוסקוביץ, נפתלי ממעליץ אשדוד","f":"יחיאל מיכל בן שלום","k":"אדמור משאץ באשדוד","b":"נכד האדמור ר שלום משאץ-לונדון. חתן ר נחמן כהנא מספינקא. אדמור משאץ באשדוד"},{"i":29788,"n":"מוסקוביץ, צבי מהאדהאז","f":"יצחק מושקוביץ-מולנר","k":"בעל כתר שם טוב","bt":"תריז","bp":"טשעלעי","b":"תלמיד השב\"ס. חיבר \"פרחי נעורים\". מחכמי האדהאז-תרמב."},{"i":29789,"n":"מוסקוביץ, צבי ממרגרטן וירושלים","f":"זאב","k":"בעל ברכה משולשת-תרצט","bt":"תרסז","bp":"אויבר-ווישווה","dt":"תשמג - ג שבט","dp":"ירושלים","b":"תלמיד בעל \"קרן לדוד\" בווישווה וסטמר, ור שמואל זלמן וינברגר במארגרטן. חתן ר אריה ליבוש לנדמן מסערט, מחכמי מארגרטן ומדפיס בבית דפוסו שם. ניצל מהשואה ואחריה חזר להדפיס במארגרטן (ובהם שהחל בהדפסתם לפני השואה). הו\"ל כתב עת \"קובץ מפרשי התורה\"-תרצג, \"דגל התורה\" - מארגרטן תרצו, \"קבוצי בחורים\" - מארגרטן תרצד, עלה לירושלים והו\"ל כתב עת \"אוצרות ירושלים\" במשך 28 שנה. חיבר הדפיס והו\"ל ספרים רבים."},{"i":29790,"n":"מוסקוביץ, שלום משאץ-לונדון","f":"מרדכי יוסף מסוליצא","k":"אדמור משאץ-לונדון","r":"אדמו\"ר משאץ - לונדון","bt":"תרלח","bp":"ווברניפקא","dt":"תשיח - כב טבת","dp":"לונדון","b":"מצאצאי השר שלום מבלז. נסמך מאת: מהרש\"ם מברזאן. חתן דודו האדמור ר מאיר מוסקוביץ משאץ. מגדולי חסידי בלז. רב בשאץ-תרסג ומתלמידיו מהר\"ם שפירא. רב קהלת \"קהל יראים\" בקלן-תרף, טורנא, עבר ללונדון-תרפז ושם כיהן כאדמור משאץ-לונדון. חיבר \"הגהות דעת שלום\" ירושלים תשיח, \"הלכה ברורה\", \"אור הגנוז\". בניו ר יצחק, ר יעקב, ור יחיאל מיכל - ונפטרו על פניו. (באהלי שם מופיע שם אביו - משה). מתלמידיו - ר מאיר שפירא מלובלין.","bk":[["אור גנוז – תורה ומועדים",""],["בית שלום – שו\"ת",""],["גנזי נסתרות – שו\"ת",""],["דעת שלום – פרק שירה וגליונות",""],["הגהות – מנחת חינוך",""],["הגהות והערות – רבינו בחיי",""],["ויאמר שלום – נודע ביהודה",""],["דעת שלום (שאץ)",""]]},{"i":29791,"n":"מוסקוביץ, שלום משאץ-רדוביץ","f":"יצחק משאץ-רדוביץ","k":"אדמור משאץ לוס אנגלס","b":"אדמור בלוס אנג'לס"},{"i":29792,"n":"מוסקוביץ, שלמה ממונקטש","b":"פרסם מאמרים ב\"אהל שם\" - רומניה תשב - תשה."},{"i":29793,"n":"מוסקוביץ, שמואל יחיאל מיכאל","f":"מנחם גרשן מצ'רנוביץ","dt":"תשד - יג חשון","dp":"אושוויץ","b":"תלמיד הדעת סופר. חתן קרובו ר מרדכי רייניץ מנאדי-פאלאד, רב בנאדי-פאלאד-תרפז על מקום חותנו. נספה בשואה."},{"i":29794,"n":"מוסקוביץ, שמואל מפאלאד","f":"גרשון מנחם מטשטשוביץ","b":"חתן ר מרדכי רייניץ מפאלאד. אב\"ד פאלאד."},{"i":29795,"n":"מוסקוביץ, שמואל צבי מאונגואר","dt":"תרח","b":"ראב\"ד באונגוואר"},{"i":29796,"n":"מוסקוביץ-רפפורט, ברוך צבי הכהן","k":"בעל ויברך דוד","r":"אב\"ד ור\"מ פאקש ובודאפעסט","bt":"תרסז","dt":"תשן - ח טבת","b":"תלמיד בעל \"קרן לדוד\" מסטמר. חסיד ויזניץ, מונקטש, בלז, ומקושר לר יואל מסטמר. ניצל מהשואה ואחריה כיהן כאב\"ד בפאקש והקים שם ישיבה (גם בזמן הקומוניסטים), ראב\"ד בבודפשט-תשיז, עבר לוינה-תשיט. ניו יורק. חיבר גם \"מהולל בתשבחות\", \"לדוד ברוך\", \"תנובות ברוך\", ועוד. חברם מילדות של האדמור מפאפא בעל \"ויחי יוסף\" והאדמור מסטמר בעל \"ברך משה\".","bk":[["תנובות ברוך - שו\"ת ודרוש",""],["משמרת צבי",""],["תנובות ברוך ב",""],["תנובות ברוך ג",""],["תנובות ברוך ד",""],["תנובות ברוך ה",""],["תנובות ברוך תניינא א",""],["תנובות ברוך תניינא ב",""],["תנובות ברוך תניינא ג",""],["תנובות ברוך תניינא ד",""]]},{"i":29797,"n":"מועד, דוב מירושלים","dt":"תשיג","b":"מגדולי חכמי ירושלים"},{"i":29798,"n":"מועטי, אהרן מאלגיר","f":"אברהם","k":"בעל קרבן אהרן","bt":"תצו - בערך","dt":"תקלב","b":"דיין באלגיר."},{"i":29799,"n":"מועטי, דוד מאלגיר","f":"שמואל","k":"בעל נאום דוד","bt":"תקנו","dt":"תרלו","b":"מחכמי אלג'יר, דיין, ראש ישיבה. חיבר גם \"ידי דוד\", \"קדשי דוד\", ועוד. מתלמידיו: ר מסעוד גוזלאן מקצמטינא. נחשב לסוף הוראה באלגיר - גדולי הרבנים שאחריו באו ממרוקו.","bk":[["לבב דוד","מפרשי רמב\"ם"],["אשר לדוד – שו\"ע",""],["ידי דוד – נזיר",""],["לבב דוד – רמב\"ם",""],["נאם דוד – רמב\"ם",""],["שלל דוד – רמב\"ם",""],["אשר לדוד [על שו\"ע]",""],["נאם דוד",""],["שלל דוד",""],["נאם דוד","מפרשי רמב\"ם"],["שלל דוד","מפרשי רמב\"ם"]]},{"i":29800,"n":"מועטי, דוד מאלגיר","f":"אהרן","dt":"תקץ - בערך","dp":"ליוורנו","b":"חתן ר אברהם בושערא בעל \"ברית אברהם\". רב באלגיר, עזב לאחר המאורעות-תקסה-תקעה ועבר לליוורנו. הסכים שם עם רבני ליוורנו על \"אשר הנחלים\" - תקפא. היה מחלוקת כנגדו בליוורנו ונדפסו כנגדו ב\"חסד לאומים\". חיבר הקדמה ל\"ברית אברהם\" לחותנו."},{"i":29801,"n":"מועטי, יהודה מאלגיר","f":"יהודה","k":"בעל ישיר משה","bp":"אלגיר","dt":"תלה","dp":"אלגיר","b":"מחכמי אלגיר(העיר), רב בקצמטינא, וחזר לאלגיר. היה בקשרי הלכה עם ר שלמה צרור. לפי החיד\"א - חיבר \"ישיר משה\" והוא פירוש לאזהרות ר יצחק בן ראובן אלברצלוני."},{"i":29802,"n":"מועטי, יהודה מאלגיר","f":"דוד","b":"רב ודיין באלגיר. נזכר ב\"אשכבתא דרבנן\" לליל כפור באלגיר. העתיק בכתב ידו מחזור מנהג אלגיר."},{"i":29803,"n":"מועטי, יהודה מאלגיר","dt":"תקפו","b":"פייטן רב ומקובל בווהראן ומכונה \"מול לבלאד\" - ראש העיר. מפיוטיו בספרי יהודי אלגיר. שיר לכבודו מאת ר דוד אמסלם מפיגיג."},{"i":29804,"n":"מועטי, יום טוב מאלגיר","b":"רב באלגיר. נזכר ברשימת רבני אלגיר."},{"i":29805,"n":"מועטי, יוסף","k":"בעל שם יוסף","r":"דיין ומו\"צ בסוסא - מרבני צפון אפריקה","dt":"תרל","b":"דיין בסוסה(תוניס)","bk":[["שם יוסף [עהש\"ס ורמב\"ם",""],["שו\"ת על שו\"ע]",""],["שם יוסף - ש\"ס",""]]},{"i":29806,"n":"מועטי, יוסף מאלגיר","bt":"ת","dt":"תע - בערך","b":"רב באלגיר. חתם בשם הקהלה על רכישת בית העלמין \"מדרש\"-תנא."},{"i":29807,"n":"מועטי, יצחק מאלגיר","f":"מסעוד","bt":"תע","dt":"תקם - בערך","b":"רב דיין ומשורר באלגיר. פיוט ממנו במחזור אלגיר. נזכר אצל ר אברהם מאיר מתלמסאן בספרו על קהלת תלמסאן (בצרפתית)."},{"i":29808,"n":"מועטי, שאול מאלגיר","f":"[שמואל]","bt":"תקס","dt":"תרלו","b":"רב באלג'יר-תרו, וחתם עם רבני אלג'יר. הסכים על \"פתח הבית\". אחיו של ר דוד ן שמעון בעל \"צוף דבש\" והספידו בספרו."},{"i":29809,"n":"מועטי, שלמה מאלג'יר","bt":"תקם - בערך","dt":"תרי - בערך","b":"רב באלג'יר. חיבר ספר על הלכות ומנהגים - בכת\"י."},{"i":29810,"n":"מועלם, חיים","b":"מחכמי ורבני בגדאד,סופר חתן ר' שמואל מג'לד"},{"i":29811,"n":"מועלם, יחזקאל מאיר מבגדד","f":"רחמים","k":"בעל ליקוטי אמרי אל","b":"חיבר גם \"ליקוטי אמרי אמת\"."},{"i":29812,"n":"מועלם, שאול משה סלימן דוד חי","k":"בעל לחם אבירים","r":"האדמו\"ר מסלונים הי\"ד","bt":"תרע","bp":"בגדד","dt":"תשלט - כסלו","b":"תלמיד \"בית זלכה\". תלמיד ר יהודה פתייה בקבלה. חזן שו\"ב ומוהל. עלה לירושלים-תשי ועסק בקבלה, ולימד בישיבות \"פורת יוסף\" ו\"הר ציון\". יסד ישיבת \"בן איש חי\". הו\"ל סספרי חכמי בבל עם הקדמה ממנו."},{"i":29813,"n":"מוציק, יעקב - יענקיל דיין","k":"בעל אמת ליעקב","bt":"תצט","dt":"תקץ - ה סיון","b":"חתן ר שמואל זנויל וייל מראפשויהר. רב באלזס, רבה של מחוז ריין תחתון-תקסב, וחבר בסנהדרין של נפוליאון. רב בשטרסבורג על מקום ר דוד זינצהיים. ספר תשובותיו נדפס בשם \"אמת ליעקב\"-תשסו עם תולדותיו."},{"i":29814,"n":"מוצך, אשר מפרשבורג","b":"מחכמי פרשבורג בזמן החת\"ס שהתאבל עליו בפטירתו."},{"i":29815,"n":"מוצן, אברהם חיים מהאלמין","f":"יצחק שטמפל מבאניהאד","bp":"באניהאד","dt":"תרנח - טז תשרי","b":"תלמיד החת\"ס והכתב סופר. גיסו של ר מרדכי טוטשטיין מהאלמין ונתמנה לדיין בהאלמין. ויש תאריכים שונים ליום פטירתו (בחכמי טרנסילבניה מופיע תרנב - ב או ה ניסן)"},{"i":29816,"n":"מוצנר, אבא מזאטור","bp":"זאטור","dt":"תרפה","b":"רב נאור באנדריכוב-תרסו."},{"i":29817,"n":"מוצנר, אלישע הכהן מפודגורזע","b":"מחסידי בובוב בפודגורדע."},{"i":29818,"n":"מוצנר, יוסף מנחם מרוזניאטוב","f":"דוד הכהן מקראקא","dt":"תש..","b":"חתן ר משה צבי נבנצאל מסטניסלב. רב ברוזניאטוב והקים שם ישיבת בובוב. נספה בשואה."},{"i":29819,"n":"מוצנר, יצחק מארלי","f":"משה מארלי","b":"רב בארלי-ליד קראקא."},{"i":29820,"n":"מוצנר, יצחק מרישא","b":"רב ברישא - תשובה אליו בטוט\"ד."},{"i":29821,"n":"מוצנר, מנחם מנדל מקראקא","bt":"תרסט","bp":"קראקא","b":"למד בביהמ\"ד בברלין-תרצה, מורה בברלין. נאסר בברגן בלזן ושוחרר. עלה לארץ."},{"i":29822,"n":"מוצנר, משה מארלי","b":"מחכמי ארלי-ליד קראקא."},{"i":29823,"n":"מוצען, יצחק","k":"בעל נטעי בחורים","b":"רב בניו יורק. עורך הירחון \"נטעי בחורים\" נ\"י תשכו."},{"i":29824,"n":"מוצפי, דוד מבגדד","b":"מחכמי בגדד - שנות ה-תר', תלמיד ר שמעון אגסי."},{"i":29825,"n":"מוצפי, יעקב מבגדד","b":"רב בבגדד"},{"i":29826,"n":"מוצפי, משה עזרא מבגדד","b":"מחכמי בגדד והיה סגי נהור. תלמיד ר עבדאללה סומך. מחכמי \"בית זילכה\" בבגדד, וכיהן כרב על מקום ר אלישע דנגור. נכדו - ר יעקב מוצפי."},{"i":29827,"n":"מוצפי, עבדאללה מבגדד","b":"מחכמי בגדד-תקלד."},{"i":29828,"n":"מוצפי, ציון מאיר מבגדד","dt":"תרפז - כז אלול","b":"תלמיד ה\"בן איש חי\". מחכמי בגדד-תרכט. בנו ר סלמאן מוצפי."},{"i":29829,"n":"מוצרי, אברהם אלברט ממצרים","dt":"תרצג - כד שבט","b":"חתן מלכיאל מני ממצרים. למד רפואה בפאריס, ממיסדי ההסתדרות הציונית במצרים, הו\"ל עתון \"ישראל\"."},{"i":29830,"n":"מוצרי, אליהו מאלכסנדריה","dp":"טבריה","b":"רבה של נא אמון(=אלכסנדריה), עלה לארץ והתישב בטבריה, נזכר על ידי ר מרדכי גלנטי בספרו \"גדולת מרדכי\" בתשובתו לחכמי טבריה."},{"i":29831,"n":"מוצרי, חיים נסים רפאל משירון","f":"אליהו מאלכסנדריה","k":"בעל באר מים חיים","bt":"תקיח","bp":"אלכסנדריה","dt":"תקסא-ב -כט אלול","dp":"טבריה","b":"מאלכסנדריה עלה לצפת ולמד אצל ר יצחק אבולעפיה, אחרי רעידת האדמה-תקמה עבר לטבריה, בשליחות צפת בתורכיה-תקכט ושהה שם כ-7 שנים, התישב בשלוניקי, רב בשירון(=שיריס), שלוניקי, לאריסה. ולפי רוזניס נפטר בשלוניקי תקעב בערך. תשובות ממנו מהיותו בסופיה. חיבר \"באר מים חיים\" שלוניקי תקנה ובנו ר משה ונכדו הדפיסו, תקנד-תקעד. נספד בספר \"עין המים\" לתלמידו ר רפאל יעקב משה. בהיותו בלאריסה פסק דין מיתה ליהודי מלשין - ורבני שלוניקי הסכימו עמו ובהם: ר יוסף אברהם ן יעיש, ר אבהם גטניו, ר חיים יוסף ן ארדיט, ר יהודה בכר שמואל, ר חיים ברוך סאפורטה, ור יעקב מנשה. הסכים על \"כוכבא דשביט\"-תקנט. בניו - ר אליהו נסים, ר שמואל שהדפיסו את ספריו אחר פטירתו."},{"i":29832,"n":"מוצרי, יוסף ביי ממצרים","bt":"תרכט","bp":"קהיר","dt":"תרצד - ז שבט","dp":"קהיר","b":"גביר, ומראשי הקהלה היהודית בקהיר."},{"i":29833,"n":"מוצרי, יעקב ממצרים","f":"נסים ביי","bt":"תרמד","bp":"קהיר","dt":"תרצד - יח אייר","dp":"קהיר","b":"מלומד ועסקן ציוני בקהיר. עזר לד\"ר שכטר בגילוי הגנזיה ובין היתר גילה דפים מספר \"מורה נבוכים\", ציר בקונגרס הציוני בוינה."},{"i":29834,"n":"מוצרי, יעקב משלוניקי","dt":"תרטז","dp":"שלוניקי","b":"מחכמי שלוניקי."},{"i":29835,"n":"מוצרי, משה משלוניקי","f":"חיים נסים משלוניקי","b":"הגיה והו\"ל ספר אביו \"באר מים חיים\"-תקנד."},{"i":29836,"n":"מוצרי, רחמים מתל אביב","b":"פרסם מאמרים ב\"הארץ\" בעניני ערבים."},{"i":29837,"n":"מוצרי, שלמה משלוניקי","b":"מחכמי שלוניקי-תקעד. נכד ר חיים נסים רפאל מוצרי והו\"ל \"באר מים חיים\"."},{"i":29838,"n":"מוצרי, שמואל נח מאזמיר","f":"חיים נסים רפאל-באר מ","dt":"תקפז - ו-ז כסלו","dp":"ירושלים","b":"רב באזמיר, עלה לירושלים."},{"i":29839,"n":"מוקי, משה","b":"מגדול ווינה בתקופת הגירוש-ת\"ל,רב בראדזין"},{"i":29840,"n":"מוקמנסקי, דב בר","dt":"תשג","b":"רב בקוורסק"},{"i":29841,"n":"מור דוד, שלמה מצפת","b":"רב בצפת, חתן ר משה ן מכיר בעל \"סדר היום\", והדפיס את ספר חותנו בונציה-שנט. בשליחות ישיבת \"עין זיתון\" באיטליה."},{"i":29842,"n":"מורביצר, מרדכי כץ","dt":"תצד","b":"רב בסלוצק"},{"i":29843,"n":"מורבסקי, אברהם","k":"א. מנקר","bt":"1896","bp":"וילנא","dt":"1965","b":"שחקן פופולרי בתיאטרון ובקולנע. פרסם מאמרים בעניני ספרות ותיאטרון. תרגם מחזות לאידיש."},{"i":29844,"n":"מורגונטו, משה מקושטא","dt":"תקפה - סיון","b":"ממונה איסור והיתר בקושטא-תקמב, דיין אצל ר אליה פאלומבו."},{"i":29845,"n":"מורגונטו, נסים חיים שלום יעקב","k":"בעל עושה שלום","b":"רב בשאלוניקי-תקפג. הכין לדפוס \"טל אורות\"."},{"i":29846,"n":"מורגנשטרן חיים ישראל בן דוד","f":"דוד מקוצק","k":"אדמור מקוצק","bt":"תר","bp":"קוצק","dt":"תרסה - יב סיון","b":"חתן הגביר ר זליג פרנקל מזגירז. אדמו\"ר בקוצק-תרלג, פילוב-תרמח. הציע תכנית להעלאת אלף משפחות חסידים לארץ - אולם התכנית לא התממשה. חיבר \"שאלו שלום ירושלים\", ו\"מעשה המנורה\" - נדפסו ב\"שארית ישראל\".","bk":[["שלום ירושלים",""]]},{"i":29847,"n":"מורגנשטרן, אברהם","f":"בנימין פלטיאל מסטרדי","b":"מצאצאי האדמור ר מנחם מנדל מקוצק. חתן ר ראובן זהמן מאוטואצק."},{"i":29848,"n":"מורגנשטרן, אברהם גרשון מלודז","dt":"תש..","b":"אין פרטים."},{"i":29849,"n":"מורגנשטרן, אברהם יוסף מפילוב","f":"חיים ישראל מפילוב","k":"אדמור מקוצק","dt":"תרצט - יג טבת","b":"חתן ר אלימלך מקוזניץ-וארשא. חבר מועצת גדולי התורה של אגו\"י. רב ואדמור בקוצק-תרפט אחר פטירת אחיו ר משה מרדכי מפילוב."},{"i":29850,"n":"מורגנשטרן, אברהם משאדעק","f":"אפרים פישל מאיר","k":"בעל רבבות אפרים","b":"אב\"ד שאדעק."},{"i":29851,"n":"מורגנשטרן, אברהם פנחס משדליץ","f":"צבי הירש מלומאז","k":"אדמור מרדזימין","bt":"תרלז","dt":"תשב","b":"רב בלומאז, אדמור בשדליץ לאחר פטירת אביו, עבר לביאלא, חזר לשדליץ, וארשא, לאחר פטירת דודו האדמור ר אהרן מנחם מנדל מראדזימין עברו אליו רבים מחסידיו. נספה בשואה. בנו ר יוסף אליעזר."},{"i":29852,"n":"מורגנשטרן, אליעזר שלום מטשיחוב","f":"שמחה","dt":"תרכז - יט אב","b":"תלמיד ר ישכר בר מרדושיץ, ור מנחם מנדל מקוצק. רב בטשיחוב, שדליץ, פיעטרקוב. חתנו - ר אברהם יהודה ליבוש מאוזרוב בעל \"ברכת טוב\". נהג לחתום שמו \"אליעזר שלום\" ללא שם משפחתו."},{"i":29853,"n":"מורגנשטרן, בנימין","dt":"תשג","b":"רב בוונגרובה"},{"i":29854,"n":"מורגנשטרן, בנימין","f":"מנחם מנדל מקוצק","dt":"תרכו","b":"חתן ר אברהם מרדכי בן האדמור ר יצחק מאיר מגור."},{"i":29855,"n":"מורגנשטרן, בנימין פלטיאל מסטרד","f":"יצחק זליג מסוקולוב","bt":"תרנה-ח","dt":"תשה","dp":"אושוויץ","b":"חתן ר יוסף מאמשינוב (שושלת וארקי). רב בסטררין-ליד סוקולוב-תרצב, רב ואדמור בסוקולוב על מקום אביו-בזמן השואה. נספה בשואה. בנו ר אברהם."},{"i":29856,"n":"מורגנשטרן, דוד מסקלט","b":"מחסידי הוסיאטין בסקלט."},{"i":29857,"n":"מורגנשטרן, דוד מקוצק","f":"מנחם מנדל מקוצק","k":"אדמור מקוצק","bt":"תקסט","dt":"תרלז - ה תמוז","b":"חתן ר צבי הירש גרינואלד דישקס מאופוטשנא. אדמו\"ר בקוצק-תריט לחלק מחסידי אביו. מתורתו ב\"אהבת דוד\" בתוך \"להבות אש\". באוצר תאריך הפטירה תרלג."},{"i":29858,"n":"מורגנשטרן, דוד שלמה","f":"יעקב אריה מורגנשטרן","dt":"תשג","b":"רב בווישקוב."},{"i":29859,"n":"מורגנשטרן, הירש מביליץ","b":"רב בביליץ."},{"i":29860,"n":"מורגנשטרן, חיים אביעזר זליג","f":"דב אורי","k":"בעל בציר אביעזר","b":"מו\"צ ור\"מ במינסק."},{"i":29861,"n":"מורגנשטרן, חיים יעקב אריה","f":"צבי הירש מלומאז","k":"אדמור מרדזימין","bt":"תרלז","dt":"תשג","dp":"וארשא","b":"חתן ר מנחם מאמשינוב (שושלת וארקי). רב בוירבזניק, וישקובה ואדמור שם-תרפו אחר פטירת אביו, רב ואדמור בראדזימין-תרצה על מקום דודו-אחי אמו ר אהרן מנחם מנדל מראדזימין. נספה בשואה עם שמונת בניו."},{"i":29862,"n":"מורגנשטרן, יוסף אהרן מליקיווא","f":"צבי הירש מליקיווא","k":"אדמור מליקיווא וארשא","bt":"תרנא","dt":"תשב","b":"אדמו\"ר בליקיווא על מקום אביו, עבר לוארשא-תרצג. נספה בשואה."},{"i":29863,"n":"מורגנשטרן, יוסף אליעזר","f":"אברהם פנחס משדליץ","b":"בנו של האדמור מקוצק שדליץ. חתן האדמור ר משה אהרן מקוברין. הו\"ל ספר דודו \"עלים לתרופה\"."},{"i":29864,"n":"מורגנשטרן, יחיאל מאיר מקוצק","f":"צבי הירש מלומאז","k":"אדמור מקוצק בלונדון","dt":"תשכד","dp":"בני ברק","b":"אדמור מקוצק בלונדון, עלה לארץ והתישב בבני ברק. בעל ספריה חשובה והו\"ל ספרים נדירים עם הקדמות ותוספות משלו."},{"i":29865,"n":"מורגנשטרן, יחיאל מבאלגראד","k":"בעל אילת השחר","b":"רב בבאלגראד-בסרביה."},{"i":29866,"n":"מורגנשטרן, יעקב דוד","f":"צבי מורגנשטרן","b":"רב בלודמיר-תר\"ס"},{"i":29867,"n":"מורגנשטרן, יעקב יהושע מקוצק","f":"דוד מקוצק","k":"אדמור מקוצק","dt":"תרסט - טו ניסן","b":"אדמור בקוצק-תרסה, על מקום אחיו ר חיים ישראל."},{"i":29868,"n":"מורגנשטרן, יעקב יצחק מקרסטור","b":"תלמיד הכת\"ס. רב בלוק (טיסא ליק)-תרך לצד חותנו. באדראג קרעסטור-תרנב."},{"i":29869,"n":"מורגנשטרן, יצחק איזיק מקאלושין","f":"יונתן","k":"בעל תולדות יצחק אהרן","bp":"לושיץ","b":"תלמיד ר יונתן איבשיץ מלושיץ. פרסם מאמרים ב\"אסיפת חכמים\" - מלניץ תרפח, \"מגד ירחים\" - סטמר תרפה, \"קהילת יעקב\" - זבורוב-סלובקיה תרפה."},{"i":29870,"n":"מורגנשטרן, יצחק בצלאל מוארשא","k":"בעל מאה שערים","b":"רב בוארשא. חיבר הגהות \"פרי יצחק - אור שחר\" על ספר חסידים. פרסם מאמרים ב\"אסיפת חכמים\" - אושפצין תרצד, \"אסיפת חכמים\" - מלניץ תרפח, \"יגדיל תורה\" - פראגא-וארשא תרפז, \"הפרדס\" פיעטרקוב-שיקגו תרעג-תרפז. מעורכי \"שערי תורה\" - וארשא תרסג-תרצט."},{"i":29871,"n":"מורגנשטרן, יצחק זליג מסוקולוב","f":"חיים ישראל מפילוב","k":"אדמור מקוצק בסוקולוב","bt":"תרכד-ו","bp":"קוצק","dt":"תש - ג חשון","dp":"אוטואצק","b":"חתן הגביר ר מרדכי שינפלד מפינטשוב. ממנהיגי היהדות בפולין. בקי ברפואה, רב בסוקולוב-תרס והקים שם ישיבה \"בית ישראל\" ואדמור-תרסה אחר פטירת אביו. ביקר בארץ-תרפד, עבר לאוטואצק. מתורתו ב\"שארית ישראל\", פרסם מאמרים ב\"אהל מועד\" - איזביצא - בילגוריי - תרפו, \"אור המאיר\" - וארשא תרצו, \"דגל התורה\" - וארשא תרפב, \"הפרדס\" פיעטרקוב-שיקגו תרעג-תרפז, \"קובץ דרושים\" - פיעטרקוב תרפג."},{"i":29872,"n":"מורגנשטרן, ישראל יצחק","f":"יעקב אריה מורגנשטרן","dt":"תשג","b":"רב בסערצקי"},{"i":29873,"n":"מורגנשטרן, מנחם מנדל א","f":"יצחק זליג מורגנשטרן","dt":"תשג","b":"רב בוולאדאווע"},{"i":29874,"n":"מורגנשטרן, מנחם מנדל מוארשא","f":"צבי הירש מלומאז","k":"אדמור מקוצק בוארשא","dt":"תש..","b":"אדמור מקוצק בוארשא. נספה בשואה."},{"i":29875,"n":"מורגנשטרן, מנחם מנדל מקוצק","f":"יהודה ליביש","k":"אדמור מקוצק","r":"אדמו\"ר מקאצק","bt":"תקמז","dt":"תריט - כב שבט","b":"חתן ר איזיק ניי מטומשוב, ובזיוו\"ש חתן הגביר ר משה חלפן מוארשא. תלמיד החוזה מלובלין, והיהודי הקדוש מפשיסחא. אדמו\"ר בטומשוב-תקפז, קוצק. מתורתו ב\"אהל תורה\", \"להבות אש\". מתולדותיו ב\"השרף מקוצק\". מבניו: ר בנימין, ר משה ירוחם. חתנו ר דב זאב הכהן רפפוט אב\"ד קוצק.","bk":[["אמת מקאצק תצמח [ליקוט] (קוצק)",""],["אהל תורה",""],["אמת ואמונה",""],["אמת מקאצק תצמח",""],["לשונות של אש",""],["עמוד האמת",""]]},{"i":29876,"n":"מורגנשטרן, מנחם מנדל מקוצק י-ם","f":"משה דוד","b":"מצאצאי האדמור ר מנחם מנדל מקוצק. נכד ר יצחק זליג מקוצק-סוקולוב. רבם של חסידי קוצק-סוקולוב בישראל."},{"i":29877,"n":"מורגנשטרן, מרדכי","bt":"תקעה","dt":"תרסב - כא ניסן","b":"חסיד האדמור ר ישראל מרוזין. נכדו - ר יחיאל מבאלגראד הקדיש לו שיר בספרו \"אילת השחר\"."},{"i":29878,"n":"מורגנשטרן, מרדכי מולאדובא","f":"משה ברוך מורגנשטרן","dt":"תשג","b":"רב בוולאדובה."},{"i":29879,"n":"מורגנשטרן, מרדכי מסקרזישק","f":"יעקב אריה מורגנשטרן","dt":"תשג","b":"רב בסקרזישק"},{"i":29880,"n":"מורגנשטרן, משה ברוך מגרובוב","f":"צבי הירש מליקיווא","k":"בעל דברי משה","dt":"תשג","b":"רב בגרובוב, ליקוב, וולאדובא, רב ואדמור בקוצק-תרצט על מקום דודו ר יוסף מקוצק. נספה בשואה."},{"i":29881,"n":"מורגנשטרן, משה ירוחם","f":"מנחם מנדל מקוצק","bt":"תרב","dt":"תרכא-ה -כב סיון","b":"בנו הצעיר של האדמור מקוצק, אחיינו של בעל חדושי הרי\"מ שאמר עליו שהוא \"צדיק יסוד עולם\". חתן הגביר ר יצחק בלאס מגור. נפטר צעיר. (יש אומרים תאריך פטירתו - תרכה)."},{"i":29882,"n":"מורגנשטרן, משה מרדכי מפילוב","f":"חיים ישראל מפילוב","k":"בעל מקוצק בפילוב","r":"אדמו\"ר מפילוב ומקוצק","bt":"תרכב","dt":"תרפט - יד אדר","dp":"וארשא","b":"אדמור מקוצר בפילוב-תרפ. חיבר \"מדרש משה\", \"מדרכי משה\".","bk":[["מדרכי משה – עה\"ת",""],["מדרש משה – עה\"ת",""],["מעשה המנורה - חנוכה",""],["מעשה המנורה - חנוכה, מדרכי משה – עה\"ת, מדרש משה – עה\"ת",""]]},{"i":29883,"n":"מורגנשטרן, מתתיהו חנוך מבאלגרא","f":"מרדכי","bt":"תריד","bp":"קונסטנטין","b":"מצאצאי ר ליפא מחמלניק-תלמיד הבעש\"ט. תלמיד ר מיכל מקונסטנטין. רב בבלגרד(=באלגראד)-בסרביה-תרנג."},{"i":29884,"n":"מורגנשטרן, צבי הירש מלומאז","f":"דוד מקוצק","k":"אדמור מקוצק","bt":"תריב","dt":"תרפו - ג אלול","b":"חתן ר שלמה יהושע דוד מראדזימין, ובזיוו\"ש חתן ר דוד מקילץ (שושלת פרגא). אדמו\"ר בראדזימין-תרלג, לומאז, פרגא-וארשא."},{"i":29885,"n":"מורגנשטרן, צבי הירש מסנט גרוד","bp":"מאגלאד","dt":"תרך","b":"תלמיד החת\"ס, ור בנימין זאב רפפורט מפאפא, ור בנימין זאב בוסקוביץ מבאניהאד. רב בשליינינג-תקעט, סנט גרוד-תקצד."},{"i":29886,"n":"מורגנשטרן, צבי מליקיווא","f":"חיים ישראל מפילוב","k":"בעל עטרת צבי","r":"אדמו\"ר מקוצק - ליקאווה","bt":"תריח","dt":"תרפ-ו - כט שבט","b":"אדמו\"ר מקוצק בליקיווא.","bk":[["עטרת צבי - עה\"ת וחנוכה",""]]},{"i":29887,"n":"מורגנשטרן, שלמה יהודה אריה ליב","f":"נטע מאיר מלובלין","k":"בעל מנחת הבקר","b":"רב בלונטשיץ. סגי נהור (וסופר שאיבד את ראייתו בגלל שפגע באחד האדמורים)."},{"i":29888,"n":"מורדו די, אברהם מקורפו","f":"אליהו","b":"מחכמי קורפו. חיבר פיוטים ונכנסו למחזור קורפו."},{"i":29889,"n":"מורדו די, אליעזר מקורפו","b":"רופא ופייטן מחכמי קורפו. פיוטים ממנו במחזור קורפו ובהם \"אחלי ירונו מחשבת לבי\"."},{"i":29890,"n":"מורדוך, דוד מאזמיר","b":"מחכמי איזמיר, תלמיד בעל \"חקרי לב\""},{"i":29891,"n":"מורדוך, דניאל משלוניקי","f":"יצחק","dt":"תרנא","dp":"שלוניקי","b":"נכד התוכן ר שלמה מורדוך. מחכמי שלוניקי ובקי בחכמת התכונה. הו\"ל לוח שנתי המכונה \"חלילה\", החזיק בכת\"י עבריים שעברו לר שאול אמריליו."},{"i":29892,"n":"מורדוך, יוסף משלוניקי","f":"שלמה-מראה האופנים","k":"בעל נפש יוסף","dt":"תרכח - כ אייר","dp":"ירושלים","b":"מחכמי שלוניקי, עלה לירושלים, הוציא לאור עם ר משה קאסטרו את שער ה' מ\"ספר השערים\"-תריב, כתב הוספות משלו ומשל אביו לשערים ב וג'. הוציא לאור ספר \"עולת תמיד\" לר יעקב צמח. חיבר \"נפש יוסף\" שלוניקי תרטז."},{"i":29893,"n":"מורדוך, יצחק משלוניקי","f":"שלמה-מראה האופנים","b":"מחכמי שלוניקי-תקפז. חיבר הקדמה ל\"מראה האופנים\" לאביו."},{"i":29894,"n":"מורדוך, ישראל משלוניקי","b":"מדפיס אצל בצלאל הלוי אשכנזי בשלוניקי-תקו."},{"i":29895,"n":"מורדוך, רפאל שלמה משלוניקי","f":"חיים","k":"בעל מראה האופנים","bt":"תקכ","dt":"תרז","dp":"שלוניקי","b":"מחכמי שלוניקי, ובקי במדעים ובתכונה. חיבר גם \"עצת חכמים\" והיה מחלוקת כנגדו מצד ר חיים פלאג'י מאזמיר על שהביא מדברי חכמי הגויים. בניו: ר יוסף, ור יצחק שחיבר הקדמה לספרו."},{"i":29896,"n":"מורדכוביץ, יעקב דוב מברעזינא","dt":"תשג","b":"ר\"מ בברעזינא"},{"i":29897,"n":"מורדכוביץ, שמעון מנ\"י","k":"בעל שמן הקודש","dt":"תשכה - כו אלול","b":"חתן ר שמחה אליהו ציפקביץ מניו יורק. רב בניו יורק. פרסם מאמרים ב\"המתיבתא\" - נ\"י תשג."},{"i":29898,"n":"מורדל, פנחס","bt":"1867","bp":"קובנא","dt":"1934","dp":"פילדלפיה","b":"תלמיד ישיבות ליטא. היגר לארה\"ב-1881. פרסם בקורת על \"ספר היצירה\" , פרסם ב\"השלוח\", \"העברי\", ועוד. כתב על התפתחות הניקוד העברי, טען במאמריו כי היהודים הם שהמציאו את האלף-בית."},{"i":29899,"n":"מורדקובסקי, יצחק","b":"פרסם מאמרים ב\"התמים\" - וארשא תרצה - קובץ חסידי חב\"ד."},{"i":29900,"n":"מורה, חיים","f":"מרדכי","k":"בעל ידי אליהו","b":"מחכמי טהראן,חיבר \"ידי אליהו\""},{"i":29901,"n":"מורו, יוסף מאיטליה","b":"מומר באיטליה, הלשין עם חבריו על התלמוד, וכתוצאה מההלשנה נשרף התלמוד-שיד."},{"i":29902,"n":"מורון, יצחק מאזמיר","b":"רב באזמיר, בזמן ר חיים פאלג'י - נזכר ב\"גנזי חיים\"."},{"i":29903,"n":"מורטירה, יצחק הכהן","b":"חידוש ממנו אצל היעב\"ץ. מחכמי מרוקו?"},{"i":29904,"n":"מורטירה, שאול הלוי מונציה","f":"יוסף","k":"בעל גבעת שאול","bt":"שנו","bp":"ונציה","dt":"תך - כה שבט","dp":"אמשטרדם","b":"עבר עם דודו הרופא ר אליהו דילונה מונטלטו לצרפת, הגיע לאמשטרדם-שעו, וכיהן כרב עם ר יוסף פרדו ור יצחק עוזיאל. ראב\"ד וראש ישיבה באמשטרדם. מתלמידיו ר משה זכות, ברוך שפינוזה, יוסף שיין איש האמעל ואליעזר פלאט איש קאמין, חתנו ותלמידו ר יאשיהו בן דוד פארדו. היה במחלוקת עם ר מנשה בן ישראל -שבעקבותיה נאלץ ר מנשה לעזוב את אמשטרדם, היה במחלוקת גם עם ר יעקב ששפורטש. יצא כנגד המומר סנטור סנסיס. החרים את שפינוזה. בנו ר דוד שפעל למען ישיבת אביו \"כתר תורה\". חיבר ספרים בספרדית, ונזכרו אצל ר משה רבק\"ש בעל \"באר הגולה\" שפגשו באמשטרדם.","bk":[["גבעת שאול",""]]},{"i":29905,"n":"מורטנפלד-הדסאי, יהודה מאיר","f":"משה יעקב","bt":"תרמב","bp":"פיעטריקוב","b":"נכד ר הירש אבא מפלבנה, והאדמור מסאסוב, פלאנטש.תלמיד ישיבת לומזה, נסמך מאת: ר מלכיאל צבי מלומז'ה, ר יעקלי מקלוביצק, ר מאטיל הורביץ, ר שמחה יאיר מפיעטרקוב, ר ישכר דב גרוברט מבנדין. תלמיד וחתן האדמו\"ר ר אברהמלי מזבירצה, מו\"צ אצל חותנו-תרסז, רב בקטוביץ-תרפו, ברסלוי-תרפח, וינה-תרצב, עלה לארץ-תרצה."},{"i":29906,"n":"מורטנפלד-הדסאי, משה יעקב","dt":"תרסח - כב אד\"ב","b":"מחכמי פיעטרקוב, בנו - ר יהודה מאיר בעל \"ליקוטי הים\"."},{"i":29907,"n":"מורטרה, מרדכי ממנטובה","k":"בעל רוח ישראל","b":"מו\"צ במנטובה."},{"i":29908,"n":"מוריאל, יהודה מבוברקא","f":"דוד מסינגר","k":"בעל עיונים במקרא","bt":"תרע","bp":"בוברקא","dt":"תשנח","b":"גדל אצל זקנו ר שלמה זלוזיצר. דרשן ועוזר פרלמנטרי לאיש אגו\"י בסיים הפולני. עלה לירושלים-תרצג. מנהל מוסדות חינוך. חיבר \"עיונים במקרא\" תל אביב תשיז."},{"i":29909,"n":"מוריגון, חיים","b":"חכם כולל"},{"i":29910,"n":"מוריירה, יעקב רודריגז מלונדון","k":"בעל קהלת יעקב","b":"מחכמי קהלת הספרדים בלונדון. חיבר \"קהלת יעקב\" - אוצר לשון הקדש."},{"i":29911,"n":"מורינו מבלגרד","b":"רב הקהלה הספרדית בבלגרד, והיה מחלוקת בינו לר לוי ירושלמי עד שעשו שלום ביניהם והרב מורינו עלה לארץ ובקש למנות על מקומו את ר לוי ירושלמי (שהיה רב הקהלה האשכנזית)."},{"i":29912,"n":"מורינו, אברהם ליאון מאזמיר","dt":"תקנה - ד אלול","dp":"אזמיר","b":"מחכמי אזמיר-תקן בערך."},{"i":29913,"n":"מורינו, דוד שלום מבאיון","b":"רב בבאיון(צרפת)-תמ\"ד"},{"i":29914,"n":"מורינו, חיים שבתי מירושלים","dt":"תקז - י טבת","dp":"ירושלים","b":"מחכמי ירושלים."},{"i":29915,"n":"מורינו, יהודה ממראקש","b":"מחכמי מראקש-שנות ה-תק'."},{"i":29916,"n":"מורינו, ישי משלוניקי וגליפולי","b":"מחכמי שלוניקי, רב בגאליפולי-שנות ה-ש'."},{"i":29917,"n":"מורינו, שלמה מאזמיר","dt":"תקכט - יז כסלו","dp":"אזמיר","b":"מחכמי אזמיר."},{"i":29918,"n":"מורינסי, יצחק מניקופול","b":"מחכמי שלוניקי, רב בניקופול-תך בערך."},{"i":29919,"n":"מורלי, יצחק מאלגיר","f":"רפאל דוד","k":"בעל צפנת פענח","bt":"תרכז","bp":"אלגיר","dt":"תשיב","b":"תלמיד ר מרדכי אטנגי, ותלמיד ר משה דדון בישיבת \"עץ חיים\" באלגיר. עשיר, פייטן, דיין רב ומנהל הת\"ת באלגיר-תרנד ודיין, מראשי הקהלה. נחשב לרב משכיל הדוגל בשילוב עם תרבות צרפת. משורר וחיבר כ-200 שירים. חיבר \"עת מלחמה ועת שלום\", ירקרק חרוץ\", \"חסד ואמת\" ועוד. פרסם מאמרים ב\"אוצר הספרות\" קראקא תרמט, \"המאסף\", \"קובץ על יד\". עורך קובץ \"היכל הקודש\"."},{"i":29920,"n":"מורנו, רפאל בנימין חיים מירושל","dt":"תקו - כז אדר","dp":"ירושלים","b":"מחכמי ירושלים. מתשובותיו בספר נכדו - ר רפאל יוסף ן רובי מירושלים. לפי רוזניס היה בשליחות-תקכה (לאחר תאריך פטירתו הרשום)."},{"i":29921,"n":"מורנו, רפאל בנימין חיים מליוור","b":"רב בליוורנו. תשובה ממנו ב\"דרך המלך\"."},{"i":29922,"n":"מורנו, שבתי חיים מפדובה","b":"מגדולי פאדובה-ת\"ל"},{"i":29923,"n":"מורנו, שלמה מירושלים","f":"עמנואל","b":"מחכמי ירושלים, בשליחות בפאס בשנת תס, חדושי תורה ממנו בספר \"השבת העבוט\" לר מאיר בן עזרא."},{"i":29924,"n":"מורנסקי, משה מסלוצק ופפד\"ם","f":"אליהו","k":"בעל על שמשא","b":"מחכמי פפד\"ם. חיבר הספד על רש\"ר הירש בשם \"על שמשא\". חיבר גם \"מנחת משה\" - בכת\"י."},{"i":29925,"n":"מורסה, שלמה ממונסטיר","b":"רב במונסטיר-שנות ה-ש'."},{"i":29926,"n":"מורסייא, אברהם מאזמיר","dt":"תקך - כה תמוז","dp":"אזמיר","b":"רב באזמיר."},{"i":29927,"n":"מורסייא, יהודה מאזמיר","dt":"תקג - ג סיון","dp":"אזמיר","b":"מקובל, רב באזמיר-שנות ה-ת'."},{"i":29928,"n":"מורסייא, שמואל מחלב","b":"רב ודרשן בחלב."},{"i":29929,"n":"מורפורגו, אברהם מאיטליה","k":"בעל אלפי מנשה","b":"מגדולי חכמי איטליה, רב בגרדיסקא-תקמ. חתנו - ר אברהם חי בן עזריאל."},{"i":29930,"n":"מורפורגו, דוד משה משלוניקי","dt":"תרמז","dp":"שלוניקי","b":"גביר בשלוניקי."},{"i":29931,"n":"מורפורגו, דוד משלוניקי","dt":"תקיח","dp":"שלוניקי","b":"אחיו של ר שמשון מאנקונה. למד רפואה בפדובה, התישב בלאריסה, עבר לשלוניקי-תע, מבני הקהלה האיטלקית בשלוניקי-תקד וחתם אז על הסכם בין האיטלקים לבין בני קהלת שלוניקי בענין הסדרת המס, היה במחלוקת עם רבני שלוניקי בענין גילוח במספריים וכתב על כך לאחיו באיטליה. סייע בהדפסת \"פרי האדמה\"-ח\"ג-תקטו."},{"i":29932,"n":"מורפורגו, דוד משלוניקי","b":"גביר מראשי קהלת שלוניקי-תרלח."},{"i":29933,"n":"מורפורגו, משה חיים שבתי רפאל","f":"שמשון","b":"רב באנקונה-תקה וחתם עם רבני אנקונה על \"פחד יצחק\"-תקי ותשובה ממנו בספר."},{"i":29934,"n":"מורפורגו, שמריה מאיטליה","f":"גבריאל יצחק","b":"עורך ומעתיק באיטליה-תקד, ערך והעתיק את ספריו של ר מנשה יוסף קציגין \"שמריה זוהם\"."},{"i":29935,"n":"מורפטשיק, יחיאל מלובלין","f":"ידידיה","k":"בעל מנחה חדשה","b":"רב בלובלין-שנות הש'. תרגם גזירת אסטרייך ווינה מלשון אשכנז."},{"i":29936,"n":"מורפטשיק, משה מפוזנא וליסא","f":"אהרן","k":"בעל כיצד סדר עבודה","b":"רב בפוזנן, עבר לליסא."},{"i":29937,"n":"מורקלן, יהודה","dt":"רכז","b":"מגדולי רבני אשכנז,רב במרפורק"},{"i":29938,"n":"מושאגי, יוסף משלוניקי","dt":"שצה - יב אלול","dp":"שלוניקי","b":"מחכמי שלוניקי."},{"i":29939,"n":"מושאילוב, אליהו","f":"מישאל","dt":"תרח","b":"בא מבגדאד-תנ\"ח, רב כולל בקווקז(דגסטאן)-תר\"ח"},{"i":29940,"n":"מושאילוב, חזקיה מטעמיר-חאן-שור","f":"אברהם","bp":"קוקז","b":"הגיע מהקוקז - חתן דודו הגביר ר יהושע מושאילוב אשר שלחו ללמוד בישיבות סלוצק, וולוזין. רב בטעמיר-קאן-שורה(דגסטאן בקוקז)-תרלה, ובנו ר רפאל מו\"ץ לצידו."},{"i":29941,"n":"מושאילוב, רפאל מטעמיר-חאן-שור","f":"חזקיה","b":"תלמיד ישיבת סלוצק ותלמיד הרידב\"ז. מו\"ץ בטעמיר-קאן-שורה(דגסטאן בקוקז) לצד אביו."},{"i":29942,"n":"מושורו, יוסף משלוניקי","dp":"שלוניקי","b":"מחכמי שלוניקי."},{"i":29943,"n":"מושורו, משה משלוניקי","dt":"רף - טו שבט","dp":"שלוניקי","b":"מחכמי שלוניקי."},{"i":29944,"n":"מושכונה, משה מאדרינופול","b":"סוחר מחכמי אדרינופול, עבר לוידין-תקיא ומשם שלח מכתב תנחומים לר ירוחם אליקים גירון על פטירת אביו."},{"i":29945,"n":"מושל, יוסף","f":"אהרן מלנצהוט","dt":"תרנג","dp":"דיסלדורף","b":"מחכמי אושפיצין, רב בדורטמונד-גרמניה. חתן ר יהודה יעקב בלז מלנצהוט."},{"i":29946,"n":"מושל, מנחם מנדל מסנוק","b":"בעל דפוס בסנוק."},{"i":29947,"n":"מושציסקר, יוסף מקידרניץ","dt":"תרצז","b":"רב בזלוטניק, קידרניץ, יאנוב, בוזנוב והיה שם מחלוקת על כך. חתן ר יעב שמשון הלר מבוזנוב, ובזיוו\"ש לבת האדמור מלשקוביץ."},{"i":29948,"n":"מושקאט, אברהם מאיר מביאלוברזיג","f":"ישעיה מפרגא","dt":"תריב","b":"בן האדמור מפרגא. חתן האדמור ר יצחק מוארקא. נפטר בחיי אביו."},{"i":29949,"n":"מושקאט, חיים אליעזר ממזריטש","f":"בנימין","k":"בעל אבני נזר","b":"מחכמי מזריטש. חיבר גם \"אדם המעלה\", ועוד."},{"i":29950,"n":"מושקאט, יוסף דמילאב מקרפנטרץ","k":"בעל אוצרות יוסף","b":"חיבר \"אוצרות יוסף\"."},{"i":29951,"n":"מושקאט, ישעיה מפראגא","f":"יעקב משה","k":"אדמור מפראגא","r":"אב\"ד פראגא","bt":"תקמג","bp":"וארשא","dt":"תרכח - ה אדר","b":"נכד ר שלמה זלמן מירוסלב ווארשא. חתן ר יצחק מראדויל (שושלת זלוטשוב). תלמיד ר ישראל מקוזניץ (וכן גם אביו ר יעקב משה) ובנו ר משה. רב ואדמור בפרגא-וארשא-ת\"ר. חיבר \"עצי בשמים\", \"הרי בשמים\", ועוד. הו\"ל ספר חותנו \"אור יצחק\".","bk":[["עצי בשמים – ש\"ס, משניות, שו\"ע או\"ח ויו\"ד",""],["ראשי בשמים – עה\"ת, סידור",""]]},{"i":29952,"n":"מושקונה, חיים מבאזארג'יק","b":"חתן ר יהודה ן סיד בעל \"נר מצוה\"."},{"i":29953,"n":"מושקין, אלעזר ראובן מארה\"ב","bt":"תרמט","b":"רב בשיקגו-ארה\"ב-תרעב. פרסם מאמרים ב\"דגל התורה\" - וארשא תרפב, \"כנסת ישראל\" - נ\"י תרצב - כתב עת הסתדרות תלמידי סלובודקה באמריקה, \"המגיד\" - סטמר תרפח-תרצט, \"שערי ציון\" - ירושלים תרפא, \"תבונה\" - קובנא תרפא."},{"i":29954,"n":"מושקין, יחיאל מיכל מירושלים","k":"בעל מיכל מים חיים","dt":"תשז - ד שבט","dp":"ירושלים","b":"רב בירושלים. בשליחות בארה\"ב-תרעד וכיהן כרב בסט. לואיס-ארה\"ב. פרסם מאמרים ב\"אור תורה\" - ירושלים תרנז, \"ועד חכמים\" - ירושלים תרפג."},{"i":29955,"n":"מז נתן בן שלמה","bt":"1720","dt":"ה'תקנו 1796","bk":[["בנין שלמה",""]]},{"i":29956,"n":"מ\"ז, צבי הירש מוישניצה","b":"רב בוישניצא, פרגא-תרצה."},{"i":29957,"n":"מזאה, אליהו מרדכי מניו יורק","k":"בעל בית אליהו מרדכי","b":"רב בניו יורק. חיבר \"בית אליהו מרדכי\" נ\"י תשו."},{"i":29958,"n":"מזאה, יעקב ממוסקבה","f":"ישעיה","k":"בעל זכרונות","bp":"מוהילוב","b":"רב במוסקבה על מקום ר שלמה מינור, עלה לארץ."},{"i":29959,"n":"מזגיש, אברהם מאלגיר","f":"שמואל","bt":"תקל","dt":"תר - בערך","b":"מחכמי אלגיר. ממחברי \"חסד לאומים\" - על הצרות שעברו על הקהלה בשנים תקסה-תקע, יחד עם ר אליהו הכהן שולאל, ר ברוך טוביאנה, ר סעדיה קאג'יג'."},{"i":29960,"n":"מזגיש, שלום מטריפולי","bt":"תם","dt":"תקי - בערך","b":"סופר קהלת טריפולי, וחתם בפנקס בי\"ד טריפולי."},{"i":29961,"n":"מזה, יהושע לוי סגל","f":"חיים","k":"בעל האמונה וההשכלה","bt":"1834","bp":"ז'אגר חדש","dt":"1917","dp":"וילנא","b":"תלמיד ישיבות ליטא, הושפע מספרות ההשכלה. פרסם מאמרי וסיפורים. הטיף להגירה לאמריקה ולארץ ישראל. חיבר גם \"טפח מגולה\", ועוד. הו\"ל את המאסף \"גן הפרחים\"."},{"i":29962,"n":"מזוז, אברהם","f":"משה","k":"בעל ברכת אברהם","b":"חיבר \"ברכת אברהם\""},{"i":29963,"n":"מזוז, אלטר","k":"בעל אם הבנים שמחה","bt":"תרצב-יא אב","bp":"ג'רבא","dt":"תשמח - יט תשרי","b":"עלה לא\"י-תשט\"ז, רב מושב איתן, מרביץ תורה, דרשן, חיבר \"אם הבנים שמחה\"","bk":[["אם הבנים שמחה",""]]},{"i":29964,"n":"מזוז, דוד אליהו","bt":"תרסו","dt":"תשמג - ניסן","b":"רב של קהילות אלחמה וספקס(טוניס), עלה לא\"י, רבה של נוה שאנן(חיפה)"},{"i":29965,"n":"מזוז, כליפא מג'רבה","b":"דיין בג'רבא-תרכה, חתם עם ר מעתוק חדד ור נסים ביתאן. עלה לארץ וכיהן כדיין. בנו ר מרדכי מזוז המוזכר ב\"שלמי תודה\"."},{"i":29966,"n":"מזוז, כמוס כמייס מג'רבה","k":"בעל כמוס עמדי","bt":"תרנה","dt":"תשח - כג כסלו","b":"תלמיד ר דידו (דוד) הכהן מג'רבא, ור כלפון משה הכהן מג'רבא. מחכמי ג'רבא, עלה לארץ ובדרך אבדו רוב כתביו."},{"i":29967,"n":"מזוז, מנחם מג'רבה","dt":"תרכח - א אדר","dp":"ירושלים","b":"דיין מחכמי ג'רבא, עלה לירושלים. בנו ר רחמים בעל \"כסא רחמים\". (יש אומרים שלא עלה לארץ)."},{"i":29968,"n":"מזוז, מעתוק מתונס","k":"בעל מצמיח ישועות","dt":"תשן - טו חשון","b":"רב בתיאטאוין."},{"i":29969,"n":"מזוז, מקיקץ מזרזיס","dt":"תרפז","b":"מחכמי זרזיס בזמן ר רחמים חדאד ור משה זקן מאזוז."},{"i":29970,"n":"מזוז, מרדכי מג'רבה","f":"כליפא","bp":"ג'רבא","b":"תלמיד ר משה ברבני בתונס. חברו של ר שלמה בן דוד דאנה והשתתף עמו בחיבור \"שלמי תודה\"."},{"i":29971,"n":"מזוז, משה זקן מג'רבה","k":"בעל שערי משה","r":"ראב\"ד אי ג'רבא","bt":"תרי\"א","dt":"תרעה - ב אייר","b":"מחכמי ג'רבאה, תלמיד ר חיים הכהן בעל \"לב שומע\". רב בחארה זגירה-תרסה, ג'רבה-תרע. מתלמידיו ר חיים חורי. חיבר גם \"צדיק ונשגב\", \"סבר פנים\" ועוד.","bk":[["ויכתוב משה",""],["ויען משה",""],["סבר פנים - ובו א] פני זקן. ב] פני משה. ג] פני מלך",""],["צדיק ונשגב",""],["סבר פנים",""],["פני המלך","מפרשי רמב\"ם"],["ביד משה",""]]},{"i":29972,"n":"מזוז, רחמים מג'רבה","f":"מנחם מאזוז","k":"בעל כסא רחמים","bt":"תרכ","dt":"תרסט - יג כסלו","b":"רב בג'רבא. בנו ר רפאל מג'רבא שלחם כנגד פתיחת בי\"ס כי\"ח בג'רבא.","bk":[["כסא רחמים",""]]},{"i":29973,"n":"מזוז, רחמים מטריפולי","bt":"תר","dt":"תרע - בערך","b":"רב ומשורר בטריפולי. חיבר קובץ פיוטים \"רב העלילה\" - בכת\"י."},{"i":29974,"n":"מזוז, רפאל מג'רבה","bt":"תרמח","bp":"ג'רבא","dt":"תשכו - ט אב","b":"מגדולי חכמי ג'רבא. בנו - ר מצליח בעל \"איש מצליח\"."},{"i":29975,"n":"מזוז, שלמה (מאזוזי)","b":"נזכר בשות המבי\"ט."},{"i":29976,"n":"מזוז, שלמה מג'רבה ונתיבות","f":"מנחם","k":"בעל כרם שלמה","bt":"תרסח","bp":"ג'רבא","dt":"תשמב - כה טבת","dp":"נתיבות","b":"נכד ר רחמים בעל \"כסא רחמים\". רב ודיין בג'רבא-תשי, על מקום ר משה כלפון הכהן, יחד עם חבריו ר שושן הכהן ור רחמים חי חויתה הכהן. תלמיד ר שאול מקיקץ השלי ונזכר בספריו, ותלמיד ר אברהם מגוץ הכהן. עלה לארץ-תשטז והתישב בנתיבות. ערך ירחון \"מקבציאל\" בג'רבא, חיבר חדושים על הש\"ס. חיבר גם \"כסא שלמה\", \"מדרש שלמה\", ועוד. פרסם מאמרים ב\"אוצר התורה\" - ג'רבה תרץ, \"הכוכב\" - מונקטש-נ\"י תרצה. הו\"ל \"מקבציאל\" - גרבה תרצה.","bk":[["שואל ומשיב [שו\"ת]",""],["כסא שלמה [שו\"ת]",""],["כסא שלמה",""]]},{"i":29977,"n":"מזוזה, בנימין זאב מזולקוא","f":"יצחק איזיק","k":"בעל בינה לעתים","b":"חיבר \"בינה לעתים\" לר יונתן אייבשיץ עם פירוש \"מקום בינה\" ממנו - למברג תריז. ?? באוצר ??"},{"i":29978,"n":"מזוזה, משה זאב מלמברג","f":"ישראל יחיאל מיכל","k":"בעל חדושי הרמז","bt":"תקף","dt":"תרעא","b":"מחכמי למברג (למרות שהיה סגינהור). חיבר \"חדושי רמ\"ז\" בילגוריא תרצא."},{"i":29979,"n":"מזור ן, מסעוד מאגוראי-מרוקו","f":"יצחק","dt":"תקפו","b":"מחכמי אגוראי-מרוקו, חכם וחתם בשטר-תקפו. נהרג עם 15 יהודים בדרך למכנאס."},{"i":29980,"n":"מזור, אליהו מוארשא","b":"נשיא קהלת וארשא, ממנהלי ישיבת חכמי לובלין."},{"i":29981,"n":"מזור, צבי מאיר מרדיחוב","b":"רב ברדיחוב-תרן."},{"i":29982,"n":"מזיא אהרן מאיר","bt":"1858","dt":"ה'תרצ 1930","bk":[["מחלת השבתא",""]]},{"i":29983,"n":"מזי\"א אשכנזי, יהודה זעלקל","k":"חתן הב\"ח","b":"דיין בקראקא-תג. בנו - ר נפתלי הרץ שחתם בלבוב-תטו."},{"i":29984,"n":"מזי\"א, אברהם","f":"אליעזר מפרידבורג הקד","b":"אביו היה רב בפרידבורג נהרג עק\"ה. אחיו - ר יצחק מפילצא בעל \"יפה נוף\" - כת\"י."},{"i":29985,"n":"מזי\"א, אליעזר ליפמן - א","f":"יצחק מאשכנז","dt":"שכג","b":"אב\"ד פרידבורג. אחיו של ר שמואל מיזא(=מזי\"א). נהרג עק\"ה. בניו - ר אברהם, ר יצחק מפילצא בעל \"יפה נוף\"-כת\"י, ונכדיו: ר ישראל ור אלעזר ליפמן מפוזנא ווראניק."},{"i":29986,"n":"מזי\"א, אליעזר ליפמן - השני","f":"יצחק מפולדא","b":"מחכמי פולין ובוהמיה. תשובה ממנו ב\"נתיבות עולם\" למהר\"ל-שמח."},{"i":29987,"n":"מזי\"א, חיים מפרג","f":"אליעזר ליפמן","k":"בעל שנות חיים","b":"מצאצאי ר סיני-אחי המהר\"ל."},{"i":29988,"n":"מזי\"א, משה חיים מפרג","dt":"תשט - כט אלול","b":"עשיר,מרביץ תורה בפרג"},{"i":29989,"n":"מזי\"א, נפתלי הרץ אשכנזי מלבוב","f":"יהודה זעלקי","dt":"תכד-ט - ב טבת","dp":"לבוב","b":"נכד בעל הב\"ח. רב בלבוב-תט בזמן בעל הט\"ז. חתם על פס\"ד עם ר נחמן רפפורט, ועוד. חתם-תטו בשם מזיא אשכנזי עם ר יהודה אברהם בן יצחק סגל, ועוד. (לדעת בובר היה דיין ולא אב\"ד כפי שאמרו אחרים)."},{"i":29990,"n":"מזי\"א, שמואל מפפד\"מ","b":"רב בפפד\"מ-ש\"ב. אחיו של ר אליעזר מפרידבורג."},{"i":29991,"n":"מזל טוב, אליהו מיון","b":"פייטן מחכמי יוון-ר'. מפיוטיו במחזור קורפו."},{"i":29992,"n":"מזל טוב, דוד","b":"תלמיד ר' חיים פאלאג'י באיזמיר שהחשיב אותו מאד"},{"i":29993,"n":"מזל תרים, מכלוף","b":"רב בדאר אלבידא-מרוקו."},{"i":29994,"n":"מזל, זאב מקאליש","dt":"תשג","b":"דומ\"צ בקאליש"},{"i":29995,"n":"מזל, זוסיא (זושא) מחוליוב","dt":"תרף","b":"מצאצאי ר זושא מאניפולי (בן אחר בן) ושל ר פנחס מקוריץ. רב בסטרימילטש (ליד רדיחוב), חוליוב לצד הרב אפרתי - בן אחותו (ולפי אלפסי - גיסו)."},{"i":29996,"n":"מזל, יוסף מויזון","b":"גביר תלמיד חכם בויזון. נכדו ר בנימין מפאנימאן."},{"i":29997,"n":"מזל, יוסף ממנצ'סטר","f":"אהרן","bt":"1850","bp":"ויז'ון-ליטא","b":"היגר לאנגליה-1890 בערך, והתישב במנצסטר והקים שם בית דפוס. תרגם לעברית את \"שמשון הגבור\" למילטון, ועוד. הו\"ל \"מכנף הארץ זמירות\", ועוד. עסקן ציוני וציר בקונגרס הציוני."},{"i":29998,"n":"מזל, יוסף שלמה מארגנטינה","f":"מנחם מנדל","k":"בעל כבוד התורה","bt":"תרטז","bp":"ויזון","dt":"תרפג - י אדר","b":"רב בבואנוס איירס-ארגנטינה. חתנו - ר גרשון חנוך הניך גינצבורג מבריסק."},{"i":29999,"n":"מזל, ישראל אברהם","f":"גדליה הי\"ד","bp":"בילאגורדגה-ווהלין","dt":"תשמז","b":"נכד ר יוסף טרוסטנצקי מבילאגורדגה נכדו של ר זושא (ומכן שם המשפחה - ר\"ת משולם זוסיא ליפמן). התחנך אצל זקנו ר משולם זוסיא לאחר שאביו נהרג בפוגרום. עלה לירושלים בזקנותו."},{"i":30000,"n":"מזקיטו, ברוך עזריאל מפיררה","b":"רב בפיררה-שכד. בדורו של הרמ\"ף, ובשות מוהרמא\"י תשובה ממנו."},{"i":30001,"n":"מזר (מייזלר), בנימין","k":"בעל ישראל בארצו","bt":"1906","bp":"גרודנא","b":"עלה לארץ-1929. ארכיאולוג ונשיא האוניברסיטה העברית. חיבר גם \"בית שערים\", ועוד."},{"i":30002,"n":"מזרחי עדני, שלום מתימן","f":"סעדיה","k":"בעל סוכת שלום","bt":"תרי","bp":"ביד'א או עדן - תימן","dt":"תרעג - יא אד\"א","dp":"ירושלים","b":"רב בתימן, עלה לירושלים-תרלה, מחברי \"בית אל\". התגורר בשכונת שמעון הצדיק בה התרכזה קהילת התימנים בירושלים. בשליחות \"בית אל\" בתונס, בהודו-תרנח - וסיפר על נסים שאירעו לו שם. ראש ישיבת \"תורת משה\". חיבר גם \"שלום ירושלים\". אחיו ר עאוץ' סאלם אלביצ'אני - שו\"ב בעדן ומוהל והו\"ל \"מקור חיים\". בניו ר סעיד ור אברהם שמעון שמואל."},{"i":30003,"n":"מזרחי שרעבי, אברהם רפאל שלום","f":"חזקיה יצחק (שלום)","k":"בעל דברי שלום","r":"נינו של הרש\"ש","bt":"תקלה","dt":"תקפז - כה כסלו","dp":"ירושלים","b":"נכדו של ר שלום שרעבי, היה ראש ישיבת המקובלים \"בית אל\" אחר פטירת רבו ר יום טוב אלגזי, חיבר ספר \"דברי שלום\" ירושלים תרג, חתנו היה הראשון לציון ר אברהם גאגין, חתום על כתב שליחות בשנת תקפו. (אצל רוזניס בלבול בינו לבין בנו)","bk":[["דברי שלום – דרוש",""],["דברי שלום",""]]},{"i":30004,"n":"מזרחי שרעבי, חזקיה יצחק מירושל","f":"שלום (הרש\"ש)","k":"הח\"י בשמ\"ש","dt":"תקסח","dp":"ירושלים","b":"רב בישיבת \"בית אל\" בירושלים לאחר פטירת אביו, ביחד עם ר יום טוב אלגזי שהיה ראש הישיבה. בשליחות חברון בשנים תקסב-ג בצפון אפריקה ובתונס, היה גם בהודו. בדרכו לקח עמו את סדור אביו בכתב יד ומאז נתפשט הסדור באותן המדינות. אחר פטירת ר יום טוב אלגזי עמד בראש הישיבה, בשנת תקסו, והיה דיין בבית דינו של ר מרדכי הלוי המכונה \"המליץ\". הסכים על ספר \"מזבח כפרה\" ו\"מראה האפנים\" לר יעקב פייתוסי. (אצל רוזניס בלבול בינו לבין אביו)"},{"i":30005,"n":"מזרחי, אברהם מאזמיר","dt":"תקסג - ז ניסן","dp":"אזמיר","b":"מחכמי אזמיר."},{"i":30006,"n":"מזרחי, אברהם מירושלים","f":"ברוך","k":"בעל זכרון לבני ישראל","b":"שו\"ב ודיין בירושלים-תמ, מחבר ספר \"זכרון לבני ישראל\" (נדפס בסוף ספר ימין משה אמשטרדם תעח). נכדיו ר משה בעל \"אדמת קודש\" ור מאיר בעל \"פרי הארץ\", היה תלמידו של ר שאול בן צאחיון."},{"i":30007,"n":"מזרחי, אבשלום מתורכיה","f":"משה","k":"בעל אמרי שפר","b":"מחכמי תורכיה-בשנות הר'. חיבר \"אמרי שפר\" והביא ממנו ר אברהם די בולמוס ב\"מקנה אברהם\"."},{"i":30008,"n":"מזרחי, אליהו - הנכד","b":"נכד הרא\"ם. מחכמי תורכיה-שן ונזכר בספרי חכמי דורו ובהם \"קורא הדורות\"."},{"i":30009,"n":"מזרחי, אליהו מחברון","b":"מחכמי חברון, חתם בשנת תכא על אגרת שליחות ר חייא דיין."},{"i":30010,"n":"מזרחי, אלעזר אליהו מירושלים","dt":"תרסז - כז כסלו","dp":"ירושלים","b":"מחכמי ירושלים, נפטר בצעירותו."},{"i":30011,"n":"מזרחי, בועז הבבלי","f":"יהונתן","b":"נדב קרקע בירושלים לבנין בתים לעניים בכפר השילוח והוקם שם כפר התימנים."},{"i":30012,"n":"מזרחי, בכור נסים יעקב מאזמיר","k":"בני\"ם - בעל ברוך מבנ","dt":"תרכט - כט אלול","dp":"אזמיר","b":"מרבני אזמיר. חיבר \"ברוך מבנים\"."},{"i":30013,"n":"מזרחי, ברוך","f":"שמואל בן שמעון מזאכו","k":"בעל שירי זמרה","bt":"תרנו","bp":"נציבין","b":"עלה לארץ-תרעא והיה מראשי עדת הכורדים בירושלים, ממיסדי אגודת \"אררט\" להתישבות הכורדים בארץ. חיבר ספר \"שירי זמרה\" ובו שירים וקינות של יהודי כורדיסטן."},{"i":30014,"n":"מזרחי, גייוזיפו משלוניקי","b":"גביר מראשי קהלת שלוניקי-תרלח."},{"i":30015,"n":"מזרחי, גמליאל","b":"מחכמי קושטא, תלמיד ר' רפאל ביטראן, רב באנטוורפן"},{"i":30016,"n":"מזרחי, גרשון","f":"אליה (הרא\"ם)"},{"i":30017,"n":"מזרחי, דוד מירושלים","b":"מרבני ירושלים. חתם על \"דברי שלום\"-תרג."},{"i":30018,"n":"מזרחי, זלמן יצחק מפאנימוניק","b":"גביר תלמיד חכם בפאנימוניק - ואמרו עליו בעירו: \"תורה חכמה ועשירות במקום אחד\"."},{"i":30019,"n":"מזרחי, חייא שלמה מירושלים","f":"ישראל מאיר-פרי הארץ","b":"מחכמי ירושלים-תקיח, מישיבת רבי יעקב פיררה - \"בית יעקב\". בשליחות במצרים-תקטו, תורכיה ויוון. הו\"ל ספר אביו \"פרי הארץ\" וחיבר לו הקדמה. דיין אצל ר מיוחס בכר שמואל יחד עם החידא - שהיה ידיד נעוריו, והביא מתורתו בספריו. בשנת תקיט חתם על שטר חזקה בירושלים."},{"i":30020,"n":"מזרחי, חיים אלעזר","k":"בעל חיאת אל איאם","bt":"תריח","bp":"טהרן-פרס","dt":"תרסט - כט סיון","dp":"ירושלים","b":"עלה לירושלים-תרנה, משורר, חיבר \"חיאת אל איאם (=חיי הימים) - ירושלים תרסו. בנו - ר חנינא."},{"i":30021,"n":"מזרחי, חיים הלל מירושלים","b":"מחכמי ירושלים-שנות ה-ת'."},{"i":30022,"n":"מזרחי, חיים יוסף","b":"אב\"ד בקושטא-תקמ\"ט"},{"i":30023,"n":"מזרחי, חיים מאיר מאזמיר","k":"בעל בן יאיר","b":"מחכמי ורבני איזמיר, דיין-תרל, חיבר \"בן הרמה\" ו\"בן יאיר\"."},{"i":30024,"n":"מזרחי, חיים משה","b":"מגדולי דייני ירושלים-תק\"ט"},{"i":30025,"n":"מזרחי, חיים נחום מצפת","f":"נסים","bt":"תקלט","bp":"אלגיר או עיראק","dt":"תריח - יב תשרי","dp":"ירושלים","b":"רב באלגיר, עלה לצפת-תקצב והיה רב הקהלה הספרדית. בשליחות צפת באיטליה ומרוקו-תרז. חתם ראשון על אגרות צפת משנת תקצט. המקור הוא בספר צפת ושם גם דעה שונה על מוצאו והיא: הגיע מקורדיסטן, ויש אומרים שהוא מצאצאי הרא\"ם."},{"i":30026,"n":"מזרחי, חיים שלמה","b":"מחכמי ירושלים-תק\"כ"},{"i":30027,"n":"מזרחי, חנינא מפרס","f":"חיים אלעזר","bt":"תרמו","bp":"טהרן-פרס","b":"עלה בילדותו לירושלים. מלמד בביהמ\"ד למורים \"מזרחי\", בישיבת \"תפארת ירושלים\", מנהל הת\"ת לעדת הספרדים, ראש הועד לעדת יהודי פרס בירושלים. חיבר ספרים ומאמרים ובהם ב\"ציון\", \"ההד\"."},{"i":30028,"n":"מזרחי, יהודה מקושטא","b":"גביר בקושטא, סייע לר יעקב כולי בהוצאת \"מעם לועז\"."},{"i":30029,"n":"מזרחי, יהושע מקושטא","b":"מדפיס בקושטא עם שותפיו רפאל טרוויש ויוסף אלקלעי, הדפיסו \"חדושי גטין\"-תעא."},{"i":30030,"n":"מזרחי, יוסף מאפיון וניקופול","b":"רב באפיון(=קארה-היסאר)-שנות ה-ש', היה מחלוקת כנגדו ועזב רב וראש ישיבה בניקופול, ותלמידו ר רפאל וינטורה על מקומו אחריו."},{"i":30031,"n":"מזרחי, יוסף מירושלים","f":"יוסף בן אברהם","b":"מגדולי חכמי ירושלים-ת\"צ"},{"i":30032,"n":"מזרחי, יוסף מירושלים","f":"נסים חיים משה מזרחי","dt":"תפט - כז אייר","b":"מחכמי ירושלים. נפטר צעיר בחיי אביו הראשל\"צ."},{"i":30033,"n":"מזרחי, יוסף מקושטא","f":"יעקב","b":"מדפיס-תעא בדפוס של יונה בן יעקב בקושטא."},{"i":30034,"n":"מזרחי, יוסף מקושטא","b":"דיין בקושטא-תקף עם ר אברהם הלוי, ור חיים מזרחי ירושלמי."},{"i":30035,"n":"מזרחי, יוסף משלוניקי","dt":"תקלט","dp":"שלוניקי","b":"גביר בשלוניקי. חתנו - ר יוסף הכהן ן ארדיט (והיה סמוך על שלחן חותנו שנים רבות)."},{"i":30036,"n":"מזרחי, יעקב משה משלוניקי","b":"גביר בשלוניקי, ונמנה על שבעת טובי העיר-תריז."},{"i":30037,"n":"מזרחי, יצחק מירושלים","bp":"קושטא?","b":"עלה מקושטא לירושלים. מקובל בירושלים, מחבורת \"אהבת שלום\" של מקובלי \"בית אל\"-תקיח. חתם על שטר התקשרות עם חכמי ירושלים-תקיד."},{"i":30038,"n":"מזרחי, ישראל","f":"אליהו-הרא\"ם","b":"מגדולי חכמי דורו-שכ. נזכר באבקת רוכל. הו\"ל ספר אביו על רש\"י לתורה."},{"i":30039,"n":"מזרחי, ישראל מאיר מירושלים","f":"יוסף","k":"בעל פרי הארץ","dt":"תקט או תפט","dp":"ירושלים","b":"נכד ר אברהם מזרחי בעל זכרון לבני ישראל. לאחר שנתייתם גדל אצל אחיו ר נסים חיים משה בעל אדמת קודש, ולימים חתן אחיו הנ\"ל. תלמיד ישיבת פירירה בירושלים אצל ר יהודה הכהן טנוג'י, ור אברהם יצחקי בישיבת \"בית יעקב\" בירושלים, ותלמיד ר חיים אלפנדרי שהגיע מקושטא לירושלים. רב בירושלים. בשליחות בטורקיה-תפג. בשנת תקא חתם על כתב שליחות ר יצחק זרחיה אזולאי, עמד בראש ישיבת \"בית יעקב\". בנו ר שלמה חייא הו\"ל את ספרו \"פרי הארץ\". חיבר גם \"תפארת ישראל\", \"נר המזרחי\" ועוד. הוא ואחיו נקראו בשם \"נרות המזרחיים\". בניו - ר שלום-נפטר בחיי אביו, ר חייא שלמה. הסכים על: \"אדמת קדש\"-תצט, \"חוט המשנה\"-תצט, \"חזון נחום\"-תקב, \"שו\"ת הרדב\"ז\"-תקב, \"ועוד.","bk":[["פרי הארץ (נר מזרחי) [שו\"ת]",""],["פרי הארץ",""]]},{"i":30040,"n":"מזרחי, מואיז אברהם משלוניקי","f":"אברהם","dt":"תרע","dp":"פאריס","b":"אחיינו-בן אחותו של ד\"ר משה אלאטיני. רופא בשלוניקי, פעל להקמת ביה\"ח הירש בשלוניקי-תרסח, עבר לפאריס-תרסט."},{"i":30041,"n":"מזרחי, משה מחלב","f":"אברהם יוסף","bt":"תרכ","b":"תלמיד ר נסים לוסיץ(אולי לופיז). רב בארם צובה-תרע."},{"i":30042,"n":"מזרחי, משה מירושלים","f":"יהודה","dt":"תרל - טו אב","dp":"ירושלים","b":"מחכמי ירושלים, וחתם על ההסכם עם האשכנזים ע\"ד \"המנורה\"-תרכד."},{"i":30043,"n":"מזרחי, משה עזרא מאר\"ץ","f":"עזרא","k":"בעל דברי משה","bt":"תרכג","bp":"חלב","dt":"תשטו - ו אב","b":"נקרא ע\"ש אביו שנפטר לפני לידתו. תלמיד ר חיים הכהן ור בכור מזרחי ור משה סוויד בחלב. חתן ר שלום הדאיה. דיין בחלב יחד עם ר עזרא חמווי, ור עזרא עבאדי שעיו. רב ראשי על מקום ר עזרא חמווי. מתורתו ב\"המאסף\". חיבר מערכות על הש\"ס. בנו ר שלום יצחק בעל \"דברי שלום\".","bk":[["דברי משה","שו\"ת - אחרונים"]]},{"i":30044,"n":"מזרחי, נחום הכהן מטבריה","b":"מחכמי טבריה, בשליחות בשנת תרכח. בשנת תרכז חתם עם חכמי טבריה."},{"i":30045,"n":"מזרחי, נסים חיים משה מירושלים","f":"יוסף","k":"בעל אדמת קדש","r":"אב\"ד ור\"מ פרנקפורט","bt":"תן - בערך","dt":"תקט - ד תמוז","dp":"ירושלים","b":"דיין בירושלים עם ר ישעיה אזולאי ור ידידיה הכהן, אחיו של ר ישראל מאיר מזרחי, היה רבו של החיד\"א. בשנים תצט - תקה חתם על תקנות וכתב שליחות. בשנת תקה נתמנה ל\"ראשון לציון\" (הראשון המכונה בשם זה) אחרי ר אליעזר נחום. חיבר \"אדמת קודש\" קושטא תקב. ראש ישיבת \"בית יעקב\" פיררה בירושלים. מבין 10 ילדיו: ר יוסף - נפטר בחייו-תפט, יצחק - נפטר בן 14, ר פנחס מירושלים. מחתניו - אחיו ר ישראל מאיר. ירש בתים בירושלים מזקנו - ר ברוך מזרחי. נאסמר-תפז בגלל חובות הקהלה.","bk":[["אדמת קודש ח\"א","שו\"ת - אחרונים"],["אדמת קודש",""]]},{"i":30046,"n":"מזרחי, נסים יצחק מקושטא","b":"רב בקושטא, ממונה על איסור והיתר-תקצד, עלה לארץ."},{"i":30047,"n":"מזרחי, נסים מחלב","dt":"תכה - יח אב","dp":"חלב","b":"מגדולי רבני ארם צובא,איש מופת"},{"i":30048,"n":"מזרחי, עזריה מאזמיר","b":"שו\"ב ורב באזמיר-תכג. שאלה ממנו ב\"בעי חיי\" אודות תרנגולים הנקראים \"טיפיליס\"."},{"i":30049,"n":"מזרחי, פנחס יוסף מירושלים","f":"משה","bt":"תעו - בערך","b":"חזן מחכמי ישיבת בית יעקב פיררה בירושלים-תקיח, ומלמד תורה. יצא לשלוניקי להדפיס ספר אביו \"אדמת קדש\". בנו - גבריאל (נפטר בחייו?), אחיו - ר דוד מיכאל."},{"i":30050,"n":"מזרחי, צדוק חי","dt":"תשכ","b":"מגדולי הרבנים הספרדים,מרבני רחובות"},{"i":30051,"n":"מזרחי, ראובן מקושטא","f":"חנניה","k":"בעל מעין גנים","bt":"תלה - בערך","dt":"תק - בערך","dp":"קושטא?","b":"מצאצאי ר אליהו מזרחי (=הרא\"ם). תלמיד ישיבת ר שמואל הלוי. דרשן בקהלת גברת בקושטא-תן, נאלץ לנדוד לאזמיר-תעב בערך וחזר לקושטא. חיבר \"מעין גנים\" קושטא, \"באר מים חיים\" ועוד."},{"i":30052,"n":"מזרחי, רחמים מירושלים","f":"שלמה מירושלים","bt":"תרה","bp":"ירושלים","b":"גביר מחכמי ירושלים."},{"i":30053,"n":"מזרחי, רחמים נסים מירושלים","b":"מצאצאי הרא\"ם. רב בירושלים-תקפ, צפת. בנו ר חיים נחום מזרחי מרבני צפת - בשליחות באיטליה."},{"i":30054,"n":"מזרחי, רחמים פנחס מירושלים","b":"מחכמי ירושלים-תרג, חתם על שטר שליחות מטעם ישיבת \"בית יעקב פיררה\" בירושלים."},{"i":30055,"n":"מזרחי, רפאל דוד מקושטא","k":"בעל צעיר רודם","b":"רב בקושטא, שלוניקי-תקץ."},{"i":30056,"n":"מזרחי, רפאל פנחס מירושלים","f":"נסים חיים משה מזרחי","b":"דיין בירושלים, הו\"ל ספר אביו \"אדמת קדש\"-תקטז."},{"i":30057,"n":"מזרחי, שבתי משלוניקי","f":"אברהם","dt":"רצח","dp":"שלוניקי","b":"נהרג עק\"ה בשלוניקי."},{"i":30058,"n":"מזרחי, שלום יצחק מחלב","k":"בעל דברי שלום","r":"חבר בית הדין הגדול בירושלם","bt":"תרפא","bp":"חלב","dt":"תשנו - כו טבת","b":"עלה בילדותו לירושלים, תלמיד \"פורת יוסף\" אצל ר עזרא עטייה. דיין בירושלים. חתן ר עזרא עבאדי שעיו. מתורתו ב\"גנזי ארץ\".","bk":[["דברי שלום","שו\"ת - אחרונים"],["דברי שלום [שו\"ת]",""],["דברי שלום - שו\"ע",""]]},{"i":30059,"n":"מזרחי, שלמה מאזמיר","b":"תלמיד בישיבת ר חיים פלאג'י באזמיר, ונזכר בספרו."},{"i":30060,"n":"מזרחי, שלמה מירושלים","b":"דיין בירושלים-תקיט. ראה גם: חייא שלמה."},{"i":30061,"n":"מזרחי, שלמה מירושלים - ב","f":"יצחק","bt":"תרנד","bp":"ירושלים","b":"מצאצאי בעל \"אדמת קדש\" ו\"פרי הארץ\". תלמיד ישיבת \"תפארת ירושלים\", ביהמ\"ד לחברת \"עזרא\" אצל רי\"חי אובלעפיה, רב\"צ אברהם קואינקה, ור בן ציון חי עוזיאל. רב בקהלת \"עץ חיים\" באינדיאנפוליס-תרפו, \"אהל אברהם\"-לוס אנג'לס-תרץ."},{"i":30062,"n":"מזרחי, שמואל","b":"חכם העיר בזאכו,נציבין-תר\"נ"},{"i":30063,"n":"מזרחי, שמעון מבגדד","f":"יונה","k":"בעל כנפי יונה","b":"מחכמי בגדד-תנו, חיבר ספר על עיבור השנה \"כנפי יונה\" ונהגו לקבוע את הלוח בבגדד ע\"פ ספרו."},{"i":30064,"n":"מזרחי, ששון עבד אל עזיז","k":"בעל באתי לגני","bt":"תרעד","bp":"בגדד","dt":"תשנח","dp":"ירושלים","b":"מקובל מחכמי בגדד, תלמיד ר יעקב מוצפי, ור יהושע משה מבגדד, ור יהודה פתייא. עלה לירושלים, ולמד ביחד עם ר יהודה צדקא."},{"i":30065,"n":"מזרחי, ששון? מבגדד","f":"מזרחי, שמעון","k":"בעל כנפי יונה","b":"מחכמי בגדד."},{"i":30066,"n":"מזרחי-ירושלמי, חיים מקושטא","b":"דיין בקושטא-תקף עם ר אברהם הלוי, ור יוסף מזרחי."},{"i":30067,"n":"מזרחי-משרקי, דוד","f":"שלמה","k":"בעל שתילי זיתים","r":"גדול חכמי תימן בדורו ורבו של ר' יחיא צאלח","bt":"תנו","bp":"צנעא","dt":"תקלב","b":"מורי ומנהיג רוחני, שינה את הנהוג בתימן לפסוק לפי הרמב\"ם, והוא נסמך על השולחן ערוך, חיבר \"שתילי זיתים\" ספר יסודי בהלכה","bk":[["רביד הזהב","שו\"ת - אחרונים"],["ראשי בשמים - יו\"ד",""],["רביד הזהב - שו\"ע ושו\"ת",""],["שתילי זתים - או\"ח",""]]},{"i":30068,"n":"מזריטש, אברהם יהודה ליב","dt":"תקסז","b":"מו\"ץ ודיין בקהלת האשכנזים בהאג-תקל. הסכים על \"ספר הברית\" ברלין תקנז."},{"i":30069,"n":"מזריטש, אהרן מפרוסטיץ","f":"יצחק מזריטש","dt":"תקז - א כסלו","b":"רב בפרוסטיץ-ת\"ס"},{"i":30070,"n":"מזריטש, איסר"},{"i":30071,"n":"מזריטש, אשר אנשיל מאלטונא","dt":"תמד - ה אלול","dp":"אלטונא","b":"מגולי פולין, רב בהמבורג, דיין באלטונא."},{"i":30072,"n":"מזריטש, יהודה ליב ממזריטש","f":"צבי הירש ממזריטש","dt":"תקו - יא אייר","dp":"המבורג","b":"אב\"ד מזריטש (הוא או אביו)."},{"i":30073,"n":"מזריטש, משה אריה מבאטורקעס","f":"אהרן מזריטש","dt":"תקסב - כז אדר","b":"רב בבאטורקעס"},{"i":30074,"n":"מזריטש, נתן נטע","f":"נחום","dp":"ירושלים","b":"אביו ר נחום היה אבד סלוצק, ומצאצאי מהרם פאדובה. בהקדמה לספר \"המאור והמלחמות\", כותב ר מרדכי בן שמעון מבריסק נין ונכד לר נתן נטע שנפטר בירושלים."},{"i":30075,"n":"מחביב, משה מקושטא","f":"מימון","b":"מסדר אותיות בדפוס קושטא-רפ."},{"i":30076,"n":"מחווג, שלום מתימן","b":"מחכמי צנעא - במאה ה-18."},{"i":30077,"n":"מחרינסקי, שלמה זלמן","f":"אלתר","bt":"תרמ","b":"נסמך מאת: ר אהרן מטשודנוב. ר\"ב בבילילובקה-פלך קיוב-תרס."},{"i":30078,"n":"מטאלון, אברהם","dt":"תרח - יח כסלו","b":"מרבני ירושלים"},{"i":30079,"n":"מטאלון, אברהם משלוניקי","f":"עזריאל","b":"דרשן ורב בשלוניקי, בזמן ר יעקב מאיר-תרע. היה מהאחרונים שחבשו \"בוניטי\" מצנפת מיוחדת שהיתה מקובל בזמן התורכים."},{"i":30080,"n":"מטאלון, אברהם משלוניקי","f":"מרדכי","dt":"תרכז","dp":"שלוניקי","b":"דיין בשלוניקי. נפטר במגיפה."},{"i":30081,"n":"מטאלון, אליהו משלוניקי","b":"גביר בשלוניקי. סייע בהדפסת \"מטה שמעון\" לר מרדכי שמעון-תקעד."},{"i":30082,"n":"מטאלון, אשר","b":"מחכמי אזמיר"},{"i":30083,"n":"מטאלון, דוד חיים מקושטא","b":"רב בשלוניקי, קושטא-שנות ה-ת'-תק'."},{"i":30084,"n":"מטאלון, דוד יעקב משלוניקי","b":"מראשי קהלת שלוניקי-תרפא."},{"i":30085,"n":"מטאלון, דוד יעקב משלוניקי","b":"נבחר לפרלמנט היוני מטעם שלוניקי."},{"i":30086,"n":"מטאלון, וידאל משלוניקי","dt":"שא - י אלול","dp":"שלוניקי","b":"מחכמי שלוניקי."},{"i":30087,"n":"מטאלון, חיים בכור משלוניקי","f":"שמואל","k":"שלוניקי","bt":"תרכא","dp":"תרע","b":"גביר מחכמי שלוניקי, דרשן מפורסם. תרם לבית החולים הירש, ועניני צבור בשלוניקי."},{"i":30088,"n":"מטאלון, חיים משלוניקי","f":"שלמה","dt":"שנו","b":"מחכמי שלוניקי. אחיו של ר יעקב."},{"i":30089,"n":"מטאלון, יהודה משלוניקי","dt":"תרם - חשון","dp":"שלוניקי","b":"מחכמי שלוניקי. נספד ע\"י ר שמעון מנשה ב\"שם משמעון\"."},{"i":30090,"n":"מטאלון, יוסף מירושלים","b":"מגדולי רבני ירושלים-תר\"ל"},{"i":30091,"n":"מטאלון, יעקב משלוניקי","b":"רב בשאלוניקי-שנ\"ד"},{"i":30092,"n":"מטאלון, יעקב משלוניקי","f":"שלמה","k":"בעל שארית יעקב","dt":"שמ","b":"מרבני שאלוניקי. נפטר בחיי אביו. חיבר גם \"תולדות יעקב\"."},{"i":30093,"n":"מטאלון, יעקב משלוניקי","f":"שלמה","dt":"שנו - יח ניסן","dp":"שלוניקי","b":"מחכמי שלוניקי. אחיו של ר חיים. נספד בידי ר סעדיה לונגו."},{"i":30094,"n":"מטאלון, יעקב שמעון מירושלים","f":"שמעון או שמשון","dt":"תרסט - טו תשרי","dp":"ירושלים","b":"ראב\"ד עדת הספרדים בירושלים, דיינים אצלו: ר שמואל נסים, ר חיים דוד סורנאגה, ר מנחם ש\"ט הכהן, ר שמואל מיוחס, ר וידאל בן חנוך אנגל, ר מרדכי ישראל, ר שלום הדאיה, ר אהרן בכור אלנקוה. השתתף בחדושי תורה בקבצים \"תורה מציון\" ו\"המאסף\". בשנת תרלד חתם בקונטרס \"כנסיה לשם שמים\". תשובותיו הובאו בספר \"שערי רחמים\"."},{"i":30095,"n":"מטאלון, יצחק משלוניקי","dt":"תקסא","dp":"באזארייה-שלוניקי","b":"גביר בשלוניקי-שנות ה-תק', נהרג ביריד באזארייה. נספד מאת ר חיים אברהם אישטרושא."},{"i":30096,"n":"מטאלון, מאיר מבגדד ויפו","f":"אהרן","bt":"תקסח","bp":"בגדד","dt":"תרן - יב כסלו","dp":"יפו","b":"ממחדשי הישוב היהודי ביפו, עסקן צבור ומראשי הקהלה, ומסייע לעולים לארץ שהגיעו ליפו."},{"i":30097,"n":"מטאלון, מואיז משלוניקי","b":"רופא בשלוניקי-תרס."},{"i":30098,"n":"מטאלון, מיכאל משלוניקי","dt":"ת? - י אלול","dp":"שלוניקי","b":"מראשי קהלת שלוניקי."},{"i":30099,"n":"מטאלון, מנחם מאזמיר","b":"רב באזמיר. תשובה ממנו ב\"מזכרת משה\" לר משה בראקי."},{"i":30100,"n":"מטאלון, מרדכי בכור משלוניקי","dt":"תרז","dp":"שלוניקי","b":"רב הכולל בשלוניקי-תקצב על מקום ר יעקב מנשה - יחד עם ר משה ברכה ואח\"כ עם ר שאול מולכו. הושעה מרבנותו ע\"י הגבירים לאחר שהתיר לגביר יהושע מודיאנו שהיה נתין איטלקי לשאת נערה יהודה בעלת נתינות תורכית. בניו: ר אברהם, ר שמואל - דיינים בשלוניקי. על מצבתו כונה \"הגאון\" והיה היחיד מרבני שלוניקי שכונה כך. חתם-תקצה עם ר אשר קובו ור משה ברכה, וחתם-תקפב גם עם ר חיים יוסף ן אדון ור שאול בן יצחק מולכו."},{"i":30101,"n":"מטאלון, מרדכי משלוניקי","dt":"ת - כג חשון","dp":"שלוניקי","b":"גביר מחכמי שלוניקי."},{"i":30102,"n":"מטאלון, מרדכי משלוניקי - א","f":"חיים","bt":"רסב","dt":"שמ - יח שבט","dp":"שלוניקי","b":"תלמיד ר יוסף טאיטצאק, רב בשלוניקי-שכ. חברו של המהרשד\"ם, ור יצחק אדרבי. חיבר פירוש לתנ\"ך. מתשובותיו ב\"דברי רבות\" ובשו\"ת מהרש\"ך. מתלמידיו: אחיינו - ר יעקב בעל \"שארית יעקב\", ר אהרן ששון-חתנו של ר שלמה הלוי בעל \"תורת אמת\", ר יעקב מטאלון. נספד ע\"י ר סעדיה לונגו."},{"i":30103,"n":"מטאלון, מרדכי משלונקי - ב","dt":"תקל - לפני","dp":"שלוניקי","b":"דיין בשלוניקי."},{"i":30104,"n":"מטאלון, משה דוד מדמשק","dt":"תרם","dp":"שלוניקי","b":"רב בדמשק, חתם-תרם עם ר יצחק אבולעפיה ור מסעוד פינטו."},{"i":30105,"n":"מטאלון, משה מאיר מניו יורק","b":"רב בניו יורק-תר\"נ"},{"i":30106,"n":"מטאלון, משה מיפו","f":"יצחק","bt":"תרלב","bp":"יפו","b":"תלמיד ר יוסף שמחון מיפו. עו\"ד וסוחר קרקעות ביפו, מנהל ומפקח הת\"ת \"תורה אור\" ביפו, לחם במסיון."},{"i":30107,"n":"מטאלון, משה משלוניקי","b":"דיין בשלוניקי-של."},{"i":30108,"n":"מטאלון, עזריאל משלוניקי","f":"דוד","dt":"תרנז - יא טבת","dp":"שלוניקי","b":"דיין בשלוניקי. בנו - הדיין ר אברהם עזריאל."},{"i":30109,"n":"מטאלון, עזריאל משלוניקי","f":"אברהם","dp":"ניו יורק","b":"דרשן בשלוניקי-תרף כאביו לפניו. נסע לארה\"ב ונפטר שם."},{"i":30110,"n":"מטאלון, רפאל יעקב ג'יליבי","dt":"תקעו - י אב","dp":"ירושלים","b":"מחכמי ירושלים, בשנת תקסו בשליחות בתורכיה-תקעג עם ר יעקב הכהן רפפורט."},{"i":30111,"n":"מטאלון, שלמה משלוניקי","b":"מרבני שאלוניקי-ש\"ך"},{"i":30112,"n":"מטאלון, שלמה משלוניקי","f":"חיים","dt":"שסב - ז ניסן","dp":"שלוניקי","b":"רב וראש ישיבה בשלוניקי. מתלמידיו ר אהרן חסון, ור אהרן ששון. בנו ר יעקב בעל \"שארית יעקב\". אחיו של ר מרדכי. שלושת בניו נפטרו בחייו."},{"i":30113,"n":"מטאלון, שמואל משלוניקי","f":"מרדכי","k":"בעל עבודת השם","dt":"תרנא - א אד\"ב","dp":"שלוניקי","b":"רב ודיין בשלוניקי-תר, אחיו של ר אברהם. רבים מכתביו אבדו בשרפה הגדולה בשלוניקי-תרן. בניו ר חיים ר יעקב ור משה ממנו והדפיסו את ספרו \"עבודת השם\" - תרנג."},{"i":30114,"n":"מטארון, יוסף מירושלים","b":"מחכמי ירושלים, בין שבעת החותמים על ההסכמה-שפג."},{"i":30115,"n":"מטוט, יעקב מאלגיר","f":"משה","bt":"תן","dt":"תקך - בערך","b":"מחכמי תלמסאן. נזכר בשטר משנת תק."},{"i":30116,"n":"מטוק, ישראל איזידור","bt":"1883","bp":"ליטא","dt":"1954","b":"תלמיד אוניברסיטת הארוורד, והיברו יוניון קולג'. רב ריפורמי בלניקולן נובה, ניו יורק, לונדון. ממיסדי האגוד העולמי ליהדות מתקדמת. חיבר ספרים באנגלית בנושאים יהודיים."},{"i":30117,"n":"מטורציאנו, שלמה מספרד","bt":"שפה","bp":"טורציאנו-ספרד","b":"הגיע מספרד לאיטליה, תלמיד הרמ\"ע מפאנו, נזכר ב\"באר עשק\", ובאגרת שלומים-שפה בשם \"החכם טיראצי\". מהסובלים בפרעות אבן פארוך."},{"i":30118,"n":"מטטרון, יוסף משלוניקי","b":"מדפיס בדפוס גדיליה בשלוניקי--רפא."},{"i":30119,"n":"מטיס, משה מליטא","b":"מראשי חברת \"מפיצי השכלה\" בקובנא. אשתו אנה בת שמעון היתה מראשי האידישיסטים בליטא, ממיסדות ביה\"ס למלאכה \"טרוד\" בקובנא - לפני מלחה\"ע ה-I. נספו בשואה."},{"i":30120,"n":"מטיש, וולף ממיקוליניץ","b":"רב במיקוליניץ-תרכו."},{"i":30121,"n":"מטקיבר, מנחם מנדל מטורקא","b":"רב בטורקא-תרל. נכדתו נשאה לר אהרן זאב הלוי וייסבלום שמילא את מקומו."},{"i":30122,"n":"מטריל, יעקב ממצרים וירושלים","b":"דיין במצרים אצל ר יצחק שולאל, עלה לירושלים-רסט."},{"i":30123,"n":"מטרסדורפר, יהודה ממטרסדורף","bp":"פולין","b":"הגיע מפולין. רב במטרסדורף."},{"i":30124,"n":"מיאדלער, אהרן מהורדנא","f":"יהודה דוד","k":"בעל ביאור לאקדמות","b":"רב בהורדנא. מכונה אהרן מאלאשקביץ. (כנראה שמוצאו מיאדלר והיה גם באלשקביץ)."},{"i":30125,"n":"מיאדניק, גרשון","dt":"תשא - כז אלול","b":"ר\"מ בקעלם"},{"i":30126,"n":"מיגאגין, אליהו מירושלים","dt":"תקיג","dp":"צפת","b":"מחכמי שלוניקי, עלה לירושלים ובסוף ימיו לצפת. אחיו ר מצליח היה רב בסרייבו, וגם ר אליהו ישב שם מספר שנים. תשובה ממנו בספר \"שמש צדקה\" לר שמעון מורפורגו."},{"i":30127,"n":"מיגאני, מצליח משלוניקי","b":"מגדולי חכמי דורו בשאלוניקי-ש\"פ"},{"i":30128,"n":"מיגאש","k":"ראה: מיגש","b":"מחמכי שלוניקי-שפ."},{"i":30129,"n":"מיג'י, אברהם ישראל משלוניקי","dt":"תש..","b":"מחכמי שלוניקי, סופר גיטין וסת\"ם."},{"i":30130,"n":"מיגש ן, אברהם הלוי מאדרינופול","k":"בעל עבודת הלוי","dt":"שמד - בערך","b":"רופא ממשפחה ממגורשי ספרד באדרינופול, רב בחלב-ש', רופא בחצר השולטן בקושטא. חיבר גם \"כבוד אלקים\", \"עמק שידים\", ועוד. נזכר ב\"אבקת רוכל\"."},{"i":30131,"n":"מיגש ן, אברהם הלוי מארץ ישראל","b":"מחכמי ארץ ישראל-ש\"כ"},{"i":30132,"n":"מיגש ן, אברהם מקושטא","b":"רב בקושטא, נתבקש לכהן כרב בדמשק על מקום ר משה נג'ארה - אך לא הסתייע ונשאר בקושטא. גיסו - ר ישועה מחלב ודמשק."},{"i":30133,"n":"מיגש ן, יוסף הזקן","b":"זקנו של הר\"י מיגש. ואביו של ר מאיר הלוי."},{"i":30134,"n":"מיגש ן, מאיר מברושא","b":"רב בברושא(=ברוסא) - בדור שלאחר הגירוש."},{"i":30135,"n":"מיגש ן, מאיר מספרד","f":"יוסף","b":"אביו של הר\"י מיגש."},{"i":30136,"n":"מיגש ן, מאיר מספרד","f":"יצחק","b":"אחיינו של הר\"י מיגאש. רב בספרד בזמן רבינו תם."},{"i":30137,"n":"מידונסה די, אמון משלוניקי","b":"רופא בשלוניקי-תרס, ממיסדי אגודת \"לה אונייון\", ורופא לקונסוליה הסרבית-תרסד."},{"i":30138,"n":"מיו רפאל יצחק בן אהרן","dt":"ה'תקע 1810","bk":[["דרכי הי\"ם",""],["פאת ים",""],["שפת הים",""],["שרשי הי\"ם",""]]},{"i":30139,"n":"מיואני, יום טוב","k":"רב תיטב","dt":"ד'תתקנא","b":"עק\"ה,מגדולי בעלי התוספות,פוסק,פייטן,מרביץ תורה ביורק(אנגליה)"},{"i":30140,"n":"מיוחס בן יוסף מירושלים","f":"מנחם בן יוסף מירושלי","b":"חתם-תקיו על שטר התקשרות עם חכמי ירושלים ושמו נרשם בטעות מיוחס במקום מנחם."},{"i":30141,"n":"מיוחס לרבינו אשר","bk":[["בשמים ראש - שו\"ת",""]]},{"i":30142,"n":"מיוחס מירושלים","f":"שמואל","dt":"תלא","b":"מחכמי ישיבת בית יעקב פיררה בירושלים-תקו. (ואולי הוא ר אברהם בן שמואל מיוחס)."},{"i":30143,"n":"מיוחס, אבטליון מיוון","f":"שמואל","b":"פייטן. סליחה ממנו במחזורי צפון אפריקה \"אוי נא לנו כי חטאנו\"."},{"i":30144,"n":"מיוחס, אברהם מקושטא","f":"יהודה","k":"בעל בני אברהם","b":"מחכמי קושטא, אב\"ד-תצז-תקכט, חיבר שו\"ת \"בני אברהם\" ונדפס עם ספר אחיו - ר נתן \"שבת אחים\". בנו - ר יהודה."},{"i":30145,"n":"מיוחס, אברהם משה פרנס מירושלים","f":"שמואל","k":"ר משה הפרנס","b":"רב ופרנס בירושלים כאביו לפניו. בנו של הפרנס ר שמואל מיוחס הראשון. נאסר בירושלים-תפג עד לקבלת כופר לשחרורו ועל כך נסע אחיינו ר רפאל בעל פרי האדמה לקושטא. בנו - ר מרדכי."},{"i":30146,"n":"מיוחס, אהרן משירון","b":"מראשי קהלת שירון-שנות ה-ת'."},{"i":30147,"n":"מיוחס, אליהו נסים שמואל מאזמיר","dt":"תקמב - כט אב","dp":"אזמיר","b":"מחכמי אזמיר."},{"i":30148,"n":"מיוחס, אליעזר מחברון","f":"יוסף","bt":"תקעד","bp":"חברון","b":"מחכמי חברון, הסכים על ספר \"שמן המור\""},{"i":30149,"n":"מיוחס, אלעזר מירושלים","b":"מחכמי ירושלים - בשנות ה-תר'. חתן ר אברהם פנסו."},{"i":30150,"n":"מיוחס, בנימין חיים מירושלים","dt":"תקפ-ד - כד שבט","dp":"ירושלים","b":"מחכמי ירושלים. (תאריך פטירתו נרשם גם תקף או תקפט)."},{"i":30151,"n":"מיוחס, בנימין משה מירושלים","f":"אברהם","dt":"תקסה-ח - ב תשרי","b":"בשנת תקמב שליח ירושלים בארצות הים התיכון, הדפיס ספרו של אביו \"שדה הארץ\", בשנת תקנז בשליחות במרוקו, ושם ערך הסכם לחלוקת התרומות בין ארבע ערי הקודש, מובא בספרו של הרב טולידנו \"אוצר גנזים\". בשנת תקסג חתם על שטר חזקה. בנו ר שלמה יצחק בעל \"חשק שלמה\""},{"i":30152,"n":"מיוחס, חיים יעקב מקושטא","f":"נתן","b":"אב\"ד בקושטא-תקכ\"ט"},{"i":30153,"n":"מיוחס, יהודה מקושטא","f":"נתן","k":"בעל מאורות נתן","b":"מחכמי ורבני קושטא,דיין בקושטא-תקמ\"ט,חיבר שו\"ת \"מאורות נתן\"."},{"i":30154,"n":"מיוחס, יהודה מקושטא","f":"אברהם","b":"ממונה על איסור והיתר בקושטא-תקכט (יחד עם ר נסים גבאי)."},{"i":30155,"n":"מיוחס, יוסף אהרן מירושלים","b":"מחכמי ירושלים, בשנת תרמו בשליחות בהודו ותימן."},{"i":30156,"n":"מיוחס, יוסף יום טוב מירושלים","f":"רפאל?","b":"רב בירושלים-תקצח. חתם-תרט על כתב שליחות ר מרדכי חיים מיוחס, יחד עם חבריו - ר יצחק קובו, ר בנימין מרדכי נבון, ור מרדכי אליעזר סוזין. בנו - ר רפאל אברהם בכור."},{"i":30157,"n":"מיוחס, יוסף יעקב מחברון","f":"אברהם","dt":"תקפד","dp":"ירושלים","b":"דיין בקושטא אצל ר אליהו פאלומבו, עלה לארץ והיה מחכמי חברון, בשליחות במרוקו בשנת תקמח אך שינה מסלולו לאיטליה בגלל מצבם הקשה של היהודים במרוקו. הדפיס את ספר אביו \"שדה הארץ\" (הכוונה כנראה לחכם אחר באותו השם). חתם על תקנות ישיבת ייאני בשנת תקע."},{"i":30158,"n":"מיוחס, יוסף יעקב מירושלים","f":"רפאל אברהם","k":"בעל מלבושי יום טוב","dt":"תקעח - כד תשרי","dp":"ירושלים","b":"מחכמי ירושלים, חיבר \"מלבושי יום טוב\". חתם על אגרת בשנת תקנט."},{"i":30159,"n":"מיוחס, יוסף מירושלים","f":"רחמים נתן","k":"בעל שיחת ישמעאל","bt":"תרכח","bp":"ירושלים","b":"חתן ר יחיאל מיכל פינס. תלמיד \"דורש ציון\" בירושלים, ישיבת \"אהל יוסף\" של משפחת מיוחס, ואצל ר אליהו טראגאן, ר מירקדו הכהן, ר שם טוב אלפנדרי, ר יהודה פאניז'ל, ועוד. בקי בשפות ומלמד, ממיסדי הספריה \"גנזי יוסף ומדרש אברבנאל\"-תרנב, פעיל צבור וציוני. חיבר ספרים ופרסם מאמרים בבלשנות ושפות, פרסם מאמרים ב\"ירושלים\" - ירושלים תרמב-תרעט."},{"i":30160,"n":"מיוחס, יוסף שמואל מרד","dt":"תרעח - ב טבת","b":"מגדולי רבני ירושלים,שד\"ר למצרים והודו"},{"i":30161,"n":"מיוחס, יעקב יוסף מירושלים","f":"אברהם","dt":"תקכד - ה אייר?","dp":"ירושלים","b":"מרבני ירושלים, הקדמה ממנו לספר אביו. (לדעת ריבלין נפטר אחרי תקנח)."},{"i":30162,"n":"מיוחס, מרדכי חיים מירושלים","f":"יוסף","k":"מחני\"ם","b":"מחכמי ירושלים, בשנת תקע ובשנת תריד חתם על תקנות ישיבת ייאני. דיין בירושלים-תרטז עם ר חיים דוד חזן, ר רפאל מאיר פאניזל. בשנת תקצח בשליחות ירושלים, בשנת תרטו חתם על כתב שליחות ר חיים צרפתי ועוד. חתם על תקנת החזקות-תריח.משגיח בישיבת \"חיים וחסד\" בירושלים. פרסם מאמרים ב\"שומר ציון הנאמן\" - אלטונא תרו-תרטז. חיבר פירוש לתורה - בכת\"י."},{"i":30163,"n":"מיוחס, מרדכי מאלכסנדריה","b":"רב באלכסנדירה-שסב. נזכר בספר הדרשות לר חיים חברייא..."},{"i":30164,"n":"מיוחס, מרדכי מירושלים","f":"שמואל יום טוב","bt":"תרלז","bp":"ירושלים","b":"ראש השוחטים בירושלים-תרעד, דיין-תרעז אצל ר בן ציון קואינקה."},{"i":30165,"n":"מיוחס, מרדכי מירושלים","f":"אברהם משה","b":"מחכמי ירושלים. הסכים על ספר קרובו \"שדה הארץ\". בשליחות-תקיד קהלת חברון."},{"i":30166,"n":"מיוחס, משה","b":"ראש רבני תוגרמה-ת\"פ"},{"i":30167,"n":"מיוחס, משה חיים מקושטא","b":"רב בקושטא-תקס. בנו ר שמואל בכר מיוחס."},{"i":30168,"n":"מיוחס, משה מירושלים","dt":"תרן - בערך","dp":"קצמטינא-אלגיר","b":"מחכמי ירושלים, בשליחות באלגיר והתישב בקצמטינא ונפטר שם. בהקדמת ר אברהם חלימי להגדת \"ויגד לאברהם\" מתארו: \"ראשון לציון איש ירושלים\". עליו בהקדמה ל\"כגן רווה\" ירושלים תשנב."},{"i":30169,"n":"מיוחס, משה מירושלים","f":"רפאל","b":"רב בירושלים."},{"i":30170,"n":"מיוחס, משה שמואל","dp":"כלכותא","b":"מגדולי רבני ירושלים,שד\"ר להודו-תרמ\"ו"},{"i":30171,"n":"מיוחס, פנחס מיאנינה","f":"שבתי","b":"רב ודיין ביאנינה-יוון - שלט."},{"i":30172,"n":"מיוחס, רחמים שלמה מירושלים","f":"שלמה","b":"רב בירושלים-תרף. חיבר הגהות על ספרים שונים, וציונים על אבן העזר."},{"i":30173,"n":"מיוחס, רפאל אברהם בכור מירושלי","f":"יוסף יום טוב","dt":"תרלד - כט כסלו","dp":"ירושלים","b":"מחכמי ירושלים."},{"i":30174,"n":"מיוחס, רפאל אברהם מירושלים","f":"מרדכי יוסף-שער המים","k":"בעל באר המים","dt":"תקסט - ד אב","dp":"ירושלים","b":"מחכמי ירושלים, בשנת תקס חתם באגרת תלמידי \"כנסת ישראל\" מיסודו של ר חיים בן עטר. דיין אצל ר מרדכי הלוי המכונה הרב המליץ בשנת תקסו. חיבר \"באר המים\". בנו - ר יוסף בעל \"מלבושי יו\"ט\".","bk":[["באר המים",""]]},{"i":30175,"n":"מיוחס, רפאל יום טוב מירושלים","k":"בעל מי באר","b":"מחכמי ירושלים בשנת תרי, חיבר \"מי באר\" בכתב יד, כתב אגרת למוטיפיורי."},{"i":30176,"n":"מיוחס, רפאל משה מירושלים","f":"שמואל","dt":"תקפד - א אדר","dp":"אמשטרדם","b":"מחכמי ירושלים. בשליחות ישיבת \"בית אל\" באירופה. הסכים על \"דרכי דוד\" לר דוד מילדולה - המבורג תקנד, \"שער המים\"-תקכח, \"קרבן אליצור\"-תקל, \"שדה הארץ\"-תקמד. נפטר בשליחותו."},{"i":30177,"n":"מיוחס, ש' יהודה בנימין","b":"מגדולי רבני ירושלים-תקפ\"ג"},{"i":30178,"n":"מיוחס, שבתי מצפת","b":"מתלמידי הארי, ונזכר בספר החזיונות."},{"i":30179,"n":"מיוחס, שלמה יצחק מירושלים","f":"בנימין משה","k":"בעל חשק שלמה","dt":"תקפח","dp":"ירושלים","b":"נכדו של ר אברהם מיוחס בעל \"פרי האדמה\". רב בירושלים, משנהו של הרשל\"צ ר שלמה משה סוזין. בשליחות באיטליה-תקנט. חתם על אגרת ישיבת \"כנסת ישראל\"-תקסז, על כתב שליחות ר רפאל בן ישראל הלוי-תקפז, על תעודה לר\"י פח-תקפז, ושליח חברון ר יצחק בן שלמה אשכנזי. חיבר \"חשק שלמה\" בכתב יד."},{"i":30180,"n":"מיוחס, שמואל אליהו מירושלים","f":"רפאל","bt":"תפח","b":"מחכמי ירושלים, בשנת תקה חתם עם חכמי ירושלים, בשנת תקלד חתם על כתב שליחות ר אליהו צבי ועוד. בשנת תקמב חתם על מכתב המלצה לר רפאל בן רובי שיצא בשליחות להצלת הר הזיתים שרצו להרסו."},{"i":30181,"n":"מיוחס, שמואל אסתרוק מקושטא","f":"ראה: אסתרוק, שמואל ח"},{"i":30182,"n":"מיוחס, שמואל יום טוב מרדכי","dt":"תרסז - כט סיון","dp":"ירושלים","b":"דיין עם ר גבריאל שבתי ור יוסף נסים בורלא, דיין אצל ר מרדכי ישראל-תרסז, ראב\"ד בירושלים. הו\"ל מגלת היוחסין לזקנו. בנו - ר מרדכי הו\"ל את הספר-תרע."},{"i":30183,"n":"מיוחס, שמואל יצחק מירושלים","f":"אברהם משה-שדה הארץ","dt":"תקלג - א-כא שבט","dp":"ירושלים","b":"סגי נהור. מחכמי \"ישיבת יעקב פירירה\" בירושלים-תקיח, ומראשי הכוללות. אחיו של ר בנימין ונזכר בספרו \"שדה הארץ\", ובספר אביו \"שדה הארץ\". נפטר צעיר. (לפי רוזניס אינו בנו של ר אברהם)."},{"i":30184,"n":"מיוחס, שמואל מירושלים","bp":"שלוניקי?","dp":"ירושלים?","b":"מחכמי שלוניקי, עלה באמצע המאה ה-17 לירושלם והיה אבי משפחת מיוחס בארץ ישראל, והיה פרנס ומראשי הקהלה. בנו - ר אברהם משה."},{"i":30185,"n":"מיוני, יום טוב מיואני-צרפת","f":"יצחק","b":"מבעלי התוספות בצרפת, נהרג עק\"ה-ד'תתקפא. חיבר פיוטים ובהם קינה \"יה תשפוך\" על קדושי בלויא שנהרגו-ד'תתקלא."},{"i":30186,"n":"מיוני, יצחק משלוניקי","b":"דיין בשלוניקי-שנג."},{"i":30187,"n":"מיז\"א, מתתיהו","b":"רב באיטונגן(שווייץ)-תי\"ד"},{"i":30188,"n":"מיזיס - משפחה","b":"משפחה בלבוב. שינו את שמם מקאזינר למיזס על שם אמם."},{"i":30189,"n":"מיזיס אשכנזי, משה נכנע מייזלש","f":"יצחק","k":"משה נכנע מייזות","dt":"תט - כא טבת","dp":"לבוב","b":"מרביץ תורה, דיין בלבוב. חתם-שצז עם ר צבי הירש פפרקורן ור יוסף בן נתן הלר, חתם-תא עם ר שמואל זנויל אוירבך ור שמשון בן קלונימוס. בנו - ר נפתלי הרץ מלבוב."},{"i":30190,"n":"מיזיס, אליהו מלבוב","f":"משה מיזס","b":"רב בלבוב-תק\"מ"},{"i":30191,"n":"מיזיס, אליעזר מסמבור","f":"יעקב יהושע מיברוב","bt":"תרנט","dt":"תשב","b":"חסיד קומרנא. רב בסמבור-תרצב. נספה בשואה."},{"i":30192,"n":"מיזיס, זאב וולף מקאליש","bt":"תרכג","bp":"ביאלא-ליד בריסק","dt":"תשט","dp":"ישראל","b":"מחכמי רוסושצה (וישב שם אצל חותנו). רב בקאליש כ-38 שנה, עלה לארץ-תרצה. מכתביו נדפס \"לקט עני\". לתולדותיו ב\"תולדות יהודי קאליש\" וספר זכרון לקהלת טורק."},{"i":30193,"n":"מיזיס, יוסף","f":"יעקב יהושע מיברוב","b":"רב בעל תואר דוקטור בנושא - תרגום גרמני עתיק ביותר של הסידור הנדפס. כיהן כרב ראשי בצבא הפולני. נספה בשואה."},{"i":30194,"n":"מיזיס, יוסף מיברוב","b":"מחכמי יברוב-תריט - אחיו של ר מרדכי מליזנסק."},{"i":30195,"n":"מיזיס, יוסף צבי מלמברג","f":"אפרים פישל","b":"גביר מחכמי לבוב, מלומד בלשון הקודש ובקי בשפות. חתן ר שלמה זלמן זוסמן מאוסטרהא, עבר אל חותנו באוסטרהא וחזר ללבוב. חיבר מליצה ונדפסה בספר דודו ר חיים הכהן רפפורט. חתניו: ר שמחה לנדא בן אלכסנדר סנדר מאוסטרהא-תרו, ר ירחמיאל הורביץ בן ר שמלקא בן ר צבי הירש בעל \"מחנה לוי\". אחיו - ר מאיר - פרנס בלבוב."},{"i":30196,"n":"מיזיס, יצחק מקראקא","b":"מחכמי קראקא - נזכר ב\"דברי שאול\"."},{"i":30197,"n":"מיזיס, מיכאל","b":"תשובה אליו ב\"שואל ומשיב\"."},{"i":30198,"n":"מיזיס, מרדכי מליזנסק","b":"מחכמי ליזנסק-תריב - אחיו של ר יוסף מיברוב."},{"i":30199,"n":"מיזיס, מתתיהו","f":"יעקב יהושע מיברוב","b":"היסטוריון - חוקר משפחות פולניות למצוא מקורות יהודיים."},{"i":30200,"n":"מיזיס, נפתלי הרץ מלבוב","f":"משה נכנע מלבוב","dt":"תק - ד אלול","dp":"לבוב","b":"מחכמי לבוב, נפטר צעיר. (אולי אביו ר משה בן יעקב מלבוב)"},{"i":30201,"n":"מיזיס, פנחס מוינה","b":"מחכמי וינה - ממשתתפי \"קבוצי אפרים\", פרסם מאמרים ב\"המגיד\" - סטמר תרפח-תרצט, \"הנצח\" - לבוב תרפז."},{"i":30202,"n":"מיזיס, שלמה","b":"תשובה אליו ב\"שואל ומשיב\"."},{"i":30203,"n":"מיזיס-קאזינר, יהודה ליב מלבוב","f":"צבי הירש מלבוב","b":"ראב\"ד בלבוב-תקד, בזמן ר חיים רפפורט, וחתם עמו על מסמכים והסכמות בלבוב. הסכים על \"קהלת יעקב\", \"מפלגות ראובן\". אחיו - ר משה."},{"i":30204,"n":"מיזיס-קאזינר, משה מלבוב","f":"צבי הירש מלבוב","dp":"לבוב","b":"ר\"מ בלבוב תקיג, נתמנה לראש ישיבה אך נפטר לאחר שנשא דרשה אחת. אחיו - הגביר ר ירחמיאל מלבוב."},{"i":30205,"n":"מיטלמן, יהודה מלבוב וניו יורק","b":"רב בניו יורק-תריח, והיה במחלוקת עם ר אברהם יוסף אש - רב ביהמ\"ד הגדול בניו יורק, אודות שוחט, ואז פרש מהקהלה ויסד קהילת קאלוואריער בניו יורק."},{"i":30206,"n":"מיטלמן, ישראל יהודה","b":"דומ\"צ באונגוואר-תר\"ס"},{"i":30207,"n":"מיטניק, יצחק אלחנן מארה\"ב","f":"אבא ליב","k":"בעל חדושי הריא\"ם","bt":"תרלא","bp":"קאלוואריה","dt":"תשב - ב טבת","dp":"ניו יורק","b":"רב בניו יורק. נפטר ללא ילדים. גיסו ר אברהם אברהמס הו\"ל את ספרו.","bk":[["חידושי הריא\"ם",""]]},{"i":30208,"n":"מיטקובסקי, בן ציון","k":"בעל בני ציון","dt":"תרסה","b":"עק\"ה,רב בבלדובה"},{"i":30209,"n":"מיטקס, קלמן חיים מסאקאלקא","f":"פנחס יוסף","k":"בעל חמדת חיים","bp":"טשכנובצע","b":"מגיד מישרים בסאקאלקא. חיבר גם \"זכרון עולם\"."},{"i":30210,"n":"מייא, יוסף מברסלוי","f":"מיכל המדפיס מדירנפור","bt":"תקכה","dt":"תקעא - ד כסלו","b":"מדפיס בדירנפורט יחד עם אחיו ר מיכאל. רב בברסלוי והמדינה-תקנט, הגיה ש\"ס דירנפורט, חיבר עם אחיו חדושי הגהות לטור."},{"i":30211,"n":"מייא, משה ליב מברסלוי","f":"שמעון מיכאל מברסלוי","b":"רב בברסלוי-שנות ה-תק'. הסכים על \"אהל ישכר\" אלטונא תקפו."},{"i":30212,"n":"מייא, שמעון מיכאל מברסלוי","f":"מיכל המדפיס מדירנפור","k":"בעל חדושי הגהות","b":"מדפיס בברסלוי עם אחיו - ר יוסף. חיברו ביחד \"חדושי הגהות\" על ארבע טורים."},{"i":30213,"n":"מייארא, בנימין ממרוקו","b":"מחכמי מרוקו-שנות ה-ת'. בנו - ר יהודה."},{"i":30214,"n":"מייארא, גבריאל","f":"שמעון","k":"בעל נחלת גבריאל","dt":"תשמא - כ סיון","b":"חיבר \"נחלת גבריאל\""},{"i":30215,"n":"מייארא, יהודה ממרוקו","f":"בנימין","b":"מחכמי מרוקו-שנות ה-ת'."},{"i":30216,"n":"מייארא, מימון ממרוקו","dt":"תשלא - י אב","dp":"ירושלים","b":"דיין בכמה מקומות במרוקו, ולאחרונה בפאס. עלה לארץ-תשכו, והתישב בנתניה."},{"i":30217,"n":"מייארא, מסעוד ממרוקו","f":"בנימין","b":"רב במרוקו-תקלב"},{"i":30218,"n":"מייארא, שמואל מפאס-מרוקו","b":"מחכמי פאס-תצז, וחתם אז עם ר שלום אדרעי, ר יעקב ן מלכא, ר שמואל אלבאז ור אברהם עטייא. מתלמידיו ר שלמה הכהן אלכלאץ."},{"i":30219,"n":"מייארא, שמעון מפאס","f":"מסעוד","b":"מחכמי פאס, חתם-רפו בענין הנפיחה."},{"i":30220,"n":"מייבוים, זיגמונד מברלין","k":"בעל תולדות הכהונה","bt":"תרה","bp":"מישקולץ","b":"תלמיד ישיבות איזנשטט, פרשבורג, בעל תואר ד\"ר. רב באלסא-קובליין-הונגריה-תרלא, סאאז-בוהמיה-תרלד, ברלין-תרמב. חיבר גם \"תולדות הנבואה\", \"שיטה להוראת הדת\", ועוד."},{"i":30221,"n":"מייבסקי, יחיאל מיכל מסטולין","dt":"תשג","b":"רב בסטאלין"},{"i":30222,"n":"מייבסקי, ישראל מסעלץ","f":"הרב מסעלץ","b":"רב בסעלץ"},{"i":30223,"n":"מיידנק, ישראל מירוגה","f":"אהרן","bt":"תרי","b":"רב ביארוגה(=ירעה)-פודוליה-תרמב."},{"i":30224,"n":"מיידסר, נחמן שמואל יעקב","f":"שלמה חיים","k":"בעל עמודי שמואל","bt":"תרלג","bp":"וארשא","b":"מצאצאי ר יונתן איבשיץ, ר צבי הירש דיין. תלמיד האדמורים בעל \"אבני נזר\", רמ\"י מאוסטרובצה. נסמך מאת רה\"צ מאוסטרובצא, מהר\"צ מפוריסוב, רש\"ז קלפפיש. רב בברוק-תרנו, עלה לארץ-תרפו וכיהן כרב בבני ברק-תרצא."},{"i":30225,"n":"מייזינגר, יצחק מאלכסנדר","dt":"תשג","b":"רב באלכסנדר"},{"i":30226,"n":"מייזל, אברהם משה (מיזלש)","f":"אפרים צבי מסאהל","dt":"כ תשרי","b":"תלמיד ר צבי אלימלך מדינוב, ר צבי הירש מרימנוב, ר יהודה צבי מסטרטין. רב בסאהל על מקום אביו"},{"i":30227,"n":"מייזל, אליהו חיים מלודז","f":"משה","bt":"תקפא","bp":"הורודוק-פלך וילנא","dt":"תרעב - יד אייר","dp":"לודז'","b":"תלמיד ר יהונתן משה וואלינער בעל \"מרגניתא טובא\". בזיוו\"ש חתן אחיו - ר נחום מייזל מלובטש ולמד שם כמה שנים. רב בהורודק-תרב, דראצין-תריג, פרוז'ין-תרכא והגדול ממינסק על מקומו אחריו, לומזה-תרכו ופעל להפחתת מכסת חייבי שירות צבא ל-500 איש לשנה, לודז-תרלט, והיה פעיל בכל עניני הכלל, כשראה שנדחקו הפועלים היהודים מבתי החרושת, דאג לפתוח בית חרושת להעסקת הפועלים המנושלים, תיכנן רכישת קרקעות מבעלי אחוזות יהודים ליסוד מושבה חקלאית לשם הכשרת חלוצים להתישבות בארץ - אך בגלל התנגדות \"חובבי ציון\" לא התממשה. עסק בפדיון שבויים, בכל מקום בו כיהן כרב - לא נחטף אף ילד לצבא הרוסי. למרות פעילות למען ארץ ישראל התנגד לציונות. לזכרו \"אטייל זכרונות וועגן הרב\" - לודז תרפז. פרסם מאמרים ב\"קובץ דרושים\" - פיעטרקוב תרפג. הספיד את מהרי\"ל דיסקין ב\"תורה מציון\" - ירושלים תרנה-תרסה."},{"i":30228,"n":"מייזל, אליעזר יצחק","b":"פרסם מאמרים ב\"חידושי תורה\" - לודז תרצו - קובץ חבורת בני ישיבת מיר בלודז."},{"i":30229,"n":"מייזל, אפרים צבי מסאהל","dt":"כו חשון","b":"תלמיד החוזה מלובלין ור מנחם מנדל מרימנוב. רב בסאהל, ובנו ר אברהם משה על מקומו אחריו."},{"i":30230,"n":"מייזל, בנימין מבודפשט","b":"רב ביה\"כ דוהאג'י בבודפשט-תריט. חיבר פירוש למסכת אבות. תרגם לגרמנית את \"בן המלך והנזיר\", ואת \"אבן הבחן\"."},{"i":30231,"n":"מייזל, בנימין מפאנימאן","f":"יעקב","bt":"תרטו","b":"נכד הגביר ר יוסף מזל מויזון. תלמיד ר יעקב באריט מוילנא, ישיבת וולוזין. חתן ר שמואל הלפרין בן ר ישראל ממינסק. רב בקאשודארי-תרמא, פאנימאן-פלך סובאלק-תרן. נסמך מאת: הנצי\"ב, ר יצחק אלחנן מקובנא, ר רפאל שפירא מוולוזין."},{"i":30232,"n":"מייזל, בנימין משטעטין ופעסט","k":"בעל זכות אבות","bt":"תקעו","bp":"יאנוביץ","dt":"תכח","dp":"פעסט","b":"למד בהמבורג, בישיבת עטינגר בברלין, ברסלוי, ד\"ר למדעים מקיל. רב ריפורמי? בשטעטין-תרב, פעסט-אפען, חיבר גם \" \"תולדות נפתלי הירץ ויזל\", \"דער פרינץ אונד דער דערויש\" והוא תרגום \"בן המלך והנזיר\", ועוד."},{"i":30233,"n":"מייזל, הירש מאויהל","b":"רב באויהל-תר בערך."},{"i":30234,"n":"מייזל, יצחק","b":"רב-שנת תר\"מ"},{"i":30235,"n":"מייזל, מאיר","b":"פרסם מאמרים ב\"תורה מציון\" - ירושלים תרנה-תרסה."},{"i":30236,"n":"מייזל, משה מדירנפורט","k":"בעל תשועת חן","b":"רב בדירנפורט-תק\"ס"},{"i":30237,"n":"מייזל, משה מויליצקה","b":"רב בויליצקה-תרס."},{"i":30238,"n":"מייזל, נחום מלובטש","f":"משה","b":"תלמיד ר יהונתן משה וואלינער בעל \"מרגניתא טובא\". חתן ר שמואל בקשטר מלובטש. רב בלובטש. אחיו של ר אליהו חיים מלודז, וחותנו-בזיוו\"ש. בנו - ר אליעזר בקשטנסקי מפינסק."},{"i":30239,"n":"מייזל, נתן נטע מלודז","f":"אליהו חיים מייזל","dt":"תרעח - ד טבת","b":"רב בלודז"},{"i":30240,"n":"מייזל, שמואל","f":"משה","b":"אחיהם של ר אליהו חיים מלודז ור נחום מלובטש. חתן ר בן ציון שפירא-בקשטר (אחיו של ר שמואל בקשטר שהיה חותנו של אחיו ר נחום) חתנו - ר יעקב משה דירקטור משטאויץ."},{"i":30241,"n":"מייזל, שמחה בונם ממוהילוב","f":"יהודה ליב","b":"רב במאהליב-ת\"נ"},{"i":30242,"n":"מייזלש, אביגדור מבילגורי","f":"משה צבי","k":"בעל בית אביגדור","b":"רב בבילגורי-תקם על מקום אביו, חתנו ר יצחק נתן נטע ברלינר על מקומו אחריו."},{"i":30243,"n":"מייזלש, אברהם","k":"חתן הרמ\"א","b":"שנת-ש\"מ"},{"i":30244,"n":"מייזלש, אברהם","f":"אליהו אורנגיל מלבוב"},{"i":30245,"n":"מייזלש, אברהם מאוסטרהא","f":"שמואל","dt":"תקפב - יד תמוז","dp":"אוסטרהא","b":"מצאצאי ר רפאל בעל \"תוספות שבת\", הב\"ח ובעל \"חלקת מחוקק\". חתן הגביר ר אבא אבלי בן פסח הכהן מאוסטרהא. פרנס באוסטרהא. מבניו: ר שמואל, ר יואל נתן. חתניו: ר צבי הירש הכהן זוסמן מאוסטרהא, ר זוסיא לוין."},{"i":30246,"n":"מייזלש, אברהם מלבוב","f":"גרשון","dt":"תיח - ב אדר","dp":"לבוב","b":"דיין גדול בלבוב, חתם-תיג עם ר מרדכי מודל, ר אברהם עקרין (אברהם עבריל בן שמעיה), ועוד."},{"i":30247,"n":"מייזלש, אברהם מפרג","f":"יוסף מייזלש","b":"רב בפרג-שנת ת'"},{"i":30248,"n":"מייזלש, אברהם מפרג","f":"יצחק איזיק מפרג","b":"רב בפרג. חתנו - ר אליהו ליפשיץ מבריסק."},{"i":30249,"n":"מייזלש, אברהם מקראקא","f":"שמחה בונם מייזלש","b":"רב בקראקא-תמד. בנו - ר יהודה בעל \"טעמי מסורת\"."},{"i":30250,"n":"מייזלש, אברהם מקראקא","f":"יוסף","dt":"שס - ז חשון","b":"חתן ר יהודה ליב מייזלש מקראקא בן אברהם-מצאצאי מר עוקבן ריש גלותא. רב בפולין. בניו: ר שמחה בונם-חתן הרמ\"א, ר ישראל-חתן ר נפתלי צבי שור מבריסק."},{"i":30251,"n":"מייזלש, אברהם נתן נטע מויזניץ","f":"משה","k":"בעל נטע שעשועים","dp":"ארץ ישראל","b":"היה אב\"ד וישניצא שבליטא, ואחר כך רב באמשטרדם, מצאצאי הרמ\"א, וסבו של ר עזריאל בעל \"כרם שלמה\". חיבר ספר \"נטע שעשועים\" אמשטרדם תצה, \"הליכות עולם\" זולצבך תקטז, הוציא לאור את הספר \"שאגת אריה\" לזקנו ר אריה ליב בן שמואל בן הב\"ח, עם שנויים בשם \"שאגת אריה וקול שחל\" שלוניקי תקו (בהיותו בשלוניקי התאכסן אצל הגביר ר ברוכיה רוסו). ועוד"},{"i":30252,"n":"מייזלש, אהרן אריה יהודה ליב","dt":"תרח - כט אייר","b":"תלמיד החוזה מלובלין. גיסו של ר מאיר מרגליות מאוסטרהא. רב בקוליקוב, זמושץ, פיעטריקוב. היה מחלוקת כנגדו בגלל חסידותו ונאלץ להתפטר מרבנותו. בניו: ר דוד דוב בעל חדושי הרד\"ד."},{"i":30253,"n":"מייזלש, אליהו מלבוב","f":"אברהם","b":"ספרא ודיינא בלבוב, חתם-תפה עם ר נתן נטע בן יקותיאל זלמן, ר פנחס זליג וילנר, ועוד."},{"i":30254,"n":"מייזלש, אליעזר ליפמן מוילנא","b":"גביר מראשי קהלת וילנא, חתם-תע בפנקס הקהלה."},{"i":30255,"n":"מייזלש, אלכסנדר סנדר מזבלטוב","f":"רפאל מפאריצק-תוספת ש","k":"בעל תוספות שבת","bt":"תק","dt":"תקעט - א אדר","dp":"רעכניץ","b":"רב בזבלטוב, עבר לאמשטרדם וברלין, סרדהלי(=סערעד)-הונגריה, רכניץ(=רעכניץ)-תקס על מקום ר אהרן ריזמן ור גבריאל אנגלסמן על מקומו אחריו, לאחר שהתעוור על מקומו הדיין הרב קניגסברג. עמד בקשר עם החת\"ס. חיבר \"תוספות שבת\"."},{"i":30256,"n":"מייזלש, אלכסנדר סנדר מלובלין","f":"חיים","dt":"תעז - כז כסלו","dp":"לובלין","b":"מחכמי לובלין. (במצבתו נכתב \"התייר הגדול\" - ולא נודע מהו)."},{"i":30257,"n":"מייזלש, אלעזר מאויהל","f":"דוד דב בריש מאויהל","b":"רב בשיקגו. חתן ר יוסף פאנעט מדעש."},{"i":30258,"n":"מייזלש, אלעזר מלימנוב","f":"יקותיאל עוזר מסטרי","dt":"תרפט","b":"חתן ר יוסף שטרן מלימנוב והיה מחכמי לימנוב."},{"i":30259,"n":"מייזלש, אריה יהודה יעקב מפיעטר","f":"נפתלי הירץ מייזלש","b":"רב בזאמוטש, פיעטרקוב-תקפ. בנו - ר דוד דב מלאסק."},{"i":30260,"n":"מייזלש, אריה יהודה ליב מפשמישל","f":"יוסף חנניא ליפא","bt":"תרי","dt":"תרף","b":"חתן ר שמואל שמלקא טויבש מיאס. רב בפשמישל-תרל על מקום אביו. הוציא לאור כתבי עת \"די נויע צייט\" ו\"המבורגר איזראלי טישעס\". פרסם מאמרים ב\"בית ועד לחכמים\" - יאסי תרסט, \"קובץ דרושים\" - פיעטרקוב תרפג."},{"i":30261,"n":"מייזלש, אריה יהודה ליב מצשינוב","f":"חנניא ליפא מצשינוב","b":"רב בצשינוב על מקום אביו. חתן ר דוד צבי אוירבך מקרמניץ."},{"i":30262,"n":"מייזלש, אריה יהודה מירושלים","f":"אלכסנדר מאפטא","b":"נכד לר ליב חסיד אב\"ד לבוב, עמד בראש עדת החסידים בירושלים יחד עם ר אברהם גרשון מקיטוב. חתם בתקיז על מכתב קהלה לבקשת עזרה מקהילת מיץ, ועל מכתבים נוספים למיץ"},{"i":30263,"n":"מייזלש, אריה ליב מוילנא","f":"משה מוילנא וחברון","dt":"תקצו - כו חשון","dp":"וילנא","b":"חסיד חב\"ד וממנהיגי החסידים בוילנא."},{"i":30264,"n":"מייזלש, גרשון"},{"i":30265,"n":"מייזלש, גרשון","f":"אברהם מייזלס"},{"i":30266,"n":"מייזלש, דב בר מקראקא וארשא","f":"יצחק מקמניץ-חוסן ישו","k":"מהרד\"ם","bt":"תקנח","bp":"שטוקצין","dt":"תרל - טו אדר","b":"מצאצאי בעל הש\"ך. חתן ר שלמה זלמן בורנשטין מקשאנוב. רב בקראקא-תקצב - תוך מחלוקת אודות ר שאול לנדא שנבחר במקביל על ידי מתנגדיו. תמך במורדים הפולנים - על מנת למנוע מהם לפגוע ביהודים. היה ציר בפרלמנט האוסטרי כפטריוט פולני. רב בוארשא-תרטז, ברח לקטוביץ וחזר לוארשא. ספרי הספדים עליו - \"עין המים\", לקורותיו \"איש חיל\". מאמר ממנו ב\"הבאר\" - זאמושץ-וארשא תרפד (אחר פטירתו), \"כרם בית שמואל\" - פיעטרקוב תרצג. בנו - ר ישראל.","bk":[["חי' מהרד\"ם [על סהמ\"צ לרמב\"ם]",""],["עבודת היום [הל' השכמת הבוקר עד קר\"ש]",""]]},{"i":30267,"n":"מייזלש, דוד דב (גוטר) מאושפיצי","f":"שלמה זלמן מאושפיצין","k":"עורך \"כתר תורה\"","bt":"תרפא","b":"התכתב עם גדולי דורו. ניצל מהשואה, עבר לניו יורק. חיבר \"מתוק מדבש\" ניו יורק תשמד. ערך ירחון תורני \"כתר תורה\" לובלין תרצט. פרסם מאמרים ב\"כתר תורה\" - סוסנוביץ-פיעטרקוב תרץ-תרצט, ו\"כתר תורה\" - אושפיצין תרצט."},{"i":30268,"n":"מייזלש, דוד דב בריש מאויהל","f":"מרדכי זאב מלאסק","k":"בעל בנין דוד","bt":"תרלה","dt":"תשד","b":"חתן ר משה יוסף טיטלבוים באויהל. רב באויהל-תרנח. נספה בשואה. חיבר \"בנין דוד\" אויהל תרצב. הסכים על הקובץ \"הפלפול\" - שאפראן תרצח."},{"i":30269,"n":"מייזלש, דוד דב בריש מלאסק","f":"אריה יהודה מקוליקוב","k":"בעל אהבת דוד","bt":"תקעד","bp":"קוליקוב","dt":"תרלו - ט כסלו","dp":"לאסק","b":"חתן ר אלעזר הכהן מפולטוסק. רב בדאברי-תקצב, נשלסק, לאסק(=לוסק)-תריא על מקום ר משה ליב זילברברג. חיבר גם \"שו\"ת הרד\"ד\". מתורתו ב\"קובץ דרושים\" - פיעטרקוב תרפג. בניו: ר צא\"י יעקב בעל \"חדות יעקב\" על מקומו אחריו בלאסק, ר פנחס אליה מראקוב, ולוטימורסק, ר זאב וולף מטרנוב. חתניו: הגביר ר יוסף גרשון גולדשטין מאוזרקוב, הגביר ר משה פצנובסקי מפיעטרקוב."},{"i":30270,"n":"מייזלש, זאב וולף מוילנא המבורג","f":"יצחק רבי בונימש","k":"וולף מייזלס מוילנא","b":"נכד הרמ\"א. מגדולי וילנא-שנת ת', ברח בפרעות תח ולאחר זמן התישב בהמבורג, דיין בהלברשטט. חתניו - ר שבתי בעל הש\"ך, ר יהודה וייל-קצנלנבוגן מבריסק. אחיו - ר משה בעל מהדורא בתרא."},{"i":30271,"n":"מייזלש, חיים אהרן מטויסט","b":"רב בטויסט-תרסו."},{"i":30272,"n":"מייזלש, חיים מסאראוואש ונ\"י","f":"דוד דב בריש מאויהל","k":"בעל בנין חיים","b":"רב בסאראוואש. ניצל מהשואה ושימש כרב בברגן בלזן על מקום אחיו. היגר לארה\"ב. חתן ר פנחס אלימלך וייסמן. חתנו ר ישכר בעריש מקרסטור(=קרסטיר) ונ\"י."},{"i":30273,"n":"מייזלש, חיים שלמה מדולינא","b":"רב בדולינא."},{"i":30274,"n":"מייזלש, חנניא ליפא מוינה","f":"יונה","k":"בעל מנחת לחם עני","b":"חתן ר אלעזר דילר מירוסלב. רב בוינה. חיבר \"מנחת לחם עני\" - בכת\"י. הדפיס קונטרס תשובה בענין שוחט - וינה תרצח."},{"i":30275,"n":"מייזלש, חנניא ליפמן מצשינוב","f":"שמשון מזולקוא","dt":"תקמא - יט ניסן","dp":"צעשינוב","b":"רב בצעשינוב על מקום אביו."},{"i":30276,"n":"מייזלש, חנניא ליפמן מקראקא","f":"אליהו","dt":"תקעב","b":"רב בפיעטרקוב, אפטא, דיין בקראקא."},{"i":30277,"n":"מייזלש, חנניה ליפא ממנוסט","dt":"תשג","b":"רב במניסטריטש"},{"i":30278,"n":"מייזלש, חנניה ליפמן מקראקא","b":"דיין בקרקא-ת\"ק"},{"i":30279,"n":"מייזלש, יהודה","f":"אברהם או שמחה בונם","k":"בעל טעמי מסורת","b":"חיבר \"טעמי מסורת\" אמשטדם תנח. ובהקדמה מסופר שהניח חבורים נוספים. (לפי גירונדי שם אביו שמחה בונם ובאוצר הרבנים זהו שמו של זקנו)."},{"i":30280,"n":"מייזלש, יהודה ליב מלובמלא","f":"יצחק","k":"בעל באר מים חיים","b":"רב בלובמלא. חיבר \"באר מים חיים\" למברג תקמד."},{"i":30281,"n":"מייזלש, יהושע מטופורוב","b":"נכד התוספות שבת והמגיד מזלוטשוב. גביר בטופורוב."},{"i":30282,"n":"מייזלש, יהושע מעגערסג","f":"שמואל שמלקא מעגרסג","dt":"תקצח - סיון","dp":"פרשבורג","b":"תלמיד החת\"ס, ונפטר בזמן שהיה בישיבתו בפרשבורג."},{"i":30283,"n":"מייזלש, יוסף חנניא ליפא מפשמיש","f":"נפתלי הירץ","k":"בעל פני יוסף","bt":"תקפג","bp":"פרמישלא","dt":"תרכה - יח אייר","b":"רב בפשמישל-תריא, זולקוא-תרטז. חיבר \"פני יוסף- שער הרוחה\" למברג תרז, ועוד."},{"i":30284,"n":"מייזלש, יוסף חנניא ממנוסטרישץ","f":"אריה יהודה מפרמישלא","k":"בעל נחלת יוסף","bt":"תרלה","dt":"תש","b":"חתן ר אברהם חנוך הכהן זילביגר מצשינוב. רב בצשינוב-תרנה, מנוסטרישץ-תרסה. חיבר \"נחלת יוסף\" מונקטש תרעג. פרסם מאמרים ב\"הפרדס\" - צאנז תרצא, \"רבותינו שבגולה\" - פרשבורג תרעה."},{"i":30285,"n":"מייזלש, יוסף מקראקא","k":"חתן הרמ\"א","b":"רב בקרקא-שס\"ב"},{"i":30286,"n":"מייזלש, יוסף משה ממראש אויוואר","f":"דוד דב בריש מאויהל","k":"בעל מקוה מים","dt":"תשלו - י סיון","dp":"ניו יורק","b":"תלמיד קרובו בעל \"עצי חיים\" בסיגט. חתן האדמור ר יחזקאל פאנט מדעש. רב בכפר טקנדורף (שרובו חסידי חותנו האדמור מדעש), רב וראש ישיבה במארוש-אויוואר-תרץ על מקום גיסו ר יעקב אלימלך פאנט שעבר לדעש. ניצל מהשואה, ואחריה חבר בלשכה האורטודוכסית בהונגריה. היגר לארה\"ב, וכיהן כרב ק\"ק \"אויהל\" בניו יורק."},{"i":30287,"n":"מייזלש, יחזקאל שרגא מראדוואן","k":"בעל זכרון יחזקאל","dt":"תרצב","b":"רב בראדוואן. חיבר \"זכרון יחזקאל\" אויהל תרצה. ?? לא באוצר ??"},{"i":30288,"n":"מייזלש, יחיאל מיכל מראווא","b":"רב בראווא-תרעג."},{"i":30289,"n":"מייזלש, יעקב","f":"צבי הירש או שמשון","b":"בניו - ר יעקב מלבוב, ר שמשון מצעשינוב וזולקוא. אחיו - ר צבי הירש מבעלז."},{"i":30290,"n":"מייזלש, יעקב מטיסמניץ","b":"רב בטיסמניץ - תשובה אליו ב\"ארץ צבי\"."},{"i":30291,"n":"מייזלש, יעקב מפיעטרקוב","f":"מנחם","b":"רב בפיעטרקוב-תקפ. מתורתו ב\"קובץ דרושים\" - פיעטרקוב תרפג."},{"i":30292,"n":"מייזלש, יצחק איזיק מירושלים","f":"צבי הירש","dt":"תפז - כג ניסן","dp":"אייזנשטאט","b":"מחכמי ירושלים, חתם בשנת תסז, בשנת תע בשליחות עם ר משה מניקלשבורג, בשנת תעה היה בפרנקפורט, נתמנה לדיין בקהילת אייזנשטאט. גיסו - ר מרדכי מוכיח."},{"i":30293,"n":"מייזלש, יצחק איזיק מפרג","b":"רב בפרג. בנו - ר אברהם מפרג."},{"i":30294,"n":"מייזלש, יצחק איזיק מפשמישל","b":"רב בפשמישל-תריז."},{"i":30295,"n":"מייזלש, יצחק ליב מהרימלוב","b":"רב בהרימלוב - תשובה אליו בטוט\"ד."},{"i":30296,"n":"מייזלש, יצחק מבריסק","b":"גביר בבריסק-תרלג. נזכר ב\"שער בנימין\" לר בנימין בישקא."},{"i":30297,"n":"מייזלש, יצחק מפינסק","f":"שמחה בונם מייזלש","b":"רב בפינסק-ש\"ס. בניו: ר משה, ר וולף-חותנו של בעל הש\"ך."},{"i":30298,"n":"מייזלש, יצחק מצוזמיר","f":"צבי הירש מסמיאטיטש","k":"בעל זר זהב","dt":"תרכב - כז תשרי","b":"לאחר שנתייתם גדל אצל אחיו ר עוזיאל מריטשעוואהל ואוסטרובצה. חתן ר אברהם מנחם מנדל מצויזמיר-נכד בעל \"ברכת יעקב\". תלמיד ר אלימלך מליזנסק. רב בצויזמיר, ניישטאט-תקמו על מקום אחיו. הו\"ל ספרי אחיו. חיבר \"זר זהב\" על הספר \"כרם שלמה\". בניו ר עוזיאל שמריה מסקרנוביץ, ר צבי מנחם מפילוב בעל \"זכרון צבי מנחם\", ר נתן מאיר."},{"i":30299,"n":"מייזלש, יצחק מקמניץ","f":"חיים","k":"בעל חוסן ישועות","b":"נכדם של גדולי הרבנים. תלמיד אביו חורגו ר ישראל הלוי מפוריצק. חתן ר יצחק הכהן מסטבניץ. רב בשטיקטשין-תקס, קמניץ-פודולסק - לפני תקסח. חיבר \"חוסן ישועות\" וארשא תקסח. אחיו - ר שמואל חתן אביהם חורגם."},{"i":30300,"n":"מייזלש, יצחק מקרמניץ","f":"יעקב","k":"בעל לקוטי שושנים","b":"גדל אצל זקנו ר פסח מוולאדובה. חתן ר יעקב ישראל הלוי מקרמניץ. רב בקרמניץ-תקס על מקום חותנו. חיבר \"לקוטי שושנים\" פאריצק תקעח."},{"i":30301,"n":"מייזלש, יצחק משה מצוזמיר","f":"שמואל שמלקא מייזלש","dt":"תקצא - כה שבט","b":"רב בצויזמיר,בלזיץ,בוחאב,עיר חדש"},{"i":30302,"n":"מייזלש, יצחק שמואל מלונדון","bp":"קראקא","b":"תלמיד ביהמ\"ד בברסלוי, רב ומטיף בלונדון-תרע, עוזר בבית דינו של ר נפתלי צבי אדלר. פרסם מאמרים בכתבי עת."},{"i":30303,"n":"מייזלש, יקותיאל יהודה מסיגייט","f":"צבי הריש מניימרקט","bt":"תרץ","b":"רב בסיגייט. ניצל מהשואה."},{"i":30304,"n":"מייזלש, ישראל","f":"מנחם מנדל מזלוטשוב","b":"חתן ר בר יצחק ורשבסקי מקיוב. עלה לארץ-תרץ."},{"i":30305,"n":"מייזלש, ישראל ליב מפשמישל","b":"ממשתתפי \"אהל מועד\"."},{"i":30306,"n":"מייזלש, ישראל מדולינא","b":"רב בדולינא - תרלט."},{"i":30307,"n":"מייזלש, ישראל מקולבסוב","f":"עוזיאל מעיר חדש","b":"רב בקולבסוב. חתן ר יצחק בן ישעיה מקולבסוב."},{"i":30308,"n":"מייזלש, ישראל משדליץ","f":"דב בר מקראקא","dt":"תרלו - יט חשון","b":"חתן ר אלכסנדר זיסל ממינסק (אצל ברוורמן-אנשי שם מופיע - חתן ר יקותיאל זיסל בן חיים רפפורט ממינסק. רב בשדלץ, קראקא-תרלד. הוציא לאור ספר המצוות עם ביאורי מהרד\"ם (לאביו)."},{"i":30309,"n":"מייזלש, מאיר מזאמושט","f":"משה","k":"בעל הליכות עולם","b":"מגדולי חכמי זאמוטש-ת\"ק"},{"i":30310,"n":"מייזלש, מאיר צבי מרכניץ","f":"משה מסערעד","b":"אמו - אחייניתו של ר שמלקא הורביץ מניקלשבורג וגדלה בביתו. ברח בגלל הלשנה מפולין להונגריה-תקסא. רב בבאנוביץ-תרו, סערדאוהל, רעכניץ, אילאווא."},{"i":30311,"n":"מייזלש, מנחם מנדל דב מזלוטשוב","f":"משה נחמן מסטרי","bt":"תרה","bp":"סטרי","dt":"תרנט","b":"חתן ר משה שבדרון מזלוטשוב. מו\"ץ בזלוטשוב, רב בשדה לבן, ראב\"ד בזלוטשוב."},{"i":30312,"n":"מייזלש, מנחם מנדל נפתלי הרץ","f":"חנניא ליפא מצשינוב","dt":"תקסה","dp":"ראווא","b":"רב בראווא, ולפניה בכמה קהלות. מתורתו ב\"קובץ דרושים\" - פיעטרקוב תרפג."},{"i":30313,"n":"מייזלש, מנחם מסיגט","f":"רפאל מייזלש","b":"רב בסיגעטוואר-תר\"מ"},{"i":30314,"n":"מייזלש, מרדכי זאב מלאסק","f":"דוד דב בריש מלאסק","b":"מחכמי לאסק. טורנא. מהדיר ספר \"אהבת דוד\" לאביו (מהדורה ב)."},{"i":30315,"n":"מייזלש, מרדכי מבוברקא","b":"רב בבוברקא - תשובה אליו בשואל ומשיב."},{"i":30316,"n":"מייזלש, מרדכי מזולקוא","f":"נתן נטע-שאגת אריה","b":"מחכמי זולקוא, הסכים-תקלד על ספר המדות לר יצחק סטנוב."},{"i":30317,"n":"מייזלש, משה","b":"חתן ר שמואל צבי הרץ. בניו: ר מאיר, ר אברהם נתן, ר יצחק"},{"i":30318,"n":"מייזלש, משה","f":"בונם מייזלס","b":"בנו - ר יהודה ליב חסיד מפרמישלא ולבוב."},{"i":30319,"n":"מייזלש, משה חיים סגל מקראקא","dt":"תריד - יד כסלו","b":"דיין בקראקא"},{"i":30320,"n":"מייזלש, משה מבלשביץ","b":"רב בבלשביץ-תריח."},{"i":30321,"n":"מייזלש, משה מוילנא וחברון","f":"מרדכי","k":"בעל שירת משה","dt":"תרא","dp":"חברון","b":"פרנס בוילנא, מקורב לגר\"א ולאחר מכן מקורבו של ר שניאור זלמן מלאדי. היה נאמן העיר וילנא אולם סולק ממשרתו בגלל שדבק בחסידות. בקי בספרות הגרמנית והחשיב את משה מנדלסון. בזמן מלחמת נפוליאון עמד בקשרים עם הצרפתים ויתכן שאף עם נפוליאון עצמו - ר שניאור זלמן ביקש ממנו לפעול לטובת הרוסים, לאחר שנחשד בידי הצרפתים ברח ועלה לארץ-תקעו והתישב בצפת ואחר כך לחברון. פגש את מונטיפיורי בביקורו בחברון. בשליחות בחו\"ל וחזר-תקצח. חיבר \"שירת משה\" שקלוב תקמח - בספר נוספו אגרות ששלחו אליו בעל התניא ובנו ר דובער. כשביקר ד\"ר אליעזר הלוי בחברון-תקצח התפלא למצוא אדם תורני הבקי גם במשוררי גרמניה שילר ולסינג. בנו ר אריה ליב ממנהיגי החסידים בוילנא - נפטר תקצה. (בעיר וילנא מביא שנאלץ לעזוב את וילנא בגלל מחלוקת כנגדו על השכלתו - חברו ר נפתלי הרץ שולמן נאלץ לעזוב גם הוא)."},{"i":30322,"n":"מייזלש, משה ממושציסק","f":"יוסף חנניא ליפא","k":"בעל כליל תפארת","bt":"תרה","bp":"פשמישל","dt":"תרפה","b":"מחכמי קוזמיר. רב בקרעשוב-תרלו, מושציסק-תרנט, פשמישל(=פרעמישלא). חיבר \"כליל תפארת\" - בתוך \"תפארת יוסף\" לאביו. הסכים על \"אהל יצחק\" - סטמר תרסג. פרסם מאמרים ב\"אהל מועד\" - פודגורזע תרנח, \"ועד חכמים\", \"כנסת חכמים\"- בורגו-פרונד - ס. וואראהל תרסה, \"שערי תורה\" - וארשא תרסג."},{"i":30323,"n":"מייזלש, משה מסערעד","f":"רפאל מפאריצק-תוספת ש","dt":"תרה - כג אב","b":"רב בסערעד-תקעה על מקום ר דוד זינרייך ור חיים בנימין פאלק על מקומו אחריו. חתנו - ר יעקב בן ברוך-דיין בסערעד, בניו: ר שמואל שמעלקא מעגערזע, ר רפאל מסיגטוואר, ר מאיר מאילאווא."},{"i":30324,"n":"מייזלש, משה מצפת","b":"חתן ר אליעזר גרייוור מסלונים. בנו ר אליהו חיים"},{"i":30325,"n":"מייזלש, משה צבי הירש מזולקווא","f":"שמשון מזולקוא","k":"בעל חמדה גנוזה","r":"אב\"ד זאלקווא והגלילות","bt":"תפ","dt":"תקסא - יח כסלו","dp":"זולקוא","b":"יש אומרים שהיה חתן ר ישכר בער פאלק מפודהייץ-בנו של בעל פני יהושע. רב בבילגוריי, לנצהוט-תקיח, זולקוא-תקכו על מקום אביו (שעבר לצעשינוב). נתבקש לכהן בפירודא על מקום ר יוסף שטינהרט, במיץ על מקום השאגת אריה, ובקופנהגן - אבל סירב לכלם ונשאר בזולקוא. חיבר \"חמדה גנוזה\" למברג תרלה. הסכים על שו\"ת גאונים בתראי - טורקא תקכד, \"שער המלך\", |אבן שוהם\", \"עבודת המלך\", ועוד. בנו - ר אביגדור רב בבילגוריי(=בילגוריא) על מקום אביו, חתנו - ר אביגדור הורביץ.","bk":[["חמדה גנוזה - שו\"ת",""]]},{"i":30326,"n":"מייזלש, נפתלי הרץ","f":"חנניה ליפא מייזלס","b":"רב בראווא דאסטריך-תק\"צ"},{"i":30327,"n":"מייזלש, נפתלי הרץ מסטניסלב","b":"מתורתו ב\"קובץ דרושים\" - פיעטרקוב תרפג."},{"i":30328,"n":"מייזלש, נתן מאיר","f":"יצחק מצוזמיר","b":"מהדיר ספרי דודו (ר עוזיאל?)"},{"i":30329,"n":"מייזלש, נתן נטע מוישניץ-ליטא","b":"רב בוישניץ דליטא-תצ\"ו"},{"i":30330,"n":"מייזלש, עוזיאל שמריה מסקרנביץ","f":"יצחק מצוזמיר","b":"רב בסקרנביץ."},{"i":30331,"n":"מייזלש, עקיבא מפשמישל","f":"יוסף חנניא ליפא","k":"בעל חדושי נחלת בן יו","bt":"תריד","bp":"פשמישל","dt":"תרעה","b":"מחכמי פשמישל, שינאווא ולמברג. חתן ר יצחק הירש בוטרווייך משינאווא. חיבר \"חדושי נחלת בן יוסף\" למברג תרסב. ?? לא באוצר ??"},{"i":30332,"n":"מייזלש, פישל מטשבין","b":"מחכמי טשבין - תשובה אליו ב\"חזון נחום\"."},{"i":30333,"n":"מייזלש, פנחס אליהו מרקוב","f":"דוד דב מלאסק","k":"בעל אפד בד - כת\"י","bt":"תרטז","dt":"תרנד - כד אייר","dp":"ליטומירסק","b":"רב ברקוב(=ראקאוו), וירושוב, ליטומירסק(-לוטימורסק). חתן ר ישראל גוטרמן מרדזימין. חתנו ר מאיר הכהן ורשביאק על מקומו אחריו בליטומירסק. פרסם מאמרים ב\"קובץ דרושים\" - פיעטרקוב תרפג."},{"i":30334,"n":"מייזלש, צבי אריה יעקב מלאסק","f":"דוד דב מלאסק","k":"בעל חדות יעקב","dt":"תרפג","b":"רב בלאסק על מקום אביו. חיבר \"חדות יעקב\" פיעטרקוב תרסג. פרסם מאמרים ב\"קול תורה\" - פאביאניץ תרפו, תשובות ממנו ב\"קבוצי בחורים\" - מארגרטן תרצג. חתנו - ר יהודה ליב איזנברג על מקומו אחריו בלאסק."},{"i":30335,"n":"מייזלש, צבי הירש","f":"יצחק","b":"רב-שנת תק\"י"},{"i":30336,"n":"מייזלש, צבי הירש מאויהל","b":"רב באוהעל-תק\"מ"},{"i":30337,"n":"מייזלש, צבי הירש מוייצען ושיקג","f":"דוד דב בריש מאויהל","k":"בעל בנין צבי","r":"אב\"ד ורב בניימראק, וייצען, ברעגן בעלזן,","bt":"תרסב","bp":"אויהל","dt":"תשלד - כה טבת","b":"חתן ר חיים יעקב טייטלבוים מלימנוב (חתן האדמור מבובוב). רב בניישטט, הקים ישיבת בובוב בניימרקט-תרפה. רב בוייצן-תרצב. ניצל מהשואה ואחריה היה רב בברגן בלזן - שם עסק בשיקום היהודים וכן היה רב האזור הבריטי בגרמניה. עבר לאמריקה וכיהן כרב בקהלת \"שארית ישראל\" בשיקגו-תשז, מקורב לחסידות סטמר. חיבר \"בנין צבי\" וייצן תרצט. חיבר גם \"מקדשי השם\" על קידוש השם בשואה.","bk":[["תפארת צבי",""],["בנין ציון – שו\"ת",""],["מקדשי ה' – שו\"ת",""],["אגרא דצבי - דרשות",""],["בנין צבי - שו\"ת, וחידושים",""],["דבר צבי - שו\"ת מקדשי השם, הגדה של פסח, ודרשות",""],["זר זהב - על התורה",""],["תקנות עגונות",""],["שו\"ת מקדשי השם [אודות השואה]",""]]},{"i":30338,"n":"מייזלש, צבי הירש מלבוב","f":"יעקב","b":"מחכמי לבוב. אחיו של ר שמשון מצעשינוב וזולקוא. תשובה ממנו בשו\"ת גאוני בתראי. הסכים על \"מענה אליהו\", \"שבט מישראל\"."},{"i":30339,"n":"מייזלש, צבי הירש מסמיאטיטש","f":"עוזיאל מעיר חדש","b":"מחכמי סמיאטיטש - גביר שסייע בהוצאת כתבי אביו."},{"i":30340,"n":"מייזלש, צבי הירש מקרזמיר","b":"רב בקרזמיר-תכ\"א"},{"i":30341,"n":"מייזלש, צבי מטרמבובלה","f":"נחמן","b":"דיין בטרמבובלה."},{"i":30342,"n":"מייזלש, צבי מנחם מפילוב","f":"יצחק מצוזמיר","k":"בעל זכרון צבי מנחם","bt":"תקן","dt":"תרך","b":"חסיד צאנז. רב בפולאב, פארצאווי, עיר חדש-ניישטט (על מקום אביו). חתן הגביר ר לוי ישכר. חיבר \"זכרון צבי מנחם\" פרמישלא תרלג."},{"i":30343,"n":"מייזלש, רפאל מסיגעטואר","f":"משה מסערעד","b":"רב בסיגעטוואר-ת\"ר"},{"i":30344,"n":"מייזלש, רפאל מפאריצק","k":"בעל תוספת שבת","dt":"תקסג - יט סיון","b":"מצאצאי בעל \"חלקת מחוקק\". מגדולי דורו, ראב\"ד בברחוב(=בארחוב), רב בפאריצק-תקכ. מבניו: ר משה מסערעד, ר סנדר מרעכניץ. תלמידו - בעל \"מחנה ראובן\"."},{"i":30345,"n":"מייזלש, שלמה זלמן מאושפיצין","f":"מרדכי זאב מלאסק","b":"מחכמי אושפיצין - בנו ר דוד דב בעל \"מתוק מדבש\"."},{"i":30346,"n":"מייזלש, שלמה זלמן ממוהילוב","f":"שמחה בונם מייזלש","b":"רב במאהליב-ת\"מ"},{"i":30347,"n":"מייזלש, שלמה מערדא-סאנזשארץ","f":"יצחק איזיק מבאנפי הו","k":"בעל לקוטי שלמה-תשא","dt":"תש..","b":"מחכמי כפר ראווא-ליד ערדא-סאנזשארץ, שו\"ב בערדא-סאנזשארץ בזמן האב\"ד ר גרשון מנדל קאהן. נספה בשואה."},{"i":30348,"n":"מייזלש, שמואל דב מירוסלב","f":"אשר מפשמישל","bt":"תרסב","bp":"פשמישל","dt":"תש","b":"חסיד הוסיאטין. ממנהיגי צא\"י. חתן ר פנחס המרלינג מירוסלב. סייע לחותנו ברבנות ירוסלב. נספה בשואה. פרסם מאמרים ב\"יבנה\" - לבוב תרפט, ועוד, וערך את \"דער יודישער וועג\"."},{"i":30349,"n":"מייזלש, שמואל זנויל מוילנא","b":"רב בוילנא, חתם-תסה עם ר מרדכי בן ישראל, ר יהודה ליב בן ישראל חריף, ר אהרן בן אברהם."},{"i":30350,"n":"מייזלש, שמואל מוערבא","b":"אב\"ד וערבא."},{"i":30351,"n":"מייזלש, שמואל מפאריצק","f":"חיים?","b":"חתן אביו חורגו ר ישראל הלוי מפאריצק. רב בפאריצק (על מקום אביו חותנו?), לברטוב. אחיו - ר יצחק בעל \"חוסן ישועות\", ר יעקבקא."},{"i":30352,"n":"מייזלש, שמואל שמלקא","f":"משה מסערעד","k":"בעל גויעת שמואל","dt":"תרטו","b":"רב באגעדא, עגערסעג(=עגערזע)."},{"i":30353,"n":"מייזלש, שמחה בונם","f":"אברהם מייזלס","k":"חתן הרמ\"א","dt":"שפד - ט אדר","b":"גביר,מגדולי קרקא"},{"i":30354,"n":"מייזלש, שמעון מזולקוא","b":"רב בזלקווא"},{"i":30355,"n":"מייזלש, שמשון מזולקוא וצעשינוב","f":"יעקב","bt":"תס","dt":"תקכט - ט סיון","dp":"צעשינוב","b":"רב בצעשינוב-תצו, זולקוא-תקח. חתם בפנקס זולקוא-תקכא. תשובה ממנו בשו\"ת גאוני בתראי, מתורתו בספר תלמידו \"נועם מגדים\" מטרניגרד. בנו ר חנניא ליפמן על מקומו בצשינוב אחריו, בנו - ר משה צבי הירש על מקומו בזולקוא. הסכים על \"מענה אליהו\" זולקוא תקיח, \"בית פרץ\" תקכג, \"מים עמוקים\" תקך, \"צמח מנחם\" תקכא, \"שבט מישראל\" תקלב, \"עיר דמשק אליעזר\", \"אבן שהם\", ועוד. היה נכדו או אחיינו של ר צבי הירש מייזלש מבעלז."},{"i":30356,"n":"מייזלש-בודנר, עוזיאל מטשכויב","f":"יוסף מהנושביץ","k":"בעל בן עוזיאל","bt":"תרכו","bp":"ברדיוב","dt":"תרצב - יז תמוז","b":"חתן ר נפתלי צבי הרפידר מרישא. רב בטשחויב, קומרניק(=קאמארניק)-תרמט, ביסטריץ-תרנה-עד. חיבר \"בן עוזיאל\" בעקלאן תרצד, ועוד."},{"i":30357,"n":"מייזלש-הורביץ, יצחק שמשון","f":"אביגדור מקמינקא","k":"בעל מעשי למלך","bt":"תקמז","bp":"קמינקא","dt":"תרלט","b":"נכד ר משה צבי הירש מייזלש. נקרא בשם אמו-מייזלש ובשם אביו-הורביץ. חתן ר דוד צבי אוירבך מנוסטרישץ. רב במנוסטרישץ-תקעב, זולקוא-תקעח, טשרנוביץ-תקצב. ההדיר ספרי קדמונים, חיבר \"מעשי למלך\" טשרנוביץ תרח, ועוד."},{"i":30358,"n":"מייזנר, זבולון יצחק מסיקס","f":"יהודה מווינרן","k":"בעל תולדות יצחק","b":"גביר מחכמי סיקס-תרם. חיבר \"תולדות יצחק\" מונקטש תרסב, עם הקדמה מבנו ר מרדכי חיים."},{"i":30359,"n":"מייזנר, יהודה (יוסף) מווינרן","dt":"תרלח - טז אדר","b":"תלמיד מהר\"ם א\"ש מאונגואר. חתן ר חיים קיצע בעל \"אוצר החיים\" (אולי הכוונה לבנו - ר משה). רבה הראשון של דאווא ואניא(=ווינרן,ויינערן)-תקצח וראש ישיבה, כיהן גם כרב המחוז-יאס נאגי קון סולנוק."},{"i":30360,"n":"מייזנר, יוסף יצחק","dt":"תשד","b":"רב ביונק. חתן ר מרדכי אפרים פישל פישר משאראש-פוטוק."},{"i":30361,"n":"מייזנר, מרדכי חיים מגרוסורדין","f":"זבולון יצחק מסיקס","dt":"תש - יב סיון","dp":"גרוסורדין","b":"נכד ר יהודה מווינרן. תלמיד ר שאול ארנפלד מסיקס. התישב באדנבורג (=שופרון). מחכמי גרוסורדין-תרסה, וממיסדי \"תומכי הישיבות\" שם. מתורתו ספר אביו \"תולדות יצחק\" וחיבר לו הקדמה. הניח חדושים בכת\"י."},{"i":30362,"n":"מייזנר, משה מניו יורק","f":"יהודה מויינערן","k":"בעל עטרת שלמה","bt":"תקצט","dt":"תרעח - יח תמוז","dp":"ניו יורק","b":"תלמיד הכת\"ס, ור ישראל יצחק אהרן לנדסברג מגרוסורדין. חתן ר חיים קיצע מאירשע בעל \"אוצר חיים\" (אולי הכוונה לאביו - ר יהודה). רב ברימאסאמבאט-תרכג, ניו יורק-תרכח. חיבר גם \"ספר החזקה פלפולים\", ועוד. הסכים מניו יורק-תרלה על \"עטרת שלמה\" לאב\"ד פונטנאק."},{"i":30363,"n":"מייזנר, עזריאל מבודפשט","f":"זבולון יצחק חייא","dt":"תרסט - ב אב","dp":"וינה","b":"תלמיד השב\"ס. חתן ר ישראל אבלס מבודפשט. מחכמי סיקסא, בודפשט."},{"i":30364,"n":"מייחסים לר' אביגדור קרא [ראה בערכו]","b":"ספר הפליאה נקרא גם: ספר הקנה; קנה בינה; טעמי מצוות: המייחסים את ס' הפליאה לר\"א קרא: רמ\"ע מפאנו (עשרה מאמרות, מאמר אם כל חי סי' יז). אך בשם הגדולים (מערכת ספרים ע' פליאה) הביא דעות נוספות: יש אומרים ר' נחוניא, יש אומרים ר\"ג קארו, יש אומרים ר' קנה ב\"ר אביגדור ממשפחת ר' נחוניא בן הקנה, ויש אומרים ר' קנה אביו של ר' נחוניא.","bk":[["הפליאה",""]]},{"i":30365,"n":"מייטלש, ליב","b":"תלמיד ישיבת \"בית ישראל\" באלכסנדר. פרסם מאמרים ב\"נהור שרגא\" - אלכסנדר תרצט."},{"i":30366,"n":"מייטלש, צבי הירש מירוסלב","f":"נפתלי הירץ הלוי","b":"מגדולי ונכבדי יערוסלב-תק\"נ"},{"i":30367,"n":"מייליס, אליהו מוילנא","f":"משה מפינסק","dt":"תקכג - ד טבת","dp":"וילנא","b":"מראשי קהילת וילנא ופרנס מדינת ליטא. חתם כנציג וילנא בזמן מחלוקת ר יונתן איבשיץ, הסכים על \"שערי בנימין\" עם הרב יסו\"ד. חתם עם ר אריה ליב בלוך על כתב רבנות ר שמואל מוילנא. נקבר לצדו של ר שלמה זלמן אבי הגר\"א - ועל מצבתו נאמר \"והציל את ישראל מכליון וחרץ\" (לא נודע על מה)."},{"i":30368,"n":"מיימון הדיין","f":"יוסף החכם","k":"אבי הרמב\"ם","b":"מגדולי התורה והמדע,דיין בקורדובה,הגלה לפאס,עזב לעלות לירושלים-ד'תתקכ\"ה"},{"i":30369,"n":"מיימון, אברהם מירושלים","b":"פרסם מאמרים ב\"אורים\" - ירושלים תשז."},{"i":30370,"n":"מיימון, אהרן","b":"רב בזקרטשין"},{"i":30371,"n":"מיינץ - משפחה","b":"משפחת בנקאים בפפד\"מ, ומראשי הקהלה האורטודוכסית."},{"i":30372,"n":"מיינשטרש, משה מוינה","k":"בעל פנים מסבירות","b":"חיבר \"פנים מסבירות\"."},{"i":30373,"n":"מייצע מקריספולי","b":"מחכמי קריספולי - תשובה אליו ב\"שואל ומשיב\"."},{"i":30374,"n":"מייקוביץ, מאיר מנוברדוק","dt":"תשג","b":"רב בנוברדוק"},{"i":30375,"n":"מייר, נ' מאנגליה","b":"ביקר בתורכיה-1908 וכתב ספר על חיי היהודים בתורכיה-באנגלית, ובו גם על כת ה\"דונמה\"."},{"i":30376,"n":"מיישטרי, חיים","b":"מגדולי חכמי אשכנז,רב במיישטרי-ר\"ל"},{"i":30377,"n":"מיישטרלן","b":"מגדולי חכמי אשכנז,רב בנוישטט-ר\"כ"},{"i":30378,"n":"מיישי, דוד מפיררה","f":"ידידיה","b":"רב בפיררה בזמן הר\"פ מונסיליסי ור יצחק ידידיה בורגי. מתורתו בספרי חכמי דורו וב\"עפר יעקב\"."},{"i":30379,"n":"מיכאל הזקן מאדרינופול","b":"מראשי עדת הקראים באדרינופול. בנו - יוסף. בזמנו התירו לקראים לראשונה להדליק נר בערב שבת כמנהג היהודים."},{"i":30380,"n":"מיכאל הכהן מאזמיר","b":"זקנו של ר אליהו האיתמרי בעל \"שבט מוסר\" המביא מתורת זקנו."},{"i":30381,"n":"מיכאל הכהן מחברון","f":"משה","b":"מחכמי חברון, בשנת תקלא בשליחות ברודוס. בשנים תקמח - תקנח, חתם עם חכמי חברון."},{"i":30382,"n":"מיכאל הכהן מירושלים","f":"משה","dp":"ירושלים","b":"מחכמי ירושלים. נכד ר מיכאל הכהן בעל \"משפט צדק\". הגיה \"עת לחננה\"."},{"i":30383,"n":"מיכאל הכהן מקלינורדין","b":"רב בקליינעדרינגלן-תרמ\"ג"},{"i":30384,"n":"מיכאל הכהן משלוניקי","f":"יום טוב","dt":"תקכא - בערך","dp":"שלוניקי","b":"מחכמי שלוניקי. חתם על פסק ר בנבנשתי גטניו לקהלת קורפו-תקטו."},{"i":30385,"n":"מיכאל הכהן משלוניקי וסרייבו","f":"משה","k":"בעל מורה צדק","bp":"סופיה","dt":"תלח - יד אב","b":"מחכמי שלוניקי, סופיה, רב הכולל בסרייבו(=שאראי). תלמיד ר שמואל גאון, ר דניאל אישטרושא. בניו ר משה הכהן - רב בסופיה, ור יום טוב - רב בשלוניקי."},{"i":30386,"n":"מיכאל הלוי משלוניקי","f":"אברהם בן יצחק","b":"רב וראש ישיבה בשלוניקי-תקם, דיין-תקנז. הו\"ל ספר זקנו - \"באר מים חיים\" יחד עם בן דודו - ר מנחם בכור בן יעקב הלוי, הכין לדפוס \"תורת משה\" לר משה חיים-תקנז. מתלמידיו: ר אברהם אישטרושה, מהר\"ם טאזארטי, ר דוד קראסו הזקן."},{"i":30387,"n":"מיכאל יהודה משלוניקי","b":"גביר בשלוניקי, סייע בהדפסת \"בן ידיד\" - שלוניקי תקסו."},{"i":30388,"n":"מיכאל יוסף משלוניקי","b":"נכד ר יוסף דוד-מהרי\"ד וחיבר הקדמה לספרו \"יקרא דשכבי\" יחד עם בן דודו - ר יוסף בן יוסף."},{"i":30389,"n":"מיכאל כץ מאונסדורף וסלנץ","dp":"סלנץ","b":"מחכמי אונסדורף, דיין בסלנץ."},{"i":30390,"n":"מיכאל ליאון מצפת","b":"מחכמי צפת, בשנים תקמג - תקנג, חתם עם חכמי צפת. בשנת תקס חתם על כתב שליחות ר חיים מודעי."},{"i":30391,"n":"מיכאל מבוכארה","f":"דוד","b":"דיין בבוכארה אצל ר חזקיה הכהן רבין, ועמו הדיינים ר משה מלה כהן, ור אברהם בן אהרן."},{"i":30392,"n":"מיכאל מברלין","f":"אברהם","b":"מראשי הקהילה בברלין-תע, והיה מתומכי ר מרדכי ראנבאך בזמן המחלוקת אודות ביהכ\"נ בברלין."},{"i":30393,"n":"מיכאל מגורליץ","dt":"תקסו - ז אד\"א","b":"מו\"צ בגורליץ"},{"i":30394,"n":"מיכאל מזולקוא הרופא","f":"ישראל","dt":"שעד - יד סיון","dp":"זולקוא","b":"רופא בזולקוא."},{"i":30395,"n":"מיכאל מזשירק","b":"רב בזשירק-תר\"ע"},{"i":30396,"n":"מיכאל ממינסק","b":"שמש ביהמ\"ד במינסק ומקורב לגדול ממינסק שהעריך את גדלותו והתספק אם יכול להנות משימושו."},{"i":30397,"n":"מיכאל מסטולין","dt":"תשג","b":"רב בסטאלין"},{"i":30398,"n":"מיכאל מקנדיאה","f":"שבתי","b":"מחכמי קנדיאה בזמן גירוש ספרד. חברו של ר משה קפסאלי - ראש הרבנים בקושטא, ועמד לצדו במחלוקת עם המהרי\"ק."},{"i":30399,"n":"מיכאל רפאל מפיררה","dt":"שס - כ שבט","b":"רב בפיררה"},{"i":30400,"n":"מיכאלשוילי, מיכאל מגרוזיה","k":"חכם מיכאל הקטן","bt":"תריב","b":"מראשי הדיינים בגרוזיה, את כינויי קיבל מרבני ירושלים - שעמם היה בקשר רציף. בניו ר משה ור אהרן."},{"i":30401,"n":"מיכל הכהן מירושלים","b":"מדפיס בירושלים. הו\"ל \"הלבנון\", \"כבוד הלבנון\" - ירושלים תרכג - יחד עם ר יחיאל בריל ור יואל משה סלומון. ממיסדי נחלת שבעה?"},{"i":30402,"n":"מיכל לעזר מפרשבורג","f":"שמעון מיכל מפרשבורג","b":"בנו של ראש היהודים מפרשבורג. מראשי קהלת פרשבורג. ממיסדי החברא קדישא בפרשבורג יחד עם אחיו ר מאיר."},{"i":30403,"n":"מיכל מאזיפולא","b":"רב באזיפאלא-תר\"מ"},{"i":30404,"n":"מיכל מברסלוי","b":"רב בברסלוי-תק\"כ"},{"i":30405,"n":"מיכל מדטנובה","dt":"תרס","b":"רב בדטנובה-ליטא, בני משפחות כגן ושפירא בדטנובה - היו מצאצאיו."},{"i":30406,"n":"מיכל מוישנוויץ","f":"מרדכי מקרמניץ"},{"i":30407,"n":"מיכל מלכוביץ","dt":"תקפז - יח אדר","b":"תלמיד ר מרדכי מלכוביץ. מתלמידיו ר משה מקוברין, ור אברהם מסלונים."},{"i":30408,"n":"מיכל מלעכוביץ","b":"רב בלעכאוויץ-תק\"ע"},{"i":30409,"n":"מיכל מסלנט","f":"גבריאל","b":"ש\"ץ ושו\"ב בסלנט, מכתב המלצה ממנו לשוחט-תרנז."},{"i":30410,"n":"מיכל מסמרגון ווילנא","f":"פיבש","b":"מ\"מ ומו\"צ בסמרגון, היה גם בוילנא-שנות ה-תק'."},{"i":30411,"n":"מיכל מפינטשוב"},{"i":30412,"n":"מיכל מקאשיבקה","f":"שמואל מקאשיבקה","k":"אדמור מקאשיווקא","b":"רב בקאשיבקה-תק\"צ"},{"i":30413,"n":"מיכל מקורמנא","f":"אהרן מפרעמישלן","b":"רב בקומרנא-תקץ."},{"i":30414,"n":"מיכל מרייכנבך","b":"מגדולי רבני אשכנז,מרביץ תורה ברייכנבך-קע\"ח"},{"i":30415,"n":"מיכלאשוילי, יצחק מקולשי-גרוזיה","f":"אברהם","bt":"תרסד","bp":"קולאשי-גרוזיה","b":"תלמיד ישיבת קולאשי-גרוזיה בראשות ר ישראל בותראשוילי, ותלמיד ר אברהם סלבין בישיבת כותאיסי. שו\"ב וחזן בצחקאיה-גרוזיה-תרפט, זוגדידי-תרצט והקים שם בית כנסת. רב בקולאשי על מקום ר אהרן בותראשוילי-תשיד."},{"i":30416,"n":"מיכלה מקוריץ","b":"רב בקוריץ-תר\"ל"},{"i":30417,"n":"מיכלוביץ, יחיאל מיכל מברוד","f":"לוי משה יהודה מברודי","dt":"תשד - ט סיון","b":"חתן ר שלום שפירא מראווא-רוסקא בן ר אבי עזרי זליג אלעזר מקאלושין (דומברובא). נספה בשואה."},{"i":30418,"n":"מיכלוביץ, לוי משה יהודה מברוד","f":"מרדכי אינגרליב","k":"אדמור מברוד","dt":"תרעט - ב אד\"א","b":"מצאצאי ר יחיאל מיכל מזלוטוב תלמיד הבעשט. הגיע מברודי והיה אדמור בקלויזנבורג וכונה \"הרבי מברוד\", נפטר כמה שנים לפני השואה, ובנו ר יחיאל מיכאל על מקומו אחריו."},{"i":30419,"n":"מיכלוביץ, שלום מברוד","f":"יחיאל מיכל מברוד","k":"אדמור מברוד בארה\"ב","dt":"תשמה - כ טבת","dp":"ארה\"ב","b":"חתן ר משה יהושע מבענדר (סטרליסק). אדמור מברוד בראשל\"צ, ארה\"ב, ובנו ר אברהם מראדויל חתן ר צבי מספינקא (רופשיץ) על מקומו אחריו."},{"i":30420,"n":"מיכלין, דב בר מקזמירוב","f":"משה ליב","k":"בעל דברי תורה","bt":"תרד","b":"רב בקאזמירוב(=קאזימיראוו)-פלך מינסק-תרכה, דומ\"צ בבברויסק, רב בקאפטקוביץ(=קאפטקאוויטש)-פלך מינסק. נסמך מאת: ר הלל מפאריטש. חיבר \"דברי תורה\" על התורה והשו\"ע - נדפס בחלקו."},{"i":30421,"n":"מיכלין, חיים מיכל","b":"פרסם מאמרים ב\"תורת ארץ ישראל\" - ירושלים תרץ."},{"i":30422,"n":"מיכלסון, אברהם חיים שמחה","f":"צבי יחזקאל","k":"בעל שמן הטוב","b":"חיבר גם \"אהל אלימלך\", \"אהל נפתלי\"."},{"i":30423,"n":"מיכלסון, יצחק יהודה מוילנא","f":"צבי","b":"חתן ר טוביה באיי מטירקשלי."},{"i":30424,"n":"מיכלסון, מרדכי מוטיל מקאלושין","f":"שלמה","k":"בעל מאמר מרדכי","b":"נכד ר יחיאל מיכל מקאלושין שעניצא ונאוי-מינסק. רב בקאלושין."},{"i":30425,"n":"מיכלסון, צבי יחזקאל מפלונסק","f":"אברהם חיים","k":"בעל בית יחזקאל","r":"אב\"ד פלונסק","bt":"תרכג","bp":"בילגוריי או פיעטריקוב","dt":"תשג","dp":"וארשא","b":"סופר, מומחה בתולדות רבנים וצדיקים, רב בקראסניברד-פלך לובלין-תרמ, פלונסק-פלך וארשא-תרנג, ראש ועד הרבנים בוארשא-תרפ. חתנו ר ישראל ברגר. פרסם מאמרים ב\"אהל תורה\" - קראקא תרפח, \"אור תורה\" - ירושלים תרנז, \"הבאר\" - זאמושץ-וארשא - תרפד, \"דבר בעתו\" - פאקש תרסט, \"וילקט יוסף\" - מונקטש-פאקש-בוניהאד תרנט-תרעז, \"יגדיל תורה\" - סלוצק-בוברויסק תרסט, \"כנסת חכמי ישראל\" - אודסה-פיעטרקוב-ברדיטשוב תרנג-תרס, \"הכרם\" - וארשא תרפז, \"הכרם\" - וארשא תרצא, \"המאסף\" - ירושלים תרנו. עורך \"קובץ דרושים\" - פיעטרקוב תרפג, \"קובץ מפרשי התורה\" - מארגרטן תרצג, \"שערי תורה\" - וארשא תרסג, \"תורה מציון\" - ירושלים תרנה-תרסה. בנו - רא\"ה שמחה בונם בעל \"שמן הטוב\".","bk":[["פינות הבית",""]]},{"i":30426,"n":"מיכלסקי, יעקב אברהם יחיאל","f":"שאול","k":"בעל למודי אברהם","b":"רב ביהכ\"נ ישורון בתל אביב-תשז."},{"i":30427,"n":"מיכלשטט, ישראל מנ\"ש-מניקלשבורג","k":"בעל מילין דרבנן","b":"מחכמי ניקלסבורג-תק\"כ, מיושבי ביהמ\"ד של ר משה חלפן בברלין. חיבר גם \"בית ישראל\" על \"עין יעקב\"."},{"i":30428,"n":"מיכלשטט-פרנקל, צבי מגרוסורדין","b":"מחכמי גדברצין-תרך, גרוסורדין, מראשי הקהלה בבודפשט. נכדו של ר ישראל מיכלשטט מניקלשבורג. חתן ר משה צבי שפיגל מהומנא."},{"i":30429,"n":"מיל, יוסף שלמה","f":"חיים","k":"ג'ון מיל","bt":"1870","bp":"פוניבז","dt":"1952","b":"ממיסדי הבונד, ומאנשי המחתרת הסוציאליסטית בוילנא ובוארשא. עורך ספרות ה\"בונד\" בפולנית. היגר לארה\"ב-1951. פרסם ספר זכרונות-1946."},{"i":30430,"n":"מילבסקי, אהרן ממונטוידאו","f":"משה אריה ליב","k":"בעל מנחת אהרן","bt":"תרסד","bp":"אליטא-ליטא","b":"גדל אצל זקנו ר יוסף יעקב רוזנברג מאליטא. תלמיד ישיבות גרודנא, סלובודקה. עלה לארץ-תרפד עם הקבוצה הראשונה של ישיבת סלובודקה שעברה לחברון. רב באליטא-תרפט, מונטוידאו-אורגוואי-תרצז. חיבר גם \"נחלת אהרן\", ועוד. בזמן השואה פעל רבות בעניני הצלה ועזרה לפליטי שנחאי."},{"i":30431,"n":"מילבסקי, יעקב פישל","b":"פרסם מאמרים ב\"כנסת הגדולה\" - וארשא תרן."},{"i":30432,"n":"מילבסקי, משה אריה מליטא","f":"מתתיהו","bt":"תרלח","bp":"טראסטינה-ליד ביאליסטוק","dt":"תשא-ג","b":"תלמיד ישיבות ביאליסטוק, מינסק, וכולל קובנא. חתן ר יוסף יעקב רוזנברג מאליטא. ר\"מ במייצ'ט-ליד ברנוביץ, שאדובה, רב בפראן, רבה האחרון של דרשונישוק. נספה בשואה עם בני עדתו. בניו: ר אהרן ממונטבידאו, מאיר מילוא מארץ ישראל."},{"i":30433,"n":"מילדולה, אברהם","f":"דוד מילדולה","b":"שנת תקנ\"ד"},{"i":30434,"n":"מילדולה, אליעזר מפיסא","b":"רב בפיסא-תעד."},{"i":30435,"n":"מילדולה, דוד מאמשטרדם","f":"רפאל-מים רבים","k":"בעל קיצור ציצת נובל","bt":"תסג","dt":"תקנג","b":"חתן ר נתנאל אלישיב צרפתי מאמשטרדם. רב וראש ישיבת משענת זקנים באמשטרדם-תצז. דור תשיעי למשפחת רבנים ממגורשי ספרד. חיבר \"מים רבים\", \"דרכי דוד\" ועוד. רבים ממשפחתו היו רבנים ממנטובה ומליוורנו. ומצאצאיו רבנים בעיר לגנדריס."},{"i":30436,"n":"מילדולה, דוד מלונדון - ג","f":"רפאל מליוורנו","k":"בעל מזמור לתודה","bt":"תקנז","dt":"תריג","b":"אב\"ד קהלת הספרדים בלונדון-תרג."},{"i":30437,"n":"מילדולה, דוד ממנטובה - א","b":"רב במנטובה-תיד."},{"i":30438,"n":"מילדולה, רפאל מליוורנו","k":"בעל מים רבים","b":"רב בפיסא, ביונה(=באיונה)-צרפת?, ליוורנו-תע. חיבר גם \"חופת חתנים\" ליוורנו. פגש את ר חיים יעקב מצפת בשליחותו שם."},{"i":30439,"n":"מילדולה, שמואל רופא מאיטליה","f":"רפאל","k":"בעל קיצור ציצת נובל","b":"רב בוירונה-תיב, במנטובה בזמן ר גור אריה הלוי. היה רופא הדוכס. מוזכר אצל ר יעקב ששפורטש ב\"אהל יעקב\"."},{"i":30440,"n":"מילהויזן, יום טוב ליפמן","k":"בעל ספר הנצחון","b":"מקובל מגדולי חכמי אשכנז, דיין בפרג-קסז. חיבר ספר האשכול בקבלה, חיבר גם פירוש על תמונות אותיות הא\"ב על דרך הקבלה, פירוש לשיר היחוד בשם \"ספר הנצחון\"."},{"i":30441,"n":"מילהויזן, עזריאל זליגמן מאשכנז","f":"חיים","b":"מחכמי אשכנז. חתם על תקנות אסיפת הרבנים בפפד\"מ-שסג בשם יהודי טאובר."},{"i":30442,"n":"מילו, אליה מארטא","b":"גביר בארטא, הניח ירושה גדולה להקדש, והיה מחלוקת על כך בין הרבנים."},{"i":30443,"n":"מילזגי, אליקים גצל מברוד","f":"יהודה ליב מהלזאק","k":"בעל זהרי ראבי\"ה","bt":"תקם","bp":"סמילא","dt":"תריד","b":"תלמיד חכם ומבין בקבלה. חיבר \"זהרי ראבי\"ה\" אופן תקצז ובו השגות על ספרו של צונץ. חיבורים רבים נוספים - בכתב יד."},{"i":30444,"n":"מילי די, אלעזר מפיררה","k":"בעל דברי חפץ","b":"מחכמי איטליה, רב בפיררה-שי\"ב, חיבר \"דברי חפץ\" ובהקדמה מודה לדון שמואל אברבנל ובנו ר יהודה על תמיכתם בו."},{"i":30445,"n":"מילי, יוסף מאיטליה","f":"מאיר","b":"רב באיטליה בזמן הרמ\"ז ור שמחה לוצאטו. תשובה ממנו מהעיר פינאלי."},{"i":30446,"n":"מילי, יחיאל מאיטליה","k":"בעל תפוחי זהב","b":"מחכמי איטליה-של, חיבר \"תפוחי זהב\" והוא קיצור \"ראשית חכמה\", נדפס ע\"י חתנו - ר דוד בן משה משער אריה."},{"i":30447,"n":"מילי, יעקב מצפת","b":"מחכמי צפת-שנות ה-ש'."},{"i":30448,"n":"מילך, ירוחם פישל מזלוטניק","f":"מנחם מנדל","bt":"תריב","b":"אב\"ד זלוטניק-תרמד."},{"i":30449,"n":"מיללער אביגדור בן ישראל","bt":"1908","dt":"ה'תשסא 2001","bk":[["שערי אורה",""]]},{"i":30450,"n":"מילנר, משה אהרן מיאלוק","dt":"תשג","b":"רב ביאלוק"},{"i":30451,"n":"מילצקי, חייקל זאב","dt":"תשכד","b":"מרביץ תורה בירושלים"},{"i":30452,"n":"מילצקי, ראובן מליטא וירושלים","f":"דב משה","k":"בעל חיי הגוף והנפש","bt":"תרלג","bp":"אורלה-פלך גרודנא","dt":"תשיג","dp":"ירושלים","b":"תלמיד ישיבת ביאליסטוק. מנהל רוחני בישיבת \"כנסת ישראל\" בסלובודקה. ר\"מ בישיבת ר הירש לויתן בסלובודקה. סירב לרבנות. ביקר בערי רוסיה וליטא ודרש ברבים. גורש עם יהודי קובנא בזמן מלחה\"ע ה-I והגיע ללובני-אוקראינה ופרסם חוברת \"גירוש קובנא\". אחרי המלחמה בשליחות הישיבה באמריקה, ובזמן שהיה שם העביר את משפחתו לארץ. עלה לירושלים-תרפה, בשליחות בארה\"ב וחזר אחר השואה. פרסם מאמרים ושירים בכתבי העת \"קול ישראל\", \"כנסת ישראל\" - נ\"י תרצב - כתב עת הסתדרות תלמידי סלובודקה באמריקה. ועוד. בנו ר חייקל - ר\"מ בירושלים, חתנו ר דוד ויין - רב בחולון."},{"i":30453,"n":"מילקובסקי, אליהו אהרן מגריווא","f":"מרדכי אוריה","k":"בעלי אהלי אהרן","bt":"תרכד","dt":"תשטז - טז סיון","b":"תלמיד ישיבת וולוזין. רב בגראייבה(=גראיעווא)-פלך לומזה-תרמב, חרקוב-תרעב, ראב\"ד בתל אביב-תרפח. פרסם מאמרים ב\"בית מדרש\" - תל אביב תשא."},{"i":30454,"n":"מילקובסקי, בנימין מוילנא","b":"פרסם מאמרים ב\"הנשר\" - טירנוי תרצג-תשד."},{"i":30455,"n":"מילקובסקי, הלל חריף מסלנט","f":"צבי","k":"הלל סלנטר","bt":"תקעט","bp":"וילנא","dt":"תרנט - כג סיון","b":"תלמיד חבר לר ישראל סלנטר. תלמיד בישיבת מייליס, יחד עם ר אלכסנדר משה לפידות. רב בקראווה, סלנט, פוניבז, שקלוב, חסלאוויץ - ויתר על הרבנות לטובת ר יהושע הורביץ שירד מנכסיו ונזקק לרבנות, רב באמציסלב. לעתים קרובות נסע בשליחות ר ישראל סלנטר בעניני ציבור. היה במגע עם השלטונות ומשפיע עליהם בעניני ציבור. השתתף בועידת רבנים שהוזמנה לדיונים עם הממשלה בפטרבורג יחד עם ר שמואל מוהליבר, ר צבי רבינוביץ מקובנא ועוד. ממונה קופת רמבע\"ה בגליל ראסיין. סירב לרבנות בפריס."},{"i":30456,"n":"מילקובסקי, חיים","bt":"תרעו","dt":"תשנג","b":"תלמיד ישיבת מיר, ניצל מהשואה והגיע לשנחאי-סין. חתן האדמור ר ירחמיאל יהודה מאיר קאליש מאמשינוב. בנו - ר יעקב כיהן כאדמו\"ר מאמשינוב. פרסם מאמרים ב\"מאור תורה\" - שנחאי-סין תשד - קובץ תלמידי ישיבת מיר בשנחאי."},{"i":30457,"n":"מילקובסקי, יעקב אריה ישעיה","f":"חיים-חתן האדמור מאמש","k":"אדמור מאמשינוב י-ם","b":"נכד מצד אמו לר ירחמיאל יהודה מאיר מאמשינוב ירושלים. אדמור מאמשינוב בירושלים על מקום זקנו."},{"i":30458,"n":"מילקובסקי, יצחק איזיק מברנוביץ","b":"פרסם מאמרים ב\"תורת ארץ ישראל\" - ירושלים תרץ."},{"i":30459,"n":"מילקובסקי, לוי הכהן","dt":"תרפה","b":"רב בלעכנדאווא"},{"i":30460,"n":"מילר, אברהם מניו יורק","b":"רב קהלת \"בית ישראל\" בניו יורק."},{"i":30461,"n":"מילר, אברהם מפאקש","f":"יעקב אליהו מילר מנדש","bp":"נאדאש","dt":"תש..","b":"תלמיד השב\"ס. חתן ר משה ישכר דב בר שלזינגר מפאקש. רב בפאקש. נספה בשואה."},{"i":30462,"n":"מילר, אברהם מפודגורזע","f":"שלום","b":"חתן המהר\"ש ענגל. רב בפודגורזע. נספה בשואה. בנו ר יצחק השיב לב\"ד ר אלחנן הלפרין - \"מקדשי השם\"-תרצו."},{"i":30463,"n":"מילר, אברהם מקוואקוביץ","f":"שבתי יצחק","b":"נכד הש\"ך וה\"חכם צבי\". מחכמי קוואקוביץ. חתן ר משה שמעון שיינדלין. נספה בשואה."},{"i":30464,"n":"מילר, אורי משוסבורג","dt":"תרמ - ל תשרי","b":"דומ\"צ בשוסבורג,רב בברעזאווא"},{"i":30465,"n":"מילר, אירוינג","f":"אברהם","bt":"1903","bp":"קובנא","b":"היגר לארה\"ב-1912, תלמיד ישיבת ר יצחק אלחנן בנ\"י, אוניברסיטת פיטסבורג וקולומביה. רב ריפורמי ב\"טמפל עמנואל\" ביונגסטאון, וב\"שערי תפלה\" בניו יורק. מזכיר הקונגרס היהודי העולמי. חבר הנהלת \"בני ברית\"."},{"i":30466,"n":"מילר, אפרים גומפריך מבינגן","b":"רב בבינגן-תקנג עד תקסח."},{"i":30467,"n":"מילר, אפרים יצחק","f":"נפתלי מגורליץ","bt":"תרסה","dt":"תשד","b":"חתן ר מנחם כץ ממונקטש. נספה בשואה."},{"i":30468,"n":"מילר, אשר אנשיל יהודה מפטרוזן","f":"חיים","k":"בעל לחם אשר-תרפט","bt":"תרם","dt":"תשכא- יג תשרי","b":"נכד(-אבי אמו) ר יהושע ברוך רייניץ מטשעטשביץ. תלמיד השב\"ס, ור כלב פיבל שלזינגר מטאפולצ'אן. חתן ר פנחס ביליצר מסערנטש וגיסו של ר אפרים ביליצר מבעטלן. רב בכפר טיסא-לוץ-ליד סערנטש-תרסו, רב בפטרוז'ני(=פעטראזשאני)-תרסח למעלה מ-50 שנה. ניצל מהשואה ואחריה מראשי ארגון הרבנים האורטודוכסים בהונגריה. עלה לארץ-תשיח-תשך, והתגורר אצל בנו ר לוי יצחק רבה של קרית בנימין. בנו ר פנחס רבה של נצרת עלית הו\"ל \"עולמו של אבא\" ובו זכרונות מגדולי טרנסילבניה ורומניה ועל תולדות חייו של ר אשר. פרסם מאמרים ב\"המגיד\" - סטמר תרפח. חיבר גם \"קרבן אשר\". בניו גם - ר לוי יצחק מפעטרזאשני, ר עמרם ישי מטעלעגד.","bk":[["חיי אשר",""],["לחם אשר",""],["פירורי לחם",""],["קרבן אשר",""]]},{"i":30469,"n":"מילר, בן ציון מבוכניה","f":"שמואל אהרן מלאבווא","dt":"תש..","b":"חתן ר יצחק מויליפולי. מוהל ומו\"ץ בבוכניה. נספה בשואה עם 11 ילדיו."},{"i":30470,"n":"מילר, בנימין פרנקלין","bt":"1874","bp":"יאנישקול","dt":"1949","dp":"פילדלפיה","b":"היגר לארה\"ב-1886. תעשיין ונדבן. מראשי התנועה הציונית בארה\"ב. ויסד יחד עם סטפן וויז את ההסתדרות הציונית באמריקה. פעל לטובת מוסדות ציבור יהודיים בפילדלפיה והיה חבר בקונגרס היהודי."},{"i":30471,"n":"מילר, גבריאל ממטרסדורף","f":"חיים מנאדאש","k":"בעל אוצר אגדות","bt":"תקצב","bp":"נאדאש","dt":"תרסז - א חשון","b":"תלמיד הכת\"ס. רב במטרסדורף-תרלא. חיבר \"שיעורי מצות\", \"מעגלי צדק\" ועוד. בנו ר יואל אב\"ד נאדאש."},{"i":30472,"n":"מילר, דוד מסיגט","f":"משה מסיגט","bt":"תרלג","bp":"סיגט","dt":"תשג - א אלול","dp":"תל אביב","b":"תלמיד השב\"ס. עלה לארץ ושימש כמורה בראש פינה ושאר מקומות."},{"i":30473,"n":"מילר, חיים מברעזאויץ","b":"חתן ר יהושע ברוך רייניץ מטשעטשאוויץ. בנו ר אשר אנשיל יהודה מפעטראזשען."},{"i":30474,"n":"מילר, טוביה זיסקינד מדרום אפרי","f":"בנימין יהודה","bt":"1884","bp":"וילקומיר","dt":"1962","b":"תלמיד ישיבות ליטא. היגר לדרום אפריקה והתישב בקייפטאון. יסד שם אגודת \"צעירי ציון\". עבר לארה\"ב ועסק בפעילות ציונית. עלה לארץ-1903 והתישב ברחובות, והיה ממיסדי התאחדות האיכרים, ואחד ממפתחי הפרדסנות בארץ. ציר בקונגרס היסוד של הסוכנות היהודית יחד עם ביאליק והרב ב\"צ חי עוזיאל. הקדיש זמנו הפנוי לתורה והיה בעל ספרייה פרטית מהגדולות בארץ."},{"i":30475,"n":"מילר, יואל הכהן מברלין","f":"משה ליב מאויסע","bt":"תקצג","bp":"אויסע","dt":"תרנו - יט חשון","b":"תלמיד הכת\"ס, ור שלמה הס מדרזניץ, ור שלמה קוועטש מניקלשבורג. רב באונגריש אוסטרוי על מקום אביו-תריג, לייפא, מלמד בוינה-תרלט, מורה בברלין-תרמד. הו\"ל תשובות חכמי צרפת, תשובות גאוני מזרח ומערב, ועוד."},{"i":30476,"n":"מילר, יואל מלאבובה","f":"שמעון אהרן מלאבובה","dt":"תשג","dp":"טרנוב","b":"רב ומגיה סת\"ם בלאבאווא. חתן ר שמעון ליבר מסנוק.נספה בשואה."},{"i":30477,"n":"מילר, יואל מנאדאש","f":"גבריאל ממטרסדורף","b":"רב בנאדאש-תרנ\"ב"},{"i":30478,"n":"מילר, יוסף אליעזר משופרון","f":"שלמה משופרון","dt":"תשד","b":"תלמיד הדעת סופר, ור מנחם גרינולד משופרון. רב ביאנושהאזא, שופרון. נספה בשואה. חתנו - ר יצחק צבי סופר משופרון בן ר אברהם יעקב סופר מטעט."},{"i":30479,"n":"מילר, יוסף הלוי מגלנטא","f":"אברהם מאיר","k":"בעל אור יוסף","bt":"תריט","dt":"תרצג - יז סיון","b":"דומ\"צ בגלנטא(=גאלאנטא)-תרסא. פרסם מאמרים ב\"הנשר\" - טירנוי תרצג-תשד, \"וילקט יוסף\". נסמך מאת: ר מיכאל פאפא. חתנו - ר אברהם יהודה שוורץ מקאמה בעל \"זכרון לראשונים\"."},{"i":30480,"n":"מילר, יחזקאל מקרעניצע","b":"מחכמי קרעניצע. חתנו ר נטע שלמה שליסל ממונקטש."},{"i":30481,"n":"מילר, יעקב אליהו מנדאדש","f":"חיים מנאדאש","b":"אחיו של ר גבריאל ממטרסדורף, ור נתן מסעטשין. אביו של ר אברהם מפאקש."},{"i":30482,"n":"מילר, יעקב מבאניא","b":"דומ\"צ בבאניא-תרע\"ד"},{"i":30483,"n":"מילר, יעקב מבאניא","b":"דיין בבאניא-תרן עד למלחמת העולם ה-I. נזכר ב\"נטע שורק\"."},{"i":30484,"n":"מילר, יעקב מפרשוב","f":"נפתלי מגורליץ","b":"ממיסדי קהל חסידים בפרשוב. נספה בשואה."},{"i":30485,"n":"מילר, יצחק משה מפרשבורג","b":"עסקן ציוני, עורך \"יידישעס פאמיליענבלאט\" - פרשבורג תרפו, \"אלגעמיינע יידשע צייטונג\" - פרשבורג תרצד - יחד עם דוד גרוס. עלה לארץ והתישב בבני ברק."},{"i":30486,"n":"מילר, ישראל מברזביץ","f":"חיים מברעזוויץ","dp":"ירושלים","b":"רב בברעזוויץ, עלה לירושלים. גיסו של ר משה סופר מטיסא-פירער, זקנו של ר אשר אנשל יהודה מפעטראזשן, חותנו של ר שמעון ארנפלד ממיהלביץ, ר צדוק קרויס מטראוויטש, ור עקיבא יוסף לעהמן מפרשבורג."},{"i":30487,"n":"מילר, לוי יצחק מקרית בנימין","f":"אשר אנשל יהודה","k":"בעל דברי לוי יצחק","bt":"תרסד","dt":"תשנו - ב טבת","dp":"קרית אתא","b":"תלמיד הדעת סופר. נסמך מאת ר בן ציון ויזל מטורדא-תרפג. חתן ר יוסף צבי הלפרט-הלפרין משאמקוט. עבר לשם וסייע לחותנו בניהול הישיבה בשאמקוט. רב הצעיר בפעראזשני, רב בכפר נירש(=נירעש) בגליל חותנו-תרצה ונשאר לגור בשאמקוט, דעווא(=דאווה), ניצל מהשואה ואחריה ר בטימישואר-יוזפשטט. עלה לארץ וכיהן כרב בקרית אתא - קרית בנימין."},{"i":30488,"n":"מילר, מנחם מנדל מזלוטשוב","f":"יוסף אליעזר כץ","k":"בעל מנחם ציון","bt":"תרכה","bp":"טרנוב","dt":"תרצה","b":"מחסידי צאנז, חתן רב\"צ קאהל מקמינקא. רב בזלוטשוב. חיבר \"מנחם ציון\" דרוהוביטש תרסג."},{"i":30489,"n":"מילר, משה מגורליץ","f":"נפתלי מגורליץ","bt":"תרלה","dt":"תשב","b":"רב בגורליץ על מקום אביו. נספה בשואה."},{"i":30490,"n":"מילר, משה מודוביצה","f":"אשר זליג","dt":"תרפד","b":"רב בודוביצה."},{"i":30491,"n":"מילר, נפתלי הכהן מגורליץ","f":"פסח דוד","bt":"תרה","bp":"מאלצוב","dt":"תרץ","b":"תלמיד ר הלל ליכטנשטין. רב בגורליץ בהמלצת רבו ה\"דברי חיים\". בנו ר משה על מקומו אחריו. פרסם מאמרים ב\"כרם חמד\" - פיעטרקוב תרפט - קובץ תלמידי ישיבת \"תפארת בחורים\" בגורליץ."},{"i":30492,"n":"מילר, נתן מסעטשין","f":"חיים","k":"בעל אבני חשן","bt":"תקפח","bp":"נאדאש","dt":"תרנא - ג תשרי","dp":"סעטשין","b":"תלמיד הכת\"ס, ור יהודה אסאד. חתן ר פיבל פריינד מטשוס ועבר לשם-תריא, רב בועטש-תרטז, סעטשין(=סאצ'אן)-מחוז נוגראד-תרכו, איפאלשאג-תרלו והיה ממקימי הקהלה החרדית שם, סעטשין-תרלח (חזר לשם) ובנו ר שלמה על מקומו אחריו, ובנו ר שמעון בעל \"שבת שבתון\". חיבר \"מנחה בלולה בשמן\"."},{"i":30493,"n":"מילר, עמרם ישי מטעלגד","f":"אשר אנשל יהודה-לחם א","dt":"תשד - ב אב","dp":"וארשא או אושוויץ","b":"תלמיד הדעת סופר. חתן ר יוסף חיים פישמן מטעלגד. רב בפעטראשני, טעלענד(=טלגד)-תרפו או תרצה על מקום חותנו (נשאה יתומה). נספה בשואה. פרסם מאמרים ב\"קבוצי בחורים\" - מארגרטן תרצג."},{"i":30494,"n":"מילר, פנחס מרומניה ונצרת","f":"אשר אנשל יהודה","b":"רב ברומניה. ניצל מהשואה, ואחריה רב דאווה, על מקום אחיו שעבר לטימישואר. עלה לארץ וכיהן כרבה הראשון של נצרת עילית. הו\"ל ספר אביו \"עולמו של אבא\" ובו מזכרונות ומתורת אביו, ומשלו. אשתו חברה ספר קורותיו בשם \"הרב שלי\" על חיי בעלה כרב ברומניה ובנצרת."},{"i":30495,"n":"מילר, פסח דוד","f":"אברהם ממאלצוב","b":"מחסידי צאנז. מחכמי מלצוב."},{"i":30496,"n":"מילר, צ' מאראד","b":"רב באראד לאחר השואה."},{"i":30497,"n":"מילר, שאול אלכסנדר מפרשבורג","f":"יצחק מקראקא","bt":"תרטז","bp":"קראקא","dt":"תרפג - טו אלול","dp":"פרשבורג","b":"תלמיד השב\"ס. חתן ר משה קליין מפאקש. מלמד תורה מחכמי פרשבורג."},{"i":30498,"n":"מילר, שאול מפרשבורג","b":"מלמד ב\"יסודי התורה\" בפרשבורג-תרמה, הצטיין בחריטת עצי חיים."},{"i":30499,"n":"מילר, שבתי","f":"יצחק זאב","dt":"תשד","b":"חתן ר עקיבא ליבר מישיניצה. נספה בשואה."},{"i":30500,"n":"מילר, שלמה יצחק","b":"פרסם מאמרים ב\"תבונה\" - ירושלים תשא-תשח."},{"i":30501,"n":"מילר, שלמה מסעטשין","f":"נתן מסעטשין","k":"בעל סידור שבח שבת","bt":"תריט","dt":"תרצג - ט סיון","b":"תלמיד השב\"ס. חתן ר כלב פיבל שלזינגר מטאפלטשן ועבר לשם-תרמה. רב בסעטשין על מקום אביו. הו\"ל ספרי אביו \"אבני חשן\", \"מנחה בלולה\" עם הוספות ממנו."},{"i":30502,"n":"מילר, שלמה משופרון","f":"יעקב אליהו","b":"חתן ר בנימין זאב אבלס. דודיו - ר נתן מילר מסעטשין, ור גבריאל מילר ממטרסדורף."},{"i":30503,"n":"מילר, שמואל אהרן מלובובה","f":"נפתלי מגורליץ","bt":"תרכה","dt":"תשב-ג","dp":"צאנז","b":"רב בלובאווא, קראקא, ידליץ-תרע. חתן ר מתתיהו וילדשטיין מלאבובה (ליד צאנז) ועמד בראש הישיבה שם. תלמיד ר הלל ליכטנשטין. חיבר חדושים על הש\"ס - בכתב יד. פרסם מאמרים ב\"אהל מועד\" - פודגורזע תרנח, \"אסיפת חכמים\" - אושפצין תרצד, \"כרם בית שמואל\" פיעטרקוב תרצב, \"הכוכב\" - מונקטש תרצה, \"כרם בית שמואל\" - פיעטרקוב תרצא, \"הלבנון\" - גורליץ תרפח, \"הפרדס\" - צאנז תרצא, \"קהלת אשר\" - אושפיצין תרפג, \"קובץ דרושים\" - פיעטרקוב תרפג, \"שערי תורה\" - קראקא תרפה. נספה בשואה."},{"i":30504,"n":"מילר, שמואל אליהו כץ מבוכניה","b":"בחור מחכמי בוכניה(=קאכניא)-תרצב. פרסם מאמרים ב\"לקט ששנ\"ה\" - סטמר תרצד."},{"i":30505,"n":"מילר, שמואל בנימין מפאסטא","f":"יואל מנאדאש","dt":"תשד-ה","dp":"אושוויץ","b":"תלמיד הדעת סופר. חתן ר שמעון דב מטאריאן. רב ביערגין, פרשבורג, פאסטא(=פאסטו)-תרצא. נספה בשואה."},{"i":30506,"n":"מילר, שמעון","f":"נתן מילר","k":"בעל שבח שבת","b":"דומ\"צ בפרקשד-תרע\"ד. חיבר \"שבת שבתון\". חתן ר אברהם יהודה שטרן משאק סעלעצע."},{"i":30507,"n":"מילר, שמעון זאב מאראד","b":"רבה האחרון של אראד וראש ישיבה שם - האחרונה ברומניה הקומוניסטית, היגר לארה\"ב."},{"i":30508,"n":"מילר-דרזניץ, אליעזר ממטרסדורף","bp":"דרזניץ (מהערין)","dt":"תקצח - בערך","b":"תלמיד החת\"ס. אביו היה אחיהם של ר מרדכי מילר מקוואלאפצי ור חיים מילר מנאדאש. דיין במטרסדורף-תקעג. תשובה אליו ב\"חתם סופר\"."},{"i":30509,"n":"מילשטוק, אליעזר מנריוב","b":"רב בנריוב."},{"i":30510,"n":"מילשטין, חיים יחזקאל","dt":"תשג","b":"רב בסובאטש"},{"i":30511,"n":"מילשטין, משה","dt":"תשג","b":"רב בלענין"},{"i":30512,"n":"מים, יהושע מאדרינופול","b":"רב באדרינופול - שנות ה-ש'."},{"i":30513,"n":"מימון - שם"},{"i":30514,"n":"מימון הדיין-אבי","f":"יוסף","k":"הרמב\"ם","bp":"ספרד","dp":"ירושלים או טבריה או קהיר","b":"אביו של הרמב\"ם. תלמיד ר יוסף ן מיגאש. דיין בקורדובה, ונאלץ לברוח בגלל רדיפות המוסלמים והגיע לפאס, אך נאלץ לברוח גם משם ועלה לארץ-ד'תתקכה (1165) עם שני בניו הרמב\"ם ור דוד. חיבר פירוש על התורה, ולתלמוד - הרמב\"ם השתמש בכתביו, והתשב\"ץ מביא מהם דין בדיני תפלה, חיבר אגרת הנחמה בערבית לחזוק היהודים במרוקו שסבלו משמד."},{"i":30515,"n":"מימון, אברהם","f":"יהושע מפראגא","b":"רב בפראגא החדשה-תרפ על מקום אביו."},{"i":30516,"n":"מימון, אפרים","dt":"תשג","b":"רב בפרגה-תר\"ע"},{"i":30517,"n":"מימון, בנימין מסרייבו","b":"מראשי קהלת סרייבו-שנות ה-ת' - אחד משבעת טובי העיר."},{"i":30518,"n":"מימון, חי מטריפולי - הזקן","f":"יעקב","bt":"תקך","dt":"תקץ - בערך","b":"רב ומלמד תורה בטריפולי, עבר לג'רבה-תקצב בגלל מלחמה. מתלמידיו - ר מנחם מזוז (הראשון). חתם בפנקס בי\"ד טריפולי-תקעא."},{"i":30519,"n":"מימון, חי מטריפולי - הנכד","f":"יעקב","k":"רח\"ם - בעל באר לחי","bt":"תקצג או תרז","dt":"תרמה - כא אלול","b":"תלמיד ר שלום עגיב. דרשן, מקובל, רב בטריפולי-תרמב, דיין אצל ר חיים הכהן, עם ר פרג'אללה דאבוש. הניח חדושים בכת\"י ומהם נדפס \"באר לחי\" - ליוורנו תרמח. הו\"ל ספר אביו \"מים חיים\", ועוד."},{"i":30520,"n":"מימון, יהושע מפראגא-וארשא","f":"יוסף מוארשא","bt":"תריח","dt":"תרפא","b":"נכד ר ישכר מפראגא. מו\"צ בפראגה-תרן, שמילויזנע, קמניקא. פרסם מאמרים ב\"יגדיל תורה\" - פראגא-וארשא תרפז. נסמך מאת: ר יהושע מקוטנא, וועד רבני וארשא. בניו: ר אברהם, ר יצחק, חתניו: ר יחזקאל צבי בן ר אברהם יצחק, ר יעקב יוסף זילברשטין נכד ר אלימלך מליזנסק."},{"i":30521,"n":"מימון, יוסף","b":"פרסם מאמרים ב\"הירח\" - ג'רבה תשח."},{"i":30522,"n":"מימון, יוסף מאלגיר","bt":"תן","dt":"תקך - בערך","b":"רב ודיין באלגיר בבית הדין הגדול. הסכים עם רבני אלגיר על \"פרי יצחק\" לר רפאל שלמה ידידיה צרור."},{"i":30523,"n":"מימון, יוסף מוארשא","f":"ישכר מפראגא-וארשא","b":"מו\"צ בוורשה-תרכ\"ד-תר\"נ"},{"i":30524,"n":"מימון, יוסף מקושטא","b":"דיין בקושטא-תקעה, ממונה על איסור והיתר עם ר יוסף הלוי ור חיים פינטו."},{"i":30525,"n":"מימון, יעקב מטריפולי","f":"חי מטריפולי","k":"בעל מים חיים","bt":"תקס-ט","dt":"תרז","b":"רב, דיין ונגיד בטריפולי, מקובל, תיקן תקנות בעניני הקהלה ונזכר ב\"הגיד מרדכי\", וכן תמך בלומדי תורה וחיזק את לימוד התורה בעירו. חיבר גם \"דרך החיים\"."},{"i":30526,"n":"מימון, יצחק חוג'ה מגאבס-תונס","f":"רחמין בושושה","dt":"תרצא - כז אב","b":"בנו - ר מערבי הנציחו בספר \"אוהב משפט\"."},{"i":30527,"n":"מימון, יצחק מברצלונה","b":"רב בברצלונה בזמן הר\"ן. היה במחלוקת עם ר פרץ הכהן."},{"i":30528,"n":"מימון, יצחק מפראגא","f":"יהושע מפראגא","b":"דיין בפראגא-תרפה."},{"i":30529,"n":"מימון, ישכר מפראגא","f":"אהרן מזקראטשין","b":"רב בפראגא-וארשא-תד."},{"i":30530,"n":"מימון, ישמעאל מטריפולי","f":"שלמה","bt":"רי","dt":"רף - בערך","dp":"[טריפולי]","b":"רב בטריפולי. נזכר בקולופון ל\"ספר פליאה\"."},{"i":30531,"n":"מימון, כמוס מגאבס-תונס","k":"בעל כמוס עמדי","b":"תלמיד ר חיים חורי."},{"i":30532,"n":"מימון, כמוס מלוב","bt":"תרך","dt":"תרף - בערך","b":"רב בכומס-לוב, ונזכר ב\"גנזים\" תשכט."},{"i":30533,"n":"מימון, מצליח מתונס","bt":"תרעט","bp":"גאבס-תונס","b":"תלמיד ר חיים חורי בג'רבא. פרסם מאמרים ב\"הירח\" - ג'רבה תשח."},{"i":30534,"n":"מימון, משה מגאבס-תונס","f":"יצחק","b":"רב בגאבס. חברו של ר עלוש פרג'י."},{"i":30535,"n":"מימון, נתן מטריפולי","bt":"תק","dt":"תקע - בערך","b":"רב בטריפולי. ונזכר בפנקס בי\"ד טריפולי."},{"i":30536,"n":"מימון, סרוגא מגרבה","f":"כליפא","b":"פרסם מאמרים ב\"מקבציאל\" - גרבה תרצה."},{"i":30537,"n":"מימון, שלמה","f":"דוד הנגיד","b":"מגדולי חכמי מצרים שנת ק'"},{"i":30538,"n":"מימון, שלמה זלמן מליטא","f":"יהושע","k":"בעל גבעת המורה","bt":"1753","bp":"נאסוויז","dt":"1800","dp":"נידרזיגרסדורף","b":"בצעירותו בליטא פנה לקבלה, וחיבר פירוש למורה נבוכים - אך לא העז להדפיסו בהיותו בליטא. עבר לקניגסברג, ברלין, נדד בפרוסיה ונעזר בר הירש ינובר. חזר לברלין ולמד פילוססופיה והיה מקורב למנדלסון, לזרוס בן דוד, ומרקוס הרץ אך היה שם מחלוקת ונאץ לעזוב. חזר לברלין אחר פטירת מנדלסון. הוזמן לגור באחוזת הנסיך אדולף קלקרוט בנידרזיגרסדורף - כעשר שנים - וחיבר שם ספרים שונים, וביניהם \"תולדות חיי\", וביאור על ספר המורה."},{"i":30539,"n":"מימון, שמעון כליפה מגרבה","b":"פרסם מאמרים ב\"קרן דוד\" - גרבה תרעו."},{"i":30540,"n":"מימון, שמעון מתונס","k":"בעל שם משמעון","dt":"תשמד","dp":"באר שבע","b":"רב בגאבס-תונס, תלמיד ר חיים חורי מגאבס. עלה לארץ והתישב בבאר שבע. חיבר גם \"אהלי שם\"."},{"i":30541,"n":"מימונא, מסעוד מאספי-מרוקו","dp":"אספי","b":"צדיק במרוקו, נקבר באספי ונהגו להשתטח על קברו."},{"i":30542,"n":"מימוני, דוד ממצרים","f":"יהושע","b":"מחכמי מצרים, אחרון הנגידים צאצאי הרמב\"ם, נגיד-קט\"ט-קל\"ד, בעל ספריה גדולה, נאלץ לברוח לעכו, חאלב, דמשק, בסיוע הרשב\"א חזר למצרים ושב לכהן כנגיד, מיוחס לו הספר \"דרשות רבי דוד\""},{"i":30543,"n":"מימי, נתן ממרוקו","b":"מחכמי מרוקו."},{"i":30544,"n":"מימי, שמעון מפורטוגל","b":"מחכמי גולי פורטוגל, ונתפס ועונה בבית הסוהר, תשובה ממנו ב\"כרם חמר\" בענין תקנת טוליטולא בכתובה. ופיוט ממנו ב\"יחס פאס\" ונדפס ב\"נר המערב\". והחיד\"א הזכירו כחכם מפאס."},{"i":30545,"n":"מימרן, אברהם ממכנאס","dt":"תקן","b":"מקובל, דיין במכנאס, נזכר ב\"משפטים ישרים\", חתם על פס\"ד-תקט? עם ר רפאל בירדוגו, ר חיים ביבאס."},{"i":30546,"n":"מימרן, אברהם ממכנאס","f":"שמעיה","b":"מראשי קהלת מכנאס-שנות ה-ת'."},{"i":30547,"n":"מימרן, אברהם ממכנאס","f":"יוסף","dt":"תפג - טו טבת","b":"נגיד ויועץ המלך במכנאס-שנות ה-ת' על מקום אביו וקרובו ר מימון מימרן על מקומו אחריו."},{"i":30548,"n":"מימרן, אברהם מצפת","f":"יצחק","b":"מחכמי צפת, חתם-תקכג על אגרת שליחות ר אשר קוריאט, בשנת תקכז על אגרת שליחות ר ישראל בנבנשתי ועוד. בשנת תקלא שליח צפת לערי אשכנז, בהיותו בפרג פגש את ר יחזקאל לנדא בעל \"נודע ביהודה\"."},{"i":30549,"n":"מימרן, אפרים מסאלי-מרוקו","b":"רב בסאלי"},{"i":30550,"n":"מימרן, ברוך ממכנאס","b":"מחכמי מכנאס-שנות ה-תק'. אחיהם של ר דניאל ור שלמה."},{"i":30551,"n":"מימרן, דוד מטבריה","b":"רב בטבריה, בשליחות בארצות ערב-תקן."},{"i":30552,"n":"מימרן, דניאל ממכנאס","f":"אברהם","b":"מחכמי מכנאס-שנות ה-תק'. אחיו של ר שלמה."},{"i":30553,"n":"מימרן, חיים ממכנאס","f":"משה","k":"בעל פרי עץ חיים","bt":"תקכה","bp":"מכנאס","dt":"תקמה-ו - ה תשרי","b":"נכד(-אבי אמו) ר יעקב טולדנו. מחכמי מרוקו, חיבר גם \"החפץ חיים\", ועוד - כ-20 חבורים. נפטר בגיל 20 בחיי אביו."},{"i":30554,"n":"מימרן, חיים ממכנאס","dt":"תפו - אחרי","b":"מחכמי מכנאס-שנות ה-ת'. בנו - הנגד ר אברהם."},{"i":30555,"n":"מימרן, יוסף חיים מקולירא-מרוקו","f":"ישראל","bt":"תריג - בערך","dt":"תרלח","dp":"קולירא-מרוקו","b":"מחכמי קולירא-מרוקו, נפטר צעיר."},{"i":30556,"n":"מימרן, יוסף ממכנאס","b":"נגיד במכנאס ויועץ המלך מולאי ישמעאל-שנות ה-ת', ובנו ר אברהם על מקומו אחריו, ואחריו ר מימון מימרן (קרובו ואולי אחיו) על מקומו אחריו. אחיו - ר שמעיה, בנו גם ר שמואל."},{"i":30557,"n":"מימרן, יוסף מפאס","b":"מחכמי פאס-שנות ה-תק' והתפרנס ממלאכתו. בנו - ר ישראל."},{"i":30558,"n":"מימרן, יצחק ממכנאס","b":"מחכמי מכנאס - שנות ה-תק', נספד מאת ר שאול ישועה אביטבול."},{"i":30559,"n":"מימרן, יצחק ממכנאס","f":"שמואל בן יוסף","dt":"תפח - כג כסלו","dp":"מכנאס","b":"גביר מחכמי מכנאס. נהרג ע\"י שודדים ערבים."},{"i":30560,"n":"מימרן, ישראל מפאס","dt":"תרלג - ד ניסן","b":"מחכמי פאס-מרוקו, בזמן ר יהודה ן עטר. בניו: ר רפאל, ר יונתן - נהרגו עק\"ה."},{"i":30561,"n":"מימרן, מאיר מירושלים","b":"מחכמי א\"י. בשליחות קהילת ירושלים בפאס-שסג עם ר שלמה בן חגי, בשליחות צפת באלגיר-שסה."},{"i":30562,"n":"מימרן, מאיר ממכנאס","b":"מחכמי מכנאס-שנות ה-ת', נציג הקהלה בפני השלטונות."},{"i":30563,"n":"מימרן, מימון ממכנאס","b":"נגיד במכנאס על מקום קרובו ר אברהם בן יוסף מימרן, מראשי השבתאים במרוקו יחד עם ר יעקב ן סעדון."},{"i":30564,"n":"מימרן, משה ממכנאס","f":"אברהם","bt":"תצט","bp":"מכנאס","dt":"תקמו - ז אב","b":"רב וראש ישיבה במכנאס. מצאצאי ר שמעיה מאימראן ממגורשי קשטיליה שעבר למכנאס. נכד ר יעקב טולדנו=מהרי\"ט ממכנאס. תלמיד ר שלמה טולדנו, וזקנו המהרי\"ט. חתן דודו ר משה טולדנו ממכנאס (לדעת טולדנו-נר המערב היה חתן ר יעקב טולדנו). בניו - ר חיים, ר יעקב ור אליעזר שנפטרו צעירים. מתלמידיו - ר חביב טולדנו, ר יהודה טולדנו, ר יחיא בן זנו, ר יצחק אצבאג ועוד. חיבר שיטות וחדושים ושו\"ת - רובם בכת\"י."},{"i":30565,"n":"מימרן, משה ממכנאס","b":"מחכמי מכנאס-שנות ה-תק'."},{"i":30566,"n":"מימרן, שלמה ממכנאס","f":"שמעיה","dt":"תסד","b":"מראשי קהלת מכנאס. כנראה נהרג."},{"i":30567,"n":"מימרן, שלמה ממכנאס-מרוקו","k":"בעל שפת אמת","bt":"תקכד","dt":"תקצג","b":"רב במכנאס-תקסד. תלמיד וחתן אחיו ר משה. חתם על הסכמה עם חכמי מכנאס. חיבר חדושי התלמוד, דרשות, ופירוש לחומש. נינו ר משה בהלול מטבריה - נפטר תרמג."},{"i":30568,"n":"מימרן, שמואל ממכנאס","f":"יוסף הנגיד","b":"מחכמי מכנאס-שנות ה-ת'. מכתב אליו מר שמואל הצרפתי. נאסר ע\"י השלטונות. אחיו - הנגיד ר אברהם מימרן. בנו - ר יצחק נהרג עק\"ה."},{"i":30569,"n":"מימרן, שמואל ממכנאס","f":"יעקב","b":"גביר מחכמי מכנאס-שנות ה-ת',"},{"i":30570,"n":"מימרן, שמואל ממרוקו וירושלים","b":"עלה ממרוקו, רב בירושלים-תקמה. הסכים על \"דרך ישרה\"-תקמח לר ראובן בן אברהם."},{"i":30571,"n":"מימרן, שמעיה ממכנאס","b":"נגיד במכנאס על מקום קרובו (או אחיו) ר יוסף מימרן. בניו - ר שלמה ור אברהם. חתנו - ר חביב בן חיים טולדנו ממכנאס."},{"i":30572,"n":"מימרן, שמעיה מספרד ומרוקו","b":"מחכמי ספרד, אחר הגירוש הגיע למכנאס-מרוקו והקים ישיבה. מצאצאיו רבנים במרוקו במשך הדורות. חתנו - ר חביב טולדנו."},{"i":30573,"n":"מינדא, אברהם","b":"דיין במצרים-תל\"א"},{"i":30574,"n":"מינדא, יהודה יצחק מאדרינופול","b":"רב באדרינופול-תקס."},{"i":30575,"n":"מינדא, יהודה מפאס","f":"בנימין","b":"מחכמי פאס-שנות ה-ת'."},{"i":30576,"n":"מינדא, יהודה מפאס - א","f":"משה","b":"מחכמי פאס, חתם על פס\"ד-שד עם ר נחמן סנובאל, ר אברהם חאגיז, ור יהושע קורקוס, ור יצחק בן יוסף נהון."},{"i":30577,"n":"מינדא, יוסף מפאס","f":"משה","dt":"שה - אחרי","dp":"פאס?","b":"תלמיד ר משה חלאווה מספרד ופאס. רב בפאס, חתם על התקנות-שה."},{"i":30578,"n":"מינדא, משה מפאס","b":"רב בפאס-שנות ה-ר'. בנו - ר יהודה."},{"i":30579,"n":"מינדולה, שמואל מאיטליה","b":"רב באיטליה, נשא ונתן עם ר שמואל אבוהב ב\"דבר שמואל\"."},{"i":30580,"n":"מינדיס די סולא, שמואל מקורסאו","k":"בעל סדר תפלות לשאלת","bt":"תנט","bp":"ליסבון-פורטוגל","dt":"תקכא - ב סיון","dp":"קורסאו","b":"בן למשפחת אנוסים, הגיע עם הוריו בילדותו לאמשטרדם, תלמיד ישיבת \"עץ חיים\", ור שלמה אאיליון. רב בקורסאו-תקה. בנו ר יצחק, וחתנו ר יעקב ופיס די פונסיקא מקורסאו. דרשה שדרש בקורסאו-תקי על כריתות ברית שלום של הממשלה - אמשטרדם תקיז. חיבר סדר תפילות לשאלת מטר - אמשטרדם תקלה."},{"i":30581,"n":"מינדיס טשומאסירו, אהרן מאמשטרד","b":"מחכמי אמשטרדם, תלמיד ישיבת \"עץ חיים\" באמשטרדם. רב בקורסאו-אמריקה - תקפח, ובבית דינו כיהנו ר בנימין ח' ב' די קאסערעס, ור משה לופיס פינייא."},{"i":30582,"n":"מינדיס לושינה, דניאל משלוניקי","dt":"תץ","dp":"שלוניקי","b":"רופא בשלוניקי, ותרם להכנסת כלה."},{"i":30583,"n":"מינדיס, יוסף מירושלים","dt":"תרטז - ב שבט","dp":"ירושלים","b":"מחכמי ירושלים. חתם ב\"ספר חיים וחסד\" לר חיים אבולעפיה בענין היתר עגונה (בזמן הרעש)."},{"i":30584,"n":"מינדיס, יצחק מאגאדיר-מרוקו","b":"מחכמי אגאדיר-מרוקו - שנות ה-ת', נזכר אצל היעב\"ץ. חתנו - ר כליפא בן מלכא מאגאדיר וירושלים."},{"i":30585,"n":"מינדיס-נשיא","k":"משפחה","b":"משפחת אנוסים בפורטוגל, שמבניה עברו לתורכיה."},{"i":30586,"n":"מינדלין, שניאור זלמן","b":"תלמיד ישיבת חב\"ד. פרסם מאמרים ב\"התמים\" - וארשא תרצה - קובץ חסידי חב\"ד."},{"i":30587,"n":"מינדליש, יצחק מלמברג","b":"מחכמי למברג."},{"i":30588,"n":"מינדן, יוסף יוזפא מברלין","b":"מראשי הקהילה בברלין, חתם על כתב הרבנות של ר צבי הירש מלונדון וברלין-תקלב."},{"i":30589,"n":"מינדן, ליב כתריאל מהמבורג","b":"אחיהם של ר סנדר, ר כתריאל טרויב מקידאן, לאחר שנפטר-תקנח בערך העביר אחיו ר סנדר העביר את חלקו בירושה לאחייניו ר יצחק איזיק טרויב מקידאן בעל יקרא דשכבי ואחיו ר שלמה זלמן מקידאן."},{"i":30590,"n":"מינדן, מאיר מברלין","b":"מראשי הקהילה בברלין, חתם על כתב הרבנות של ר צבי הירש מלונדון וברלין."},{"i":30591,"n":"מינדן, מרדכי גומפל מברלין","b":"מראשי הקהילה בברלין, חתם על כתב הרבנות של ר צבי הירש מלונדון וברלין-תקלב."},{"i":30592,"n":"מינדן, משה מברלין","b":"מראשי הקהילה בברלין, חתם על כתב הרבנות של ר צבי הירש מלונדון וברלין-תקלב."},{"i":30593,"n":"מינדס ליפשיץ","k":"ראה: ליפשיץ מינדס","b":"מגדולי רבני ירושלים-תקמ\"ב"},{"i":30594,"n":"מינדס, יוסף מפאס","b":"מחכמי פאס, חתם על התקנות בפאס-שה."},{"i":30595,"n":"מינור, יוסף (אוסיפ)","f":"שלמה זלקינד","bt":"1861","bp":"וילנא","b":"אביו היה רב מטעם בוילנא. הצטרף לתנועה המהפכנית ונאסר-1883, שוחרר ונאסר וגלה בחו\"ל כמה פעמים. עורך בטאון המפלגה \"טרוד\"-1917. יצא לחו\"ל וניהל את \"הצלב האדום\" הפוליטי לעזרת נפגעי המשטר הקומוניסטי."},{"i":30596,"n":"מינור, שלמה זלקינד מוילנא","f":"1827","bt":"1827","bp":"וילנא","dt":"1900","dp":"וילנא","b":"תלמיד ומורה בביהמ\"ד לרבנים בוילנא, רב מטעם במינסק-1858, מוסקבה-1869 והקים שם קהלה עם ביכ\"נ ומוסדות חסד ור יעקב מזא\"ה על מקומו אחריו. הדריך את ל. טולסטוי בתנ\"ך ובעברית. פרסם מאמרים וחוברות נגד האנטישמיות. גורש ממוסקבה בגלל התערבותו לטובת בני קהילתו ועבר לוילנא. בניו: יוסף המהפכן, לזר שהיה פרופ' לנוירולוגיה במוסקבה."},{"i":30597,"n":"מיניקס, חנן יעקב","bt":"1867","bp":"וילנא","dt":"1932","dp":"ניו יורק","b":"תלמיד ישיבת וולוזין. עבר לגרמניה והתקרב לר עזריאל הילדסהימר ור ישראל סלנטר. ממיסדי \"אהבת ציון\". פרסם מאמרים ב\"השחר\". היגר לארה\"ב-1888 והיה שם מורה עברי, פרסם מאמרים בשם \"מיניקעס יום טוב בלעטער\" שזכו לתפוצה רבה, ועוד."},{"i":30598,"n":"מינסטר, אהרן מברלין","f":"וולף","b":"מראשי הקהילה בברלין, חתם על כתב הרבנות של ר צבי הירש מלונדון וברלין-תקלב."},{"i":30599,"n":"מינסטר, וולף מברלין","b":"מראשי הקהילה בברלין, חתם על כתב הרבנות של ר צבי הירש מלונדון וברלין-תקלב."},{"i":30600,"n":"מינסטר, משה בנדט מסלובודקה","dt":"תשג","b":"מרביץ תורה בסלובודקה. פרסם מאמרים ב\"כנסת ישראל\" - סלובודקה-ויליאמפולי תרצח - כתב עת תלמידי \"כנסת ישראל\" בסלובודקה."},{"i":30601,"n":"מינץ בנימין","bt":"1903","dt":"ה'תשכא 1961","bk":[["מאיר באהבה",""]]},{"i":30602,"n":"מינץ יהודה בן אליעזר","f":"אליעזר הלוי","bt":"קסה","bp":"מיינץ?","dt":"רסח-ט","dp":"פדובה","b":"רב בפדובה קרוב ליובל שנים ובנו ר אברהם על מקומו אחריו. מגדולי ישראל בדורו. היה נכבד גם בעיני הגויים - שחקקו צלם תבניתו ונמצא באוניברסיטה בפדובה. נקבר לצדו דון יצחק אברבנאל שנפטר חמשה ימים אחריו. ובמלחמה בשנת רסט - נהרס בית העלמין הישן של פדובה.","bk":[["פסקים ושאלות תשובות הרב יהודה מינץ והרב מאיר מפדוואה",""],["שאלות ותשובות רבי יהודה מינץ",""]]},{"i":30603,"n":"מינץ, אברהם הירש מארה\"ב","f":"מנחם מנדל","bp":"ראזינאי-פלך הורדנא","dt":"תרס - ה כסלו","b":"נכד ר שלמה מינץ מסלונים, היגר לניו יורק אל בניו בזקנותו."},{"i":30604,"n":"מינץ, אברהם הלוי מפדובה -אבי\"ח","f":"יהודה","k":"בעל סדר גיטין וחליצה","dt":"רפג-רצ -כג סיון","b":"רב בפדובה-רסט על מקום אביו. בנו ר יוסף הלוי, וחתנו מהר\"ם פדובה. חתם שמו אבי\"ה (אברהם בן יהודה הלוי). היה במחלוקת עם כמה מגדולי דורו ובהם ר יעקב מרגליות שהחרימו (עוד בחיי אביו), והיה מחלוקת-רעח בינו לבין ר יעקב פולק מפולין ור אברהם הכהן מבולוניה וכמה מרבני ונציה, ומתומכיו היו דודו ר לימא פיררה, ר עזריאל מסביוניטה ועוד. לימים הזכירו הרמ\"א שהיה תלמיד תלמידו של ר יעקב פולק - בכבוד."},{"i":30605,"n":"מינץ, אברהם יוסף","f":"שמעון וולף","k":"בעל ראשית למודים","b":"חיבר ספר מדעי המבוסס על אוקלידס - ברלין תקלה."},{"i":30606,"n":"מינץ, אברהם ליב מפוסוואל","f":"שלמה מקוברין","dt":"תרכט","b":"חתן ר יחיאל מיכל מפאסוואל(=פוסוואל) (לפי אווצינסקי-קורלנד היה חתן הגביר ר ישכר בר בן מאיר מפוסוואל - מחותנו של ר אבלי פוסוואלר מוילנא). רב בפוסוואל. אחיו - ר נתן נטע מטיקטין, ר יצחק צבי מוארשא, ר מנחם מראזינאי. חתניו: ר משה זלמן ראבקין(=ריבקין) מפוניבז, ר חיים ברוידא מפוניבז."},{"i":30607,"n":"מינץ, אהרן (ארוש)","f":"זאב וולף בן נחום","dt":"תקצג - יח סיון","dp":"מזריטש","b":"חתן הגביר ר דוד לידא בן ר פתחיה מולאדאווע בעל \"יד כל בו\". גביר בעל חסד מחכמי מזריטש. נספד ב\"אבל יחיד\" לר בריש פלאהם. בנו ר הרש קלצקי מוילנא."},{"i":30608,"n":"מינץ, אליהו אהרן מגריווא","f":"אריה ליב","dt":"תרלח - כח שבט","b":"רב בגראייעווא(=גריווא)-תרט על מקום ר חיים דוד זליגמן."},{"i":30609,"n":"מינץ, אליעזר משלוניקי","f":"משה","dt":"שד","b":"נכד ר משה מינץ מאשכנז. רב בשלוניקי."},{"i":30610,"n":"מינץ, אלכסנדר זיסקינד מברוד","f":"אהרן ארוש","k":"בעל פרי עץ הדר","bt":"תקן","bp":"טיקטין","dt":"תרי","b":"מחכמי ברודי - סוחר אתרוגים וידידו של שד\"ל. חיבר \"פרי עץ הדר\" למברג תרו. ?? לא באוצר ??"},{"i":30611,"n":"מינץ, אלכסנדר זיסקינד מברוד","f":"אלעזר","b":"מחכמי ברודי."},{"i":30612,"n":"מינץ, אלעזר מאושפיצין","f":"אריה ליב","bt":"תקצז","bp":"טרנוב","dt":"תרפא","b":"בעל תואר דוקטור מאוניברסיטת וינה. חתן ר חנוך הניך קליננמן מטרנוב. רב באושפיצין (מחלוקות בעיר עם החסידים שהביאו רב אחר), קמפנא-תרלה (על מקום המלבים). חיבר תורת הנשים בגרמנית, \"גט מסודר\" בילוגריא תרצב. פרסם מאמרים ב\"וילקט יוסף\" - מונקטש-פאקש-בוניהאד תרנט-תרעז."},{"i":30613,"n":"מינץ, אריה ליב","f":"אלעזר לעוו -שמן רוקח","b":"חתן ר טוביה הכהן בלוך."},{"i":30614,"n":"מינץ, בנימין זאב מגלייויץ","f":"אלעזר","bt":"תרכא","b":"נכד בעל \"שמן רוקח\". רב ודרשן בגלייוויץ-גרמניה."},{"i":30615,"n":"מינץ, בנימין מנ\"י","b":"פרסם מאמרים ב\"אור המאיר\" - נ\"י תשח, \"היהודי\" - נ\"י תרצו."},{"i":30616,"n":"מינץ, דוד הלוי משלוניקי","dt":"שפ - יח כסלו","dp":"שלוניקי","b":"מחכמי האשכנזים בשלוניקי, ר\"מ בחברת ת\"ת בשלוניקי."},{"i":30617,"n":"מינץ, הלל הלוי מלייפניק","f":"יהושע","b":"חתן ר אברהם מקראקא ולייפניק. רב בלייפניק, ר\"מ במנהיים-תמ."},{"i":30618,"n":"מינץ, יהודה משלוניקי","f":"יהודה","dt":"שט - יז כסלו","dp":"שלוניקי","b":"מחכמי שלוניקי. נפטר צעיר."},{"i":30619,"n":"מינץ, יהודה משלוניקי","f":"אברהם","dt":"שלג - יז ניסן","dp":"שלוניקי","b":"מחכמי שלוניקי, אולי נכד מהר\"י מינץ."},{"i":30620,"n":"מינץ, יהושע מסטרי","f":"מנחם נחום מביאליסטוק","bt":"תקעט","bp":"מזריטש","dt":"תרמט","b":"חתן ר השל רבה של סטרי. רב בסטרי."},{"i":30621,"n":"מינץ, יוסף יוחנן (יצחק) מטאב","f":"משה - מהר\"ם מינץ","b":"רב בטאב-תקף ור יוחנן שפיץ על מקומו אחריו-תקצז, פאפא-תקצח. הו\"ל ספר אביו \"שו\"ת מהר\"ם מינץ\"."},{"i":30622,"n":"מינץ, יוסף מאוסטרוב","b":"פרסם מאמרים ב\"קול תורה\" - וארשא תרסח."},{"i":30623,"n":"מינץ, יצחק מברנט","f":"אלעזר מאושפיצין","b":"תלמיד ביהמ\"ד בברלין-תרמג. רב בברנט-פרוסיה. חיבר ספרים בפילוסופיה והסטוריה. אחיו הרופא פנחס מקמפן למד עמו."},{"i":30624,"n":"מינץ, יצחק צבי מורשה","f":"שלמה מינץ","dt":"תרלב - י אד\"א","b":"רב בוורשה"},{"i":30625,"n":"מינץ, ליב מפפד\"מ","b":"מראשי קהילת פפד\"מ-תפ בערך."},{"i":30626,"n":"מינץ, ליב מפפד\"מ","f":"הרץ","b":"מוהל בפפד\"מ-תקנז עד תרח. בנו - ר משה - מוהל גם הוא."},{"i":30627,"n":"מינץ, מאיר מארה\"ב","b":"פרסם מאמרים ב\"התבונה\" - נ\"י תשז - קובץ תלמידי ישיבת מיר."},{"i":30628,"n":"מינץ, מאיר מלמברג","f":"אלכסנדר זיסקינד","k":"בעל איין וארט צור צי","bt":"תקעה","dt":"תרכו - כד אייר","dp":"לבוב","b":"נכדו של ר אהרן ארוש. חתן ר אפרים פישל ירחמיאל מייזיש מלמברג. מחכמי למברג (דובר שבע שפות) עסק במסחר. חיבר בגרמנית \"דבר בעתו\" תרח (להגן על זכויות היהודים), וחוברת בגרמנית נגד האנטישמי פאווליאקווסקי-תרך."},{"i":30629,"n":"מינץ, מרדכי מרישא","b":"מחכמי רישא - ממשתתפי \"אהל מועד\"."},{"i":30630,"n":"מינץ, משה מברוד ואויבן","f":"יהודה","k":"בעל דברי הבית","r":"אב\"ד אובן ישן","bt":"תקי","bp":"מינקוביץ","dt":"תקצא - ו אלול","b":"תלמיד ר משלם איגרא בטיסמניץ. חתן ר יוסף הלוי מברודי וגאלינא. ר\"מ בברודי, רב בוישנוביץ, רדיויל(=ראדויל), אויבן ישן (בודפשט) והקים שם ישיבה. הכריח את אהרן חורין לחזור בו מדעותיו הכוזבות. (מחותנו של החתם סופר). מונה כרב ראשי של מחוז פשט - המעמד הגבוה ביותר שזכה לו רב בהונגריה (הוסמך להכריע בענינים שהיו עד אז בסמכותו של בעל האחוזה בלבד). חיבר \"דברי הבית\" וינה תקפב, \"מהר\"ם מינץ\" פרג תקפז, \"אבל כבד\" - אופען תקפו - הספד על ר ישראל ורמן מבודפשט, ועוד. בנו ר יוסף יצחק (יוחנן) - אב\"ד פאפא, ר יעקב-נהרג עק\"ה, חתנו - ר יהודה צבי גינז-אחיינו של ר עקיבא איגר.","bk":[["מהר\"ם מינץ (החדש) [שו\"ת]",""],["דביר הבית - דרשה לחנוכת בית תפילה",""],["מהר\"ם מינץ אפי זוטרי – שו\"ת –",""]]},{"i":30631,"n":"מינץ, משה מפפד\"מ","f":"ליב","b":"מוהל בפפד\"מ-תקף עד תרמד."},{"i":30632,"n":"מינץ, משה סגל מוירצבורג","k":"בעל שו\"ת מהרם מינץ","bt":"קפ","b":"פוסק הדור,רב בוירצבורג-רי\"ב,מיינץ-רי\"ז,לנדוי,אולם-רכ\"ד,במברג-רכ\"ט,נירנברג-רל\"ג,פוזן-רל\"ד"},{"i":30633,"n":"מינץ, נטע מטיקטין","f":"שלמה מינץ","b":"רב בטיקטין-תר\"ל"},{"i":30634,"n":"מינץ, שלמה הלוי מוילנא והמבורג","f":"צבי הירש","dt":"תלא - א תמוז","dp":"אלטונא","b":"מגדולי חכמי וילנא, עבר להמבורג בגזירות תח, דיין באלטונא."},{"i":30635,"n":"מינץ, שלמה הלוי מונציה","b":"מגדולי רבני ויניציאה-תק\"י"},{"i":30636,"n":"מינץ, שלמה הלוי משלוניקי","dt":"תכב","dp":"שלוניקי","b":"רב בשלוניקי."},{"i":30637,"n":"מינץ, שלמה מקוברין","f":"אברהם בן אהרן","b":"רב בקוברין, וילקומיר, סלונים-תקצ. בניו - ר אברהם ליב מפאסוואל, ר נתן נטע מטיקטין, ר יצחק צבי איזיק הירש מוארשא, ר מאיר מנחם מנדל מראזינאי."},{"i":30638,"n":"מינץ, שמעון","f":"שמואל אהרן","b":"נכד ר אריה ליב בנו של ר אלעזר לעוו-מינץ בעל שמן רוקח והו\"ל ספר זקנו - קראקא תרסב, עם אחיו - ר אברהם."},{"i":30639,"n":"מינצברג, אברהם אליעזר מיוזפוף","f":"שלמה","dt":"תרסד - ד שבט","dp":"ירושלים","b":"היה רבן של הקהלות טשפלוב(=טשאפלא), יוזפוף, היה חתנו של ר יצחק דוד בן ר משה מללוב, עלה לירושלים-אחרי תריא בעקבות חותנו. בניו: ר ישראל זאב מינצברג ראב\"ד בירושלים, ר ירחמיאל ישעיה מליקווא, ר משה צבי."},{"i":30640,"n":"מינצברג, אפרים צבי מברטש","b":"רב בבירטש(=ברטש)-תרעו, ליסקווה-תרעט, ניו יורק-תרפג."},{"i":30641,"n":"מינצברג, דוד מלובלין","dt":"תשג","b":"רב בלובלין"},{"i":30642,"n":"מינצברג, חיים דובער מדולהנוב","b":"רב בדולהנוב, בזמן השואה הגיע לשנחאי, חתם על מכתב-תשא לר ראובן כץ עם כמה רבנים."},{"i":30643,"n":"מינצברג, יוסף יהודה לי מקוזניץ","b":"פרסם מאמרים ב\"קובץ דרושים\" - פיעטרקוב תרפג."},{"i":30644,"n":"מינצברג, ירחמיאל ישעיה מליקווא","b":"נכד ר יצחק דוד בידרמן ממשפחת אדמורי ללוב. רב בלוקבה-תרס, זדונסקה-וואלה(=זדינסקאוואלי)-תרע. פרסם מאמרים ב\"רשפי אש\" - לודז תרפז, \"שערי תורה\" - וארשא תרסג. גיסו(-נשוי לאחות אשתו) - ר חיים יעקב ישראל ברגר."},{"i":30645,"n":"מינצברג, ישראל זאב מירושלים","f":"משה צבי","k":"בעל זאת חוקת התורה","r":"אב\"ד חסידים ירושלים","bt":"תרלב","bp":"פולין","dt":"תשכב - יז אד\"ב","b":"נינו של ר יצחק דוד בידרמן ור משה האדמור מללוב, ונכד ה\"יהודי הקדוש\" מפשיסחא. ראב\"ד בביה\"ד החסידי בירושלים-תרף. מראשי ישיבת \"חיי עולם\" בירושלים. פרסם מאמרים ב\"הדביר\" - ירושלים תרעט, פרסם מאמרים ב\"כרם ציון\" - ירושלים תרצה-תשכג - קובץ \"מדרש בני ציון\", \"תבונה\" - ירושלים תשא, \"אהל תורה\" - ירושלים תרפו.","bk":[["זאת חוקת התורה – בחירת נשים",""],["ישוב ארץ ישראל",""],["פירות שביעית",""],["שארית ישראל – שו\"ת",""]]},{"i":30646,"n":"מינצברג, משה צבי","f":"אברהם אליעזר מיוזפוף","b":"נכד ר יצחק דוד בידרמן ממשפחת אדמורי ללוב. בנו ר ישראל זאב דיין בירושלים."},{"i":30647,"n":"מינצברג, פנחס מנחם ישעיה מירוש","k":"בעל מרגניתא דר מאיר","b":"תלמיד ישיבת \"אור תורה\" בטבריה. גיסו ר אשר זאב ורנר מארה\"ב סייע לו בהוצאת ספרו."},{"i":30648,"n":"מינצילופי, י ר יהושע מליוורנו","b":"רב בליוורנו-ת\"ק"},{"i":30649,"n":"מינצנט, שלמה זלמן ממארגרטן","dt":"תרכט - ז טבת","b":"תלמיד החת\"ס. רב במארגרטן-תקפה, עבר למיהאי-פאלווא."},{"i":30650,"n":"מינצר, יצחק","b":"פרסם מאמרים ב\"הנצנים\" - תל אביב תשא - קובץ תלמידי ישיבת הישוב החדש בת\"א."},{"i":30651,"n":"מינצרג, יצחק דוד","dt":"תשב - כא אלול","b":"ר\"מ בישיבת חכמי לובלין"},{"i":30652,"n":"מינקובסקי, אברהם מארה\"ב","b":"חזן ומנגן בדטרויט. אחיו - החזן פנחס מינקובסקי."},{"i":30653,"n":"מינקובסקי, אברהם מירושלים","dt":"תרכו","dp":"ירושלים","b":"בנו של ר יצחק בעל \"קרן אורה\", על עם משפחתו לירושלים בשנת תרכד והיה ש\"ץ בבית הכנסת של הגאון מקוטנא"},{"i":30654,"n":"מינקובסקי, יצחק","f":"משה שלום","k":"בעל האהבה והקנאה"},{"i":30655,"n":"מינקובסקי, מרדכי משדה לבן","b":"חזן בשדה לבן. אביו של ר פנחס - החזן מאודסה."},{"i":30656,"n":"מינקובסקי, פנחס מאודסה","f":"מרדכי","bt":"תריט","b":"למד חזנות אצל ר ניסן ספיווקובסקי (בלעזער), ור ניסן בלומנטל מאודסה, והפרופ' ויקטור רקיסונסקי. מגדולי החזנים, חזן בקישינוב, חרסון, אודסה, ניו יורק, שוב באודסה על מקום ר ניסן בלומנטל. פרסם מאמרים ב\"המגיד\", \"המליץ\", ועוד. חיבר ספר בגרמנית ונדפס ועוד חיבורים בכת\"י. אחיו - החזן אברהם מדטרויט."},{"i":30657,"n":"מינקובסקי, קלמן מקיעלץ","b":"פרסם מאמרים ב\"התמים\" - וארשא תרצה - קובץ חסידי חב\"ד."},{"i":30658,"n":"מיסקין, אברהם","dt":"תרצב","b":"רב במוש"},{"i":30659,"n":"מיערגן, שמואל בר\"ל משטמפן","b":"מחכמי שטמפן, חתם-תקעו על כתב רבנות ר מרדכי בנט."},{"i":30660,"n":"מיץ, משה","f":"מאיר","b":"תלמיד יש\"ר מקנדיא. תשובה ממנו בספר אילם. הגיע לוילנא עם רבו-שפא."},{"i":30661,"n":"מיץ, שלמה זלמן משטמפן","f":"משה","k":"לוונשטין","bt":"תקכב","bp":"מיץ","dt":"תריא - כד סיון","dp":"שטמפן","b":"תלמיד בישיבת פרג-תקמא, חתן משפחת גיירינג משטמפן. מוהל, מראשי קהלת שטמפן-תקנה. כתב פנקס מילה, כתב את קורות הקהלה בזמן מלחמת נפוליאון. חתם-תקעו על כתב רבנות ר מרדכי בנט."},{"i":30662,"n":"מיצברג, ישראל צבי מירושלים","b":"פרסם מאמרים ב\"קול תורה\" - ירושלים תרץ."},{"i":30663,"n":"מיצל, שמחה ממנוסטרישט","b":"מחכמי נוסטרישטש-תרן."},{"i":30664,"n":"מיצקון, דוד משה","f":"קלונימוס קלמן","k":"בעל כנור דוד","bt":"1836","bp":"וילנא","dt":"1887","dp":"וילנא","b":"ממשפחת גינצבורג והשם מיצקון - בית מלון ליד וילנא ששייך למשפחה. חתן ר מרדכי גינצבורג. בקי בשפות. משורר עברי. פרסם בכתבי עת שונים. ספרו נתקבל בביקורת חריפה ע\"י קובנר ופפירנא ב\"בכורים\" - חוברת ב'."},{"i":30665,"n":"מיקליש יוסף בן יששכר","bt":"1580","dt":"ה'תיד 1654","bk":[["יוסף דעת ח\"א",""]]},{"i":30666,"n":"מיקלישונסקי, אבא חיים מוארשא","b":"פרסם מאמרים ב\"כנסת חכמי ישראל\" - אודסה-פיעטרקוב-ברדיטשוב תרנג-תרס, \"תורה מציון\" - ירושלים תרנה-תרסה."},{"i":30667,"n":"מיר, אהרן מרודוס","b":"פרנס קהלת רודוס-ש'."},{"i":30668,"n":"מיראנדה, אברהם משלוניקי","b":"מבני הקהלה האיטלקית בשלוניקי-תקד וחתם אז על הסכם בין האיטלקים לבין בני קהלת שלוניקי בענין הסדרת המס."},{"i":30669,"n":"מיראנדה, חיים אברהם","f":"שמואל","k":"בעל יד נאמן","b":"מחכמי שלוניקי-שנות ה-תק', מקובל, חיבר גם \"רוח נאמן\", \"דקדוקי חברים\", ועוד."},{"i":30670,"n":"מירויס, אריה מרדכי מראדין","f":"נחום יצחק","k":"בעל מאור הבנים","bt":"תריט","dt":"תרצד - ו אייר","b":"רב בראדין-פלך וילנא-תרנד. חיבר גם \"אומר ודברים\", \"ספר החיים\" - בכת\"י."},{"i":30671,"n":"מירויס, מרדכי","b":"פרסם מאמרים ב\"כנסת ישראל\" - וילנא תרץ."},{"i":30672,"n":"מירויס, משה חיים מקייפטאון","bt":"תרלא","b":"רב בקיפטאון-דרום אפריקה-תרסט. פרסם מאמרים ב\"שערי ציון\" - ירושלים תרפא."},{"i":30673,"n":"מיריינא, ישראל מקופאריד","f":"מיכאל מקאפרד","b":"חתן ר יעקב סופר מילטושקוב. רב בקופאריד(=קאפרד)-פודוליה-תרע על מקום אביו. פרסם מאמרים ב\"אסיפת חכמים\" - אטיניא תרע."},{"i":30674,"n":"מיריינא, מיכאל מקופאריד","f":"ישעיה","bt":"תרכ","b":"רב בשאטובה-תרמב, קופורד(=קופאריד, קאפרד)-פודוליה. פרסם מאמרים ב\"אסיפת חכמים\" - אטוניא תרע. חיבר שו\"ת - בכת\"י. בנו - ר ישראל, חתנו - ר מרדכי שרייבמן מבירזולא."},{"i":30675,"n":"מיריס, ראובן חיים ממצרים","b":"גביר במצרים-שנות ה-תק'. סייע לר ידידיה שלמה ישראל בהדפסת ספרי אביו. חתנו - הגביר ר ישי הכהן."},{"i":30676,"n":"מירלש, אברהם מפוזנא","f":"משלם זלמן מאה\"ו","b":"דיין בפוזנא. בנו - ר משלם זלמן מחסלביץ."},{"i":30677,"n":"מירלש, אהרן","f":"משלם זלמן מאה\"ו","b":"בנו - ר צבי הירש משווערין (ויש דעות אחרות על כך - עיין בערכו)."},{"i":30678,"n":"מירלש, אהרן מחנטשין","f":"צבי הירש מירלס","k":"בעל בית אהרן","b":"רב בחנטשין גליל קראקא, אזרוב, קרבא, וורעשנא-תקפ. חיבר \"בית אהרן\" ובו גם שו\"ת מה\"חכם צבי\" - דודו של המחבר."},{"i":30679,"n":"מירלש, אהרן מניימרק","f":"יעקב קופל מירלס","b":"רב בניימרק"},{"i":30680,"n":"מירלש, אריה ליב","f":"נפתלי הירש מירלס","b":"רב בקארוב תק\"ל"},{"i":30681,"n":"מירלש, אריה ליב מוואלפא","f":"משלם זלמן מאה\"ו","b":"רב בוואלפא-פלך הורדנא-תנא."},{"i":30682,"n":"מירלש, בנימין זאב וולף מברלין","f":"משלם זלמן מאה\"ו","b":"חתן ר נפתלי כץ מאוסטרהא. מדפיס בברלין-תצ. הו\"ל משניות עם פירוש עץ חיים יחד עם אחיו - ר דובער. חתנו - החכם צבי (ובאמת היה גיסו)."},{"i":30683,"n":"מירלש, דב בער","f":"משלם זלמן מאה\"ו","b":"הו\"ל משניות עם פירוש עץ החיים יחד עם אחיו ר זאב וולף מברלין. בנו - ר דוד פוזנר."},{"i":30684,"n":"מירלש, דוד","f":"נפתלי הירש מפולדא","b":"בנו - ר זלמן."},{"i":30685,"n":"מירלש, יעקב דוד ניימרק מוינה","f":"נפתלי הרש מירלש","dt":"תכ-ח - כז שבט","b":"מנכבדי וינה, ולאחר הגירוש מוינה - רב בפרג. בניו: ר משלם זלמן מאה\"ו, ר בנימין מברלין. חתנו ר שמואל זנויל פפערשי-חותנו של ר אברהם ברוידא."},{"i":30686,"n":"מירלש, משה מוינה","b":"פרנס ור\"מ בווינה עד הגירוש-ת\"ל"},{"i":30687,"n":"מירלש, משה מפריישדורף","f":"שלמה זלמן מאלטונא","b":"רב בפריישדורף-תן בערך."},{"i":30688,"n":"מירלש, משה פאלק מארה\"ב","bp":"בייסיגולה","dt":"1952","b":"היגר לארה\"ב-אחרי 1880. פרסם מכתבים ומאמרים ב\"המליץ\", \"פסגה\" של זאב שור, \"הדואר\". מראשוני חובבי ציון בארה\"ב, וממייסדי \"אגודת ציון\" בבולטימור."},{"i":30689,"n":"מירלש, משלם זלמן מוינה ואה\"ו","f":"יעקב דוד ניימרק מוינ","bt":"שפד-ו","dt":"תסו-ז - כב חשון","dp":"אה\"ו","b":"מרביץ תורה, פוסק, בעל חסד. בזיוו\"ש חתן ר נתן פרידלנדר. ממגורשי וינה-תל עם אביו, חתן ר יעקב-אב\"ד וינה. רב במיץ-תל, אה\"ו-תמ, נתקבל לרב בזולקווא ובטיקטין - אולם לא נסע לשם. חתניו: החכם צבי, ר אלחנן ברלינר \"בעל התוספות\" מהורדנא, ר שלום ז\"ק מבירז. מתורתו בספרי חכמי דורו ובהם - שו\"ת \"אבן השהם\", \"חינוך בית יהודה\", ועוד. בניו: ר אברהם מפוזנא, ר וולף מברלין, ר דובער, ר אריה ליב מוואלפא, ר נפתלי הירש ניימרק מברלין, ר משה ניימרק, ר דובער, חתניו: ר צבי אשכנזי-החכם צבי, ר שלום ז\"ק מבירז, ר שמואל זנויל מקראקא, ר אלחנן ברלינר מגרודנא, ר יצחק איזיק גינצבורג. (בחכמי אה\"ו רשום - נפטר בכסלו)"},{"i":30690,"n":"מירלש, משלם זלמן מחסלביץ","f":"אברהם מירלס","b":"רב בחסלביץ-תקל. מצאצאיו - ר יצחק איזיק בכרך."},{"i":30691,"n":"מירלש, צבי הירש מוערשנא","f":"אהרן או ישראל מירקין","k":"בעל מספר צבאם","b":"חתן ר צבי הירש מהילדסהיים. נכד ר זלמן מירלש. גדל בלונדון. רב בוערשנא, שווערן(=שוערין)-פולין - תקמ. חיבר גם \"ארץ צבי\", \"פנות צבאם\"."},{"i":30692,"n":"מירלש, שלמה זלמן מאלטונא","dt":"תמט - אחרי","dp":"אלטונא","b":"הרב הראשון של אה\"ו שנקבר באלטונא. בנו - ר משה מפיירשדורף."},{"i":30693,"n":"מירלש-הלר, יעקב קופל מניימרק","f":"אהרן מולרשטין","b":"רב בניימרק-שפ. בנו - ר נפתלי הירש מפולדא."},{"i":30694,"n":"מירלש-ניימרק","k":"משפחה","b":"משפחת רבנים שמקורם בולרשטין."},{"i":30695,"n":"מירלש-ניימרק, נפתלי הרש מפולדא","f":"יעקב קופל מניימרק","dt":"תט","b":"רב בפולדא. בנו - ר דוד מירלש."},{"i":30696,"n":"מירלש-פרנקל, בנימין","f":"יעקב דוד מירלש","dt":"תנא - כא אדר","b":"אחרי הגירוש מוינה-ת\"ל, בא לברלין. בנו ר נפתלי מברלין אביו של ר דוד פרנקל בעל \"קרבן העדה\". חתנו - ר משה צבי מהורדנא בעל \"תפארת למשה\"."},{"i":30697,"n":"מירסקי, ברוך אברהם מליטא","f":"משה ממיר","k":"בעל שמעתא דרב\"א","bt":"תר","bp":"מיר","dt":"תרעג - יב חשון","dp":"זאטל","b":"ר\"מ בנאסוויז-תרכט על מקום אביו, פרוזובה-תרלג, זאטל-תרנב. מחובבי ציון, ורכש אדמה בגליל התחתון בגבעת ארבל ואיבד את כספו. השתתף במחלוקת בענין השמיטה, ממיסדי \"המזרחי\", מראשוני הרושמים בספר הזהב של קק\"ל, פרש מהתנועה-תרסט. רוב כתביו אבדו.","bk":[["שמעתתא דרב\"א חלק א",""]]},{"i":30698,"n":"מירסקי, יוחנן מסטופצי","f":"מאיר","dt":"תשג","b":"חתן ר צבי זאב רצקר מנאווא-סויציאן. רב בסטופצי-פלך מינסק, זאבלודוב. פרסם מאמרים ב\"בית שמואל\" - וארשא תרצו. נסמך מאת: ר רפאל שפירא מוולוזין, ר חיים עוזר גרודזנסקי, ר יצחק רבינוביץ מפוניבז, ר אליעזר גורדון מטלז."},{"i":30699,"n":"מירסקי, משה","b":"ר\"מ במיר-ת\"ר,נסוויז-תר\"ל"},{"i":30700,"n":"מירסקי, שמואל קלמן מארה\"ב","b":"מורה לתלמוד בביהמ\"ד למורים של ישיבת 'ר יצחק אלחנן' בניו יורק. פרסם מאמרים ב\"הדנו\" - נ\"י תרפה. עורך \"תלפיות\" - נ\"י תשד."},{"i":30701,"n":"מירקדו קרישפין, י'מ","dt":"תרעב - א כסלו","b":"מרבני אזמיר,עלה לירושלים"},{"i":30702,"n":"מירקדו שלום מירושלים","f":"משה בן ששון בן משה","dt":"תרעז - כז אדר","dp":"ירושלים","b":"מגדולי חכמי ורבני ירושלים"},{"i":30703,"n":"מירקדו, דוד מפפד\"מ","b":"מחכמי פפד\"מ-תכח, נזכר אצל ר יעקב ששפורטש שרדף את שבתי רפאל נביאו של שבתי צבי שהגיע לאמשטרדם."},{"i":30704,"n":"מירקדו, חיים אנג'יל","b":"רב פעלים,רב בשאלוניקי-תרכ\"ז"},{"i":30705,"n":"מירקדו, משה ישראל","k":"בעל פירוש לתהלים","dt":"תיב","b":"תלמיד ר שאול מורטירה מאמשטרדם. חיבר פירוש לקהילת ותהלים, ונדפס אחר פטירתו ע\"י ר יעקב מירקדו."},{"i":30706,"n":"מירקדו, סעדיה הלוי","k":"בעל נוה צדק","bt":"1768","b":"רב בתורכיה-תקכח. תלמידו ר אלישע שוחמי.","bk":[["נוה צדק","מפרשי רמב\"ם"]]},{"i":30707,"n":"מירקין, יצחק","f":"שלמה","k":"בעל תולדות החינוך","bt":"1871","bp":"סלנט או שקוד","dt":"1941","dp":"ירושלים","b":"תלמיד ישיבות ליטא. נסמך מאת ר בן ציון קרצמר מסימפרפול. למד באוניבר' בגרמניה. ניהל בי\"ס עברי ריאלי באנטורפן. עלה לארץ-1913 והיה מנהל המוסד ליתומים בפתח תקוה. מורה בביהמ\"ד למורים \"מזרחי\" בירושלים. מכתבי המלצה אליו מר יעקב יפה משקוד, ומר אהרן אליהו הכהן מאקמיאן."},{"i":30708,"n":"מירקין, ישראל ליב מיארצעווע","dt":"תשג","b":"נכד-מצד אמו תומרקין. גביר ביארצעווע-ליד סמולנסק. חתן הגדול ממינסק."},{"i":30709,"n":"מירקין, כתריאל מפולטבה","b":"רב בפולטבה. פרסם מאמרים ב\"אהל יצחק\" סטמר - תרסג - תרעד."},{"i":30710,"n":"מירקין, צבי הירש","f":"ישראל מירקין","b":"רב במנסק-תק\"פ"},{"i":30711,"n":"מירקש, זאב וולף מטיקטין","f":"יהושע מירקש","dt":"תקעד - ד אייר","b":"רב בטיקטין"},{"i":30712,"n":"מירקש, יהודה ליב ממינסק","f":"ישראל מירקש","b":"רב במינסק-ת\"ר"},{"i":30713,"n":"מירקש, יהושע","f":"יהודה ליב מירקש","b":"רב-שנת תק\"כ"},{"i":30714,"n":"מירקש, ישראל ממינסק","f":"יהודה ליב","dt":"תקעג","dp":"מינסק?","b":"רב במינסק-תקלח על מקום ר שמואל הכהן מאמדור. חברו של ר חיים מוולוזין ומתומכי ישיבת וולוזין בזמן הקמתה, והסכימו ביחד על ש\"ס ירושלמי בקאפוסט-תקסח, הסכים על \"עמודי שמים\" - תקס. פעל יחד עם חברו הגביר ר צבי הירש שימחוביץ למפעלי צדקה וחסד ותורה. אחיו - ר שלמה זלמן ממיר בעל \"שלחן שלמה\". לאחר פטירתו החליטו שלא ינתן יותר תואר רב ואב\"ד במינסק אל \"מרא דאתרא\" כי \"מי ידמה לו ומי ראוי להיות ממלא מקומו\" (ויש אומרים סיבה אחרת לכך). חתנו - ר מנחם אליעזר בעל \"יעיר קינו\"."},{"i":30715,"n":"מירקש, מיכאל מדבורץ","f":"ישראל מירקש","b":"רב בדבורץ-תק\"צ"},{"i":30716,"n":"מירקש, סעדיה ישעיה","f":"ישראל מירקש","b":"רב במינסק-תק\"צ"},{"i":30717,"n":"מירקש, שלמה זלמן ממיר","f":"יהודה ליב מירקש","k":"בעל שלחן שלמה","r":"רב ופוסק - רב במיר, קליניגרד","bp":"מיר","dt":"תקלה - כח תשרי","dp":"קליניגרד [קניגסברג]","b":"רב במיר, קניגסברג, פפד\"א-תקל. חיבר גם שרשרות עבותות\", \"דרוש הספד\".","bk":[["שולחן שלמה [קיצוש\"ע או\"ח]",""],["שלחן שלמה",""]],"e":"תקל\"ד [פטירה]","rb":"מיר, קליניגרד","co":{"d":"54.733333,20.483333"}},{"i":30718,"n":"מירקש-מייזליש, יהודה ליב ממיר","f":"שלמה זלמן מייזלש","dt":"תקכג - כג תמוז","b":"מקובל, רב במיר. חתנו - ר יוסף בן בצלאל הכהן מאוסטרהא."},{"i":30719,"n":"מישאל דוסא","b":"מגדולי חכמי דורו-ד'תתקם. חותנו של הרמבם."},{"i":30720,"n":"מישטרלן","b":"מגדולי חכמי אשכנז,מרביץ תורה בנוישטט-ק\"פ"},{"i":30721,"n":"מישימי, זכריה","b":"רב בקושטא-תרכ\"א"},{"i":30722,"n":"מישיני, יצחק מתורכיה","f":"יוסף","b":"מחכמי תורכיה בדור הגירוש מספרד, אחיו של ר ישעיה. חיבר פיוטים במחזור תורכיה (רומניה?)."},{"i":30723,"n":"מישיני, ישעיה ממסינה","f":"יוסף","b":"פייטן מחכמי טורקיה-רמא לפני גירוש ספרד. חתם בפיוטיו בשם \"משוני\". אחיו ר יצחק משוני. סייע לר גדליה ן יחיא מליסבון."},{"i":30724,"n":"מישל, אליעזר סגל מגוליגור","f":"דב בר הלוי","k":"בעל משנת אליעזר","bt":"תרכג","bp":"שצריץ(=שטשרץ)-פלך לבוב","dt":"תש","b":"חתן הגביר ר שמואל מרדכי אונגר מרדיחוב. רב בגוליגור-תרמה, טורקא-תרסו. חיבר \"משנת אליעזר\" דרוהוביטש תרסו, ועוד. פרסם מאמרים ב\"אהל מועד\" - פודגורזע תרנח, \"אוצר החיים\" - זאמושט תרצז, \"ועד חכמים\", \"הכוכב\" - מונקטש-נ\"י תרצה, \"משכנות יעקב\" - דרוהוביטש-בילגוריי תרצב, \"רבותינו שבגולה\" - פרשבורג תרעה. תשובה ממנו ב\"שערי אורה\" - מיהאלביץ תרץ-תרצד. חתנו - ר נפתלי כהנא."},{"i":30725,"n":"מישל, דב בר משצריץ","f":"שמואל הלוי","dt":"תרסט","b":"מחכמי שצריץ. חתן ר יואל רוזמן. בנו היה ר אליעזר מגוליגור."},{"i":30726,"n":"מישל, זאב וולף מקופלונג","f":"צבי אלימלך משצריץ","k":"בעל דברי חכמים","b":"דוקטור לפילוספיה ורב בקומפלונג. חיבר \"דברי חכמים\" קראקא תרסח, ועוד."},{"i":30727,"n":"מישלוב, שלמה חיים","bt":"תרכא","dt":"תרפט - ג כסלו","b":"מו\"צ בקריניק"},{"i":30728,"n":"מישקובסקי, אליהו אליעזר רפאל","f":"חזקיה יוסף","bt":"תרעז","bp":"פולין","dt":"תשמא - כ טבת","b":"נכד(-אבי אמו) ר יצחק בלזר. תלמיד ישיבת גרודנא, כנסת בית יצחק בקמניץ, מיר. עלה לארץ-תשא ולמד בישיבת לומזה בפתח תקוה. חתן ר מרדכי שמואל קרול מכפר חסידים. רב בכפר חסידים וראש ישיבת כנסת חזקיהו מזכרון יעקב שעברה לכפר חסידים - על מקום גיסו - ר נח שימנוביץ. לאחר שחלה נוסף לו השם רפאל..","bk":[["משנת אליהו (ר' א ל'ה)",""],["משנת אליהו – סוכה נדרים",""],["משנת אליהו",""]],"e":"תרע\"ז-תשמ\"א"},{"i":30729,"n":"מישקובסקי, חזקיה יוסף","f":"חיים אריה ליב","bt":"תרמד","dt":"תשו","dp":"צפת","b":"גיסו או חתן ר יצחק בלזר. תלמיד ישיבות ירושלים. בשליחות בליטא-תרעג להזמין לרבנות ירושלים את אחד מרבני ליטא. נשא ונתן עם בעל \"אור שמח\", ר יצחק מפוניבז, ור אליהו מפרוז'אן, ובזמן מלחה\"ע ה-I נתמנה לרב באיווייה, בורנובה, קריניק-תרפב, פעל לצד ר חיים עוזר גרוזנסקי להקמת ועד הישיבות. חזר לארץ-תשא וייסד בה את ועד הישיבות, לאחר השואה היה פעיל במחנות הפליטים באירופה, וסייע לחילוץ ילדים מבתי נוצרים. פרסם מאמרים ב\"בית מדרש\" - תל אביב תשא. על שמו ישיבת \"כנסת חזקיהו\" בכפר חסידים."},{"i":30730,"n":"מישקובסקי, יוסף משטוצ'ין","b":"דיין בשטוצ'ין-תרי כ-40 שנה. בנו ר חיים ליב מסטאויסק."},{"i":30731,"n":"מישקובסקי-רוטנברג, חיים אריה","f":"יוסף משטוצ'ין","k":"בעל פני הארי החי","bt":"תקצו","bp":"שטוצ'ין","dt":"תרנח - כח ניסן","dp":"סטאויסק","b":"תלמיד ישיבת וולוזין, ר אברהם שמואל בעל \"עמודי אש\" באיישישוק - יחד עם החפץ חיים. רב באורלובה-תריט, ז'אלדוק-תרכה, סטאויסק-תרמ. חברו וידידו של ה\"חפץ חיים\" - שבקשו לחבר את ה\"משנה ברורה\" וכשסירב לקח זאת על עצמו. ממיסדי ישיבת לומז'ה. תולדות ב\"פעולת צדיק\" לר יצחק מלצן. בנו - ר חזקיה יוסף. חתנו - ר יצחק בלזר."},{"i":30732,"n":"מישקינסקי, חיים יעקב מטשבין","f":"משה יהודה מברעזניקי","dt":"תשד","b":"רב בטשבין-פלך סובאלק, קנישין-פלך גרודנא, סווישלאץ(=סויסלאץ)-פלך גרודנא. נספה בשואה. גיסו - ר יהודה חשסמן מארה\"ב."},{"i":30733,"n":"מישקינסקי, חיים יעקב מטשבין","b":"גביר מחכמי ברעזניקי-פלך סובאלק. בנו - ר חיים יעקב מטשבין, חתנו - ר יהודה חשסמן מארה\"ב."},{"i":30734,"n":"מך, זלמן מסקאהל","b":"רב בסקול. חתנו - ר יהודה צבי פלץ מויטקוב."},{"i":30735,"n":"מכבי, חיים זונדל מלונדון","k":"המגיד מקמניץ-אמרי חי","bt":"תרטז או תרך","bp":"קוברין או קמניץ","dt":"תרעו","dp":"לונדון","b":"תלמיד ישיבות קוברין, בריסק. בקי באגדה ובספרות יהודית. צמחוני וטבעוני. בגיל 17 התמנה למגיד בקמניץ, והתפרסם מאוד. בשליחות חובבי ציון ברוסיה ובהשפעתו נוסדו עשרות אגודות לישוב הארץ, אולם היה גם מחלוקת כנגדו והיו שרדפוהו על דעותיו העצמאיות. היגר ללונדון-תרן וכיהן כמטיף-דרשן באנגלית - בעזרתו של ר שמואל מונטאנו (לורד סוויטלינג)."},{"i":30736,"n":"מכט, אפרים","bt":"1866","bp":"קובנא","dt":"1944","dp":"בולטימור","b":"היגר לארה\"ב-1887. עסק בנכסי נדל\"ן. פעיל בחיים הציבוריים של יהודי בולטימור. נשיא הקולג' היהודי וסגן יו\"ר מועצת החינוך היהודי. יסד מוסדות חסד וחינוך רבים."},{"i":30737,"n":"מכיר","f":"יהודה","k":"בעל אלפא ביתא","b":"מגדולי הראשונים בחכמי מגנצא-ד'תש\"צ"},{"i":30738,"n":"מכיר","f":"אבא מארי","b":"מגדולי חכמי פרובינצא-ק\"ס"},{"i":30739,"n":"מכיר","f":"יצחק בן שר חסד","k":"בעל ילקוט המכירי","b":"מחכמי ספרד בזמן הר\"ן, מצאצאי ר נתנאל \"מקלל התאונה\" ור מיכאל \"המלאך\". תלמיד ר יהודה בן הרא\"ש. חיבר \"ילקוט המכירי\" בכת\"י (אצל ר דוד אופנהים), חיבר גם \"אבקת רוכל\" קושטא."},{"i":30740,"n":"מכיר מנרבונא","b":"מגדולי הראשונים ששתלו התורה על אדמת צרפת-ד'תק\"ס"},{"i":30741,"n":"מכיר ן, אברהם מספרד","f":"יצחק","b":"רופא מחכמי טולדו-ספרד, פייטן, משורר-ק'."},{"i":30742,"n":"מכיר ן, אהרן מירושלים","f":"משה","b":"מובא בשו\"ת \"באר עשק\" סימן נא, חתום בסוף הספר \"חרבות ירושלים\" בשנת שפה."},{"i":30743,"n":"מכיר ן, זכריה (זרחיה) מירושלים","b":"מחכמי ישיבת ר יצחק גאון בירושלים-תיב."},{"i":30744,"n":"מכיר ן, שלמה מאיטליה","f":"אברהם","b":"רב באיטליה בזמן מהר\"ם פאדובה. נזכר בספרי חכמי דורו."},{"i":30745,"n":"מכלוף הכהן מטבריה","b":"דיין בטבריה-תרם. חתם עם ר בכור אהרן אלחדיף, ור שמואל בן קיקי."},{"i":30746,"n":"מכלוף מאלגיר","bt":"ץ - בערך","dt":"קס - בערך","b":"נגד קהלת קצמטינא בזמן הריב\"ש שכתב עליו - בני משפחתו גדולה יש בה לפי הנשמע יותר מ-50 אנשים כולם גבורים ובעלי זרוע רוכבים על סוסים."},{"i":30747,"n":"מכלוף מאלגיר","b":"רב קדמון באזור בו סעאדא-אלגיר, ומקום קבורתו מקודש והזיירא(הילולא) שלו בל\"ג בעומר."},{"i":30748,"n":"מכלוף, גד מלוב","bt":"תרך","dt":"תרץ - בערך","b":"רב ומשורר בלוב. חיבר קובץ פיוטים \"חנני אבי\"."},{"i":30749,"n":"מכלוף, יעקב מלוב","k":"אלגרגאשי-אלקרקאשי","bt":"תרמג","bp":"קרקאש","dt":"תשטו","b":"תלמיד ר ציון ביתאן. מלמד תורה בישיבת \"דאר אל כושאנא\", עלה לארץ. התכתב עם ר משה סרוסי ונזכר ב\"וישב משה\"."},{"i":30750,"n":"מכלר, מרדכי ליבוש מזברז","b":"רב בזברז - תשובה אליו ב\"ספר יהושע\"."},{"i":30751,"n":"מכמל, יצחק צאלח מבגדד","k":"בעל נתיבות יצחק","bt":"תרלו","bp":"בגדד","dt":"תשיא - ד סיון","dp":"ירושלים","b":"מחכמי בגדד, תלמיד ר שמעון אגסי, ר דוד בן מאיר (דודו של הבן איש חי), ר אלישע דנגור ועוד. עלה לירושלים-תרסה אולם נאלץ לחזור. רב בבגדד ומלמד ב\"בית זילכה\" ומתלמידיו ר משה אברהם מרידך, ר יוסף רביע, ר סלימן חוגי עבודי ועוד. עלה לירושלים-תשי. חיבר \"זמן תפילות לעיר בגדד\" ועוד."},{"i":30752,"n":"מכמל, עזרא נאג'י מבגדד","f":"יצחק","bt":"תרעג","bp":"בגדד","b":"מחכמי בגדד, עלה לארץ, מומחה בהכנת לוחות כמו אביו לפניו."},{"i":30753,"n":"מכנס, שם טוב מיוזיל-היסר","b":"רב ביוזיל-היסאר(=הארמון היפה)-ליד אזמיר-שנות ה-ת'."},{"i":30754,"n":"מכנס, שמואל מאזמיר","b":"שליח צבור בקהלת באקיש באזמיר-שנות ה-ת'."},{"i":30755,"n":"מל, ישראל מראגובה","dt":"תש..","b":"רבה האחרון של ראגובה. נספה בשואה."},{"i":30756,"n":"מלאוידה, יהודה חי חזקיה","k":"בעל קול יהודה","dt":"תקסו - כח סיון","b":"תלמיד השד\"ר מירושלים - ר יעקב משה עייאש בפיררה. תלמיד וחתן ר יצחק משה חי פיסארו. רב בפיררה. חיבר \"קול יהודה\", תשובות ממנו בספרי חכמי דורו."},{"i":30757,"n":"מלאטיש, רפאל מרומא","b":"מחכמי רומא. שאלה ממנו ב\"דבר שמואל\" - האם מותר לעסוק בתורה ולהנות מאחרים."},{"i":30758,"n":"מלאך, אפרים מארה\"ב","b":"רב בשיקגו. פרסם מאמרים ב\"שערי אורה\" - מיהאלביץ תרץ-תרצד."},{"i":30759,"n":"מלאך, אשר משלוניקי","bt":"תרמג","bp":"שלוניקי","b":"עו\"ד מראשי קהלת שלוניקי-תרפא, פעיל ציוני, עלה לארץ-תרצד והתישב בתל אביב."},{"i":30760,"n":"מלאך, אשר משלוניקי","b":"קומוניסט, נבחר לפרלמנט היוני מטעם שלוניקי."},{"i":30761,"n":"מלאך, דוד מליוורנו","b":"רב בליוורנו-תקמד בזמן החיד\"א. הסכים על \"אורח לצדיק\" יחד עם ר דוד חיים חסאן, ור אליהו בכר משה הכהן והחיד\"א."},{"i":30762,"n":"מלאך, חיים משלוניקי (אנגל)","f":"יוסף","bp":"אשכנז או שלוניקי","b":"שבתאי משלוניקי, נסע לוינה-תנח ולפולין ושם אמר ששבתי צבי הוא המשיח ועתיד להתגלות בשנית. השפיע על ר יהודה החסיד."},{"i":30763,"n":"מלאך, יוסף משלוניקי","b":"נבחר לפרלמנט היוני מטעם שלוניקי."},{"i":30764,"n":"מלאך, משה אהרן משלוניקי","f":"אהרן","bt":"תריא-ג","bp":"שלוניקי","dt":"תרצד - יח אדר","dp":"שלוניקי","b":"תלמיד וחתן ר משה קאשטרו. מנהל הדפוס ומגיה הספרים בדפוס \"עץ החיים\"-תרלו. יסד וניהל את העתון \"איל אביניר\"-תרנח, וחבר ב\"ועד הרוחני\". מפקח על הקדש הגביר ר חיים קובו (מינהו בצוואתו), ופעל לבניתו מחדש של ביהכ\"נ \"קייאנה\"."},{"i":30765,"n":"מלאך, פיפו נחמה משלוניקי","b":"נבחר לפרלמנט היוני מטעם שלוניקי."},{"i":30766,"n":"מלאך, רפאל חיים","b":"מחכמי איטליה. חיבר דקדוק לשון הקדש - בכת\"י."},{"i":30767,"n":"מלאך, שלמה מליוורנו","f":"חיים דוד","b":"רב בליוורנו, חתם-תקפט על כתב הרשאה לשליח ירושלים ר יעקב דוד יקותיאל הכהן יחד עם חבריו - ר מנחם עזריה קסטילנובו, ור אברהם ברוך פיפרנו. חתם על הפסק של ר ברוך עוזר מהמבורג נגד הריפורמים."},{"i":30768,"n":"מלאכי הכהן מליוורנו","f":"יעקב הכהן מליוורנו","k":"בעל יד מלאכי - הרמ\"ך","r":"רבה של ליוורנו","bt":"תנה - תס","bp":"ליוורנו","dt":"תקלב","b":"רב בליוורנו-תק. תלמיד ר יוסף אירגאס, ולפני פטירתו הפקיד ר יוסף בידיו את כתביו, וכן את ילדיו הקטנים לגדלם. הו\"ל את ספרי רבו יחד עם ילדי רבו שגדלו אצלו.","bk":[["יד מלאכי","כללים"]],"e":"ת\"ס-תקל\"ב"},{"i":30769,"n":"מלאכי רפאל מירושלים","b":"מחכמי ירושלים-שנות ה-ת' - בזמן ר יעקב חגיז."},{"i":30770,"n":"מלאכי, א' ר'","b":"פרסם מאמרים ב\"היהודי\" - נ\"י תרצו."},{"i":30771,"n":"מלאכי, דב הלוי","k":"בעל זהב הארץ","bt":"תרנ","dt":"תשכד - כח אדר","b":"רב בצפון צרפת,פאריס,עלה לא\"י"},{"i":30772,"n":"מלאל ן, יוסף","b":"נזכר בתעודה משנת ד'תתקח, וכנראה משם השם - מלול. עליו ב\"אהל דוד\"."},{"i":30773,"n":"מל\"ב, יוסף מויסבורג","b":"רב בויסבורג. ישב כדיין בדינו של ר נתן אורהולץ שנחשד ע\"י היעב\"ץ בשבתאות ויצא זכאי."},{"i":30774,"n":"מלבים מאיר ליבוש","bt":"1809","dt":"ה'תרלט 1879","bk":[["ארץ חמדה",""],["ארצות החיים",""],["ארצות השלום",""],["הכרמל",""],["יסודי חכמת ההגיון",""],["לקוטי שושנים",""],["מגלת אסתר עם פירוש מלבי”ם",""],["מגלת רות",""],["מלבי\"ם",""],["משל ומליצה",""],["שירי קדש ולהם משל ומליצה",""],["תורת כהנים",""]]},{"i":30775,"n":"מלביצקי, יוחנן","dt":"תשג","b":"רב בלעכוויץ"},{"i":30776,"n":"מלבסקי, יוסף","b":"חתן ר אברהם לנדא האדמור מטשכנוב."},{"i":30777,"n":"מלבר, יהודה מירושלים","b":"תלמיד ישיבת \"שפת אמת\" בירושלים. פרסם מאמרים ב\"תורה מציון\" - ירושלים תרצה - בהוצאת ישיבת \"שפת אמת\"."},{"i":30778,"n":"מלג'ויירי, שמואל","f":"משה","k":"בעל קץ לתכונה","b":"גדול בחכמה ותכונה-תן. חיבר גם \"וספר המלך\", ועוד."},{"i":30779,"n":"מלדולה דוד בן רפאל","bt":"1714","dt":"ה'תקע 1810","bk":[["בינה לעתים",""],["דברי דוד",""],["דרכי דוד",""],["מועד דוד",""]]},{"i":30780,"n":"מלהיוף, משה הכהן מבוכרה","bp":"בוכרה","dt":"תרפג","dp":"ירושלים","b":"דיין אצל ר חזקיה הכהן רבין בבוכרה. חתם על מכתב ליש\"א ברכה בירושלים יחד עם ר חזקיה רבין ור אבא כודיידאתיף. עלה לירושלים-תרסט, הניח לבניו בנין בירושלים וציווה לתת כל שנה מעשר מהכנסותיו וכך היה."},{"i":30781,"n":"מלוביצקי, אהרן מלכוביץ","f":"מרדכי מלכוביץ","k":"אדמור מלכוביץ","dt":"תרמא - כא סיון","b":"חתן ר פנחס מקאלק-בן ר זאב מזיטומיר. בנו - ר משה, ונכדו ר שלמה מסטולין וחברון."},{"i":30782,"n":"מלוביצקי, יהושע","f":"אברהם אהרן","bt":"תרפב","dt":"תשמז - טז שבט","b":"נכד ר פנחס מלכוביץ. חתן ר יעקב הלברשטם מטשאקאובא (צאנז). עבר לארה\"ב וכיהן כר\"מ בישיבת אביו. חזר לארץ-תשלא והתקרב לאדמורי סלונים."},{"i":30783,"n":"מלוביצקי, יוחנן מלכוביץ","f":"נח מלכוביץ","k":"אדמור מלכוביץ","dt":"תשב","b":"חתן ר ישכר ליב מסלונים. נספה בשואה."},{"i":30784,"n":"מלוביצקי, מרדכי מלכוביץ","f":"משה דב-בן אהרן שותק","b":"נכד ר אהרן \"שותק\" מזליחוב. חתן ר נח יפה האדמור מלכוביץ. אדמור בלכוביץ לחלק מחסידי חותנו על מקומו אחריו. מקורב לר אהרן מקרלין."},{"i":30785,"n":"מלוביצקי, פנחס מלכוביץ","k":"אדמור מלכוביץ בארה\"ב","b":"חתן ר שמואל מסלונים. נסע לארה\"ב וכיהן כאדמור."},{"i":30786,"n":"מלול ן, אברהם מאספי-מרוקו","b":"מו\"ץ באספי-מרוקו, חתם על פס\"ד-תעב, ובשו\"ת מצב\"י."},{"i":30787,"n":"מלול, יוסף מסאלי-מרוקו","b":"מחכמי סאלי-מרוקו-שנות ה-ת'. שאלה ממנו לר שמואל הצרפתי והיעב\"ץ - וחתם עמו ר שלמה בן יעקב."},{"i":30788,"n":"מלול, יצחק איקוראן מראבט-מרוקו","b":"רב בראבט-מרוקו-תקעד."},{"i":30789,"n":"מלול, ישראל","k":"בעל פלח הרימון","dt":"תשכח"},{"i":30790,"n":"מלול, משה חיים ממצרים - א","k":"בעל קרבן חגיגה","b":"תלמיד ר מלאכי הכהן בעל \"יד מלאכי\" בליוורנו, וחיבר הקדמה לספר רבו. רב במצרים-תקך."},{"i":30791,"n":"מלול, משה חיים ממצרים - ב","dt":"תרפה","dp":"טנטה-מצרים","b":"רב בקהיר, טנטה-מצרים. מחדושיו בקובץ \"זכור לאברהם\" תשמט."},{"i":30792,"n":"מלול, שלמה מאלגיר","f":"מאיר","bt":"תרס - בערך","dt":"תשל","b":"רב באלמעסכר. הו\"ל \"יקרא דשכבי\" - ת\"א תשיא."},{"i":30793,"n":"מלטי, אהרן מסופיה","b":"רב בסופיה-שנב, לצדו ואחר כך לאחר ר יוסף אלבו - היה מחלוקת בקהלה וחלק מינו אותו במקום ר יוסף אלבו, עזב לאחר זמן קצר."},{"i":30794,"n":"מלטי, יצחק מליפאנטו","b":"רב בליפאנטו-שנות ה-ש'. בנו - ר רפאל מליפאנטו."},{"i":30795,"n":"מלטי, רפאל מליפאנטו","f":"יצחק מליפאנטו","b":"רב בליפאנטו-שנות ה-ש'."},{"i":30796,"n":"מלטי, שבתי מיאנינה","b":"דיין מחכמי יאנינה, בקשרי מכתבים עם ר יוסף מולכו."},{"i":30797,"n":"מלטר, מאיר מזבנא","b":"חתן ר יוסף שפירא מקשאנוב. מחכמי טורנא, סירב לרבנות. ממשתתפי \"אהל מועד\"."},{"i":30798,"n":"מליחי, שלום מתימן","b":"מחכמי סדה (סעדה?)-תימן - בשנות ה-תש'."},{"i":30799,"n":"מלילי, דוד מאלגיר","f":"מרדכי","bt":"רך - בערך","dt":"רצ - בערך","b":"רב בבג'איה-אלגיר. מכונה \"המשכיל\". שאלה ממנו לר שמעון דוראן."},{"i":30800,"n":"מלילי, חיים מתונס","f":"יוסף","b":"רב ודיין בתונס או תנס-אלגיר. נזכר בשו\"ת הריב\"ש ומשתמע שהיה מאזור מגוריו שהיה באלגיר. על כך ב\"ספונות ז."},{"i":30801,"n":"מלין, אברהם משה מביאליסטוק","f":"יוסף שרגא מבריסק","b":"נכד ר מאיר? איסר יהודה בעל \"עזרת יהודה\". מו\"צ בביאליסטוק. בניו: ר איסר יהודה מבריסק, ר אריה ליב. נספה בשואה."},{"i":30802,"n":"מלין, איסר (מאיר?) יהודה מבריס","f":"נחמיה","k":"בעל עזרת יהודה","dp":"ארץ ישראל","b":"רב בבריסק-תר, עלה לארץ. בנו - ר יוסף שרגא מבריסק."},{"i":30803,"n":"מלין, איסר יהודה מבריסק","f":"אברהם משה מביאליסטוק","k":"בעל עזרת יהודה","dt":"תשג","b":"מגדולי חכמי דורו, רב בלאמזיצא, בריסק. חיבר גם \"נחמת יהודה\", תשובות ר איסר יהודה."},{"i":30804,"n":"מלין, אריה ליב מארה\"ב","f":"אברהם משה מביאליסטוק","dt":"תשכב","b":"תלמיד ישיבת מיר בליטא, מראשי הישיבה בזמן השואה כשגלתה לשנחאי, יסד את ישיבת \"בית התלמוד\" בניו יורק עם ר שמואל חרקובר ור חיים ויסוקר. פרסם מאמרים ב\"התבונה\" - נ\"י תשז - קובץ תלמידי ישיבת מיר."},{"i":30805,"n":"מלין, יוסף שרגא מבריסק","f":"מאיר יהודה-עזרת יהוד","b":"רב בבריסק על מקום אביו."},{"i":30806,"n":"מלין, נחמיה","b":"ניצל מהשואה והגיע לשנחאי-סין. פרסם מאמרים ב\"מאור תורה\" - שנחאי-סין תשד - קובץ תלמידי ישיבת מיר בשנחאי."},{"i":30807,"n":"מלין, ר' ש' מביאליסטוק","b":"פרסם מאמרים ב\"ירושלים\" - וארשא תרצו."},{"i":30808,"n":"מלינג, חיים מפרג","f":"יצחק איזיק מפרג","dt":"שסח - יח ניסן","dp":"פרג","b":"רב באוסטרליץ וראש ישיבה שם, אב\"ד בפרג-שמג על מקום אביו בזמן ר דוד גאנז המזכירו בספרו \"צמח דוד\"."},{"i":30809,"n":"מלינג, יוסף מפרג","f":"יצחק","dt":"שמב - טו כסלו","dp":"פרג","b":"משורר ובקי בדקדוק. נפטר צעיר בגיל 16."},{"i":30810,"n":"מלינג, יצחק מפרג","f":"ישעיה","dt":"שמג - יא ניסן","dp":"פרג","b":"ראש ישיבה ואב\"ד בפרג ובנו ר חיים על מקומו אחריו."},{"i":30811,"n":"מליניאק, משה מפראגא","b":"גביר חסיד מחכמי פראגא."},{"i":30812,"n":"מלינק, דובער מפראגא","b":"פרסם מאמרים ב\"יגדיל תורה\" - פראגא-וארשא תרפז."},{"i":30813,"n":"מלינק, שמואל קלמן מלונדון","f":"גרשון יעקב","k":"בעל רוח חיים","bt":"תרכב","bp":"זקראטשין-פלך וארשא","b":"תלמיד ר יצחק מיולאווע-ליד סוכטשוב, ר דב מנחם רגנשבורג מזאמברווא-פלך לומזה, ר ישראל איטשע מפאוואזניק-ליד וארשא. מלמד תורה בזקרטשין, מו\"צ בלונדון-תרנד. נסמך מאת: ר ישראל יעקב מזאקרטשין, ר יחיאל מיכל מזקראטשין. חיבר דרשות ושו\"ת בשם \"רוח חיים\" - בכת\"י."},{"i":30814,"n":"מלינרציק, אברהם חיים דב","k":"בעל ברכת אברהם","b":"חתן ר נח מנאויגראד. דרשן בלומז'ה."},{"i":30815,"n":"מלינרציק, חיים ברל מלומזה","b":"תלמיד ישיבת וולוזין. חתן ר נח וינר מנובוגרד."},{"i":30816,"n":"מליק, חיים יצחק מסטמר","f":"משה יעקב ממאסיף","k":"בעל ובחרת בחיים-תרפו","bp":"מארמארוש","b":"תלמיד בעל \"עצי חיים\" בסיגט. ר\"מ בישיבת ר אליעזר שיף מבקיסאד בסטמר. מקורב לאדמור ר אהרן ראטה וכשעזב ר אהרן לברגסאס ניהל את ישיבתו בסטמר. נספה בשואה. חיבר גם \"מכלכל חיים\", \"סיפורים נפלאים מהבעשט\", \"נחלת יעקב\" ועוד."},{"i":30817,"n":"מלך ן, ברוך","b":"מחכמי ארם צובה, חכם קדמון"},{"i":30818,"n":"מלך ן, יקותיאל מטיריא","b":"מחכמי טיריא-שנות ה-ת'."},{"i":30819,"n":"מלך ן, שלמה ממרוקו וקושטא","k":"בעל מכלל יופי","bt":"רמ","bp":"פאס","dt":"שיד - אחרי","b":"מחכמי מרוקו, בזמן ר משה בנצור, ר דניאל בן יוסף טולדנו, ר שמעון לביא. עבר לקושטא - רפ - רצ."},{"i":30820,"n":"מלכא גאון פומפדיתא","f":"רב אחא","b":"גאון פומפודיתא - (733-731). היה מעורב במחלוקת בין רב זכאי ראש הגולה לבין ר נטרונאי בר חביבאי - ותמך בראש הגולה רב נטורנאי נאלץ לעזוב את בבל, הגיע לספרד וכתב להם את התלמוד."},{"i":30821,"n":"מלכא, אברהם משלוניקי","bp":"שלוניקי","b":"עוזר דיין באזמיר, רב ודרשן בקאבאלה-מקדוניה-תרסא."},{"i":30822,"n":"מלכא, אהרן ממרוקו","f":"שלמה","b":"מחכמי פאס-שנת ר', חברם של ר שמואל אביטבול, ור אהרן ן סמחון. יצאו בדרכם לארץ ישראל יחד עם האחים ר יוסף ור חלפתא ן אליד, אך הגיעו לתלמסן וחזרו (האחים ן אליד המשיכו בדרכם)."},{"i":30823,"n":"מלכא, בצלאל מטבריה","bp":"מכנאס","dt":"תשא - ל אדר","dp":"טבריה","b":"עלה לא\"י, מחכמי טבריה"},{"i":30824,"n":"מלכא, דוד ממכנאס","b":"מחכמי מכנאס-שנות ה-ת'."},{"i":30825,"n":"מלכא, יהודה","f":"יצחק","b":"חכם שלם-תק\"ב"},{"i":30826,"n":"מלכא, יהודה מפאס","f":"נסים","k":"בעל ספר הצנורות?","b":"מקובל ורב בפאס-שנות ה-תק'. חיבר פירוש לספר יצירה, ועל פרקי דרבי אליעזר."},{"i":30827,"n":"מלכא, יוסף מאלגיר","bt":"תקסג","bp":"וואהרן","dt":"תרלה","dp":"טבריה","b":"רב בווהראן, עלה לצפת-תקצט, רב בטבריה ומלמד תורה. חתם בטבריה על יסוד ישיבת \"בית יעקב\"-תריז. בשליחות קהלות צפת וטבריה בתורכיה-תרכב."},{"i":30828,"n":"מלכא, יוסף מפאס","f":"סאלם","b":"מחכמי פאס. בנו - ר יעקב ונכדו ר סאלם-השני."},{"i":30829,"n":"מלכא, יעקב מפאס וטיטואן","bt":"תן - לפני","dt":"תקלא","dp":"טיטואן","b":"מו\"ץ וסופר ביה\"ד בפאס ואח\"כ דיין, בזמן הרעב גלה לטיטואן וכיהן כרב עם ר אפרים מונסינייגו, ר יהודה אבודרהם, ר יהודה קוריאט. קינה לזכרו ב\"תהלה לדוד\" לר דוד ן חסין. מתלמידיו - ר יעקב ן נאים בעל \"זרע יעקב והזכירו בספרו. היה מחלוקת בינו לבין דייני פאס בראשות היעב\"ץ"},{"i":30830,"n":"מלכא, יצחק מפאס - א","f":"יוסף","b":"מחכמי פאס, שאלה ממנו ליעב\"ץ-תפג, תשובה אליו ב\"משפט וצדקה ביעקב\". אחיו של ר יעקב."},{"i":30831,"n":"מלכא, כליפא חסיד ממרוקו וירוש","f":"מלכה?","k":"בעל כף ונקי","bt":"תמ","bp":"טיטואן-מרוקו","dt":"תקכ - ג אלול","dp":"ירושלים","b":"חתן ר יצחק מינדיס מאגאדיר. מקובל, רב באגאדיר-מרוקו, עלה לירושלים והיה מחכמי \"בית אל\". תלמיד ר יהודה ן עטר. התוכח עם הנוצרים ועם המוסלמים בעניני אמונה. היה עשיר גדול אך איבד את רכושו והגביר ר משה בן יעקב מאמשטרדם היה תומך בו. חיבר \"כף ונקי\"-בכת\"י, \"קול רינה\", \"רך טוב\", \"רינה וישועה\". (יא אומרים תאריך פטירתו - ג אייר). נזכר ברשימת החכמים בירושלים-תקיח, החיד\"א מזכירו בספריו."},{"i":30832,"n":"מלכא, מוסי מאגוראי-מרוקו","dt":"תקפו","b":"מחכמי אגוראי-מרוקו. נהרג עק\"ה עם עוד 15 יהודים, קינה לזכרו ב\"קול יעקב\" לר יעקב בירדוגו."},{"i":30833,"n":"מלכא, מימון ממראקש","bt":"תפג","dt":"תקכג","b":"מקובל מחכמי מראקש. בשליחות בדבדו עבור פדיון שבויים-תקכג."},{"i":30834,"n":"מלכא, מרדכי ממכנאס","b":"מחכמי מכנאס, חתם-תצז על פס\"ד עם ר אברהם בן דוד ן חסין ועם ר חנניה ן זכרי, וחתם עם ר שמואל בהלול."},{"i":30835,"n":"מלכא, משה מאגוראי-מרוקו","dt":"תקפו","dp":"מכנאס","b":"מחכמי אגוראי-מרוקו, נזכר ב\"קול יעקב\" לר יעקב בירדוגו. נהרג עק\"ה ליד מכנאס."},{"i":30836,"n":"מלכא, משה מטיטואן-מרוקו","b":"דיין בטיטואן-תקלב."},{"i":30837,"n":"מלכא, משה ממרוקו","f":"יחיא","k":"בעל מקוה המים","bt":"תרעא","bp":"תודגא-מרוקו","dt":"תשנז - יד אדר","dp":"פתח תקוה","b":"תלמיד בישיבת אביו ואחיו ר יעקב. עבר לעיר ארבט-מרוקו ולימד שם, והיה תלמיד ר יהושע ברדוגו, כיהן כשו\"ב בהמלצת רבו בלקצר, לעראייש, ארזילא-תשז תחת הרב כלפון - ראש הרבנים במרוקו הספרדית. מלמד בביהמ\"ד לרבנים בארבט-תשיא, דיין בבני מללאל, תאדלא, בוזעה. דיין בקזבלנקא. עלה לארץ-תשכז וכיהן כרב בפתח תקוה."},{"i":30838,"n":"מלכא, משה מפאס","b":"מחכמי פאס בשנות ה-ת'. נזכר ע\"י היעבץ."},{"i":30839,"n":"מלכא, נסים מפאס-מרוקו","k":"בעל אמרי מלוכה","b":"רב ומקובל בפאס-קך. בנו ר יהודה בעל צניף מלוכה, ונזכרו האב ובנו בפירוש ר משה בוטריל."},{"i":30840,"n":"מלכא, סאלם מפאס","b":"מחכמי פאס-שנות ה-ש'. אביו של ר יוסף וזקנו של ר יעקב."},{"i":30841,"n":"מלכא, סאלם מפאס","f":"יצחק","b":"מחכמי פאס-תקסב, אחיו של מוהר\"י ן מלכא."},{"i":30842,"n":"מלכא, שלום מטבריה","dt":"תרסז - כא סיון","b":"נתעוור בנערותו, מחכמי טבריה. בשליחות-תרלא בתורכיה ומרוקו. רב ראשי בטבריה-תרנט, ואחר כמה שנים התפטר."},{"i":30843,"n":"מלכא, שלום ממרוקו וירושלים","k":"בעל וזרח השמש","dt":"תרנו","dp":"ירושלים?","b":"מקובל מחכמי \"בית אל\". נספד ב\"שמחת כהן\". חיבר \"וזרח השמש\" על עניני הזריחה והשקיעה."},{"i":30844,"n":"מלכא, שלמה מירושלים","b":"עלה ממרוקו לירושלים. מחכמי ירושלים-תרלג וחתם בהקדמה ל\"ויאמר יצחק\" לר יצחק ן ואליד."},{"i":30845,"n":"מלכא, שמואל ממכנאס","b":"מחכמי מכנאס-תקפא. נזכר ב\"שופריה דיעקב\"."},{"i":30846,"n":"מלכא, שמואל מפאס-מרוקו","f":"יעקב","dt":"תקכא - יג סיון","b":"מחכמי פאס, נהרג עק\"ה, ונספד ע\"י ר אליהו הצרפתי ב\"נער בוכה\". בשנת תקכא מצא גובה המס בצרור כסף המס - מטבע שחוק, וטען שהיהודים זייפו את המטבע, ושר העיר חקר בעינויים את כל היהודים עד שאחד אמר את שמו של ר שמואל כמקור המטבע, והרגוהו בעינויים, ואשתו שהיתה מעוברת ילדה בן שנקרא ע\"ש אביו - שמואל."},{"i":30847,"n":"מלכא, שמואל מפאס-מרוקו","k":"בעל לשון למודים","dt":"תש..","b":"רב בפאס-תרצא, הסכים אז על \"מלכי רבנן\" לר יוסף בן נאיים. מצאצאי ר יעקב מלכא בעל \"נר המערבי\". חיבר גם \"בינה לעתים\", \"צפנת פענח\", ועוד."},{"i":30848,"n":"מלכובסקי, הלל","k":"בעל כתבים בספר","b":"חיבר \"כתבים בספר\" - מחיי היהודים באמריקה."},{"i":30849,"n":"מלכי צדק, יצחק מאיטליה","f":"הרב מלכי צדק","k":"בעל פירוש למשנה","b":"רב בסימפונא(=סיפונטי)-דרום איטליה - ד'תתע-ד'תתקכ."},{"i":30850,"n":"מלכי, משה מצפת","f":"רפאל מרדכי","dt":"תקה","dp":"כפר יאסיף","b":"אחיו של ר עזרא מלכי מרודוס בעל \"עין משפט\". מחכמי צפת וחתם-תצו על כתב שליחות ר חיים יעקב ור מאיר די שיגורה, ועל מכתב רבני צפת לקהילת פיסא, ועוד. ר חיים ן עטר כינהו \"ידיד נפשי\"."},{"i":30851,"n":"מלכי, משה מצפת - ב","b":"מחכמי צפת. בשליחות באמריקה-תקיט, בהיותו בניו יורק נענה לבקשת אחת הקהלות להיות רבם לתקופה קצרה ולסייע להם בארגון עניני הדת, היה ניו פורט, קורסאו - ונזכר בפנקס הקהלה. היה השליח הראשון מארץ ישראל באמריקה, שחזר לארץ."},{"i":30852,"n":"מלכי, עזרא מצפת ורודוס","f":"רפאל מרדכי","k":"בעל מלכי בקדש","bt":"תע","bp":"צפת","dt":"תקכח - אייר","dp":"רודוס","b":"תלמיד ר מיכאל מלמד. רב בצפת. בשליחות בתורכיה-תקה, תקט, ועוד. פגש רבים מגדולי דורו. בדרכו ברודוס-תקיב נתמנה לרב ור משה ישראל על מקומו אחריו. גיסו של ר חזקיה די סילוא שהיה בעל אחותו. חיבר גם \"עין משפט\", \"שמן למאור\" ועוד. בהיותו בניקופול-תקה סייע לבני הקהלה לשקם את ביהכ\"נ של ר יוסף קארו."},{"i":30853,"n":"מלכי, רפאל מצפת","f":"עזריאל?","b":"מחכמי צפת-תפ, חתם-תקכד על כתב שליחות ר מרדכי בונאן."},{"i":30854,"n":"מלכי, רפאל מרדכי מאיטליה","k":"בעל פירוש לתורה","bt":"[ת..]","bp":"איטליה","dt":"תסב-ה - ד אב","dp":"ירושלים","b":"רופא מחכמי איטליה, עלה לירושלים-תלז ושימש גם כרופא בשנים תלג - תסב, ר גדליה מסמיאטיץ מספר כי נקרא לטפל בר יהודה החסיד בזמן חוליו. בשנת תס חתם על הסכם כספי החלוקה. כתב חיבור על התורה בחלקו נדפס בירושלים תרפג, שו\"ת, מאמרים ברפואה. בניו ר משה - רב בצפת, ר מאיר ור עזרא מצפת. חתניו - ר חזקיה די סילוה בעל \"פרי חדש\", ור משה חאגיז - המני\"ח.","bk":[["לקוטים",""]]},{"i":30855,"n":"מלכיאל הכהן מטריפולי","f":"יעקב","bt":"תע","dt":"תקמ","b":"רב ודיין בטריפולי. עסק בפדיון שבויים - של יהודים מטריפולי שנשבו והוחזקו במלטה או בליוורנו. נזכר בספר \"מיכאל\" ת\"א תשלה."},{"i":30856,"n":"מלכיש, אהרן מוינה","b":"רב בוינה-שעח."},{"i":30857,"n":"מלמד אגמי, חיים","k":"בעל מדרש ישועה ורחמי","b":"חיבר \"מדרש ישועה ורחמים\" על פרקי אבות"},{"i":30858,"n":"מלמד, אברהם הרופא משלוניקי","dp":"איסקופיה","b":"רופא מחכמי שלוניקי-שץ, רב הכולל באיסקופיה(=איסקוב) ורב קהלת \"בית אהרן\" שם. קרובו - ר מאיר מלמד."},{"i":30859,"n":"מלמד, אברהם שלמה מקרים","k":"בעל מסכת סוחרים","b":"רב בפיאדוסיא כפא-קרים. (כנראה שם בדוי ומקום בדוי)."},{"i":30860,"n":"מלמד, אליהו מחברון","f":"דוד","b":"מחכמי חברון, בשנת תקלה חתם על כתב שליחות ר משה הכהן סקלי לקהילת ארטיב במרוקו, לגייס כסף פדיון נפשם של 10 בחורים מישראל שנדונו לממות על השיך של חברון כנקמה על בנו הקטן שנמצא מת."},{"i":30861,"n":"מלמד, אליעזר יהודה חיים","bt":"תקעד","bp":"חברון","dt":"תריח - לפני","dp":"גיברלטר","b":"שליח חברון לצפון אפריקה ונפטר בדרכו."},{"i":30862,"n":"מלמד, בכור בנימין מאזמיר - א","f":"מאיר","bt":"שעה","bp":"שלוניקי","dt":"תל-ח - כט כסלו","dp":"מגניסיאה או אזמיר","b":"תלמיד ר אברהם מוטאל. מחכמי שלוניקי, איזמיר וראש ישיבה שם, רב במגניסיאה על מקום ר משה עוזיאל, חזר לאזמיר-תכח ור משה עוזיאל על מקומו אחריו (לאחר שחזר). מתלמידיו ר אליהו הכהן בעל \"שבט מוסר\" שהספידו בספרו \"מדרש אליהו\"."},{"i":30863,"n":"מלמד, בכור בנימין מאזמיר - ב","dt":"תרמח","b":"מרבני איזמיר, מרביץ תורה"},{"i":30864,"n":"מלמד, בן ציון מפיקאלן","dt":"תרפט","b":"רב בפיקאלן-ליטא."},{"i":30865,"n":"מלמד, בן ציון מתל אביב","b":"רב בתל-אביב-תר\"צ"},{"i":30866,"n":"מלמד, בנימין מאזמיר","b":"רב באזמיר-תכא, יחד עם ר יצחק אשכנזי."},{"i":30867,"n":"מלמד, גדליה מאזריץ","b":"נכד ר שלמה מאזארישץ. רב באזארישץ-תרע."},{"i":30868,"n":"מלמד, דב מגלינא","f":"יעקב","bp":"גלינא","dt":"תרעא","dp":"למברג","b":"רב בגלינא."},{"i":30869,"n":"מלמד, דב מפיקאלן","b":"רב בפיקאלן על מקום ר בן ציון מלמד - אביו?"},{"i":30870,"n":"מלמד, דובער","dt":"תשג","b":"רב בצייקישאק"},{"i":30871,"n":"מלמד, דוד מאיטליה","b":"חברו של ר יצחק רפאל פינצי."},{"i":30872,"n":"מלמד, דוד מירושלים","bp":"ירושלים","b":"מחכמי ירושלים, תלמידו וחתנו של ר אברהם ישראל זאבי, עבר לחברון ויצא בשליחות לאיטליה -תעח, עם ר ישראל הכהן. תשובה שלו בשות \"מים רבים\", חתימה שלו משנת תעח לבקשת עזרה לקהילת חברון. בהיותו בפיררה יסד עם אחרים את חברת תקון חצות בשם \"חדשים לבקרים\", ביקר גם באשכנז, בעל תג\"י מעיד כי ברשותו פסק של ר דוד משנת תעח בדבר מעמדם של יהודי חברון לגבי פדיון שבויים. בשנת תקד חתם על כתב שליחות ר אברהם גדליה. בשנת תקי חתם על כתב סמיכה לר חיים יצחק קריגל. בשנת תקכב נתמנה ראש הרבנים בחברון."},{"i":30873,"n":"מלמד, דוד מנמירוב","f":"נחום אהרן מחרישקיפקא","b":"מצאצאי ר שכנא ליכטמן מנמירוב. רב בנמירוב-תרע."},{"i":30874,"n":"מלמד, חיים הכהן","b":"רב בשיראז(פרס)-תרכ\"ה"},{"i":30875,"n":"מלמד, חיים הכהן משירז","b":"רב בשיראז(פרס)-תרכ\"ה"},{"i":30876,"n":"מלמד, חיים מאמשטרדם","f":"ישכר בער","k":"בעל מנחה קטנה","dt":"תקעה - ג אלול","b":"דרשן,מג\"מ באמשטרדם. סגי נהור. חיבר גם \"תהלת ה'\" על ספר תהלים, \"פרפראות לחכמה\"."},{"i":30877,"n":"מלמד, יהושע השל מוורנה-ליטא","b":"רב בווארנה(=וורנה), ציטוביאן."},{"i":30878,"n":"מלמד, יוסף אלחנן מויטבסק","k":"בעל משא ננוה","bt":"תרכ","dt":"תרצב - ג טבת","b":"רב בויטבסק-תרע. עלה לא\"י- תרפה."},{"i":30879,"n":"מלמד, יעקב משלוניקי","dt":"שיז","b":"רופא בשלוניקי. בנו ר שם טוב - רופא ורב בפאטראס."},{"i":30880,"n":"מלמד, יצחק זאב מלייפציג","f":"נחמיה","k":"בעל דברי בינה","b":"רב בלייפציג. אחיו - ר שמואל דב מצייקישוק."},{"i":30881,"n":"מלמד, יצחק מטריאניבקע","f":"שמשון","bt":"תרכב","b":"רב בטריינובקה(=טריאניבקע)-ווהלין-תרנח."},{"i":30882,"n":"מלמד, ישראל חיים מחברון","f":"דוד","b":"מחכמי חברון, בשנת תקלה חתם על אגרת שנשלחה אל החידא באיטליה. בשליחות בגרמניה ובשנת תקמד היה בפיורדא והסכים לספר \"וחשב לו הכהן\" לר אברהם כץ מלאסק."},{"i":30883,"n":"מלמד, ישראל יהושע סגל מוורנה","f":"שמואל אריה","bt":"תרכד-לד","dt":"תרעט","b":"חתן ר צבי יעקב אופנהים. רב בוורנה(=וארנא)-פלך קובנא-תרנח, טריסק(=טרישקי) על מקום ר חיים פוהן."},{"i":30884,"n":"מלמד, מאיר מפטרץ וליפנטו","f":"שם טוב","k":"בעל משפט צדק","b":"תלמיד ר יוסף עזרא, ר אהרן ן חסון בשלוניקי. רב בליפאנטו-שסב, מגדולי חכמי דורו בגליל המוריאה-שפ, רב בפאטראס(=פטרץ) על מקום ר יעקב הלוי. מתלמידיו - ר יוסף ן עזרא בעל \"עצמות יוסף\" המזכירו בספרו."},{"i":30885,"n":"מלמד, מאיר שמואל מיגולניצה","b":"רב ביגולניצה-תרף."},{"i":30886,"n":"מלמד, משה מאזמיר","f":"שלמה יהושע מלמד","b":"רב-שנת תר\"פ,מרבני אזמיר"},{"i":30887,"n":"מלמד, משה מאזמיר","b":"רב באזמיר."},{"i":30888,"n":"מלמד, נחום אהרן מחרישקיפקא","f":"יעקב יהודה בן משה מר","bt":"תרח","b":"חתן ר שכנא מבראהלוב. נכד ר משה מרדכי, ונכד-אבי אמו ר חיים צאנזר מברוד. רב בחרישקיפקה(חארישקיפקא)-פודוליה-תרמה. בניו: ר שלום מפרוליקא, ר דוד מנעמירוב. חתניו: ר צבי מיאמפילא, ור אברהם ליב."},{"i":30889,"n":"מלמד, נסים מארטא","b":"רב בארטא-יוון, חברו של מהרשד\"ם (=ר שמואל די מדינה)."},{"i":30890,"n":"מלמד, סימן טוב מפרס","k":"בעל ספר האזהרות","bp":"יזד-פרס","dt":"תקפג","dp":"משהד","b":"מחכמי פרס. נשלח על ידי ר אור שרגא מיזד לעיר משהד כדי לחזק את מצב היהודים. חיבר גם \"חייח אל רוח\" ירושלים תרנח. פיוטיו נפוצו בין יהודי פרס, אפגניסטן ובוכרה."},{"i":30891,"n":"מלמד, עזרא ציון הכהן","f":"רחמים","k":"בעל מילון אספרנטו עב","bt":"תרסד","bp":"שיראז-פרס","dt":"ה'תשנד 1994","b":"עלה לירושלים, מלמד ב\"דורש ציון\", בעל תואר באוניברסיטה, פרסם מאמרים ומחקרים בעניני ארץ ישראל ועוד.","bk":[["מבוא לספרות התלמוד",""],["מלון ארמי",""],["מילון עברי ארמי",""]]},{"i":30892,"n":"מלמד, פנחס ממיכלפאליע","f":"ישראל","bt":"תרלא","b":"רב במיכאלפאל(=מיכלפאליע)-פודוליה-תרנג."},{"i":30893,"n":"מלמד, ראובן","b":"ניצל מהשואה והגיע לשנחאי-סין. פרסם מאמרים ב\"מאור תורה\" - שנחאי-סין תשד - קובץ תלמידי ישיבת מיר בשנחאי."},{"i":30894,"n":"מלמד, ראובן מבוכרה וירושלים","bt":"תקעט","bp":"בוכרה","dt":"תרנו - ג תמוז","dp":"ירושלים","b":"רב בבוכרה, עלה לירושלים-תרם. יסד ביכ\"נ, חתנו - ר משיח גליבוף עמד בראשו אחריו."},{"i":30895,"n":"מלמד, רחמים הכהן ראובן מפרס","f":"חיים בן שמואל","k":"בעל כסא רחמים","bt":"תרכה","bp":"שיראז-פרס","dt":"תרצב - ד שבט","dp":"ירושלים","b":"בן למשפחה ידועה וחשובה בשיראז, ראש הקהילה בשיראז-פרס, עלה לירושלים-תרסז. כינויו היה \"מולא כוצ'יק\". רבה של קהילת יוצאי פרס בירושלים ודרשן ידוע. חיבר גם \"ישועה ורחמים\", \"צדקה ורחמים\" ועוד. בנו ר יעקב מלמד.","bk":[["כסא רחמים",""]]},{"i":30896,"n":"מלמד, רפאל הכהן מפרס","b":"מחכמי לאר-פרס-תרמז. חיבר מילון לארמית שבזהר - תרגום לעברית ופרסית."},{"i":30897,"n":"מלמד, רפאל מיכאל מצפת","b":"מחכמי צפת, חתם-תפא על כתב שליחות ר משה ישראל מרודוס."},{"i":30898,"n":"מלמד, שלום מפרוליקא","f":"נחום אהרן מחרישקיפקא","b":"רב בפרלוק(=פרוליקא)-ליד ברדיטשוב, אומן, עלה לארץ-תרפח."},{"i":30899,"n":"מלמד, שלמה יהושע מאזמיר","k":"בעל שער השמים","dt":"תרפט","b":"מרבני אזמיר,רב בקסאבא-תורכיה"},{"i":30900,"n":"מלמד, שלמה מאזרארושיץ","b":"רב באזאראשיץ על מקום אחיו - ר שמואל. ונכדו ר גדליה גם הוא רב באזארישץ."},{"i":30901,"n":"מלמד, שם טוב מאזמיר - א","f":"יעקב","k":"בעל כתר שם טוב","b":"רופא מחכמי אזמיר בשנות ה-ר'. חיבר גם \"מאמר מרדכי\". בנו ר מאיר בעל \"משפט צדק\" - תלמיד ר יוסף ן עזרא בעל \"עצמות יוסף\"."},{"i":30902,"n":"מלמד, שמואל דב מצייקישוק","f":"נחמיה","k":"בעל נחלת שמואל","r":"רב דצייקשוק","bt":"תרמח (ממעמקים ה)","dt":"תש..","b":"רבה האחרון של צייקישוק-ליטא. נספה בשואה. אחיו - ר יצחק זאב מלייפציג.","bk":[["נחלת שמואל",""]]},{"i":30903,"n":"מלמד, שמואל מאזארישץ","b":"רב באזארישץ-פודוליה-תקץ. אחיהם של ר משה מרדכי, ר שלמה מאזארישץ."},{"i":30904,"n":"מלמד, שמואל משה (מכס)","bt":"1885","bp":"וילקוביסק","dt":"1938","dp":"ניו יורק","b":"פרסם בעותנים גרמניים ועבריים ובהם \"השלוח\". עבר ללונדון ופרסם בעתונים גרמניים משם. עבר לארה\"ב, עורך ה\"אמריקן ג'ואיש כרוניקל\"-1914, נשיא הסתדרות הציונית בשיקגו. חיבר ספרים בגרמנית בנושאים יהודיים."},{"i":30905,"n":"מלמד, שמואל משלוניקי","b":"גביר מראשי קהלת שלוניקי, השתתף במשלחת אצל השולטן בקושטא-שצז בראשות ר יהודה קובו - שנהרג עק\"ה בידי השולטן."},{"i":30906,"n":"מלניצקי, חיים דוד","bt":"תרטו","dt":"תרפח","b":"רב בגרודזינסק"},{"i":30907,"n":"מלץ, בן ציון","f":"אליעזר מאושפיצין","bt":"תרסא-ה","b":"מחכמי אושפיצין, עבר לקשאנוב ולגדוב. נספה בשואה. מדברי תורתו ב\"כרם שלמה\" תשמב."},{"i":30908,"n":"מלץ, מאיר מראדוילישוק","dt":"תרמה","b":"רב בראדוילישוק על מקום ר יוסלה הצדיק."},{"i":30909,"n":"מלצן, יצחק מליטא וירושלים","f":"שמואל המגיד מסלוצק","k":"בעל אזהרת שבת","bt":"תריד","bp":"סלוצק","dt":"תרעד","dp":"ירושלים","b":"מחכמי המוסר בליטא, אביו הידוע בשם המגיד מסלוצק בעל \"אבן שלמה\". תלמיד ר ישראל סלנט וקיבל ממנו היתר הוראה. היה רב בקלם, ר\"מ בראדין, עלה לירושלים-תרסו. חיבר גם \"סידור הגר\"א\", \"שביתת שבת\", \"דקדוק חברים\", ועוד. הו\"ל \"אמרי נעם\" - מתורת הגר\"א - יחד עם רא\"ל ליפקין מקרטגינא ור ש\"מ ליזרוביץ. פרסם מאמרים בכתבי עת. פעיל באגודה לגילוי עקבות עשרת השבטים בתימן. פרסם מאמרים ב\"הפלס\" - ברלין תרסא-תרסה.","bk":[["שביתת השבת","מערכות"]]},{"i":30910,"n":"מלצן, שמואל מסלוצק","f":"אברהם","k":"בעל אבן שלמה","b":"בנו - ר יצחק הו\"ל את ספרו עם תוספות ממנו."},{"i":30911,"n":"מלצר איסר זלמן בן ברוך פרץ","f":"ברוך פרץ","k":"בעל אבן האזל","r":"ראש ישיבת עץ חיים","bt":"תרל","bp":"מיר","dt":"תשיד - י כסלו","dp":"ירושלים","b":"ממשפחת הוטנר. גדל אצל קרובו ר יו\"ט ליפמן ממיר בעל \"מלבושי יו\"ט\" ולמד עם נכדו-ר בצלאל לוין מלומזה, תלמיד ישיבות וולוזין, ראדין. חתן ר פיבל פרנק מאלקסוט והתקרב לחכמי המוסר. ר\"מ בסלובודקה-תרנד, הקים ישיבה בסלוצק-תרנז בהזמנת הרידב\"ז, רב בסלוצק-תרסג על מקום הרידב\"ז שעלה לצפת, עלה לירושלים-תרפה ועל מקומו בישיבת סלוצק - גיסו ר שבתי קרמר, ר\"מ בישיבת \"עץ חיים\" בירושלים. היה חבר ב\"אגודת מייסדי חדרה\" יחד עם גיסו ר משה מרדכי אפשטין. נשיא מועצת גדולי התורה של אגו\"י, וועד הישיבות. פרסם מאמרים ב\"כרם ציון\" - ירושלים תרצה-תשיג - קובץ \"מדרש בני ציון\", \"סיני\" - ירושלים תרצז, \"השער\" - בני ברק תשח.","bk":[["אבן האזל","מפרשי רמב\"ם"],["אבן האזל - רמב\"ם",""]],"e":"תר\"ל-תשי\"ד"},{"i":30912,"n":"מלצר, זלמן מויזון","bt":"תרסב","dt":"תשא","b":"רבה האחרון של ויזון על מקום ר אברהם כץ. נספה בשואה."},{"i":30913,"n":"מלצר, יצחק איזיק","f":"אברהם אשר","b":"דיין בווילקומיר-תק\"מ"},{"i":30914,"n":"מלצר, פיביש הכהן מהורודנקא","k":"בעל שירים ומאמרים","bt":"תרכו","bp":"הורודונקא","b":"מחכמי ברודושין. חיבר שירים ומאמרים בכתבי עת. פרסם מאמרים ב\"ישורון\" - ברלין תרף. נדפס ממנו שירים וספורים - חיפה תשמא."},{"i":30915,"n":"מלצר, צבי יהודה","f":"איסר זלמן מלצר","dt":"תשכט - טו תמוז","b":"רב פעלים,רב בפרדס חנה,רחובות"},{"i":30916,"n":"מלצר, שמואל אברהם מארה\"ב","k":"בעל אשדות הפסגה","b":"רב במיניאפוליס-ארה\"ב. חיבר \"אשדות הפסגה\" נ\"י תרצח. ?? לא באוצר ??"},{"i":30917,"n":"מלצר, שרגא פיבל","f":"איסר זלמן","bt":"1897","bp":"קובנא","b":"תלמיד ישיבת סלוצק, קלם, סלובודקה. עלה לארץ-1920 ולמד בביהמ\"ד למורים \"המזרחי\" בירושלים, תלמיד באונ' ברלין. פרסם מאמרים שונים, ומחקר אודות שירת ביאליק. פרופ' לתנ\"ך בישיבה אוניברסיטה בניו יורק, וב\"בר אילן\"."},{"i":30918,"n":"מלצר-שפר, אברהם מוארשא","f":"ישראל איסר גרוסגליק","dt":"תרכה - יז תמוז","b":"מקובל מחכמי וארשא. הניח חבורים בקבלה וחקירה."},{"i":30919,"n":"מלר, דוד מאשצעניצא","k":"בעל בשורות טובות","b":"מחכמי אשצעניצא, קאלא וגורליץ. חיבר \"בשורות טובות\" בילוגריא תרפז. ?? לא באוצר ??"},{"i":30920,"n":"מלר, יוליוס","bt":"1901","bp":"ליטא","b":"היגר לארה\"ב. מנהל \"מכון למחקר בעניני חינוך\" של \"אגוד הקהילות היהודיות\". פרופ' בניו יורק. חיבר ספרים באנגלית בנושאי חינוך ועוד."},{"i":30921,"n":"מלר, יצחק מבלגרד","k":"בעל עזרה להבין","bt":"תריז","bp":"קרמניץ","dt":"תרצא","b":"מו\"צ במנזיר-בסרביה-תרנז, רב בבאלגראד(בסרביה)-תרסה (האם בלגרד-סרביה?). פרסם מאמרים ב\"כנסת הגדולה\" - וארשא תרן, \"קבוצי אפרים\" - יאסי-בוקרשט תרעד."},{"i":30922,"n":"מלר, יצחק מזוולוב","f":"אליהו מסטניסלב","k":"בעל מנחת יצחק","b":"רב בזוולוב - בגיל 14, ברודי. חיבר \"מנחת יצחק\" זולקוא תקסה."},{"i":30923,"n":"מלר, ישראל מלבוב","b":"דיין בלבוב, חתם-תפח על העתק פס\"ד עם ר יעקב קופל בן אשר."},{"i":30924,"n":"מלר, ישראל מרוזדול","b":"מחכמי רוזדול.."},{"i":30925,"n":"מלר, ליפמן","k":"ליפמן גאון","b":"תלמיד ר יונתן איבשיץ."},{"i":30926,"n":"מלר, מאיר מפישטשאנקא","f":"זאב","k":"בעל ועד לחכמים","b":"שו\"ב בפישטשאנקא."},{"i":30927,"n":"מלר, מנחם מנדל מיסלו","k":"בעל המדבר בצדקה","b":"עסקן ביסלו. חיבר (עם אחרים) \"המדבר בצדקה\" טרנוב תרצה."},{"i":30928,"n":"מלר, נטע יונה מסטניסלב","f":"שמעון מפודהייץ","k":"בעל הדרת מלך","bt":"תרי","bp":"פודהייץ","dt":"תרעד","b":"רב בפודהייץ-תרלט על מקום אביו, סטניסלב, ושוב בפודהייץ. חיבר \"הדרת מלך\" קאלומעא תרמח."},{"i":30929,"n":"מלר, שמעון מפודהייץ","bt":"תקע","dt":"תרם","b":"נכד ר נתן נטע גליצר-קליצר מפודהייץ. רב בפודהייץ, סטניסלב. בנו ר נטע יונה על מקומו אחריו בשתי העיירות."},{"i":30930,"n":"מלר-גומן, ליפמן","b":"רב-שנת תק\"ל"},{"i":30931,"n":"ממלוך, צבי יהודה","b":"רב-שנת תר\"פ"},{"i":30932,"n":"ממלוק, אברהם הלוי מקאליש","f":"מרדכי","b":"מחכמי רוסעשטיץ. אחיו - ר צבי יהודה בעל אביר הרועים."},{"i":30933,"n":"ממלוק, יעקב מקאליש","k":"בעל עקב רב"},{"i":30934,"n":"ממלוק, צבי יהודה הלוי מקאליש","f":"מרדכי","k":"בעל אביר הרועים","b":"מחסידי סוכטשוב בקאליש. חיבר גם \"מלחמות יהודה\". אחיו - ר אברהם מרוסעשטיץ."},{"i":30935,"n":"ממן, יהושע מצפרו","f":"רפאל","b":"רב בצפרו, חתם-תש על קול קורא."},{"i":30936,"n":"מן","b":"מרביץ תורה בקרקא-ש\"ל"},{"i":30937,"n":"מן - מלכה, יעקב מקראקא","k":"בעל עפר יעקב","dt":"תרה - א חשון","b":"מגדולי חכמי קרקא"},{"i":30938,"n":"מן אורהולץ, נתן משטמפן","f":"מנחם","dt":"תקנב - כה תשרי","dp":"שטמפן","b":"תלמיד ר יונתן איבשיץ. חתן הגביר ר יצחק גיירינג (גיירונגער) משטאמפי. מקובל, מרביץ תורה בהמבורג, רב בשטמפן(=שטאמפא)-תקכב על מקום ר יצחק איזיק קאליש שעבר לטיפליץ, לאחר שחלה עבר לפרשבורג-תקנא. בזמן מחלוקת ר יונתן איבשיץ ור יעקב עמדן - נחשד ר נתן בשבתאות, הסכים לקבל את ר מרדכי עמדין בנו של ר יונתן - שגורש מפרשבורג - לקהלתו שטמפן, הוקם בי\"ד מיוחד שהכשירו מהחשד - הדיינים היו: ר משה המבורגר מעיר חדש, ר מאיר דייטש מדרזניץ, ר יעקב בן ישכר בר מניקלשבורג, ר יוסף סטיפיאו מסעמניץ, ור יוסף מל\"ב מויסבורג. בנו - שמואל באב\"ד, חתנו - ר אברהם טרך (דראך)."},{"i":30939,"n":"מן ההר, אברהם","k":"ר\"א","bt":"1240?","dt":"ע\"ה","b":"מגדולי הראשונים, הרביץ תורה במונפלייר(=מונטפלייר, מן ההר), דיין בקרפנטרץ-ס. חיבר חדושים על הש\"ס. חילופי מכתבים בינו לבין המאירי.","bk":[["ר' אברהם מן ההר","מפרשי ש\"ס - ראשונים"],["פירוש רבינו אברהם מן ההר",""]],"e":"ע\"ה [פטירה]"},{"i":30940,"n":"מן ההר, שלמה מספרד","f":"אברהם","k":"מונטפלייר","b":"רב במונטפליר-פרובנס-ד'תתקצב, ועבר לספרד, בן דורו של הרמ\"ה. מתלמידיו - ר יונה גירונדי ור דוד בר שאול. מגדולי החולקים על הרמבם, והטיל עם חבריו חרם על \"מורה נבוכים\" ו\"ספר המדע\" לרמבם."},{"i":30941,"n":"מן רקובסקי, יעקב מירושלים","b":"פרסם מאמרים ב\"תורה אור\" - ירושלים תשה."},{"i":30942,"n":"מן, אברהם מנחם מניו יורק","bt":"תרכו","dt":"תרפט - ה כסלו","b":"רב בניו יורק"},{"i":30943,"n":"מן, אהרן זעליג מירושלים","b":"מחכמי ירושלים, בשליחות באמריקה-תרח, ויסד חברת משמרת קודש לעזרה לקהילת הפרושים בירושלים. פנקס שליחותו נדפס - תרץ."},{"i":30944,"n":"מן, חיים מהורנסטייפל","f":"יעקב","bt":"תרכח","b":"רב בהורנסטייפל-פלך קיוב-תרנח על מקום אביו. נסמך מאת: ר שמריה לרנר מבערשאד, ר קלמן ברקוביץ מסאברן, ר נחום זאב טבטשניק מקריוויע, האדמור רמ\"ד מהורנסטייפל."},{"i":30945,"n":"מן, יעקב מהורנסטייפל","f":"יצחק מען","b":"רב בהורניסטופול-תרן על מקום אביו, ובנו ר חיים על מקומו אחריו."},{"i":30946,"n":"מן, יצחק איזיק מהמבורג","f":"מנחם","dt":"תנב - ה חשון","dp":"אלטונא","b":"דיין בהמבורג אצל ר זלמן מירלש."},{"i":30947,"n":"מן, יצחק מהורנסטייפל","b":"רב בהורנוסטופול-תרל ובנו ר יעקב על מקומו אחריו."},{"i":30948,"n":"מן, מאיר מלעמזאל","f":"יוסף","k":"בעל מאירי הלכה","b":"רב בלעמזאל, עלה לירושלים. חיבר גם \"פרי יוסף\", \"הידור מצוה\"."},{"i":30949,"n":"מן, מנחם","b":"מתלמידיו בעל \"ברכת טוב\" - שהביא מחדושיו."},{"i":30950,"n":"מן, מנחם מהמבורג","bp":"אלטונא","dt":"תרז - כה ניסן","dp":"אלטונא","b":"גבאי דרשן ומגיד בח\"ק באלטונא ומשגיח בת\"ת באלטונא כ-55 שנה. הגיה משניות דפוס אלטונא."},{"i":30951,"n":"מן, פיבל מסמטר","k":"חותן ר' עקיבא איגר","b":"רב בסמטר-תק\"נ"},{"i":30952,"n":"מן, צבי מבני ברק","b":"פרסם מאמרים ב\"תפארת ציון\" - בני ברק תשב - קובץ תלמידי ישיבת \"תפארת ציון\"."},{"i":30953,"n":"מנבי מרדכי צבי בן בנימין","bt":"1822","dt":"ה'תרסד 1904","bk":[["בית המדרש",""],["דרך הישרים",""],["מפתח האגדות",""],["ספר זכרון",""],["קרסי זהב",""]]},{"i":30954,"n":"מנבי, מרדכי צבי מבוברויסק","f":"בנימין","k":"בעל תהילה ותפארת","b":"מחכמי בוברויסק וכונה בשם \"הפרוש מבוברויסק\". חיבר גם קרסי זהב, ספר זכרון, ועוד. בניו - ר יהודה משה מהאלוסק (הו\"ל חלק מספרי אביו), ר שמעון דב בעל נאוה תהלה, נכדו - ר שמואל בן יהודה משה הו\"ל מספרי זקנו."},{"i":30955,"n":"מנבי, שמואל","f":"יהודה משה","k":"הו\"ל דרך הישרים","b":"נכד ר מרדכי צבי מבוברויסק, הו\"ל ספר זקנו."},{"i":30956,"n":"מנבי, שמעון דב מבוברויסק","f":"מרדכי צבי","k":"בעל מעשה וחשבון","b":"חיבר גם \"נאה תהילה\" על הגדה של פסח וילנא תרסב."},{"i":30957,"n":"מנג'ד, שלמה מחלב","b":"רב בחלב, נספד ע\"י ר יעקב עבאדי."},{"i":30958,"n":"מנגמי, רצון מתימן","f":"עמרם","k":"בעל עת רצון","bt":"תרמב","bp":"תימן","dt":"תשכד","dp":"רחובות","b":"דיין במחוז שרעב-תרסה. עלה לארץ-תרצב וכיהן כרב ברחובות. נודע לפועל ישועות ונתפרסמו ע\"י ר סעדיה חוזה."},{"i":30959,"n":"מנגן, יהושע מרומא","b":"רב ברומא בזמן בעל \"דבר שמואל\" המזכירו בספרו."},{"i":30960,"n":"מנגר, יצחק איציק","b":"משורר אידי. ניצל מהשואה ואחריה עלה לארץ."},{"i":30961,"n":"מנדהי, ששון מבגדד","b":"רב בבגדד-שנות ה-ת'."},{"i":30962,"n":"מנדילי, מנחם מאדרינופול","b":"מראשי עדת הקראים באדרינופול. בזמנו התירו לקראים לראשונה להדליק נר בערב שבת כמנהג היהודים."},{"i":30963,"n":"מנדיס, דניאל הרופא משלוניקי","b":"רופא בשלוניקי-שנות ה-ת'."},{"i":30964,"n":"מנדל, אברהם מוועטש","bp":"עלעשד","b":"תלמיד השב\"ס, ור מרדכי יהודה ליב וינקלר מהעלידא. חתן ר משה איבשיץ משוראן. שו\"ב בוועטש-תרסג."},{"i":30965,"n":"מנדל, וולף הירש מפרשבורג","b":"שופט היהודים - ראש הקהלה בפרשבורג-תקמג."},{"i":30966,"n":"מנדל, זאב וולף","dt":"תקעא","b":"רב בנאדיקערעש,עבר לאבאני"},{"i":30967,"n":"מנדל, זכריה יוסף","dt":"תקצה - יז אייר","b":"רב בפינטשוב"},{"i":30968,"n":"מנדל, חיים כץ מסטריזוב","b":"מחכמי סטריזוב-תרנט."},{"i":30969,"n":"מנדל, יהודה ליב ממעדיאש","f":"יעקב קופל צבי","bt":"תרג","bp":"בודפשט","dt":"תרפט - כו תמוז","dp":"מעדיאש","b":"תלמיד הכת\"ס, ור אהרן דוד דייטש מבאלש-ירמוט. חתן ר יהושע גרין מקיקלבורג, ועבר לשם. מראשי הקהלה במדיעש-תרמז."},{"i":30970,"n":"מנדל, יוסף זכריה","b":"דיין ומרביץ תורה בקרקא"},{"i":30971,"n":"מנדל, יחזקאל הלוי מירושלים","f":"ישראל משה מטעגלאש","b":"רב בירושלים. חתן ר שמעיה לעוו מסאקיי-קערעסטור."},{"i":30972,"n":"מנדל, יעקב יוסף מקראקא","f":"אריה ליב","dt":"תקצה - יז אייר","b":"דיין בקרקא"},{"i":30973,"n":"מנדל, יעקב קופל צבי מבודפשט","b":"הרב הראשון של הקהלה החרדית בבודפשט."},{"i":30974,"n":"מנדל, ישי הלוי (הורביץ) מהעדיל","dp":"טעגלאש","b":"מחכמי העדילא-מאדע. חתן ר שמואל ויילר מהעדילא-מאדא."},{"i":30975,"n":"מנדל, ישראל משה מטעגלאש","f":"ישי הלוי מנדל הורביץ","k":"בעל שפת הים","bt":"תרלד","bp":"העדילא-מאדע","dt":"תשה - יח ניסן","dp":"ברגן-בלזן","b":"תלמיד השב\"ס, ור שאול רוזנברג מרצפערט, ועוד. חתן ר יששאל זאב פנט מטעגלאש ועבר לשם והורה הוראה במשך כיובל שנים. נספה בשואה. מחדושיו ב\"שפת הים\" בתוך \"מפרי הגן\", וממכתביו ב\"וירא ישראל\". בנו ר יחזקאל הלוי מנדל מירושלים."},{"i":30976,"n":"מנדל, מנחם יעקב יוסף מקרלסבור","f":"יהושע","bp":"קרלסבורג","dt":"תקפג - כט טבת","b":"דיין בקרלסבורג-טרנסילבניה, רב המדינה בקרלסבורג-תקעח, והיה מחלוקת על כך בין הטוענים שקנה את הרבנות בכסף ואינו ראוי לה, ופנו על כך אל החת\"ס שדרש ממנו לעמוד במבחן אצל ר יהודה הלר בעל \"קונטרס הספיקות\" בסיגט, ר מנחם הסכים אך בעל \"קונטרס הספיקות\" נפטר בטרם הספיק, ואז פנה החת\"ס לקהלת קרלסבורג - וניסה לפייס בין הרב למתנגדיו."},{"i":30977,"n":"מנדל, מנחם סגל","f":"שמואל דוד","bt":"תרעג","dt":"תש..","b":"תלמיד ישיבת עץ חיים בבובוב. התכתב עם גדולי דורו (וביניהם הרוגצובר). חתן ר זישא בלויגרונד מלימנוב. נספה בשואה."},{"i":30978,"n":"מנדל, נתן מנחם מקראקא","f":"יהודה ליבוש","k":"בעל ילקוט נתן","bt":"תרמז","bp":"קראקא","dt":"תשל","b":"חניך ישיבות הונגריה, עבר לאנטורפן ולפני השואה הגיע לניו יורק. פרסם מאמרים בכתבי עת שונים. חיבר \"הגדה - ילקוט נתן\" ניו יורק תשיד, \"רעיונות נתן\" תשכא."},{"i":30979,"n":"מנדל, קופל מפרשבורג","b":"ממיסדי ביה\"ס בפרשבורג-תקף כנגד דעת החרדים."},{"i":30980,"n":"מנדל, שלמה ליב כץ","dt":"תרסב - כה תמוז","b":"דיין בקליינוורדיין. חתנו - ר יעקב שפירא מטערצל."},{"i":30981,"n":"מנדל, שמעון מנוי-טיטשין","bt":"תרכז","bp":"צעהלים","dt":"תרפד - יט אב","dp":"וינה","b":"תלמיד השב\"ס. חתן ר שמואל בק מליסא. רב בקאסטל (מעהרין)-תרנד, נוי-טיטשין-תרנט."},{"i":30982,"n":"מנדלבוים, אהרן משה ממארוש-ואשא","f":"בנימין זאב מסטמר","bt":"תרה או תרל","bp":"סטמר","dt":"תרעה-ח - ו אדר","dp":"בודפשט","b":"חתן ר משה נתן נטע יונגרייז מטיסא-פירד בעל \"מנוחת משה\". רב במארוש-ואשארהי(=ואשארהעלי)-תרמז. היה במחלוקת עם ראשי הקהל-תרסח (על כך בעתון \"המצפה\") - והשלטונות תמכו ברב והדיחו את ראשי הקהל, אולם לבסוף עזב את העיר ועבר לבודפשט, רב בית כנסת בבודפשט. פרסם מאמרים ב\"תל תלפיות\"."},{"i":30983,"n":"מנדלבוים, אריה ליב","dt":"תשג","b":"רב בגלובקי"},{"i":30984,"n":"מנדלבוים, בנימין זאב וולף","f":"שמואל","bt":"תקעה","bp":"באניהאד","dt":"תרנח - ג תשרי","dp":"סטמר","b":"תלמיד החת\"ס. חתן ר דוד הולנדר מבאטיז וכיהן שם כר\"מ בישיבה-תרג. רבה הראשון של סטמר-תרח (שנוסדה אז) ובתקופה הראשונה המשיך להתגורר אצל חותנו. מתורתו בספר תלמידו ר יעקב יוסף גרוס מבודפשט בעל \"תבואת יקב\"."},{"i":30985,"n":"מנדלבוים, ברוך מטוראוו וירושלי","f":"מרדכי יהודה ליב","k":"בעל נודע בשערים","r":"הרב מטורוב","bt":"תקצה","bp":"רוסיה","dt":"תרסה - יז אייר","dp":"ירושלים","b":"מצאצאי הב\"ח. תלמיד ר אהרן מקרלין ובנו ר אשר. רב בטורוב בסטולין ובמאצאב, בשנת תרלד עלה לירושלים והקים ישיבת \"אור חדש\". בשנת תרנא בשליחות. חיבר \"נודע בשערים\" ו\"קץ הימין\" ירושלים תרסד. בנו - ר שמחה מירושלים.","bk":[["נודע בשערים - שו\"ת",""]]},{"i":30986,"n":"מנדלבוים, יעקב דב מניו יורק","b":"הכין מפתח ל\"שערי תורה\" - וארשא תרסג-תרצט, ע\"י המכון לחקר בעיות היהדות החרדית בנ\"י-תשלו."},{"i":30987,"n":"מנדלבוים, מרדכי יהודה ליב","b":"תלמיד ר אשר מסטולין. אב\"ד ולאדאווקא. בנו ר ברוך מטוראוו."},{"i":30988,"n":"מנדלבוים, משה מאיר","b":"פרסם מאמרים ב\"תלפיות\" - שנחאי תשו."},{"i":30989,"n":"מנדלבוים, עזריאל אליעזר","f":"משה דוד","bt":"תרס","dt":"תשב","b":"חתן ר גדליה צבי צינץ מלימנוב. חסיד בובוב ור\"מ בישיבת בובוב. מלחין ניגונים. נספה בשואה."},{"i":30990,"n":"מנדלבוים, שמחה מירושלים","b":"חתם עם ראיש מוסדות וממוני הכולל בירושלים-תרע-ף בערך."},{"i":30991,"n":"מנדלביץ, משה יהודה מראצפרט","b":"תלמיד ר שמואל דוד אונגר בישיבת טירנוי. פרסם מאמרים ב\"הלכות החדש\" - טירוני תרצא - קובץ מאת תלמידי ר שמואל דוד אונגר מטירנוי, \"משא ומתן\" - טירנוי תרצא."},{"i":30992,"n":"מנדלוביץ שניאור זלמן","bt":"1804","dt":"ה'תרמו 1886","bk":[["עבודת ה'",""]]},{"i":30993,"n":"מנדלן, דוד זכריה","b":"מחותן עם השל\"ה - בניו - ר חיים פיבל מבומסלא-חתן השל\"ה, ר יצחק מסמיאטיש."},{"i":30994,"n":"מנדלן, נפתלי","f":"זכריה מנדלן","k":"בעל סדר השלחן","b":"רב-שנת ש\"ס"},{"i":30995,"n":"מנדלס, אלעזר","f":"זכריה מנדל","b":"רב בלבוב"},{"i":30996,"n":"מנדלס, הירש","b":"ראש חכמי הדור,רב בלבוב-תמ\"ג,רב בלובלין"},{"i":30997,"n":"מנדלס, יוסף שלמה","f":"מנדל מפוזנא","k":"רבי מנדלס מפוזנא","b":"רב פעלים מפוזנא-שנת ת'"},{"i":30998,"n":"מנדלסון, אברהם דב בריש מוארשא","f":"יקיר בן שמואל צבי","k":"בעל דברי אברהם","b":"רב בוארשא."},{"i":30999,"n":"מנדלסון, אליהו פסח","f":"מנחם מנדל","b":"יסד חברה הכנסת אורחים במיטאוי-תרכו, יחד עם מאיר בן אליעזר זערץ מבריינסק."},{"i":31000,"n":"מנדלסון, אשר מפולין","b":"מראשי אגודת ישראל בפולין, חתם לאחר מהר\"ם שפירא מלובלין."},{"i":31001,"n":"מנדלסון, בונם זאב מוארשא","k":"בעל תרומת זהב","r":"מו\"ץ בוורשא","bt":"תקפד","dt":"תרלו - ל חשון","b":"מרביץ תורה ומו\"צ בוורשה","bk":[["תרומת זהב - עה\"ת וששה סדרי משנה",""]]},{"i":31002,"n":"מנדלסון, יהודה ליב מוארשא","f":"רא\"מ","k":"בעל אמונת זרעים","b":"רב בוארשא."},{"i":31003,"n":"מנדלסון, יהודה מלונדון","f":"מנחם","bt":"תרכט","bp":"שילעל","b":"תלמיד ביהמ\"ד לרבנים בלונדון, ובעל תואר ד\"ר. חתן ר יצחק נתן קפילוביץ ממינסק. רב בלונדון-תרנ."},{"i":31004,"n":"מנדלסון, יהושע השל","b":"רב בווינאווי-תר\"ל"},{"i":31005,"n":"מנדלסון, יעקב בן ציון הכהן","b":"רב בגלאזגו-סקוטלנד-תרעה."},{"i":31006,"n":"מנדלסון, יעקב בן ציון מאנגליה","f":"מנחם הכהן","k":"בעל שערי ציון","bt":"א' דסוכות תרלו","dt":"יא מנחם אב תשא","b":"תלמיד ישיבת יאקובשטט, דוינסק, איישישוק, ר בנימין ליב מקריזבורג, ר שמעון מקריזבורג. מו\"צ בלידס-אנגליה-תרסא, רב בגיטסהד-תרסד, גלזגו-תרסו, ניו יורק. פרסם מאמרים ב\"בית ועד לחכמים\" - לונדון תרסב. נסמך מאת: ר אליהו פוסק, ר עקיבא הכהן מאטלין. היה במחלוקת נגד ר\"י קנביץ ונזכר בספר \"משנת יעב\"ץ\" בקונטרס דברי ריבות.","bk":[["דברי ריבות - מחלוקת על הרבנות",""],["מדרש יעבץ - בראשית",""],["משנת יעבץ - חגיגה",""],["צייד - כיסוי הדם",""],["שערי ציון - חידושים על תשע מסכתות",""]]},{"i":31007,"n":"מנדלסון, יעקב זלמן","b":"רב-שנת תק\"צ"},{"i":31008,"n":"מנדלסון, יקיר מוארשא","dt":"תשג","b":"מרבני וורשה"},{"i":31009,"n":"מנדלסון, מנדל מירושלים","f":"יונה ליב","bt":"תר","bp":"ירושלים","dt":"תרץ - כד שבט","dp":"ירושלים","b":"מחכמי ירושלים."},{"i":31010,"n":"מנדלסון, משה מדעסוי וברלין","k":"בעל ביאור לתנ\"ך","b":"ר פנחס הורביץ בעל ההפלאה מפפד\"מ יצא כנגד הביאור-תקמב - בגלל הביאור לפסוק \"הוכח תוכיח את עמיתך\" שמנדלסון ביארו - \"אם פגע בך קודם\" (שפירושו - שאיש בשרירות לבו ילך ואין להוכיחו)."},{"i":31011,"n":"מנדלסון, משה מהמבורג","f":"מנחם מנדל פרנקפורטר-","k":"בעל פני תבל","bt":"תקמב","bp":"המבורג","dt":"תרכא - כז סיון","dp":"המבורג","b":"תלמיד ר נפתלי הרץ ויזל, מחכמי המבורג, בקי בדקדוק, משורר ומליץ. פעל נגד הריפורמים בהמבורג-תקפט. חיבר הקדמה למחזורי אלטונא, פרסם מאמרים במאספים. חיבר גם \"מציאת הארץ החדשה\", \"שושן עדות\", ועוד. רצה לתרגם ספר בן אחיו - ר שמשון רפאל הירש לעברית אך הרש\"ר סירב."},{"i":31012,"n":"מנדלסון, עזריאל אפרים","f":"יעקב זלמן מנדלסון"},{"i":31013,"n":"מנדלסון, צבי הירש","dt":"תרכ - ג תשרי","b":"מגדולי חכמי וורשה"},{"i":31014,"n":"מנדלסון, צבי הירש מויזניץ","b":"פרסם מאמרים ב\"קובץ דרושים\" - פיעטרקוב תרפג."},{"i":31015,"n":"מנדלסון, ראובן מירושלים","f":"מנחם מנדל","dt":"תרמב - ט שבט","dp":"ירושלים","b":"שו\"ב בירושלים."},{"i":31016,"n":"מנדלסון, שמואל","bt":"1850","bp":"שילאל","b":"תלמיד ביהמ\"ד לרבנים בוילנא, למד בברלין ופילדלפיה. רב בנורפולק, וילמינגטון-צפון קרולינה. פרסם מחקרים ב\"הצופה\", וכתב עת שונים. וספרים באנגלית בנושאי יהדות."},{"i":31017,"n":"מנדלסון, שמואל דוד מאנגליה","b":"רב בלידז(אנגליה)-תרפ. פרסם מאמרים ב\"שערי ציון\" - ירושלים תרפא."},{"i":31018,"n":"מנדלסון, שמואל הלוי מקרוטושין","f":"ר\"מ","k":"בעל דבר שמואל","b":"רב בקראטשין(=קרוטושין)-תקצה."},{"i":31019,"n":"מנדלסון-לבל, יונה ליב מפרשבורג","f":"יהודה ליב מיאקא ופרש","bt":"תקעו","dt":"תרמו - ל ניסן","dp":"ירושלים","b":"תלמיד החת\"ס. עלה לירושלים-תקצו (בעצת החת\"ס - שעזר לפרנסתו). חתן ר יהושע ממינסק (שנהרג ברעש בצפת-תקעז). ממייסדי כולל אונגרין, ויצא לשליחות הכולל בחו\"ל. אבי משפחת מנדלסון בירושלים."},{"i":31020,"n":"מנדלקורן, שלמה","k":"בעל הקונקורדנציה","bt":"תרח","dt":"תרסב","dp":"וינה","b":"היה מקורב לבנו של האדמור מקוצק, פנה להשכלה, רב מטעם באודסה (הרב הראשון שהטיף ברוסית)."},{"i":31021,"n":"מנדלשטם, אריה ליב (ליאון)","f":"יוסף בן אברהם אריה","k":"בעל אלף בית-חנוך נער","bt":"1809","bp":"ז'אגר","dt":"1889","dp":"פטרבורג","b":"תלמיד אוני' פטרבורג והיהודי הראשון שקיבל תואר מדעי בפילולוגיה. מזכיר בועידת הרבנים בפטרבורג-1843, עבד במשרד החינוך ברוסיה בביצוע תכניות ועדת הרבנים אולם פעולותיו היו שנויות במחלוקת ולא נתקבלו ע\"י רוב הציבור. עבר לגרמניה. בעל ספריה גדולה שנמכרה אחר פטירתו לספריה הציבורית בניו יורק. תרגם את התנ\"ך לרוסית. חיבר ברוסית \"להגנת היהודים\" 1858, ועוד."},{"i":31022,"n":"מנדלשטם, בנימין","f":"יוסף בן אברהם אריה","k":"בעל חזון למועד","bt":"1800","bp":"ז'אגר","dt":"1886","dp":"סימפרופול","b":"חתן ר מנחם מנדל מזאגר חדש. מראשי המשכילים ברוסיה. עבד כ-40 שנה בשירות משפחת הברון גינצבורג. חיבר גם \"פאריס\" - ויהודיה, \"משלי בנימין\", ועוד. פרסם ב\"המגיד\". מכתב אליו מר מנדלי מלובאויטש. לזכרו \"כנסת ישראל\" לר שפ\"ר - וארשא תרמו."},{"i":31023,"n":"מנדלשטם, יוסף","bt":"1846","bp":"ז'אגר","dt":"1910","b":"חוקר וסופר. התנצר והיה פרופ' לרוסית בהלסינגפורס. חיבר ברוסית \"מיתולוגיה של יהודים\", \"אורבך כאדם, סופר, יהודי ואזרח\". אחיו של מכס עמנואל."},{"i":31024,"n":"מנדלשטם, יחזקאל מוילנא","f":"יוסף בן אברהם אריה","k":"בעל באור על תנ\"ך","bt":"תקעב","dt":"תרנא - ו ניסן","dp":"פולטבה","b":"חיבר ספר השמות מהתנ\"ך והוא חלק שני מקונקורדנציה לר יהודה ליב שוסלביץ משקלוב."},{"i":31025,"n":"מנדלשטם, מכס עמנואל","bt":"1839","bp":"ז'אגר","dt":"1912","dp":"קיוב","b":"רופא עינים מפורסם ולא נתמנה לפרופ' בגלל יהדותו. דודיו ליאון ובנימין שהטיפו להתבוללות, ואילו הוא שקיבל חינוך חילוני הצטרף לחובבי ציון, ועם הופעת הרצל ברוסיה הצטרף לתנועה הציונית. מאישיה המרכזיים של יהדות רוסיה."},{"i":31026,"n":"מנה, מרדכי צבי","k":"בעל כל כתבי","bt":"1859","bp":"רדושקביץ","dt":"1886","dp":"רדושקביץ","b":"למד אומניות בוילנא ופטרבורג וקיבל אות הצטיינות ע\"י הנסיך הגדול ולדימיר. חיבר שירים שיצאו לאור אחר פטירתו בשם \"כל כתבי מרדכי צבי מאנע\" וארשא תרנז."},{"i":31027,"n":"מנהיים, זלמן מהמבורג","b":"דיין בהמבורג-ת\"ר"},{"i":31028,"n":"מנהיים, חיים מפפד\"מ","f":"וולף","dt":"תק - יא תמוז","dp":"פפד\"מ","b":"מחכמי פפד\"מ."},{"i":31029,"n":"מנהיים, יעקב מאדא","b":"דומ\"צ באדא-תרל\"ז"},{"i":31030,"n":"מנהיים, משה מדברצין","b":"פרסם מאמרים ב\"אהל שם\" - רומניה תשב - תשה."},{"i":31031,"n":"מנהיים, נתן נטע האגני מירושלים","f":"יהודה ליב","dt":"תקג","dp":"מנהיים","b":"רבה של הגנוי, עלה לירושלים בשיירת ר יהודה החסיד, וחתם עם חכמי ירושלים על מכתב לברסא בשנת תסד. בשנת תסז בשליחות במצרים באיטליה ובאשכנז. הדפיס בפרנקפורט בשנת תסט ספר \"מאורי אור לר מאיר פאפירש עם פירוש שלו ושל ר יעקב וילנא בשם \"מאורות נתן ויאיר נתיב\". הצטרף לבית המדרש במנהיים, וכן למד בריגיו אצל ר בנימין הכהן."},{"i":31032,"n":"מנהיים, שמואל ממיץ","b":"מתורתו ב\"תל תלפיות\" - וייצען תרנב-תרעד."},{"i":31033,"n":"מנהיימר, דוד יהודה ליב מפישטאן","b":"תלמיד החת\"ס. רב בפישטיאן-תקעד."},{"i":31034,"n":"מנהיימר, חיים צבי מאונגוואר","f":"דוד יהודה ליב","k":"בעל עין הבדלח","bt":"תקעד","bp":"פישטיאן","dt":"תרמו - יז תמוז","dp":"אונגוואר","b":"תלמיד החת\"ס, ור יעקב קאפל מוערבא, ור בנימין זאב לעוו מוערבא. חתן ר אברהם מגרופא ועבר לשם, ובזיוו\"ש חתן ר יעקב מאיר צבי פרידלנדר משוראן. רב בשטמנסדורף-תריב, וערבא-תרכך, אונגוואר-תרל. פרסם מאמרים ב\"וילקט יוסף\" - מונקטש-פאקש-בוניהאד תרנט-תרעז, \"החיים\" - אונגואר תרפב, \"הנשר\" - טירנוי תרצג-תשד, \"תל תלפיות\" - וייצען תרנב-תרעד.","bk":[["עין הבדלח - שו\"ת וחידושים על סוגיות הש\"ס",""]]},{"i":31035,"n":"מנהיימר, יצחק איציק קצנלנבוגן","f":"צבי הירש מפאלץ","b":"נכד ר מרדכי מוכיח מפרשבורג. נכדו - ר נתן נטע מצאנץ ופרשבורג."},{"i":31036,"n":"מנהיימר, יצחק מפישטיאן","f":"דוד יהודה ליב","b":"תלמיד החת\"ס. חתן נכדת ר שמואל קעלין בעל \"מחצית השקל\". מחכמי פישטיאן."},{"i":31037,"n":"מנהיימר, יצחק נח","k":"בעל מי נח","bt":"תקנד","bp":"קופנהגן","dt":"תרכה - כ אדר","b":"רב ודוקטור לפילוסופיה, מורה בקופנהגן, דרשן ורב בוינה על מקום יו\"ט צונץ, פעל נגד הריפורמים. כמה מדרשותיו נדפסו בתרגום עברי בשם \"מי נח\" ע\"י אפרים קוטנר."},{"i":31038,"n":"מנואה, אליהו מרומא","b":"מחכמי רומא-ש'. תשובה ממנו ב\"פחד יצחק\"-שלג."},{"i":31039,"n":"מנואל, צבי נתן מדרוהוביטש","f":"אליעזר","k":"בעל ישראל והזמנים","bt":"תרן","bp":"לעטנע","dt":"תשכה","b":"נכד המגיד מזלוטשוב והנודע ביהודה. תלמיד ר שמעון גרינפלד מסעמיהאלי, ישיבת חוסט, אצל האדמור מויזניץ, ר יוסף פאנצער מדרוהוביץ, ר אשר לוי ממעיניץ, ישיבת אור תורה בסטניסלב. נסמך מאת: ר מאיר אריק מבוצאץ, ר דוד הורביץ מסטניסלב, ר בנימין וייס מטשרנוביץ, ר חיים הלר. חתן הגביר ר אהרן ענגלמן מבויאן. רב קהלת \"אנשי דת וצדק\" בוינה-תרעט, עבר לארה\"ב-תרפא ושימש כרב בניו יורק, היה גם מנהל ישיבת \"תפארת ירושלים\" בניו יורק. פרסם מאמרים ב\"הלבנון\" - סטמר תרפח, \"המגיד\" - סטמר תרפח-תרצט."},{"i":31040,"n":"מנוח","f":"אשר","b":"רב בזמן מהרמא\"י-שיא שהביא ממנו בספרו. העיד אודות גט שסידר ר הירץ מפרשבורג."},{"i":31041,"n":"מנוח הנדל הלוי מבלז","b":"מחכמי בלז, שו\"ב בברודי."},{"i":31042,"n":"מנוח מנרבונא","k":"בעל ספר המנוחה","b":"מגדולי הראשונים בפרובנס, מרביץ תורה בנרבונא-ק\"ס"},{"i":31043,"n":"מנוח מפרובנס","k":"בעל ספר המנוחה","b":"מגדולי הפוסקים בחכמי פרובינצא בנרבונא-שנת ל'"},{"i":31044,"n":"מנוסזון, אברהם משה דב בר","f":"מנוש","k":"בעל מערכי אדם","bt":"תרכח","bp":"וילנא","dt":"תרצו - ל אב","b":"תלמיד קבוץ איישישוק, קובנא. נסמך מאת: ר דוד צבי חן מצרניגוב, ר זאב וולף וייל מקיוב. מו\"צ בקיוב-תרנט, סודנוב?, סעדילוב-ליד צרניגוב, גרימסבי-אנגליה, גייטסהד-תרפח."},{"i":31045,"n":"מנור ן, יצחק מספרד","f":"יוסף","k":"בעל בארות יצחק","b":"מחכמי ספרד בדור ה-11, תלמיד הריטב\"א. בנו ר יוסף היה מתלמידי הריב\"ש."},{"i":31046,"n":"מנור ן, שם טוב מתורכיה","b":"רב בתורכיה בזמן ר יוסף קארו."},{"i":31047,"n":"מנזלי, יוסף מצנעא","f":"דוד","bt":"תקסד","bp":"צנעא-תימן","b":"דיין בצנעא-תימן-תרד כ-40 שנה."},{"i":31048,"n":"מנזלי, שלום מתימן","b":"מחכמי צנעא - בסוף המאה ה-19. למד בחברותא עם ר יחיא קאפח."},{"i":31049,"n":"מנחם","b":"תלמיד ר אליעזר מגרמיזה. חיבר ספרי קבלה על \"עשר ספירות\", ביאורי פסוקים על דרך הקבלה, ועוד - בכת\"י."},{"i":31050,"n":"מנחם אהרן מנייטרא","b":"דומ\"צ בנייטרא-תק\"צ"},{"i":31051,"n":"מנחם אליעזר מארץ ישראל","f":"ישראל","b":"אחיו של ר משה מקוברין. עלה לארץ-תקצג והיה מראשי הכולל - חתם ראשון על מסמכי הכולל."},{"i":31052,"n":"מנחם אליעזר מוילנא ומינסק","f":"לוי-בעל עטרת ראש","k":"בעל יעיר קינו","bt":"תקיט","bp":"וילנא","dt":"תקסז-עז - ד טבת","dp":"מינסק","b":"חתן ר ישראל ממינסק (כך באוצר הרבנים ואצל איזנשטין-מינסק ולפי מרקוביץ-ראסיין היה חתן ר זאב וולף מראסיין-בן ר שמואל מפלונגיאן). מגדולי חכמי וילנא בזמן הגר\"א, אחר פטירת הגר\"א נתבקש ע\"י תלמידיו לפרש את הערותיו לשו\"ע - התחיל בכך אך לא השלים את המלאכה. מרביץ תורה במינסק. חיבר \"יעיר קינו\" על פירוש הרא\"ש למסכת קינים ועליו אמר הגר\"א \"נראה שרק לו נתן ה' להבין פירוש מסכת קשה זו וכו'\". בנו - לוי דוד גינסטלינג. חתנו - ר שלמה גולדברג בן ר שמואל דוד מסמחוולעויטש. גיסיו - ר דוד בן אליהו מראסיין, ר אליהו מריטובה, ר שמואל חסיד מראסיין. לפי פין היה חתן הגביר ר מנחם נחום קופילוביץ מואשלישוק."},{"i":31053,"n":"מנחם אריה הלוי מירושלים","f":"שמואל","dt":"תקצט","dp":"ירושלים","b":"מחסידי חב\"ד בחברון. מחכמי ירושלים, בשנת תקפו חתם עם חכמי ירושלים. חתם על כתב שליחות-תקצד."},{"i":31054,"n":"מנחם החברוני","f":"פרץ","b":"נוסע שביקר בארץ-ד'תתקעא, והיה ש\"ץ בחברון 8 שנים, קפריסין, תיאר את קהלת הקראים בירושלים."},{"i":31055,"n":"מנחם הכהן מאלטונא","f":"דוד מאלטונא","dt":"תסט","dp":"אלטונא","b":"מחכמי אלטונא."},{"i":31056,"n":"מנחם הכהן מהנאו","f":"דוד","dt":"שפז","dp":"הנאו","b":"רב בהנאו, בנו - ר דוד-ראב\"ד באה\"ו."},{"i":31057,"n":"מנחם הכהן מונציה","f":"יצחק","b":"רב בונציה. הגן על הרב מן - בזמן המחלוקת כנגדו - יחד עם ר משולם הלוי - כמובא בתשובות מהרמא\"י."},{"i":31058,"n":"מנחם הכהן ממצרים","b":"רב במצרים בזמן ה\"דרכי נועם\", ו\"גינת ורדים\", ור משה ויטאל ור ישראל רומנו. ונזכר ב\"מנהגי מצרים\". חתם על הסכמה לר משה סרגוסי עם ר יעקב בירב, ר ישראל רומנו ור יהודה הכהן."},{"i":31059,"n":"מנחם הכהן מקאשטוריאה","f":"חיים מקאשטוריאה","b":"דיין בקאשטוריאה-תע - בזמן כהונת אביו כרב הכולל, עם ר יצחק אלבוחר ור יצחק בן חיים בנבנישתי."},{"i":31060,"n":"מנחם הכהן משלוניקי","dt":"שן - כז כסלו","dp":"שלוניקי","b":"מחכמי שלוניקי."},{"i":31061,"n":"מנחם הכהן משלוניקי ומצרים","b":"גביר מחכמי שלוניקי-שנות ה-ת', עבר למצרים. מתורתו ב\"דרכי נעם\"."},{"i":31062,"n":"מנחם הלוי מאישטיפי","b":"רב באישטיפי-תק אצל ר ברוך יוחנן עשאל."},{"i":31063,"n":"מנחם הלוי מבוסניה וירושלים","dt":"תקצט - ח כסלו","dp":"ירושלים","b":"עלה לירושלים והיה פקיד הכולל. חתם עם ר שלמה משה סוזין-תקפו, תקפט."},{"i":31064,"n":"מנחם הלוי משלוניקי","k":"בעל לקוטי מנחם","b":"רב בשלוניקי - בשנות ה-ש."},{"i":31065,"n":"מנחם המכירי","f":"מכיר","b":"מגדולי הפוסקים בחכמי אשכנז,מרביץ תורה במגנצא-ד'תתנ\"ו"},{"i":31066,"n":"מנחם זונדל מאיוועניץ","k":"מנחם מנדל מלובץ","b":"חתן ר אליעזר שפירא מלויביטש(=לובץ). אב\"ד איוועניץ. נפטר צעיר. בנו - ר אריה ליב שפירא מקובנא."},{"i":31067,"n":"מנחם חיים מחוגריה-תימן","b":"דיין בחוגריה-תימן בתחילת המאה ה-20."},{"i":31068,"n":"מנחם חלבו","b":"מראשוני מפרשי המקרא בפרובינצה שבצרפת-ד'תת\"נ"},{"i":31069,"n":"מנחם חסיד משפיירא","b":"מגדולי חכמי שפירא-ד'תתקנ\"ו"},{"i":31070,"n":"מנחם טוביה מפיראטין","b":"מגדולי תלמידי ר מנחם מנדל מליובאויטש, בנו ר יהודה ליב ונכדו ר שלמה זלמן מקפוסט. רב ברציצא. מחדש בתורת חב\"ד ור הלל מפאריטש מזכירו בספריו."},{"i":31071,"n":"מנחם יהודה הכהן","b":"דיין ביאנינה-תמה."},{"i":31072,"n":"מנחם יהודה מאלחביל-תימן","b":"רב באלחביל-דרום תימן-תרעא."},{"i":31073,"n":"מנחם מאויבן","f":"צבי אלחנן בן איציק","b":"דיין באויבן-תקמב."},{"i":31074,"n":"מנחם מאוסטרהא","f":"אליעזר","dt":"רה - טו שבט","dp":"אוסטרהא","b":"מחכמי אוסטרהא."},{"i":31075,"n":"מנחם מאיטליה","f":"שלמה","k":"בעל שכל טוב","b":"מחכמי איטליה הקדמונים-ד'תתק\"ג. חיבר \"שכל טוב\", \"אבן בוחן\", פירוש על קהילת - המבורג תקכד."},{"i":31076,"n":"מנחם מאיטליה","f":"שבתי","b":"מחכמי איטליה, עלה לארץ בזמן הרדב\"ז, הובא ב\"אבקת רוכל\", וב\"בנימין זאב\"-רפב."},{"i":31077,"n":"מנחם מאניש","f":"מאיר","k":"חתן הש\"ך","b":"חתן הש\"ך. מגדולי חכמי דורו, הגלה בשנת ת\"ח, הדפיס את ספר חותנו הש\"ך-תכג. בניו ר פנחס אב\"ד לבוב, ר שמשון מזולקוא."},{"i":31078,"n":"מנחם מאניש מזולקוא","b":"ראב\"ד ומגיד בזולקוא אצל ר נפתלי הרץ הורביץ, הסכים על \"ברכת יוסף\" זולקוא תקז, נזכר בספר \"אדני פז\"."},{"i":31079,"n":"מנחם מאניש מירושלים","b":"רב עדת האשכנזים בירושלים-שפב וכאשר הגיע השל\"ה אז לירושלים העביר לו את כס הרבנות."},{"i":31080,"n":"מנחם מאניש מלבוב","f":"יוסף","dp":"לבוב","b":"מג\"מ, ראב\"ד בלבוב."},{"i":31081,"n":"מנחם מאניש מלובלין","dt":"תב - ה שבט","b":"דיין בלובלין."},{"i":31082,"n":"מנחם מאניש ממזבוז","dt":"תקנה","b":"תלמיד הבעשט, ונקבר לידו."},{"i":31083,"n":"מנחם מאניש מסוקולוב","b":"רב בסוקולוב-תרלה, טרנופול."},{"i":31084,"n":"מנחם מאניש מסעלץ","b":"תלמיד בעל פרי מגדים. רב בסעלץ-שנות ה-תקס' ובנו ר חיים על מקומו אחריו. חברו של בעל 'אפיקי יהודה', נזכר בשו\"ת בנין עולם לר איזיק חבר."},{"i":31085,"n":"מנחם מאניש סגי נהור","b":"רב-שנת תק\"מ"},{"i":31086,"n":"מנחם מאנש מוילנא","f":"טודרוס","k":"ר מאנש גוטקע טויבעס","dt":"תקעו - יח תשרי","dp":"וילנא","b":"מחכמי וילנא."},{"i":31087,"n":"מנחם מגזילי","f":"משולם","b":"רב בגזילי-ליד תירייא - בדור שלאחר הגירוש."},{"i":31088,"n":"מנחם מגירונדי","b":"רב בגירונדי-ספרד. תלמיד ר יצחק סגי נהור."},{"i":31089,"n":"מנחם מדובניצה","f":"אברהם","b":"מראשי קהלת דובניצה-שנות ה-ת'-תק'."},{"i":31090,"n":"מנחם מדרהטשין","f":"אליהו צבי מדרהטשין","b":"רב בדרהטשין על מקום אביו."},{"i":31091,"n":"מנחם מוארשא","b":"מגדולי הראשונים-ק\"ז"},{"i":31092,"n":"מנחם מויזון","f":"אריה","dt":"תקסט - יז תמוז","b":"רבו של גר הצדק הגרף פוטוצקי, ולמד אתו בביהמ\"ד באיליא-ליד וילנא, נאסר לאחר הלשנה, ונהרג עק\"ה. לזכרו תפלה בסדור כ\"י בוילנא."},{"i":31093,"n":"מנחם מורמייזא","dt":"ד'תתקסג -ג אייר","b":"מגדולי הראשונים בחכמי אשכנז,פוסק,פייטן,מרביץ תורה בוורמייזא"},{"i":31094,"n":"מנחם מזאמוטש וירושלים","f":"אברהם","b":"מחכמי ארץ ישראל וירושלים-תקץ, בשליחות באירופה - הביא עמו עפר מאה\"ק ושקלו זהב כנגדו. רבו של ר יוסף זאמירו בעל \"עין יוסף\"."},{"i":31095,"n":"מנחם מטריקולה","f":"שבתי","b":"רב בטריקולה-שנות ה-ש'."},{"i":31096,"n":"מנחם מיואני","f":"פרץ מיואני","dt":"ד'תתקמא","b":"מגדולי הראשונים בבעלי התוספות,מרביץ תורה ביואני"},{"i":31097,"n":"מנחם מירושלים","f":"יצחק","dt":"תרנח - א סיון","b":"רב ומחנך בירושלים, בשליחות קהלת ירושלים לצורך ארבעת בתי הכנסת שנבנו קודם לכן."},{"i":31098,"n":"מנחם מירושלים","f":"מאיר","dt":"תריא - כב תשרי","dp":"ירושלים","b":"מחכמי ירושלים."},{"i":31099,"n":"מנחם מירושלים (מיוחס)","f":"יוסף","dt":"תקיח - אחרי","b":"מחכמי ירושלים-תקיד מלומדי \"בית אל\", תלמיד ר שלום שרעבי, והיה מסדר הרשימה. וחתום בשטר התקשרות משנת תקיב. בשליחות בחו\"ל-תקיח ונפטר בשליחותו."},{"i":31100,"n":"מנחם מלבוב","f":"יצחק","dt":"תכד - ח אייר","dp":"לבוב","b":"ר\"מ בלבוב. נהרג עק\"ה."},{"i":31101,"n":"מנחם ממיזיתרה","f":"שלמה","b":"רב במיזיתרה-מוריאה, קושטא-ש'."},{"i":31102,"n":"מנחם ממירזבורג","k":"בעל מעיל צדק","b":"מגדולי הפוסקים מחכמי אשכנז במירזבורג מדינת זקסן-ק\"מ,ביטל המיאון. חיבר \"מעיל צדק\"."},{"i":31103,"n":"מנחם ממצרים","f":"יצחק בר ששון הדיין","b":"מחכמי מצרים בדור שלאחר הרמבם."},{"i":31104,"n":"מנחם מן (מנלי) מקרלין","b":"תלמיד המגיד ממזריטש. קירב את אחיינו - ר אהרן הגדול מקרלין - לחסידות, והביאו אל רבו המגיד. בנו ר יעקב-חתן ר צבי בן הבעשט."},{"i":31105,"n":"מנחם מן הלוי","k":"בעל שארית ישראל","b":"חיבר \"שארית ישראל\" - פיורדא תקכז."},{"i":31106,"n":"מנחם מן הלוי מאמשטרדם","f":"שלמה","b":"מגיה באמשטרדם."},{"i":31107,"n":"מנחם מן מוילנא","f":"גרשון","b":"מראשי קהלת וילנא, חתם-תמו על תקנות."},{"i":31108,"n":"מנחם מן מזולקוא","f":"יוסף יוזפא","b":"מחכמי זולקוא, חתם-תפד על תקנה שלא אחד מקרובי הרב בתוך מנהיגי הקהלה."},{"i":31109,"n":"מנחם מנדל","b":"רב-שנת תק\"כ"},{"i":31110,"n":"מנחם מנדל","dt":"תקכח - כה חשון","b":"רב באסטריך-תר\"מ"},{"i":31111,"n":"מנחם מנדל","f":"יעקב","k":"מאה\"ו","b":"דיין באה\"ו. חתם בהמבורג-תקמט על החרם כנגד הספר \"מצפה יקותיאל\" - שפנה נגד ר רפאל הכהן מהמבורג."},{"i":31112,"n":"מנחם מנדל","f":"יארא","k":"בעל ילקוט מנחם","b":"חיבר גם \"קהלת מנחם\", \"דרשות מנחם\", \"מסורת מנחם\", ועוד."},{"i":31113,"n":"מנחם מנדל ביאלא","f":"יחיאל","k":"בעל זכרון מנחם","b":"רב בביאלא."},{"i":31114,"n":"מנחם מנדל הכהן מראווא","b":"רב בראווא."},{"i":31115,"n":"מנחם מנדל הלוי מוילנא","f":"הלל הלוי","dt":"תקלה - ג אב","b":"דיין בווילנה"},{"i":31116,"n":"מנחם מנדל זשירין וקישינוב","k":"מנדלי זשירינער","b":"רב בזשירין-תר, קישינוב. נכדו - ר צבי הירש שרמן מליניץ."},{"i":31117,"n":"מנחם מנדל מאוסטרהא","f":"משלם","dt":"תקכב - יד אדר","dp":"אוסטרהא","b":"חתן ר שמואל ר יעקב'ס. מחכמי אוסטרהא. חתנו ר יודיל חסיד מאוסטרהא."},{"i":31118,"n":"מנחם מנדל מאוסטרהא","f":"יצחק בן מנחם מנדל","k":"מנדל יאניווער","dt":"תרט - יז תשרי","dp":"אוסטרהא","b":"תלמיד החוזה מלובלין, וישב אצלו הרבה. מחכמי אוסטרהא. נפטר ללא ילדים."},{"i":31119,"n":"מנחם מנדל מאלשאן","b":"רב באלשאן ובנו ר משה על מקומו אחריו, עוד מבניו: ר אברהם יצחק מוישנובה, ר יוסף מוולקניק. מחותנו - ר אלכסנדר זיסקינד בעל \"יסוד ושורש העבודה\"."},{"i":31120,"n":"מנחם מנדל מבאר","b":"רב בבאר, מתלמידי הבעש\"ט-תקכ. מתורתו ב\"משנת חסידים\". בנו ר צבי. מכתבים ממנו ב\"התמים\" - וארשא תרצה - קובץ חסידי חב\"ד."},{"i":31121,"n":"מנחם מנדל מבוליחוב","b":"מחכמי בוליחוב-תריב."},{"i":31122,"n":"מנחם מנדל מבורשטשוב","b":"רב בבורטשוב-תרך, רב חסידי סדיגורא בדוקלא (אחרי המחלוקת), עלה לצפת."},{"i":31123,"n":"מנחם מנדל מבליגרוד","b":"רב בבליגרוד. חתן ר מרדכי יהושע ויינברג מדוקלא."},{"i":31124,"n":"מנחם מנדל מברעזן","f":"מיכל","b":"מחמכי ברעזאן, חתם-תסא על תקנות זולקוא, וחתם-תנז בירוסלב על מדפיסי זולקוא יחד עם ר שמחה מנחם בן יוחנן ברוך מיונה, ועוד."},{"i":31125,"n":"מנחם מנדל מגרובוביץ","b":"תלמיד ר מנחם מנדל מקוצק."},{"i":31126,"n":"מנחם מנדל מדושאט","k":"בעל תמים יחדיו","bp":"לובלין","b":"רב בדושאט=דוסיאט-תקמ, פוניבז. חיבר \"תמים יחדיו\"."},{"i":31127,"n":"מנחם מנדל מדמביץ","b":"מחכמי דמביץ - תשובה אליו ב\"שואל ומשיב\"."},{"i":31128,"n":"מנחם מנדל מהוסיאטין","b":"מחכמי הוסיאטין - תשובות אליו בטוט\"ד."},{"i":31129,"n":"מנחם מנדל מוארשא","k":"מנחם מנדל מביאליסטוק","dt":"תרלג - טז אייר","b":"ראש ישיבה בוורשה"},{"i":31130,"n":"מנחם מנדל מוואלי","b":"רב בוואלי-ש\"פ"},{"i":31131,"n":"מנחם מנדל מויטבסק","f":"משה","k":"בעל פרי הארץ","r":"אדמו\"ר","bt":"תץ","bp":"ויטבסק","dt":"תקמח -א-יח אייר","dp":"טבריה","b":"אביו היה מתלמידי הבעש\"ט ואף ר מנחם פגשו בילדותו, תלמיד המגיד ממזריטש בהשפעת ר אהרן הגדול מקרלין, מפיץ תורת החסידות ברוסיה הלבנה וליטא בכשרון גדול בתקופת ה\"חרם\", ישב בהורודוק ומתלמידיו שם היה בעל התניא, במינסק, היה אדמור בויטבסק ובין תלמידיו היו רבים מגדולי החסידות וביניהם ר אברהם מקליסק. בשנת תקלז עלה לארץ ישראל בראש שיירה ובה כ-300 עולים לצפת וטבריה, והניח את היסודות לישוב החסידי בארץ. חיבר \"פרי הארץ\" קפוסט תקעד, ועוד. בנו ר משה, וחתנו ר דב בער.","bk":[["פרי הארץ",""],["אגרות קודש מארץ הקודש",""],["אגרת הקודש",""],["לקוטי אמרים",""],["פרי עץ",""],["פרי הארץ [עה\"ת] (וויטבסק)",""]],"e":"ת\"צ-תקמ\"ח"},{"i":31132,"n":"מנחם מנדל מויטקוב ובלזיץ","dt":"תקכח - כה חשון","b":"רב בוויטקוב,בלזיץ"},{"i":31133,"n":"מנחם מנדל מוילנא","f":"יצחק איזיק","dt":"תקץ - יג חשון","dp":"וילנא","b":"נכד ר דניאל מהורדנא בעל \"חמודות דניאל\". כתובת מצבתו נכתב בידי אד\"ם הכהן."},{"i":31134,"n":"מנחם מנדל מזברז","b":"רב בזברז."},{"i":31135,"n":"מנחם מנדל מזדונסקוואלא","dt":"תרלג - טו אלול","b":"תלמיד ר מנחם מנדל מקוצק, בעל חדושי הרי\"ם, ר חנוך הניך מאלכסנדר, ובעל שפת אמת. רב בליסא, זדונסקוואלא-פולין. מפורסם בקנאותו."},{"i":31136,"n":"מנחם מנדל מזולקוא","f":"יוסף","k":"בעל דרך המלך","b":"חיבר \"דרך המלך\" זולקוא תריד."},{"i":31137,"n":"מנחם מנדל מזסלוי(=ז'וסלי)","f":"דוד","bt":"תקפא","dt":"תרלד - כט טבת","b":"מו\"צ בזאסלוי(=ז'וסלי)-תקצד על מקום אביו וזקנו כ-40 שנה."},{"i":31138,"n":"מנחם מנדל מטורקא","b":"דיין בטורקע-ת\"ר"},{"i":31139,"n":"מנחם מנדל מטרמבובלה","b":"רב בטרמבובלה."},{"i":31140,"n":"מנחם מנדל מטשרקוב וירושלים","dt":"תקפח - כ שבט","dp":"ירושלים","b":"רב בטשרקוב, עלה לירושלים."},{"i":31141,"n":"מנחם מנדל מירושלים","k":"אדמור מפרמישלן","dt":"תקנד - כא תשרי","b":"מתלמידי הבעש\"ט עלה לירושלים-תקכ\"ה"},{"i":31142,"n":"מנחם מנדל מלבוב","f":"יחיאל מיכל ש\"ן","b":"הסכים על תנ\"ך-אמשטרדם תמז עם ראשי ועד ארבע ארצות עם ר צבי הירש בן זכריה מלבוב ובנו ר יהושע השל. פירוש הר\"ת בחתימתו ש\"ן - שיחיה נצח."},{"i":31143,"n":"מנחם מנדל מליסעץ","b":"רב בליסעץ."},{"i":31144,"n":"מנחם מנדל מליסקיווע","k":"אדמור מליסקיווע","b":"תלמיד ר צבי אריה מאליק, ור אשר מסטולין. אדמור בליסקיווע."},{"i":31145,"n":"מנחם מנדל ממינסק","f":"ברוך סטופלר","k":"בעל זכרון מנחם","bt":"פאלוצק","dt":"תקצד","dp":"מינסק או פאלוצק","b":"מכונה 'מנדיל'. התייתם בילדותו וגדל בין חכמי שקלוב, נחשב לעילוי בילדותו. תלמיד ר ברוך מגיד מישרים בשקלוב. חתן ר אברהם בן אשר אנשל ממינסק בעל עמוד מישרים. ראש ישיבה במינסק-תקע בערך. מתלמידיו - ר משה שמואל פינס, ר יום טוב ליפמן הלפרין, ר ברוך מרדכי מקלצק. בנו - ר ישראל חיים הו\"ל מתורתו את הספר 'זכרון מנחם', נזכר בספר תלמידו ר בנימין מסטויפץ 'שארית בנימין'. אחיו - ר ברוך שמעון משקלוב."},{"i":31146,"n":"מנחם מנדל מנרף","b":"מנהיג בועד ארבע ארצות, חתם-תמז ביריד ירוסלב."},{"i":31147,"n":"מנחם מנדל מסטנוב","f":"משה","dt":"תקכז","b":"רב בסטאנוב"},{"i":31148,"n":"מנחם מנדל מסטנוב","f":"חיים מסטנוב","b":"נינו של המגיד מזלטושוב. חתן ר יוסף משה בן אברהם יהושע השל מאפטא."},{"i":31149,"n":"מנחם מנדל מסטרי","b":"רב בזלוטשוב."},{"i":31150,"n":"מנחם מנדל מסקופישוק","b":"רב בסקופישוק-ליטא."},{"i":31151,"n":"מנחם מנדל מפילטען","f":"יהושע זליג מפילטען","dp":"זידיק-פלך קובנא","b":"גביר צדיק מחכמי פילטען, עליו הסיפור המפורסם על שהפקיר את רכושו החמץ בפסח."},{"i":31152,"n":"מנחם מנדל מפמורן","b":"רב בפמורן, טיסמניץ-תריב. חיבר פלפול על הרמבם וסוגיות שונות - עמד להיות נדפס בלמברג תרלה."},{"i":31153,"n":"מנחם מנדל מפפד\"א וברלין","b":"חתן ר יחיאל מיכל חסיד רבה של ברלין. דיין בפפד\"א וברלין."},{"i":31154,"n":"מנחם מנדל מפפד\"מ וברלין","b":"דיין בברלין-תקד אצל ר דוד פרנקל."},{"i":31155,"n":"מנחם מנדל מפרג","b":"דיין בפרג-ש\"י"},{"i":31156,"n":"מנחם מנדל מפרג ושוואקשנה","b":"הגיע מפרג לז'אמוט-תח, והיה מראשוני הרבנים שם. רב בשוואקשנה-ליטא והגליל-תח."},{"i":31157,"n":"מנחם מנדל מפרוזין","f":"שילם מפרוזין","b":"דיין בפרוזין אצל הגדול ממינסק."},{"i":31158,"n":"מנחם מנדל מפרמישלא","f":"יחיאל מיכל","b":"רב בפרעמישלא"},{"i":31159,"n":"מנחם מנדל מפרמישלן","f":"אליעזר","k":"בעל דרכי ישרים","bt":"תפח","dt":"תקלא - כא תשרי","dp":"טבריה או ירושלים","b":"תלמיד הבעשט ותלמיד חבר למגיד ממזריטש, עמד בראש עליית החסידים-תקכד יחד עם ר נחמן מהורודנקא והתישב בטבריה, שלח אגרת לאחיו ר צבי מזלוטשוב ובו קורא לו להצטרף אליו. בנו ר דוד עלה עמו. חיבר \"דרכי ישרים - לקוטים ישרים\"","bk":[["דרכי ישרים","לקוטים והנהגות מגדולי החסידות"]]},{"i":31160,"n":"מנחם מנדל מצילץ","b":"רב בצילץ-תנ\"ב"},{"i":31161,"n":"מנחם מנדל מקאזאנהרדוק","f":"דוד","b":"רב בקאזאנהרדוק"},{"i":31162,"n":"מנחם מנדל מקובנא","dt":"תרט","b":"מו\"צ בקובנה"},{"i":31163,"n":"מנחם מנדל מקולומיי","b":"רב בקולומיי-ת\"ס"},{"i":31164,"n":"מנחם מנדל מקולומייא","b":"תלמיד הבעשט."},{"i":31165,"n":"מנחם מנדל מקיטוב","f":"שאול","dp":"תקע","b":"רב בקיטוב."},{"i":31166,"n":"מנחם מנדל מקמניץ","b":"רב בקמניץ"},{"i":31167,"n":"מנחם מנדל מקראקא","dt":"תקלט - יד אלול","dp":"קראקא","b":"רופא מחכמי קראקא, ומראשי הקהלה."},{"i":31168,"n":"מנחם מנדל מקרטינגה","b":"רב בקרטינגה."},{"i":31169,"n":"מנחם מנדל מקריווטש","b":"שו\"ב בקריווטש-תרכה."},{"i":31170,"n":"מנחם מנדל מקרקוביץ","f":"נפתלי הירצקי מלמברג","dp":"ישראל","b":"רבה של קרקוביץ. עלה לארץ ישראל."},{"i":31171,"n":"מנחם מנדל מראווא","f":"נפתלי הירץ","b":"רב בראווא על מקום אביו. ידידו של הישועות יעקב."},{"i":31172,"n":"מנחם מנדל מראווא (שינאווי)","f":"צבי הירש","k":"בעל שיחת חולין","b":"רב בראווא-תקלט. חיבר \"שיחת חולין\" פפדא תקלט. אחיו - ר אהרן משה בעל הלכה למשה."},{"i":31173,"n":"מנחם מנדל מראסיין","dt":"תקצו","dp":"ראסיין","b":"שו\"ב בנירטענאלי-פלך ראסיין, ולאחר שפרש עבר ללמוד בראסיין. חתנו - ר שלמה זלמן מראסיין ונכדו - ר פנחס קאמיסער מראסיין וגראפסקאי."},{"i":31174,"n":"מנחם מנדל מרדומסק וצפת","b":"דיין בצפת-תרנא, חתם עם ר שמשון בן פיבל בצפת-תרנא."},{"i":31175,"n":"מנחם מנדל מרובנא","f":"פיבוש מלענטשנא","b":"תלמיד המגיד ממזריטש. רב בראוונה(=רובנא)-תקס."},{"i":31176,"n":"מנחם מנדל מרוהטין","b":"מחכמי רוהטין. נכד ר יחזקאל סופר."},{"i":31177,"n":"מנחם מנדל מרוסיה","b":"ראב\"ד ור\"מ בכל מדינות רוסיה"},{"i":31178,"n":"מנחם מנדל משירווינט","f":"אליעזר ליפמן הלוי","k":"בעל ברכת מנחם","dt":"תרעב","b":"רב בשירווינט-תרס."},{"i":31179,"n":"מנחם מנדל משקלוב וירושלים","f":"ברוך בנדיט מהלוסק","k":"בעל מים אדירים","r":"תלמידו של הגר\"א ומו\"ל חלק גדול מכתביו","dt":"תקפז - ל שבט","dp":"ירושלים","b":"מתלמידי הגר\"א, עלה לטבריה בשנת תקסח והקדים את שיירת העולים שבאה שלוש שנים אחר כך. התגורר בצפת ואחר כך עבר לירושלים. עמד יחד עם ר משה סוזין ה\"ראשון לציון\" בראש קהילת ירושלים. חיבר \"מים אדירים\" וארשא תרעו, ועוד, וכן עסק רבות בפרסום תורתו של הגר\"א.","bk":[["מים אדירים - אידרא זוטא",""],["דרך הקודש",""]],"e":"תקפ\"ז [פטירה]"},{"i":31180,"n":"מנחם מנדל סגל מויליאמפול","dt":"תקלו - לפני","b":"רבה הראשון של וילימפול-סלבדקה-תקכב. בנו - ר משה."},{"i":31181,"n":"מנחם מנדל סגל מלבוב ואוסטרהא","f":"אליעזר הרופא","b":"גביר עשיר, רופא ופרנס ומנהיג הקהלה-תקכד יחד עם ר מרדכי בן יואל הלפרין ור שמואל ר יעקב'ס ועם בני הקצין ר יוזפא. כנראה אשתו מצאצאי המהרש\"א. חתם ראשון על כתב הרבנות של ר דוד הלפרין ור אברהם משלם זלמן. מבניו: ר משה שמואל הרופא מאוסטרהא, ר נפתלי פרנס באוסטרהא. חתניו: ר מרדכי בן אליעזר ליפמן מאוסטרהא, ר חיים. (אולי אביו הוא הרופא ר אליעזר בן יוחנן ברוך מיונה אחיו של ר שמחה דאקטור - \"אנשי שם\" לבובר)."},{"i":31182,"n":"מנחם מנדל עשווא מברלין","b":"ממנהיגי קהילת ברלין. חתם על מינוי ר משה בן אהרן מלבוב ולייפניק לרבה של ברלין-תפט."},{"i":31183,"n":"מנחם מנדל רמ\"ר מפוזנא","k":"בעל צנצנת מנחם","b":"נכד(-אבי אמו) ר אברהם שרנצל בעל \"איתן האזרחי\". תלמיד הט\"ז, ר אשר זליג מזולקוא. מרביץ תורה בפוזנא, רב בהעלישוי, זמיגראד, ונגרוב-תעח. חיבר \"צנצנת מנחם\", \"לחם מנחם\"."},{"i":31184,"n":"מנחם מניש מרדכי מטיסמניץ","f":"שמשון","b":"רב בטיסמניץ. תשובה אליו ב\"גור אריה יהודה\"."},{"i":31185,"n":"מנחם מנלי","k":"בעל צנצנת המן","b":"מחכמי ליסא-ת\"ס. חיבר \"צנצנת המן\"."},{"i":31186,"n":"מנחם מנלי הלוי מלבוב","f":"ברוך","k":"בעל זרע ברוך","dt":"תקו - ז סיון","dp":"לבוב","b":"מצאצאי השר שאול וויל ור יוסף כץ מקראקא בעל \"שארית יוסף\", נכד ר יצחק שרנצלס מלבוב. דיין בלבוב כנראה אצל ר חיים הכהן רפפורט. חיבר גם \"עמק הלכה\". חתם-תקא עם ר אברהם סגל מטיסמניץ ור נתן נטע בן זלמן, ועוד."},{"i":31187,"n":"מנחם מנלי מלובלין","f":"אוריש פיבל","dt":"תקמז - כז אייר","dp":"לובלין","b":"מחכמי לובלין."},{"i":31188,"n":"מנחם מנלי מפעצעל","b":"רב בפעצעל-תקפ\"א רב-שנת תק\"נ"},{"i":31189,"n":"מנחם מנלי סגל מפריסטיק","b":"רב בפריסטיק - תשובה אליו ב\"שואל ומשיב\"."},{"i":31190,"n":"מנחם מנשה מקושטא","f":"יעקב","k":"בעל אהבת חיים","bt":"תרנו","bp":"קושטא","dt":"תשכח - יב אלול","dp":"ירושלים","b":"נתייתם בצעירותו ונאלץ לשרת בצבא התורכי, מחכמי קושטא, עלה לירושלים והתחבר למהרש\"א אלפנדרי ור מרדכי שרעבי שכיבדוהו מאוד. ר מרדכי שרעבי העיד עליו כי הוא אחד מל\"ו צדיקים. היה מ ארגן תפלות מיוחדות בזמן מלחמת העולם השניה, עם עוד עשרה צדיקים נסתרים. ארגן חברת \"אהבת חיים\" ובין חבריה היו ר בנימין זאב חשין, ר יעקב מאיר שכטר - המגיד הירושלמי. התנגד לציונות. חיבר עוד \"לקוטי מנשה\", \"שער החיים\" ועוד."},{"i":31191,"n":"מנחם מסימנא","b":"אב\"ד סימנא-תרמה."},{"i":31192,"n":"מנחם מפדובה","f":"אליה","b":"רב בפדובה. נזכר בספר זכרון נשמות עירנו."},{"i":31193,"n":"מנחם מצעדה-תימן","f":"דוד","k":"בעל מעשה ידי אמן","b":"דיין בצעדה-תימן במאה ה-19."},{"i":31194,"n":"מנחם מקושטא","f":"שמואל","b":"רב ראשי בקושטא-ש' בערך על מקום ר אליהו הלוי - למרות שמשרת החכם באשי הרשמי בוטלה."},{"i":31195,"n":"מנחם מקראקא","b":"דיין בקרקא-שי\"ט"},{"i":31196,"n":"מנחם מראווא","f":"חנניה ליפא","b":"רב בראווע-תק\"צ. בנו - ר יעקב מפיעטרקוב"},{"i":31197,"n":"מנחם מרמלה","f":"יפת","b":"מחכמי רמלה, חתום על תעודה משנת ד'תרצט (939)."},{"i":31198,"n":"מנחם משה מהמבורג וירושלים","f":"יהודה","dt":"תרי - יח תשרי","dp":"ירושלים","b":"רב בלונא. מחכמי ירושלים. אחיו - ר אברהם שמואל רבינוביץ בעל \"עמודי אש\"."},{"i":31199,"n":"מנחם ן, אליהו","b":"מגדולי חכמי קושטא-שפ\"ה"},{"i":31200,"n":"מנחם נחום בן צבי הירש מצ’רנובל","bt":"1730","dt":"ה'תקנז 1797","bk":[["ישמח לב",""],["מאור עינים",""]]},{"i":31201,"n":"מנחם נחום הלוי מהורדנא","f":"יחיאל מיכל","dt":"תקסח - כ חשון","dp":"הורדנא","b":"דיין בהורדנא, הסכים-תקסו עם ביה\"ד בהורדנא על שו\"ע להגר\"א."},{"i":31202,"n":"מנחם נחום חריף משירווינט","f":"דוד משירווינט","b":"אב\"ד שירווינט. חתנו - ר שלמה זלמן רבל, ונכדו - ר מנחם נחום שרגא רבל מלינקובה."},{"i":31203,"n":"מנחם נחום מבאהפאלי","f":"ישראל מבאהפאלי","b":"חתן נכדת ר יהודה ליב הסבא משפולה. רב בבאהפאלי על מקום אביו."},{"i":31204,"n":"מנחם נחום מוולברום","f":"בנימין","dt":"תקן - ט אדר","dp":"קראקא","b":"רב בוולבראם(=וולברום)."},{"i":31205,"n":"מנחם נחום מלודזין","b":"רב בלאדזין(=לודזין)-תפ. בנו - ר נפתלי מטולטשין, ונכדו ר אברהם אבלי מחרסון."},{"i":31206,"n":"מנחם נחום מניקלבורג","f":"יעקב אורי שרגא","b":"רב בניקלבורג. אביו הדפיס לזכרו \"זכרון מנחם\"."},{"i":31207,"n":"מנחם נחום מפלאצק וירושלים","f":"נפתלי","dt":"תרכח - ט שבט","dp":"ירושלים","b":"חסיד חב\"ד, מחכמי ירושלים. עמד לצד ר\"מ יאנובר בזמן המחלוקת."},{"i":31208,"n":"מנחם נחום מצאווס מוילנא","f":"יהודה ליב","k":"בעל תוספות בכורים","b":"מו\"צ בווילנה-תק\"ע"},{"i":31209,"n":"מנחם נחום מקידאן","f":"יחיאל מיכל","b":"דיין בקידאן. חתם על שטר הרשאה-תקנח, עם האב\"ד ר יהודה ליב בן יחזקאל כהנא מקידאן."},{"i":31210,"n":"מנחם נחום ריבקינד שתדלן מוילנא","f":"יצחק מצאוות","k":"בעל בית אברהם","dt":"תקצג - ב אלול","dp":"וילנא","b":"חיבר שיר ידידות בראש \"דבר שמואל\" לר שמואל מרדכי גרשוני מוילנא. היה גם בפטרבורג."},{"i":31211,"n":"מנחם עזריה ממילי","b":"מחכמי צפת, בשנת שלט בשליחות באיטליה מטעם עדת האיטליאנים."},{"i":31212,"n":"מנחם עזריה מפנו","bt":"1548","dt":"ה'שפ 1620","bk":[["אלפסי זוטא",""],["אמרות טהורות",""],["גלגולי נשמות",""],["יואל משה",""],["יונת אלם",""],["ימין השם רוממה",""],["כנפי יונה",""],["מאמר הנפש",""],["מאמר צבאות ה’",""],["סדר עבודה",""],["ספר תשובות",""],["עשרה מאמרות",""],["פלח הרמון",""],["שבעים ושתים ידיעות",""],["שברי לוחות",""],["תשובות ופירוש סוגיות רמ\"ע מפאנו",""]]},{"i":31213,"n":"מנחם צבי מסט-גראד","b":"רב בסט'גראד-תק\"נ"},{"i":31214,"n":"מנחם רופא","f":"שבתי","k":"בעל דרכי ישרים","b":"מחכמי איטליה, בשנת תג עלה לארץ ישראל. חיבר \"דרכי ישרים\" זולקווא תקנג (כנראה בלבול עם ר מנחם מנדל מפרמישלן)."},{"i":31215,"n":"מנחם רופא מלודז","b":"תלמיד החת\"ס. רופא בלודז-תרלד. ועסק בהעתקת למוד הנתוח ללשון הקדש בענין טריפות."},{"i":31216,"n":"מנחם שבתי משלוניקי","dt":"תסט","dp":"שלוניקי","b":"רב בשלוניקי."},{"i":31217,"n":"מנחם שלמה מנמירוב","b":"רב בנמירוב-תר\"ס"},{"i":31218,"n":"מנחם שמואל הלוי מפרס וירושלים","f":"שמואל מרדכי","k":"בעל מרדכי ואסתר בשוש","bt":"תרמד","bp":"המדאן-פרס","dt":"תש - יט שבט","dp":"ירושלים","b":"מקורב למלכות, רב בהמדאן(=שושן הבירה), עלה לארץ-תרפג. מנהל ביה\"ס בהמדאן, רב בהמדאן, יסד אגודת \"חובבי ישורון\", מעורר ישנים\" - כנגד האמונה הבאהית, פעל למען הציונות בפרס, פעיל ציבור בירושלים. חיבר גם \"מעורר ישנים\" - בכת\"י, \"מחקרים לתולדות יהודי פרס\", ועוד."},{"i":31219,"n":"מנחם, אליהו משלוניקי וארטא","b":"מרבני שאלוניקי, רב בארטא(יון)"},{"i":31220,"n":"מנחם, חיים מאזמיר","b":"מרבני איזמיר"},{"i":31221,"n":"מנחם, יוסף מלוב","bt":"תרי","dt":"תרץ - בערך","b":"רב ושוחט במסלאתה, ומלמד תשב\"ר. שאלות ממנו לר משה סרוסי ב\"וישב משה\"."},{"i":31222,"n":"מנחם, ישראל משלוניקי","dt":"שפ - יח אב","dp":"שלוניקי","b":"מחכמי שלוניקי."},{"i":31223,"n":"מנחם, משה מטריפולי","bt":"תץ","dt":"תקס - בערך","b":"תלמיד ר מ' רוקח. רב בטריפולי. נזכר ב\"מעשה רוקח\"."},{"i":31224,"n":"מנטבייא, יוסף","f":"ראה דמונטנייא, יוסף"},{"i":31225,"n":"מנטיג, אהרן יהודה","b":"רב במזלבריץ"},{"i":31226,"n":"מנטל, אליעזר מפמורן","b":"מחכמי פמורן-תרלו."},{"i":31227,"n":"מנטל, ישראל מזברז","b":"מחכמי זברז-תריז."},{"i":31228,"n":"מנטליק, מנדל","b":"תלמיד ישיבת אוטואצק. פרסם מאמרים ב\"התמים\" - וארשא תרצה - קובץ חסידי חב\"ד."},{"i":31229,"n":"מנטליק, מרדכי מנ\"י","b":"ר\"מ בישיבת \"תומכי תמימים\" בניו יורק-תשד. פרסם מאמרים ב\"קובץ חדושי תורה\" - נ\"י תשד - קובץ תלמידי ישיבות \"תומכי תמימים ליובאויטש\"."},{"i":31230,"n":"מנטשל, ברוך מאיר מזבלטוב","f":"דניאל בן ציון מבוצאץ","k":"בעל רב טובך","bt":"תקף","dt":"תרע","b":"חתן ר שלמה דרימר מסקאלא. רב בזבלטוב-תר, פוטיק-תרי, אוסציא-ביסקופייע-תרך. חיבר \"רב טובך\" למברג תרמד."},{"i":31231,"n":"מנטשר, מרדכי מצרנוביץ","b":"ראש הקהל בצרנוביץ-תרצז."},{"i":31232,"n":"מני, אהרן מחברון וירושלים","f":"סלימן","bp":"חברון","b":"עסקן צבור בירושלים."},{"i":31233,"n":"מני, יעקב מירושלים","b":"מחכמי ירושלים, עמד בראש ישיבת הנגיד וחתם על מכתב בני הישיבה בשנת רפא."},{"i":31234,"n":"מני, יצחק מלכיאל","f":"אליהו","bt":"תרכא","bp":"חברון","dt":"תרצג - ה כסלו","dp":"תל אביב","b":"מלומד וחוקר ערבית ואיסלם, שופט בירושלים."},{"i":31235,"n":"מני, מנשה מחברון","f":"יעקב בן אליהו","k":"בעל ספר זכרונות","bt":"תרסט","bp":"חברון","b":"תלמיד ר חנוך חסון, ר מאיר קשטיל, ר חיים חזקיהו מדיני בחברון. פעיל צבור בחברון, תל אביב."},{"i":31236,"n":"מני, מסעוד ממרוקו","dp":"מרוקו","b":"מצדיקי מרוקו. נקבר על הר אימין תאמוגה ליד קבר ר אברהם דרעי."},{"i":31237,"n":"מני, שלום הכהן איש קריווה","b":"מחכמי איטליה, עלה לצפת. גיסו של ר אליהו די וידאש בעל \"ראשית חכמה\". מתורתו בספר נכדו \"ברכת טוב\"."},{"i":31238,"n":"מני, שלום יחזקאל מבגדד וירושלי","f":"אליהו","bt":"תרטו","bp":"בגדד","b":"מחכמי ירושלים."},{"i":31239,"n":"מני, שלמה סלימן מנחם מחברון","f":"אליהו מחברון","r":"ראב\"ד לעדת הספרדים בחברון וראש ישיבת מעשי נסים","bt":"תרי או תרטו","bp":"בגדד","dt":"תרפד - יט אלול","dp":"חברון","b":"נקרא בשם מנחם על שם ר מנחם לונזאנו. עלה עם אביו לחברון-תרטז שם התמנה אביו לרב. היה תלמיד ר שלמה יהודה אליעזרוב, חתן ר משה פיררה רבה של חברון. היה רבה של חברון-תרנט על מקום ר חזקיהו מדיני. ראש ישיבת מעשה נסים בחברון. בזמן המחלקות בירושלים על ירושת כס הראשל\"צ לאחר פטירת ר יעקב שאול אלישר, התמנה לעמוד באופן זמני בראש הקהלה. עשה \"סולחה\" בין שתי משפחות ערביות בחברון. מתורתו ב\"המאסף\". הו\"ל \"שיח יצחק\" לאביו עם הקדמה ממנו.","bk":[["ממני פריך - ביאור מקראות ודרשות",""]]},{"i":31240,"n":"מנימני, אהרן מג'רבה","b":"מרבני ג'רבא"},{"i":31241,"n":"מניני חדאד, בנימין מג'רבה","f":"מכלוף","k":"בעל מחי ומסי","bt":"תרעב","bp":"ג'רבא","dt":"תשיט","dp":"ישראל","b":"מחכמי ורבני ג'רבא, חיבר ספר \"מחי ומסי\""},{"i":31242,"n":"מניני חדאד, רפאל מג'רבה","k":"בעל מחי ומסי","dt":"תשכא","b":"מחכמי ג'רבא. תלמיד ר רחמים חי חויתה הכהן. עלה לארץ בזקנותו. חיבר גם \"פטר רחם\". פרסם מאמרים ב\"הירח\" - ג'רבה תשח.","bk":[["פטר רחם",""]]},{"i":31243,"n":"מניני כהן, יהודה מג'רבה","k":"בעל קול יהודה","bt":"תרנה","b":"מחכמי ורבני ג'רבה,חיבר \"קול יהודה\" חידושים"},{"i":31244,"n":"מניר, יוסף מאלגיר","f":"יצחק","bt":"קכ - בערך","dt":"קץ - בערך","b":"תלמיד ר חסדאי בן שלמה, והריב\"ש - המזכירו בספרו. הגיע מספרד-קנא, רב ודיין בקצמטינא. השיב תשובות, חיבר שיטה על נדרים. מתלמידיו ר יצחק בן קאג'יג. ציונו נחשב למקום קדוש גם ע\"י לא יהודים. נזכר ב\"בית יוסף\"."},{"i":31245,"n":"מניר, יצחק מסרגוסה","f":"יוסף","b":"תלמיד הריטב\"א. דיין ופוסק בסרגוסה(טולדו?)-קס בזמן הריב\"ש. אביו של ר יוסף מניר."},{"i":31246,"n":"מנישביץ, דב מליטא ונ\"י","f":"יחיאל מיכל","bt":"1858","bp":"סלנט","dt":"1914","b":"תלמיד ישיבות ליטא. שימש את ר ישראל סלנטר וקיבל ממנו סמיכה לשו\"ב. היגר לארה\"ב והקים שם בית חרושת למצות שנתפרסם בעולם. מכתב גלוי ב\"בית ועד לחכמים\" - נ\"י תרסג - אודות סדרי אפיית המצות במפעלו אשר בסינסינטי. בניו הקימו ישיבה על שמו בירושלים-תרצב."},{"i":31247,"n":"מנישביץ, ישראל מארה\"ב","b":"גביר ובעל צדקה בארה\"ב. חתנו - ר דוד רוקמן - ראש ישיבת רבי יצחק אלחנן בניו יורק."},{"i":31248,"n":"מנישביץ, מיכל מסלנט","b":"מלמד בסלנט. בנו התעשיין דב מ'."},{"i":31249,"n":"מנישביץ, צבי הירש מנ\"י","f":"דב בר מארה\"ב","b":"בעל ביח\"ר למצות בארה\"ב. הקים והחזיק יחד עם אחיו - ישיבה בירושלים-תרצב על שם אביו."},{"i":31250,"n":"מנליש, ליב","b":"דומ\"צ בדובנא,קרקא"},{"i":31251,"n":"מנלס, פיבוש","dt":"תסז - א סיון","b":"מרביץ תורה,רב באונגאריש-ברוד"},{"i":31252,"n":"מנסס, אליעזר מירושלים","dt":"תיו - יד כסלו","dp":"ירושלים","b":"מחכמי ירושלים"},{"i":31253,"n":"מנספלד, יוסף","f":"שבתי","k":"יוסף בן שבתי מקליש","dt":"תקצז","dp":"צפת","b":"מחכמי צפת, עלה מקליש בשנת תקצה, ונספה עם אשתו ברעש, (???יערי פרסם אגרת ממנו לאחיו בקליש אודות החיים בצפת משנת תקמז???)."},{"i":31254,"n":"מנספלד, יחזקאל","f":"נתן הכהן מקראקא","b":"חתן ר משה יעקב שנקר מאושפיצין. מחכמי אושפיצין ובנקאי."},{"i":31255,"n":"מנפריד, אליעזר (לאזרוס)","bt":"1885","bp":"שאדובה","dt":"1955","dp":"ניו יורק","b":"למד מוסיקה בוארשא. פרסם מאמרים ושירים ב\"פריינד\", \"טאג\", ועוד. היגר לארה\"ב-1907 ופרסם מאמרים ב\"אידישע טאגעבלאט\", ועוד."},{"i":31256,"n":"מנצור, מנחם מעדן-תימן","bt":"תקי - אחרי","bp":"עדן","dp":"עדן","b":"דיין בעדן-תימן עם ר ישועה (סבו של ר שמואל עדני בעל \"נחלת יוסף\"), וחתם בפס\"ד בענין ירושת רבי עואץ-תקעד - תקצד. (סופר כי שר מוסלמי סטר לו בגלל שנעל נעליים מצוחצחות - והשר מת באותו היום)."},{"i":31257,"n":"מנצורה, שלום מתימן","f":"יהודה","k":"בעל נר מצוה","bt":"תקס","bp":"צנעא","dt":"תרמה","dp":"צנעא","b":"מחכמי תימן, שו\"ב ורופא. אחיו של המשורר ר סעדיה מנצורה. תלמיד מרי אברהם הלוי אלשיך מצנעא. בשליחות הרב הראשי - ר יוסף קארה, בישובי תימן, כדי לפקח על השחיטה, להסמיך רבנים וכו'. נגיד בצנעא-תריד. מתלמידיו ר אברהם בן יהודה בדיחי, ר אברהם אלנאדף, ור אברהם עמרני. נכדו - ר יחיא יצחק הלוי - ראב\"ד בצנעא. חיבר גם \"זבחי תודה\", \"שלמה חגיגה\" ועוד. חיבר גם \"נר מצוה\", \"סדר המילה\" ועוד."},{"i":31258,"n":"מנצ’ל ברוך מאיר בן דניאל בנציון","bt":"1820","dt":"ה'תרעד 1914","bk":[["רב טובך",""]]},{"i":31259,"n":"מנצל, מרדכי מפרשבורג","dt":"תצו","dp":"פרשבורג","b":"רופא בפרשבורג."},{"i":31260,"n":"מנצל, מרכוס מפרשבורג","dt":"תץ","b":"רופא מחכמי פרשבורג, ועסקן בחברא קדישא."},{"i":31261,"n":"מנצפ\"ך, יוסף יפתח סגל","f":"נפתלי הלוי","k":"בעל מנהגי ורמייזא","bt":"שסד","dt":"תלח - יג שבט","dp":"ורמייזא","b":"מכונה ר יוזפא שמש. תלמיד ר פנחס הורביץ בפולדא, סופר מגדולי חכמי וורמייזא-תי. חיבר גם \"מעשה נסים\" ונדפס בידי בנו - ר אליעזר ליברמן עם \"מעשה ה'\"."},{"i":31262,"n":"מנצר, ישכר דב בר מיאקא","f":"יצחק באניהאד","bt":"תקפג","bp":"פרשבורג","dt":"תרמג - ז תשרי","dp":"יאקא","b":"תלמיד הכת\"ס. רב ברעטה, יאקא-תריב, זשאמבוקרט-תרכ. חתנו ר משה שמעון הלוי על מקומו אחריו. בנו - ר ליפמן - רב ביאקא."},{"i":31263,"n":"מנצר, ליפמן מיאקא","f":"ישכר דב מיאקא","b":"רב ביאקא"},{"i":31264,"n":"מנקין, אברהם יצחק מאיוויא","b":"רב באיוויא(=איויא)-תרצ\"ד"},{"i":31265,"n":"מנקין, ברוך זאב מגריווא","bp":"שוינציאן","b":"ר\"מ ומו\"ץ בגריווא. בנו - ר רפאל ראובן מרימשאן."},{"i":31266,"n":"מנקין, דוד מדובינובה","bt":"תרטו","dt":"תרצא - יט טבת","b":"רב בדובינובה-תרנ\"א"},{"i":31267,"n":"מנקין, יעקב שמואל","f":"אריה","bt":"1865","bp":"סואנציאן","b":"תלמיד ישיבות ליטא. היגר לארה\"ב-1904. תלמיד אוניברסיטת קולומביה. רב בקהילות שונות בארה\"ב, פרש מהרבנות ועסק בכתיבת ספרים. חיבר ספר באנגלית על החסידות - שעשה רושם בצבור הלא יהודי. חיבר ספרים באנגלית בנושאי יהדות."},{"i":31268,"n":"מנקין, פתחיה מחרקוב","k":"בעל כרם פתחיה","bt":"תרמא","dt":"תשז - יט טבת","b":"דרשן,רב בחרקוב, ראדין, דשקאבה-תרעג, קניאזיץ-תרעה, קרוטש-תרפב, סינה-תרפט, עלה לארץ תרצג. פרסם מאמרים ב\"בית הכנסת\" - תל אביב תשו, \"אהל יצחק\" סטמר - תרסג - תרעד, \"בית ועד לחכמים\" - לונדון תרסב, \"דבר בעתו\" - פאקש תרסט. פרסם מאמרים ב\"יגדיל תורה\" - בוברויסק תרפח (תחת שלטון הקומוניסטים ברוסיה), \"המאור\" - תל אביב תרצה, \"תבונה\" - ירושלים תשא-תשח."},{"i":31269,"n":"מנקין, רפאל ראובן מרימשן","f":"ברוך זאב מגריווא","dt":"תרסז - סיון","dp":"גריווא","b":"חתן אב\"ד לינקובא. רב ברימשאן(=רימשן) כ-4 שנים, נפטר צעיר."},{"i":31270,"n":"מנקיש, יעקב יהודה ליב","b":"פרסם מאמרים ב\"שומר ציון הנאמן\" - אלטונא תרו-תרטז."},{"i":31271,"n":"מנקס, אברהם יצחק","f":"חיים טעביל","b":"מדפיס בלמברג. נכדו של ר נחמן הכהן מגלוגא."},{"i":31272,"n":"מנקס, גבריאל","b":"מחכמי שטרזיץ-תרלה, סטניסלב. נכד ר מאיר צבי ויטמאיר מסמבור - טיפל בהדפסת ספר זקנו. נפטר בגיל צעיר."},{"i":31273,"n":"מנקס, יעקב יהודה ליב מלמברג","b":"מחכמי למברג-תריד."},{"i":31274,"n":"מנקס, יעקב מברוד","dt":"תרלה","b":"עסקן מחכמי ברודי ויסד שם ישיבה."},{"i":31275,"n":"מנשה בן ישראל מאמשטרדם","f":"יוסף בן ישראל","k":"בעל נשמת חיים","bt":"שסד","bp":"מדירה או לארושיל-פורטוגל","dt":"תיז-ח - יד כסלו","dp":"מידלבורג-הולנד","b":"ממשפחת אנוסים בפורטוגל, הגיע להולנד עם אביו שחזר ליהדות שם. תלמיד ר יצחק עוזיאל. רב ומדפיס באמשטרדם. היגר לברזיל-ת בעקבות גיסו ר אפרים סואירו, וכיהן כרב בפירנמבוקו ועמד בראש ישיבת האחים פרירה, חזר לאמשטרדם-תב, נפגש עם קרומוול באנגליה-תטו וקיבל ממנו כמה הטבות עבור היהודים, ולאחר זמן נתאפשרה בזכותו חזרת היהודים לאנגליה. (צוייר ע\"י רמברנדט). חיבר עוד \"פני רבה\", \"אבן יקרה\", \"מקוה ישראל\" - ובו טען כי עשרת השבטים הם האינדיאנים באמריקה, ועוד. בנו ר יוסף - נפטר צעיר בחיי אביו.","bk":[["מקוה ישראל",""],["נשמת חיים",""],["פני רבה",""],["תשועת ישראל",""]]},{"i":31276,"n":"מנשה הלוי מבגדד וירושלים","k":"בעל אהבת חיים","dt":"תשנו - ל תשרי","dp":"ירושלים","b":"מחכמי בגדד, עלה לירושלים. מקובל וצדיק בירושלים."},{"i":31277,"n":"מנשה ליב מיארמוט","dt":"תרט - כח סיון","b":"דומ\"צ ביארמוט-תקץ והיה ממלא מקום מהר\"ם אש שעבר לאונגואר-תקצה עד למינוי ר יעקב יהושע הכהן רפפורט."},{"i":31278,"n":"מנשה מאוסטרהא","f":"יהודה ליוואי מלחובץ","dt":"תע - א חשון","dp":"אוסטרהא","b":"מחכמי אוסטרהא. בן האב\"ד של לעחוביץ."},{"i":31279,"n":"מנשה מבוליחוב","b":"רב בבוליחוב"},{"i":31280,"n":"מנשה מבינגן","b":"מחכמי בינגן. חתם על תקנות אסיפת הרבנים בפפד\"מ-שסג."},{"i":31281,"n":"מנשה מווסטפלן","b":"מחכמי אשכנז. חתם על תקנות אסיפת הרבנים בפפד\"מ-שסג."},{"i":31282,"n":"מנשה מלובלין","f":"יצחק","b":"מחכמי לובלין. חתם על תקנות בפנקס ביהכ\"נ ר צבי הירש בן משה דאקטאר."},{"i":31283,"n":"מנשה ממצרים","f":"יוסף","b":"רב בבית דינו של הרמב\"ם במצרים וחתם עמו בתקנת הקידושין."},{"i":31284,"n":"מנשה מקוזניץ","f":"דוד","dt":"תקעד - ה אלול","dp":"קוזניץ","b":"תלמיד המגיד מקוזניץ. על קברו צוין \"רבים השיב מעון\"."},{"i":31285,"n":"מנשה משדה לבן","f":"שמשון מקרמניץ","b":"מגדולי חכמי דורו, רב בשדה לבן-ש\"ס"},{"i":31286,"n":"מנשה, אברהם משלוניקי","f":"יעקב","dt":"תרכד","dp":"שלוניקי","b":"בנו של הרב הכולל ר יעקב מנשה. מחכמי שלוניקי-תקעט, סופרו של ר אשר קובו-הרב הראשי בשלוניקי, הגיה את \"מטה שמעון\" לר מרדכי שמעון, והו\"ל יחד עם אביו \"מראה הגדול\" לר רפאל אשכנזי-תקצא, חיבר הקדמות לספרי אביו, הגיה כמה מספרי ר חיים פלאג'י, ועוד."},{"i":31287,"n":"מנשה, חיים אליהו מירושלים","f":"יצחק","dt":"תקסח - כב שבט","dp":"ירושלים","b":"מחכמי שלוניקי, עלה לירושלים."},{"i":31288,"n":"מנשה, חיים משלוניקי","f":"שמעון","b":"סופר הרב הראשי - כאביו וזקנו לפניו, ובנו - ר רפאל מנשה על מקומו אחריו כסופר ומזכיר הרב הראשי. הגיה \"ירים משה\" לר משה קאשטרו-תרן, הו\"ל ספר אביו \"שם משמעון\" ובסופו חיבור ממנו על \"ספק ספיקא\"."},{"i":31289,"n":"מנשה, חיים רפאל יהושע","dt":"תרלז","dp":"שלוניקי","b":"מחכמי שלוניקי."},{"i":31290,"n":"מנשה, יוסף משלוניקי","f":"אברהם","dt":"תקמב","dp":"שלוניקי","b":"מחכמי שלוניקי. אחיו של ר יעקב מנשה-רבה של שלוניקי."},{"i":31291,"n":"מנשה, יוסף משלוניקי וירושלים","dt":"תקפו - אחרי","b":"מחכמי שלוניקי, עלה לירושלים, חתם-תקסט על מכתב, בשנת תקפו חתם על שטר כולל."},{"i":31292,"n":"מנשה, יעקב רפאל מחברון ושלוניק","f":"אברהם","k":"בעל אהל יעקב","bt":"תקכב - בערך","dt":"תקצב","dp":"שלוניקי","b":"תלמיד ר חיים נסים רפאל מוצירי. מחכמי חברון דיין בשלוניקי-תקנז, רב הכולל על מקום ר חיים יוסף ן ארדיט - עם כמה מחבריו, ור משה ברכה על מקומו אחריו. בשליחות חברון באיטליה-תקסו, בשליחות עצמו בתורכיה והתישב בשלוניקי. חיבר \"אהל יעקב\" שלוניקי תקצב, \"עין המים\", \"באר המים\". בניו: ר אברהם-סופרו של ר אשר קובו, ר מנחם, ור מאיר."},{"i":31293,"n":"מנשה, מאיר משלוניקי","f":"יעקב","dt":"תרכז","dp":"שלוניקי","b":"דיין בשלוניקי. נפטר במגיפה."},{"i":31294,"n":"מנשה, מנחם משלוניקי","f":"יעקב","dt":"תרלז","dp":"שלוניקי","b":"מחכמי שלוניקי."},{"i":31295,"n":"מנשה, שמעון משלוניקי","f":"אברהם מנשה","k":"בעל שם משמעון","dt":"תרנד","b":"רב בשלוניקי, מזכיר הרבנים הראשיים ר אשר קובו, ר אברהם גטניו ור שמואל ארדיטי - כמו אביו לפניו. הגיה \"רוב דגן\" לר יצחק שלמה הלוי-תרכב, \"תפארת אדם\"-תרכז, ועוד. מתשובותיו בספרי חכמי דורו."},{"i":31296,"n":"מס, נתן מפפד\"מ","f":"שלמה","b":"מראשי קהילת פפד\"מ-תקך, ונמנה על קבוצת הרבנים שמילאו את מקומו של ר יעקב יהושע בעל ה\"פני יהושע\"."},{"i":31297,"n":"מסאלתי - משפחה","b":"משפחת רבנים במרוקו, מוצאה בכפר מסילא שליד קלעת בני חאמאד. ענף של המשפחה במזאב(=גרדאיא)-אלגיר והראשון ששמו לא ידוע נזכר אצל ר הרשב\"ץ השני ב\"חוט המשולש\" ובנו ר יצחק על מקומו אחריו."},{"i":31298,"n":"מסאלתי, יצחק מאלגיר","bt":"שכ","dt":"שץ - בערך","b":"רב במזאב-אלגיר על מקום אביו."},{"i":31299,"n":"מסאלתי, סעדיה מאלגיר","f":"משה","bt":"רפ","dt":"שן - בערך","b":"סופר מחכמי אלגיר, העתיק חיבור בקבלה עבור ר יהודה זיזה-שיח."},{"i":31300,"n":"מסג'למסה, שלמה ממרוקו","f":"נתן","b":"מחכמי מרוקו בדור שאחרי הרי\"ף. חיבר סידור עם דברי הלכה."},{"i":31301,"n":"מסטובסקי, בנימין מארה\"ב","f":"משה","k":"בעל גבול בנימין","bt":"תרנו","bp":"קמניץ ליטאווסק-פלך גרודנא","b":"תלמיד ישיבת \"תורת חיים\" בבריסק, בריינסק, וולוזין. נסמך מאת: ר רפאל שפירא, ר ראובן דוד בורשטין מקמניץ. חתן ר דוד יצחק הכהן קאפלין. היגר לארה\"ב-תרצז וכיהן כרב קהלת \"שערי תפלה\" בבוסטון. חבר ועד הרבנים באמריקה, ותנועת המזרחי."},{"i":31302,"n":"מסיה, שמואל","b":"רב בוורמס(=וורמייזא)-שצד. השתתף באספת הרבנים בוורמייזא-שב."},{"i":31303,"n":"מסיכה, אברהם מטריפולי","bt":"תקל","dt":"תר - בערך","b":"סופר דווקני בטריפולי. חתם בפנקס בי\"ד טריפולי."},{"i":31304,"n":"מסיכה, בנימין מטריפולי","bt":"תקף","bp":"טריפולי","dt":"תרן - בערך","b":"רב בדרנה-לוב-תרי עד תרם."},{"i":31305,"n":"מסיכה, חי מטריפולי","bt":"תקן","dt":"תרי - בערך","b":"רב וסופר בטריפולי. חתם בפנקס בי\"ד טריפולי."},{"i":31306,"n":"מסינג, יוסף מויטקוב","f":"אהרן","k":"בעל ארונו של יוסף","b":"רב בגאסטין, שעמפין, ויטקוב(=ויטקאווא)."},{"i":31307,"n":"מסיני, יצחק הפייטן","f":"יוסף","b":"רופא ופייטן. חיבר פיוט \"מי כמוכה\" במחזור רומניה. אולי הוא אחיו של ר ישעיה מסיני."},{"i":31308,"n":"מסך, סעדיה מתימן","b":"מחכמי צנעא-תימן-תקכה ונזכר אז בפנקס בית דין."},{"i":31309,"n":"מסליאנסקי, אברהם יצחק מארה\"ב","f":"יהודה ליב","k":"בעל ספר ההטפה","bp":"סלוצק","b":"חתן ר דוד בנימן מסלוצק (שהיה רבו של ר חיים סולוביציק). עבר ללונדון וניהל ת\"ת, הגיע לניו יורק והיה דרשן ומלמד תורה."},{"i":31310,"n":"מסלתון, בכור הכהן מדמשק","bt":"תקצא","b":"דרשן, דיין ומו\"צ בדמשק אצל ר יצחק אבולעפיא בעל \"פחד יצחק\"."},{"i":31311,"n":"מסלתון, יעקב מביירות","bt":"תריא","bp":"דמשק","b":"דרשן, דומ\"צ בביירות-תרנז בביהמ\"ד של ר רפאל הלוי."},{"i":31312,"n":"מסנגווי אשכנזי, אברהם מקושטא","f":"שמואל","b":"מגיה בדפוס ר שלמה אושקי בקושטא-שכא."},{"i":31313,"n":"מסנות, שלום מספרד","b":"מחכמי ספרד, לאחר הגירוש הגיע לתונס, ולפאס. היה מעורב במחלוקת הנפיחה עם ר משה חלאווה."},{"i":31314,"n":"מסנות, שמואל מחלב","f":"נסים","k":"בעל מעין גנים","b":"רב בארם צובא בזמן ר יהודה אלחריזי - ד'תתקף. חיבר גם ילקוט על התורה."},{"i":31315,"n":"מסעוד בן שמעון ממצרים","f":"שמעון ן, מסעוד","k":"בעל אגרת שבוקין","dt":"תרפה - כ ניסן","b":"רב במצרים. חתן אחיו ר רפאל אהרן ן שמעון. חיבר גם \"שערי משפט\", \"שם חדש\" ועוד."},{"i":31316,"n":"מסעוד בנימין ממצרים","k":"בעל לקט שכחה"},{"i":31317,"n":"מסעוד הכהן מדרעא","f":"גואשוש, מסעוד מצליח","b":"מקובל מחכמי דרעא-שנות ה-ש', עלה לצפת-שלז."},{"i":31318,"n":"מסעוד הכהן מדרעא-מרוקו וצפת","b":"מקובל מחכמי דרעא-מרוקו-שנות ה-ר', עלה לצפת."},{"i":31319,"n":"מסעוד הכהן ממרוקו ואלגיר","f":"אליהו","k":"בעל פרחי כהונה","bp":"תאפילאלת-מרוקו","dt":"תשי","dp":"ווהראן","b":"תלמיד ר ישראל הבבא סאלי בתפיללאלת, תלמיד אביו וגיסו ר דוד אבוחצירא הי\"ד - ר דוד נשא את אחות ר מסעוד. מלמד תורה ומתלמידיו: ר פנחס אביטבול (טבול). חיבר \"פרחי כהונה\". רב בתאמושנת."},{"i":31320,"n":"מסעוד הכהן מתאפילאלת","b":"רב בטנג'יר-תפט, תאפילאלת, שאלה ממנו ליעב\"ץ."},{"i":31321,"n":"מסעוד מאלגיר","bt":"ש","dt":"שע - בערך","b":"רב בקצמטינא. נזכר בשו\"ת נפך לר אברהם ן טוואה."},{"i":31322,"n":"מסעוד מארבאט-מרוקו","f":"נחמן","b":"רב בארבאט-מרוקו-תלד, נזכר אצל ר מאיר טאפיירו."},{"i":31323,"n":"מסעוד ממרוקו","b":"מקובל במרוקו-תק\"כ"},{"i":31324,"n":"מסעוד מצפרו-מרוקו","f":"יתאח בן עמוד","dt":"תר - בערך","b":"נכד ר משה בן חמו. מחכמי צפרו, שו\"ב ודיין בזמן ר שאול ישועה אביטבול."},{"i":31325,"n":"מסעוד מתלמסאן","f":"יצו","k":"בעל אבי שר שלום,בעל אבי שר שלום-תשנד","bt":"תקצה","dt":"תרסב","b":"רב ומלמד תורה בתלמסאן. חיבר גם פירוש על הלכות שחיטה - ואבד."},{"i":31326,"n":"מסעוד ן, יצחק","f":"ישועה","b":"חתם על שטר-תקצו."},{"i":31327,"n":"מסעוד, יהודה ממצרים ודמשק","f":"יצחק מדמשק","k":"בעל יד יהודה","bp":"דמשק","b":"גלה במקומות שונים, רב במצרים, עלה לירושלים-שמט, צפת, רב בדמשק לעדת סיציליה על מקום ר משה נג'ארה. תשובות ממנו ב\"זרע אנשים\"."},{"i":31328,"n":"מסעוד, יוסף מתימן וירושלים","dt":"תרמו","dp":"ירושלים","b":"עלה לירושלים-תרמה, מחכמי תימן בירושלים."},{"i":31329,"n":"מסעוד, יצחק מדמשק","b":"רב בקהלת הספרדים בדמשק-רפא."},{"i":31330,"n":"מסעוד, יצחק מצפת","b":"דיין בצפת אצל ר יוסף קארו. בנו ר יעקב מסעוד שחתם-שלה על שטר התקשרות ר חיים ויטאל."},{"i":31331,"n":"מסקולנסקי, יעקב צבי מבערטא","f":"חיים אהרן","bt":"תרלה","b":"רב בברטי(=בערטא)-פלך קיוב-תרנט."},{"i":31332,"n":"מסקין, יעקב הכהן מליטא ונ\"י","f":"מרדכי","k":"בעל אבן יעקב","bt":"תרמד","bp":"וילקומיר","dt":"תשטז","b":"תלמיד ישיבת סלובודקה. נסמך מאת: ר יצחק רבינוביץ מפוניבז, ר מאיר אטלס משאוול, ר יוסף ליב בלוך מטלז. רב בנובה-פרגה-פלך חרסון, פוניביז, היגר לארה\"ב וכיהן כרב בבורלינגטון, ניו יורק. חבר בועד של אגודת הרבנים באמריקה. חיבר גם \"בית יעקב\" נ\"י תרץ, ועוד. פרסם מאמרים ב\"כנסת ישראל\" - נ\"י תרצב - כתב עת הסתדרות תלמידי סלובודקה באמריקה, \"כנסת ישראל\" - סלובודקה-ויליאמפולי תרצח - כתב עת תלמידי \"כנסת ישראל\" בסלובודקה, \"המסלה\" - נ\"י תרצו, \"הפוסק\" - תל אביב תש-תשיד.","bk":[["אבן יעקב – חגיגה מגילה ושו\"ת",""],["משפט ליעקב – חו\"מ",""]]},{"i":31333,"n":"מסר, יצחק מסנוק","f":"אריה ליב","k":"בעל וממדבר מתנה","bt":"תרנא","bp":"סכודניצה","dt":"תשג - ד חשון","dp":"סיביר","b":"מחכמי סנוק, בעל תואר אקדמי ומלומד בקבלה. רוב חיבוריו אבדו בשואה. נדפס ממנו חיבורו שכתב בסיביר \"וממדבר מתנה\" ירושלים תשמה."},{"i":31334,"n":"מסראן, יצחק או ישראל משלוניקי","dt":"תנט","dp":"שלוניקי","b":"מחכמי שלוניקי, ספרא רבה של פנקסי הקהלה. בשליחות הקהלה בקושטא יחד עם הגביר ר יעקב אבוהב."},{"i":31335,"n":"מסראן, לוי משלוניקי","f":"יצחק משלוניקי","dt":"תצח","dp":"שלוניקי","b":"מחכמי שלוניקי."},{"i":31336,"n":"מעארך, חי מאלגיר","bt":"תקף","dt":"תרן - בערך","b":"רב בגילמא-אלגיר, ממסייעי הדפסת הגדת \"ויגד לאברהם\" ליוורנו תרכב."},{"i":31337,"n":"מעארך, נסים מתונס","b":"רב בתונס בזמן ר ישועה בסיס. נספד ע\"י ר אברהם יצחקי ב\"חסדי כהונה\"."},{"i":31338,"n":"מעבל, אליהו מהארקי","f":"בנימין","bt":"תרכד","b":"רב בגורקי(=הארקי)-פלך מוהילוב-תרסג."},{"i":31339,"n":"מעבל, לוי יצחק מטשערטרסק","f":"שאול מטשערטרסק","b":"רב בטשערטרסק-תרן, וחתנו ר משה יוטער על מקומו אחריו."},{"i":31340,"n":"מעבל, משה יהודה ליב מטולצין","f":"צבי","dt":"תרכו - יט אדר","dp":"ירושלים","b":"חתן ר משה מגיד ריבלין. רב בטוליצין(=טולצין), עלה לירושלים. חתניו - ר אברהם בהר\"ן, ר בנימין ריבלין, ונכדו - ר יצחק צבי ריבלין."},{"i":31341,"n":"מעבל, שאול מטשערטרסק","b":"רב בטשערטשערסק(=טשערטרסק)-פלך מוהילוב-תרך, ובנו ר לוי יצחק על מקומו אחריו."},{"i":31342,"n":"מעברי, משה מירושלים","b":"תלמיד ישיבת \"שערי ציון\" בירושלים. פרסם מאמרים ב\"בכורי ציון\" - ירושלים תשד."},{"i":31343,"n":"מעד, עזרא","b":"רב בפוניבאז'-תר\"ס"},{"i":31344,"n":"מעדויעדיוו, דוד משה מראקיטנא","f":"זאב","bt":"תרכח","b":"תלמיד זקנו ר חיים מראקיטנא. רב ברקיטנא-פלך קיוב-תרנט על מקום זקנו. נסמך מאת: ר משה מואסליקוב-פלך קיוב, ר ישראל יוסף בן ברוך בבראויארי וסלובודקא-פלך קיוב!"},{"i":31345,"n":"מעדין, עזריאל אברהם מציטאוויאן","dt":"תשא-ג","b":"רב בציטאוויאן(=ציטוון)."},{"i":31346,"n":"מעדריאלי, מאיר מבבל","b":"מחכמי בבל בזמן רב סעדיה גאון."},{"i":31347,"n":"מעהל, ישראל מדראגאווע","dt":"תשג","b":"חתן ר אברהם בנימין טייץ מארה\"ב. רב בדראגאווע. נספה בשואה עם משפחתו."},{"i":31348,"n":"מעוצה, שלמה מתימן","b":"רב ודיין בד'מאר-תימן, בתחילת המאה ה-20."},{"i":31349,"n":"מעט, אורי מויליצקה","b":"רב בויליצקה-תרפח על מקום חותן חותנו (וקיבל את הרבנות כנדוניה). עבר לארה\"ב."},{"i":31350,"n":"מעט, יהודה יחזקאל מוארשא","dt":"תרץ - ח אלול","dp":"אוסטרובצא","b":"גביר בוארשא, נשיא כולל פולין לעניי ארץ ישראל, עבר לאוסטרובצא. בנו - ר ירחמיאל מלונדון בעל אבן יחזקאל."},{"i":31351,"n":"מעט, יצחק גדליהו הכהן","f":"בן ציון מברוזדוביץ","b":"תשובה אליו מזקנו ב\"שות הד\"ר\"."},{"i":31352,"n":"מעט, ירחמיאל מלונדון","f":"יהודה יחזקאל מוארשא","k":"בעל אבן יחזקאל","b":"רב בלונדון."},{"i":31353,"n":"מעט, פנחס דניאל מבלזוב","f":"יוסף","bt":"תרא","dt":"תרפה","b":"נסמך מאת: מהר\"י שמלקיס מפרמישלא. מו\"צ בבלוזוב-תרמא."},{"i":31354,"n":"מעטוף, סעדיה מתימן","b":"דיין בחבאן-תימן בתחילת המאה ה-20. התפרנס מכתיבת סת\"ם."},{"i":31355,"n":"מעטי אלתלמסאני, אברהם מאלגיר","bt":"ד'תתק","dt":"ד'תתקס","b":"רב ונגיד בתלמסאן - אולי הוא ראשון הרבנים שם. נזכר בשטר בגניזה בקהיר יחד עם ר יוסף ן עזרה"},{"i":31356,"n":"מעייני, בצלאל מהוד השרון","f":"דב","bt":"תשה","bp":"מגדיאל","dt":"תשסט","b":"תלמיד ישיבת תפארת ציון, פוניבז. רב בהוד השרון-תשנב על מקום ר פרץ אריאל."},{"i":31357,"n":"מעייני, דב ממגדיאל","bt":"תרסד","dt":"תשיב","b":"דרשן,רב פעלים, רב ביאלובקה, עלה למגדיאל. פרסם מאמרים ב\"תורת ארץ ישראל\" - ירושלים תרץ."},{"i":31358,"n":"מעלי, אברהם הכהן מירושלים","f":"בנימין?","b":"דיין בירושלים-תק-ל בזמנו של ר יעקב אלגזי בעל \"שארית יעקב\" שכתב עליו."},{"i":31359,"n":"מעלי, בנימין הכהן (הזקן)","f":"חיים שלום","bt":"תל","bp":"ירושלים","dt":"תצב או תקד","dp":"ירושלים","b":"דיין בירושלים בבית דינו של ר אברהם יצחקי, בשנת תע בשליחות בפרס, בדרכו פגש בארם צובא את ר משה הררי. היה רב במצרים ודיין אצל ר נסים שלמה אלגזי יחד עם ר ישועה שבאבו, בשנת תפו חזר לירושלים ובשנת תפט התמנה לראשון לציון לאחר פטירת ר אברהם יצחקי,"},{"i":31360,"n":"מעלי, בנימין הכהן (הנכד)","f":"חיים שלום הכהן","b":"מחכמי ירושלים, נכד לסבו בעל אותו השם, בשליחות טבריה-תקלח והשתקע בקהילת הספרדים בהמבורג. בשנת תקל הביא לדפוס \"יסוד מורא\" לר אברהם אבן עזרא, המבורג, ועוד ספרים שם. הוציא ספר \"המבקש\" לר שם טוב פאלקירא האג תקלה, בין המסכימים לספר היה החיד\"א ששהא אז בהולנד, בנו - ר חיים ונכדו - ר בנימין משה."},{"i":31361,"n":"מעלי, חיים הכהן ממצרים","f":"בנימין הכהן מעלי","b":"רב במצרים-תקמ. ולפי רוזניס היה אחיו של ר בנימין ולא בנו."},{"i":31362,"n":"מעלי, חיים שלום הכהן מירושלים","k":"בעל הוספות לימין משה","b":"מחכמי ירושלים-תקכ (? כך באוצר ואולי החליף בינו לבין נכדו), הסכים על ספר \"פרי האדמה\" לר מיוחס בן שמואל, תשובה ממנו במכון (107). חיבר הוספות והגהות על \"ימין משה\" לר חיים משה קריגל - אמשטרדם תקמא. סדר בדפוס של ר אברהם רוזניס-תעט. אביו של ר בנימין ממצרים וירושלים."},{"i":31363,"n":"מעלי, משה הכהן","b":"קבלה בידם שהם ממשפחת עלי הכהן,מגדולי רבני מצרים"},{"i":31364,"n":"מעליש, ליב מפרג","b":"תלמיד ר יונתן איבשיץ. ראב\"ד בפרג-תקל."},{"i":31365,"n":"מעליש, צבי הכהן","k":"חתן התוספות יום טוב","dt":"תה - ג סיון","b":"גביר בפרג,דיין בקרקא"},{"i":31366,"n":"מעלם, יהודה מבצרה","b":"חכם ורב ראשי בבצרה"},{"i":31367,"n":"מענג, אברהם מאנגליה","f":"נפתלי","b":"תרגם ופירש פרקי אבות באנגלית - לונדון תקלב."},{"i":31368,"n":"מענית, שלום מספרד","b":"מחכמי ספרד, לאחר הגירוש הגיע לפאס-רנב. היה מעורב במחלוקת הריאה עם ר חיים גאגין."},{"i":31369,"n":"מענצלש, יוסף בנימין וולף מפרשב","dt":"תקז - יז חשון","dp":"פרשבורג","b":"מחכמי פרשבורג"},{"i":31370,"n":"מענצלש, ישראל ליזר מפרשבורג","b":"מחכמי פרשבורג, חתם-תקנז על חידוש תקנות החברא קדישא שתיקן ר יום טוב ליפמן מפרשבורג."},{"i":31371,"n":"מענצלש, ליזר מפרשבורג","f":"ר\"ח","dt":"תקפז - כו שבט","dp":"פרשבורג","b":"מחכמי פרשבורג"},{"i":31372,"n":"מעסינג, אהרן יונתן מניו יורק","b":"רב ד\"ר ריפורמי? במקלנבורג, ניו יורק-1869 בקהלת \"בית ישראל\", שיקגו בקהלת \"בית שלום\", סן פרנציסקו. חיבר ספרים באנגלית"},{"i":31373,"n":"מער, משה","dt":"תרנה - ג טבת","b":"רב ברעטה(=ראטה)."},{"i":31374,"n":"מערבי חלאק, יהודה אברהם מדמשק","b":"דיין בדמשק-תרצו."},{"i":31375,"n":"מערבי, אברהם הכהן מירושלים","b":"מראשי עדת המערבים בירושלים, חתום על שליחות תרלד."},{"i":31376,"n":"מערבי, אליהו משה","f":"משה","bt":"תרלג","bp":"דמשק","b":"מקובל, עלה לירושלים-תרעד, בשליחות בדרום אמריקה-תרפד, בהודו וסין-תרצב."},{"i":31377,"n":"מערבי, דינר מירושלים","f":"עוליל","b":"בשנת שפה חתם בין חכמי ירושלים להתחבר לאגודה. בשנת שץ חתם על כתב שליחות של ר אברהם רימון ור שמואל ביטון שיצאו בשליחות לצפון אפריקה אחרי תלאות אבן פארוך"},{"i":31378,"n":"מערבי, מסעוד כהן סגי נהור מצפת","b":"מקובל מחכמי פאס, ועלה לצפת-שלד, בזמן ר אברהם גלנטי בעל \"קול בוכים\". ונזכר בספר החזיונות למהרח\"ו."},{"i":31379,"n":"מערבי, מרדכי מירושלים","b":"מחכמי ישיבת \"כנסת ישראל\" בירושלים-תקיח."},{"i":31380,"n":"מערבי, נחום ממרוקו","b":"מחכמי מרוקו הקדומים. תרגם את אגרת תימן לרמבם וביאור ספר יצירה לעברית."},{"i":31381,"n":"מערבי, רפאל מנחם מדמשק","bt":"תרכג","bp":"דמשק","dt":"תרצג - כג טבת","dp":"ירושלים","b":"רב בדמשק-תרפג, עלה לירושלים והיה מחכמי המקובלים בירושלים."},{"i":31382,"n":"מערבער, בנימין","dt":"תרסב - כג חשון","b":"מו\"צ בווינוטא, רב בוורנה."},{"i":31383,"n":"מעריך, אהרן מטשיטש","b":"פרסם מאמרים ב\"כרם בית שמואל\" - פיעטרקוב תרצב - כתב עת תלמידי ישיבת אלכסנדר."},{"i":31384,"n":"מערינהולץ, יצחק מירושלים","f":"משה","k":"בעל תורת יצחק","b":"תלמיד ר שלמה יהודה מלענטשנע, מקורב לאדמורים ר יצחק מווארקא, ר יעקב מראדזמין, המגיד מטריסק ואחרים. עלה לירושלים. הניח חדושי תורה ונדפסו ע\"י בניו: ר מאיר ור יעקב מרדכי."},{"i":31385,"n":"מערכי, שמעון","b":"מקובל,מחכמי אשכנז-ש\"פ"},{"i":31386,"n":"מערקל","b":"רב בעדנבורג-רס\"ז"},{"i":31387,"n":"מעשיל הכהן מבוריסוב","b":"רב בבוריסוב-תרמ\"ב"},{"i":31388,"n":"מעתוק - משפחה","b":"משפחה בענאה-(=נהרדעא), וממנה נסתעפה גם משפחת יהודה."},{"i":31389,"n":"מעתוק, חי מבגדד","b":"מחכמי בגדד - שנות ה-תר', תלמיד ר שמעון אגסי."},{"i":31390,"n":"מעתוק, מרדכי הלוי סיידא מצידון","bt":"תרא","bp":"צידון","b":"רב בצידון."},{"i":31391,"n":"מפסקי רבו"},{"i":31392,"n":"מץ, אברהם מאה\"ו","dt":"תמה - כב אב","dp":"אה\"ו","b":"חתן ר ליב הערפורט-גיסו של ר שמואל זנויל מדעקשער, בזיוו\"ש חתן הפרנס ר אליהו בן דוד כץ מאלטונא. נהרג עק\"ה. נזכר ב\"זכרונות גליקל\"."},{"i":31393,"n":"מץ, אפרים פישל מאומאן","f":"משה מסקווירא","bt":"תרכח","b":"נכד ר נפתלי צבי מזארנישטש וסקווירא. מצאצאי ר יעקב עמדין. רב בזרניטש-פלך קיוב-תרנו, טפליך-פודוליה, אומאן-תרע. חתנו - ר יוסף יהודה דערברמדיקר."},{"i":31394,"n":"מץ, יצחק איזיק ממיינץ","f":"אשר","dt":"תריב - י שבט","dp":"המבורג","b":"דיין במיץ-תקס?, רב במיינץ, תלמידו הרב בערנייס ממיינץ שעבר להמבורג הביאו עמו להמבורג וכיהן כדיין, לאחר פטירת תלמידו מילא את מקומו עד למינוי ר אשר אנשל שטרן. הו\"ל \"קהלת דוד\" - רשימת הספרים של ר דוד אופנהיים. (תאריך פטירתו הינו תריב ולא תקיב - כפי שנרשם בטעות באוצר הרבנים)."},{"i":31395,"n":"מץ, ישראל מארה\"ב","f":"שניאור","bt":"1869","bp":"קאלואריה","dt":"1950","dp":"ניו יורק","b":"מצאצאי ר מרדכי יפה בעל הלבושים, ומצד אמו מצאצאי ר אברהם אחי הגר\"א. למד בחדר מתוקן, תלמיד ר ישראל מאיר אלקס. פרסם מאמרים ב\"הצפירה\", \"המליץ\", ועוד. היגר לארה\"ב, רכש פטנט לתרופה \"אקס לקס\" והתעשר. תרם לצדקה ולמפעלים ציוניים ורכש קרקעות בארץ. ממיסדי ביה\"ס \"הרצליה\" בנ\"י, תרם לביהמ\"ד לרבנים של שכטר, ועוד. יסד \"קרן מץ\"-תרפה לתמיכה בסופרים עבריים."},{"i":31396,"n":"מ\"ץ, מאיר","b":"מו\"צ בקובנה-תקפ\"ד(לא ניתן היה למנות רב)"},{"i":31397,"n":"מץ, מאיר ליב מגרינקישק","f":"יהושע מרדכי","k":"בעל נתיב מאיר","bt":"תרנג","bp":"פלונגיאן","dt":"תשא-ג","dp":"קרוק","b":"תלמידי ישיבת טלז. רב בגרינקישוק. הניח חיבורים בכת\"י. נספה בשואה. פרסם מאמרים ב\"כנסת ישראל\" - סלובודקה-ויליאמפולי תרצח - כתב עת תלמידי \"כנסת ישראל\" בסלובודקה.","bk":[["נתיב מאיר","מפרשי רמב\"ם"],["נתיב מאיר – רמב\"ם",""]]},{"i":31398,"n":"מ\"ץ, משה","f":"נפתלי צבי","b":"רב בסקווירא-תרכ\"ח"},{"i":31399,"n":"מצה ן, אהרן ממונסטיר","b":"רב במונסטיר-שנות ה-ש'."},{"i":31400,"n":"מצוררי, משה הקראי מקושטא","b":"מחכמי הקראים בקושטא-שנות ה-ש'. פעל לכתיבת פירוש התורה \"כליל יופי\" לר מרדכי כומטיאנו - ע\"י הסופר שבתי בכר משה (הקראי?)"},{"i":31401,"n":"מציפ, אברהם משלוניקי","dt":"ש - יד תשרי","dp":"שלוניקי","b":"מחכמי שלוניקי."},{"i":31402,"n":"מצלח פדובה, מנ' יהושע","b":"חכם השלם,רב במודנא-ת\"ק"},{"i":31403,"n":"מצליח המערבי מאיטליה","b":"מחכמי צפון אפריקה, עבר לאיטליה בזמן הרמ\"ע מפאנו, שהזכירו בתשובותיו."},{"i":31404,"n":"מצליח מאיר מאזמיר וירושלים","dt":"תקיז - כט סיון","dp":"ירושלים","b":"מצאצאי ר שמואל דניאל בעל \"זקן שמואל\" והו\"ל את ספרו - אזמיר תקטז. רב בירושלים. חתנו ר משה סוסי מזכירו בספר זקנו (של ר משה) \"דבר שמואל\". (לפי גליס - חתנו ותלמידו של ר משה סוסי, ותאריך פטירתו - תקסז)."},{"i":31405,"n":"מצליח עובדיה מאנקונה","b":"רב באנקונה, פיררה. הדפיס \"חזון עובדיה\", \"יין הרקח\" ועוד."},{"i":31406,"n":"מצליח, אברהם מאזמיר","b":"דיין, מחכמי איזמיר"},{"i":31407,"n":"מצליח, אברהם ממגניסיאה - א","k":"בעל מאמר המלך","b":"רב במגניסיאה-תקן, יסד חברת \"בקור חולים\"-תקנה. חיבר \"מאמר המלך\" בכת\"י."},{"i":31408,"n":"מצליח, אברהם ממגניסיאה - ב","b":"נכד ר אברהם ממגניסיאה. רב במגניסיאה-תרס."},{"i":31409,"n":"מצליח, אלעזר מאלכסנדריה","dt":"שעו","b":"מחכמי אלכסנדריה"},{"i":31410,"n":"מצליח, חיים יוסף מקושטא","b":"מחכמי קושטא - בשנים תק-תקן."},{"i":31411,"n":"מצליח, ישראל מצפת","b":"מחכמי צפת, בשנת תקנא חתם על כתב שליחות ר חיים מודעי."},{"i":31412,"n":"מצליח, מאיר מירושלים","dt":"תקכג - כג סיון","dp":"ירושלים","b":"מחכמי ירושלים, בשליחות בצפון אפריקה והיה גם באלגיר - מתורתו ב\"קרבן אהרן\" לר אהרן מועטי."},{"i":31413,"n":"מצליח, מנחם עזריה מאיטליה","b":"רב בפדובה?, פירנצה, מודנא. הסכים על כמה ספרים."},{"i":31414,"n":"מצליח, משה חיים ממגניסיאה","k":"בעל אם הבנים","dt":"תרנז - יח אב","dp":"ירושלים","b":"רב במגנסיא(=מגניסיאה), בסוף ימיו עלה לירושלים. חיבר \"אם הבנים\" אזמיר תרלג."},{"i":31415,"n":"מצליח, משה מצפת","dt":"תקץ","dp":"צפת","b":"דיין מחכמי צפת, בשנת תקנא חתם על כתב שליחות ר חיים מודעי. בשליחות באיטליה והודו. נספד בספר \"אם לבנים\" לבן אחיו."},{"i":31416,"n":"מצליח, נסים משלוניקי","b":"מורה בביה\"ס ת\"ת בשלוניקי-לפני השואה."},{"i":31417,"n":"מצליח, נסים משלוניקי","bt":"תרלה","bp":"אזמיר","b":"פרופסור למשפטים בקושטא, שופט מטעם השלטון התורכי בשלוניקי, וחבר פרלמנט מטעם אזמיר. הו\"ל עתון בקושטא, פרסם מאמרים בתורכית."},{"i":31418,"n":"מצליח, נתן מטבריה","b":"קברו נתגלה ליד קבר הרמבם בשכונת מיימוניה."},{"i":31419,"n":"מצליח, צאלח","b":"איש מופת,רבה של בגדד-תקל\"ה"},{"i":31420,"n":"מצליח-פדובה, מנשה יהושע ממודנא","f":"יהודה ממודנא","bt":"תן - בערך","dt":"תקי - בערך","b":"חתן הרב\"ך. רב במודנא-איטליה על מקום אביו. תשובות ממנו ב\"שמש צדקה\", ובספר אביו \"פני הכרובים\". הסכים על 'אור החיים' - ונציה תקב יחד עם ר אברהם חי גרציאנו. גיסו - ר ישעיה בסאן בעל \"תודת שלמים\"."},{"i":31421,"n":"מצמוני, יוסף מירושלים","b":"חתם-תקיו על שטר התקשרות עם חכמי ירושלים."},{"i":31422,"n":"מצמוני, יוסף סעיד מתימן","b":"מחכמי תימן, רב בירושלים. שליח ישיבת \"עץ חיים\" בתימן."},{"i":31423,"n":"מצעדה, יהודה","f":"שלמה","b":"מחכמי תימן,מרבני צעדה,חיבר בערבית פירוש פילוסופי לתורה בשם \"אל חקאק\",הספר הוחרם בצנעא"},{"i":31424,"n":"מצרי, אברהם מצפת","b":"דיין בצפת-תעג, וחתם אז על כתב שליחות ר שמואל בן עובדיה הלוי, ובשנת תפב על מכתב לקהילת פיזא."},{"i":31425,"n":"מקאמיריני, שלמה יחיאל מאיטליה","b":"רב ודרשן באנקונה-תקמח. נזכר באגרות החידא."},{"i":31426,"n":"מקאס, דוד","b":"בשנת שח חתם על התקונה לשחרר תלמידי חכמים ממס."},{"i":31427,"n":"מקאתל, יוסף מאלגיר","dt":"קסח - לפני","b":"דיין במסתגאנם, נזכר בשו\"ת הריב\"ש."},{"i":31428,"n":"מקובסקי, צבי","k":"בעל יחוה דעת","bt":"תרמד","bp":"קאליש","dt":"תרצח","dp":"ירושלים","b":"למד אצל ר אברהם מסוכטשוב. רב בגולין פיציקא וזלוטופול. עלה לירושלים בשנת תרצג. חיבר \"יחוה דעת\" ו\"אשיבה שופטיך\". היה חבר בית הדין של תל אביב. פרסם מאמרים ב\"המאור\" - תל אביב תרצה."},{"i":31429,"n":"מקור ברוך - ישיבה בירושלים","b":"ישיבה בירושלים-תחילת שנות ה-תק'."},{"i":31430,"n":"מקלבסקי, צבי","dt":"תשג","b":"רב בקאבילניק"},{"i":31431,"n":"מקלר, דוד ליב מארה\"ב","k":"בעל פון רבינס הויף","bt":"1891","bp":"וילנא","dt":"1976","b":"היגר לארה\"ב והיה עורך \"אידישער אדווקאט\", \"ג'ואיש וויקלי\", ועוד. פרסם בשם \"בן שלמה\". חיבר ספרים באנגלית ובאידיש מחיי החסידים. חיבר גם \"דער אמת וועגען הענרי פארד\", ועוד. ?? לא באוצר ??"},{"i":31432,"n":"מקנז, שמואל מגזילי","b":"רב בגזילי-ליד תירייא - בדור שלאחר הגירוש."},{"i":31433,"n":"מקרר, שלמה","dt":"תשג","b":"רב בוורשה"},{"i":31434,"n":"מקשן, שמואל","k":"בעל ביאור על מגלות","b":"חיבר ביאור על מגילות - קראקא."},{"i":31435,"n":"מר חיים, יעקב הספרדי","f":"יצחק","b":"מחכמי ירושלים חתם בשנת רסט על התקנה לשחרור תלמידי חכמים ממס."},{"i":31436,"n":"מר חיים, יצחק מספרד","f":"שמואל","k":"בעל ספר בקבלה","bp":"ספרד","b":"מחכמי ומקובלי ספרד, ערב הגירוש-רנא היה בנפולי-איטליה בדרכו לארץ ישראל, וכתב שם אגרות לר יצחק בן יחיאל מפיסא (נדפסה על ידי נדב בתרביץ). עלה לירושלים ולמד בישיבה והיה מחכמי ישיבת הנגיד בירושלים. לפי רוזניס עלה משלוניקי. חתם על תקנות המסים-רסט, בין החותמים גם ר יעקב בן יצחק - כנראה בנו. עבר לצפת ולימד שם תורה, בידידות עם ר יעקב בירב ומובא בספרו של ר יעקב בירב. חיבר ספר בקבלה בכתב יד."},{"i":31437,"n":"מר חיים, ששון מאדרינופול","b":"רב באדרינופול-שנות ה-ש'."},{"i":31438,"n":"מר יוסף ן, יצחק","f":"ישועה","b":"חתם על שטר-תקץ."},{"i":31439,"n":"מר שלמה בן מנחם","bt":"1850","dt":"ה'תרעב 1912","bk":[["דברי שלמה",""]]},{"i":31440,"n":"מר, שכנא","bt":"1863","bp":"פוסבול","dt":"1930","dp":"פוניבז","b":"רופא ועסקן ציבור. יסד בית חולים לעניים בפוניבז, עוזר לנזקקים, וגם רעייתו חנה עסקנית ועוסקת בצדקה וחסד. בנו גדעון - רופא בראש פינה."},{"i":31441,"n":"מראג'י, משה מטנג'יר","b":"רב בטנג'יר - במאה ה-19."},{"i":31442,"n":"מראג'י, נתן ממכנאס","dt":"תקצח - יב אדר","dp":"טבריה","b":"עלה לטבריה, וחתם עם ר יהודה נחמד-תקצב על שטר חוב שלוה ר פרחיה סרגוסי מר אברהם חיים גאגין."},{"i":31443,"n":"מראווי, אריה ליב","b":"דיין בלבוב-תצ\"ט"},{"i":31444,"n":"מראנג'י, נתן","b":"מחכמי צפת, בשנת תקסט בשליחות לאיטליה, וחזר בתקצה."},{"i":31445,"n":"מראני, חזקיה מטריפולי","b":"רב הכולל בטריפולי-תרל ור אברהם חביב על מקומו אחריו."},{"i":31446,"n":"מראני, יעקב","b":"מקובל במרוקו-ש\"פ"},{"i":31447,"n":"מראק, פסח","f":"זוסמן","k":"בעל שתי גזירות","bt":"1862","bp":"שאדובה","dt":"1920","dp":"סארטוב","b":"למד משפטים במסוקבה יחד עם אוסישקין, מאז\"ה, ואחרים. פרסם מאמר על תולדות בתי הדפוס היהודים ברוסיה ב\"ווסחוד\". חיבר עם שאול גינצבורג מחקר על שירי עם יהודיים ברוסיה בשם \"אידישע פאלקסלידער\". נשלח מטעם \"חברת מפיצי השכלה\" לתחום המושב\" לחקור את נושאי החינוך וההוי היהודי ופרסם ספר ברוסית על כך. חיבר מסות על מאבק המשכילים והחרדים"},{"i":31448,"n":"מרבינו - משפחה","b":"משפחה מקמינקא."},{"i":31449,"n":"מרבינו, אברהם דוד ממיראפאליע","k":"ר דוד'ל מיראפאליר","b":"נכד ר אברהם דוד טרוטשר, נכד ר שמואל קאמינקר. מ\"מ במיראפאליע-ווהלין-תרע. בעל ספריה חשובה. בנו - ר שמואל קופלר בעל \"תפארת שמואל\"."},{"i":31450,"n":"מרבינו, דוד מקמינקא","b":"רב בקמינקא. היה לו 7 בנים ונקראו - די קאמינקער זיבען ברידער (והבעשט שיבחם), ומהם - ר צבי הירש מקמינקא-ממקורבי הבעשט."},{"i":31451,"n":"מרבינו, צבי הירש מקמינקא","f":"דוד מקמינקא","b":"רב בקמינקא. ממקורבי הבעשט. היה מכונה עם ששת אחיו - די קאמינקער זיבען ברידער."},{"i":31452,"n":"מרבינו, שמואל מקמינקא (קמינקר)","f":"יצחק איזיק","k":"שמואל קאמינקר","b":"נכד ר צבי הירש קאמינקר-ממקורבי הבעש\"ט, ומצאצאי ר אהרן טוטיווער-נכד הבעשט. מתלמידי הבעש\"ט, רב בקאמינקא-תקך. בנו - ר חיים קמינקר, ונכדו - ר אהרן בעל \"מורה דרך\"."},{"i":31453,"n":"מרבר, בנימין מוורנה","dt":"תרסב","b":"רב בוורנה-ליטא."},{"i":31454,"n":"מרבר, שלמה הכהן מקוזמינקא","b":"פרסם מאמרים ב\"קובץ דרושים\" - פיעטרקוב תרפג."},{"i":31455,"n":"מרגולין פיבל שרגא","bt":"1870","dt":"ה'תשב 1942","bk":[["שלשה בעלי המסעות לבית ישראל",""]]},{"i":31456,"n":"מרגולין, אשר מברדיטשוב","f":"נח","b":"תלמיד ישיבת וולוזין. נסמך מאת: הנצי\"ב. מו\"צ בליטא, בפלך יקטרינסלב, ברדיטשוב-תרע-פלך קיוב."},{"i":31457,"n":"מרגולין, ברוך זונדל","f":"שמואל אייזיק מרגולין","bt":"תרלו","dt":"תשד - כה ניסן","b":"רב באוניצה,ברוקלין,שיקגו,עלה לא\"י תרפ\"ט"},{"i":31458,"n":"מרגולין, יוסף ישעיה מנ\"י","b":"פרסם מאמרים ב\"הכרם\" - וארשא תרצא, \"קבוצי אפרים\" - יאסי-בוקרשט תרעד."},{"i":31459,"n":"מרגולין, יצחק צבי מסלדקובדנא","f":"דוד יהודה","k":"בעל קהלת יצחק","bt":"תריז","b":"רב בסלאדקוודנא(=קאבעלנא)."},{"i":31460,"n":"מרגולין, ישעיהו יוסף מניו יורק","k":"בעל תפארת מהרשי\"ם","b":"רב בבראנזויל, מונטריאול, ניו יורק-תרפא. עורך \"יגדיל תורה\" - וארשא-פראגא תרפז, \"בית ועד לחכמים\" נ\"י תשא. חיבר גם \"המעשה והמדרש\", \"דרושי מהרש\"ם\" נ\"י תרפא. פרסם מאמרים ב\"אהל מועד\" - איזביצא - בילגוריי - תרפו, \"אהל תורה\" - קראקא תרפח, \"בית ועד לחכמים\" - סטמר תרפב, \"יגדיל תורה\" - פראגא-וארשא תרפז. עורך \"בית ועד לחכמים\" - נ\"י תשא, \"חדרי תורה\" - קראקא תרפו, \"הנצח\" - לבוב תרפז, \"הנשר\" - טירנוי תרצג-תשד, \"קהילת יעקב\" - זבארוב-סלובקיה תרפה, \"שערי אורה\" - מיהאלביץ תרץ-תרצד, \"שערי ציון\" - ירושלים תרפא, \"תורת ארץ ישראל\" - ירושלים תרץ."},{"i":31461,"n":"מרגולין, לוי יצחק"},{"i":31462,"n":"מרגולין, שלמה זלמן","f":"אליעזר מרגליות","bt":"תקס","dt":"תרלו - יג אייר","b":"רב בפאריץ"},{"i":31463,"n":"מרגולין, שמואל איזיק","b":"מרביץ תורה במיר-תר\"מ"},{"i":31464,"n":"מרגולין, שמואל מברנובקי","f":"לוי יצחק","bt":"תריז","b":"נסמך מאת: ר אהרן מטשידנוב. רב בקונסטנטין-פודוליה-תרמז, ברנובקי-פלך זואהלין."},{"i":31465,"n":"מרגונטו, ירמיה מאזמיר - הנכד","dt":"תקכט - יז תשרי","dp":"אזמיר","b":"מחכמי אזמיר. אחיו - ר נסים חיים שלום."},{"i":31466,"n":"מרגונטו, ירמיה מכרתים וקושטא","f":"לוי","b":"מחכמי קנדיא (כרתים), עלה לצפת ולמד אצל ר יוסף קארו, אחר כך במצרים אצל ר בצלאל אשכנזי, ובסוף ימיו התיישב בקושטא בהיותו כבן 100 שנה. מוזכר בשות ר תם בן יחיא ומדבריו בספרי חכמי דורו, ובהם ר אהרן קונפינו."},{"i":31467,"n":"מרגונטו, ישעיה מאזמיר","f":"נסים חיים שלום","dt":"תקלט","b":"נפטר צעיר."},{"i":31468,"n":"מרגונטו, משה מקושטא","dt":"תקפד","dp":"קושטא","b":"אב\"ד בקושטא-שנות ה-תק'. נספד מאת ר יעקב רפאל מנשה בשלוניקי."},{"i":31469,"n":"מרגונטו, נסים חיים שלום יעקב","k":"בעל דרכי שלום","bp":"אזמיר","dt":"תקסט - כב כסלו","dp":"אזמיר","b":"תלמיד ר שלמה ברכה. חתן ר יעקב קלומיטי. רב בשומלה, אזמיר-תקסט וראש ישיבה שם, שלוניקי-תקס, מתא מחסיא. נספד ע\"י ר דוד אמאדו ב\"תהלה לדוד\". חיבר גם \"עושה שלום\", והו\"ל \"טל אורות\" לר יוסף ן ג'ויא. בנו - ר ישעיה נפטר בחיי אביו שהספידו, אחיו - ר ירמיה. מתלמידיו - ר יוסף שאול, ר אברהם די ג'אביש, ר אברהם ן עזרא."},{"i":31470,"n":"מרגושס, אליעזר","f":"יהודה","dp":"למברג","b":"סופר ונאמן ועד ארבע ארצות."},{"i":31471,"n":"מרגושס, אליעזר מלמברג","bt":"תקצא","dt":"תרנט","b":"מדפיס בלמברג."},{"i":31472,"n":"מרגושס, אלעזר ניסן מדרנא","f":"מנחם מנדל","bp":"למברג","dt":"תרצג","dp":"וינה","b":"נכד השר שלום. חתן ר יחיאל פפר מאוזירן וחתן ר משה פנט מדעש. רב בדרנא ווטרה בבוקובינה-תקסב."},{"i":31473,"n":"מרגושס, אריה אליעזר מלמברג","b":"מראשי קהילת למברג-תרכו"},{"i":31474,"n":"מרגושס, יוסף","f":"שמואל","k":"בעל דעראינערונגען פו","bt":"תרכז","bp":"למברג","dt":"תשטו","dp":"ניו יורק","b":"חתן ר מרדכי דוד שטיגליץ. היגר לארה\"ב-תרנח חזר לגליציה ושוב לניו יורק-תרסג. פרסם מאמרים בכתבי עת שונים. חיבר \"דעראינערונגען פון מיין לעבען\" ניו יורק תרצו. ?? לא באוצר ??"},{"i":31475,"n":"מרגושס, יוסף מלמברג","f":"אליעזר מלמברג","bt":"תקל","dt":"תר","b":"גביר מחכמי למברג"},{"i":31476,"n":"מרגושס, שמואל (אריה)","f":"יוסף מלמברג","bt":"תקעד","dt":"תרם","b":"עסקן מחכמי למברג. (בעל נכסים שהפסידם במפולת הבורסה - תרלג). חתן אחיו ר ניסן מרגושס."},{"i":31477,"n":"מרגל, נתן מדוקלא","b":"פרסם מאמרים ב\"הנשר\" - טירנוי תרצג-תשד."},{"i":31478,"n":"מרגל, שלום שכנא מפודגורזע","b":"ר\"מ בישיבה בפודגורזע-תרפט. פרסם מאמרים ב\"כתר תורה\" - סוסנוביץ-פיעטרקוב תרץ."},{"i":31479,"n":"מרגליות מרדכי","bt":"1909","dt":"ה'תשכח 1968","bk":[["אנציקלופדיה לתולדות גדולי ישראל",""]]},{"i":31480,"n":"מרגליות משה מרדכי בן שמואל","f":"שמואל","k":"בעל חסדי ה'","r":"ר\"מ בק\"ק קראקא","bt":"1550","dt":"שעז - י כסלו","dp":"קראקא","b":"תלמיד המהרש\"ל. מגדולי חכמי דורו, רב בוינה, קראקא. חיבר סליחה \"אלקים למדתני מנעורי\" לזקר הרוגי וארשוי-שנו - האחים משה ויהודה בני יקותיאל. התנגד ללימוד קבלה ברבים. נזכר ב\"עמודי עבודה\". חיבר גם \"מענה רך\". תשובה ממנו ב\"פלגי מים\". נזכר בכנה\"ג. בנו - ר יוסף.","bk":[["חסדי ה' - ביאור על הפס' ולך ה' חסד וי\"ג מידות",""],["מענה רך - תחינה לדופקים בתשובה",""],["חסדי ה'",""],["מענה רך",""]]},{"i":31481,"n":"מרגליות, אביגדור מטלז","f":"אברהם מטלז","dt":"תרמב","dp":"ירושלים?","b":"מחכמי טלז, עלה לארץ. בניו - ר צבי, ר אברהם (נפטר תרמז)."},{"i":31482,"n":"מרגליות, אביגדור מיברוב","f":"אליהו מבילגוריא","k":"בעל סוגה בשושנים","bp":"בילגוריא","dt":"תקע","dp":"רדיויל","b":"מחכמי ספרד בפולין (לפי ארזי הלבנון), רב בלבוב-תקמג, יברוב-תקנו. חתן ר פנחס מאשילס ואהל (רוכל) מלמברג. בנו ר נפתלי הרץ מפמורן. ההדיר \"פרק אליהו\" לר אליהו ב\"ר אשר הלוי עם פירושו \"סוגה בשושנים\" - למברג תקמג."},{"i":31483,"n":"מרגליות, אביעזרי (אליעזר) זליג","f":"יצחק אייזיק","k":"בעל כסף נבחר","bp":"פלאצק","dt":"תעה","dp":"ירושלים","b":"רב ודרשן בהלברשטט-תע, קאליש, התישב באיטליה. הדפיס: כסף נבחר, חבורי לקוטים. מתלמידיו - ר ישראל דרשן ור מאיר זליג."},{"i":31484,"n":"מרגליות, אברהם אבלי מבאקלי-ראו","dt":"תרלז","b":"תלמיד ר חיים וסרצוג מפיליפאוע בעל \"נשמת חיים\". מחכמי באקלי-ראווע."},{"i":31485,"n":"מרגליות, אברהם אליעזר","b":"אחיינו של ר יעקב ויידנפלד מהרימלוב - תשובה אליו \"כוכב מיעקב\" ועוד."},{"i":31486,"n":"מרגליות, אברהם דב מרדושקביץ","dt":"תרמג","b":"חתן ר שמואל באקשטר, וגיסו של ר יהונתן משה דב וואלינער. אב\"ד רדישקוביץ, ז'לודוק, ואסילקובא."},{"i":31487,"n":"מרגליות, אברהם דוד מוושילקובה","b":"רב בוושליקובה."},{"i":31488,"n":"מרגליות, אברהם מארה\"ב","b":"מנהל ת\"ת בניו יורק. בנו - ר זאב-חתנו של ר יעקב מורגרטן."},{"i":31489,"n":"מרגליות, אברהם מזולקווא","f":"שמואל מפוזנן","b":"מחכמי זולקווא, חתם-שפ-שפו על תקנות הקהלה. אחיו - ר מנחם מנדל מוילנא, ר משה מרדכי בעל \"חסדי ה'\", ר צבי הירש מלודמיר."},{"i":31490,"n":"מרגליות, אברהם מטלז","dt":"תר - בערך","b":"חתן ר זאב וולף אלטשולר מלוצין בעל \"זבד טוב\" ו\"שפת הים\". רב בטלז-תקץ ובנו (או נכדו) ר יהודה ליב על מקומו אחריו, בנו גם - ר אביגדור מטלז."},{"i":31491,"n":"מרגליות, אברהם מפריישטט","k":"בעל ברית אברהם","b":"מג\"מ בפריישטט-תר\"מ"},{"i":31492,"n":"מרגליות, אברהם מרד' מאיסטיטשקי","f":"יעקב מטלוסט","b":"רב באיסטיטשקי."},{"i":31493,"n":"מרגליות, אברהם נתן","b":"נכדו של ר גרשון מרגליות מסקלט. אביו כנראה חתנו של ר משה מסדיגורא בעל \"פני משה\". רב בסקלט, מורניץ, טשרנוביץ-תרכה, ברלד-תקצד."},{"i":31494,"n":"מרגליות, אברהם צבי מגלוסק","f":"מרדכי זאב","k":"בעל קרן אורה","bt":"תרכא","b":"רבה של גלוסק(=גלוסקא), למד אצל ר צדוק הכהן מלובלין. עלה לירושלים-תרסח. חיבר \"קרן אורה\" ירושלים תשכד, ועוד. חתנו - ר דוד ורנר מירושלים וארה\"ב."},{"i":31495,"n":"מרגליות, אהרן","f":"שמואל שמלקא מרגליות","b":"שנת תק\"ל(חותן ה\"נעם אלימלך\")"},{"i":31496,"n":"מרגליות, איסר אשר מראקישוק","f":"אליהו מראקישוק","k":"בעל שפת אמת","b":"רב בראקישוק-תרם - בקהילת המתנגדים - על מקום אביו, וחתנו ר שמואל לויטין על מקומו אחריו. חיבר \"שפת אמת\" על הלכות גדולות."},{"i":31497,"n":"מרגליות, אליהו","f":"שמואל בן מרדכי","b":"מצאצאי ר שמואל שיק. רב בכמה קהלות ברוסיה-פולין."},{"i":31498,"n":"מרגליות, אליהו מבאלטי וא\"י","bt":"תצ","b":"רב בעיר באלטי, עלה לצפת בשנת תקל, בשנת תקמח בשליחות ניצל מטביעת הספינה ליד אזמיר, בשנת תקן בשליחות לצפון אפריקה ואיטליה."},{"i":31499,"n":"מרגליות, אליהו מדרביאן","f":"יעקב","bt":"תקעו","dt":"תרלד","dp":"ירושלים","b":"רב בדארבינאן(=דרביאן)-ליטא (זאמוט) ור יוסף אלכסנדר על מקומו אחריו, עלה לירושלים, דיין בית דינו של ר מאיר אוירבוך, וגבאי בכולל וילנא-זאמוט."},{"i":31500,"n":"מרגליות, אליהו מוישיי-ליטא","b":"רב בוישיי. בנו ר יצחק מדרוסקניק ונ\"י."},{"i":31501,"n":"מרגליות, אליהו מקראקא","b":"דיין בקרקא-תנ\"ה"},{"i":31502,"n":"מרגליות, אליהו מראדין וראקישו","f":"מרדכי","b":"רב בראדין, ראקישוק-תרח - קהילת המתנגדים - ובנו ר איסר אשר בעל \"שפת אמת\" על מקומו אחריו. בניו: ר מרדכי מאילוקסט, ר יצחק מדרוזניק וארה\"ב."},{"i":31503,"n":"מרגליות, אליהו מרעמישלא","f":"מנחם מנדל מפרמישלא","b":"רב ברעמישלא-ת\"מ"},{"i":31504,"n":"מרגליות, אליעזר ליפמן","b":"גבאי ישיבת מייליס בוילנא. חתם על כתב התמנות ר ישראל סלנטר לראש הישיבה, על מקום ר מרדכי מלצר."},{"i":31505,"n":"מרגליות, אליעזר ליפמן מוילנא","f":"יוסף","k":"ליפעלע יאסיל-נח'ס","bp":"פאריטש","dt":"תרך - ח אלול","dp":"וילנא","b":"חתן קרובו הגביר ר יוסף יצחק בן נח מרגליות מוילנא. גביר מחכמי וילנא, גבאי ישיבת מייליס. בנו ר נחמן אידל אב\"ד יקאבשטאדט."},{"i":31506,"n":"מרגליות, אליעזר מאוסטרהא","f":"חיים מרדכי מדובנא","b":"רב באוסטרהא. נכדו ר אפרים זלמן פלק-ליפסון על מקומו אחריו."},{"i":31507,"n":"מרגליות, אליעזר מהאלוסק","f":"יוסף מהלוסק וסלוצק","k":"בעל בהר יראה","b":"חתן הגביר ר יצחק מיכל פלייא-בן ר יהושע השל מטארלי. אב\"ד האלוסק(=הלוסק) על מקום אביו. הסכים על \"מראות הצובאות\", ו\"אגודת אזוב\" לבנו וסייע לו בהדפסת ספרו. בניו: ר משה זאב מרגליות בעל \"מראות הצובאות\"-מהרמ\"ז, ר נח מוילנא, הגביר ר אליהו, ר שלמה זלמן מרגלין מפאריץ."},{"i":31508,"n":"מרגליות, אליעזר ממינסק","f":"משה זאב ממינסק","b":"רב בגליל מינסק, מאהליב(=מוהילוב)-תעד-תפג. בנו - ר עקיבא מבוריסוב בעל \"ביזת מצרים\"."},{"i":31509,"n":"מרגליות, אליעזר מסטרי","dt":"תרעא","dp":"ירושלים","b":"חסיד קומרנא. רב בסטרי. נכד ר יצחק דב בר מרגליות מיזלוביץ. חותנו של ר מנחם ברגר הרב בדברצין (בזמן הפירוד)."},{"i":31510,"n":"מרגליות, אליעזר מפרמישלא","f":"מנחם מנדל מפרמישלא","b":"רב בלומבלא,פרמיסלא-ת\"מ"},{"i":31511,"n":"מרגליות, אליקים גצל","f":"מנחם מניש מויטקוב","b":"הדפיס עם אחיו ר אפרים זלמן את שו\"ת הב\"ח החדשות. חתן א מרדכי כץ לופטינר מברודי."},{"i":31512,"n":"מרגליות, אלכסנדר אשר","dt":"תשד","b":"מרבני מונקאטש"},{"i":31513,"n":"מרגליות, אלכסנדר אשר מברוד","f":"אריה ליב מקראקא","bt":"תרי","dt":"תרעה","b":"גברי מחכמי ברודי - גידל בביתו ילדים שברחו מגיוס לצבא ברוסיה, וכשבגרו קראו לעצמם בשמו - מרגליות. חתן ר דב בריש פופרש מברודי."},{"i":31514,"n":"מרגליות, אלכסנדר יהודה","f":"נפתלי הירץ מרגליות","k":"בעל דרך אניה","dt":"תרא - טז אדר","b":"רב בגומבין. חתנו ר אהרן מקויל."},{"i":31515,"n":"מרגליות, אלכסנדר סנדר","f":"מנחם מניש מויטקוב","b":"מופיע בספר אחיו \"בית אפרים\".","bk":[["תשובות הרא\"ם","שו\"ת בענינ אבה\"ע"],["הרא\"ם","שו\"ת"]]},{"i":31516,"n":"מרגליות, אלכסנדר סנדר מסטנוב","f":"מרדכי מברודי","k":"בעל תשובות הראם","bt":"תצ","dt":"תקסב - כט טבת","b":"הרביץ תורה בתלמידים וזכה לשבחים מהנודע ביהודה ומהפרי מגדים. חתן ר צבי הירש מזברז. רב בדוברמיל, זברז(=זאברוב) על מקום חותנו-תקלד, סטנוב-תקם, פשוורסק. מתנגד לחסידות ומקורב לגדולי דורו. חיבר \"תשובות הרא\"ם\" וארשא תריט, ועוד. מתלמידיו - ר זלמן מרגליות שהיה גם אחיינו."},{"i":31517,"n":"מרגליות, אלעזר","f":"אלחנן","b":"מחכמי ירושלים, חתם על כתב רבנות ר דוד אופנהיים בשנת תסז"},{"i":31518,"n":"מרגליות, אפרים זלמן מברזן","b":"נכדו של ר אפרים זלמן מרגליות. מחכמי ברזן שעסק במסחר."},{"i":31519,"n":"מרגליות, אפרים זלמן מלובלין","f":"יוסף מאוסטרובצא","bt":"תצא","dt":"תקעג - ג אד\"ב","dp":"לובלין","b":"בנו של בעל \"תבנית אות יוסף\". גביר עשיר ודיין בלובלין. ולפי המסורת הוא שהביא את ה\"חוזה\" ללובלין. חתם על תקנות בפנקס ביהכ\"נ של ר צבי הירש בר משה דאקטאר, וחתם על חרם ר שאול מרגליות שלא לייסד מנינים חדשים בלובלין."},{"i":31520,"n":"מרגליות, אפרים זלמן מלנקא","f":"אלכסנדר אשר מברודי","bt":"תרכה","bp":"ברודי","dt":"תרפב","b":"נכד ר חיים מרדכי מרגליות בעל \"שערי תשובה\" - אחיו של ר אפרים זלמן מברודי. חתן ר ישראל ליב פרנקל (חתנו של האדמור מפרימישלן). רב בלנקא-תרן, עבר לדרוהוביטש. מחסידי בלז. מחותן עם ר נפתלי הרץ תאומים מוילקאטש."},{"i":31521,"n":"מרגליות, אפרים זלמן ממאציוב","f":"מנחם מאניש ממאציוב","k":"אדמור מטריסק במציוב","dt":"תרמו - יב אב","b":"חתן המגיד ר אברהם מטריסק. רב בהארחוב, מציוב על מקום אביו, וכיהן כאדמור מטריסק במציוב. חתניו - ר שלום יוסף מהוסיאטין, ר יצחק מאיר מזינקוב."},{"i":31522,"n":"מרגליות, אפרים פישל","b":"תשובה אליו ב\"שואל ומשיב\"."},{"i":31523,"n":"מרגליות, אשר זליג משברשין","f":"אהרן פרלא או יהודה ל","b":"רב בשברשין-תקסב על מקום אביו, פרוזנא. מחדושיו בספרי אביו \"טל אורות\" ועוד."},{"i":31524,"n":"מרגליות, אשר מהורדנא","f":"מרדכי","bt":"תקא-ג","dt":"תקפב - כא סיון","dp":"הורדנא","b":"דיין בהורדנא, הסכים-תקסו עם ביה\"ד בהורדנא על שו\"ע הגר\"א. נזכר ב'ברכת משה' לר משה מזלאטווי."},{"i":31525,"n":"מרגליות, אשר ממזבוז","f":"שלמה זלמן מברודי","b":"מחכמי מזיבוז. הוציא לאור \"סדר תפלה מכל השנה\" למברג תקמח."},{"i":31526,"n":"מרגליות, בן ציון מסקלט","b":"רב בסקלט."},{"i":31527,"n":"מרגליות, בן ציון מסקלט-הנכד","f":"מרדכי מסקלט","b":"נכד ר בן ציון מסקלט."},{"i":31528,"n":"מרגליות, בנימין אליעזר מקאלין","b":"רב בקאלין-הונגריה. פרסם מאמרים ב\"אסיפת חכמים\" - אטיניא תרע."},{"i":31529,"n":"מרגליות, בצלאל מזוויהל ואוסטרה","f":"מאיר","r":"אב\"ד אוסטראה","dt":"תקפא - יג אדר","dp":"אוסטרהא","b":"אחיו של ר שאול מלובלין. תלמיד ר משולם זוסיא מאניפולי (ור זושא התאכסן אצלו בביקוריו באוסטרהא), ור ברוך ממזבוז. חתן ר יהושע מדרוהוביטש (ובאוצר הרבנים - חתן ר חיים רפפורט). רב בזוויהל, אוסטרהא-תקן על מקום אביו. בנו ר שלמה יחזקאל אב\"ד הרלוי-רומניה, ר נחמן-חתנו של ר חיים הכהן רפפורט. (באלפסי תאריך הפטירה-תקצא). הסכים על ספרים רבים ובהם \"איתן האזרחי\" - תקנו ועוד. הסכים על \"אור פני משה\"-תקסט, \"ערכי הכנוים\", ועוד.","bk":[["כתר שבת",""]]},{"i":31530,"n":"מרגליות, ברוך בנדט מחסלביץ","f":"שמחה בונם מפוחביץ","b":"מו\"צ בחסלאביץ(=חסלביץ). חתנו - ר משה יצחק אביגדור בעל \"פרדס רמונים\" משקלוב וקובנא. אחיו - ר צבי שמחוביץ ממינסק."},{"i":31531,"n":"מרגליות, גבריאל זאב מהורדנא","f":"יחיאל יצחק","k":"בעל תורת גבריאל","r":"רב בבוסטון, ארה\"ב","bt":"תרח","bp":"וילנא","dt":"תרצה - י אלול","dp":"ניו יורק","b":"תלמיד ר יקב באריט מוילנא, חתן ר נחום שמש קפלן מהורדנא. רב בדוברוונא-תרלו, יאשינובקא-תרלח. רב בהורדנא על מקום חותנו-תרם. חתם על תקנות והסכמות, חיבר מכתב ב\"תל תלפיות\"-תרסה כנגד הציונות והמזרחי, מתורתו ב\"קהילת יצחק\". רב בבוסטון-תרסח, ניו יורק-תרעב. חיבר גם \"שם עולם\", \"תורת גבריאל\", \"גנזי מרגליות\" נ\"י תרפא, \"חרוזי מרגליות\" ירושלים תרעב ועוד. מתורתו ב\"פרח לבנון\" - תרעח, \"המגיד\" - סטמר תרפח, \"פרח הלבנון\" - וארשא תרעח.","bk":[["אגודת אזוב",""]],"e":"תר\"ח-תרצ\"ה","rb":"בוסטון, ארה\"ב"},{"i":31532,"n":"מרגליות, ג'ורג'","bt":"1853","bp":"וילקוביסק","dt":"1924","dp":"ניו ברייטן-אנגליה","b":"חוקר התנ\"ך והמזרח. ממונה על כתבי היד העבריים והסוריים במוזיאון הבריטי-1891. ערך רשימת כתבי היד העבריים במוזיאן. השתתף בכתבי עת מדעיים שונים ובהם ג'ואיש קוורטלי רוויו. התנצר."},{"i":31533,"n":"מרגליות, גרשון מסקלט וזיטומיר","f":"בן ציון מסקלט","bt":"תקל","dt":"תקצח - א תמוז","dp":"צפת","b":"ממקורבי ר לוי יצחק מברדיטשוב. רב בסקלט על מקום אביו, זיטומיר. חתן ר ישכר בער מגזע צבי מזלוטשוב בעל \"מבשר צדק\", עלה לצפת-תקעא והיה מראשי עדת החסידים וראש כולל החסידים בצפת. בשנת תקפט חתם על הסכמים בין הפרושים והחסידים, היה נציג פקידים ואמרכלים של כולל אמשטרדם. הוציא לאור ספר חותנו עם הקדמה ממנו - \"מבשר צדק\" דובנא תקנח, הו\"ל תהלים עם ביאור הזהר צפת תקצג."},{"i":31534,"n":"מרגליות, דוד (דב) שלמה מקראקא","k":"בעל חדושי מהרשדם","dt":"תרנ - כא ניסן","b":"מגדולי חכמי קרקא, רב בקלוואריע(=קלוואריה)-תרמ."},{"i":31535,"n":"מרגליות, ח' בנימין וולף מסערד","dt":"תקצב - ג תשרי","b":"רב בסרד"},{"i":31536,"n":"מרגליות, חיים","k":"בעל לקורות היהודים ב","b":"חיבר לקורות היהודים בעיר דובנא."},{"i":31537,"n":"מרגליות, חיים זאב","f":"יעקב","k":"בעל זכרונות מימים עב","bt":"1842","bp":"וילנא","b":"תלמיד דודו ר יעקב בארי\"ט. נדד בגרמניה אוסטריה והונגריה. תלמיד ביהמ\"ד לרבנים בזיטומיר. רב מטעם בדובנא. פרסם מאמרים ב\"המליץ\", ועוד. חיבר גם \"דובנא רבתי\" - לתולדות העיר דובנא, ועוד."},{"i":31538,"n":"מרגליות, חיים יהודה ליבש מוינה","f":"אפרים זלמן מברודי","bt":"תקס","dt":"תקצז","b":"חתן ר מרדכי ביק. עבר לוינה."},{"i":31539,"n":"מרגליות, חיים מאוסטרהא","b":"רב באוסטרא-תק\"צ"},{"i":31540,"n":"מרגליות, חיים מלבוב","f":"אליקים גץ אשכנזי","b":"רב בלבוב-תק\"מ"},{"i":31541,"n":"מרגליות, חיים מרדכי מביסהאר","f":"חיים מרדכי מדובנא","b":"רב בביסהאר-דיבאר. חתן ר מנחם נחום טברסקי האדמור ממקרוב."},{"i":31542,"n":"מרגליות, חיים מרדכי מדוביסאר","f":"מנחם מניש ממציוב","k":"אדמור מדוביסאר","b":"חתן האדמור ר מנחם נחום טברסקי ממקרוב. אדמור בדוביסאר. מכתב ממנו אל ר יצחק מנסכיז ב\"זכרון טוב\"."},{"i":31543,"n":"מרגליות, חיים מרדכי מדובנא","f":"מנחם מניש מויטקוב","bt":"תקל","dt":"תקפ - טז שבט","b":"אחיו של ר אפרים זלמן מברודי. חתן אחיו ר אליקים גצל מברודי. מחכמי ברודי, רב ברסטיצקה(ברסטיצקי)-תקס, דובנא-תקע על מקום ר חיים יעקב אשכנזי-הלברשטט, והקים שם דפוס. הדפיס ספר \"שערי אפרים\" לאחיו דובנא תקף - ושילב מתורתו בתוך ספר אחיו. הוציא \"שערי תשובה\" דובנא (לקוטים מאחרונים). הסכים על \"מחצית השקל\"-פאריצק תקעט. היה אחד משלושה נבחרים במשלחת לפטרבורג-תקעח.","bk":[["שערי תשובה","מפרשי שו\"ע"],["שערי תשובה [שו\"ע או\"ח]",""]]},{"i":31544,"n":"מרגליות, חיים שמחוביץ ממינסק","f":"צבי הירש ממינסק","b":"גביר במינסק. דודו - ר משה זאב מביאליסטוק בעל \"מראות הצובאות\"."},{"i":31545,"n":"מרגליות, ידידיה","f":"יוסף","k":"בעל ערצעהלונגען","bt":"1884","bp":"פוסטיקי-פלך גרודנא","b":"ביקר באמריקה-1915, וחזר לרוסיה. חיבר גם \"פון היינטיגער צייט\", כתב מסה על הסוציאליזם בספרות אידיש. פרסם בעתונות היהודית ברוסיה."},{"i":31546,"n":"מרגליות, יהודה אריה ליב מבוזנו","f":"אשר זליג מזברז","k":"בעל פרי תבואה","r":"רב בכמה קהילות ובסוף ימיו אב\"ד פרנקפורט","bt":"תקז","bp":"[זבורוב]","dt":"תקעא - כב סיון","b":"חתן הגביר ר מאיר מטרניגרד. רב בסוכסטוב, קופיטשיניץ, בוזנוב(=יאזנוב?), חאטין, פלאצק, שברשין-תקם, לעסלא, פפד\"א-תקסד. פגש את הגר\"א בוילנא (ונזכר ב\"עליות אליהו\"). התנגד למנדלסון. חיבר \"קרבן ראשית\", \"טוב ויפה\" פפדא תקל, ועוד. חיבר \"טוב ויפה\" ו\"בית מדות\". מונרו תשס. בנו ר אשר זליג פרילש (מרגליות) על מקומו אחריו בשברשין - הדפיס את ספרי אביו והגיהם, בנו גם ר משה. חתנו - ר נתן בן ר יצחק פלוצקר מפלוצק.","bk":[["אגרת המליצה ומשפט לשון הקודש",""],["אור עולם - סוד יכין ובועז הדרך הטוב והישר כתנות אור",""],["בית מידות",""],["טוב ויפה - מפתח לכמה חכמות ומליצות",""],["טל אורות - דרושים ומליצות נכבדות",""],["עצי עדן",""],["פרי תבואה - שו\"ת",""],["קרבן ראשית - שו\"ת וחידושי הלכה על מס' ראש השנה",""]]},{"i":31547,"n":"מרגליות, יהודה אריה מזמיגרוד","f":"אלכסנדר סנדר מסטנוב","b":"רב בזמיגרוד."},{"i":31548,"n":"מרגליות, יהודה יידל מאושאץ","f":"נתן נטע מרגליות","b":"רב באושאץ"},{"i":31549,"n":"מרגליות, יהודה ליב מטלז","f":"אברהם מטלז","b":"חתן ר זאב וולף אלטשולר מלוצין בעל \"זבד טוב\". רב בטלז על מקום אביו או זקנו. חתנו - ר מיכאל יעקב זליגמן מגריווא."},{"i":31550,"n":"מרגליות, יהודה ליב מפרימישלן","f":"שמואל כץ","dt":"תכד - ח אייר","dp":"לבוב","b":"רב בפרימישלן, לבוב. נהרג עק\"ה."},{"i":31551,"n":"מרגליות, יהודה ליב מקוזניץ","dt":"תקו - טו חשון","b":"רב בקוזניץ"},{"i":31552,"n":"מרגליות, יהודה צבי מזבורוב","b":"רב בזבורוב - תשובה ממנו לר משולם איגרא ב\"והמה בכתובים\"."},{"i":31553,"n":"מרגליות, יהושע השל מוורונובה","b":"מחכמי וורונובה-תרכז."},{"i":31554,"n":"מרגליות, יהושע השל מוישנובה","f":"אליהו","k":"בעל קול התור","bt":"תרד","dt":"תרצח","dp":"רחובות","b":"רב בוישנובה, חיבר \"קול התור\" וילנא תרמח. עלה בתרנד וכיהן כרב ברחובות. פרסם מאמרים ב\"כנסת חכמי ישראל\" - אודסה-פיעטרקוב-ברדיטשוב תרנג-תרס."},{"i":31555,"n":"מרגליות, יואל פיבוש","f":"מנחם מנדל מפרמישלא","b":"חתן ר אברהם סלניק מטרנופול ובריסק. רב-שנת ת\"מ"},{"i":31556,"n":"מרגליות, יוסף","f":"מרדכי משה מרגליות","b":"רב-שנת שצ\"ה"},{"i":31557,"n":"מרגליות, יוסף יאסקי מזברז","b":"רב בזברז, צורטקוב-תקסו."},{"i":31558,"n":"מרגליות, יוסף מאיר מארה\"ב","b":"פרסם מאמרים ב\"כרם ציון\" - ירושלים תרצה-תשיג, תשכג - קובץ \"מדרש בני ציון\"."},{"i":31559,"n":"מרגליות, יוסף מזולקוא","f":"משה מרגליות","b":"רב בזלקווא-תק\"פ"},{"i":31560,"n":"מרגליות, יוסף מזמיגרוד","f":"אלכסנדר סנדר מסטנוב","b":"רב בזמיגרוד על מקום אחיו ר יהודה אריה. חתן הנגיד ר יהושע מדרוהוביטש."},{"i":31561,"n":"מרגליות, יוסף מסלוצק והאלוסק","f":"מנחם מנדל ממינסק","dt":"תקלט - יח סיון","b":"אב\"ד סלוצק, הלוסק(=האלוסק) על מקום אביו, ובנו ר אליעזר על מקומו אחריו. הסכים על \"ערכי הכנויים\"-תקכט, \"תפארת ישראל זוטא\" - תקלד. אחיו של ר שמחה אב\"ד פוחאויץ - ראש משפחת שמחהויץ במינסק. קרובו של משה יצחק אביגדור אב\"ד שקלוב המזכירו בספרו \"פרדס רמונים\". בנו גם - ר יהודה אידיל ונכדו ר יוסף מפאריץ."},{"i":31562,"n":"מרגליות, יוסף מפאריטש","f":"יהודה אידיל בן יוסף","b":"נכד ר יוסף מסלוצק והאלוסק. רב בפאריטש(=פאריץ)-תקפ."},{"i":31563,"n":"מרגליות, יוסף נחמן מפולנאה","f":"מאיר","k":"הו\"ל מאיר נתיבים","b":"רב בפולנאה. הו\"ל את ספרי אביו \"מאיר נתיבים\" ו\"דרך הטוב והישר\" עם פירוש ממנו. בנו ר חיים מאוסטרהא. (לפי אוצר הרבנים היה רב באוסטרהא-תפ)"},{"i":31564,"n":"מרגליות, יחזקאל מאוסטרובצא","f":"אביגדור מרגליות","b":"רב באסטרווצי(=אוסטרובצא), גריידיג. חתנו - ר שמחה מאוסטרובצא-נכד הפני יהושע ואביו של ר נתן יחזקאל מקוזניץ."},{"i":31565,"n":"מרגליות, יחיאל מיכל מהורדנא","f":"שמואל שמלקא מליסקא","k":"בעל הר אדני","dt":"תקיב - כא תשרי","b":"נכד ר יחיאל מנמירוב הי\"ד. תלמיד הבעשט. רב בקאוולע, הורדנא-תקו על מקום ר זכריה מנדל בן אריה ליב, והבעשט ליווהו לשם בעצמו, ור משה יהושע הורביץ על מקומו אחריו. הו\"ל זוהר למגילת רות בשם \"הר אדני\". מתשובותיו ב\"גבעת שאול\", ו\"תשובת שמואל\". חתנו ר ישכר בעריש בן ר דוד הלפרין מאוסטרהא. אחיו: ר אלעזר רוקח מאמשטרדם, ור אהרן מרגליות-חותנו של ה\"נועם אלימלך\"."},{"i":31566,"n":"מרגליות, יחיאל מיכל מלשקוביץ","f":"משה אברהם מהורודנקא","b":"רב בלשקוביץ. חתנו היה ר דוד שלמה אייבשיץ בעל \"לבושי שרד\"."},{"i":31567,"n":"מרגליות, יעקב אריה מאזיפולי","b":"חתן ר יוסף לינדנר. היגר לארגנטינה-תרצג וכיהן כרב."},{"i":31568,"n":"מרגליות, יעקב מאיזנשטט","b":"רב באיזנשטט-רפו, ור שלמה ליברמן על מקומו אחריו."},{"i":31569,"n":"מרגליות, יעקב מברדיטשוב","f":"משלם נתן מברדיטשוב","k":"בעל קבוצת יעקב","b":"רב בברדיטשוב על מקום אביו. חתן ר מנחם דב בר בן האדמור האמצעי. חיבר \"קבוצת יעקב\"."},{"i":31570,"n":"מרגליות, יעקב מברוד","f":"מנחם מניש מויטקוב","b":"מחכמי ברודי."},{"i":31571,"n":"מרגליות, יעקב מבריולוב","b":"רב בבריולוב(=בריילוב, ברילוב)-רומניה-תרן."},{"i":31572,"n":"מרגליות, יעקב מטלוסט","f":"יצחק דב מיזלוביץ","b":"רב בטויסט (=טלוסט). בנו ר אברהם מרדכי רבה של איסטיטשקי."},{"i":31573,"n":"מרגליות, יעקב מלוקא","f":"משה מרגליות","k":"בעל סדר גיטין וחליצה","b":"מגדולי חכמי אשכנז,רב בלוקא,ווארמס-ק\"צ"},{"i":31574,"n":"מרגליות, יעקב מנירנברג","k":"יעקב מרגליות הראשון","dt":"רנב","b":"רב בנירנברג, פרג עם ר יעקב פולק. מקורב למלכות. נזכר ב\"יוסף אומץ\". התכתב עם רויכלין שבקש ממנו ספרים בקבלה."},{"i":31575,"n":"מרגליות, יעקב מרגנשבורג","k":"ר' יעקב מרגליות השני","dt":"רעט","b":"מגדולי חכמי דורו,רב ברגנסבורג"},{"i":31576,"n":"מרגליות, יעקב קופל מדוינסק","k":"בעל אבל משה","b":"ר\"מ ומ\"מ בדוינסק-תרן. חיבר \"אבל משה\" - הספד על מונטיפיורי - וארשא תרמו."},{"i":31577,"n":"מרגליות, יעקב קופל מונציה","f":"צבי","k":"בעל קול יעקב","b":"ברח מפולין בגזירות תח-תט והגיע לונציה ושם חיבר \"קול יעקב\", ו\"מזבח יעקב\" ו\"מראות יעקב\" ונציא תכב."},{"i":31578,"n":"מרגליות, יעקב שמשון מצפת","bt":"תרנז","dt":"תשמא","dp":"צפת","b":"מחכמי צפת."},{"i":31579,"n":"מרגליות, יצחק איזיק מפרג","f":"יעקב מנירנברג","k":"בעל סדר גיטין","dt":"רפה - כד אד\"ב","b":"מגדולי הפוסקים בדורו,ר\"מ בפרג,רבה של פרג-משנת רנ\"ב"},{"i":31580,"n":"מרגליות, יצחק דב מיזלוביץ","f":"צבי הירש מיזלוביץ","k":"בעל באר יצחק","b":"תלמיד הבעש\"ט - והיה מתלמידיו עוד כשהיה נסתר. רב ביזלוביץ על מקום אביו. חתן ר יעקב מפוזנא. העיד על הבעשט שהוא \"חכם מכל החכמים\". תשובותיו בספר אחיו-ר מאיר מהורודנקא \"מאיר נתיבים\". חיבר \"באר יצחק\". היה אחד מהשלושה שנבחרו לעמוד לויכוח עם הפרנקיסטים-תקיט - יחד עם ר חיים הכהן רפפורט והבעש\"ט. בעל הט\"ז היה דודו זקנו, ר אריה ליב בן מרדכי אוירבך מסטניסלב היה אחי אמו. בנו - ר שמואל מזלישטשיק ולבוב. (לדעת ר יוסף לוינשטין"},{"i":31581,"n":"מרגליות, יצחק יואל מירושלים","b":"גבאי כולל ווהלין-ירושלים-תרפד."},{"i":31582,"n":"מרגליות, יצחק מברוד","f":"חיים","b":"מחכמי ברודי."},{"i":31583,"n":"מרגליות, יצחק מוילנא","f":"יהודה ליב","b":"רב בוילנא, חתם-תסח עם ר אליהו בן משה קרמר."},{"i":31584,"n":"מרגליות, יצחק מיברוב","f":"אלעזר","b":"חתן ר מאניש חיות. גביר מחכמי יאברוב. בניו - ר מנחם מאניש-חתן ר אלכסנדר שור בעל \"שמלה חדשה\", ר אריה ליבש מבוטשאש."},{"i":31585,"n":"מרגליות, יצחק מליטא ונ\"י","f":"אליהו מראדין","k":"בעל מעוז התלמוד","bt":"תרב","bp":"קלוואריה-ליטא","dt":"תרמז","dp":"ניו יורק","b":"תלמיד ישיבות ליטא. השתקע במאראטש ועסק במסחר, עבר לקובנא. רב בדרוסקניק(=דרוזנעניק). היגר לארה\"ב וכיהן כרב בקהילת קאלוואריה בניו יורק. חיבר \"מעוז התלמוד וכנגדו יצא לילנבלום ב\"המגלה\", ר יצחק ענה לו ב\"מעוז הים\". פרסם מאמרים בכתבי עת."},{"i":31586,"n":"מרגליות, יצחק מפודקמין","k":"בעל שירי זמרה","b":"מחכמי פודקמין - בדחן ומשורר עממי נודד. חיבר \"שירי זמרה\" פרשבורג תרך."},{"i":31587,"n":"מרגליות, יצחק מצרניחוב","f":"משה זאב ממינסק","b":"רב בטשערניחוב-ת\"צ"},{"i":31588,"n":"מרגליות, יצחק שמואל מטרנופול","dt":"תשג","b":"רב בטרנופול"},{"i":31589,"n":"מרגליות, יקותיאל זלמן מאניפולי","f":"משלם נתן מברדיטשוב","bt":"תקצא","b":"רב באניפולי, בנו ר מנחם משולם על מקומו אחריו."},{"i":31590,"n":"מרגליות, ישעיה אשר זליג מירושל","f":"יעקב צבי","k":"בעל עמודי ארזים","bt":"תרנד","dt":"תשכט - כז ניסן","b":"עלה לירושלים-תרסו. מקובל, מגדולי חכמי ירושלים, תלמיד הרב מברנוב. חיבר ספרים במירון.","bk":[["קומי רוני",""],["מידות רשב\"י",""]],"e":"תרנ\"ד-תשכ\"ט"},{"i":31591,"n":"מרגליות, ישראל","f":"מנחם מנדל מפרמישלא","b":"חתן ר אברהם ר יוספש-ראש מדינה בטיסמניץ. מגדולי חכמי דורו-תמ."},{"i":31592,"n":"מרגליות, ישראל אריה מפרימישלן","f":"אפרים זלמן מלנקא","k":"אדמור מפרימישלן","bt":"תרנב","bp":"פרימישלן","dt":"תשטו - כד טבת","dp":"לונדון","b":"ממשפחת אדמורי פרמישלן. נכד ר ישראל אריה ליב פ\"ת מפרמישלן. חתן ר יצחק באבד מטארטיקוב. ברח לבודפשט במלחמת העולם הראשונה והיה שם אדמור מפרימישלן, אדמור בלמברג-תרעז, רב ואדמור מפרימישלן בלונדון-תרפז. חיבר \"בך יברך ישראל\", \"בית ישראל\" - לא נדפס."},{"i":31593,"n":"מרגליות, מאיר חריף"},{"i":31594,"n":"מרגליות, מאיר מברדיטשוב","f":"יעקב","bt":"תריז","b":"תלמיד מהרש\"ם מברעזן. מו\"צ בברדיטשוב-תרן. הניח חיבור על הש\"ס."},{"i":31595,"n":"מרגליות, מאיר מהורדנקא לבוב","f":"צבי הירש מיזלוביץ","k":"בעל מאיר נתיבים","bt":"תס-תסז","dt":"תקן - י אייר","dp":"אוסטרהא","b":"נכד(-אבי אמו) ר יצחק זאלקוויר. מתלמידי הבעש\"ט. חתן ר חיים מהורודנקא-אחיו של ר משה מקיטוב וגיסו של ר נחמן מהורודנקא, ובזיוו\"ש חתן דודו ורבו ר אריה ליב אוירבך מסטניסלב. פגש בילדותו את הבעשט כשהיה שו\"ב בכפר קשילוויץ. רב בהורודנקא-תקב, יזלוביץ על מקום אביו. רב בגליל למברג-תקיד (עד לביטול ועד ארבע ארצות ובעקבותיו משרת רב הגליל), קומרנא-תקכד, ברסלב, אוסטרהא-תקלז על מקום ר אברהם משולם זלמן אשכנזי., ובזמנו כיהן רב ייבי כמגיד באוסטרהא. (בנו ר שאול הצביע על הדוכס סטניסלב אוגוסט פוניאטובסקי ואמר כי רואה בו גינוני מלכות הדוכס ואביו רשמו את הדבר ולימים כשהפך למלך פולין - העניק לו כתב רבנות על גליל אוקראינה). חיבר \"אור עולם - מאיר נתיבים\" פולנאה תקנא, ועוד. היו לו 10 בנים, מבניו: ר מרדכי מרומלוב, ר שאול מזבריזא, ר יוסף נחמן מפולנאה, ר בצלאל מאוסטרהא, ר נפתלי מרדכי מהימלוב, ר שלמה בער. חתניו: ר נפתלי הרץ הכהן משאריגרד, ר שמחה בן נחמן כץ. חיבר \"אור עולם\" ובו חמשה ספרים \"מאיר נתיבים\", \"סוד יכין ובועז\", \"הדרך הטוב והישר\" ,\"כתנות אור\".","bk":[["מאיר נתיבים (אור עולם) [שו\"ת]",""]]},{"i":31596,"n":"מרגליות, מאיר מלומז'ה","f":"צבי הירש","b":"מחכמי לומז'ה - אחרי תקעח."},{"i":31597,"n":"מרגליות, מאיר קופל ממיטאוי","b":"העתיק את פנקס החברא קדישא במיטאוי-תקצו."},{"i":31598,"n":"מרגליות, מכס ליאופולד","bt":"1866","bp":"מאראטש","dt":"1932","b":"אביו היה רב במאראטש. תלמיד אוניב' ברלין וקולומביה. פרופסור לשפות שמיות בקולומביה ובהיברו יוניון קולג' בסינסינטי, בקליפורניה, דרופסי קולג'. תרגם את התנ\"ך לאנגלית. עורך כתב העת של הספרות התנ\"כית. חיבר ספרים באנגלית בנושאי שפות ויהדות."},{"i":31599,"n":"מרגליות, מנדל הייקריל מלובלין","f":"נחמן ממזריטש","b":"נכד ר מנחם מנדל מרגליות. מחכמי לובלין-תס."},{"i":31600,"n":"מרגליות, מנחם מנדל","b":"מצאצאי ר יוסף קרא. חתן ר יעקב אליהו-בנו של ר משה משאראגרד. חתנו - ר משה בן בעל הש\"ך."},{"i":31601,"n":"מרגליות, מנחם מנדל מאטיניא","bt":"תרלח","bp":"קאלין","b":"חתן ר שמואל זנויל כהנא מדרגמרושט-חתנו של ר יהודה מודרן בעל \"זכרון שמואל\". רב באטיניא-תרע. פרסם מאמרים ב\"אסיפת חכמים\" - אטיניא תרע. נסמך מאת: ר יהודה גרינולד מסאלמאר, ר אליעזר דייטש בעל \"תבואות השדה\", מהרשד\"ם מברעזן, ר אריה ליב הורביץ בעל \"הרי בשמים\", ר אברהם בנימין קלוגר מברוד, ר שמואל נתנזון מפודקמין."},{"i":31602,"n":"מרגליות, מנחם מנדל מהרינטש","f":"[ישראל]","bt":"תרלה","bp":"קאלין-מרמרוש","dt":"תשד","b":"אחיו של ר בנימין אליעזר. תלמיד ר אליעזר דייטש בבניהאד, ור יהודה גרינוולד בסטמר ובעל \"קדושת יו\"ט בסיגט\". חתן ר שמואל זאנויל כהנא מדראגמירשט. גביר ורב - לא רשמי - בכפר גלוד-מארמרוש, רב באטיניא-תרסח אצל האדמור ר חיים הגר מאטיניא, טיסמניץ-תרעג, קאלין, רב בכפר הארינטש-ליד חוסט-מארמרוש. הוזמן לרבנות בארה\"ב וסירב. נספה בשואה, וחיבוריו אבדו בשואה."},{"i":31603,"n":"מרגליות, מנחם מנדל מוילנא","f":"שמואל מפוזנן","b":"מחכמי וילנא-שפ, נזכר בשו\"ת הב\"ח החדשות. אחיו - ר אברהם מזולקווא, ר משה מרדכי בעל \"חסדי ה'\", ר צבי הירש מלודמיר."},{"i":31604,"n":"מרגליות, מנחם מנדל ממינסק","f":"משה זאב ממינסק","dt":"תקה - כט סיון","b":"נכד ר אליעזר מרגליות מלובמלא. חתן הקדוש ר שמחה בונם בן משה בן נתן שפירא מקראקא בעל \"מגלה עמוקות\". רב בפלך מינסק על מקום אביו (בזמן כהונת בעל \"סדר הדורות\" כרב בעיר מינסק) ור אשר בן ליב בעל התוספות על מקומו אחריו, האלוסק, ובנו ר יוסף על מקומו אחריו. הסכים על \"מרי צבי\"-תצז."},{"i":31605,"n":"מרגליות, מנחם מנדל מקרוטושין","f":"משה מטרניגרד","b":"מצאצאי ר יעקב מרגליות בעל \"סדר גטין וחליצה\". חתן ר יואל הלפרין מאוסטרהא-(נפטר תעד). רב בקרוטושין. בנו ר אביגדור מחנטשין."},{"i":31606,"n":"מרגליות, מנחם מניש","f":"יצחק מיאברוב","b":"נכד ר מאניש חיות. חתן ר אלכסנדר סנדר שור בעל \"שמלה חדשה\"."},{"i":31607,"n":"מרגליות, מנחם מניש","f":"אלכסנדר מרגליות","b":"רב-שנת תק\"ס"},{"i":31608,"n":"מרגליות, מנחם מניש מברוד","dt":"תשג","b":"רב בקרסני-ברוד. פרסם מאמרים ב\"עטרת תפארת\" - פודוולוטשיסק-בילגוריי תרצא."},{"i":31609,"n":"מרגליות, מנחם מניש מויטקוב","f":"מרדכי חסיד מברודי","bt":"תק","dt":"תקסא","b":"תלמיד ר יעקב יצחק דוקלא לנדא מפרשבורג. מחכמי ברודי, רב בויטקוב-תקמא, דינוביץ, לכוביץ, גרידינג. חתן ר אהרן רבינוביץ מלברטוב. בנו - ר אפרים זלמן מברוד."},{"i":31610,"n":"מרגליות, מנחם מניש מיאנוב","f":"משה לוי","bt":"תרמא","dt":"תש","b":"רב ביאנוב-תרע."},{"i":31611,"n":"מרגליות, מנחם מניש ממציוב","f":"חיים מרדכי מדובנא","b":"חתן ר יעקב אריה שפירא מקאוולי. רב במאציוב-תר, פוריצק והורכוב. בנו ר אפרים זלמן על מקומו אחריו במאציוב והורכוב."},{"i":31612,"n":"מרגליות, מנחם נחום מסוכסטוב","b":"רב בסוכוסטוב. דור שישי ל\"מאיר נתיבים\"."},{"i":31613,"n":"מרגליות, מנחם נחום משטפינשט","k":"אדמור משטפינשט","b":"חתן ר מרדכי זוסיא מהוצאלאס. נכד לבית טשרנוביל מצד אביו. אדמור בקלויז שטפינשט ביאס-תרצג אחר פטירת האדמור ר מתתיהו משטפינשט."},{"i":31614,"n":"מרגליות, מנשה מנ\"י","b":"רב בניו יורק. פרסם מאמרים ב\"קבוצי אפרים\" - יאסי-בוקרשט תרעד, \"שערי אורה\" - מיהאלביץ תרץ-תרצד."},{"i":31615,"n":"מרגליות, מרדכי","b":"חתן ר שמואל שיק. בניו - ר שמואל, ר אשר מהורדנא."},{"i":31616,"n":"מרגליות, מרדכי מאילוקסט ודיסנא","f":"אליהו מראדין","k":"בעל סוגה בשושנים","bt":"תרח","dt":"אחרי ה'תרנד","b":"רב באליקסט(=אילוקשט)-פלך קורלנד-תרלב (או תרלה) על מקום ר בנימין פוטרמן ור אברהם שלוסברג על מקומו אחריו, דיסנא-פלך וילנא-תרמב. חיבר גם \"ליקוטי שושנים\", ועוד. נסמך מאת: ר יצחק אלחנן מקובנא, ר יהושע זליג הכהן מדוינסק, ר ראובן הלוי מדוינסק, ר אריה ליב זיוואוו מדוינסק, ר משה יהודה ליב משקלוב, אדמורי לובאוויץ. בניו: ר יהודה ליב, ר דובער, ר הלל, ר שלמה יעקב, ר מנחם מנדל, ר איזיק.","bk":[["סוגה בשושנים [על שו\"ע נדה]",""]]},{"i":31617,"n":"מרגליות, מרדכי מדיסבאר","f":"מאניש מרגליות","b":"רב בדיסבאר-תרכ\"ב. חתנו ר אליעזר מאוסטילא."},{"i":31618,"n":"מרגליות, מרדכי מדיסנא","f":"מנחם מניש מזולקוא","dp":"דובנא","b":"חברו של הנודע ביהודה ותלמיד חבר לר משה אוסטרר. חתן ר שמואל לופטינר מברודי. נפטר בגיל 22."},{"i":31619,"n":"מרגליות, מרדכי מוינה","b":"רב בווינה-תק\"י"},{"i":31620,"n":"מרגליות, מרדכי מזולקוא","f":"משה","b":"מחכמי זולקוא, חתם-שפו בפנקס הקהלה."},{"i":31621,"n":"מרגליות, מרדכי מסטנוב - א","f":"אלכסנדר סנדר מסטנוב","bt":"תקיח","dt":"תקעח","b":"רב בחיורב, דוברמויל על מקום אביו, אניפולי, אטיק, קוריץ, סטנוב-תקסב על מקום אביו. חתן ר יהושע רישיווער הורשובסקי מדרוהוביטש."},{"i":31622,"n":"מרגליות, מרדכי מסטנוב - ב","f":"מנחם מאניש מרגליות","b":"רב בסטאנוב-תקע\"ה"},{"i":31623,"n":"מרגליות, מרדכי מקראקא","f":"מנחם מנדל מפרמישלא","b":"מגדולי חכמי קרקא-ת\"נ"},{"i":31624,"n":"מרגליות, מרדכי משה מניקלשבורג","b":"הרב הראשון בניקלסבורג-שנת ש'"},{"i":31625,"n":"מרגליות, מרדכי שמחוביץ ממינסק","b":"חתן ר זאב וולף זלדוביץ ממינסק. גביר מחכמי מינסק-תרן."},{"i":31626,"n":"מרגליות, משה אברהם אבוש","f":"צבי הירש מיזלוביץ","k":"בעל צלותא דאברהם","b":"רב בהורדודנקא-תקס, זבנא (או זביא ליד הורודנקא). חיבר \"צילותא דאברהם\" - חידושי מהרמ\"א\" אוסטרהא תקפא."},{"i":31627,"n":"מרגליות, משה בצלאל מירושלים","b":"ר\"מ בישיבת \"חיי עולם\" בירושלים."},{"i":31628,"n":"מרגליות, משה הלוי מקרלסבורג","f":"שמואל","k":"ר משה מוכיח","bp":"פולין","dt":"תקעה-ח -יב תשרי","b":"רב בקרלסבורג על מקום ר בנימין זאב ורצקנד ור יעקב מסעמלין על מקומו אחריו, ורב המדינה בטרנסילבניה-תקלח כ-40 שנה. היה נוהג לעבור ברחבי טרנסילבניה רכוב על סוס ומעוטף טלית ותפלין, ובכל מקום שישבו בו יהודים היה מלמדם הלכות, מפקח על השחיטה ועל מורי ההוראה בכפרים. בסוף תקופת כהונותו-תקעח נפקדו בכל טרנסילבניה 233 משפחות יהודים שהתגוררו בעשרות ישובים וכפרים. (על תאריך פטירתו יש האומרים תקעה או תקעז). נזכר בחת\"ס בדבר סכסוך בקהלה הספרדית.-תקנג, ב\"מקל נועם\", \"מראה יחזקאל\" - שם נזכר ששינה את שם העיר בגיטין מקרלסבורג לקארילסבורג או קאדילסבורג. בנו - ר איציק. מתלמידיו - ר בצלאל רנשבורג."},{"i":31629,"n":"מרגליות, משה זאב וולף - הזקן","f":"יהודה יידל-קול יהודה","b":"חתן ר אליעזר מרגליות מלובמלא - וכינה עצמו מרגליות כשם חותנו. רב ברוזינאי-תנט, פלך מינסק-תסא (בזמן רבנות ר ליב בעל התוספות בעיר מינסק), פיורדא-תעה. מחותן עם בעל \"ראש יוסף\" המביא מחדושיו בספרו. הסכים על \"אהל יעקב\" לר יעקב כהנא שפירא מטיקטין-תעט, \"אור ישראל\" פפד\"א תסב. אחיו של ר יוסף מדובנא בעל \"יסוד יוסף\". בניו נקראו בר\"ת \"אנשים\" והם: ר אליעזר ממינסק ומוהליב, ר נטע אב\"ד רדישוביץ, ר שמואל אב\"ד ארקאוו, ר יצחק אב\"ד טשרניחוב, ר מנחם מנדל אב\"ד הלוסק. (לפי פרומקין - בנו היה ר שמחה בונם מפיחאווטי שהיה זקנו של ר מנחם מנדל משקלוב)."},{"i":31630,"n":"מרגליות, משה זאב וולף מהורדנא","f":"אליעזר מהלוסק","k":"בעל מראות הצובאות","r":"רב ופוסק - רב בטיקטין, ביאליסטוק","bt":"תקכח","bp":"גרודנא","dt":"תקצ - ד טבת","dp":"ביאליסטוק","b":"מגדולי חכמי דורו. חתן הגביר ר נפתלי-בן ר שמואל ר ברכ'ס. רב וראש ישיבה בהורדנא-תקע, טיקטין-תקעג על מקום ר מרדכי הלוי ור אריה ליב בעל אסיפת הגאונים בן ר מרדכי הלוי על מקומו אחריו, ביאליסטוק-תקפד. חיבר גם \"חדושי מהרמ\"ז\", \"אגודת אזוב\", ועוד. בניו: ר שמואל יצחק יעבץ מוילנא, ר מנחם דוד יעבץ מקאנסקוואלי, כתה\"י של ספרו \"אגודת אזוב\" הגיע לאוסף פרידלנד בפטרבורג.","bk":[["אגודת אזוב",""],["חידושי מוהרמ\"ז",""],["מראות הצובאות",""],["אגודת אזוב [שו\"ת",""],["עשו\"ע",""],["עהש\"ס",""],["דרשות]",""],["מראות הצובאות","מפרשי שו\"ע"],["אגודת אזוב","שו\"ת - אחרונים"]],"e":"תקכ\"ח-תק\"צ","rb":"טיקטין, ביאליסטוק","co":{"a":"53.2,22.783333"}},{"i":31631,"n":"מרגליות, משה זבולון מליטא ונ\"י","f":"שלמה זלמן","k":"המגיד מגרודנא,בעל שם הגדולים השליש","bt":"תריא","bp":"קראזני(=קרוז')","dt":"תרצז - ז אלול","dp":"ניו יורק","b":"נכד ר אברהם מרגליות מטלז, ונכד-אבי אמו ר וולף אלטשול מלוצן בעל \"שפת הים\", ומצאצאי ר אליהו קרויזר-גיסו של הגר\"א. תלמיד דודו ר דוד קרוזיר ממערטש, ר יו\"ט הלפרין מביאליסטוק בעל \"עונג יו\"ט\". רב בביאליסטוק, מארטש-תרלו, סלבודה-תרלז, היגר לארה\"ב-תרנח וכיהן כרב בבוסטון-תרנט, ניו יורק-תרסו בק\"ק \"ישורון\", היה זקן הרבנים באמריקה. חתם ב\"לדור אחרון\" ניו יורק תרצז - לאסור קידושין על תנאי כהצעת הריפורמים. חיבר פירוש לחומש."},{"i":31632,"n":"מרגליות, משה יוסף מקראקא","f":"משה מרדכי","b":"מחכמי קראקא."},{"i":31633,"n":"מרגליות, משה לוי מהיבנוב","f":"אלכסנדר אשר מברודי","dt":"תרעב - לפני","b":"רב בהיבנוב."},{"i":31634,"n":"מרגליות, משה מבנדין","f":"אהרן מרגליות","b":"רב בבנדין-תק\"ל"},{"i":31635,"n":"מרגליות, משה מטרניגרד","f":"מנחם מנדל מפרמישלא","b":"רב בטרניגרד-ת\"נ. בנו ר מנחם מנדל מקורטשין."},{"i":31636,"n":"מרגליות, משה מלעסלא","f":"יהודה ליב-פרי תבואה"},{"i":31637,"n":"מרגליות, משה מנירנברג","b":"מגדולי הפוסקים בחכמי אשכנז,רב בנירנברג-ק\"ס"},{"i":31638,"n":"מרגליות, משה מפרג","f":"יצחק מרגליות","b":"פרנס בפרג-ש\"כ"},{"i":31639,"n":"מרגליות, משה מרדכי מפשמישל","k":"בעל מטה משה","dt":"ת - ט כסלו","b":"מגדולי חכמי דורו, רב בפשעמישל"},{"i":31640,"n":"מרגליות, משלם נתן מברדיטשוב","f":"יעקב בן שמואל מזלישט","bt":"תקלו","dt":"תריז-תרכא","b":"תלמיד ר מנחם מנדל מקוסוב, ר משה צבי מסאווראן ור לוי יצחק מברדיטשוב. רב בברדיטשוב אחרי ר לוי יצחק, בנו ר יעקב על מקומו אחריו. היה מקורב לגדולי האדמורים בדורו. אצל וונדר מופיע כבנו של ר שמואל אב\"ד זילשטשיק - ולא נכדו."},{"i":31641,"n":"מרגליות, נח מוילנא","b":"חתן ר זלמן בן וולף-חתן ר חיים שמש-הנקרא ר חיים איצעלעס. גביר מחכמי וילנא. גבאי בקלויז הגר\"א יחד עם ר ליבלי זלקינדס-תקסב. חתם בפנקס הגר\"א פעמים רבות."},{"i":31642,"n":"מרגליות, נחמן אידל מיאקובשטט","f":"אליעזר ליפמן מוילנא","bt":"תקצג","bp":"וילנא","dt":"תרנח - יב שבט","dp":"מיטאווי","b":"מצאצאי ר משה זאב וולף ממינסק והמהר\"ל. חתן הגביר ר מיכל גורדון מדינבורג(=דוינסק). אב\"ד יאקובשטט-תרל על מקום ר מאיר מארים בעל \"ניר\", קרייצבורג, מיטאוי-תרן (והיה גם רב מטעם הממשלה). תשובות ממנו ב\"ציוני\". הניח שו\"ת בכת\"י."},{"i":31643,"n":"מרגליות, נחמן הכהן מאוסטרהא","f":"בצלאל אב\"ד אוסטרהא","dt":"תקלד - ד אדר","dp":"אוסטרהא","b":"מצאצאי ר נתן שפירא בעל מגלה עמוקות, נכד-מצד אמו ר יואל הלפרין. חתן ר חיים רפפורט מלבוב. רב בערזדוב, פרנס מחכמי אוסטרהא ואלוף הגבאים על מקום דודו ר מרדכי הלפרין בהגאון מפינסק. מבניו: ר יואל מביחוב ואוסטרהא. חתניו: ר אריה יהודה ליב בן פנחס בן ר שאול מלודמיר. נכדו - ר חיים נחמן פרנס מוילנא. הניח ספר בכת\"י שהגיע ללבוב - ולא נדפס."},{"i":31644,"n":"מרגליות, נחמן ממזריטש","f":"מנחם מנדל מפרמישלא","b":"רב במזריטש-ת\"מ"},{"i":31645,"n":"מרגליות, נפתלי הרץ מגומבין","dt":"תקנו - א חשון","b":"רב בגומבין"},{"i":31646,"n":"מרגליות, נפתלי מברודי","dt":"תקנב - יח כסלו","b":"מחכמי ברודי"},{"i":31647,"n":"מרגליות, נפתלי מרדכי מהרימלוב","f":"מאיר","b":"רב בהרימלוב-תקע, ועוד קהלות. בנו ר שמשון אריה מו\" \"תקוני זהר\" פולנאה תקנא."},{"i":31648,"n":"מרגליות, נפתלי צבי הירש מהרימל","f":"אלכסנדר סנדר מסטנוב","b":"חתן ר ליב מהרימלוב, מחכמי הרימלוב, למברג."},{"i":31649,"n":"מרגליות, נתן נטע מרדושקביץ","f":"משה זאב ממינסק","b":"רב ברדושקביץ-ת\"צ"},{"i":31650,"n":"מרגליות, נתן נטע שפירא מאוסטרה","f":"אליעזר מרגליות שפירא","dt":"תקכח - טו אב","dp":"אוסטרהא","b":"מצאצאי בעל \"מגלה עמוקות\". דיין ומו\"צ באוסטרהא בזמן ר אברהם משלם זלמן. נזכר בפנקס הח\"ק. בנו הפרנס ר אביגדדור מאוסטרהא. וחתנו כנראה ר שמואל בן אריה ליב מקרמניץ."},{"i":31651,"n":"מרגליות, עקיבא מבוריסוב","f":"אליעזר מרגליות","k":"בעל ביזת מצרים","b":"רב בבוריסוב(=באריסוב)-תקכ. בנו - ר שלמה."},{"i":31652,"n":"מרגליות, פיבוש מטרניגרד","f":"משה מרגליות","b":"רב בטרניגרד-ת\"פ"},{"i":31653,"n":"מרגליות, צבי הירש","f":"אלכסנדר סנדר מרגליות","b":"רב-שנת תק\"פ"},{"i":31654,"n":"מרגליות, צבי הירש","f":"חיים מרדכי מדובנא","b":"חתן הגביר ר אשר שמחה גינצוברג מויטבסק."},{"i":31655,"n":"מרגליות, צבי הירש מיזלוביץ","f":"יוסף מיזלוביץ","bt":"שצז","bp":"זולקוא","b":"רב ביזלוביץ-תקך על מקום אביו - במשך 84 שנה. בניו: ר יצחק דב על מקומו אחריו ביזלוביץ, בעל \"מאיר נתיבים\"."},{"i":31656,"n":"מרגליות, צבי הירש מלבוב","f":"משה","b":"מראשי קהלת לבוב, חתם-תעח עם ר משה קאזינר, ר ישכר בר טרניפולר, ר משה קיקניש ועוד."},{"i":31657,"n":"מרגליות, צבי הירש מלובלין","f":"שאול מלובלין","dt":"תקסו - ד כסלו","b":"חתן ר אריה ליב מרישא ולבוב. רב בלובלין-תקמח. בניו: ר יהושע העשקי, ר אוטשי זלמן."},{"i":31658,"n":"מרגליות, צבי הירש מלודמיר","f":"שמואל מפוזנן","b":"אב\"ד לודמיר-שפ. נזכר בשות הב\"ח. אחיו - ר אברהם מזולקווא, ר משה מרדכי בעל \"חסדי ה'\", ר מנחם מנדל מוילנא."},{"i":31659,"n":"מרגליות, צבי הירש ממזריטש","b":"אב\"ד מזריטש גדול-תקמ. (דודו זקנו של ר אפרים זלמן מרגליות מברוד). חתנו - ר יצחק איזיק הכהן בעל \"ברית כהונת עולם\"."},{"i":31660,"n":"מרגליות, צבי הירש שמחוביץ ממינ","f":"שמחה מפוחאביץ","b":"גביר מחכמי מינסק בזמן ר ישראל מירקש, ופעלו יחדו בהקמת מוסדות צבור חסד ותורה. בנו - ר חיים ממינסק."},{"i":31661,"n":"מרגליות, צבי הירש שמחוביץ ממינ","f":"חיים ממינסק","b":"גביר במינסק-תר בערך, עם חברו ר יעקב הורביץ. חתנו - ר יעקב הלל אטינגר ממינסק."},{"i":31662,"n":"מרגליות, צבי מיזלוביץ","f":"יצחק דוב מיזלוביץ","b":"רב באסטיטשקא,יאזלוביץ(=ייזלוביץ)-תקע על מקום אביו."},{"i":31663,"n":"מרגליות, ראובן מלמברג ותל אביב","f":"משה","r":"ספרן בספרית הרמב\"ם","bt":"1889","bp":"למברג","dt":"ה'תשלא","b":"חתן ר מאיר שיין, ובזיוו\"ש חתן ר מאיר הכהן טויבה. הוציא לאור רבעון לביבליוגרפיה \"המודיע\", עלה לארץ תרצה והיה מנהל ספריית הרמבם בתל אביב. חיבר עשרות ספרים, וביניהם: \"תולדות אדם\" למברג תרעב. פרסם מאמרים ב\"בית הכנסת\" - תל אביב תשו, \"המאור\" - תל אביב תרצה, \"סיני\" - ירושלים תרצז, \"הפוסק\" - תל אביב תש-תשיד, \"קול תורה\" - ירושלים תרץ-תשז.","bk":[["מרגליות הים","מפרשי ש\"ס - אחרונים"],["נפש חיה [על שו\"ע או\"ח]",""],["אור המאיר - תולדותיו של ר' מאיר מפרימישלאן",""],["גבורת ארי - תולדות ר' ליב שרה'ס",""],["דברים בעתם - דרוש",""],["הגדה של פסח - עם פירוש באר מרים, וקהלת משה",""],["הלולא דצדיקיא - רשימת ימי השנה של צדיקים",""],["המקרא והמסורה",""],["טל תחיה - בתי המשפט בארץ ישראל, רופאים ורפואות, ומשפטי גר תושב",""],["ילקוט מרגליות - דרוש",""],["ילקוט פנינים - דרוש",""],["יסוד המשנה ועריכתה",""],["לחקר שמות וכינויים בתלמוד",""],["מחקרים בדרכי התלמוד וחידותיו - עוללות",""],["מלאכי עליון",""],["מקור ברוך - תולדות רבי ברוך ממז'בוז'",""],["מקור הברכה - ברכת המצוות ומטבע ברכתן",""],["מקור חסד - ספר חסידים",""],["מרגליות הים - סנהדרין",""],["ניצוצי אור - ש\"ס",""],["ניצוצי זוהר - תיקוני זוהר",""],["נפש חיה - שלחן ערוך",""],["נר למאור - פירוש אור החיים על התורה",""],["סיבת התנגדותו של רבינו יעקב מעמדין לרבינו יונתן אייבשיץ",""],["פנינים ומרגליות",""],["קב בשמים - קב הערות בדברי התוספות וענינים מסתעפים",""],["קוי אור - חקרי הלכה במשפטי הישוב המדיני בארץ ישראל",""],["שיחות חכמים",""],["שם עולם",""],["שערי זהר",""],["תולדות אדם - תולדות המהרש\"א",""],["תולדות רבינו חיים בן עטר",""],["תולדות רבנו אברהם מיימוני הוא ר' אברהם בן הרמב\"ם",""],["תפארת אדם - ר' דוד משה מטשורטקוב",""],["נפש חיה",""]],"e":"תר\"ן-תשל\"א"},{"i":31664,"n":"מרגליות, ראובן מפוטיק","f":"משה","bp":"פוטיק","b":"עלה לצפת-תרטז. ביק בנדבורנה ורכש מנכדי המגיד את כתביו - הדפיס \"שפתי קדושים\" למברג תרל. בנו ר בן ציון חתן נכדת ר דוד אריה ליב מנדבורנה."},{"i":31665,"n":"מרגליות, רפאל יהושע השל מפיעט","f":"צבי הירש מלובלין","dt":"תרח - כח שבט","b":"תלמיד החוזה מלובלין, ר שמחה בונם מפשיסחא, ור מנחם מנדל מקוצק. רב בפיעטרקוב."},{"i":31666,"n":"מרגליות, שאול דוד הכהן מפרשקוב","f":"אלתר יוזפא הכהן","k":"בעל שדה מרגליות","bt":"תרס","bp":"גרויבליץ(=גרעבליס)","dt":"תשמח","b":"רב בסוכוסטוב, בלזיץ, פרושקוב (ליד וארשא). חסיד גור. בזמן השואה עסק בפעילות עזרה ליהודים, ניצל דרך שנחאי, והיגר לניו יורק-תשו ויסד ביכ\"נ \"אהל רחל\". הוציא לאור חוברות על התורה - פערל פון אונדזער תורה. רב בניו יורק. חיבר \"שדה מרגליות\" ירושלים תשנו. בנו - ר יהושע פאליק - נספה בשואה בגיל 17."},{"i":31667,"n":"מרגליות, שאול מזברז ולובלין","f":"מאיר","dt":"תקמו-ח- כז כסלו","b":"תלמיד הבעשט. חתן הגביר ר שאול בן חיים מלובלין. רב בזברז, קומרנא-תקיב, לובלין-תקיח. הסכים על \"כלילת יופי\", \"עמודי כסף\", ועוד. מתורתו בספר אביו. הסכים על \"תולדות יוסף\", \"ערכי הכנויים\", ועוד. תיקן בלובלין תקנות רבות ובהם תקנה לבל יוקמו מנינים נפרדים. בצעירותו כשישב אצל אביו הרב ביזלביץ ראה את הדוכס פוניטאייסקי בהיותו צעיר אצל אביו וראה בו גינוני מלכות ואביו סיפר זאת לדוכס ולאביו וכי בנו הינו חכם הרואה את הנולד וכי הדוכס יהיה למלך פולין - וכשהתמנה למלך זכר זאת ונתן כתב רבנות לאביו, ור שאול כשחלה בהיותו בלובלין -טופל ע\"י רופא המלך בוארשא. בנו - ר צבי הירש מלובלין."},{"i":31668,"n":"מרגליות, שאול מחעלמא","b":"רב בחעלמא-ת\"צ"},{"i":31669,"n":"מרגליות, שבתי שפטל מקעסטעהל","f":"גרשן הלוי מטרנופול","b":"תלמיד ר יהושע באבד בעל \"ספר יהושע\", רב בקעסטעהל-תקפט - והיה מחלוקת כנגדו ועזב, סעטשין - וגם שם נאלץ לעזוב בגלל מחלוקת כנגדו."},{"i":31670,"n":"מרגליות, שלמה ליברמן","f":"שמואל מרגליות","k":"ר' שלמה מעיר הברזל","b":"רב באייזנשטט,פוזנא-ר\"ס-שי\"א"},{"i":31671,"n":"מרגליות, שלמה צבי מארה\"ב","k":"בעל פנינים יקרים","b":"רב ברוצ'סטר-ארה\"ב-תרפו."},{"i":31672,"n":"מרגליות, שלמה שמריהו מבריינסקי","b":"אב\"ד בריינסקי. פרסם מאמרים ב\"הועד\" - פיעטרקוב תרעד."},{"i":31673,"n":"מרגליות, שמאי מזלוזיץ","b":"מחכמי זלוזיץ."},{"i":31674,"n":"מרגליות, שמואל מוילנא","f":"מנחם מנדל מפרמישלא","b":"מגדולי חכמי וילנא-תל, נזכר ב\"ברכת הזבח\"."},{"i":31675,"n":"מרגליות, שמואל מזלישטשיק ולבוב","f":"יצחק דב","b":"בנערותו ישב שנה אצל הבעש\"ט. חתן ר אברהם בן יעקב מפוזנא. רב בזלישטשיק, דיין בלבוב, חתם-תעג עם ר משה מזאמושט ועוד. (לפי בובר היה בנו של בעל באר יצחק - הדבר לא מסתדר עם התאריכים ואולי החליפו עם המסומן באוצר כ-19275)."},{"i":31676,"n":"מרגליות, שמואל מלבוב","f":"יצחק דב","bt":"תצג","dt":"תקסה - כד שבט","b":"דיין בלבוב,"},{"i":31677,"n":"מרגליות, שמואל מסטרי","f":"אלכסנדר סנדר מסטנוב","bt":"תקכ","dt":"תקף או תקפו","b":"חתן הגביר ר משה בן שמואל מברודי. רב דאליטשקער, סוריהער, קרמניץ, מיקוליניץ, סטרי-תקעג על מקום הקצות. הוציא לאור יחד עם בן דודו ר אפרים זלמן מרגליות \"שות הב\"ח החדשות\". חיבר ספר דרושים - בכתב יד."},{"i":31678,"n":"מרגליות, שמואל מפוזנן","f":"משה מרגליות","b":"מגדולי דורו, רב בפוזנן-רפז. בניו - ר שלמה ליברמן, ר משה מרדכי בעל חסדי ה', ר אברהם מזולקווא, ר צבי הירש מלודמיר, ר מנחם מנדל מוילנא."},{"i":31679,"n":"מרגליות, שמואל מקאוולי","f":"מרדכי","dt":"תצג - אחרי","b":"רב בקאוולי. נספד בספר החיים לר חיים רפפורט."},{"i":31680,"n":"מרגליות, שמואל מקרליפקא","b":"רב בקרליפקא-תרלה."},{"i":31681,"n":"מרגליות, שמואל מרקוב","f":"משה זאב ממינסק","b":"רב בראקוב-ת\"צ"},{"i":31682,"n":"מרגליות, שמואל צבי הירש","f":"אפרים זלמן מברזן","bt":"תריח","bp":"ברזן(=ברזשעזשאן)","dt":"תרפב - יב אדר","b":"תלמיד ביהמ\"ד לרבנים בברסלוי, בעל תואר דוקטור. רב בקהלת \"נאוה שלום\" בהמבורג-תרמה, ווילבורג (אססן-נאסוא)-תרמז, פלורנץ(=פירנצה)-איטליה-תרן ועמד שם בראש בית המדרש לרבנים. יסד כתב עת באיטלקית - ריוויסטה איזראליטיקה. והיה מראשי היהודים באיטליה."},{"i":31683,"n":"מרגליות, שמחה מפוחאביץ","f":"מנחם מנדל ממינסק","b":"רב בפוחאוויץ-תקי. בנו - ר צבי הירש שמחוביץ ממינסק. אחיו - ר יוסף מסלוצק והאלוסק."},{"i":31684,"n":"מרגליות, שמעון יצחק","f":"יקותיאל לזל","k":"הו\"ל גבעת הלבונה","bt":"תרפה","b":"ניצל מהשואה - גלה לסיביר. עלה לארץ. חסיד הוסיאטין וסדיגורא. גבאי בימ\"ד רוזין בבני ברק. ההדיר \"גבעת הלבונה\" לדודו."},{"i":31685,"n":"מרגליות, שמשון אריה","f":"נפתלי מרדכי מרגליות","b":"רב-שנת ת\"ר"},{"i":31686,"n":"מרגליות, שמשון מטשסנוביץ","b":"מחכמי טשסנוביץ-תרכט, בזלוזיץ. חתנו היה בעל \"מנחת שי\"."},{"i":31687,"n":"מרגליות-יפה שלזינגר, מ'","f":"משה מרגליות שלזינגר","bt":"שעה","dt":"תמג","b":"עק\"ה"},{"i":31688,"n":"מרגליות-יפה, בנימין וולף מוינה","f":"מרדכי מרגליות יפה","bt":"תיא","dt":"תפז","b":"מגדולי מנהיגי ווינה"},{"i":31689,"n":"מרגליות-יפה, יוסף יצחק מוינה","f":"מרדכי מרגליות","bt":"תעה","dt":"תקלא","b":"מגדולי חכמי ווינה"},{"i":31690,"n":"מרגליות-יפה, ליב מפרשבורג","b":"מחכמי פרשבורג, חתם-תקכח על תקנות החברא קדישא."},{"i":31691,"n":"מרגליות-יפה, מנחם מאניש מויטקו","f":"מרדכי מרגליות","bt":"תקכא","dt":"תקסא - כג טבת","b":"רב בוויטקוב,דינאביץ,לכוויץ,גריידיץ"},{"i":31692,"n":"מרגליות-יפה, מרדכי מוינה","f":"בנימין וולף","bt":"תמד","dt":"תקטו","b":"חתן ר יעקב אשקלש משטאמפן. מקובל, גביר, קרוב למלכות, פרנס וינה."},{"i":31693,"n":"מרגליות-יפה, מרדכי מסערעד וינה","f":"יוסף יצחק מרגליותיפה","bt":"תקטז","dt":"תקצ","b":"חתן ר דוד הלוי זינרייך מסעליש. מגדולי סערעד, וינה. בנו - ר ישראל דוד מפעזינג."},{"i":31694,"n":"מרגליות-פרקש, אהרן מניגרעשט","b":"תלמיד החת\"ס. מחכמי ניגרעשט. בנו - ר אלכסנדר פרקש ממעדיאש."},{"i":31695,"n":"מרגליות-רוקח, שלום מטיקטין","f":"אלעזר מאמשטרדם וצפת","dt":"תקכז","b":"רב בטיקטין. בנו - ר יהושע מפינסק."},{"i":31696,"n":"מרגליות-שטנגן, מנחם מנדל","f":"יואל","dt":"תיב - כג ניסן","b":"חתן ר מרדכי מרגליות מקראקא, ובזיוו\"ש חתן ר משה חריף מלבוב וקרמניץ. רב בפינשוב, פרעמישלא. מחותן עם ר אברהם ר יוספש-ראש מדינה בטיסמניץ."},{"i":31697,"n":"מרגליות-שלזינגר, משה","f":"יהודה אריה יפה","bt":"שמ","dt":"תי"},{"i":31698,"n":"מרגרטן, יצחק צבי מאבראהאם","k":"בעל תוקף התלמוד","bt":"תקסח","dt":"תרי - ו סיון","b":"חתן ר חיים קיצע בעל \"אוצר החיים\". רב באבראהאם(=אבראני). חיבר גם \"בית דוד\"."},{"i":31699,"n":"מרגרטן, משה מהעטהארש","f":"יצחק צבי מאבראני","dt":"תרנו - טז סיון","dp":"העטהארש?","b":"נכד ר חיים קיצע בעל \"אוצר החיים\". רב בהעטהרש-תרס."},{"i":31700,"n":"מרגשס, יקותיאל זלמן מברודי","dt":"תקפז - י שבט","b":"גביר,מגדולי ברודי"},{"i":31701,"n":"מרדכי"},{"i":31702,"n":"מרדכי","b":"רב-שנת תק\"צ"},{"i":31703,"n":"מרדכי","f":"שמעון מזאוואכיסט","b":"רב-שנת תר\"מ"},{"i":31704,"n":"מרדכי","f":"אהרן","b":"הסכים על \"חדושי מהר\"י (ר יעקב בן לוי מבריסק)-תקמח."},{"i":31705,"n":"מרדכי אב\"ד מטומשוב","f":"יוסף מוילנא","dt":"תט","b":"מגדולי חכמי דורו, רב בטומשוב, ראב\"ד בלבוב. נהרג עק\"ה בגזירות תח-תט. אחיו - ר יהושע בעל \"מגיני שלמה\"."},{"i":31706,"n":"מרדכי אברהם מירושלים","f":"צבי מחמלניק","dt":"תרל","dp":"ירושלים","b":"חסיד רוזין. עלה לארץ-תרא, והגיד שיעורים בביה\"כ \"תפארת ישראל\"."},{"i":31707,"n":"מרדכי אברהם מצפת","b":"מחכמי צפת, חתם-תקפו על כתב שליחות ר מסעוד פינטו."},{"i":31708,"n":"מרדכי אליהו מוינה","b":"גביר מראשי קהלת הספרדים בוינה-תקס בערך. סייע לר יהודה ן סיד בהדפסת ספרו \"נר מצוה\"."},{"i":31709,"n":"מרדכי אליעזר קאוונער מוילנא","b":"מחכמי \"ישיבת הארבעים\" בוילנא-תקפז."},{"i":31710,"n":"מרדכי אריה מפרמישלן","f":"צבי בן מאיר מפרמישלן","k":"אדמור מפרמישלן","b":"ממשפחת אדמורי פרמישלן. חתן ר משה מזוויהל (זלוטשוב) - השני."},{"i":31711,"n":"מרדכי בן הלל הכהן","f":"הלל","k":"בעל המרדכי","dt":"ע - כב חשון","b":"חתן ר' יחיאל מפאריז. נהרג עק\"ה, מגדולי הפוסקים בחכמי אשכנז, רב בגסלר-שנת נא, נירנברג."},{"i":31712,"n":"מרדכי בן מנחם נחום מצ’רנובל","bt":"1770","dt":"ה'תקצז 1837","bk":[["הגדה של פסח",""],["לקוטי תורה",""]]},{"i":31713,"n":"מרדכי בער מיאניקה","b":"רב-שנת תק\"ע"},{"i":31714,"n":"מרדכי בצלאל משלוניקי","dt":"שעז - יד אלול","dp":"שלוניקי","b":"נהרג ליד שלוניקי בדרכו מיריד דולייא-שפח עם רבים מישראל."},{"i":31715,"n":"מרדכי גומפרכט מוינה","dt":"שפא - כד אלול","b":"רב בוינה"},{"i":31716,"n":"מרדכי גומפרכט מזולקוא","f":"יצחק","b":"מראשי קהלת זולקוא, חתם-תנט על קבלת ר אברהם אבלי בן מרדכי לאב\"ד זולקוא, חתם באספת קוליקוב-תן, ועוד."},{"i":31717,"n":"מרדכי גימפל מלבוב","f":"ראובן","k":"בעל מפלגי ראובן","b":"חתן ר מרדכי גימפל בן יעקב בן שמואל רעכליס. מחכמי אוסטרהא מיושבי הקלויז הגדולה, רב באנקוביץ(=וינקאביץ), דיין בלבוב-תקכ. והסכימו על ספרו רבני אוסטרהא ובהם ר אשר ענזיל בעל \"ברוך מבנים אשר\". חתם-תקלג עם ר יחיאל מיכל בריסקר ועוד. בנו - הגביר ר אליעזר ליזר מלבוב."},{"i":31718,"n":"מרדכי גימפל מלבוב","f":"יעקב בן שמואל רעכליס","b":"מצאצאי המהר\"ם מלובלין. מראשי קהלת לבוב, קנה קרקע-תמ מראשי קהלת לבוב. חתנו - ר ראובן מלבוב."},{"i":31719,"n":"מרדכי גימפל מלובק","b":"גדול בתורה,מוסר ומדות בלובק-תר\"נ"},{"i":31720,"n":"מרדכי גימפל מקרקוביץ","f":"נתן אברהם","b":"רב בקרקוביץ-תקסו."},{"i":31721,"n":"מרדכי דוב מקלויזנבורג","b":"דומ\"צ בקלוזנבורג-תרכ\"ה,עבר לווינה"},{"i":31722,"n":"מרדכי דידך הכהן","f":"ר\"ח","b":"פרסם מאמרים ב\"אוצר התורה\" - ג'רבה תרץ."},{"i":31723,"n":"מרדכי דן מליזנסק","b":"תלמיד ר אלימלך מליזנסק. נזכר ע\"י ר משה סופר משפוורסק באגרתו לר מנחם מנדל מרימנוב. מתורתו ב\"שפתי צדיקים\"."},{"i":31724,"n":"מרדכי הכהן","f":"אליהו בן דוד מאלטונא","k":"מאה\"ו","dp":"אלטונא","b":"נכד ר דוד בן מנחם הכהן מאלטונא. פרנס באה\"ו. חתניו: ר משה יצחק שפירא מפרג, ר אברהם אשקלס, ר אליהו בן אליקים גץ מקרזמיר, בנו היה חתן ר אריה ליב מאמשטרדם."},{"i":31725,"n":"מרדכי הכהן מאויבן","b":"ראב\"ד באויבן-ת\"י"},{"i":31726,"n":"מרדכי הכהן מאוסטרהא","f":"זכריה","dt":"שנב - יח כסלו","dp":"אוסטרהא","b":"מחכמי אוסטרהא."},{"i":31727,"n":"מרדכי הכהן מאלגיר","bt":"קמ","dt":"רי - בערך","b":"דיין בתנס-אלגיר. שאלות ממנו לרשב\"ץ בשו\"ת התשב\"ץ."},{"i":31728,"n":"מרדכי הכהן מברלין","b":"ממנהיגי קהילת ברלין. חתם על מינוי ר משה בן אהרן מלבוב ולייפניק לרבה של ברלין-תפט."},{"i":31729,"n":"מרדכי הכהן מהאמעל","f":"הלל","bt":"תרטז","bp":"מוהליב","b":"למד עברית אצל ר יעקב שמעון הכהן - מתרגם \"היהודים\" ללסינג. התגורר בפטרבורג, צערנינוב, האמעל. חיבר מאמרים ב\"הלבנון\", \"הצפירה\", \"המליץ\", ועוד. יסד אגודת סופרים בכנסיה הגדולה לציוני רוסיה במינסק."},{"i":31730,"n":"מרדכי הכהן מחודרוב","f":"יוסף מקלוש","b":"אחיו של בעל הקצות. רב בחודרוב. עזב את הרבנות ועבר לאונגוואר. היה נחשב לגדול בתורה כמו אחיו המפורסמים."},{"i":31731,"n":"מרדכי הכהן מחלב","b":"מקובל,מרבני ארם צובה-ש\"ל"},{"i":31732,"n":"מרדכי הכהן מחרסון","dt":"תקפג","b":"רב בחרסון"},{"i":31733,"n":"מרדכי הכהן מטבריה","b":"מחכמי טבריה-תקסז, חתם אז עם רבני טבריה."},{"i":31734,"n":"מרדכי הכהן מטיקטין","b":"דיין בטיקטין-תק\"נ"},{"i":31735,"n":"מרדכי הכהן מטנג'יר","bt":"תקפו","bp":"טנג'יר","b":"תלמיד ר יצחק כאהון, ור יצחק ן וואליד מטיטואן. רב בטנג'יר-תרכו. השיב תשובות רבות וגם לחכמי ירושלים."},{"i":31736,"n":"מרדכי הכהן מטריפולי","f":"יהודה","k":"בעל הגיד מרדכי","bt":"תרטז-יז","bp":"טריפולי","dt":"תרפג","b":"בן למשפחה שמוצאה מאיטליה. תלמיד ר אברהם אדאדי בעל \"ויקרא אברהם\". מורשה לבי\"ד בטריפולי, דיין בבנגזי-תרף. חיבר \"הגיד מרדכי\" לתולדות יהודי לוב, \"מנחת כהן\" - ובו ויכוח עם הנצרות, ועוד."},{"i":31737,"n":"מרדכי הכהן מירושלים","b":"מקובל, רב אשכנזי בירושלים. חברם של ר יעקב צמח, ר יצחק גאון ור נתן שפירא."},{"i":31738,"n":"מרדכי הכהן מלבוב","f":"יחיאל","dt":"תכד - ח אייר","dp":"לבוב","b":"מראשי קהלת לבוב. נהרג עק\"ה."},{"i":31739,"n":"מרדכי הכהן מסאלי","k":"בעל פסקי דינים","dt":"תעז-ט","b":"דיין בסאלי, עם ר יוסף צבע ור יעקב ביבאס. נזכר ב\"הלכה למשה\", ואצל היעב\"ץ. בנו - ר שלמה."},{"i":31740,"n":"מרדכי הכהן מסטנוב","f":"אברהם הכהן","dt":"תרטו - יט אדר","b":"רב בסטאנוב"},{"i":31741,"n":"מרדכי הכהן משלוניקי","b":"מחכמי שלוניקי, תלמיד בישיבת נתן העזתי בשלוניקי-תלז - אחרי המרתו של ש\"ץ."},{"i":31742,"n":"מרדכי הכהן מתונס","b":"סבו של המוהרש\"ך בעל \"לחם הבכורים\"."},{"i":31743,"n":"מרדכי הלוי","b":"רב-שנת תקפ. בנו - ר בעריש הלוי סטבשקי. אחיו ר מאיר הלוי."},{"i":31744,"n":"מרדכי הלוי מאזמיר","dt":"תקמו - א תמוז","dp":"אזמיר","b":"מחכמי אזמיר."},{"i":31745,"n":"מרדכי הלוי מאלטונא","f":"הרץ","dt":"תקנו - כט שבט","dp":"אלטונא","b":"מחכמי אלטונא."},{"i":31746,"n":"מרדכי הלוי מוילנא","b":"מחכמי \"ישיבת הארבעים\" בוילנא-תקפז."},{"i":31747,"n":"מרדכי הלוי מזאלישיץ ולבוב","f":"יצחק מחעלמא","b":"חתן ר יעקב בן יצחק כהנא שפירא. אב\"ד זאלישיץ, טיקטין, מחכמי לבוב-תקלז. הסכים על \"גבעת שאול\"-תקלד עם חדושים ממנו בתוך הספר, \"דברי קהלת\"-תקמה, \"שירי תהלה\"-תקסח. בנו - ר אריה ליב שהו\"ל \"אסיפת גאונים\" מזקנו ר השל מקראקא ומבעל חלקת מחוקק."},{"i":31748,"n":"מרדכי הלוי מירושלים","f":"[אהרן]","k":"בעל מאמר מרדכי,המלי\"ץ","dt":"תקסז","dp":"קושטא","b":"חתן הראשון לציון ר מרדכי יוסף מיוחס בעל \"שער המים\" (שם אשתו אסתרולה - נפטרה בכא אב תקעד). דיין בביה\"ד של ר משה יוסף מרדכי מיוחס. ראשון לציון על מקום חותנו-תקסו ור יעקב משה עייאש על מקומו אחריו. בשליחות אצל המושל ברמלה יחד עם ר יוסף מרדכי מיוחס, בשליחות ירושלים באיטליה-תקנג, בתורכיה-תקנו - יצא לגלות בקושטא בגלל גזרות המושל בירושלים. בשנת תקנט חתם על כתב שליחות ר יונה נבון ועוד. יתכן ופגש את החיד\"א בשליחות בתונס-תקלו. הדפיס \"אשי השם\", \"בית הבחירה\". חיבר \"מאמר מרדכי\". דיינים אצלו: ר חזקיה יצחק מזרחי שרעבי, ר מיכאל אריה, ר רפאל בן יוסף מיוחס, ר יעקב קוראל, ר שלמה בן בנימין מיוחס, ר אברהם אשכנזי, ר משה סוזין, ר יעקב משה עייאש."},{"i":31749,"n":"מרדכי הלוי ממצרים","f":"יהודה","k":"בעל דרכי נועם","dt":"תמד-ו","dp":"ירושלים","b":"למד בישיבת ר יהודה חביליו באלכסנדריה. רב במצרים ברוזטה(=רשיד, רוזיתא) ור דוד גרשון על מקומו אחריו-תיג, קהיר-תיג - תמה. חתן ר אברהם טאריקה. היה מחלוקת-תלח בינו ובין ר גבריאל איספרנסה מצפת. עלה לירושלים-תמד-ו. חיבר גם \"עבודת קדש\", \"מקראי קדש\" ועוד. בנו - ר אברהם בעל \"גנת ורדים\" על מקומו אחריו בקהיר."},{"i":31750,"n":"מרדכי הלוי מסטאבניץ","f":"שמואל","k":"בעל מרא דכיא - בכת\"י","dp":"סטאשוב","b":"אחיו של האדמור ר מאיר רוטנברג מאפטא. תלמיד ר אלימלך מליזנסק, ומראשני חסידיו של החוזה מלובלין - עוד בהיות החוזה בלנצהוט. היה חזן בסטאבניץ (וכשהיה אומר והוא רחום היה הקהל גועה בבכי), עבר לסטאשוב. נפטר בחיי ה\"חוזה\" שהספידו. מתולדותיו ב\"גדולת מרדכי\"."},{"i":31751,"n":"מרדכי הלוי מסלאויטש","k":"מרדכי הלוי מסלאוויטש","b":"מדקדק,רב בסלאוויטש-ת\"ס"},{"i":31752,"n":"מרדכי הלוי מסעליש","f":"צבי","dt":"תרנא - כא כסלו","dp":"סעליש","b":"מו\"ץ בסעליש-תקצט כ-50 שנה."},{"i":31753,"n":"מרדכי הלוי מפאס","f":"חסדאי","dt":"תקכז","b":"מחכמי פאס. נספד בידי ר אליהו הצרפתי. בנו - ר יהודה."},{"i":31754,"n":"מרדכי הלוי מפאס - ב","b":"מחכמי פאס-שנות ה-תק'-תר'."},{"i":31755,"n":"מרדכי הלוי מקלימנטוב","b":"רב בקלימנטוב-תפ\"ה"},{"i":31756,"n":"מרדכי הלוי מרוזנברג","b":"רב בצילץ?, רוזנברג-תק\"פ. בנו - ר אליעזר."},{"i":31757,"n":"מרדכי הלוי משימבורג ויאקובשטט","f":"יקותיאל זלמן","bp":"זאגר חדש","b":"חתן הפרנס ר יהודה צבי בן אליעזר מבירז, רב בשימבורג, חלפנעניץ, יאקובשטט-תר על מקום ר שמעון זרחי שעבר לטאוריג. חתנו - ר שניאור הלל'ס מבירז."},{"i":31758,"n":"מרדכי הלוי משלוניקי","dt":"תסג","dp":"שלוניקי","b":"רופא בשלוניקי."},{"i":31759,"n":"מרדכי הלוי משלוניקי - ב","b":"רב בשלוניקי-שנות ה-תק', בזמן ר חיים יוסף ן אדון."},{"i":31760,"n":"מרדכי הלוי סגל מטיקטין","f":"יצחק מלבוב וקראקא","dt":"תקעז - ז אייר","b":"נכד ר אריה ליב מלבוב ואמשטרדם, ונינו של ה\"חכם צבי\". חתן ר יעקב כהנא שפירא בעל \"אהל יעקב\". רב בזאלזיץ-תקלד, טיקטין-תקלז כ-40 שנה ור משה זאב מרגליות בעל \"אגודת אזוב\" על מקומו אחריו - והספידו בספרו. גיסו של ר שאול מדובנא ואמשטרדם. הסכים על ספרים רבים ובהם ספר קרובו ר שאול בן משה מלומז'ה \"גבעת שאול\" ומביא מתורתו ומכנהו - \"חתן דודי\". נספד ע\"י עוד מגדולי דורו. חיבר \"חמדה גנוזה\" - בכת\"י, וכתבים נוספים. בנו - ר אריה ליב בעל \"אסיפת הגאונים\" - כיהן כרב בטיקטין על מקום ר משה זאב."},{"i":31761,"n":"מרדכי הנגיד ממצרים","f":"אלהרביה","b":"נגיד במצרים-ד'תתך על מקום ר מבורך בן סעדיה, ור שמואל אבומנצור על מקומו אחריו."},{"i":31762,"n":"מרדכי הרופא מספרד","f":"נתן","k":"בעל מאיר נתיב","b":"מחכמי ספרד לפני הגירוש. חיבר קונקורדנציא \"מאיר נתיב\" יחד עם קרובו ר יצחק בן נתן."},{"i":31763,"n":"מרדכי הרץ מועלקוטש","b":"רב בוועלקאטש"},{"i":31764,"n":"מרדכי זאב מסקרטוב","b":"רב בסקארטוב-תר\"מ"},{"i":31765,"n":"מרדכי זאב מקאליבל","b":"רב בקאלביעל"},{"i":31766,"n":"מרדכי זיסקינד מלאשצוב","b":"הסכים על \"שבחי הבעשט\"."},{"i":31767,"n":"מרדכי זיסקינד מלובלין","b":"מו\"ץ בלובלין, חתם-תקפד על פסק דין בענין סכסוך בביהכ\"נ ר צבי הירש בן משה דאקטאר."},{"i":31768,"n":"מרדכי טאקלעס מליסא וברלין","f":"אברהם","k":"בעל תורת חיים ואהבת","bp":"ליסא?","dt":"תקג - כ סיון","dp":"ברלין","b":"הגיע מליסא לברלין-לפני תעב וכונה טאקלעס ע\"ש האשה טאקלעס שעזרה לו כשהגיע לברלין, ונקרא גם מרדכי ליססער. חתן ר אברהם ריז הלוי-בנו של ר מאדל ריז איטינגן מוינה, ובזיוו\"ש חתן המדפיס ר וולף מירלש פרנקל מברלין בן ר משלם זלמן מירלש מוינה-אב\"ד אה\"ו. דיין בברלין-תפב, הראב\"ד הראשון בברלין-תפו, גבאי ראשון בח\"ק-תפט על מקום ר מיכל חסיד. נזכר אצל חכמי דורו ובהם קרובו ר יחזקאל קצנלנבויגן אב\"ד אה\"ו ב\"כנסת יחזקאל\", וב\"שב יעקב\" לר יעקב הכהן מפפד\"מ. חיבר \"תורת חיים ואהבת חסד\" ונדפס ע\"י גיסו ר אברהם בן מאיר רינטל - ברלין תקי. בניו: ר וולף מברלין, ר איצק מברלין, ר ברוך מפפד\"מ וברלין, ר אברהם, ר זלמן ר מן. ומצאצאיו גם ר אברהם בן יצחק בן אשר בעל \"מסעות רבי בנימין\"."},{"i":31769,"n":"מרדכי יהושע מביאליסטוק וירושלי","b":"רב בירושלים-תר."},{"i":31770,"n":"מר'דכי יוסף מקריטשוב","f":"יחיאל?","b":"אולי בנו של ר יחיאל מקריטשוב שליח ירושלים בקושטא. חתם שמו - השדר\"ח (שלוחא דרחמנא?) אולי בניו או אחיו - ר פלטיאל שדר\"ח ור שמואל אלעזר שדר\"ח."},{"i":31771,"n":"מרדכי יעקב הלוי מירושלים","b":"מחכמי בית אל, חתם-תריא על כתב שליחות ר שלמה בכר אברהם עם חבריו - ר חיים נסים אבולעפיה, ר רפאל ידידיה אבולעפיה, ר רפאל מאיר פאניזל, ועוד."},{"i":31772,"n":"מרדכי כהן צדק מבודון","f":"דוד","b":"רב בבודון-שנות ה-ת'."},{"i":31773,"n":"מרדכי ליב מנאשלסק","b":"ראש חסידי פשיסחא וקוצק בנאשלסק - עוד בזמן היהודי הקדוש מפשיסחא."},{"i":31774,"n":"מרדכי מאדל סגל מוינה","f":"שמעון זימלא מוינה","k":"ואה\"ו","dt":"תפט","dp":"ונדסבק","b":"ממגורשי וינה, ממשפחת משולמים. רב בשוואבך-תקי"},{"i":31775,"n":"מרדכי מאוארשא","f":"ישראל ברוך מליאזני","dt":"תקפג - יא אדר","b":"אחיו של בעל התניא ועזר לו בהגהת ה\"שלחן ערוך\" שלו."},{"i":31776,"n":"מרדכי מאוסטרהא","f":"אברהם לעמיל","dt":"תקסב - בערך","b":"דיין מחכמי אוסטרהא. גיסו של ר ייב\"י והסכים על ספרו, ועל ספרים נוספים. חתם על פסק דין יחד עם יצחק איזיק מקוריץ ור אהרן שמואל הכהן מסטעפן. חתנו ר שמעיה מאוסטרהא, ונכדו יעקב יוסף על שם סיגו ר ייב\"י."},{"i":31777,"n":"מרדכי מאוסטרהא","f":"יעקב ר שמואלס מאוסטר","dt":"תצב - ג טבת","dp":"אוסטרהא","b":"פרנס מחכמי אוסטרהא. אחיו של ר שמואל ר יעקב'ס. חתם הרבה בפנסקי הח\"ק."},{"i":31778,"n":"מרדכי מאוסטרהא","f":"אליעזר ליפמן","dt":"תק - אחרי","b":"חתן הרופא ר מנחם מנדל סגל מאוסטרהא. פרנס באוסטרהא-תץ, יחד עם ר מרדכי הלפרין, ור שמואל ר יעקב'ס. נזכר ב\"נודע ביהודה\". בנו ר אליעזר ליפמן. יתכן שעבר לברוד."},{"i":31779,"n":"מרדכי מאוסטרהא","f":"יהודה ליב מפינסק","dt":"תקלה - אחרי","b":"אביו היה רב באוסטרהא סלוצק ופינסק. חתן ר יוזפא אוסטרר מאוסטרהא פרנס מדינת ואהלין. פרנס באוסטרהא עם חותנו ועם ר מרדכי הלפרין, ונזכר בפנקסי הקהלה - לפעמים נקרא \"ר מרדכי בהגאון\". חתם על תקנה-תקלב אחרי ר נפתלי הרץ הכהן. אחיו הגדול של ר אשר ענזיל בעל \"ברוך מבנים אשר\". חתנו: ר נפתלי הרץ הכהן מאוסטרהא ושדה לבן. לא ידוע אם עזב את אוסטרהא אחרי תקלה או נפטר שם."},{"i":31780,"n":"מרדכי מאוסטרהא","f":"גרשון","k":"מרדכלי ר גרשן'ס","dt":"תרה - ח שבט","dp":"אוסטרהא","b":"גביר באוסטרהא בעל חסד, משולח ונאמן אצל ר מאיר זוסמן מאוסטרהא - ונסע לפרייסן בשליחותו למכור סחורה, ועסק רבות בתורה. נפטר ללא ילדים, והוריש את ספריו החשובים לביהכ\"נ של רב ייב\"י."},{"i":31781,"n":"מרדכי מאוסציא","f":"דוד","b":"רב באוסציא-תר\"כ"},{"i":31782,"n":"מרדכי מאזמיר","f":"עזרא","b":"רב באזמיר, עלה לירושלים."},{"i":31783,"n":"מרדכי מאטל הלוי","f":"אליהו הלוי"},{"i":31784,"n":"מרדכי מאיר ממזריטש וירושלים","f":"אליהו","k":"ראבין-זאהן","dt":"תרכא - ז תמוז","dp":"ירושלים","b":"רב בביאלא, דיין בירושלים, ממונה כולל פולין, גבאי ומנהל \"עץ חיים\" בירושלים, חתם עם גבאי ה\"חורבה\". נזכר ב\"זכרונות לבן ירושלים\". לזכרו ב\"שדה בוכים\" לר מרדכי יצחק וינצימר."},{"i":31785,"n":"מרדכי מאיר מסעלץ","b":"שו\"ב בסעלץ בזמן כהונת ר ירוחם יהודה פרלמן-הגדול ממינסק, ולימד את ר ירוחם את עניני השחיטה ובדיקה למעשה."},{"i":31786,"n":"מרדכי מאלוינוב","b":"רב באולינוב-תק\"ל"},{"i":31787,"n":"מרדכי מאליק","b":"רב באליק-תר\"כ"},{"i":31788,"n":"מרדכי מאלקסניץ ואוסטרהא","b":"ראב\"ד באלקסניץ, ספרא ודיינא באוסטרהא על מקום ר מרדכי בן שמעון הורביץ. הסכים על \"חדושי הלכות\" לר העשיל - אוסטרהא תקסד, ועוד."},{"i":31789,"n":"מרדכי מארדיש מזולקוא","f":"הלל","dt":"תקעז","b":"מחכמי זולקוא, אב\"ד פאריצק. חיבר פירוש על מהר\"ם שי\"ף. חתנו - ר שמחה מלודמיר (בן אחותו של ר פנחס שמואל הורביץ מניקלשבורג)."},{"i":31790,"n":"מרדכי מארץ ישראל","f":"שמואל שאול","b":"מחכמי ארץ ישראל, בשנת שסח בשליחות באיטליה. הדפיס ספר \"תורת הבית\" לרשבא בונציה והפיצו באיטליה."},{"i":31791,"n":"מרדכי מאשמינא","b":"רב באשמינא-תרמ\"ג"},{"i":31792,"n":"מרדכי מאתיק","dt":"תקעא - ב כסלו","b":"רב באתיק"},{"i":31793,"n":"מרדכי מבויסק","b":"רב בבויסק-ת\"ר"},{"i":31794,"n":"מרדכי מבלטרמאנץ","b":"רב בבלטרמאנץ. אחיו - ר אברהם ליכטנשטין מאניקשט בעל \"כנפי נשרים\"."},{"i":31795,"n":"מרדכי מדאברי","b":"רב בדאברי-ת\"ס"},{"i":31796,"n":"מרדכי מדאלהינו","f":"אהרן מהורדנא","b":"רב בדאלהינו"},{"i":31797,"n":"מרדכי מהורדנא","b":"רב בהורדנא-שט. היה במחלוקת עם ר משה בן אהרן."},{"i":31798,"n":"מרדכי מהלברשטט וברלין","b":"ממנהיגי קהילת ברלין. חתם על מינוי ר משה בן אהרן מלבוב ולייפניק לרבה של ברלין-תפט."},{"i":31799,"n":"מרדכי מואדיסלב","b":"נכד בעל \"קצות החושן\". תלמיד ר מנחם מנדל מקוצק."},{"i":31800,"n":"מרדכי מוארשא","k":"בעל מר דרור","dt":"תרטו -י-טז תמוז","b":"מקובל, מו\"צ ודיין בוארשא."},{"i":31801,"n":"מרדכי מוארשליווקא","f":"ישראל מליטשניניץ","b":"חתן ר יוסף דוד מאליק"},{"i":31802,"n":"מרדכי מודל מלבוב","f":"מנחם מנדל","dt":"תיט - ז טבת","dp":"לבוב","b":"דיין בלבוב. חתם על פס\"ד-תיג עם ר נפתלי בן יהודה זעלקי, ועוד."},{"i":31803,"n":"מרדכי מוטל מאופוטשנה","b":"ראש חסידי קוצק באופוטשנה מזמן היהודי הקדוש מפשיסחא."},{"i":31804,"n":"מרדכי מוילנא","f":"יעקב ישראל מוילנא","dt":"תקלט - כב תמוז","dp":"וילנא","b":"מחכמי וילנא, קרובו של ר חיים מוולוזין. חתם בפנקס היסו\"ד-תקי. אחיו של ר משה יחיאל שהיה פרנס-תסח. בניו: ר ירחמיאל מוילנאר ישראל ראב\"ד הח\"ק בוילנא, ר אליהו הינדעס, חתנו ר אריה-חותן הגביר ר חייא דנציג."},{"i":31805,"n":"מרדכי מוילנא","f":"ישכר בער-אחי הגר\"א","dt":"תר - כ חשון","dp":"וילנא","b":"חתן ר יצחק אב\"ד ברעכטיצקע. מחכמי וילנא. בנו - הגביר ר אשר קלצקי מוילנא. חתנו ר אהרן נתנזון משוינצאן."},{"i":31806,"n":"מרדכי מוילנא","f":"דוד אלשאנער","dt":"תקפו - כא אד\"ב","dp":"וילנא","b":"מחכמי וילנא."},{"i":31807,"n":"מרדכי מוילנא","f":"ישראל","b":"ראב\"ד בוילנא, חתם-תסה עם ר שמואל זנויל מייזלש, ר יהודה ליב בן ישראל חריף, ר אהרן בן אברהם."},{"i":31808,"n":"מרדכי מוילנא","f":"עזריאל מוילנא","b":"גביר מראשי קהלת וילנא, חתם על תקנות הקהלה בשנות-תנ-ס כאביו לפניו. חתנו ר ליב שפירא."},{"i":31809,"n":"מרדכי מוילנא","f":"משה","b":"דיין בוילנא, חתם-תקיא עם ר חיים בן יחיאל."},{"i":31810,"n":"מרדכי מוילנא","f":"שלמה","dt":"תקנז - ח ניסן","dp":"וילנא","b":"מחכמי וילנא."},{"i":31811,"n":"מרדכי מוילנא","f":"יעקב פרץ מוילנא","dt":"תקסז - ה ניסן","dp":"וילנא","b":"גביר מחכמי וילנא."},{"i":31812,"n":"מרדכי מוילנא","f":"בנימין","dt":"תקסג - יט כסלו","dp":"וילנא","b":"מחכמי וילנא."},{"i":31813,"n":"מרדכי מוילקוטש","f":"שמואל","k":"בעל שער המלך","bp":"קוטנא","b":"חיבר \"שער המלך\" זולקוא תקכב."},{"i":31814,"n":"מרדכי מוינה","f":"חיים אברהם","b":"רב בווינה"},{"i":31815,"n":"מרדכי מוכיח מפרשבורג","f":"ישעיה","k":"?בעל ואבוא היום אל ?","dt":"תפט - יט אייר","dp":"קראקא","b":"נכד ר חיים שור בעל \"תורת חיים\", ובעל תוי\"ט-מצד אמו. חתן מהר\"ם שי\"ף. הגיע מאלזס, אב\"ד וינה, הגיע לפרשבורג-תעד. מטיף ודרשן. בניו: ר ליב ברלין מפרשבורג, וולף. חתניו - ר שלמה איזנשטט, ר משה לבוב-אב\"ד פרשבורג, ר נתן נטע מצונץ. נזכר אצל נכדו - ר ישעיה ברלין פיק מברסלוי בעל \"ההפלאה שבערכין\". מתורתו ב\"זכרון יוסף\" לחתן בנו. יש שטענו כי הוא ר מרדכי איזנשטט השבתאי ולדברי וינגרטן (בתולדות יהודי פרשבורג - הדבר לא יתכן)"},{"i":31816,"n":"מרדכי מורדאש מפאריצק","b":"רב בפאריצק. חיבר ביאור על חדושי המהר\"ם שיף."},{"i":31817,"n":"מרדכי מזאחלין ופרגא","b":"רב בזאחלין,פרגה"},{"i":31818,"n":"מרדכי מזולקוא","b":"רב בזלקווא-ת\"ק"},{"i":31819,"n":"מרדכי מזולקוא","f":"אברהם שרנצל","b":"חתן ר מאיר וייל-קצנלנבוגן."},{"i":31820,"n":"מרדכי מזולקוא","f":"זאב","b":"מחכמי זולקוא, חתם-תנא בפנקס הקהלה."},{"i":31821,"n":"מרדכי מזולקוא","f":"נחמן","b":"חתם בפנקס זולקוא-תפד עם מנהיגי הקהלה."},{"i":31822,"n":"מרדכי מזולקוא","f":"יוסף","b":"מחכמי זולקוא, חתם-תקכא עם האב\"ד - ר שמשון מייזלש."},{"i":31823,"n":"מרדכי מזולקוא","b":"חתן ר נתן מזולקוא. מחכמי זולקוא. מתורתו ב\"פלפולא חריפתא\" זולקוא תצו."},{"i":31824,"n":"מרדכי מחברון","f":"יצחק","b":"מחכמי חברון, בשליחות קהלת חברון-תמה. תרגם את שו\"ת הרמב\"ם מערבית - ונדפס בשם \"פאר הדור\" - אמשטרדם תקכח."},{"i":31825,"n":"מרדכי מטורקיה","f":"אליעזר","k":"בעל כתר תורה","dt":"רמה","b":"תלמיד ר חנוך צפורתא. מחכמי טורקיה, פילוסוף, פייטין ואסטרונום. חיבר גם ביאור על האבן עזרא, וספרים בחשבון והנדסה."},{"i":31826,"n":"מרדכי מטיסמניץ - ב","f":"משה אשכנזי או שמואל","b":"ראש המדינה ברייסין-תק\"י. חתנו - מאיר חיות מטיסמניץ."},{"i":31827,"n":"מרדכי מטיקטין","b":"רב בטיקטין-שנת ש'"},{"i":31828,"n":"מרדכי מינסקר מוילנא וירושלים","f":"אביגדור","k":"המשולח מוילנא","dt":"תר - כ כסלו","dp":"ירושלים","b":"מחכמי ירושלים. אולי מצאצאי בעל הש\"ך. שם אשתו - מלכה."},{"i":31829,"n":"מרדכי מירושלים","f":"ליב אריה","dt":"תרמב","dp":"ירושלים","b":"מחכמי ירושלים, חבר בית הדין בשנת תרלט ולאחר מיכן ראש בית הדין."},{"i":31830,"n":"מרדכי מירושלים","f":"מיכאל","b":"תלמיד ר אברהם צרפתי מירושלים. נשלח מטעם רבו אל הרא\"ם בקושטא."},{"i":31831,"n":"מרדכי מירושלים","f":"ירחמיאל בן מרדכי","b":"אחיו של ר אריה ליב נאמן, עלו לארץ עם ר מנחם מנדל משקלוב."},{"i":31832,"n":"מרדכי מיריטשוב","dt":"תקלז - יג חשון","b":"רב ביריטשוב"},{"i":31833,"n":"מרדכי מלאכי מירושלים","dt":"תנח - בערך","b":"גביר מחכמי ירושלים. חתנו - ר חזקיה די סילבה בעל \"פרי חדש\"."},{"i":31834,"n":"מרדכי מלבוב","f":"שלמה","dt":"תכד - ח אייר","dp":"לבוב","b":"ר\"מ בלבוב. נהרג עק\"ה."},{"i":31835,"n":"מרדכי מלבוב","f":"יצחק","b":"גביר מראשי קהלת לבוב, בעל חסד בנה בית אורחים ובית כנסת-שמב יחד עם אביו ואחיו - ר נחמן ואשת אחיו - המכונה 'רוזא של זהב'."},{"i":31836,"n":"מרדכי מלבוב (אשכנזי) - א","f":"צבי הירש","dt":"שצו - טו ניסן","dp":"לבוב","b":"רב בלבוב. חתם-שסא על פסק דין ביריד ירוסלב, יחד עם ר יוחנן הלוי בן דוד קשי' ארבך, חתם עם ר יעקב קצנלנבוגן ור נתן שטרנבורג ונזכרו ב\"איתן האזרחי\". חתם-תח עם ר אהרן בן פנחס ור יהודה ליווא אפשטין, חתם-שצג בפנקס פינטשוב עם שמואל הקטן ספרא בקרקא. שנת פטירתו נרשמה בטעות שצו - כך לפי בובר."},{"i":31837,"n":"מרדכי מלבוב - ב","dt":"תקכ - ה אייר","b":"עק\"ה,מרביץ תורה בלבוב"},{"i":31838,"n":"מרדכי מלבוב - ב","f":"צבי הירש","dt":"תקח - אחרי","b":"דיין בלבוב, חתם-תצט עם ר אברהם מטיסמניץ ור יוסף יהושע פאלק שור, חתם-תקג בענין עזבון, חתם-תקו עם ר אריה ליב כהנא רפפורט, ועוד."},{"i":31839,"n":"מרדכי מלבוב הקדוש","f":"יוסף","dt":"תט","b":"ראב\"ד בלבוב, אב\"ד טומשוב. נזכר בשו\"ת הב\"ח החדשות, ובספר אחיו - ר יהושע חריף בעל \"מגיני שלמה\". נהרג עק\"ה בגזרת תט."},{"i":31840,"n":"מרדכי מלבוב ודאברי","b":"רב בדאברי-ת\"ס"},{"i":31841,"n":"מרדכי מלובלין","dt":"תלה - ד אב","b":"רב בלובלין"},{"i":31842,"n":"מרדכי מלובלין","f":"בנימין","dt":"תקסו - ז אדר","dp":"לובלין","b":"מחכמי לובלין."},{"i":31843,"n":"מרדכי מלובלין","f":"צבי הירש הקדוש","b":"מחכמי הח\"ק בלובלין. חתם על בוררות בענין בחירת גבאי - תמה."},{"i":31844,"n":"מרדכי מלובלין","f":"דוד טעביל","dt":"תקעא - כד אייר","dp":"לובלין","b":"דיין ור\"מ בלובלין."},{"i":31845,"n":"מרדכי מלובלין ולבוב","b":"ראש מדינה בגליל לבוב. חתם על שטר חזקה ביריד ירוסלב-תמז."},{"i":31846,"n":"מרדכי מלובלין ולבוב","f":"שמריה שמרל","b":"חתם-תנד על תקנת קהלת זולקוא, על תקנות מאספת קוליקוב-תן, בועד ירוסלב אודות מדפיסי זולקוא-תנט, כנגד השבתאים בועד ירוסלב-תפב."},{"i":31847,"n":"מרדכי מלויצק","b":"רב בלוצק-ת\"א"},{"i":31848,"n":"מרדכי מלויצקא","f":"צבי הירש מלבוב","b":"חתם בועד ירוסלב-תנט בענין המדפיסים בזולקוא. הסכים על \"ברית שלום\", נזכר בהקדמה לספר הפלאה לנכדו (בן בתו) ר פנחס הלוי."},{"i":31849,"n":"מרדכי מלייפן","b":"רב בלייפן-תק\"פ"},{"i":31850,"n":"מרדכי מליסא","f":"ראובן מפוזנא או צבי","dt":"תקלז - כז ניסן","dp":"אלטונא","b":"נכד(-אבי אמו) ר יצחק מזולקוא. חתן דודו - ר אברהם מזולקוא (חתן ר יצחק מזולקוא). ראב\"ד בליסא, עבר לאלטונא."},{"i":31851,"n":"מרדכי מליסיץ","b":"תלמיד ר צבי הירש מנדבורנא. נזכר בספרי ר אברהם דוד מבוצאץ, ועוד."},{"i":31852,"n":"מרדכי מליעפלי","b":"תלמיד ר דב בר מליובאויטש."},{"i":31853,"n":"מרדכי מליפלי","b":"מראשוני חסידיו של בעל התניא. גביר מקורב למלכות ועשיר. הגיע לפטרבורג ושהה שם בזמן שרבו ישב שם בכלא. בעל התניא היה אצלו בחתונת אחד מילדיו."},{"i":31854,"n":"מרדכי ממוהליב וירושלים","b":"רב במוהליב,דיין בירושלים-תר\"נ"},{"i":31855,"n":"מרדכי ממינסק","f":"אביגדור","b":"משכיל מחכמי מינסק."},{"i":31856,"n":"מרדכי ממרוקו","f":"עזריה","dt":"תסט","b":"רב ודיין-בשלוניקי-תמז. מתלמידיו ר יצחק ן שאנג'י בעל \"בארות המים\", ור אברהם גאטיניו. בנו ר עזריה - נפטר-תץ, וחתנו ר חיים צרפתי."},{"i":31857,"n":"מרדכי מנאוויגרוד וירושלים","dt":"תריט - טז טבת","dp":"ירושלים","b":"מחכמי ירושלים."},{"i":31858,"n":"מרדכי מסמפולנא","b":"רב בסמפולנע-תר\"ל"},{"i":31859,"n":"מרדכי מעלקיש","f":"יוסף יוזפא","b":"תלמיד החת\"ס. מחכמי עלקיש (גליציה)-תקעו. תשובה אליו ב\"חתם סופר\"."},{"i":31860,"n":"מרדכי מפודהייץ","b":"רב בפדהייץ,רישא-ת\"מ"},{"i":31861,"n":"מרדכי מפולינייא","b":"מגדולי רבני איטליה,מרביץ תורה בקוני-פיימונט-של\"ה"},{"i":31862,"n":"מרדכי מפוקרוי מ\"אגודת חסידים\"","dt":"תקע - בערך","dp":"יאנישקול-פלך קובנא","b":"סירב להתפרנס מהתורה ולמד נגרות. הסכים לכהן כאב\"ד פוקרוי-(=פאקראי)-תקם והתנה שלא יקבל שכר אלא ימשיך לעבוד כנגר, וכך עסק רוב היום בנגרות כששפתיו דובבות בתורה. בסוף ימיו אב\"ד פוקרוי. ר מרדכי היה אחד מהחבורה של שלשה רבנים שנקראה \"אגודת חסידים\" עם חבריו ר שמואל חסיד בן ברוך מז'אמוט-נינו של ר ר ברוך פודקובקא, ור משה מטלז - ובמשך 15 שנה עשו אגודה אחת להתנזר מכל הנאות שבעולם ולמדו תורה בחסידות ובפרישות בנגלה ובנסתר, ופעמיים בשנה היו נוסעים אל הגר\"א שכינה אותם \"חסידי ז'אמוט\" (ונקראו גם \"חסידי ראסיין\"). מתורתם בספר \"זכרון יעקב\" לר יעקב בנדטמן בשם \"תורת חסידים\". בנו - ר נתן נטע רבינוביץ מראסיין."},{"i":31863,"n":"מרדכי מפינסק","dt":"תריט - כא תשרי","b":"רב בפינסק"},{"i":31864,"n":"מרדכי מפנליניו-איטליה","f":"גמליאל","b":"רב בקייני-איטליה בזמן המהרש\"ל. מתשובותיו בספרי חכמי דורו. מוזכר ב\"ברכת חתנים\"."},{"i":31865,"n":"מרדכי מפרג","b":"דיין בפרג-ש\"י"},{"i":31866,"n":"מרדכי מפרג","f":"אליהו","b":"חברו של יעקב פרנק יחד עם חברו - נחמן."},{"i":31867,"n":"מרדכי מפרדייץ","b":"רב בפדהייץ,רישא"},{"i":31868,"n":"מרדכי מצפת","f":"משה מגיד מוילייקה","dt":"תרם - יא ניסן","b":"עלה לארץ-תקצו עם אביו ואחיו ר אהרן שמואל."},{"i":31869,"n":"מרדכי מקאמין","b":"רב בקאמין,דיסנא-תר\"כ"},{"i":31870,"n":"מרדכי מקובנא","b":"מו\"צ בקובנה-תר\"ס"},{"i":31871,"n":"מרדכי מקולוניה","f":"שמואל בן נטורנאי","b":"נכד הראב\"ן-אבי אמו. ובנו ר שלמה מברונא."},{"i":31872,"n":"מרדכי מקומרנא","f":"שמחה אשכנזי","b":"רב בקומרנא-תק\"פ"},{"i":31873,"n":"מרדכי מקומרנא","f":"יחיאל מיכל מקומרנא","dt":"תרכז - כג אב","dp":"ישראל","b":"נינו של ר מאיר מפרמישלן. חתן ר אליעזר זאב מבוצאץ. עלה לארץ."},{"i":31874,"n":"מרדכי מקונסטנטין","b":"רב בקונסטנטין ישן-תר\"ס"},{"i":31875,"n":"מרדכי מקונסטנטין ישן","f":"מנחם מנדל מסטנוב","k":"אדמור מקונסטנטין","dt":"טז חשון","b":"חתן ר יעקב מקונסטנטין-ישן."},{"i":31876,"n":"מרדכי מקוריץ","f":"פנחס","dt":"תקעו - אחרי","b":"מחותנו של החוזה מלובלין. הסכים על הרבה ספרים שנדפסו בקוריץ."},{"i":31877,"n":"מרדכי מקושטא","f":"דוד","b":"מדפיס-תעא בדפוס של יונה בן יעקב בקושטא."},{"i":31878,"n":"מרדכי מקידאן","f":"יהודה מקידאן","b":"גיסו של הגר\"א (אביו ר מרדכי נשא את אחות אשתו של הגר\"א). בנו ר דובריש הלפרין-שוערדשרף."},{"i":31879,"n":"מרדכי מקראקא","f":"הרבי ר השל","b":"חתן ר יונה פרנקל-תאומים בעל קיקיון דיונה. רב בקראקא-תפ. בנו - ר שאול מזולקוא."},{"i":31880,"n":"מרדכי מקרטשין","b":"רב בקארטשין-תק\"י"},{"i":31881,"n":"מרדכי מקרליץ","b":"איש מופת,רב בבוטני,קרליץ,אושמינה,סלונים-תר\"ל"},{"i":31882,"n":"מרדכי מקרמאנד","b":"רב בקערמענד-תק\"נ"},{"i":31883,"n":"מרדכי מקרמניץ","f":"המגיד מזלוטשוב","k":"אדמור מקרמניץ","bt":"תקו-טו-כה","dt":"תקף - יא תמוז","b":"חתן ר אליעזר מלמד מקולבוסוב (וי\"א חתן ר לייביש גורזיצקר-תלמיד אביו). רב בקרמניץ. מתורתו ואודותיו - \"נחלת צבי\" לרמ\"מ ויזניצר - תשן. אחד מ\"חמשה חומשי תורה\" - כפי שכונו בני המגיד מזלוטשוב. מגדולי האדמורים בדורו."},{"i":31884,"n":"מרדכי מראב","b":"רב בראאב-תר\"י"},{"i":31885,"n":"מרדכי מראגובה ופוסוואל","b":"רב בראגאווא(=ראגובה), פוסבול-תרכ."},{"i":31886,"n":"מרדכי מראדין","f":"יהודה","k":"בעל פתח השער","dt":"תקעד - יז כסלו","dp":"ראדין","b":"גדול בנגלה ונסתר,דרשן בראדין. חיבר גם \"צפנת פענח\", \"תורת הסנה\" ועוד - בכת\"י. עמד לפני מלך פולין סטניסלב אוגוסט. אחיינו הגביר ר יהודה אפטוב מוילנא."},{"i":31887,"n":"מרדכי מרדוש מאוסטרהא","b":"ראש ישיבה באוסטרהא על מקום המהרש\"ל."},{"i":31888,"n":"מרדכי מרדוש מזולקוא ופאריצק","k":"בעל ביאור מהרם שיף","dt":"תקעו-ח","b":"חריף,רב בפאריצק"},{"i":31889,"n":"מרדכי מרוטרדם","f":"אריה ליב","b":"דיין ברוטרדם. בנו של ר אריה ליב ברסלוי-רבה של רוטרדם (נפטר תקסט)."},{"i":31890,"n":"מרדכי מרוסיה","f":"אברהם בן אברהם","b":"רב דמדינת רוסיה-ת\"ק"},{"i":31891,"n":"מרדכי מרעזינא","f":"שלמה זלמינא מרשקוב","b":"חתן ר משה דן מסקוירא (טשרנוביל)."},{"i":31892,"n":"מרדכי משאריגרד","b":"מתלמידי הבעש\"ט,רב בשאריגרד-תק\"מ"},{"i":31893,"n":"מרדכי משדה לבן","f":"צבי","b":"פרסם מאמרים ב\"קול תורה\" - וארשא תרסח."},{"i":31894,"n":"מרדכי משידלוב","f":"יצחק","b":"רב בשידלוב,סטאבניץ"},{"i":31895,"n":"מרדכי משלוניקי","f":"עזריה","dt":"תסט","dp":"שלוניקי","b":"דיין ור\"מ בשלוניקי."},{"i":31896,"n":"מרדכי משלם מיזירנה","b":"רב ביזירנה."},{"i":31897,"n":"מרדכי משצריץ","f":"נפתלי הירץ מברודי","k":"בעל פתחיה יה","b":"רב בשצריץ, ברודי. חיבר \"פתחי יה\" למברג תקנט."},{"i":31898,"n":"מרדכי מתמיד מוילקוביסק וירושלי","k":"מרדכי טראיאנאווער","b":"מצאצאי ר איזיק פאהאסטער. מחכמי ירושלים, ממונה על כולל הפרושים-תרי. נכדו ר ישראל איזקסון מניו יורק."},{"i":31899,"n":"מרדכי נחום מאזמיר","dt":"תריג - יא תמוז","dp":"אזמיר","b":"רב באזמיר."},{"i":31900,"n":"מרדכי נחמן משלוניקי","dt":"תקסג - בערך","dp":"שלוניקי?","b":"יסד בית דפוס בשלוניקי-תקט, עם רפאל יהודה קלעי. ממשפחת המדפיס אברהם בן דוד נחמן."},{"i":31901,"n":"מרדכי נתן","b":"מגדולי חכמי דורו,מרביץ תורה באוניון-רט\"ז"},{"i":31902,"n":"מרדכי סגל","b":"מו\"צ באויבן-תל\"ו"},{"i":31903,"n":"מרדכי סגל מצורטקוב","f":"יהודה ליב","b":"מחכמי סטנוב, רב בצורטקוב. גיסו של ר משולם איגרא."},{"i":31904,"n":"מרדכי סגל מקרונהיים","b":"דיין בגונצנהויזן והגליל, ואב\"ד בקרונהיים-תקנו (מאמצע המאה ה-18 ועד אמצע המאה ה-19 עמדה קהלת קרונהיים תחת הנהגת דייני גונצהויזן שנזכרו גם כאב\"ד קרונהיים),"},{"i":31905,"n":"מרדכי עזריאל מוילנא","f":"אברהם","k":"מרדכי עזריאלך","b":"דיין בוילנא, חתם-תכד עם ר יצחק מפוזנא. חתנו - ר ליב שפירא בעל נחלת אריאל."},{"i":31906,"n":"מרדכי פישל מבינישקי","b":"רב בבינישקי-תר. בנו - הגביר ר יהושע."},{"i":31907,"n":"מרדכי פישל מגרוסורדין","dt":"תרלא - אלול","b":"תלמיד ר יצחק אהרן לנדברג מגרוסורדין וגדל בביתו. קיבל מרבו את משרת הרב בכפר טעלעגד-ליד גרוסורדין והיה בראש ישיבה קטנה שם.נפטר צעיר"},{"i":31908,"n":"מרדכי פרץ מאישקופיה","b":"רב באישקופיה-שסז."},{"i":31909,"n":"מרדכי צבי מיוהאנא","b":"רב ביוהאנא-ת\"ר"},{"i":31910,"n":"מרדכי רופא מפרשבורג","f":"משה לבוב מפרשבורג","b":"מחכמי פרשבורג-בנו של האב\"ד, רופא ומלומד במדעים, למד רפואה בגרמניה."},{"i":31911,"n":"מרדכי שמואל מפיסארו","f":"מנחם","b":"רב בפיררה. תשובה ממנו-תח - יחד עם ר\"פ נונציליסי ור יצחק ידידיה בורגו. חתם עם רבני פיררה במכתב לקהילת מונפיראטו."},{"i":31912,"n":"מרדכי שניאור זלמן מזיטומיר","b":"מתורתו ב\"התמים\" - וארשא תרצה - קובץ חסידי חב\"ד."},{"i":31913,"n":"מרדכיאשוילי, יצחק מלאילאשי","bt":"תרם","bp":"לאילאשי-גרוזיה","b":"עלה לירושלים בגיל חצי שנה עם הוריו. תלמיד ישיבת חבקוק בירושלים, ונשלח לגרוזיה מטעם רבני ירושלים. רב בבאנדזה-גרוזיה-תרסב. חתן ר מנשה אג'יאשוילי מבאנדזה. לימד בישיבת קולאשי אצל ר אהרן בותראשוילי."},{"i":31914,"n":"מרדכיה, יחזקאל משה מדגסטן","dt":"תרף - יז שבט","dp":"ירושלים","b":"מראשי עדת דגסטן בירושלים. בשליחות בגיאורגיה, דגסטאן-תרנד."},{"i":31915,"n":"מרדר, אליהו מדזיקוב","f":"[יהושע]","bt":"תקפח","bp":"דזיקוב","dt":"תרעז","dp":"ירושלים","b":"רב בדזיקוב, ירוסלב. עלה לירושלים-תרסב. ההדיר כתבי יד והדפיסם. הדפיס \"תוספות הראש\" ירושלים תרסג, ועוד."},{"i":31916,"n":"מרוויט, ליבר מארה\"ב","bt":"תרמו","b":"רב בדוגילישיק-תרע\"א,ווילאק-תרע\"ד,ניו יורק-תרפ\"ב"},{"i":31917,"n":"מרולי, יוסף הקראי מקושטא","b":"מראשי עדת הקראים בקושטא-ת'."},{"i":31918,"n":"מרומי, אברהם מאיטליה","f":"יחיאל מרומי","b":"מגדולי איטליה,ראש ישיבה ברומי-ד'תת\"מ"},{"i":31919,"n":"מרומי, דניאל מאיטליה","f":"יחיאל","b":"מחכמי איטליה, ראש ישיבה רומא יחד עם אחיו ר' נתן בעל \"הערוך\"-ד'תת\"ל, פוסק, חיבר פירוש לסדר זרעים"},{"i":31920,"n":"מרון, אברהם","f":"יוסף","b":"חיבר הלכות שו\"ב-ש' - בכת\"י."},{"i":31921,"n":"מרוסא, משה מטריפולי","b":"רב בטריפולי, חתם על תעודה בענין אברהם קרדוזו השבתאי, ונזכר בכתב העת \"עאדא\" 23. מכונה גם משה ב\"ר ברוסא."},{"i":31922,"n":"מרוקו - משפחות שאבד זכרם"},{"i":31923,"n":"מרזוק, חננאל סלאמייה מירושלים","dt":"תקט - ז חשון","dp":"ירושלים","b":"מחכמי ירושלים."},{"i":31924,"n":"מרזוק, מנצור מחלב וירושלים","k":"בעל בן פדהצור","dt":"תקמד - ג סיון","dp":"ירושלים","b":"מחכמי ארם צובא, עלה לירושלים והיה מלומדי \"בית יעקב פיררה\", אצל הרבנים לבית מזרחי בעלי פרי הארץ ופרי האדמה. בשנת תקמב חתם על תקנת העזבונות, היה מראשי \"בית אל\". דיין בירושלים אצל מהרי\"ט אלגזי. תלמידו ר מרדכי נבון שכתב הקדמה לספר רבו. חתם עם חבריו ר רפאל יוסף בן רובי, הרשש, ר אליהו צבי, ור חיים נסים הכהן. היה מעורב במחלוקת בקהלת אר\"ץ - בין ר\"ש לניאדו ור יהודה קצין ופסק כדעת ר יהודה קצין. חיבר עוד \"קרבן אליצור\", \"צור תעודה\", ועוד. י\"א שנפטר תקמט.","bk":[["קרבן אליצור",""]]},{"i":31925,"n":"מרזוק, סעדיה (מסעוד) מחלב","bp":"ארם צובא?","dt":"תקלג - כ אייר","dp":"ירושלים","b":"מחכמי ארם צובא, עלה לירושלים וישב בישיבת \"בית יעקב פיררה\", למד אצל ר ישראל מזרחי בעל \"פרי הארץ\" ואחיו ר נסים בעל \"אדמת קודש\". תלמידו היה ר בנימין מרדכי נבון. היה סבו של ר סעדיה בנבנשתי. חלק מחדושיו נדפסו בספרי אחיו ר מנצור ובהם \"פן פדהצור\" ועוד. מתלמידיו ר בנימין מרדכי נבון מירושלים. חיבר חדושים בכת\"י."},{"i":31926,"n":"מרזל, אברהם מסכודניצה","b":"מחכמי סכודניצה-תרפה."},{"i":31927,"n":"מרטון, דב בר מניו יורק","f":"מנחם מועליאטין","k":"בעל משיב נפש","bt":"תרסט","bp":"ועליאטין","dt":"תשנא - ז חשון","b":"תלמיד הדעת סופר, ור יוסף צבי דושינסקי. מחכמי חוסט-תרפו, עבר לאמריקה וכיהן כרב בניו יורק, סן פרנציסקו, ניו יורק-תשיג."},{"i":31928,"n":"מרטון, מרדכי צבי מסט מארטון","f":"משה מצעהלים","bt":"תרכד","bp":"צעהלים","dt":"תרעג - ה חשון","b":"תלמיד השב\"ס. חתן ר דב בער דושינסקי מנאמעסטא (=נאווא-מעסטא). רב בקאוועגרעש (=קאוואגו-ערש)-תרנא, דיטשא-סט מארטון-תרנד על מקום ר זאב רוזנבליט בעל \"מלחמת חובה\", וחתנו ר יחיאל יוסף קרויס על מקומו אחריו."},{"i":31929,"n":"מרטון, משה משטיינמאנגר","b":"מחכמי צעהלים, שטיינמאנגר. בנו ר מרדכי צבי הכהן מדיטשא-סנט מרטון-תרכד."},{"i":31930,"n":"מרידיק, חיים יצחק מסנוק","k":"בעל מצת מצוה","b":"רב בסנוק, פשמישל, למברג. חיבר \"מצת מצוה\" למברג תרלב, ועוד. ?? לא באוצר ??"},{"i":31931,"n":"מרידך, משה אברהם מבבל","dt":"תשי","b":"תלמיד ר שמעון אגסי. רב ושו\"ב בבבל, רב בעמארה."},{"i":31932,"n":"מרידך, משה מבבל","f":"אברהם","dt":"תשח","b":"שו\"ב ודרשן בבבל. תלמיד ר שמעון אגסי."},{"i":31933,"n":"מרייבסקי, אליעזר משה","b":"רב בחאראש-תרע\"ב"},{"i":31934,"n":"מרייו, משה מאיטליה","b":"רב באיטליה בזמן מהר\"ן טרבוש, נזכר בחיד\"א."},{"i":31935,"n":"מרילס, אברהם יצחק","f":"ישראל אריה מירוסלב","k":"אדמור מליזנסק","b":"כיהן כאדמור מליזנסק בניו יורק"},{"i":31936,"n":"מרילס, אברהם משה מליטוביסק","f":"יעקב קופיל מליטוביסק","b":"נספה בשואה עם משפחתו."},{"i":31937,"n":"מרילס, אליעזר זאב מהרצה","f":"חיים","k":"רבין","bt":"תקס","dt":"תריב","b":"רב בהרצה, בוצצי. חתן נכדת ר לוי יצחק מברדיטשוב."},{"i":31938,"n":"מרילס, אלעזר מירוסלב וברלין","f":"שמעון השני מירוסלב","k":"אדמור מירוסלב","dt":"תש..","b":"חתן ר חיים מאיר יחיאל מדומברובא, ובזיוו\"ש חתן ר אשר ישעיה מזולקוא וקשנוב. כיהן בברלין כאדמור מירוסלב, גורש לירוסלב ונספה בשואה."},{"i":31939,"n":"מרילס, אשר מציריך","f":"אליעזר זאב מבוצאץ","b":"בן האדמור מבוצאץ. רב בציריך."},{"i":31940,"n":"מרילס, בונם מנחם מנדל מירוסלב","f":"שמעון מירוסלב","k":"אדמור מירוסלב","bt":"תקע","dt":"תרמח - אלול","b":"חתן ר אברהם דוד מבוצאץ נכדת ה\"דעת קדושים\". רב ואדמור בירוסלב והיה במחלוקת כנגד המשכילים שם. בנו ר שמעון השני על מקומו אחריו כאדמור."},{"i":31941,"n":"מרילס, דוד מירוסלב","f":"שמעון השני מירוסלב","k":"אדמור מירוסלב","bt":"תרלה","dt":"תרצז","b":"רב ואדמור בירוסלב, בנו ר בנימין על מקומו אחריו. חתן רבו ר מנחם מנדל אייכנשטין מזורובנא."},{"i":31942,"n":"מרילס, חיים מברלין","f":"אליעזר זאב מבוצאץ","dt":"תשד - ב תמוז","b":"בן האדמור מבוצאץ. שו\"ב בברלין. עלה לארץ בסוף ימיו."},{"i":31943,"n":"מרילס, יוסף אהרן מבוצאץ","f":"אליעזר זאב מהרצה","k":"אדמור מבוצאץ","bt":"תקצה","bp":"הרצה","dt":"תרעג","dp":"בורדוזען","b":"חתן ר ר לוי יצחק פרנקל מבוקרשט נכדת ר לוי יצחק מברדיטשוב והבעשט. רב ואדמור בבוצצי על מקום אביו (והיה שם מחלוקת עם ר בצלאל דב וייסבך מקוזובה - והדפיסו ספר \"קול יעקב\" להגן עליו כנגד \"מאמר בצדק\" כנגדו). רב בדורוהי. בנו ר אליעזר זאב על מקומו אחריו בבוצצי. חיבר \"יד יוסף\" קלוזש תרפו."},{"i":31944,"n":"מרילס, יעקב קופל מליטוביסק","f":"נפתלי מליטוביסק","bt":"תריג","dt":"תרפו - ב תשרי","b":"נכד ר שמעון מירוסלב. רב בליטובסק-תרע על מקום אביו. חתן ר יוסף ברנדויין מסאהל."},{"i":31945,"n":"מרילס, יצחק מאיר מבוקרשט","f":"מנשה מבוצאץ","k":"אדמור מבוצאץ בבוקרשט","bt":"תרסג","bp":"בוצאץ","dt":"תשמז","dp":"בוקרשט - ירושלים","b":"חתן דודו ר שמשון אפרים גוטסמן מלשקוביץ-סניטין (שושלת זבאריז). תלמיד ישיבת דעש. רב במיהלן, דורוהוי, בוקרשט. ניצל מהשואה. ואחריה ר בבקוי על מקום רב\"ז שפרן. אחרון רבני רומניה שלא שינה מאום מהנהגת אבותיו - תחת שלטון הקומוניסטים. מבניו: ר מנחם מנדל מפריז בעל |תפארת מנחם\", ר שמעון אב\"ד ליפקאן-בסרביה ואנטורפן, ר סנדר ליפא מחיפה."},{"i":31946,"n":"מרילס, יצחק מרופשיץ","f":"שמעון מירוסלב","bt":"תקעה","dt":"תרנב","b":"חתן ר מנשה רובין מרופשיץ-תרן. רב ברופשיץ-תרכא על מקום חותנו. בנו ר מנחם מנדל על מקומו אחריו ברופשיץ."},{"i":31947,"n":"מרילס, ישראל אריה מירוסלב","f":"שמעון מירוסלב","k":"אדמור מירוסלב","dt":"תש..","b":"חזר מוינה-תרעו לירוסלב. חתן ר טודרוס רוקח מנמירוב, בזיוו\"ש חתן ר אברהם שטיקלר ממוסט, ובזיוו\"ש חתן ר אשר ישעיה רובין האדמור מזולקוא בקשנוב. כיהן כאדמור בירוסלב."},{"i":31948,"n":"מרילס, מאיר מסערט","f":"אליעזר זאב מבוצאץ","b":"בן האדמור מבוצאץ. רב בסערט."},{"i":31949,"n":"מרילס, מנחם מירוסלב","f":"דוד מירוסלב","k":"אדמור מירוסלב","dt":"תש..","b":"נתמנה לאדמור בירוסלב בהיותו בחור."},{"i":31950,"n":"מרילס, מנחם מנדל מפריז","f":"יצחק מאיר מבוקרשט","k":"בעל תפארת מנחם","dt":"תשכו - ל סיון","dp":"אנטורפן","b":"נכד האדמור ר מנשה מבוצאץ, ונכד ר שמעון מירוסלב. רב בפריס בקהלת סלובקיה.."},{"i":31951,"n":"מרילס, מנחם מנדל מרופשיץ","f":"יצחק מרופשיץ","bt":"תר","dt":"תרף","b":"חתן ר מאיר יהודה שפירא מדינוב נכד ה\"בני ישכר\". רב בדובצק, רופשיץ על מקום אביו. בנו ר מנשה על מקומו בדובצק וברופשיץ."},{"i":31952,"n":"מרילס, מנשה מבוצאץ","f":"אליעזר זאב מבוצאץ","b":"חתן ר חיים מאיר יחיאל מדומברובא (שושלת רופשיץ). מבניו: ר יצחק מאיר מבוקרשט."},{"i":31953,"n":"מרילס, מנשה מרופשיץ","f":"מנחם מנדל מרופשיץ","bt":"תרכד","dt":"תרצג","b":"רב בדובצק-תרנב על מקום אביו, וברופשיץ על מקום אביו, וחתנו ר יצחק ליברמן על מקומו אחריו. מחסידי בלז. חתן ר יחיאל השל מקריליביץ, ובזיוו\"ש חתן ר אשר ישעיה רובין האדמור מזולקוא בקשנוב, ובזיוו\"ש שלישי חתן ר שמואל אהרן פלאם מקורטשין. חתנו גם - האדמור ר חיים הלברשטם מטשחוב."},{"i":31954,"n":"מרילס, נפתלי מליטוביסק","f":"שמעון מירוסלב","k":"בעל אילה שלוחה","bt":"תקפח","dt":"תרן - כט ניסן","b":"חתן ר ישכר בריש מליטוביסק, ובזיוו\"ש חתן ר ישעיה זלמן קלך מאיסטריק. מחסידי בלז וזידיטשוב. רב בליטוביסק-תרם, בנו ר יעקב קופל על מקומו אחריו. סירב לאדמורות אך הסכים לקת פתקאות ולתיתם על ציון אביו. חיבר \"אילה שלוחה\" ברוקלין תשל."},{"i":31955,"n":"מרילס, שלום מבורדוזן","f":"אליעזר זאב מבוצאץ","b":"בן האדמור מבוצאץ. רב בבורדוזן."},{"i":31956,"n":"מרילס, שמעון השני מירוסלב","f":"בונם מנחם מנדל","k":"אדמור מירוסלב","bt":"תריא","dt":"תרעה - טו שבט","dp":"וינה","b":"נכדו של ר שמעון מירוסלב (הראשון). חתן ר שמחה שפירא מלנצהוט. רב ואדמור בירוסלב על מקום אביו, במלחה\"ע ה-I ברח לוינה."},{"i":31957,"n":"מרילס, שמעון מירוסלב","f":"ישראל ליב אילבוים","k":"אדמור מירוסלב","bt":"תקיט","dt":"תרי - טו תשרי","b":"נכד ר יעקב קופיל מליקובא. מקורב לגדולי האדמורים ובעיקר לר אלימלך מליזנסק והחוזה מלובלין. מחכמי ירוסלב, שהחל לכהן כאדמור מירוסלב. בנו ר בונם מנחם מנדל על מקומו אחריו. חיבר \"תורת שמעון\" יאראסלויא תרסח."},{"i":31958,"n":"מרילס, שמעון מליפקאן-בסרביה","f":"יצחק מאיר מבוקרשט","b":"נכד האדמור ר מנשה מבוצאץ. אב\"ד לפיקאן-בסרביה, עבר לאנטורפן."},{"i":31959,"n":"מרילס-פרנקל, אליעזר זאב מבוצאץ","f":"יוסף אהרן מבוצאץ","k":"אדמור מבוצאץ","bt":"תריג","dt":"תשו - כה טבת","dp":"בוטושאן","b":"תלמיד ר ה\"דברי חיים\" מצאנז. רב בפשצלוב, רב ואדמור בבוצאץ-תרעג על מקום אביו, פשצלוב. חתן ר יעקב מרדכי ליברמן מטופורוב-חתן ר יצחק מרילס מרופשיץ (שושלת ירוסלב) ואימץ את שם משפחת אשתו. מבניו: ר חיים מברלין, ר אשר מציריך, ר מאיר מסערט, ר שלום מבורדוזען."},{"i":31960,"n":"מרים הנביאה ע\"ה","dt":"י ניסן"},{"i":31961,"n":"מרינג, חיים יוסף הלוי מניישטט-","b":"מראשי קהילת ניישטט-שירווינט-ליטא. פרסם מכתב ברכה מטעם הקהילה ב\"בית ועד לחכמים\" - לונדון תרסב."},{"i":31962,"n":"מריני, אברהם יצחק","b":"רב באליסנדרא-ת\"צ"},{"i":31963,"n":"מריני, יוסף מוירונה","f":"שמעון","k":"בעל כתונת יוסף","bt":"תקלט","bp":"וירונה","b":"מחכמי איטליה, מחבורת הרמח\"ל, רב בוירונה. חיבר \"כתונת יוסף\"."},{"i":31964,"n":"מריני, יצחק מפדובה","f":"שלמה","b":"רב בוירונה. מהר\"י בסאן חיבר שיר לכבוד חתונתו - נדפס ב\"לשון למודים\". אביו של ר שבתי חיים מריני ממנטובה."},{"i":31965,"n":"מריני, יצחק מפדובה","f":"שבתי","k":"בעל עיני אברהם","b":"מחכמי פדובה, מבני החבורה של הרמח\"ל."},{"i":31966,"n":"מריני, שבתי אהרן חיים מפדובה","f":"יצחק בן שלמה","dt":"תקח - יט אייר","b":"נכדו של ר שלמה מריני מפדובה. תלמיד הרב יחכ\"ם. רב בפדובה על מקום רבו. חיבר שירים דרשות ומאמרים - רובם בכת\"י. מתורתו ב\"שמש צדקה\". בנו - ר אברהם צבי הלוי."},{"i":31967,"n":"מריני, שבתי אהרן חיים מפדובה-ב","dt":"תקסט - ג אדר","b":"רב בפדובה. נספד מאת ר מרדכי שמואל גירונדי."},{"i":31968,"n":"מריני, שבתי מפדובה","f":"יצחק","dt":"תמה - פורים","b":"תלמיד ר יעקב חזק. רב בפדובה ומשורר. בנו - ר אברהם צבי הלוי."},{"i":31969,"n":"מריני, שלמה מפדובה","f":"יצחק","k":"בעל תיקון עולם","dt":"תל - ערח אייר","b":"רב בפדובה, ותיקן תקנות בעירו. אחיו ר שבתי הרופא מפדובה. ניצל מהמגפה-שצא בזמן הרב קאטאלאנו. חיבר \"תיקון עולם\" וירונה תיב. תלמידו ר יצחק חיים הכהן מהחזנים - סיפר בשבחו בכת\"י - ומספר שהרביץ תורה בחברת ידידו ר ברוך לוצטו."},{"i":31970,"n":"מריני, שלמה מפדובה","f":"שבתי","b":"רב בפדובה. בנו (או נכדו) ר שבתי אהרן חיים ממריני מפדובה."},{"i":31971,"n":"מריק, אהרן מטשיטש","b":"פרסם מאמרים ב\"אהל תורה\" - קראקא תרפח."},{"i":31972,"n":"מריקא, ישראל צבי הכהן מירושלים","f":"שמשון מרדכי","dt":"תרלז","dp":"ירושלים","b":"רב בריקאווה, עלה לירושלים."},{"i":31973,"n":"מרמורק, אלכסנדר מפאריז","bt":"1865","bp":"גליציה","b":"למד בוינה והיה מחברי \"קדימה\" הציונית. רופא במכון פאסטר בפריז ופיתח תרופה חשובה. פעיל בתנועה הציונית וממקורבי הרצל."},{"i":31974,"n":"מרמורשטין, אברהם מוינקוועצי","f":"יהודה אריה ליב מסמני","b":"רב בוינקוועצי, לונדון. פרסם מאמרים ב\"אוצר החיים\" - דעווא תרפה."},{"i":31975,"n":"מרמורשטין, יהודה אריה ליב","f":"ברוך מבהיאר","bp":"ביהאר-נאדי-באיאם","dt":"תרצא - כ כסלו","dp":"סעמניץ","b":"תלמיד השב\"ס. חתן ר חיים מאיר רוזנפלד ממישקולץ, ועבר לשם. רב בשילדברג-תרמד, אורמין-תרמו, סעמניץ-תרמח."},{"i":31976,"n":"מרמורשטין, יוסף זאב מטור-טרבש","b":"דיין בטור-טרבש ליד האלמין-[תרס] עד [תרעט]"},{"i":31977,"n":"מרמורשטין, ניסן יהודה מטארנליא","b":"חתן ר יצחק גליק מסנט-פעטר. חתנו - ר שמעון טיטלבוים מטארנליא. מחכמי טארנאליא."},{"i":31978,"n":"מרמורשטין, שאול נייפעסט","f":"אפרים יהודה הלוי","bt":"תריז","dt":"תרפא - ניסן","b":"תלמיד הכת\"ס. מחכמי נייפעסט. חתנו ר אביגדור קצבורג עורך \"נטעי בחורים\"."},{"i":31979,"n":"מרמינסקי, יהושע משה","dt":"תשכא","b":"רב בניו יורק"},{"i":31980,"n":"מרמלשטין, יהודה ישכר מבטרטש","f":"צבי מסוואליווע","k":"בעל חוקי חיים-תרפה","b":"שו\"ב ורב בבאטארטש-ליד האלמין. חברו של ר אהרן גד כץ מנימוז'א. נספה בשואה."},{"i":31981,"n":"מרמלשטין, יחיאל סגל","b":"בהיותו בחור פרסם מאמרים ב\"המעין\" - בודפשט תשז (לאחר השואה!)."},{"i":31982,"n":"מרמן, מנחם מנדל מחאלץ","f":"משה ירחמיאל","bt":"תרכא","b":"תלמיד ר דובער ליפשיץ בישיבת ויעטקא. רב בחאלץ-פלך מוהילוב-תרנב. נסמך מאת: האדמור מרעציצע, ר משה דב חאווין מהומל."},{"i":31983,"n":"מרמר, קלמן צבי (קרל)","k":"בעל דוד עדעלשטאט","bt":"1877","bp":"מאישיגולה","dt":"1956","b":"חבר בתנועה הסוציאליסטית. למד באונ' ברן ופרייבורג. הצטרף לתנועה הציונית וכיהן כציר בקונגרס הציוני. עבר לתנועה הקומוניסטית והיה מעורכי ה\"נייע וועלט\" של היבסקציה, ועוד. עבר לרוסיה-1933, וחזר לארה\"ב אחרי 3 שנים. חיבר גם \"קלאסנקאמפן אין אלטערטום, ועוד. ?? לא באוצר ??"},{"i":31984,"n":"מרמרשטיין, יעקב דב מסעק","b":"תלמיד ר אשר אנשל יונגרייז בעל מנחת אשר."},{"i":31985,"n":"מרמרשטין, יוסף זאב מטורטערבעש","b":"דומ\"צ בטורטערעבעש-תרע\"ד"},{"i":31986,"n":"מרני, דוד מחברון","b":"בשנת שעו חתם על מכתב בקשה של קהילת חברון"},{"i":31987,"n":"מרנינו, יוסף מקושטא","b":"רב בקושטא-ד'תתקלו, נזכר אצל ר בנימין מטודילא."},{"i":31988,"n":"מרס, יוסף","b":"חיבר פירוש על הברייתא - מובא ב\"וזאת ליהודה\"."},{"i":31989,"n":"מרעלי, זרחיה מאלגיר","f":"יהודה","dt":"תקלב","dp":"אלג'יר","b":"ראש ישיבה, מרביץ תורה ואב\"ד באלג'יר ור יעקב בן נאיים על מקומו אחריו, פייטן, מליץ."},{"i":31990,"n":"מרעלי, יעקב מאלגיר","f":"זרחיה מאלגיר","dt":"תקסו","b":"רב ודיין באלגיר ומלמד תורה, גבאי ארץ ישראל. נרדף ע\"י אנשי הנגיד דוד דוראן ורכושו הוחרם."},{"i":31991,"n":"מרעלי, שמעון יחיאל מאלגיר וצרפ","f":"יצחק","bt":"תרסט","dt":"תשמד","b":"רב בצרפת מטעם הקונסיסטואר."},{"i":31992,"n":"מרפורק, אנשיל","b":"מגדולי התורה באשכנז-ק\"פ"},{"i":31993,"n":"מרפורק, שמריה","b":"גיסו של ר דוד לוריא. נזכר ב\"עולם הפוך\" לר\"א קאטאלאנו."},{"i":31994,"n":"מרפלד, אשר זליג מפרוכניק","f":"צבי לוי","bt":"תרלה","dt":"תשג","b":"נסמך מאת ר בנימין וייס מטשרנוביץ, ר משה רפפורט מליזנסק, ר יצחק אליעזר גרינברג מגלינא. רב בפרוכניק-תרסו."},{"i":31995,"n":"מרץ, חיים יהודה ממונקטש","dt":"תשד","b":"דומ\"צ במונקאטש"},{"i":31996,"n":"מרץ, חיים מניו יורק","f":"יחזקאל מקאשוי נ\"י","b":"אדמור מקאשוי בניו יורק על מקום אביו."},{"i":31997,"n":"מרץ, יואל זוסמן מקאשוי","k":"בעל הר יראה","b":"חתן ר יעקב פרנקפורטר האדמור מקאשוי. מחכמי קאשוי, עבר לניו יורק. אבי האדמור ר יחזקאל שרגא מרץ מברוקלין."},{"i":31998,"n":"מרץ, יחזקאל שרגא מברוקלין","f":"יואל זוסמן מקאשוי","k":"אדמור מקאשוי-תפארת י","bt":"תרסח","bp":"קאשוי","dt":"תשל-ב - ט ניסן","dp":"ניו יורק","b":"נכד ר יעקב פרנקפורטר מקאשוי, וגדל אצלו. תלמיד ישיבת ר מנחם ברודי מקאליב בעל \"באר מנחם\", ור יואל טיטלבוים האדמור מסטמר. חתן ר חיים-נכד ר נפתלי הרץ מראצפרד. אדמור מקאשוי בניו יורק ובנו ר חיים על מקומו אחריו. ניצל מהשואה ואחריה התישב בבודפשט, ברח מהקומוניסטים לוינה, עבר לארה\"ב-תשיז והתישב בניו יורק, וכיהן כרב, ובנו ר חיים על מקומו אחריו. חיבר \"תפארת יחזקאל\"."},{"i":31999,"n":"מרציאנו - משפחה","b":"משפחה במרוקו, מוצאה מהעיר קצבה למכסן."},{"i":32000,"n":"מרציאנו, אברהם","f":"שלמה","bp":"דבדו או ירושלים","dt":"תרצו","dp":"ירושלים","b":"עלה לא\"י-תרכ\"ה, רב ביוון, שכם. שד\"ר של ירושלים למערב"},{"i":32001,"n":"מרציאנו, אברהם","dp":"תאזא","b":"רב ומו\"ץ בתאזא-תרע\"ה"},{"i":32002,"n":"מרציאנו, אברהם ממרוקו ואלגיר","f":"יוסף","bt":"תרט","bp":"דבדו","dt":"תרפד","dp":"דבדו","b":"תלמיד ר יעקב אבוחצירא בתאפילאלית. מחכמי דברו-מרוקו. רב באלכיחל-אלגיר, עין לארבע-ליד עין תמושנת, דיין בדברו."},{"i":32003,"n":"מרציאנו, דוד","f":"יעקב","dt":"תשיד","dp":"מיסור","b":"מרביץ תורה בדבדו(מרוקו)"},{"i":32004,"n":"מרציאנו, דוד מרגנט ומיסור","f":"יצחק","dt":"תשטו - ה אדר","b":"רב ברגנט, מיסור"},{"i":32005,"n":"מרציאנו, יצחק מדברו-מרוקו","bt":"של","dt":"תי","b":"רב בדברו-מרוקו. הניח דרשות וחדושים בכת\"י."},{"i":32006,"n":"מרציאנו, מאיר מרדכי מאלגיר","f":"שמואל מדברו","k":"בעל בית מאיר - תשלח","bt":"תרף","bp":"דברו-מרוקו","b":"רב בארמשי(=מונטאנייאק)-אלגיר, בורג' בו ערירג-אלגיר, תביסא-אלגיר. עבר לצרפת-תשכב וכיהן כרב במאסי-אנטוני-ליד פאריס, עלה לירושלים-תשם. חיבר \"בית מאיר\" ירושלים תשלח, ועוד."},{"i":32007,"n":"מרציאנו, מימון מדבדו-מרוקו","bt":"תמ","dt":"תקן","b":"דיין בדבדו-מרוקו. אביו של ר שלמה."},{"i":32008,"n":"מרציאנו, משה ממרוקו","f":"יוסף","dt":"תרסז","dp":"מרוקו","b":"למד בדברו-מרוקו, ר יעקב אביחצירא. נגיד מחכמי צפרו-תרם. היה בקשר עם השליח הצרפתי - דה פוקו-תרמד, תמך במלך מרוקו כנגד המורד בוחמארה ונלקח בשבי ע\"י המורדים."},{"i":32009,"n":"מרציאנו, משה ממרוקו","k":"בעל מורשת משה","bt":"תרעז","bp":"דברו-מרוקו","dt":"תשנו - כג טבת","b":"דיין בקזבלקנה, ראש ישיבה באוזדא-תשד, עלה לארץ וכיהן כרב בלוד."},{"i":32010,"n":"מרציאנו, משה מרדכי מאלגיר","f":"שמואל","b":"שו\"ב בבורג' בועריריג'-אלגיר-תרצט."},{"i":32011,"n":"מרציאנו, שלמה ממרודו","f":"מימון","bt":"[תף]","dt":"תקם - בערך","b":"רב בדברו-מרוקו ובעל מופתים, ורבים עולים על קברו."},{"i":32012,"n":"מרציאנו, שלמה ממרוקו","f":"יעקב בן דוד","bt":"[תק]","dt":"תקס - בערך","b":"רב במרוקו-תקלה."},{"i":32013,"n":"מרציאנו, שמואל ממרוקו","f":"אליהו","bt":"תרנא","bp":"דברו-מרוקו","dt":"תשלה - יג ניסן","dp":"ירושלים","b":"תלמיד ר חיים ן שושן, ור שלמה הכהן צבאן. רב וראש ישיבה בדברו-תרף, וסופר ביה\"ד בדברו-תשו. עלה לירושלים. חיבר חדושים בכת\"י. כולל אברכים ע\"ש בשם \"מדרש שמואל\" בירושלים."},{"i":32014,"n":"מרצקי, אליעזר מירעמיץ","f":"יצחק","k":"בעל דברי אליעזר-כת\"י","bt":"תרכב","bp":"פלך וילנא","b":"תלמיד ישיבת רמיילע(=מיילעס) בוילנא, איישישוק, כולל קובנא. חתן ר חיים סטרלצסקי מאיישישוק. רב בירמניץ(=ירעמיץ)-פלך מינסק-תרנד. נסמך מאת: ר יצחק אלחנן מקובנא, ר ירוחם יהודה ליב הגדול ממינסק."},{"i":32015,"n":"מרצר, דוד","b":"רב בווידז-ת\"ר"},{"i":32016,"n":"מרק בריט, אליעזר מנחם מנלי","k":"בעל לקוטי מן","b":"תשובה ממנו בשו\"ת מהרמא\"י - משנת ש\"י, להגן על הרב מ\"ן מהביקורת כנגדו על ענין גט."},{"i":32017,"n":"מרק, אברהם יעקב מצ'רנוביץ","k":"בעל זכותנו על הכותל","bt":"תרמד","bp":"איסטריק","dt":"תשא","b":"נכד ר אפרים מיגולניצה ואצלו גדל. בעל תואר דוקטור מאוני' וינא. רב במחנה פליטים בזמן מלחמת העולם הראשונה ועוזר לרב בלינץ, רב בביאלא-ביליץ-תרעח, טשרנוביץ-תרפו. נשיא המזרחי בעירו. נספה בשואה. חיבר \"זכותנו על הכותל\" בחוברת \"קול יעקב\" בגרמנית - תרפט."},{"i":32018,"n":"מרק, יהודה מפלונגיאן","bp":"פלונגיאן","dt":"תרנז - יא אייר","dp":"פלונגיאן","b":"תלמיד ר אליהו שיק, ר משה יצחק. רב בפלונגיאן, היגר לארה\"ב וכיהן כרב בריימאן, חזר לפלונגיאן. מתלמידיו - ר יחזקאל ליפשיץ מקאליש. בנו - ר יעקב."},{"i":32019,"n":"מרק, יודל מליבאוי","bt":"1897","bp":"פולנגן","b":"למד היסטוריה בקורסים ללימודי יהדות של הברון גינצבורג בפטרבורג. חבר ועד הקהילה בליבאו. ממיסדי הגימנסיה האידית בוילקומיר ומנהלה. מזכיר הועד הלאומי היהודי בליטא. עבר ללטביה-1927 והיה מנהל ציש\"א. עורך \"פאלקסבלאט\" בקובנא. היגר לארה\"ב-1936 והיה פעיל בייוו\"א. מפקח בתי הספר של \"ארבייטער רינג\". חיבר ספר דקדוק באידיש. מעורכי המילון האקדמי באידיש. תרגם ספרים לאידיש וחיבר ספרי ילדים. מגדולי הבלשנים באידיש."},{"i":32020,"n":"מרק, יעקב מליבאוי(=ליבאו)","f":"יהודה מפולנגאן","k":"בעל גדולים פון אונזע","bt":"1858","bp":"פולנגן(=פלונגיאן)","dt":"1929","b":"תלמיד ישיבות ליטא, ר מאיר אטלס משאוולי. פרסם שיטה חדשה בהוראת הנהלת חשבונות בעברית. פרסם מאמרים ב\"הלבנון\", ועוד. עסקן ציוני בליבאו. חיבר ספר על רבנים ומשכילים בני דורו \"גדולים פון אונזער צייט\". פרסם מאמרים ב\"הלבנון\", \"המליץ\", \"הצפירה\", ועוד."},{"i":32021,"n":"מרק, מנחם מנדל מקראקא","dt":"תשג","b":"מחכמי קראקא. השתתף בשבועון \"די אידישע שטימע\"-תרצא ופרסם בעוד כתבי עת. נספה בשואה."},{"i":32022,"n":"מרקבריט, אליעזר מנחם מנלי","k":"בעל לקוטי מן","b":"חתן ר ישראל חריף מזסלב ואוסטרהא. רב בברסיטישקע(=ברסטיצקי), דובנא. (ויש אומרים כי שמו שאול)."},{"i":32023,"n":"מרקבריטר, שמעון מפרשבורג","b":"דיין בפרשבורג-תקי בבית דינו של ר משה לבוב."},{"i":32024,"n":"מרקבריטר, שמעון צבי","dt":"תרז","b":"רב בדרזניץ,אייזנשטט,לאשברין"},{"i":32025,"n":"מרקוביץ, אהרן","b":"סוכן של המלך ולדיסלב הרביעי-תחילת המאה ה-17. הצאר מיכאל פיודורוביץ סירב להתיר לו לעסוק במסחר במוסקבה - כי \"אין ליהודים ברוסיה רשות לעסוק במסחר ולא לנוצרים לבוא במגע עם יהודים\" (תשובת הצאר למלך ולדיסלב)."},{"i":32026,"n":"מרקוביץ, זלמן טוביה ש'","f":"משה","bt":"תרמח","bp":"ראסיין","dt":"תשג","dp":"קובנא","b":"תלמיד ישיבת טלז, וולוזין. חתן ר יוסף יוזל פרסקי מוולוזין. רבה של אנטאליפט ואחריו ר יהודה לוין - רבה האחרון. נספה בשואה עם בנו ר חיים שמשון - נהרגו במצודה ה-9 בקובנא."},{"i":32027,"n":"מרקוביץ, חיים","b":"פרסם מאמרים ב\"כנסת ישראל\" - סלובודקה-ויליאמפולי תרצח - כתב עת תלמידי \"כנסת ישראל\" בסלובודקה."},{"i":32028,"n":"מרקוביץ, חיים שמשון","f":"זלמן טוביה","k":"בעל דבר החיים","dt":"תשג","dp":"קובנא","b":"נכד ר משה בעל \"שם הגדולים השלישי\". הצטיין בזכרון מופלא כזקנו. נספה בשואה עם אביו במצודה התשיעית בקובנא."},{"i":32029,"n":"מרקוביץ, יעקב ליב מוארשא","b":"תלמיד בישיבת אוטואצק. פרסם מאמרים ב\"התמים\" - וארשא תרצה - קובץ חסידי חב\"ד."},{"i":32030,"n":"מרקוביץ, יצחק מטשקאני","b":"דומ\"צ במארצאלטא, טשאקאני-תרסא. פרסם מאמרים ב\"דבר בעתו\" - פאקש תרסט, \"הנשר\" - טירנוי תרצג-תשד."},{"i":32031,"n":"מרקוביץ, שמואל","dt":"תשג","b":"רב בטורעץ"},{"i":32032,"n":"מרקובסקי, אברהם","f":"שרגא פיבש","bt":"תרלא","b":"רב בקניאשי(=קניאשזיא)-פודוליה-תרסב."},{"i":32033,"n":"מרקון, חיים ליב מוילנא","f":"מאיר אברהם","bt":"1848","bp":"וילנא","dt":"1909","b":"עזר לרש\"י פין בהוצאת \"הכרמל\", ופרסם שם מאמרים. חיבר ביאור על 15 שירי המעלות בתהלים. עסקן ציבור, ממנהלי ספריית שטרשון. בעל ספריה חשובה וגדולה."},{"i":32034,"n":"מרקוס, אברהם ישראל מקראקא","b":"מחכמי קראקא - ממשתתפי \"אהל מועד\"."},{"i":32035,"n":"מרקוס, אברהם שלום מוולדזירז","f":"אהרן הלוי","bt":"תקצח","b":"רב בוולדזירז(ליד דולינא)-תרלח."},{"i":32036,"n":"מרקוס, אהרן מקאשוי","dt":"תשד","b":"רב בקאשוי"},{"i":32037,"n":"מרקוס, אהרן מקראקא","f":"מאיר","k":"בעל קסת הסופר","bt":"תרג","bp":"המבורג","dt":"תרעו - ל אד\"א","dp":"פפד\"מ","b":"שלט בשפות רבות ובמדע. תלמיד ר ברוך יצחק ליפשיץ בן התפא\"י. התקרב לחסידות והפך למקורב לגדולי האדמורים. מחכמי קראקא, זגירז. סירב לרבנות. סייע לרב מאז\"ה בזמן משפט בייליס. חיבר \"קסת הסופר\" קראקא תרעב, ועוד ספרים רבים בגרמנית."},{"i":32038,"n":"מרקוס, אריה ליב נאמן מירושלים","f":"ירחמיאל","dt":"תרלז - ה אדר","dp":"ירושלים","b":"חתן ר שלמה זלמן שפירא מירושלים. נאמן כולל הפרושים בירושלים, ומראשי הקהלה. חתם עם ר ישראל משקלוב-תקצא. פעל בשנת תריד לבנית ביהמ\"ד \"שערי ציון\" יחד עם ר מרדכי צורף. יצר קשר עם הלורד גאפיור מאנגליה ובקש את עזרתו בחצר השולטן בענין בית הכנסת החורבה. אחיו - ר מרדכי פינס מירושלים."},{"i":32039,"n":"מרקוס, בנימין מנדל מטיפליס","f":"יחזקאל מקורלנד","bt":"תרלה","bp":"נאווה-פולטאייקה","b":"חסיד חב\"ד, אביו הגיע מקורלנד למושבה חקלאית בפלך חרסון ושם נולד. תלמיד ר מאיר דב יעקבסון מנאווא-פאלטאייקא, תלמיד ישיבת רעזישצעוו בהשגחת ר צבי שליעז, ר צבי הירש מה-יפית באיישישוק, וואראנאווא (לשם עבר אחרי השריפה באיישישוק-תרנה). מו\"צ באודסה(=אדעס)-תרנד, יעוופאטאריע-פלך טבריא-תרסב, רב בטיפליס-תרע. נסמך מאת: ר יצחק אלחנן מקובנא, ר שלמה הכהן מוילנא, ר צבי הירש מה-יפית."},{"i":32040,"n":"מרקוס, ברוך מריטווא וחיפה","f":"מאיר פלק","k":"בעל אמרי ברוך","r":"ראש ישיבת בית המוסר בירושלם, ואחר כך רב דחיפה","bt":"תרל","bp":"ריטובה-ליטא","dt":"תשכא - יט סיון","dp":"חיפה","b":"תלמיד ישיבות קלם, סלובודקה. הגיע לארץ-תרנא בשליחות רבו ר שמחה זיסל זיו להקים בתי מוסר בארץ והיה חלוץ תנועת המוסר בארץ. ר\"מ ביפו, יסד וניהל עם ר חיים זוננפלד את ישיבת \"אור חדש\". עבר לחיפה-תרסו בה היו אז כ-50 משפחות יהודים וכיהן כרבה של חיפה כ-55 שנה. פרסם מאמרים ב\"אור תורה\" - ירושלים תרנז, \"קול תורה\" - ירושלים תרץ-תשז.","bk":[["אמרי ברוך - חידושי הלכות, תשובות ודרושים",""]]},{"i":32041,"n":"מרקוס, יוסף יעקב מבולטימור","b":"רב בזשידיק,בלטימור(ארה\"ב)-תרפ\"ג"},{"i":32042,"n":"מרקוס, יוסף מבאייה","b":"רב בבאייה בשנות תקל'."},{"i":32043,"n":"מרקוס, יצחק הלוי מארה\"ב","f":"יעקב","k":"בעל עולת יצחק - כת\"י","bt":"תריט","bp":"טלז","b":"תלמיד ר מאיר אטלס מקוברין וסלנט, למד עם פרושי שאוויל והיה מקורב לרי\"ז שטרן. היגר לארה\"ב וכיהן כרב יוצאי יאנוסטאוו בניו יורק-תרנה, יוטיקא, פורטלנד-מיין, ניו ברונזביק. נסמך מאת: ר מנחם מנדל זיו מטאוריג, ר אלעזר רבינוביץ ממינסק. פרסם מאמרים ב\"המגיד\", \"עברי אנכי\" - בשם \"יהלם\". מתורתו גם ב\"המאסף\" - ירושלים, פרסם מאמרים ב\"המאסף\" - ירושלים-אלכסנדריה תרנו-תרעג."},{"i":32044,"n":"מרקוס, יצחק מסמרגון","dt":"תשג","b":"רב בסמרגאן"},{"i":32045,"n":"מרקוס, ישעיה הכהן מבוסטון","b":"רב בקולומבוס-תרסה, שיקגו-תרסח, בוסטון-תרפד. חתנו - ר שמואל יאלוב מסירקוז-ארה\"ב."},{"i":32046,"n":"מרקוס, ישראל","f":"מאיר פאלק מרקוס","b":"דרשן,רב בשיקאגו"},{"i":32047,"n":"מרקוס, נפתלי הרץ","b":"פרסם מאמרים ב\"כנסת הגדולה\" - וארשא תרן."},{"i":32048,"n":"מרקוס, נתן מחלב","dt":"תרף - י תשרי","dp":"חלב","b":"רב בחלב, תשובה ממנו ב\"פה אליהו\" לר אליהו חמווי-תרנז, והיה ראש חברת \"צדקה ומרפא\" בחלב."},{"i":32049,"n":"מרקוס, שלמה מקראקא","f":"אהרן","k":"בעל פרי עץ הדר","b":"עבר להמבורג ועסק במסחר בספרים עתיקים. נספה בשואה. חיבר \"פרי עץ הדר\""},{"i":32050,"n":"מרקוס, שלמה צבי מארה\"ב","k":"בעל גרן שלמה","b":"רב בארה\"ב. חיבר \"גרן שלמה\" נ\"י תרעב."},{"i":32051,"n":"מרקוס, שמואל מדטנובה","b":"גביר מחכמי דטנובה. תומך בלומדי תורה."},{"i":32052,"n":"מרקוש, אברהם מפיליפופולי","b":"רב בפיליפופולי-שנות ה-ש'."},{"i":32053,"n":"מרקזון, אברהם יוסף מארה\"ב","b":"משכיל בניו יורק."},{"i":32054,"n":"מרקיל, מרדכי מאוסטרהא","f":"אליעזר לינקר","b":"גביר מחכמי אוסטרהא. חתן ר יעקב רפפורט בן ר חיים בעל מים חיים."},{"i":32055,"n":"מרקיל, מרדכי מנוברדוק","b":"רב בנוברדוק על מקום ר נפתלי הרץ ור יעקב צבי הירש על מקומו אחריו. פסק דין ממנו-תקנג."},{"i":32056,"n":"מרקילס, אהרן הכהן מוילנא","dt":"תרצג - לפני","b":"מו\"צ בוילנא. חתנו - ר יוסף רוזובסקי מוילנא."},{"i":32057,"n":"מרקין, אליהו מקרוהלא","f":"יעקב","bt":"תרטז-יז","b":"רב בקרוהלא-פלך מוהילוב-תרסז על מקום אביו. נסמך מאת: ר שמריהו נח שניאורסון, ר משה שמואל שפירא מבוברויסק, ר מאיר שורץ משקלוב."},{"i":32058,"n":"מרקין, יעקב מקרוהלא","dt":"תרסז - בערך","b":"רב בקרוהלא-תרנ, ובנו ר אליהו על מקומו אחריו-תרסז"},{"i":32059,"n":"מרקל, ניסן זיסקינד מבאפלו","k":"בעל בינת נבונים","bt":"תרלז","dt":"תשז - ה שבט","b":"רב בפולין, באפלו-ניו יורק-תרפ\"א."},{"i":32060,"n":"מרקל, שלום בר","b":"מגדולי חכמי אשכנז,מרביץ תורה בגראץ-קע\"ט"},{"i":32061,"n":"מרקל, שמעון","f":"אליהו","bt":"1862","bp":"קובנא","dt":"1935","b":"נכד-אבי אמו הגביר ר הירשל נביאז'ר וניהל את בתיו בקובנא. חתן הגביר זלצר-קבלן צבאי מוורנה. עשיר ועסקן חרדי ממתנגי הציונות."},{"i":32062,"n":"מרקל-מוזסזון, מרים","f":"ורזבלובסקי","bt":"1841","bp":"וילקוביסק","dt":"1920","dp":"גרייבה","b":"תרגמה לעברית את \"היהודים באנגליה\" לפרנקולס. החליפה מכתבים עם מאפו ויל\"ג. אגרות יל\"ג אליה נתפרסמו ע\"י אברהם יערי - ירושלים תרצז."},{"i":32063,"n":"מרקלס, אהרן הכהן","dt":"תרצו - יד ניסן","b":"מו\"צ בווילנה-תר\"ע"},{"i":32064,"n":"מרקס, מוריס","b":"מנהל ביה\"ס כי\"ח בבגדד, שלוניקי-תרלה."},{"i":32065,"n":"מרקס, מרדכי הלוי","dt":"תקסד","b":"רב בטרייר"},{"i":32066,"n":"מרקר, יהודה מסוכא","f":"אברהם","k":"בעל בני אברהם","b":"רב בסוכא, זייבוש, ברלין-תרף. חיבר \"בני אברהם\" קראקא תרעט."},{"i":32067,"n":"מרקריאה, יעקב מקרימונה","k":"בעל עברונות","b":"רופא ודיין בקרימונה אצל ר יוסף אוטולינגו, ואף סייע בידו בבית דפוסו. חיבר \"עברונות\"."},{"i":32068,"n":"מרקשניט, דוד ברוך מאברטין","b":"מחכמי אברטין."},{"i":32069,"n":"מררי, משה מונציה","b":"רב בונציה. השיב בענין גזירת החנויות בפיררה."},{"i":32070,"n":"מררי, שאול מוירונה","b":"תשובה אליו ב\"דבר שמואל\"."},{"i":32071,"n":"מרשטין, מרדכי","f":"צבי הירש"},{"i":32072,"n":"מרשיה, מנצור","bp":"תקמד","b":"נזכר ב\"מלל לאברהם\" (ושם נפל טעות בשנת פטירתו - תקי וצ\"ל תקמד)."},{"i":32073,"n":"מרשן, יצחק","k":"בעל פרשנדתא","bt":"תרנב","dt":"תשד","b":"רב בהאג-תרפ\"ה"},{"i":32074,"n":"מרת גליק ב\"ר יהודה יוסף מהמבורג","k":"האמיל","bt":"תא","dt":"יום טוב שני של ראש השנה תפה","bk":[["גליקל - זכרונותי",""]]},{"i":32075,"n":"מרת הדסה לוין הי\"ד ב\"ר יוסף הירשוביץ","r":"מורה בבית יעקב","bt":"תרעב","dt":"תשה","bk":[["בת עמי - סיפור שואה",""]]},{"i":32076,"n":"מרת רחל מרגליות","dt":"תשסט","bk":[["אחד היה ישעיהו – נגד חלוקת ישעיהו",""],["איוב כמו שהוא",""],["בהר מתוך האש – מעמד הר סיני",""]]},{"i":32077,"n":"משאש שלום בן מימון","f":"מימון","k":"בעל מזרח שמש","bt":"תרסט","dt":"תשסג - י ניסן","dp":"ירושלים","b":"נכד ר שלום ממכנאס. תלמיד בת\"ת שיסד ר זאב וולף הלפרין במרוקו. תלמיד ר יצחק סבג בעל \"פחד יצחק\". יסד ישיבת \"כתר תורה\" ועמד בראשה, וכן ניהל ת\"ת במכנאס. דיין בקזבלנקה-תשט, רב ראשי-תשטו, עלה לארץ-תשלז וכיהן כרב של ירושלים. עסק בהוצאה לאור של ספרי קדמוני מרוקו. חיבר גם \"בית שמש\", \"וחם השמש\" ועוד.","bk":[["שמ\"ש ומגן","שו\"ת - אחרונים"],["תבואות שמ\"ש",""],["תבואות שמש [שו\"ת]",""],["מזרח שמ\"ש",""],["תבואות שמ\"ש","שו\"ת - אחרונים"]]},{"i":32078,"n":"משאש, אליעזר ממכנאס","dt":"תג","b":"מחכמי מכנאס"},{"i":32079,"n":"משאש, דוד ממכנאס","k":"בעל שבת כלה","bt":"תקצד","bp":"מרוקו","b":"סופר, מרביץ תורה, דרשן, חתם-תרלב. חיבר \"שבת כלה\", מעשה חייא\" ועוד הרבה חידושים שאבדו. נזכר אצל ר יעקב בירדוגו ב\"משפטים ישרים\". בנו - ר יעקב."},{"i":32080,"n":"משאש, זכרי ממכנאס","bt":"תק","dt":"תקמב","dp":"פאס","b":"מחכמי מכנאס(מרוקו), מלוב\"ן, בקי בחכמת האר\"י ז\"ל, בקי בש\"ס ומדרשים"},{"i":32081,"n":"משאש, זכרי ממכנאס","dt":"תר","b":"מחכמי מכנאס, חתם על קבלת עדות-תש עם ר אליעזר מונסונייגו. קינה לפטירתו ב\"תהלה לדוד\" לר דוד חסין."},{"i":32082,"n":"משאש, חיים ממכנאס","k":"בעל נשמת חיים","dt":"תרסד - ח תמוז","b":"הרביץ תורה במקנס, נדפס ביחד עם ספר נשמת חיים, ותפארת בנים אבותם לבנו ר' יוסף הרביץ תורה במקנס, נדפס ביחד עם ספר לקט הקמח, ותפארת בנים אבותם לבנו ר' יוסף","bk":[["נשמת חיים",""],["לקט הקמח - על ד' חלקי שלחן ערוך לפי סדר א' ב'",""],["נשמת חיים - פנינים על התנ\"ך",""]]},{"i":32083,"n":"משאש, יוסף ממכנאס","b":"מחכמי מכנאס-שצט."},{"i":32084,"n":"משאש, יוסף ממרוקו וחיפה","f":"חיים","k":"בעל מים חיים","r":"רב בתלימסאן, מקנס, חיפה","bt":"תרנב","bp":"מכנאס-מרוקו","dt":"תשלד - ב שבט","b":"רב בתלמסאן-תרפד, אלגיר-תרצח, מכנאס, חיפה-תשכ\"ה. פרסם מאמרים ב\"אוצר התורה\" - ג'רבה תרץ. חיבר גם \"מים חיים\", \"נר מצוה\", ועוד. בספריו ידיעות רבות על קהלות אלגיר. בעל כשרון ציור וצייר בעצמו את השערים לספריו.","bk":[["מים חיים",""],["מים חיים [משאש]","שו\"ת - אחרונים"],["מים חיים [שו\"ת]",""],["אוצר המכתבים",""],["בגדי ישע – הושענות וסוכות",""],["גרש ירחים – גירושין",""],["זבח תודה - שחיטה",""],["נחלת אבות – אבות",""],["נר מצוה - חנוכה",""],["תפארת בנים אבותם - סיפור יחוס משפחת משאש לדורותם",""]]},{"i":32085,"n":"משאש, מימון","k":"בעל אוצרות שמים","bt":"תרלח","bp":"מרוקו","b":"תלמיד ר חיים מריג'ין. אביו של ר שלום רבה של ירושלים."},{"i":32086,"n":"משאש, מסעוד ממרוקו","f":"זכרי","b":"רב במכנאס, חתם-תקך עם ר שלמה טאפירו."},{"i":32087,"n":"משאש, מרדכי ממכנאס","b":"מחכמי מכנאס, חתם-תקסד על הסכמה ועם חכמי מכנאס-תקץ. נזכר ב\"שופריה דיעקב\"."},{"i":32088,"n":"משבוים, יהודה ליב מטרסטינע","k":"בעל ברכת הארץ","bt":"תרסח","dt":"תש..","dp":"טרסטינה","b":"תלמיד ישיבת תורת חסד בבריסק אצל בעל אמרי משה. אב\"ד טרסטינה-ליד ביאליסטוק. פרסם מאמרים ב\"בית שמואל\" - וארשא תרצו. נספה בשואה עם אשתו ובנו התינוק."},{"i":32089,"n":"משביצקי, יצחק נטע מאירקטסק","f":"דב","bt":"תרח","bp":"נוואהרדוק","b":"תלמיד ישיבת קובנא. רב בוערחנא-אודינסק-פלך זאבאייקאלי, אירקוטסק-סיביר-תרלג. נסמך מאת: ר יצחק אלחנן מקובנא, הנצי\"ב, ר ברוך מרדכי ליפשיץ מנווהארדוק."},{"i":32090,"n":"משה","f":"חיים מסטאנוב","b":"רב-שנת תק\"פ"},{"i":32091,"n":"משה","k":"בעל זכרון משה","b":"נכד ר יוסף קרא. רב-שנת שמ. זקנו-אבי אמו של המהרש\"א."},{"i":32092,"n":"משה","f":"יוסף"},{"i":32093,"n":"משה","f":"שמעיה","k":"בעל ספר האורה","b":"מגדולי בעלי התוספות-ד'תתק\"נ"},{"i":32094,"n":"משה","f":"יום טוב","b":"מגדולי הראשונים,אביר העולם-ד'תתק\"מ"},{"i":32095,"n":"משה","b":"מגדולי מרביצי התורה בדורו,ריש מתיבתא במתא מחסיא-שנת מ'"},{"i":32096,"n":"משה","k":"בעל ברכת משה","b":"רב-שנת תק\"ע"},{"i":32097,"n":"משה","k":"ר' משה השרף"},{"i":32098,"n":"משה","f":"שמואל","k":"בעל אסף המזכיר","dp":"יארמוט"},{"i":32099,"n":"משה","f":"שניאור זלמן - התניא","bt":"תקמד","dt":"תרל","dp":"ראדימסליע","b":"חתן ר צבי הירש מאולע. רשם את תורת אביו - בכת\"י. חתניו ר שלום שכנא בן ר נח אלטשולר, ר אברהם שיינעס משקלוב, ר אליהו זסלבסקי מקרמנצוג."},{"i":32100,"n":"משה (אהרן) מבריסק","f":"הלל","k":"משה ר הללס מבריסק","b":"בניו - ר אהרן זליג בעל \"עמודי שבעה\", ר שמואל-פרנס בבריסק. נכדו - ר הלל בעל \"בית הלל\", ר יהודה."},{"i":32101,"n":"משה (יהושע) הכהן מקראקא","f":"אהרן צבי הירש","k":"בעל אסיפת הכהן","b":"נכד להרב העשל מצאצאי מהרם פאדובה. חתן ר יום טוב מ\"ץ מקראקא. מחכמי קראקא-תס, תלמיד ר יצחק חיים ן דנא די בריטו באמשטרדם. חיבר \"אסיפת הכהן\" - אמשטרדם תצא."},{"i":32102,"n":"משה (רוזנבלט)","f":"אשר למל מאייבנשיץ","bt":"תפ","b":"תלמיד ר משה לבוב מטרייר (מורביה). דיין וספרא דמתא באייבנשיץ, עבר לקראקא (לאחר גזירת המלבושים). בנו ר ישמעאל יואל על מקומו אחריו."},{"i":32103,"n":"משה - מדפיס בוילנא","f":"מנחם מנדל","b":"מדפיס בוילנא-תקס אצל יאזיפאט מירסקי קאנאניק, יחד עם ר אריה ליב בן דוד ריט ור גרשון לוריא."},{"i":32104,"n":"משה אברהם מאיטליה","b":"מגדולי רבני איטליה-ש\"צ"},{"i":32105,"n":"משה אברהם מבריסק ואילוקסט","b":"חתן ר זאב וולף מזעטיל בעל \"עמק הלכה\". רבה הראשון של אילוקסט-תרז, ור בייניש על מקומו אחריו. חסיד והפיץ את החסידות באילקוסט."},{"i":32106,"n":"משה אברהם מראשקוב","f":"שבתי מראשקוב","k":"אדמור מראשקוב","b":"חתן ר יוסף דרוהוביטשר ממזבוז. אדמור בראשקוב יחד עם אחיו ר יחיאל יוסף על מקום אביהם. חתנו - ר ישראל שלום יוסף בעל \"פאר ישראל\"."},{"i":32107,"n":"משה אהרן דוד מטאליא","b":"רב בטאליא-תקע\"ה"},{"i":32108,"n":"משה אהרן הלוי מקושטא וירושלים","k":"בעל מטה אהרן","bt":"תקד","bp":"קושטא","dt":"תקעד - ח תמוז","dp":"ירושלים","b":"רב בקושטא, עלה לירושלים בזמן מהרי\"ט אלגזי, נאלץ לחזור לקושטא ושב לירושלים. חותנו של ר משה זכות. חיבר \"מטה אהרן\" שלוניקי תקעט."},{"i":32109,"n":"משה אהרן מאיטליה וירושלים","f":"גרשון","dt":"תרב - ג אייר","dp":"ירושלים","b":"מחכמי איטליה, עלה לארץ."},{"i":32110,"n":"משה אהרן מדסוי","b":"רב בדעסוי,ברלין-תרכ\"ג"},{"i":32111,"n":"משה אהרן מוושילישק","b":"רב בואשילישוק-תקמב (אולי הוא שהיה רב בוילקוביסק). בניו - ר יהודה ליב מוילנא, ר אשר - נפטר צעיר-תקנג."},{"i":32112,"n":"משה אהרן מוילקוביסק","b":"רב בווילקוביסק-תקכ (אולי הוא שהיה רב בואשלישוק)."},{"i":32113,"n":"משה אהרן מקוטנא","dt":"תריא","b":"תלמיד החוזה מלובלין, היהודי הקדוש מפשיסחא, ר שמחה בונם מפשיסחא. רב בסטריקוב, קוטנא-תקפ."},{"i":32114,"n":"משה אהרן מריטובה","f":"אברהם אבלי מוארז'אן","b":"רב בריטובה."},{"i":32115,"n":"משה אהרן שניאור מליוורנו","b":"תשובה ממנו ב\"שמש צדקה\"."},{"i":32116,"n":"משה אורי הלוי מאמשטרדם","b":"רב הקהלה האשכנזית באמשטרדם-שמה, דאג לקליטת האנוסים בקהלה היהודית עד שנצטרף אליו ר יוסף פארדו כרב העדה הספרדית. אחיו - ר אברהם אורי."},{"i":32117,"n":"משה איוויער מואשלישוק","f":"יעקב אשכנזי","dt":"תקלא","dp":"ואשלישוק","b":"מקובל, מחכמי וילנא-תקמ, היה נכבד בעיני הגר\"א. אחיו - המקובל ר יצחק אשכנזי בעל \"ברית עולם\". בנו - ר קארפעל, מצאצאיו ר זרח מוילנא בן שמואל מדרעטשין."},{"i":32118,"n":"משה איזיק","f":"יוסף מקאמינקא","b":"רב בארוסטשוב-תק\"ס"},{"i":32119,"n":"משה איש חי מפרמישלא","k":"בעל מטה משה","dt":"שצ - כד ניסן","b":"עק\"ה, רב בפרעמיסלא"},{"i":32120,"n":"משה אליהו מאניקשט","f":"חיים","b":"רב בפומפיאן כ-15 שנה, אניקשט על מקום ר אליהו מראגולה (רגולר) ור משה יואל גוריון על מקומו אחריו. הסכים על ש\"ס וילנא."},{"i":32121,"n":"משה אליהו מקרסטיר","b":"רב בקרסטור-תקעח. נזכר ב\"חתם סופר\"."},{"i":32122,"n":"משה אליעזר מצ'רלסטון","b":"רב בצ'רלסטון-תקם אצל ר אברהם אלכסנדר, ונזכר בפנקס הקהלה שם."},{"i":32123,"n":"משה אליקים הרופא מרודוס","b":"רופא ברודוס-שנות ה-ת'."},{"i":32124,"n":"משה אלעזר","b":"רב בקיצע"},{"i":32125,"n":"משה אלתר ממאקווא","b":"פרסם מאמרים ב\"כרם בית שמואל\" - פיעטרקוב תרצב - כתב עת תלמידי ישיבת אלכסנדר."},{"i":32126,"n":"משה אפרים אשכנזי מקאליש","f":"ראה: אשכנזי, משה אפר","b":"נכד החכם צבי, תלמיד רמ\"ל מקוסוב. רב בקליש."},{"i":32127,"n":"משה אפרים מאברזיצקא","f":"שמעון","k":"בעל דברי משה-כת\"י","b":"רב באברזיצקא-תקפט. חיבר \"דברי משה\", \"בית החכמה\", \"בית נדה\", \"בית אפרים\" - על ארבעה חלקי השו\"ע - בכת\"י. נזכר בשו\"ת ר עקיבא איגר, גם אביו ר שמעון היה חברו של ר עקיבא איגר ונזכר בספריו."},{"i":32128,"n":"משה אפרים מקרלסבורג","f":"יוסף הלוי","b":"פרנס בקרלסבורג-תק בערך."},{"i":32129,"n":"משה אריה הלוי מיאנובה","dt":"תרנב","b":"רב באיישישוק, פוניבז', יאנובה על מקום ר יהושע השל אליאשזון. אחד מחמשת הגדולים שהסכימו-תרלד על הספר \"חפץ חיים\" שיצא אז בעילום שם מחברו. בנו - ר שמואל צבי רבינוביץ מויזאהן."},{"i":32130,"n":"משה אריה ליב מבאזינג","b":"חתן ר שלמה טלטש ממורביה. אב\"ד באזינג-תקס בערך. נזכר בשו\"ת החת\"ס."},{"i":32131,"n":"משה אריה מטיריא","b":"רב בטיריא-ש'-ת' - בזמן ר גבריאל גליקו."},{"i":32132,"n":"משה אריה ממזריטש","f":"יוסף","dt":"תקעט - ב אדר","dp":"אוסטרהא","b":"מגיד מישרים במזריטש-פרבר אוסטרהא בזמן ר חיים רפפורט. בנו ר יוסף מאוסטרהא."},{"i":32133,"n":"משה בן אברהם מפרמישלה","bt":"1540","dt":"ה'שסו 1606","bk":[["הואיל משה",""],["מטה משה",""]]},{"i":32134,"n":"משה בן יצחק איזיק מסמבור","f":"איכנשטין, משה","k":"בעל תפלה למשה","b":"רב בסמבור"},{"i":32135,"n":"משה בן ציון מוילנא","f":"יהודה ליב","b":"גביר מראשי קהלת וילנא, חתם-תע בפנקס הקהלה."},{"i":32136,"n":"משה בנימין מבגדד","f":"בנימין","k":"בעל מעשה רב","b":"רב בבבגדד-תצא. חיבר גם \"הואיל משה\" קושטא תצו, ועוד. שלח כתבי היד של ספריו להדפסה בקושטא ונשדדו בדרכם. נזכר אצל השליח ר מרדכי רוביו."},{"i":32137,"n":"משה בנימין ממזיתרא","b":"רב במזיתרא-שנות ה-ש'."},{"i":32138,"n":"משה בנימין מספרד","b":"רב בסלמנקה. הריב\"ש מזכירו בספרו."},{"i":32139,"n":"משה בעל התוספות","k":"השר מקוצי,הסמ\"ג","b":"מגדולי הראשונים בעלי התוספות,פוסק,דרשן,מוכיח,משפיע,מראשי מנהיגי ישראל בקוצי(צרפת)-ד'תתק\"צ"},{"i":32140,"n":"משה בער מזדונסקא-וואלא","dt":"תשג","b":"חתן ר אליעזר ליפשיץ מזדונסקא-וואלא. רב בזדונסקא-וואלא על מקום חותנו."},{"i":32141,"n":"משה בצלאל משלוניקי","b":"גביר בשלוניקי-שנות ה-תק'. סייע בהדפסת שו\"ת ר ישראל מברונא."},{"i":32142,"n":"משה ברוך הלוי","dt":"תשג","b":"רב בוואהין"},{"i":32143,"n":"משה ברוך מאדרינופול וצפת","bp":"אדרינופול","b":"רב באדרינופול, עלה לצפת-רצה, מחכמי צפת-רצח, נמנה על 25 הרבנים שהכתירו את ר יעקב בירב כמוסמך הראוי להסמיך אחרים. רב קהלת הספרדים בדמשק-שא, ור משה ברור על מקומו אחריו, רב בשכם."},{"i":32144,"n":"משה ברוך משלוניקי - א","dt":"שכז","b":"מחכמי שלוניקי, חתם על הסכמות הקהל בשלוניקי, התלוה לר משה אלמושנינו בשליחות-שכו קהלת שלוניקי בקושטא אצל השולטן ושריו - ונפטר בשליחותו, בשליחות ה\"מוסילימליק\" בברוסה."},{"i":32145,"n":"משה ברוך משלוניקי - ב","dt":"שמא-שסא - ד טבת","dp":"שלוניקי","b":"מחכמי שלוניקי."},{"i":32146,"n":"משה בריינדילש מלובלין","b":"מחכמי לובלין. הביא מכתב מר חיים שור מסטנווא לר מרדכי כץ בלבוב-שפד בדבר נבואת ילד - ונדפס בספר אלים - אמשטרדם."},{"i":32147,"n":"משה גבריאל מליסא","b":"רב בגריידיץ-תקמ, ראב\"ד בניישטט-מחוז פוזן על מקום ר גדליה ליפשיץ, חאדזעזען-מחוז ברומברג-תריא."},{"i":32148,"n":"משה גומפרץ מברלין","f":"ליב קליווא","b":"מראשי הקהילה בברלין-תפט, והיה מראשי התומכים בר משה בן אהרן מלבוב-רבה של ברלין - כנגד סיעת המתנגדים לו."},{"i":32149,"n":"משה געצילס מוילנא וצפת","b":"מחכמי וילנא, עלה לצפת-תקע בערך."},{"i":32150,"n":"משה גרשון מדאמאן","b":"רב בדאמאן-תק\"ס"},{"i":32151,"n":"משה גרשון מפינטשוב","b":"רב בפינטשקוב-ת\"ק"},{"i":32152,"n":"משה גרשון מפלונסק","dt":"תרנג - יא חשון","b":"רב בפלונסק"},{"i":32153,"n":"משה גרשון משלוניקי","b":"רב בשלוניקי-שנות ה-ש'."},{"i":32154,"n":"משה דאקטאר מלובלין","dt":"תקסו - כד אדר","dp":"לובלין","b":"מחכמי לובלין."},{"i":32155,"n":"משה דב בר מלחוביץ","b":"מגדולי תלמידי ר מנחם מנדל מליובאויטש. רב בלחוביץ-ליד האדיץ."},{"i":32156,"n":"משה דב מטבריה","f":"אהרן השותק מזליחוב","dt":"תרז - יב אב","b":"חתן ר שלמה מקרלין, ובזיוו\"ש חתן ר משה מקוברין-אחיו של ר אהרן הגדול מקרלין. עלה לארץ-[תר..] והשתקע בטבריה. בניו ר מרדכי מלכוביץ (השני), ר ישראל מקוברין, ר חיים חייקיל מהורודני, ר אשר ור יעקב יצחק מטבריה."},{"i":32157,"n":"משה דב משאוולי","f":"דוד מיכל","b":"שו\"ב בשאוולי-תרסד, חתם על סמיכה לשוחט."},{"i":32158,"n":"משה דוד מצפת","b":"מרבני צפת"},{"i":32159,"n":"משה דוד מקאלושין","k":"חתן ר יחזקאל מקוזמיר","dt":"תרנה - יג אדר","b":"רב בקאלושין"},{"i":32160,"n":"משה דניאל מדופניצה","b":"מחכמי דופניצה-ליד סופיה-תלב."},{"i":32161,"n":"משה הגולה מקיוב","f":"יעקב בן משה","k":"בעל אוצר נחמד","bt":"רט","bp":"שאדובה","dt":"רפ-צ","b":"מגדולי חכמי דורו. (תלמיד וחתן ר אברהם הצרפתי מאדרינופול ולפי ליפמן-קובנא - באמת הכוונה לר משה מקיוב הראשון), הלך ללמוד תורה בקושטא-רמ - כי בליטא לא היה אז מרכז תורה. למד תכונה אצל החכם הקראי אליהו בן משה בשיאצי בעל \"ספר המצוות\". עבר לאדריאנופול ולקיוב, ובזמן פלישת הטטרים איבד את רכושו ואת חיבורו על הספר \"גן עדן\" לר אהרן בן אליהו מ ניקומדיה (הספר נתגלה אח\"כ בתיאודוסיה והועתק בקושטא), ושני בניו נלקחו לעבדים בתיאודוסיה, והוא עצמו ניצל וברח ללוצק וחזרה לשאדובה-רנה, והחל לכתוב את \"שושן סודות\". באותה שנה גורשו היהודי מליטא, ועבר ללידא, עם פלישת הטטרים לשם נפל בשבי והובא לקרים-סולקאט, ונפדה ע\"י היהודים הרבניים והקראים והתישב בקאפה(=תיאודוסיה) שבקרים, והיה שם מחלוקת בקהלה בענין נוסח התפילה והמנהגים, והצליח להשכין שלום. חיבר מחזור כמנהג קאפה - והוא מנהג קרים, וקבע 18 כללי התנהגות שנתקבלו ע\"י הציבור בקרים. יהודי קרים הכניסו את פיוטיו לתפילותיהם, ובמשך דורות הזכירו את נשמתו כאחד מגדולי רבניהם. כונה בפיהם משה אשכנזי או משה מרוסיה. ניסה לעלות לארץ - אך לא עלה בידו."},{"i":32162,"n":"משה הדרשן מוילנא וחעלמא","f":"הלל","k":"בעל תורת אשם","bt":"תכא - בערך","bp":"וילנא","dt":"תפו - יג אייר","dp":"וילנא","b":"חתן ר שלמה בן ישראל קצנלנבוגן. רב בחעלמא, קמפנה, מגיד בוילנא-תסט-תפו, בזמן ר השל אב\"ד וילנא, וחתנו ר יצחק איזיק בן אליעזר על מקומו אחריו. חיבר ביאור על \"ילמדנו רבנו\" שבמדרש תנחומא. נזכר ב\"עטרת צבי\" לר צבי בן עזריאל מוילנא, ו\"נחלת יעקב\" לר יעקב בן אברהם מקראקא. הו\"ל ספר אביו \"בית הלל\" עם הוספות ממנו."},{"i":32163,"n":"משה הדרשן מפרג","f":"אברהם וולרשטיין","dt":"תיט - כה שבט","b":"מגדולי חכמי פרג,דרשן בפרג"},{"i":32164,"n":"משה הדרשן מצרפת","f":"רבי יעקב הנביא גאון","b":"מראשוני חכמי התורה בצרפת הדרומית,ראש ישיבה בנרבונא-ד'תת\"מ. חיבר מדרש הלכה."},{"i":32165,"n":"משה הירש מכפר דוילא","bt":"תריא - בערך","dt":"תרצא - כז אד\"ב","b":"תלמיד ר מנחם א\"ש מאונגוואר. מחכמי כפר דוליא-ליד קלויב."},{"i":32166,"n":"משה הירש פילדרער","b":"מחכמי כפר פילדר-ליד נאסאד."},{"i":32167,"n":"משה הכהן [גדישא] מג'רבה","f":"שאול-לחם הבכורים","k":"בעל פני משה","r":"ראב\"ד ג'רבא","bt":"תקן","dt":"תרכג","dp":"ליוורנו - ישראל","b":"תלמיד ר אברהם הכהן בעל \"קנה אברהם\", רב ומקובל מחכמי ג'רבא-[תר..]. תלמידו - ר חיים חורי. חיבר גם \"זכות משה\".","bk":[["פני משה -",""]]},{"i":32168,"n":"משה הכהן מאוסטרהא (זוסמן)","f":"אברהם אבלי בן פסח","dt":"תריח - א סיון","dp":"אוסטרהא","b":"גביר מחכמי אוסטרהא ומחברי הח\"ק-תקס. מבניו: ר ליבוש ר משהקס. חתניו: ר שאול לוין מפינסק, ר שמואל הכהן בן ר שלמה זלמן הכהן - אחיינו."},{"i":32169,"n":"משה הכהן מאזמיר","b":"שליח צבור בקהלת שלום (לימים נקראה נוה שלום) באזמיר-שנות ה-ת'."},{"i":32170,"n":"משה הכהן מאזמיר","b":"מדפיס באזמיר-תק אצל המדפיס הארמני אוסטה מארגוס."},{"i":32171,"n":"משה הכהן מאיטליה","b":"מגדולי חכמי איטליה, מרביץ תורה בקורפו-שכ\"ה"},{"i":32172,"n":"משה הכהן מאיטליה","f":"זכריה","b":"רב ומשורר באיטליה. מוזכר בספר \"אגדת שמואל\" לר שמואל אריפול. משיריו בספרים שנדפסו בונציה."},{"i":32173,"n":"משה הכהן מאלגיר","b":"רב במסתגאנם. נזכר בשו\"ת הרשב\"ש."},{"i":32174,"n":"משה הכהן מאלגיר","bt":"תמ","dt":"תקי - בערך","b":"רב בענאבא(=בון). שאלה ממנו לר ישראל צרור ב\"פרי צדיק\"."},{"i":32175,"n":"משה הכהן מאלגיר","bt":"תרי","dt":"תרף - בערך","b":"רב באל עבאס-אלגיר-תרעב. נזכר במכתבי ר יצחק מרעלי. ברשימת התומכים בהדפסת \"שערי רחמים\" ירושלים תרסב - בשם ר משה הכהן מעין צפרא."},{"i":32176,"n":"משה הכהן מאלטונא","f":"ליבוש","k":"ר משה ר ליבש","dt":"תס - א אייר","dp":"אלטונא","b":"תלמיד ר השל בפולין, פרנס מחכמי אלטונא בזמן ה\"חכם צבי\" המזכירו בספרו שסייע לו בהיותו באלטונא. בניו: ר הענדל, ר מרדכי המבורגר מלונדון."},{"i":32177,"n":"משה הכהן מבוקובסק","b":"רב בבוקובסק."},{"i":32178,"n":"משה הכהן מביאלא","f":"ברכיה הכהן","b":"מו\"צ בביאלא"},{"i":32179,"n":"משה הכהן מבלגרד","f":"אברהם","b":"מראשי קהלת בלגרד-תקכא בזמן שלא כיהן רב שם."},{"i":32180,"n":"משה הכהן מדובנא","f":"שלמה זלמן מאוסטרהא","b":"רב בדובנא-בשנות התק'."},{"i":32181,"n":"משה הכהן מהוניין","b":"רב בהוניין בזמן הרשב\"ש, ושלח אליו שאלות לאלגיר ולא לר אפרים אנקאוה שישב בתלמסאן הסמוכה - וכאשר נודע על כך לר אפרים הקפיד על הרשב\"ש ובכך נתעורר מחלוקת בין הרבנים. לאחר פטירת ר אפרים היה לאחד מחשובי הרבנים באזור יחד עם ר יוסף ששפורטש. נפטר ללא בנים והשלטונות נטלו את נכסיו עד שהגיעו ר עמרם הכהן ואחיו והוכיחו שהם אחי ר משה וירשו את נכסיו. מחלוקת היתה בין היורשים לבין בעלי חוב אחיהם ר יוסף פרובנצאל ור חיים הכהן שלאל והרשב\"ש הכריע לטובת היורשים."},{"i":32182,"n":"משה הכהן מוארשא","k":"ר משה'לי חריף","b":"תלמיד החוזה מלובלין, המגיד מקוזניץ, ור אברהם יהושע השל מאפטא. אגרת ממנו בסוף \"דעת משה\"."},{"i":32183,"n":"משה הכהן מוויניוויטש","b":"רב בוויניוויטש-תרן."},{"i":32184,"n":"משה הכהן מונציה","f":"מיכאל","k":"בעל עט סופר","dp":"ירושלים","b":"מחכמי בלגרד, נשבה במלחמה (יחד עם ר יוסף אלמושנינו) בידי האוסטרים ונפדה, רב בונציה, ומגיה בבית הדפוס. חיבר \"עט סופר\", \"דברי יוסף\". הגיה \"שערי ירושלים\", \"ברכת אברהם\"."},{"i":32185,"n":"משה הכהן מחברון","f":"גוליב","b":"נדיב מחברון, הקדיש שדה לבנית בית כנסת בערך ד'תשפו (1026)."},{"i":32186,"n":"משה הכהן מחלב","dt":"תרמב - ח ניסן","b":"מגדולי דורו,ראב\"ד ור\"מ בארם צובה"},{"i":32187,"n":"משה הכהן מטרדוסילס-ספרד","k":"בעל עזר האמונה","bp":"טרדוסילס-סביליה","b":"מחכמי טרדוסילס, בגלל המלחמה-קכו עבר לאווילה וכיהן כרב. השתתף בויכוח באווילה כנגד תלמיד המשומד אבנר מבורגוס-קלה, וסיפר על כך בספרו \"עזר האמונה\"."},{"i":32188,"n":"משה הכהן מיאסטרוב","f":"סיני","k":"בעל משה מסיני-כת\"י","b":"אב\"ד יאסטרוב(=יאסטראווי)-תקצא. חיבר \"משה מסיני\" - בכת\"י."},{"i":32189,"n":"משה הכהן מיזלוביץ","b":"רב ביזלוביץ-תרמד, רדומישל."},{"i":32190,"n":"משה הכהן מלויצק","b":"חתן ר יהודה וייל-קצנלנבוגן מבריסק (ולפי אוצר הרבנים חתן זקנו של ר יהודה - השר שאול). רב בלויצק-שפ"},{"i":32191,"n":"משה הכהן מלונדון","dt":"תקכב","b":"הגיע מלונדון-תקי לאמריקה עם כל עדתו והתישבו בצ'רלסטון, וכיהן כרב."},{"i":32192,"n":"משה הכהן מלוניל","k":"הרמ\"ך","b":"מגדולי הראשונים,מרביץ תורה בלוניל-ד'תתק\"נ. חיבר השגות על הרמבם."},{"i":32193,"n":"משה הכהן מליוורנו","f":"שמואל","b":"תשובה ממנו ב\"ארח לצדיק\". בנו המהרש\"ך שהיה רב בליוורנו בזמן החיד\"א."},{"i":32194,"n":"משה הכהן ממאקאווי","k":"הכהן הגדול מטיקטין","b":"מגדולי חכמי דורו,רב במאקאווי-תק\"ל"},{"i":32195,"n":"משה הכהן ממגנדורף","f":"נתן ממגנדורף","b":"תלמיד החת\"ס. חיבר בכת\"י הגדה עם פי' אשכנז - ונתנה במתנה לרבנית שרל אשת החת\"ס (בת ר עקיבא איגר). וכן שירטט את השער לכת\"י \"מרדכי\" שהיה בידי החת\"ס-תקעז."},{"i":32196,"n":"משה הכהן ממגנצא","f":"שלמה","b":"מגדולי בעלי התוספות,מרביץ תורה במגנצא-ד'תתק\"ס"},{"i":32197,"n":"משה הכהן ממוגאדור","b":"רב במוגאדור-תרכא, חיבר הקדמה ל\"ברית אבות\"."},{"i":32198,"n":"משה הכהן ממזיבוז","k":"בעל פני משה","b":"מרביץ תורה במעזיבוז,פרעמיסלא-ת\"ע"},{"i":32199,"n":"משה הכהן ממיץ","dt":"תנ - ד חשון","b":"רב במיץ,דומ\"צ בפרג"},{"i":32200,"n":"משה הכהן ממיקלוש","f":"יחזקאל","b":"רב בסט-מיקלוש-תרן."},{"i":32201,"n":"משה הכהן ממסתגאנם","b":"רב בבמסתגאנם. נזכר בשות הרשב\"ש."},{"i":32202,"n":"משה הכהן ממצרים","bt":"שלוניקי","dt":"תיב - אחרי","dp":"מצרים","b":"תלמיד ר עזוז בן שמעון נחמני באלכסנדריה. מחכמי שלוניקי, רב ברודוס, אלכסנדריה, קהיר, חתם על מכתב התמיכה של רבני קושטא ומצרים בדון יוסף נשיא. מתלמידיו - ר מרדכי הלוי ממצרים בעל \"דרכי נעם\", ר דוד קונפורטי."},{"i":32203,"n":"משה הכהן ממצרים","dt":"תעח","b":"מגדולי רבני מצרים"},{"i":32204,"n":"משה הכהן מסופיה","b":"גביר בסופיה-תקן, תמך ברבנים ובהדפסת ספרים."},{"i":32205,"n":"משה הכהן מסופיה ובלגרד","f":"מיכאל","k":"בעל מורה צדק","b":"רב בסופיה-תלט, עבר לבלגרד לאחר כיבוש סופיה בידי האוסטרים, נלקח בשבי האוסטרים לניקלשבורג יחד עם ר יוסף אלמושנינו ונפדה שם, וכתב על כך. תשובותיו היו בידי החיד\"א."},{"i":32206,"n":"משה הכהן מפאס","f":"יחיא","b":"מחכמי פאס, חתם-רפו בענין הנפיחה."},{"i":32207,"n":"משה הכהן מפאס","f":"אהרן","b":"מחכמי פאס-תקך."},{"i":32208,"n":"משה הכהן מפרג וירושלים","f":"יעקב מפרג","dt":"תנט-עח","b":"רב קהילת האשכנזים בירושלים בשנים תמה - תנט, היה בשליחות באיטליה, בפולין ובמצרים. בשנים תמט - תנא היה בפרג."},{"i":32209,"n":"משה הכהן מפרג וירושלים","f":"יעקב","b":"מחכמי פרג, עלה לירושלים והיה רב הקהלה האשכנזית גם בזמן עליית חבורת רבי יהודה החסיד, בשליחות באירופה עם חברו ר איזיק מסלוצק, והיה בקרזמיר-תמח, מיץ-תעא."},{"i":32210,"n":"משה הכהן מפרוביזנא","b":"תלמיד ר מנחם מנדל מקוסוב. מכתב ממנו ב\"עטרת יעקב וישראל\"."},{"i":32211,"n":"משה הכהן מצפת - א","b":"מחכמי צפת-שנות ה-ש'."},{"i":32212,"n":"משה הכהן מצפת - ב","b":"רב בצפת, חתם-תרלז על כתב שליחות ר יעקב חיון, עם ר יהודה חכים, ר שמואל עבו, ר מרדכי מאמאן ועוד."},{"i":32213,"n":"משה הכהן מקאמאי","b":"רב בקאמיי-תק\"כ"},{"i":32214,"n":"משה הכהן מקובין","b":"ציר ממשלת מרוקו-אחרי תקנא."},{"i":32215,"n":"משה הכהן מקושטא - ב","bt":"סביב ה'תי","dt":"ה'תצג (בערך)","b":"דיין ביה\"ד האשכנזי בקושטא-תי.","bk":[["כהונת עולם [שו\"ת, ועל טור - ריבית ונדרים]",""]]},{"i":32216,"n":"משה הכהן מקושטא ואדרינופול","k":"בעל כהונת עולם","bt":"תי - בערך","dt":"תצה - בערך","dp":"קושטא","b":"חתן ר יהודה שמואל פרימו. מחכמי אדריאנופול, ובתחלה נטה לשבתאות אך בהמשך חזר בו. עבר לקושטא-תצג והיה דיין איסור והיתר וראש ישיבה. רוב כתביו כמו כתבי חותנו אבדו בשריפה-תמד ושוב בשריפה-תעד, תלמידו ר אהרן אלידי סייע בהוצאת ספרו. בנו ר אליעזר הכהן היה גם הוא ממונה על איסור והיתר בקושטא."},{"i":32217,"n":"משה הכהן מקושטא ואלכסנדריה","b":"תלמיד ר יוסף ן לב. רב בקושטא, אלכסנדריה-שנות ה-ש'. חתם עם רבו ועם ר מרדכי מטיבולי."},{"i":32218,"n":"משה הכהן מרודוס וכיאו","b":"תלמיד ר חיים שבתי בשלוניקי. מחכמי שלוניקי, רב ברודוס יחד עם ר יצחק איריסה, היה מחלוקת ביניהם ועבר לכהן כרב בכיאו-שעה (כנראה נשלח ע\"י רבו ר חיים שבתי)."},{"i":32219,"n":"משה הכהן משלוניקי","bt":"תרכא","b":"מקובל מחכמי שלוניקי."},{"i":32220,"n":"משה הכהן משלוניקי","f":"יהושע","b":"גביר בשלוניקי. סייע בהדפסת \"בית מנוחה\"-תריא - עם כמה מחבריו. אחיו של הגביר ג'יליבי אליהו הכהן."},{"i":32221,"n":"משה הכהן משלוניקי","b":"מחכמי שלוניקי-תרס."},{"i":32222,"n":"משה הכהן משלוניקי","f":"שמואל","k":"בעל אורים ותומים","b":"מחכמי שלוניקי. חיבר ספר באסטרולוגיה \"אורים ותומים\" - בכת\"י."},{"i":32223,"n":"משה הכהן מתונס","k":"בעל בני משה","b":"מגדולי חכמי תוניס-תר\"ס"},{"i":32224,"n":"משה הלוי אשכנזי","f":"שלמה","k":"בעל יואל משה,מפפד\"מ","b":"מקובל מחכמי פפד\"מ-ת'. תלמיד ר ליב מלבוב. חיבר פירוש ל\"עשרה מאמרות\" לר מנחם עזריה בשם \"יואל משה\". והסכים לו ר מנחם מנדל בס-רבה של פפד\"מ."},{"i":32225,"n":"משה הלוי הקראי","f":"אליהו","b":"נוסע קראי, היה במצרים-תיד."},{"i":32226,"n":"משה הלוי מאיפסולה","f":"שאול","b":"רב באיפסולה(-ליד אדרינופול)-ת' יחד עם ר שם טוב ואלאנסי."},{"i":32227,"n":"משה הלוי מאלגיר","bt":"תרי","dt":"תרף בערך","b":"הגיע מאשכנז לאלגיר, ונשא אשה ממשפחת טבול. רב בנומור(=גאזאווית)-אלגיר, בל עבאס-אלגיר. מכתב ברכה ממנו לר מסעוד בן יצו, נזכר ב\"כרם חמר\"."},{"i":32228,"n":"משה הלוי מבודון","b":"רב בבודון-שנות ה-ת'."},{"i":32229,"n":"משה הלוי מבלחוב","f":"אהרן הלוי","b":"רב בבלחוב-תצ\"ח,אלעסק-תק\"ח"},{"i":32230,"n":"משה הלוי מגאטש וקמניץ","f":"אברהם דוב הלוי מקמני","b":"רב בגאטש, קמניץ-תרנ על מקום אביו."},{"i":32231,"n":"משה הלוי מגיברלטר","f":"יצחק","b":"מחכמי גיברלטאר."},{"i":32232,"n":"משה הלוי מגליפולי","b":"רב בגליפולי-ת' בזמנם של ר מאיר די בוטון ור יוסף ששון."},{"i":32233,"n":"משה הלוי מחעלמא","f":"הלל הלוי","b":"רב בחעלמא-ת\"פ"},{"i":32234,"n":"משה הלוי מטבריה","b":"מחכמי האשכנזים בטבריה, חתם-תקסא על כתב שליחות ר דוד בן ישראל פולציקר עם ר אברהם מקאליסק."},{"i":32235,"n":"משה הלוי מטיטואן","b":"ראב\"ד בטיטואן-תקפ\"ה"},{"i":32236,"n":"משה הלוי מטיטואן","b":"מו\"ץ בטיטואן, חתם-תקמח עם ר וידאל וישראל ור מנחם נהון., ועל הסכמה על פס\"ד של ר משה ן צור-תקנח."},{"i":32237,"n":"משה הלוי מירושלים","b":"מחכמי ירושלים-תק\"פ"},{"i":32238,"n":"משה הלוי מירושלים","f":"מרדכי גימפל","k":"בעל לקוטי משה ובן לו","dt":"תריב","dp":"ירושלים","b":"עלה לירושלים. חיבר \"ליקוטי משה ובן לוי\" ירושלים תרי."},{"i":32239,"n":"משה הלוי מירושלים וחברון","f":"יוסף","k":"בעל מטה יוסף","b":"חיבר דיני שחיטה וטריפות בשם \"מטה יוסף\" בכת\"י."},{"i":32240,"n":"משה הלוי מלבוב","f":"יוסף סגל","dt":"תעט - כז אלול","b":"דיין בלבוב"},{"i":32241,"n":"משה הלוי מלודמיר","f":"שלמה מקרלין","k":"אדמור מלובלין","dt":"תקפח-ט - יח שבט","b":"חתן ר יהודה ליב מאניפולי בעל \"אור הגנוז\",ובזיוו\"ש חתן ר דוד מסטפין. אדמור בלודמיר-וואהלין. בניו ר יהושע, ר שלמה מלודמיר."},{"i":32242,"n":"משה הלוי ממינסק","b":"רב במינסק-ת\"כ"},{"i":32243,"n":"משה הלוי ממצרים","b":"רב במצרים-שס."},{"i":32244,"n":"משה הלוי מניש","b":"חזן ורב בניש-תקסט, חתנו - יזרעאל שנהרג-תקסט בדרכו לסאמאקוף."},{"i":32245,"n":"משה הלוי מנרבונה","k":"חתן הראב\"ד השני","b":"מגדולי הראשונים,רב מובהק,ראש ישיבה בנרבונה-ד'תת\"ק"},{"i":32246,"n":"משה הלוי מסופיה","b":"גביר בסופיה-שנות ה-ת'-תק'. נזכר ב\"שונה הלכות\" לר שלמה שלם."},{"i":32247,"n":"משה הלוי מסרייבו ווינה","f":"יצחק","b":"גביר מראשי קהלת סרייבו, עבר לוינה עם רבים מבני הקהלה-תקס בערך בזמן מרד הסרבים."},{"i":32248,"n":"משה הלוי מפאס","dt":"תקץ","b":"תלמיד ר שלמה אבודרהם. אב\"ד בפאס על מקום חברו ר מנחם נהון-תקפד, ונחשב לגדול הרבנים במרוקו בתקופתו. שליח טבריה ר יצחק אירגאס פגשו-תקפו וכתב עליו. מתשובותיו בספרי חכמי דורו."},{"i":32249,"n":"משה הלוי מפאס","b":"גביר ונגיד בפאס בזמן בעלי התקנות, חתם על הסכמה-תנח."},{"i":32250,"n":"משה הלוי מפדובה","f":"אליעזר","b":"רב בפדובה. נזכר בספר זכרון נשמות עירנו."},{"i":32251,"n":"משה הלוי מצעהלים וליבנא","f":"יחיאל מיכל מאיזנשטט","k":"בעל שער הקטן","dt":"תקצה - יב תשרי","b":"חתן ר אלעזר קאליר בעל \"אור חדש\". רב בליבנא, מסטיץ, דיין בצעהלם ואח\"כ רב וראש ישיבה."},{"i":32252,"n":"משה הלוי מצפת","f":"יצחק הדיין","b":"מחכמי צפת וראש ישיבה, בשנת רסד מנהיג הקהלה אחר פטירת ר יוסף סרגוסי."},{"i":32253,"n":"משה הלוי מקושטא","f":"יעקב","bt":"תקע","bp":"קושטא או ברושא","dt":"תרע - יד-ז תמוז","dp":"קושטא","b":"ראש רבני תוגרמא, חכם באשי בקושטא-תרלא, ור חיים נחום על מקומו אחריו (היה הרב האחרון שקיבל משכורת קבועה מהממשלה)."},{"i":32254,"n":"משה הלוי מקושטא","f":"יחיאל","b":"רב בקושטא-ש'."},{"i":32255,"n":"משה הלוי מקיטוב","b":"רב בקיטוב."},{"i":32256,"n":"משה הלוי מקמניץ","f":"אברהם דב מרדושקביץ","k":"הו\"ל קרני אור","b":"רב בקמניץ-ליטאווסק על מקום אביו."},{"i":32257,"n":"משה הלוי מרוזדול","b":"אב\"ד רוזדול, חתם-תג על עדות לגביר ר שלמה שבנה ביכ\"נ בזידיטשוב."},{"i":32258,"n":"משה הלוי משלוניקי","f":"יוסף","dt":"תרכה","dp":"שלוניקי","b":"דיין בשלוניקי."},{"i":32259,"n":"משה הלוי משרענק","dt":"תרלט - טז ניסן","b":"רב בשרענק"},{"i":32260,"n":"משה הלוי סופר מפשוורסק","f":"יצחק הלוי","k":"בעל אור פני משה","r":"לספר למעלה מחמישים הסכמות","bt":"תפ","dt":"תקסו - יב טבת","b":"תלמיד המגיד ממזריטש. סופר סת\"ם בפשוורסק - התפילין שהכין נחשבו ליקרים במיוחד במהלך הדורות. אחיו של ר יהודה ליב וייס מטשענגער. חיבר \"אור פני משה\" מזריטש תקע עם הסכמות של כ-50 אדמורים ורבנים. בניו ר נחמן ור דוד, חתניו ר שלמה זלמן ור שלמה ישראל. (באוצר הרבנים תאריך פטירתו - ט חשון תקנד).","bk":[["אור פני משה (פשעווארסק)",""],["אור פני משה – עה\"ת כתובים משניות ואגדתות",""],["אור פני משה",""]]},{"i":32261,"n":"משה המערבי","f":"יצחק","b":"מחכמי המערב-ד'תת."},{"i":32262,"n":"משה הנגיד","f":"מבורך בן סעדיה","b":"נגיד במצרים-ד'תתע (1110)."},{"i":32263,"n":"משה הספרדי","k":"כנראה הרמב\"ם","b":"מוזכר ע\"י הרמב\"ן בחדושיו"},{"i":32264,"n":"משה העזתי הנקדן","k":"בעל דרכי הניקוד","b":"מחכמי המסורה הקדומים. רב ונקדן בעזה, במאה השמינית. חיבר \"דרכי הניקוד והנגינות\" וילנא תקפב."},{"i":32265,"n":"משה הענוכש איש ירושלים","k":"בעל ספר המראה","b":"חיבר \"בראנט שפיגל\" - הוא ספר המראה - נדפס בשנת שס."},{"i":32266,"n":"משה הענוכש ירושלמי","k":"בעל ברנט שפיגל","b":"מחכמי ירושלים, חיבר \"ברנט שפיגל\" \"המראה\" בזל שס, ועוד."},{"i":32267,"n":"משה הפייטן","f":"שמעון הגדול","b":"רב ופייטן. מפיוטיו במחזור האשכנזי."},{"i":32268,"n":"משה הפרחי מפלורנצה-ספרד","f":"הפרחי, משה מפלורנצה","k":"ר' דוד הדיין","b":"מחכמי ספרד הקדמונים בגרנדה-ד'תתפ, מדקדק, תלמיד הרי\"ף, חיבר \"דיני הגט\""},{"i":32269,"n":"משה הפרנס מירושלים","dt":"תסו","b":"מחכמי ירושלים"},{"i":32270,"n":"משה הפרנס מספרד","b":"מגדולי חכמי ספרד, רב בנרבונה - בשנות ה-ר'."},{"i":32271,"n":"משה הפרנס מתשע קהלות","f":"מאיר הלפרן","b":"פרנס בתשע קהילות-ת\"ק"},{"i":32272,"n":"משה הרופא משלוניקי","f":"שלמה","dt":"תקצז - טז ניסן","dp":"שלוניקי","b":"רופא בשלוניקי."},{"i":32273,"n":"משה השל מוינה","dt":"תשג","b":"רב בווינה"},{"i":32274,"n":"משה וולף מבוכניא","dt":"תשד","b":"רב בבוכניא"},{"i":32275,"n":"משה ויצי נגיד","b":"מחכמי ירושלים, מוזכר על ידי ר משולם מוולטרא כאחד החכמים בירושלים."},{"i":32276,"n":"משה זאב הכהן מפלוטל","f":"שאול","b":"רב בפלוטל-ליטא."},{"i":32277,"n":"משה זאב ממזריטש","b":"רב בפולין. בשליחות באיטליה-תעה לפדיון שבויים - והסכים שם על \"ראשית בכורי קציר\" - ונציה-פיררה תעה."},{"i":32278,"n":"משה זיסקינד","dt":"שעח","b":"נספד מאת ר אברהם רפפורט ב\"איתן האזרחי\"."},{"i":32279,"n":"משה זקש מקשטילץ","f":"יחיאל","dp":"צפת","b":"מחכמי מצרים, היה בקשרי מכתבים עם ר יוסף מטרני, עלה לצפת אחר שסא, בשנת שסז בשליחות בתורכיה. וכשחזר לצפת עמד בראש עדת האשכנזים. בשנים שעב - שעז חתם על תשובות לשאלות שהגיעו מקהילות שונות עם חכמי צפת, לאחר פטירתו פנו חכמי האשכנזים לר ישכר בר אילנבורג בבקשה לכהן כרבם."},{"i":32280,"n":"משה חזקיה הלוי מפיסארו","f":"יצחק","b":"תשובה ממנו אצל ר אליקים ממציראטא."},{"i":32281,"n":"משה חיים אפרים מסדילקוב","f":"יחיאל","k":"בעל דגל מחנה אפרים","bt":"תקח","dt":"תקס - יז אייר","b":"נכד הבעשט, וגדל אצלו, תלמיד המגיד ממזריטש ור יעקב יוסף מפולנאה. רב בסדילקוב, עבר למז'בוז'-תקמח. בניו ר יצחק מקאליס, ר יוסף ור יעקב יחיאל, חתנו ר דוד הלוי הורביץ מסדילקוב.","bk":[["דגל מחנה אפרים","חסידות"],["דגל מחנה אפרים - עה\"ת",""]],"e":"תק\"ב-תק\"ס"},{"i":32282,"n":"משה חיים הלוי מואלאסי","b":"אב\"ד ואלאסי, מכתב ממנו-תרפו אל ר יוסף הכהן ראויטש מברסטוביץ."},{"i":32283,"n":"משה חיים יצחק מלבוב","b":"פרסם מאמרים ב\"הנשר\" - טירנוי תרצג-תשד."},{"i":32284,"n":"משה חיים מבוסקוביץ","b":"תלמיד החוזה מלובלין, ר יצחק משה עזריאל ליכט מבלזיץ, ר מנחם מנדל מקוצק."},{"i":32285,"n":"משה חיים מחברון","f":"דב בר","b":"מראשוני חסידי חב\"ד בחברון. חתם-תקצד על כתב שליחות ר נתן עמרם."},{"i":32286,"n":"משה חיים מנישוויז","b":"חסיד לכוביץ. עלה לארץ-תקצח."},{"i":32287,"n":"משה חיים עובדיה משלוניקי","b":"מחכמי שלוניקי. חתם-שכט על מכתב התמיכה של רבני קושטא ומצרים בדון יוסף נשיא."},{"i":32288,"n":"משה חיים שבתי משלוניקי","f":"חיים שבתי - הרח\"ש","k":"בעל תורת משה","bt":"שעה-פה","bp":"שלוניקי","dt":"תמה - יד-ז אלול","dp":"שלוניקי","b":"ראש ישיבת ק\"ק שלום-תז על מקום אביו, דייין בשלוניקי-תח, רב הכולל על מקום ר חסדאי הכהן-תלח. חתם-תכה כדיין עם ר בנימין עשאל ור אברהם ן יעש. חתנו - ר אליהו קובו, בנו - ר דוד חיים - גביר בשלוניקי. נשאל מאת ר אפרים הכהן מבודון בידי חתנו ר יעקב מוילנא שהגיע לשלוניקי."},{"i":32289,"n":"משה חנן מפטרץ","b":"רב בפטרץ-שנות ה-ש'."},{"i":32290,"n":"משה חננאל מקושטא","b":"ממונה על איסור והיתר בקושטא-תרלט, דיין-תרמא. חתם-תרלב על המלצה לר אברהם גירון שרצה לעלות לירושלים. הסכים על \"מעשה נסים\" לר משה יצחק הלוי מסופיה."},{"i":32291,"n":"משה חריף הכהן מגאלוב","f":"מתתיהו מראביטש","bt":"תקנד","dt":"תקצא","b":"תלמיד ר עקיבא איגר. רב בגאלוב-פלך פוזנא-תקפ, נפטר צעיר כאשר מסר נפשו לעצור המגיפה (לאחר שהתפלל בערב יום כפור להיות כפרתן של ישראל). ר עקיבא איגר המליץ עליו לקהלת הנובר (כך במכתבו אל ר עקיבא איגר-תקפה). אחיו - ר מיכל ליב (יחיאל אריה) מונק הכהן מדנציג בעל מעלות יחיאל. שני האחים נזכרים ב'מאורן של ישראל' כתלמידי ר עקיבא איגר."},{"i":32292,"n":"משה חריף מואבולניק","bt":"תקמא","dt":"תרלד","b":"תלמיד ר חיים מוולוזין. רב בואבולניק."},{"i":32293,"n":"משה חריף מלבוב - א","f":"ישראל מלובלין","k":"בעל סדר גיטין","bp":"אולינוב?","dp":"אולינוב","b":"רב בלבוב-שס ור אברהם יוסף יעקב קצנלנבוגן על מקומו אחריו (לאחר שר משה ויתר על הרבנות לטובתו), אולינוב, קרמניץ. חיבר \"סדר גיטין\". חתניו - ר שבתי בעל \"ווי העמודים\", ר מנחם מנדל מרגליות מפרמישלא (בזיוו\"ש)."},{"i":32294,"n":"משה חריף מקאליש","b":"רב בסאכטשוב-תק\"פ"},{"i":32295,"n":"משה חריף סגל מלבוב ופולנאה","f":"שלמה מפולנאה ולבוב","b":"חתן ר נתן נטע כהנא מאוסטרהא. רב בלבוב, פולנאה-תע. בנו - ר יוסף מפרמישלא ולבוב."},{"i":32296,"n":"משה יהודה ליב בן יעקב מססוב","dt":"ה'תקסז 1807","bk":[["חידושי הרמ\"ל",""],["חמדה גנוזה",""],["ליקוטי רמ\"ל",""],["לקוטי רמ\"ל",""],["תורת הרמ\"ל השלם",""]]},{"i":32297,"n":"משה יהודה ליב הכהן מאמשטרדם","f":"קלונימוס","k":"ליב חריף","dt":"תסז - יד-ט טבת","b":"רב קהלת האשכנזים באמשטרדם-תמה על מקום ר דוד לידא. תשובותיו בספרי חכמי דורו ובהם - \"אבן השוהם\". הסכים על \"מנחת יצחק\", \"מורה צדק\", \"פרי חדש\" ועוד ספרים רבים שנדפסו באמשטרדם."},{"i":32298,"n":"משה יהודה ליב מאוסטרהא","f":"יהודה ליב","dt":"תקעב - יח אייר","dp":"אוסטרהא","b":"נולד אחר פטירת אביו וגדל אצל ר ישראל בן הרב מזוויהל. מחכמי אוסטרהא וגבאי הח\"ק."},{"i":32299,"n":"משה יהודה ליב ממינסק","k":"בעל מילי דאבות","bp":"טורעץ-ליד מיר","dt":"תרמט - כט סיון","dp":"מינסק","b":"חתן ר דוד טבלי ממינסק בעל \"בית דוד\". מו\"ץ במינסק, ויחד עם חבריו ר אריה רבינוביץ בעל \"באר היטב\", ור גרשון תנחום ביליצקי בעל \"אילנא דחיי\" - מנהיגי קהלת מינסק בזמן שבין רבנות ר דוד טעביל בעל \"בית דוד\" ועד למינוי של הגדול ממינסק. חיבר גם \"מילי דנזיקין\". יחד עם גיסו - ר שאול חיים מדוברובנא בהדפסת ספרי חותנם. בניו - ר יעקב ממינסק, ר שמואל. חתנו - ר יעקב וישנבסקי."},{"i":32300,"n":"משה יהודה ליב מקוטנא וירושלים","f":"ראה: זילברברג, משה י"},{"i":32301,"n":"משה יהודה מסקאלקא","b":"רב בסאקאלקא, הסכים-תרסה על \"חמדת ימים\" לר קלמן חיים מיטקס."},{"i":32302,"n":"משה יהודה סגל (במברגר)","b":"רב בנקרבישופסהיים-תקם. בנו - ר יעקב במברגר מוורמייזא."},{"i":32303,"n":"משה יהושע השל מדינוב","k":"בעל נפלאות רבי יהושע","dt":"תקעג","b":"תלמיד ר לוי יצחק מברדיטשוב. רב בדינוב. חיבר \"נפלאות רבי יהושיע\" פשמישל תרצז."},{"i":32304,"n":"משה יהושע זליג הכהן מהאזנפוט","f":"מנחם מנדל מפילטן","dt":"תריג - יד סיון","dp":"ירושלים","b":"תלמיד ר חיים מוולוזין, למד עם גיסו ר יהושע זליג אשכנזי. גביר תלמיד חכם, רב בגולדינגן, אב\"ד בהאזנפוט(=הזנפורט)-קורלנד-תקצט בערך, עלה לירושלים-תריב. חיבר צוואה לבניו - ונדפסה. (תאריך פטירתו אצל אווצינסקי - טו אב). מבניו - ר אוריה הכהן, ר אברהם, חתנו - ר שמואל ליכטנשטין."},{"i":32305,"n":"משה יהושע מדויד הורודוק","f":"זאב וולף מדויד הורוד","k":"אדמור מדויד הורודוק","b":"תלמיד ישיבת וולוזין, לידא. נספה בשואה. אדמור בדויד הורודוק."},{"i":32306,"n":"משה יהושע נאיישטדטער מוילנא","f":"בנימין בינש ניישטדטר","k":"יהושע'לע נאישטאדטער","bp":"עיר חדש","dt":"תריא - יא אייר","dp":"וילנא","b":"חתן ר זעלמעלע מוילנא (שאחר שנתייתמה גדלה אצל דודה ר חיים מוולוזין). גביר מחכמי ניישטט-ליטא. ר\"מ בוולוזין, גבאי ור\"מ בישיבת מייליס בוילנא, וחתם על כתב התמנות ר ישראל סלנטר לראש הישיבה, על מקום ר מרדכי מלצר. עסק גם במסחר והיה פרנס מראשי הקהל. בניו: ר שלום אב\"ד יאנושק בעל \"דברי שלום ואמת\", ר ביינש מראסיין - הו\"ל כתבי אחיו בשם \"דברי שלום ואמת\". אחיו - ר ברוך מסוגינדט."},{"i":32307,"n":"משה יהושע רופא מלובלין","f":"אברהם","dt":"תד - יז תשרי","dp":"לובלין","b":"רופא מחכמי לובלין."},{"i":32308,"n":"משה יום טוב מחברון","b":"מחכמי חברון, בשנת תקץ בשליחות בתורכיה, בתקצד חתם לר מנחם בורלה."},{"i":32309,"n":"משה יונה מוילנא","b":"פרוש,רב בווילנה-תר\"ל"},{"i":32310,"n":"משה יונה ממצרים","b":"מגדולי רבני מצרים-ש\"נ"},{"i":32311,"n":"משה יונה מצפת","b":"מחכמי צפת-שנות ה-ש'."},{"i":32312,"n":"משה יונה מקהיר","b":"מקובל מחכמי צפת, ועבר לקהיר. ויש המיחסים לו את הספר \"כנפי יונה\" ו\"שער הכללים\" המובא ב\"עץ חיים\". תשובה ממנו בשות ר חיים כפוסי."},{"i":32313,"n":"משה יונה משוראני","dt":"תקמד - כח סיון","b":"רב בשוראני"},{"i":32314,"n":"משה יוסף","f":"שמואל","k":"יוזביל שפרינץ,מפפד\"מ","b":"מחכמי פפד\"מ-שכה, חתם לצד ר אליעזר טרוויש וחכמי פפד\"מ על מכתב לרבני שוואבן בנוגע למחלוקת בין ר שמעון גינצבורג בתמיכת ר יצחק איזיק גינצבורג לבין ר נתן שאטין בתמיכת ר אליעזר טרוויש מפפד\"מ."},{"i":32315,"n":"משה יוסף מאוסטרהא","f":"משלם זלמן","dt":"תקטז - ח טבת","dp":"אוסטרהא","b":"מחכמי אוסטרהא. אביהם של ר זלמן מעזריטשער מאוסטרהא, ור אריה ליב מעזריטשער."},{"i":32316,"n":"משה יוסף מואנדסבק","f":"אברהם","dt":"תקיב - ט תמוז","dp":"ונדסבק","b":"נהרג עק\"ה."},{"i":32317,"n":"משה יוסף ממזיבוז","b":"מג\"מ במזיבוז-תקט\"ו"},{"i":32318,"n":"משה יוסף משלוניקי","k":"ניל קהין","dt":"שעא - י אדר","dp":"שלוניקי","b":"מחכמי שלוניקי."},{"i":32319,"n":"משה יחזקאל","f":"אפרים פישל","b":"רב-שנת תק\"ע"},{"i":32320,"n":"משה יחזקאל די, יחזקאל","bt":"תרכג","bp":"בומבי","b":"רב בבומבי-הודו-תרמו. חוקר לשון עברי. פרסם מאמרים ב\"אוצר ישראל\", תפלות מיוחדות, הספד על מלך אנגליה."},{"i":32321,"n":"משה יחזקאל מירושלים","f":"יואל","dt":"תרכב - כה חשון","dp":"ירושלים","b":"מחכמי ירושלים."},{"i":32322,"n":"משה יחזקאל מסלונים","b":"מרביץ תורה בסלונים"},{"i":32323,"n":"משה יחיאל","b":"רב-שנת תר\"מ"},{"i":32324,"n":"משה יחיאל מיכל","f":"אליעזר פישל","dt":"תקלה","b":"רב בביאלא-תק\"צ,הורדנא"},{"i":32325,"n":"משה יחיאל מיכל הכהן מראדום","bt":"תרכד","dt":"תרצו - כד תשרי","b":"מו\"צ בוורשה,ראדום"},{"i":32326,"n":"משה יעקב הירש","f":"אברהם מליסא ופפד\"מ","k":"מפפד\"מ","b":"בנו של רבה של פפד\"מ. מחכמי פפד\"מ-תקל."},{"i":32327,"n":"משה יעקב הכהן מאלטונא","f":"אליהו בן דוד מאלטונא","dp":"אלטונא","b":"נכד ר דוד בן מנחם הכהן בעל \"מזמור לתודה\"."},{"i":32328,"n":"משה יעקב הכהן מקושטא","b":"מדפיס-תצו בדפוס של יונה בן יעקב בקושטא."},{"i":32329,"n":"משה יעקב מארטא","b":"רב בארטא על מקום ר אליעזר מנחם-שנות ה-ת'."},{"i":32330,"n":"משה יעקב מבצרה","b":"דיין בבצרה-עירק-תקס, יחד עם ר אברהם בן נתן ור אברהם בן דוד טוויג שחתמו עמו. ונזכר ב\"דבר משה\" לר משה חיים."},{"i":32331,"n":"משה יעקב מבריגל","k":"בעל אבן הבוחן","b":"חיבר \"אבן הבוחן\" פוגורזע תרן."},{"i":32332,"n":"משה יעקב מטושוויץ","b":"רב בטושוויץ."},{"i":32333,"n":"משה יעקב מצפת","b":"מחכמי צפת, וחתם-תרנה על אגרת לחכמי מכנאס בענין ה\"גאבילה\", עם חבריו ר יוסף יהודה חכים הרב הראשי בצפת. ונדפס בספר תקנות חכמי מכנאס."},{"i":32334,"n":"משה יעקב מקראקא","b":"רב בחנטשין-תע\"ג,אפטא-תצ\"ג"},{"i":32335,"n":"משה יעקב מקשונז","f":"יעקב מאפטא","k":"ר' משה מאפטא,חתן המאור ושמש","bt":"תקכג","dt":"תקצג - יא תשרי","b":"חתן ר קלונימוס קלמן בעל \"מאור ושמש\". אב\"ד קשונז."},{"i":32336,"n":"משה יעקב נתן מהעלישט","b":"חתם בפנקס קהלת לבוב-שפו."},{"i":32337,"n":"משה יצחק הכהן מירושלים","f":"בצלאל","b":"חתם-תקצו על רכישת חצר עבור כולל הפרושים עם ר אברהם מחסלביץ ור אברהם ברי\"צ אשכנזי."},{"i":32338,"n":"משה יצחק הלוי מזלאטווי","f":"יחזקאל הלוי","dt":"תקנז - כב תשרי","b":"מקובל,רב בזלאטווי-תקט\"ו,פרוורהא"},{"i":32339,"n":"משה יצחק הלוי מירושלים","b":"מחכמי ירושלים-שנות ה-תק'."},{"i":32340,"n":"משה יצחק הלוי מפירוט וסופיה","f":"יצחק","k":"בעל מעשה נסים","dt":"תקפט","dp":"סופיה","b":"רב בקסטוריאה, פירוט(=שיאיר-קיווי)-תקן (או תקעב), פיליבי-תקעט על מקום ר אהרן אברהם ן ארוליא ור רחמים אברהם וינטורא על מקומו אחריו, סופיה-תקפא (מרוזניס משמע שנתמנה בסופיה על מקום ר רחמים אברהם וינטורא שהחליפו בפיליבי). בניו: ר יצחק מסופיה, ר מאיר מבגדד, ר אברהם מסופיה, ר יעקב - נהרג עק\"ה צעיר. חתניו: ר יום טוב הלוי, ר יוסף מולכו, הגביר ר יהודה אריה מסאמאקוף, ר שלמה ברכה. בתו רחל יהודה אריה בעזרת ר אברהם הכהן מסמאקוף(=סאמאקוף) הו\"ל מכתביו את ספרו \"מעשה נסים\" - פרשבורג תרלד - כך לפי רוזניס) ושאר כתביו היו בידי בני משפחת אריה מסאמאקוף וסופיה, ואבדו."},{"i":32341,"n":"משה יצחק המגיד מקלם","f":"נח דרשן","k":"המגיד מקלם-תוכחות חי","bt":"תקפח","bp":"אוזרניצה-פלך גרודנא","dt":"תרנט","b":"תלמיד ישיבת סלונים, ותלמיד ר ישראל סלנטר ששלחו להיות מגיד. מגיד בקלם-תרי, זאגר, אושמיאנה, מינסק (בהזמנת ר איזל חריף שהיה הרב שם), ובמקומות נוספים, ולבסוף ויתר על משרה קבועה והיה נודד ממקום למקום ומעורר את הציבור בדרשותיו, היה דורש שעות ארוכות והמונים היו מצטופפים לשמוע. ייסד חברות ללימוד תורה ובהם \"חיי אדם\", \"לינת הצדק\", משמרת חולים, קופת גמ\"ח לבעלי מלאכה, וחברות לעזרה הדדית. בערים רבות שברו את המדות והמשקולות המזוייפים לאחר ביקורו, סופר אחד סיפר כי אחר דרשת המגיד בעירו התאבד חנווני אחד שנהג לזייף את המידות. היה במחלוקת עם המשכילים ונרדף על ידם וכמה פעמים נאסר בגלל הלשנות. הגיע ללונדון לפעול אצל המהגרים, וסיר מונטגיו והרב הראשי קרבוהו והוקירו את פעולתו. בסוף ימיו התישב בלידא."},{"i":32342,"n":"משה יצחק מהוסיאטין","b":"רב בהוסיאטין."},{"i":32343,"n":"משה יצחק מליטא","dt":"תרסב","b":"מגדולי חכמי דורו, רב בטאווריג, פוניבאז, פלונגיאן."},{"i":32344,"n":"משה יקותיאל זלמן מדוקלא","f":"שמחה","b":"רב בדוקלא. מצאצאי ר שמחה דוקטור בן יעקב מאיטליה (שעבר לגליציה)."},{"i":32345,"n":"משה יקותיאל זלמן מקראקא","dt":"תקלה - טו סיון","b":"דיין בקראקא"},{"i":32346,"n":"משה יקותיאל מקושטא","b":"ממונה על איסור והיתר בקושטא-תקעז, ודיין בדיני אישות. פסק ממנו מובשא ע\"י ר יצחק הלוי מקושטא."},{"i":32347,"n":"משה ישראל איסר מפינסק","f":"אליהו מפינסק","dt":"תקמ - כד אד\"א","dp":"אוסטרהא","b":"נכד ר ישראל איסר אב\"ד פינסק. מגדולי אוסטרהא ונפטר צעיר. על מצבתו נכתב. \"עושה פלא\" - דבר נדיר בדור ההוא."},{"i":32348,"n":"משה ישראל מאדרינופול","b":"מחכמי אדרינופול - בזמן הרא\"ם - שהתארח בביתו בהיותו באדרינופול."},{"i":32349,"n":"משה ישראל מדריסא וגריווא","f":"מרדכי מליעפלי","b":"תלמיד הצמח צדק, ושליחו לעניני החסידות, ואחריו חסיד בנו רדי\"ל מקאפוסט ואחריו רש\"ז מלאדי. הגיע לגריווא עם ר יחזקאל יאנובר והפכוה לעיר חסידית."},{"i":32350,"n":"משה ישראל מסמרקנד","f":"יצחק","b":"סופר בסמרקנד-בוכרה-תרצג."},{"i":32351,"n":"משה ליב ממאהילנא","b":"מצאצאי בעל \"שלחן שלמה\". רב במאהלינא(=מאהילנא)-פלך מינסק. נכדו - ר משה ליב ברנשטין מארה\"ב."},{"i":32352,"n":"משה ליב ממעזאטור","b":"רב במעזאטור-תר\"ו"},{"i":32353,"n":"משה ליב מפאקשן","k":"אדמור מפאקשן","b":"הסכים על \"בית ועד לחכמים\" - יאסי תרסט."},{"i":32354,"n":"משה ליב מפעזינג","b":"רב בפזינג-ת\"ר"},{"i":32355,"n":"משה ליזרס מבריסק וילנא","f":"אליעזר","b":"גביר מחכמי בריסק-שנות ה-ת', וילנא. סייע בהדפסת ש\"ס לובלין-שעז-שצט. בניו - ר ישעיה, ר יעקב אליעזר. (עליו בדקדוקי סופרים)."},{"i":32356,"n":"משה מאבאני","b":"רב באבאני-תק\"פ"},{"i":32357,"n":"משה מאברטין","b":"תלמיד המגיד מזלוטשוב. גיסו של ר משה יהודה ליב מסאסוב. מתורתו בספרי ר אברהם דוד מבוצאץ."},{"i":32358,"n":"משה מאדרינופול","f":"ציון","b":"רב באדרינופול-רע."},{"i":32359,"n":"משה מאונסדורף","f":"ברש\"ש","b":"מחכמי אונסדורף-תקלא."},{"i":32360,"n":"משה מאוסטרהא","f":"יוסף","dt":"תקסט - א אב","dp":"אוסטרהא","b":"מחכמי אוסטרהא, נספה בשרפה."},{"i":32361,"n":"משה מאוסטרהא","dt":"תח","b":"עק\"ה,מקובל באוסטרהא"},{"i":32362,"n":"משה מאוסטרהא","f":"יודיל חסיד מאוסטרהא","dt":"תקלה - ל תשרי","dp":"אוסטרהא","b":"בנו של ר יעקב יהודה חסיד מאוסטרהא. מחכמי אוסטרהא."},{"i":32363,"n":"משה מאוסטרהא","f":"דב בר","dt":"תקסב - ד אד\"א","dp":"אוסטרהא","b":"מחכמי אוסטרהא."},{"i":32364,"n":"משה מאורזיסטשוב(=ראזיסטשוב)","f":"פנחס מאוסטרהא","k":"אדמור מאורזיסטשוב","dt":"יט אלול","b":"נכד רב ייבי. חתן ר אברהם מסדילקוב בן ר בנימין זאב וולף מבאלטא. נתייתם בילדותו וגדל אצל ר יהודה ליב משפולא. כיהן כאדמור באורזיסטשוב(=ראזיסטשוב)-פלך קיוב. בנו ר אברהם."},{"i":32365,"n":"משה מאזמיר","f":"יעקב שאול","dt":"תצח - יז סיון","dp":"אזמיר","b":"רב באזמיר-שנות ה-ת'."},{"i":32366,"n":"משה מאיבניצא","b":"תלמיד הבעשט. בנו ר אליהו דב חתן ר גדליה מליניץ."},{"i":32367,"n":"משה מאיוונקוב","b":"רב באיוונקוב-תר\"מ"},{"i":32368,"n":"משה מאיטליה","f":"יקותיאל","b":"מגדולי חכמי איטליה-שנת ס'"},{"i":32369,"n":"משה מאייברא","b":"מגדולי בעלי התוספות בחכמי צרפת,ראש ישיבה באייברא-נורמנדיה(ד'תתק\"ס)"},{"i":32370,"n":"משה מאיר השבתאי","b":"שליח השבתאים במנהיים-תפה, הגיע לפפד\"מ ושם נלקחו ממנו כתביו."},{"i":32371,"n":"משה מאיר מאדרינופול","b":"רב באדרינופול - בדור שאחר הגירוש."},{"i":32372,"n":"משה מאיר מטיסמניץ","b":"רב בטיסמניץ-תרי, בירטש."},{"i":32373,"n":"משה מאיר מפדובה","b":"תשובה ממנו בשות מהרם פרובנצאל - בכת\"י."},{"i":32374,"n":"משה מאיר מצפת","f":"יעקב","b":"מחכמי צפת, חתם בשנת שפא על מכתב לר ישכר בר איילנבורג."},{"i":32375,"n":"משה מאיר מקוניב ואוסטרהא","f":"יעקב","dt":"תקעח - ה אד\"ב","dp":"אוסטרהא","b":"אב\"ד קוניב(=קינין), הגיע לאוסטרהא."},{"i":32376,"n":"משה מאישישוק וירושלים","f":"שלמה","dt":"תרכב - ב ניסן","dp":"ירושלים","b":"מחכמי ירושלים. בנו - ר אליהו סטרעלצר מירושלים."},{"i":32377,"n":"משה מאלגיר","f":"חיים שניאור","bt":"[קע]","dt":"רן - בערך","b":"רב בבג'איה-אלגיר ובזמן הרשב\"ש שהשיב לו בספרו. היה מחלוקת בינו לר דוד הכהן מבג'איה והגיע לידי נידוי."},{"i":32378,"n":"משה מאליסינה -","f":"יוסף","b":"תרגם מערבית פירוש רבינו סעדיה לספר יצירה ופירוש רבינו נסים - בכת\"י."},{"i":32379,"n":"משה מאלסק","f":"חנוך הניך מאלעסק","b":"רב באלעסק-תר\"נ"},{"i":32380,"n":"משה מאלקסוט","f":"אברהם","b":"שו\"ב באלקסוט-תרמח, חתם על כתב סמיכה לשוחט."},{"i":32381,"n":"משה מאלשאן","f":"מנחם מנדל מאלשאן","b":"אב\"ד אלשאן על מקום אביו. אחיהם של - ר אברהם יצחק מוישנובה, ר יוסף מואלקוניק."},{"i":32382,"n":"משה מאמטשסלב","b":"מ\"מ בזאריק-תק\"י"},{"i":32383,"n":"משה מאמשטרדם","k":"ואה\"ו","b":"חתם באה\"ו-תקל על פס\"ד של ר דוד ברלין, יחד עם ר יצחק איזיק בן ליב (אולי הם דיינים אצלו)."},{"i":32384,"n":"משה מאניס מקמפנא","b":"רב בקמפנא-תקס. חתנו - ר אלכסנדר סנדר בן ר אריה ליב בן ר שמואל לסקר מלוסק."},{"i":32385,"n":"משה מאנשבך","f":"יעקב","b":"רב מדינת אנשבך-תקפ. (ראה גם משה קצנלנבוגן - בנו של ר שאול)."},{"i":32386,"n":"משה מאסלאפא","b":"רב באסלאפא-תקע\"ה"},{"i":32387,"n":"משה מאשיל מלבוב","b":"ראש מדינה בגליל לבוב, חתם-תמז ביריד ירוסלב."},{"i":32388,"n":"משה מאשכנז","f":"יהודה החסיד","b":"מגדולי חכמי אשכנז-ד'תתק\"צ"},{"i":32389,"n":"משה מאשקה מלבוב","f":"חיים","dt":"תכד - ח אייר","b":"מרביץ תורה בלבוב. נהרג עק\"ה."},{"i":32390,"n":"משה מבאדירש","f":"יהודה","b":"מגדולי חכמי דורו"},{"i":32391,"n":"משה מבאייעב וליפעלי","f":"ישראל ברוך מליאזני","b":"אחיו של בעל התניא. רב בבאייעב, ליפעלי."},{"i":32392,"n":"משה מבארלאד","b":"אב\"ד באראלד-תקצח."},{"i":32393,"n":"משה מבבל וספרד","dt":"ד'תשפה","b":"מגדולי הדור,מארבעה שבויים שבאו מישיבות בבל והפיצו תורה בארצות המערב,ראש ישיבת קורדובה"},{"i":32394,"n":"משה מבגדד","f":"יחזקאל ראובן ששון","b":"גביר בבגדד, סייע בבנין ה\"חורבה\" בירושלים יחד עם אחיו ששון - לפי צוואת אביהם."},{"i":32395,"n":"משה מבוברויק וצפת","b":"מדפיס בצפת-תרלו עם ר צבי שפיגלמן ור מנחם וידברג, הדפיס \"זמרת הארץ\" - תרלו, בהמשך פרש מהשותפות."},{"i":32396,"n":"משה מבוטשטש וזולקוא","b":"אב\"ד בוטשטש, דיין בזולקוא, הסכים על שו\"ע עם באר היטב - זולקוא תקב יחד עם דייני זולקוא."},{"i":32397,"n":"משה מבוקרשט","b":"מחכמי ארץ ישראל."},{"i":32398,"n":"משה מבוקרשט וירושלים","f":"דוד","dt":"תריג - יט אב","dp":"ירושלים","b":"רב בבוקרשט, עלה לירושלים."},{"i":32399,"n":"משה מביהם","f":"יעקב","k":"ר' משה בן יעקב מביהם","b":"מגדולי חכמי ביהם,מבעלי התוספות-ד'תתק\"צ"},{"i":32400,"n":"משה מבינגן","b":"מחכמי בינגן. חתם על תקנות אסיפת הרבנים בפפד\"מ-שסג."},{"i":32401,"n":"משה מבלגרד","f":"נחמן","b":"רב בבלגרד-שנות ה-ש'."},{"i":32402,"n":"משה מבלז","f":"זכריה מנדל","b":"רב בבעלז-ת\"צ"},{"i":32403,"n":"משה מבלקייר-ספרד","f":"שלמה","b":"רב בסלמנקה-ספרד-ן' עם חברו ר שניאור אשטרוק די נייס. רבו של ר קלונימוס בעל \"אבן בוחן\"."},{"i":32404,"n":"משה מברדטשין","b":"תלמיד ר מנחם מ נדל מקוסוב."},{"i":32405,"n":"משה מברדיטשוב","f":"אליעזר הלוי","b":"מגדולי ונכבדי ברדיטשוב-תק\"ע"},{"i":32406,"n":"משה מבריסק","f":"הירץ","b":"מגדולי חכמי בריסק-ת\"צ"},{"i":32407,"n":"משה מבריסק","f":"יצחק","k":"בעל מפרש חטאים","b":"רב בבריסק. חיבר \"מפרש חטאים\" ונציה. נלקח בשבי הטטרים."},{"i":32408,"n":"משה מבריסק","dp":"הורדנא","b":"נכד הרבי ר השלי. ראש ישיבה בבריסק, אב\"ד הורדנא, קראקא-תמ?"},{"i":32409,"n":"משה מבריסק וטרספול","f":"מרדכי","b":"אב\"ד טרספול. מחכמי בריסק, נזכר ב\"גבעת שאול\" לר שאול מלומזה. הסכים על \"חדושי מהר\"י (ר יעקב בן לוי מבריסק)-תקמח."},{"i":32410,"n":"משה מברישטול","b":"מגדולי הראשונים"},{"i":32411,"n":"משה מגיד מוילייקה","f":"דב בר","dt":"תר - כג אלול","b":"חתן ר מרדכי מלכוביץ. עלה לארץ-תקצו ועמד יחד עם ר שאול הולוי הורוקר בראש \"כולל רייסין\". בניו ר מרדכי ור אהרן שמואל - עלו אתו."},{"i":32412,"n":"משה מגראן","b":"רב בגראן-תקע\"ה"},{"i":32413,"n":"משה מדאמאן","b":"רב בדאמאן-תק\"נ"},{"i":32414,"n":"משה מדוברוונא","f":"מנחם","b":"רב בדוברוונא"},{"i":32415,"n":"משה מדינוב","b":"רב בדינוב-תר\"כ"},{"i":32416,"n":"משה מדינוביץ","k":"בעל הדר מלכות","dt":"תקעז - כה כסלו","b":"גדול בנגלה ונסתר,רב בדינוביץ"},{"i":32417,"n":"משה מדרגיטשין","dt":"תקי - ו אייר","b":"מקובל,איש מופת,רב בדרגיטשין,ראב\"ד בפינסק,עלה לא\"י. חיבר \"מגיד משנה\"."},{"i":32418,"n":"משה מדרישקפאלי","b":"רב בדרישקפאלי"},{"i":32419,"n":"משה מהאלוסק","f":"פנחס שמערינר","b":"נכד(-אבי אמו) ר שמואל תאומים מאלטונא וזאמושט. רב בהאלוסק-תץ. חתניו - ר אהרן קצנלנבוגן, ר צבי הירש הלוי-זקנו של ר אליהו זאב לוין מקרלין."},{"i":32420,"n":"משה מהאלינסק-פודוליה","b":"תלמיד ר אברהם יהושע השל מאפטא. רבים פנו אליו לברכות וישועות."},{"i":32421,"n":"משה מהאם","b":"מחכמי אשכנז. חתם על תקנות אסיפת הרבנים בפפד\"מ-שסג."},{"i":32422,"n":"משה מהורדנא","b":"תלמיד המגיד מקוזניץ, החוזה מלובלין, ור אשר מסטולין, ור אהרן מקרלין."},{"i":32423,"n":"משה מהורדנא","f":"אהרן","b":"רב בהורדנא-שט ?, היה במחלוקת עם ר מרדכי-רבה של הורדנא."},{"i":32424,"n":"משה מהורדנא וירושלים","f":"מאיר","dt":"תקצח - כ סיון","dp":"ירושלים","b":"מחכמי ירושלים."},{"i":32425,"n":"משה מהלישוי וירושלים","f":"מרדכי","b":"מחכמי ירושלים-תסה, חתם אז על מכתב רבני ירושלים כנגד אנשי ר יהודה החסיד."},{"i":32426,"n":"משה מהרשוי","b":"תלמיד הכת\"ס. רב בהרשוי-תרכו. תשובה אליו ב\"כתב סופר\"."},{"i":32427,"n":"משה מואסילקוב","b":"רב בוואסילקוב-תרמ\"ח"},{"i":32428,"n":"משה מוארנוב","b":"רב בווראנוב(=וארנוב)-תקפ\"ג"},{"i":32429,"n":"משה מוארנוב","k":"בעל מאירת אבן - כת\"י","b":"תלמיד החוזה מלובלין."},{"i":32430,"n":"משה מודיסלב","dt":"תקצא - כח סיון","b":"רב בוודיסלב"},{"i":32431,"n":"משה מוויגרשום","k":"בעל דרכוני זהב","b":"רב בוויגרשום. חיבר \"דרכוני זהב\"."},{"i":32432,"n":"משה מווידז","f":"יצחק","b":"גבאי מעות ארץ ישראל בווידז, הגיע מווידז לויטבסק. ברשותו נמצאו כל הקבלות על קבלת כספים מארץ ישראל. (ראה מונדשין יהושע)."},{"i":32433,"n":"משה מויטבסק וטבריה","f":"מנחם מנדל מויטבסק","dt":"תקנט - א ניסן","dp":"טבריה","b":"מחכמי טבריה, עלה עם אביו בשנת תקמא, חתום על אגרות שונות. בנו ר שמואל - נפטר-תקנד לפני נישואיו."},{"i":32434,"n":"משה מויליאמפול-סלובודקה","f":"מנחם מנדל סגל","b":"מראשי קהלת ויליאמפול-תקכב, וחתם על תקנות החברא קדישא-תקכב ותקלו."},{"i":32435,"n":"משה מוילנא","f":"זרח","b":"גבאי ישיבת מייליס בוילנא. חתם על כתב התמנות ר ישראל סלנטר לראש הישיבה, על מקום ר מרדכי מלצר."},{"i":32436,"n":"משה מוילנא","f":"יהודה ליב","dt":"תקמט - כא כסלו","dp":"וילנא","b":"סו\"ד קהילת וילנא בזמן המחלוקת עם ר שמואל בן אביגדור-רבה האחרון של וילנא."},{"i":32437,"n":"משה מוילנא","f":"אברהם אשר","k":"משה חצקל'ס","dt":"תקסב - כג חשון","dp":"וילנא","b":"מראשי קהילת וילנא. נבחר לראש ועד בן חמשה אנשים שפעל אחרי פטירת הגר\"א כדי ללחום בחסידות, חבירו לועד: ר אריה ליב בן דב בער(=ר ליבלי ר בערס), ר יצחק איזיק בן אברהם הלוי. נפטר ללא ילדים."},{"i":32438,"n":"משה מוילנא","f":"קלמן","b":"חתם בקוליקוב-תן על תקנות קהלת זולקוא יחד עם רבני גליל לבוב."},{"i":32439,"n":"משה מוילנא","f":"יצחק","b":"רב בוילנא, חתם-תסא עם ר הלל בן נפתלי הרץ מוילנא וקידאן."},{"i":32440,"n":"משה מוילנא","f":"שלמה","b":"רב בוילנא, חתם-תסא עם ר הלל בן נפתלי הרץ מוילנא וקידאן."},{"i":32441,"n":"משה מוילנא","f":"מנחם","b":"סו\"ד בוילנא, חתם-תסח עם ר אליהו בן משה קרמר."},{"i":32442,"n":"משה מוילנא","f":"יהודה ליב","b":"רב בוילנא, חתם-תפד עם ר צמח בן יעקב, ר יהודה בן בנימין, ר שמריה בן יוסף א\"ש."},{"i":32443,"n":"משה מוילנא","f":"שלמה","dt":"תקמט - יג סיון","dp":"וילנא","b":"מחכמי וילנא."},{"i":32444,"n":"משה מוילנא","f":"יוסף","dt":"יג אלול","dp":"וילנא","b":"מחכמי וילנא-שנות ה-תק'."},{"i":32445,"n":"משה מוילנא","f":"אברהם","dt":"תקמד - כו טבת","dp":"וילנא","b":"מחכמי וילנא."},{"i":32446,"n":"משה מוילנא","f":"יהודה ליב מוילקומיר","dt":"תקסז - כד אדר","dp":"וילנא","b":"מחכמי וילנא."},{"i":32447,"n":"משה מוילנא","b":"בנו - ר יוסף ונכדו ר יהושע בעל מגיני שלמה."},{"i":32448,"n":"משה מוילקומיר","b":"רב בווילקומיר-תרל\"א"},{"i":32449,"n":"משה מוילקומיר","dt":"תקסז - כד אדר","b":"רב בווילקומיר"},{"i":32450,"n":"משה מוינה (וינר)","f":"נתן","dp":"אלטונא","b":"ממגורשי וינה. חתן ר דוד דיין-אחיו של ר שמעון-אב\"ד פרג."},{"i":32451,"n":"משה מויניצא","b":"רב בויניצא-תק\"י"},{"i":32452,"n":"משה מוישגראד","b":"תלמיד החוזה מלובלין, היהודי הקדוש מפשיסחא, מגדולי תלמידי ר שמחה בונם מפשיסחא, תלמיד חבר לר יצחק מוארקי, ור מנחם מנדל מקוצק."},{"i":32453,"n":"משה מולאדמיר","f":"מנחם מנדל","b":"אב\"ד ולאדמיר-שעט. מחותן עם ר בנימין אהרן סלניק."},{"i":32454,"n":"משה מוסייב משקלוב וטבריה","dt":"תקלט","dp":"טבריה","b":"עלה לארץ-תקלח."},{"i":32455,"n":"משה מזאלושין-יאנוב","f":"גרשון","k":"בעל משפט צדק","bt":"תקמט","dt":"תקצא - כט תמוז","b":"חתן ר יחיאל מיכל מזאלושין(=זלושין)-בן ר שמואל לסקר מלוסק. תלמיד החוזה מלובלין - שהעריכו מאוד. חיבר גם \"סידור תיקון שבת\", ועוד. בנו ר יוסף גרשון מדוואהרט."},{"i":32456,"n":"משה מזאמוטש ולבוב","f":"יהודה זונדל","dt":"תעט - אחרי","b":"דיין בלבוב, חתם-תמו עם ר ישעיה כץ-נכד בעל הסמ\"ע, ר ישעיה בן מנחם קצנלנבוגן, חתם-תמח עם ר שלמה בן צבי הירש קראקובר, ועוד הרבה."},{"i":32457,"n":"משה מזבורוב","k":"בעל ברית אברהם","bt":"תצה","dt":"תקעה - כג אלול","b":"דרשן,מגיד בזבורוב,זאלוזיץ"},{"i":32458,"n":"משה מזוויהל","f":"המגיד מזלוטשוב","k":"אדמור מזוויהל","dt":"תקצא - י אייר","b":"חתן ר דוד ז\"ק מגרבובץ. סירב לאדמורות ולבסוף הסכים בהוראת ר לוי יצחק מברדיטשוב ור מרדכי מנסכיז. מגיד מישרים במזריטש, זוויהל. אחד מ\"חמשה חומשי תורה\" - כפי שכונו בני המגיד מזלוטשוב."},{"i":32459,"n":"משה מזווירש","b":"עק\"ה,רב בזווירש-ת\"כ"},{"i":32460,"n":"משה מזולקוא","f":"דניאל","k":"בעל סוגיות התלמוד","b":"דיין בזולקוא אצל ר יצחק לנדא. חיבר \"סוגיות התלמוד\" זולקוא תצג."},{"i":32461,"n":"משה מזולקוא","f":"אברהם בן מרדכי מזולק","b":"מחכמי זולקוא, חתם-תקיא על החרם לטובת ר יונתן איבשיץ."},{"i":32462,"n":"משה מזולקוא","f":"פרץ","b":"מחכמי זולקוא, חתם-תקם על תקנה שלא לתת שכירות למשרתי הקהל בלי כתב מהקהל."},{"i":32463,"n":"משה מזולקוא","f":"עזריאל","b":"מחכמי זולקוא, חתם-תסד על תקנת הקהלה, ובשנת תפד עם מנהיגי הקהל."},{"i":32464,"n":"משה מזולקוא","f":"שניאור פיבש","b":"מחכמי זולקוא, חתם-תעו על תקנת הקהלה."},{"i":32465,"n":"משה מזולקוא","f":"שכנא","dt":"תיג - כג חשון","dp":"זולקוא","b":"רב באחת הקהלות, עבר לזולקוא."},{"i":32466,"n":"משה מזולקוא","f":"צבי דוד","dt":"תקנו - ט אייר","dp":"זולקוא","b":"אב\"ד בעלז, עבר לזולקוא."},{"i":32467,"n":"משה מזיגל","k":"ר' משה מזיגל","dt":"תשג","b":"רב בקלוועריא(=קלווריה-גליציה?). נספה בשואה."},{"i":32468,"n":"משה מזידיטשוב","dt":"תרלז- ב ניסן","b":"רב בזידטשוב"},{"i":32469,"n":"משה מזיטומיר ואוסטרהא","f":"אליהו מפינסק","dt":"תקיג - לפני","b":"רב בזיטומיר, ראש הגליל באוסטרהא-תפ - על מקום ר ישראל חריף הלפרין ולפני בנו ר דוד. הסכים על \"תנא דבי אליהו\" לאחיינו ר אליהו פינס משקלוב."},{"i":32470,"n":"משה מזלטיפול","b":"רב בזלאטיפאלי-תר\"ע"},{"i":32471,"n":"משה מזמושטש","b":"רב בזאמושטש-ת\"פ"},{"i":32472,"n":"משה מזנטא-הונגריה","f":"אורי שרגא פיבל","dt":"תקעג - כז תמוז","b":"בנו של בעל \"אור החכמה\". חתן ר חיים פולק מבריגל-תלמיד ר יונתן אייבשיץ. רב בזענטא(=זנטא)-הונגריה, מראשוני החסידים בהונגריה. חתנו ר יעקב מפיאסק."},{"i":32473,"n":"משה מחברון","f":"גבריאל","bp":"סופיה","b":"עלה לחברון בשנת תקעג, בשנת תקפא בשליחות בחברון."},{"i":32474,"n":"משה מחליש מקראקא","b":"דרשן,דיין בקרקא-ת\"ס"},{"i":32475,"n":"משה מטבריה","f":"אהרן","b":"ממונה כולל רייסין בטבריה-תרטו."},{"i":32476,"n":"משה מטולנא","b":"רב בטאלנא-תר\"י"},{"i":32477,"n":"משה מטיבולי","k":"בעל ימין משה?","b":"חיבר הגהות והשגות על הבית יוסף. חתום על פסק מהריב\"ל יחד עם ר משה הכהן מאלכסנדריה, ונזכר בשות מהראנ\"ח. אולי הוא המחבר \"ימין משה\""},{"i":32478,"n":"משה מטלז מ\"אגודת חסידים\"","dt":"תקע","dp":"טלז","b":"בסוף ימיו אב\"ד טלז. ר משה היה אחד מהחבורה של שלשה רבנים שנקראה \"אגודת חסידים\" ובה גם ר שמואל בן ברוך מז'אמוט, ור מרדכי מפוקרוי - שבמשך 15 שנה עשו אגודה אחת להתנזר מכל הנאות שבעולם ולמדו תורה בחסידות ובפרישות. מתורתם בספר \"זכרון יעקב\" לר יעקב בנדטמן בשם \"תורת חסידים\"."},{"i":32479,"n":"משה מטפלטשין","b":"רב בהונגריה-תרכה, מכתב ממנו כנגד הרב הריפורמי ד\"ר יהודה לעף מסנדין - עם חתימות חבריו ר יוסף ברייער, ור דוד נוסנבוים."},{"i":32480,"n":"משה מטריד","dt":"תקמח - א אב","b":"רב בטריד"},{"i":32481,"n":"משה מטריפולי","f":"נסים","bt":"קן","dt":"רך - בערך","b":"רב ומעתיק ספרים בלוב. העתיק משנה תורה לרמב\"ם. נזכר ב\"אסופות כתבים עבריים\" ירושלים תשסב."},{"i":32482,"n":"משה מטריפולי-לבנון","f":"מאיר","b":"רב בטריפולי-לבנון-שנות ה-ש'."},{"i":32483,"n":"משה מטריקולה","f":"חנין בן פרחיה מטריקו","b":"רב בטריקולה. נזכר בשו\"ת ר מאיר קצנלנבוגן-מהר\"ם מפדובה."},{"i":32484,"n":"משה מטשרניגוב","k":"ר' משה מארימוב","b":"רב בטשרניגוב-תר\"כ"},{"i":32485,"n":"משה מיאנוב","b":"רב ביאנוב-תק\"צ"},{"i":32486,"n":"משה מיורבורג","f":"ראובן","k":"בעל נאדר בקדש","b":"זקנו - נהרג עק\"ה, ועל כך ב\"שבט אלוה\" לסופר מרדכי פלונגיאן."},{"i":32487,"n":"משה מיכל מביאלא","f":"אליעזר פישל מסטריזוב","dt":"תרטו","b":"תלמיד החוזה מלובלין-תקעג, ר שמחה בונם מפשיסחא, ר מנחם מנדל מקוצק. גביר עשיר וכשהתרושש קיבל עליו רבנות - רב בביאלא."},{"i":32488,"n":"משה מימון מקרית אתא","k":"בעל הלכה למשה","b":"רב בקרית אתא-תשיח."},{"i":32489,"n":"משה מירושלים","f":"דוד","b":"מחכמי ירושלים, בשנת רסט חתם על התקנה לשחרור תלמידי חכמים ממס."},{"i":32490,"n":"משה מירושלים","f":"יהושע","b":"מחכמי ירושלים, בשנת תסז חתום על כמה אגרות."},{"i":32491,"n":"משה מירושלים","f":"יצחק","b":"מחכמי ירושלים בזמן הנגיד, חתם בשנת תרסט על תקנת המס."},{"i":32492,"n":"משה מירושלים","f":"שבתי","dt":"תקס - כז ניסן","dp":"ירושלים","b":"מחכמי ירושלים, חתנו של ר יעקב אשכנזי די קורונא, בשליחות בשנת תקנא. הדפיס את הספר \"לב שמח\" לר אברהם אליגרי, ועוד. אולי הוא שחיבר הקדמה ל\"אור צדיקים\" - שלוניקי תקנט."},{"i":32493,"n":"משה מירושלים","f":"צבי הירש","b":"מחכמי ירושלים-תסה, חתם אז על מכתב רבני ירושלים כנגד אנשי ר יהודה החסיד."},{"i":32494,"n":"משה מירושלים","f":"אברהם","dt":"תרל - כו סיון","dp":"ירושלים","b":"מחכמי ירושלים."},{"i":32495,"n":"משה מירושלים","f":"מהר\"ש","k":"בעל דרך משה","b":"מחכמי ירושלים-שנות ה-ת'. בספרו מביא בשם ר יונה מקעלין, ומחותנו זקנו - ר אברהם וורטר מליסא, ומר אברהם ברוידא מפרג."},{"i":32496,"n":"משה מלאדיזין","f":"אברהם גרשון קיטובר","k":"אחיינו של הבעשט","b":"אחיינו ותלמידו של הבעשט. רב בלאדיזין."},{"i":32497,"n":"משה מלאריקה-איטליה","b":"משורר ומדקדק מחכמי איטליה בזמן מהר\"ם מלובלין. תלמידו ר יהודה בן יצחק מודנא."},{"i":32498,"n":"משה מלבוב","f":"יוסף","dt":"שעג - יב סיון","dp":"לבוב","b":"מרביץ תורה ור\"מ בלבוב."},{"i":32499,"n":"משה מלבוב","f":"אליהו","dt":"תח - טו אדר","dp":"לבוב","b":"ר\"מ בלבוב. גיסו - ר אברהם שרנצל רפפורט בעל \"איתן האזרחי\"."},{"i":32500,"n":"משה מלבוב","f":"נטע בערמניש","k":"משה ר בערמנש","dt":"תכ - יב טבת","dp":"לבוב","b":"דיין בלבוב. חתם-תיב עם ר אברהם גראפין ור יוסף בן יצחק מלבוב, חתם-תטו עם ר ישעיה קרמניצר."},{"i":32501,"n":"משה מלבוב","f":"יוסף","k":"בעל ויקהל משה","dt":"תקכד - אחרי","b":"חתן ר ישעיה בן הט\"ז. דיין בלבוב, חתם-תקח עם ר אריה ליב רפפורט, חתם-תקיא, חתם-תקך עם ר חיים רפפורט, ועוד. הסכים על \"בית דוד ושלמה\"."},{"i":32502,"n":"משה מלבוב","k":"ר' משה ריש מתיבתא","dt":"תכה - יב אדר","dp":"לבוב","b":"מרביץ תורה בלבוב. מחותן עם המהר\"ם מלובלין, ונזכר בשו\"ת מהר\"ם מלובלין."},{"i":32503,"n":"משה מלבוב","f":"שלום","dt":"תכד - ח אייר","dp":"לבוב","b":"מחכמי לבוב. נהרג עק\"ה."},{"i":32504,"n":"משה מלבוב","f":"אברהם","dt":"תכד - ח אייר","dp":"לבוב","b":"מחכמי לבוב. נהרג עק\"ה."},{"i":32505,"n":"משה מלבוב","f":"יהושע","dp":"לבוב","b":"רב בלבוב. חתם על פסק דין-שצט. אולי הוא שהיה בנו של בעל מגיני שלמה."},{"i":32506,"n":"משה מלבוב","f":"מנחם מן מלבוב","dt":"תטו - כא טבת","dp":"לבוב","b":"מחכמי לבוב."},{"i":32507,"n":"משה מלבוב","f":"מאיר או יאיר","b":"דיין בלבוב, חתם-תקלה עם ר אהרן ישכר בער בן יוסף ועוד."},{"i":32508,"n":"משה מלבוב","f":"אהרן","dt":"שסט - טז תשרי","dp":"לבוב","b":"ר\"מ בלבוב."},{"i":32509,"n":"משה מלבוב","f":"מהר\"ף","b":"דיין בלבוב, חתם-תעח בפנקס הקהלה."},{"i":32510,"n":"משה מלבוב","f":"יאיר","b":"דיין בלבוב אצל ר חיים רפפורט, חתם-תי, תקטו עם ר יחיאל בריסקר ור ישכר איגרא אחרי ר חיים רפפורט, חתם-תקכו עם ר ישעיה קיקניש, חתם-תקלג על פס\"ד עם ר מנחם מנדל רפפורט, ועוד. הסכים על \"זכרון כהונה\" לר יצחק איזיק מקוריץ."},{"i":32511,"n":"משה מלבוב וברעזן","f":"אברהם","dt":"תכד - כט אב","dp":"לבוב","b":"רב בברזאן, ראב\"ד בלבוב."},{"i":32512,"n":"משה מלובלין","f":"יהושע","dt":"שעה - ז חשון","dp":"לובלין","b":"מחכמי לובלין וממנהיגי הקהילה. נהרג עק\"ה (כנרמז מנוסח מצבתו)."},{"i":32513,"n":"משה מלובלין","f":"צבי הירש סבא","k":"משה ר הירש ר יאסקעס","b":"נכד ר יוסף יאסקי מלובלין-נכדו של המהר\"ל. רב-שנת תע. בנו - ר יהודה יודל מקאוולי ולבוב (6827)."},{"i":32514,"n":"משה מלובלין","f":"מנחם מאניש סגי נהור","dt":"תקלד - יג חשון","dp":"לובלין","b":"מחכמי לובלין. נכד ר פנחס אב\"ד לבוב ונינו של ר מאניש חתן הש\"ך. (באוצר הרבנים שנת פטירתו - תקיד)"},{"i":32515,"n":"משה מלובלין","b":"רב בעלזיץ,מו\"צ בלובלין-תר\"כ"},{"i":32516,"n":"משה מלובלין","f":"יהודה בן שלמה","dt":"שעז - כה אייר","dp":"לובלין","b":"נכד ר שלמה ר ליבשיס. מחכמי לובלין."},{"i":32517,"n":"משה מלובלין","f":"אליקים","dt":"תקסא - ח שבט","dp":"לובלין","b":"דיין בלובלין."},{"i":32518,"n":"משה מלובלין","f":"אליהו","dt":"תקסד - יח חשון","dp":"לובלין","b":"מחכמי לובלין. בנו של ר אליהו בעל \"יד אליהו\" שעלה לארץ (ונפטר תף ? - לבדוק)."},{"i":32519,"n":"משה מלובלין","f":"אלעזר","dt":"תקע - יד אדר","dp":"לובלין","b":"דיין בלובלין."},{"i":32520,"n":"משה מלובלין","f":"אברהם","dt":"תקעד - כג אייר","dp":"לובלין","b":"דיין בלובלין."},{"i":32521,"n":"משה מלובלין","f":"בנימין וולף","bt":"ת\"כ","dt":"תקא - ה שבט","dp":"לובלין","b":"אחיו - ר צבי.","bk":[["פרחי שושנים",""]],"e":"ת\"כ~-ת\"ק~"},{"i":32522,"n":"משה מלובלין וחברון","f":"אליהו","k":"בעל פרחי שושנים","b":"מחכמי חברון. חיבר \"פרחי שושנים\" קושטא תצט. אביו היה ר משה לובלין בעל \"ידי אליהו\". יש ר משה לובלין המוזכר ב\"חרבות ירושלים\" כאחד הסובלים בשנת שפה. (ויש ר משה מלובלין בן אליהו-בעל יד אליהו שנפטר בלובלין תקסד - קורות יהודי לובלין)."},{"i":32523,"n":"משה מלובלין וירושלים","b":"מחכמי ירושלים-שפ."},{"i":32524,"n":"משה מלובלינץ וליסא","f":"ישראל ורעשנא מקאבלין","b":"רב בלובלינץ, ליסא. אחיהם של ר אברהם מוועלין, ור שאול מטומשוב."},{"i":32525,"n":"משה מלובמלא","dt":"שעז","b":"רב בלובמלא. נספד ב\"איתן האזרחי\"."},{"i":32526,"n":"משה מלובמלא ולובלין","f":"יצחק רבי בונימש","k":"בעל מהדורא בתרא","dt":"תכט - ח-כא כסלו","dp":"לובלין","b":"חתן המהרש\"א. מגדולי חריפי דורו, רב בלובמלא, לובלין. חתם ראשון מבין חכמי ועד ארבע ארצות על הסכמה ל\"עמודיה שבעה\" ביריד לובלין-תכד, הסכים על ש\"ך ליו\"ד - תו. בנו ר ישראל איסר רב בלומבלא על מקום אביו, בריסק ולובלין. אחיו - ר זאב וולף-חותנו של בעל הש\"ך."},{"i":32527,"n":"משה מלוניל","b":"מגדולי הראשונים,מרביץ תורה בלוניל-ד'תת\"ע"},{"i":32528,"n":"משה מליבער","b":"מוכיח,רב בליבער"},{"i":32529,"n":"משה מליטא","f":"אהרן","k":"בעל פרדס החכמה,ונ\"י","bt":"תקסה","bp":"סלנט","dt":"תרלה","dp":"שיקגו","b":"רב ומגיד בכמה מקומות בליטא, סלנט-תקע, לאזדיי, וישטיניץ, ראצק. היגר לארה\"ב ונתקבל למגיד מישרים בניו יורק, היה מחלוקת בינו לבין ר אברהם יוסף אש ועזב. התפרסם כדרשן ומחבר ספרי דרוש. חיבר גם \"פרדס הבינה\", ועוד."},{"i":32530,"n":"משה מליטומירסק","b":"תלמיד היהודי הקדוש מפשיסחא, ר שמחה בונם מפשיסחא. ר מנחם מנדל מקוצק העריכו מאוד."},{"i":32531,"n":"משה מלינסק","f":"יצחק","dt":"תקצה","b":"רב בלינסק."},{"i":32532,"n":"משה מלנצהוט - א","f":"יהודה ליב מראקוב וקר","b":"נינו של ר שמואל שמלקא-אב\"ד אוסטרהא. חתן ר יעקב יצחק לנדא דוקלא-אב\"ד פרשבורג בעל \"מעיני הישועה\". בנו - ר שמואל שמלקא-אב\"ד דניביץ ובומסלא בעל \"אמרי זוטרי\"."},{"i":32533,"n":"משה מלנצהוט - ב","f":"יהודה ליב","b":"חתן ר שלום מקראקא. רב בלאנצוט-שנת ת'. בנו - ר צבי."},{"i":32534,"n":"משה ממגנצא","k":"רבינו משה ממגנצא","b":"מגדולי הראשונים בחכמי אשכנז-ד'תתק\"פ"},{"i":32535,"n":"משה ממגנצא(=מיינץ)","f":"קלונימוס","b":"פייטן באשכנז-ד'תשפ, בן למשפחת פייטנים ידועה."},{"i":32536,"n":"משה ממודנא","f":"צבי הירש","b":"רב במודנא"},{"i":32537,"n":"משה ממטרסדורף","dt":"תכ - ג תשרי","b":"רב במטרסדורף"},{"i":32538,"n":"משה ממיטאוי","f":"צבי הירש חריף ממיטאו","dt":"תקעח - כד אב","dp":"מיטאוי","b":"מחכמי מיטאוי."},{"i":32539,"n":"משה ממינסק","f":"יהודה","dt":"תרכא - ד תשרי","dp":"מינסק","b":"מחכמי מינסק."},{"i":32540,"n":"משה ממינסק ולונדון","f":"יהודה","k":"בעל אבן שהם","b":"מגיד במינסק, לונדון-תקכד."},{"i":32541,"n":"משה ממנהיים","f":"זעלקלי","dt":"תמב - ה אדר","dp":"פפד\"מ","b":"רב במנהיים"},{"i":32542,"n":"משה ממעדלינג","b":"מוזכר אצל ר יצחק יעקב בהגהותיו לשחיטות ובדיקות למהר\"י ווייל."},{"i":32543,"n":"משה ממצרים","f":"סעדיה","b":"מגדולי רבני מצרים-ד'תתק\"נ"},{"i":32544,"n":"משה מנוברדוק ואורלא","f":"נתן נטע","b":"נינו של ר שמואל מפיורדא בעל \"בית שמואל\". רב בנוברדוק(=נווארדוק) על מקום ר ישראל בעל \"אבן בוחן\" ור דוד בעל \"גליא מסכת\" על מקומו אחריו, אורלא-תקנו. הסכים על ספר יצירה עם פירוש הגר\"א הורדנא תקסו, שו\"ע ביאור הגר\"א הורדנא תקסו, הגדה עם ביאור הגר\"א הורדנא תקסז."},{"i":32545,"n":"משה מנוידואהר","b":"רב בנאווידוואר-תרמ\"ה"},{"i":32546,"n":"משה מנחם מליפנא","f":"מרדכי מרדוש","b":"רב בליפנא,לוביטש-תר\"ל"},{"i":32547,"n":"משה מנחם מנדל מאלטונא","k":"מנדל רוברט","dt":"תקנד - טו ניסן","dp":"אלטונא","b":"חתן ר משה היילבוט מהמבורג. דיין בברלין, אלטונא בזמן ר יונתן איבשיץ וחתם עמו, ואצל ר רפאל הכהן מהמבורג. חתם על החרם על מחבר \"מצפה יקותיאל\"."},{"i":32548,"n":"משה מנייהייזל","b":"ראב\"ד בנייהייזל-ת\"ק"},{"i":32549,"n":"משה מניקלשבורג","f":"אלחנן","dt":"תעד","dp":"פרג","b":"רב בניקלשבורג, עלה לירושלים וחתם שם בשנת תסז, בשליחות באשכנז בשנת תעא היה במיץ. נפטר בדרך שליחותו."},{"i":32550,"n":"משה מנמירוב","f":"יעקב ממזבוז","b":"תלמיד הבעשט בנמירוב. חתן אחות ר יעקב יוסף מפולנאה."},{"i":32551,"n":"משה מסאמטור וניקלשבורג","b":"אב\"ד סאמטור-ליד פוזנא, ניקלשבורג."},{"i":32552,"n":"משה מסדיגורא ופאקשן","f":"פנחס","k":"בעל פני משה","b":"אחיו של ר מרדכי מקוריץ. רב בפאקשן, קליוואן, סדיגורא-תקעח. חיבר גם \"מראה הפנים\"."},{"i":32553,"n":"משה מסוואלק","f":"שלמה זלמן","b":"מו\"צ בסוואלק"},{"i":32554,"n":"משה מסווירז","b":"זקנו של המגיד מזלוטשוב - בנו ר יוסף היה סבו של המגיד. רב בסווירז. מת על קדוש השם."},{"i":32555,"n":"משה מסווראן","b":"רב בסווראן-תק\"פ"},{"i":32556,"n":"משה מסוכטשוב","b":"רב בסאכטשוב-ת\"פ"},{"i":32557,"n":"משה מסופיה","f":"חיים","dt":"תקעד - כה אב","dp":"סופיה","b":"מחכמי סופיה."},{"i":32558,"n":"משה מסטולין","f":"אהרן מלוביצקי מלכובי","b":"בן האדמור מלכוביץ, ונכד ר אשר הגדול מסטולין (אמו פעריל - בתו של ר אשר). בנו - ר שלמה מסטולין וחברון."},{"i":32559,"n":"משה מסטזניץ","f":"בנימין","k":"אדמור מזליחוב","dt":"תרד - ו אדר","b":"תלמיד החוזה מלובלין. אדמור בזליחוב. בניו: ר יעקב יצחק מסאבין, ור יוסף מזליחוב."},{"i":32560,"n":"משה מסטנוב","f":"נפתלי הרץ מדובנא","b":"נכד ר צבי הירש מהלברשטט. חתן ר יצחק לנדא מאפטא ולבוב. רב בסטאנוב."},{"i":32561,"n":"משה מסטנוב","f":"נפתלי הרץ","dt":"תקסב","b":"רב בסטאנוב וגליל פאדאליע"},{"i":32562,"n":"משה מסטנוב(=סאטינוב)","b":"תלמיד הבעשט. ונפטר בחיי הבעשט."},{"i":32563,"n":"משה מסיציליה","f":"גבאי","b":"רב בסיציליה אחרי הריב\"ש. חתנו ותלמידו - ר אהרן אבו רבי."},{"i":32564,"n":"משה מסיציליה","f":"גרשון","b":"מחכמי סיציליה בזמן הרשב\"ץ. אחיו - ר ברוך, ר אהרן אבו רבי, ור יעקב מסיציליה."},{"i":32565,"n":"משה מספרד","f":"יוסף","b":"מגדולי רבותינו הקדמונים בספרד-ד'תתק\"ע"},{"i":32566,"n":"משה מספרד","f":"גמאי","b":"תלמיד הריב\"ש. רב בספרד בזמן הרשב\"ץ המזכירו בספרו."},{"i":32567,"n":"משה מספרד","f":"יהודה הכהן","b":"בן אחותו ותלמידו של הרא\"ש (המכנהו נכדי - והכוונה אחייני), הגיע מאשכנז לספרד."},{"i":32568,"n":"משה מספרד","f":"יצחק","k":"בעל הכרת המדות","b":"מחכמי ספרד בשנות ה-ק."},{"i":32569,"n":"משה מספרד","f":"מאיר","b":"מחכמי ספרד מדקדק ומשורר. בן דורו של הרמבם. תלמיד ר אברהם ן עזרא."},{"i":32570,"n":"משה מספרד ומודנא","b":"מגדולי חכמי ספרד בדור הגירוש(רנ\"ב),עלה לפירארה"},{"i":32571,"n":"משה מסקאלי","f":"יהודה ליב-שבט מיהודה","k":"בעל פני משה","b":"נכד ר משה גולדין מטומשוב. רב בסקאלי על מקום אביו, הו\"ל ספר אביו \"שבט מיהודה\". חיבר גם \"הלכה למשה\"."},{"i":32572,"n":"משה מסקול","b":"תלמיד ר צבי הירש מזידיטשוב, ר יצחק איזיק מזידיטשוב. היה מנהיג עדת חסידים תחת רבו."},{"i":32573,"n":"משה מסקול וגליל בעלז","f":"מרדכי","b":"חתם בפנקס זולקוא-תנט אודות מדפיסי זולקוא. מתורתו ב\"לקוטי שושנים\"."},{"i":32574,"n":"משה מעשיל מהילדסהיים","b":"רב בהילדסהיים-תקעב."},{"i":32575,"n":"משה מעשל מבעזענקא","b":"תלמיד הבעשט."},{"i":32576,"n":"משה מפאנו","f":"יהודה מפאנו","b":"סופר סת\"ם בפדובה."},{"i":32577,"n":"משה מפדזלווא - אחי הגר\"א","f":"שלמה זלמן מוילנא","b":"מו\"צ בפדזעלווא-תק\"צ."},{"i":32578,"n":"משה מפודהייץ","b":"רב בפדהייץ-ש\"מ"},{"i":32579,"n":"משה מפוזנא","f":"יהודה יידל-קול יהודה","b":"רב בפוזנא-תצ. חתנו - ר קדש - אביו של ר ברוך - חתנו של ר ברוך מלאזניא-אביו של בעל התניא."},{"i":32580,"n":"משה מפולין","f":"חסדאי","b":"חכם מפולין המובא ברמב\"ן."},{"i":32581,"n":"משה מפונטייזא","b":"מגדולי בעלי התוספות-ד'תתק\"נ"},{"i":32582,"n":"משה מפופאביץ","f":"מוהר\"מ","b":"רב בפופאוויץ. פרסם מאמרים ב\"אסיפת חכמים\" - אטיניא-בויאן תרע-תרעד."},{"i":32583,"n":"משה מפטיר מענדלש מאוסטרהא","b":"רב באוסטרהא בזמן המהרש\"א. מחדושיו ב\"ברכת טוב\"."},{"i":32584,"n":"משה מפיורדא ופרשבורג","b":"מראשי קהלת פרשבורג. חתם על תקנות ר מאיר ברבי-תקכח."},{"i":32585,"n":"משה מפיורדא ושידלוב","f":"שמחה","b":"מדפיס בדפוס חיים בן צבי הירש בפיורדא - תקל."},{"i":32586,"n":"משה מפינסק וירושלים","f":"אריה ליב","dt":"תרמד - יח חשון","dp":"ירושלים","b":"מחכמי ירושלים."},{"i":32587,"n":"משה מפפד\"מ ופוזנא","f":"ישעיה מנדל ר אביגדור","k":"משה ר מנדלש","b":"דיין בקראקא. רב בשידלוב, לודמיר, פפד\"מ-שסה, פרג, פוזנא-שץ. חיבר סליחה לעצור המגיפה. חתם-שצט עם רבני ועד ארבע ארצות ובהם בעל תוי\"ט, בעל מגיני שלמה, ר מאיר ז\"ק מלבוב. הסכים על ביאורי סמ\"ג לר יוסף מקרמניץ, \"גלילות ארץ ישראל\", סידור שער השמים להשל\"ה. בניו - ר ישראל בעל \"מראה צדק\", בתו - אדל חיברה קיצור יוסיפון בלשון אשכנז - קראקא תל."},{"i":32588,"n":"משה מפרבוזנה","f":"צבי מדעלאטין","b":"רב בפרעבוזנה"},{"i":32589,"n":"משה מפרג","dt":"שפו - ד כסלו","b":"דיין בפרג"},{"i":32590,"n":"משה מפרג","f":"מנחם","k":"בעל ויקהל משה","b":"מקובל, מגדולי חכמי פרג, עבר לניקלשבורג, רב בשינאווי-תמט. רב בזמן ר דוד אופנהים. חיבר \"זרע קודש\", \"ויקהל משה\"."},{"i":32591,"n":"משה מפרג","b":"מחכמי עזה, נזכר על ידי ר עובדיה מברטנורא."},{"i":32592,"n":"משה מפרידברג","f":"יעקב","b":"מחכמי פרידברג. חתם על תקנות אסיפת הרבנים בפפד\"מ-שסג."},{"i":32593,"n":"משה מפרמישלא","f":"אברהם","k":"בעל מטה משה","dt":"שסו","b":"תלמיד המהרש\"ל, מחותן עם ר בנימין אהרן סלנק בעל \"משאת בנימין\" - תלמיד המהרש\"ל גם הוא."},{"i":32594,"n":"משה מפרשבורג","bt":"תקא","dt":"תקפא - ה חשון","dp":"פרשבורג","b":"מחכמי פרשבורג."},{"i":32595,"n":"משה מפרשבורג","f":"ליב","b":"מחכמי פרשבורג, חתם-תקכח על תקנות ר מאיר ברבי."},{"i":32596,"n":"משה מצור","f":"יצחק","b":"מחכמי צור בתקופת הצלבנים, היה פייטן."},{"i":32597,"n":"משה מצורך","k":"בעל הגהות על הסמק","b":"מגדולי הפוסקים"},{"i":32598,"n":"משה מצייקישוק","f":"אליעזר מקרוז ווילנא","b":"אב\"ד צייקישוק. אחיו של ר אברהם אבלי מוילנא"},{"i":32599,"n":"משה מצפת","f":"יהודה","b":"מחכמי צפת, הלך עם בית דינו לטבריה לקבר הרמבם והחרימו כל מי שידבר סרה עליו או על ספריו."},{"i":32600,"n":"משה מצפת","f":"סעדיה","dt":"שלו - כח אלול","b":"מחכמי צפת-רצח, נמנה על 25 הרבנים שהכתירו את ר יעקב בירב כמוסמך הראוי להסמיך אחרים, ונמנה עם החכמים שחתמו עם ר יוסף קארו בענין הקדש ישיבת ר יעקב בירב. חתנו - ר חיים ויטאל."},{"i":32601,"n":"משה מצפת","f":"שמעון","b":"מחכמי צפת-שצד, וחתם עם ר יוסף מליריאה. נזכר ב\"דרכי נעם\"."},{"i":32602,"n":"משה מצפת","f":"יצחק","b":"תלמיד ר שלמה אלקבץ. מראשי המקובלים בצפת. חיבר ספרים ומאמרים בקבלה - בכת\"י."},{"i":32603,"n":"משה מצפת","f":"מאיר","b":"נמנה בין העולים לצפת עם ר מנחם מנדל משקלוב, וחתם-תקעג בענין ר יוסף יעקבקא פרנקל מברסלוי."},{"i":32604,"n":"משה מצפת","f":"יוסף","b":"גבאי בקהלת הפרושים בצפת-תקעה יחד עם ר ישראל משקלוב."},{"i":32605,"n":"משה מקאבאלה","f":"נתן","b":"רב בקאבאלה-שנות ה-ש'."},{"i":32606,"n":"משה מקאפוסט","f":"ישראל","b":"הסכים על \"שבחי הבעשט\"."},{"i":32607,"n":"משה מקאריב","f":"אברהם אביש","b":"רב בקאריב-תק\"ל"},{"i":32608,"n":"משה מקובין","dt":"תרה - כא תשרי","b":"רב בקובין"},{"i":32609,"n":"משה מקובנא","dp":"תקצג - אחרי","b":"תלמיד הגר\"א. מו\"צ הראשון בקובנא לאחר שחזרו מהגלות. נזכר בהקדמה ל\"אבות דרבי נתן\" עם פירוש \"שני אליהו\" לר אליהו בן אברהם."},{"i":32610,"n":"משה מקובנא ווילנא","f":"אליהו חסיד מוילנא","dt":"תקכה - יב טבת","dp":"וילנא","b":"נכד בעל \"באר הגולה\". רבה הראשון של קובנא לאחר ישובם שם מחדש-תצא. אחיו של ר דב בער - זקנו של הגר\"א. חתם-תקח עם בית דינו של ר יהושע השל מוילנא. נקבר לצד אחיו-ר צבי הירש."},{"i":32611,"n":"משה מקובנא ווילנא","f":"אליעזר פייבל מוילנא","dt":"תרמה - יב אדר","dp":"וילנא","b":"חתן הגביר ר אלעזר חלפן מוילנא. תלמיד חכם וגביר על מקום חותנו בקובנא."},{"i":32612,"n":"משה מקוברין","b":"רב בקוברין-תק\"י"},{"i":32613,"n":"משה מקונסטנטין ישן","b":"רב בקונסטנטין ישן"},{"i":32614,"n":"משה מקופנהגן","f":"יוסף מסעלץ","b":"רב בקופנהגן. בנו - ר חיים, ונכדו - ר שלמה זלמן מזאבלודוב."},{"i":32615,"n":"משה מקורדובה","f":"מימון","bt":"ד'תתקמ","b":"מגדולי חכמי קורטובה"},{"i":32616,"n":"משה מקורדובה","f":"חנוך","bp":"איטליה","b":"מחכמי ספרד הקדומים. הגיע מאיטליה בימי ר שרירא גאון. רב בקורדובה, והעלה את לימוד התלמוד בספרד. תשובות ממנו בכת\"י."},{"i":32617,"n":"משה מקושטא","f":"יצחק כלב","b":"מדפיס אצל ר יונה בן יעקב אשכנזי בקושטא-תע."},{"i":32618,"n":"משה מקידאן","b":"רב בקידאן-תקף. ראה גם משה החסיד רגולר-בן ר אברהם-אחי הגר\"א."},{"i":32619,"n":"משה מקיוב","b":"מגדולי בעלי התוספות-ד'תתק\"נ"},{"i":32620,"n":"משה מקיוסטנדיל","f":"יעקב","b":"רב בקיוסטנדיל-תקנה."},{"i":32621,"n":"משה מקיטוב","f":"שלמה","bt":"תמח","dt":"תצח - יז שבט","b":"מקובל. היה מקושר עם הבעש\"ט (לא ברור אם תלמידו או רבו - לפי אלפסי תלמידו), והיה מראשוני המודיעים את טבעו בעולם. מתורתו ב\"משנת חסידים\". חתנו ר יונה בן אברהם הלוי מקיטוב."},{"i":32622,"n":"משה מקלוואריה","f":"יהודה","b":"שמש ונאמן קהלת קלוואריה, חתם-תקצז עם הראב\"ד ר אריה ליב ברוידא, ועם ר אלתר בן יעקב ור צבי הירש בן פנחס חיים כהנא"},{"i":32623,"n":"משה מקליקול-ליטא","bt":"תקעו","dt":"תרנז","b":"רב בקליקול-ליטא כ-46 שנה ובנו? ר יצחק ראובן על מקומו אחריו."},{"i":32624,"n":"משה מקראקא","f":"יהושע","dt":"תמח - כח אייר","dp":"קראקא","b":"רב בקראקא-תח. אולי הוא שחתם-שצג בפנקס הקהלה."},{"i":32625,"n":"משה מקראקא","b":"עשיר,רב המדינה דגליל קרקא-שע\"א"},{"i":32626,"n":"משה מקראקא","b":"סופר דמתא בקרקא-שנת ת'"},{"i":32627,"n":"משה מקראקא","k":"בעל דרש משה","dt":"תצו - יג כסלו","b":"דרשן,מגיד בקרקא"},{"i":32628,"n":"משה מקראקא","k":"ר' משה פישלס מקרקא","b":"עשיר,שר המכס במדינת פולין"},{"i":32629,"n":"משה מקראקא","k":"בעל פני משה","b":"רב באויסזעע-ת\"ל"},{"i":32630,"n":"משה מקראקא","k":"ר' משה משטעטשין","dt":"תקלד - טז כסלו","b":"דיין בקרקא"},{"i":32631,"n":"משה מקראקא","f":"עזריה","b":"מחכמי צפת, בשנת שפא חתם על הזמנת ר ישכר בר איילינבורג לכהן בצפת."},{"i":32632,"n":"משה מקראקא","f":"שמואל זנויל מקראקא","b":"נכד בעל חלקת מחוקק. הו\"ל שפתי כהן על התורה-ואנזבק תן."},{"i":32633,"n":"משה מקרוז ווילנא","k":"משה'ל מיינה'ס","dp":"וילנא","b":"גאון וצדיק מפורסם בקרוז' ווילנא."},{"i":32634,"n":"משה מקריסטשוב","f":"מרדכי מקאריסטשוב","b":"חתן ר אפרים מטריסק. רב בקאריסטשוב-תר\"מ"},{"i":32635,"n":"משה מקרליץ","f":"דוד","dt":"תרה","b":"רב בקרליץ. נפטר צעיר כבן 30. חדושי תורה ממנו ב\"גזע ישישים\"."},{"i":32636,"n":"משה מקרסטון","b":"רב בקרסטור-תר\"ח"},{"i":32637,"n":"משה מקרסלבורג","f":"חיים אריה מקניזש","b":"פרנס בקרלסבורג-תק בערך."},{"i":32638,"n":"משה מקרשטשוב ואוסטרהא","b":"חתן ר יעקב יוסף מאוסטרהא - נכדו של רב ייב\"י."},{"i":32639,"n":"משה מראדויל","b":"רב בראדוויל-תק\"מ"},{"i":32640,"n":"משה מראסיין","b":"תלמיד ר חיים מוולוזין."},{"i":32641,"n":"משה מרגנשבורג","f":"יואל","b":"מגדולי חכמי רגנשבורג-ד'תתק\"כ,מבעלי התוספות"},{"i":32642,"n":"משה מרדכי","f":"אליעזר","k":"בעל תפלה למשה","b":"חתן ר יהושע פאלק הכהן נכד הסמ\"ע. חיבר \"תפלה למשה\" - בכתב יד."},{"i":32643,"n":"משה מרדכי הכהן (כהנא) מברעזן","f":"נתן(16325?)","k":"בעל צאן קדשים","dt":"שצא - כא תשרי","dp":"לבוב","b":"חתן המהר\"ם מלובלין. רב בבערזאן, ראש ישיבה בלבוב. חברו של ר אברהם חיים שור בעל תורת חיים וחיברו ביחד את \"צאן קדשים\". בנו - ר נתן נטע כץ כהנא מאוסטרהא. (יש טעות באוצר הספרים באשר לאביו)"},{"i":32644,"n":"משה מרדכי השל מוארשא","f":"אברהם יהושע","dt":"תרעח","b":"אדמו\"ר בפלצבוויזנה בוורשה"},{"i":32645,"n":"משה מרדכי מאוסטרהא","f":"ברוך","dt":"שעז - ז אדר","dp":"אוסטרהא","b":"מנהיג \"עיקור\" הקהלה באוסטרהא."},{"i":32646,"n":"משה מרדכי מבגדד","b":"נשיא הקהלה בבגדד-תקח בזמן ר צדקה חוצין המזכירו בספרו \"צדקה ומשפט\", בנו - ישראל. החזיק בכת\"י \"עץ חיים\" לר חיים ויטאל, ושליח אשכנזי העתיקו בביתו."},{"i":32647,"n":"משה מרדכי מטבריה","f":"יעקב אריה","b":"ממונה כולל רייסין בטבריה-תרטו."},{"i":32648,"n":"משה מרדכי מנוברדוק","b":"מחכמי נוברדוק-תר בערך. נספד מאת ר אליהו שיק מלידא. מתורתו בשו\"ת \"קהלת יעקב\" לר יעקב מקרלין."},{"i":32649,"n":"משה מרדכי משלוניקי","dt":"תנז","dp":"שלוניקי","b":"מחכמי שלוניקי."},{"i":32650,"n":"משה מרדכי משלוניקי - ב","dt":"תץ - אחרי","dp":"שלוניקי","b":"גביר בשלוניקי ותרם הרבה לצרכי העיר."},{"i":32651,"n":"משה מרדכי'ס מוילנא","b":"מחכמי \"ישיבת הארבעים\" בוילנא-תקפז."},{"i":32652,"n":"משה מרודניא","b":"רב בבאייעב,ליעפלי,רודניא-תק\"נ"},{"i":32653,"n":"משה מרוזבדוב","b":"תלמיד החוזה מלובלין, היהודי הקדוש מפשיסחא, מגדולי תלמידי ר שמחה בונם מפשיסחא. מתורתו ב\"שפתי צדיקים\"."},{"i":32654,"n":"משה מרוזוודוב","b":"רב ברזוואדוב-תק\"ס"},{"i":32655,"n":"משה מרחמיסטריבקא אודסה","f":"מרדכי מרחמיסטריבקא","k":"אדמור מרחמיסטריבקא","b":"חתן ר דוד מסאוורן, ובזיוו\"ש חתן ר יחיאל מקרילוביץ (אפטא). אדמור מרחמיסטריבקא באודסה."},{"i":32656,"n":"משה מריישא","b":"רב ברישא-תמ\"ה"},{"i":32657,"n":"משה משאנלאנק","b":"רב בשאנלאנק-תק\"פ"},{"i":32658,"n":"משה משארוואר","b":"רב בשארוואר-תקע\"ה"},{"i":32659,"n":"משה משדה חדש","b":"תלמיד הבעשט. ונקבר לידו."},{"i":32660,"n":"משה משוואל-הולנד","dt":"תקסח","b":"רב ראשון של שוואל(הולנד)"},{"i":32661,"n":"משה משטינין","f":"אלחנן מפירודא","b":"רב בשטיינין-ת\"י"},{"i":32662,"n":"משה משטרעלטיק","f":"יוסף משטרעלטיק","b":"אביו היה מו\"צ בשטרעלטיק-בוהמיה. תלמיד ר שלמה קוועטש, וקיבל ממנו תעודת מורנו-תריא."},{"i":32663,"n":"משה משלוניקי","f":"חיים עובדיה משלוניקי","dp":"אוילונה","b":"רב בק\"ק קאטאלן בשלוניקי-שנות ה-ש' על מקום אביו. חיבר ספרים."},{"i":32664,"n":"משה משלוניקי","f":"שמואל מרגנשבורג","dt":"שטו - ד אלול","dp":"שלוניקי","b":"מחכמי שלוניקי. בן למשפחה שמוצאה מרגנשבורג."},{"i":32665,"n":"משה משלוניקי","f":"יונתן","b":"רב בשלוניקי-שנות ה-ש'."},{"i":32666,"n":"משה משלם הלוי משלוניקי","f":"אליעזר","bt":"רצה","dt":"שעו - אחרי","b":"מחכמי קושטא-שס, ממונה על החזקות-שסב. נזכר בספרי ר אליהו ן חיים, ר יחיאל באסאן ור יוסף טרני."},{"i":32667,"n":"משה משלם חסיד מקראקא","dt":"תי - יד שבט","b":"דיין בקראקא"},{"i":32668,"n":"משה משניפישוק","f":"יוסף הלוי","dt":"תקעט - כג אייר","b":"מו\"צ הראשון בשניפישוק אחר פטירת האב\"ד האחרון של וילנא ר שמואל - שהיתה כפופה עד אז לראב\"ד וילנא. על מקומו אחריו ר פנחס בן יהודה בעל \"מגיד צדק\"."},{"i":32669,"n":"משה משערשוב","dt":"תקפז - ל תשרי","b":"רב בשערשוב. תלמיד ר חיים חייקא מאמדור, ור שלמה מקרלין, ור מרדכי מנסכיז. ממפיצי החסידות בליטא."},{"i":32670,"n":"משה משקודוויל","dt":"תקצה","b":"אב\"ד שקודוויל. בנו - ר טודרוס לוריא מראסיין."},{"i":32671,"n":"משה משקלוב","f":"מנחם","k":"בעל קשוט טוב","b":"מגיד בשקלאב-תק\"כ"},{"i":32672,"n":"משה משקלוב ומינסק","f":"יהודה","b":"רב במינסק-תר בערך."},{"i":32673,"n":"משה מתימן","f":"סעיד","b":"דיין ושליח הגאונים בירים-תימן יחד עם אחיו ר שלמה. במאה ה-יא. נזכרו בגניזה במכתב של גאון בבל שפנה אליהם בקשר לאיסוף התרומות לישיבת הגאונים."},{"i":32674,"n":"משה ן, חיים מסופיה","b":"רב בסופיה-סוף שנות ה-ש'."},{"i":32675,"n":"משה ן, ישועה מאלגיר","bt":"קי","dt":"קפ - בערך","b":"מחכמי הוניין ועסק במסחר, נזכר בשו\"ת הריב\"ש שהפליג בשבחו."},{"i":32676,"n":"משה נאמן מאנטיפליא וירושלים","f":"עקיבא","dt":"תרה - יח ניסן","dp":"ירושלים","b":"מחכמי צפת, ירושלים, חתם עם ראשי הפרושים על שטר חוב גבאי החורבה למשפחת אמזליג."},{"i":32677,"n":"משה נח יונה מזולקוא","f":"משה","b":"דיין בזולקוא, חתם-תיד על שטר מכירה בלבוב ונתקיימה החתימה מאת עדים ובהם בעל הט\"ז."},{"i":32678,"n":"משה נתן","b":"רב ברישא-תקי\"ג"},{"i":32679,"n":"משה סגי נהור מירושלים","b":"מחכמי ירושלים. נזכר במכתב ר ישראל מפירושא-רפג, ואצל ר משה בסולה-רפב."},{"i":32680,"n":"משה סגי-נהור מהורודוק","b":"חסיד ר מנחם מנדל מויטבסק, ועלה עם רבו לארץ-תקלז."},{"i":32681,"n":"משה סגל מטבריה","f":"אברהם","dt":"תקעג - יב ניסן","dp":"טבריה","b":"אחיו של ר צבי הירש מהורקא. חתנו - ר אברהם מקאליסק בזיוו\"ש. נחשב לזקן החסידים בארץ. בשליחות-תקמז."},{"i":32682,"n":"משה סופר-ספרא מקראקא","f":"אשר למל מאייבנשיץ","dt":"תקנא - יח אב","b":"סופר ודיין בקראקא."},{"i":32683,"n":"משה סמבורר מלינסק","f":"יהודה ליב","b":"מחכמי לינסק."},{"i":32684,"n":"משה עובדיה מניוזיל-היסאר ואזמי","dt":"תכג - ט כסלו","dp":"אזמיר","b":"רב ביוזיל-היסאר - ליד אזמיר - שנות ה-ש', רב באזמיר-שנות ה-ת'."},{"i":32685,"n":"משה עמרם משלוניקי","b":"דיין בק\"ק שלום בשלוניקי-של."},{"i":32686,"n":"משה עקיבא מקושטא","b":"ממונה על איסור והיתר בקושטא-תקעב."},{"i":32687,"n":"משה פישל הרופא מקראקא","b":"רופא,רב בקראקא-רפג."},{"i":32688,"n":"משה פנחס חריף מלבוב","f":"ישראל חריף","k":"בעל הגהות על גטין","dt":"תסב - כו אלול","dp":"לבוב","b":"נכד ר משה חריף מלבוב-הראשון. השם פנחס נוסף לו בבגרותו. חתן ר שמעון הכהן מיזלוביץ-בן ר אברהם שרנציל (ה\"חכם צבי\"?). מגדולי דורו, מחכמי ועד ארבע ארצות, חתם-תנג על הסכמות עם שאר חכמי הועד. רב ור\"מ שתי הקהלות בלבוב. חיבר ספר על שמות גיטין יחד עם ר אברהם שרענצל בעל \"איתן האזרחי\". בניו: ר ישראל חריף מלבוב, ר צבי הירש מיבורוב, לפי בובר-זולקוא בנו גם ר יעקב חריף מלעשנוב, לפי פעסיס בנו גם - ר צדוק דער רייכער. חתניו - ר נפתלי הרץ אשכנזי מקאוולי, ר ישעיה קצנלנבוגן. (ר יהודה יוסל מלבוב (7175) - כך באוצר הרבנים)."},{"i":32689,"n":"משה פרנס מרוטנברג","k":"בעל ספר הפרנס","b":"מגדולי הראשונים,פוסק מרוטנבורג-שנת ס'"},{"i":32690,"n":"משה פרץ מדובנא","f":"מנחם מאניש הורביץ מד","dt":"תקסח","b":"מחכמי דובנא. אחיו - ר אברהם אריה מלויצק."},{"i":32691,"n":"משה פרץ מחברון","b":"מחכמי חברון, בשנת תקמח חתם עם חכמי חברון."},{"i":32692,"n":"משה פרץ מחברון","b":"מחכמי חברון, בשנת תי בשליחות במרוקו. שאלות ממנו לר שמואל צרפתי בפאס. היה שליח חברון הראשון הידוע."},{"i":32693,"n":"משה צבי"},{"i":32694,"n":"משה צבי הירש","b":"נכד ר קלונימוס קלמן מביאלא בעל \"דעת משה\". פרסם מאמרים ב\"מציון תצא תורה\" - זאמושט תרפט."},{"i":32695,"n":"משה צבי הירש מירושלים","b":"מחכמי ירושלים-תסה, חתם אז על מכתב רבני ירושלים כנגד אנשי ר יהודה החסיד."},{"i":32696,"n":"משה צבי הירש משאוולי","b":"שו\"ב בשאוולי-תרסד, חתם על סמיכה לשוחט."},{"i":32697,"n":"משה צבי הרש מוערבא","f":"שמחה מוערבא","b":"מתלמידיו הראשונים של החת\"ס."},{"i":32698,"n":"משה צבי מקופיטשיניץ","b":"חתן ר אברהם אהרן מצורטקוב. רב בקופיטשיניץ."},{"i":32699,"n":"משה צבי משדליץ (וינגרטן)","f":"יעקב","k":"בעל חידושי מהר\"ם צבי","b":"אב\"ד שדליץ. בנו - ר ברוך הו\"ל את ספרו \"חידושי מהר\"ם צבי\" - וארשא תרנא."},{"i":32700,"n":"משה ציון","dt":"תמא - כה אב","dp":"אזמיר","b":"חיבר שו\"ת ופסקים, ונזכר ב\"עבודת ישראל\". תשובה ממנו ב\"דבר שמואל\"."},{"i":32701,"n":"משה קראטשניר מלבוב","f":"יהודה ליב","dt":"תנו - כה תמוז","dp":"לבוב","b":"מרביץ תורה בלבוב"},{"i":32702,"n":"משה ר ליזרש","k":"חתן המהרש\"ל","dt":"שלד - יב כסלו","b":"מגדולי חכמי בריסק (אולי הוא נכד המהרש\"ל - בנו של ר אליעזר אחי הרמ\"א)."},{"i":32703,"n":"משה ראובן מצפת וטבריה","f":"ראובן","b":"מראשי הקהלה בצפת וטבריה, חתם-תקפט על שטר פשר."},{"i":32704,"n":"משה רבינו בן עמרם","dt":"ז' אדר ב' אלפים תפח","bk":[["איוב",""]]},{"i":32705,"n":"משה רבינו ע\"ה","dt":"ז אדר"},{"i":32706,"n":"משה ר\"ה מלובלין","dt":"תקסא - יד סיון","dp":"לובלין","b":"מחכמי לובלין ומראשי הקהילה."},{"i":32707,"n":"משה שאול מירושלים","dt":"תקעג - ח אלול","dp":"ירושלים","b":"מחכמי ירושלים."},{"i":32708,"n":"משה שאול מקאליש","f":"יהודה יודל-קול יהודה","dt":"תקיט - ה ניסן","b":"רב בזורוונא, קאליש."},{"i":32709,"n":"משה שלאנימור מוילנא","f":"ענזיל מסלונים","dt":"תקנב - כה אייר","dp":"וילנא","b":"דיין בוילנא."},{"i":32710,"n":"משה שלום הלוי מפרשבורג","dt":"תקפה - ל סיון","b":"ראב\"ד בפרשבורג, חתם על כתב מנוי רבנות לחת\"ס-תקסז."},{"i":32711,"n":"משה שלום מתונס","k":"בעל ישמח משה","bt":"תקח","bp":"תונס","dt":"תקסו - א אייר","b":"תלמיד ר יוסף זרקא. רב בתונס ומתלמידיו ר ישועה בסיס, ר שלום שמעוני מגפצה, ור שלמה שמאמה בעל \"שורש ישי\" והספידו בספרו. שאלות ממנו בספרי החיד\"א. חיבר חדושים על השס הרמבם ושוע, ונדפס \"ישמח משה\" בסוף \"באר משה\" לר משה כריף.","bk":[["ישמח משה",""]]},{"i":32712,"n":"משה שלמה זלמן מדוקשיץ","f":"מנחם נחום","dt":"תרלה-ח","dp":"ירושלים","b":"רב בדאקשיץ, עלה לירושלים"},{"i":32713,"n":"משה שלמה זלמן מפרצובה","k":"בעל חלק שלמה","dt":"תרכד - יא אב","b":"רב בפארצווע"},{"i":32714,"n":"משה שלמה מטולטשין וילנא","f":"יצחק מטולטשין","k":"בעל אבן שלמה","dt":"תקמו - כה תמוז","dp":"חברון","b":"תלמיד הגר\"א (ואינו ר\"ש מטולטשין הנזכר בבאורי הגר\"א לשו\"ע), העתיק וסידר כ\"י של הגר\"א על הקבלה בשם \"הדרת קודש\". מגיד בוילנא, עלה לירושלים-תקנח. חיבר גם \"שער השירים\", \"ביזת מצרים\" ובו פי' על \"חד גדיא\" להגר\"א, ועוד. נזכר ב\"קריה נאמנה\" ושם נרשם בשם אביו ר נתן מטולטשין. התגורר בכל אחת מארבע ערי הקודש. מבניו - ר טוביה, נכדו - ר יואל משה סלומון - מבוני ירושלים. אולי הוא שהיה אב\"ד וילקומיר-תקמב."},{"i":32715,"n":"משה שלמה מפיעטרקוב","dt":"תרכו - ח טבת","dp":"ירושלים","b":"רב בפטריקוב(=פיעטרקוב), עלה לירושלים. עמד לצדו של ר\"מ יאנובר בזמן המחלוקת."},{"i":32716,"n":"משה שמואל","f":"סעדיה","k":"בעל ביאור לאבן עזרא","b":"חיבר ביאור על האבן עזרא, ופירוש לתורה - בכת\"י (די רוסי)."},{"i":32717,"n":"משה שמואל אהרן הכהן","b":"בנו - ר למל הכהן."},{"i":32718,"n":"משה שמואל הלוי מנרול","b":"סופר בנרול."},{"i":32719,"n":"משה שמואל מאוסטרהא","f":"מנחם מנדל סגל מלבוב","b":"גביר, רופא ופרנס באוסטרהא על מקום אביו-שנות התקכ-ל. בפנקס הח\"ק נרשם כי פדה כתר תורה שהיה מוחזק אצל הגויים זמן רב. חתם שמו \"משה שמואל בן מנחם מאצעראטא רופא מומחה..\"."},{"i":32720,"n":"משה שמואל מלובער","b":"מכובד על צדיקי דורו. ר ישראל מרוזין ביקש לשמוע ממנו דברי תורה. נכדו ר דוד מלובלין."},{"i":32721,"n":"משה שמואל מצפת","b":"מחכמי צפת, בשליחות בשנים תצה ותקה."},{"i":32722,"n":"משה שמואל משטעקטשין","dt":"תרלח - יד ניסן","b":"מגדולי תלמידי ר דוד מללוב."},{"i":32723,"n":"משה שמואל שמלקי מלובלין","f":"יהודה ליב מזאויחואסט","dt":"תקסח - ט סיון","dp":"לובלין","b":"בנו של אב\"ד זאוויחוואסט. מחכמי לובלין - נפטר צעיר."},{"i":32724,"n":"משה שמחה בונם ממסטיץ","b":"רב במעסטיץ(=מסטיץ)-תפה."},{"i":32725,"n":"משה שמלקא","dt":"תריט","dp":"טבריה","b":"רב בניאמץ, עלה לטבריה."},{"i":32726,"n":"משה שמעון הלוי מפרוינקירכן","f":"יהודה מעיר חדש","k":"בעל ישמח לב","bt":"תרכא","bp":"עיר חדש","dt":"תש - ו אייר","dp":"ירושלים","b":"תלמיד השב\"ס, ור יוסף וייסע מעיר חדש. חתן ר ישכר דב בער מנצר מיאקא. רב ביאקא-תרמג על מקום חותנו, פרוינקירכן-תרנב, עזב את הרבנות ועבר לוינה-תרצז. עלה לירושלים-תרצט. בנו ר ישכר הלוי מסינער-ועראלי. חתנו - ר יעקב יוסף זינגר ממאראש-ואשרהעלי. חיבר \"פלח הרימון\" והוא חלק מספרו \"ישמח לב\"."},{"i":32727,"n":"משה שמעון וולף מצפת","b":"מראשי קהילת החסידים בצפת-תקפא."},{"i":32728,"n":"משה שמרל מיאנאוי","f":"יהושע","b":"רב ביאנאוי, אב\"ד קאלברישאך-תקפז ושאל אז את ר אבלי פוסוואלר מוילנא. תשובה ממנו אודות עגונה-תקעד בערך."},{"i":32729,"n":"משה שניאור מדובנא ולובלין","b":"חתם על כתב החרם בדובנא שלא ליסד חברות חדשות-תקכה."},{"i":32730,"n":"משה ששון אריה משלוניקי","f":"היכל המלך","b":"חיבר הקדמה לספר אביו \"היכל המלך\" על הרמב\"ם."},{"i":32731,"n":"משה ששון מאזמיר","b":"רב באזמיר-שצט, עלה לצפת-ת'. השיב לר חיים בנבנישתי מאזמיר."},{"i":32732,"n":"משה ששון מצפת","b":"רב בצפת-תעח. בשליחות כמה פעמים בתורכיה-תף - תץ ר משה אמריליו משלוניקי מזכירו בספרו, אודות משא ומתן שהתקיים בעברו בשלוניקי בינו ובין ר יעקב ן פורנה. תשובותיו בספרי חכמי קושטא ושלוניקי. חתם על כתב שליחות ר דניאל קאפוסטו-תפב. היה בלאריסה-תפח והסכים על פס\"ד של ר יצחק פרנסיס שם."},{"i":32733,"n":"משה, אברהם ממונאסטיר","b":"גביר במונאסטיר-תקן בערך, בנו הגביר מתתיה ממואנסטיר."},{"i":32734,"n":"משה, יהושע מיון וירושלים","bt":"תקצח","bp":"יינישר-יון","dt":"תרצד - יט חשון","b":"עלה לירושלים, מחכמי ירושלים. בנו - ר שמואל יהושע משה."},{"i":32735,"n":"משה, כלב ממונאסטיר","b":"גביר במונאסטיר-תקן בערך, נזכר בהקדמת \"קמח סולת\"."},{"i":32736,"n":"משה, מתתיה ממונאסטיר","f":"אברהם","b":"גביר במונאסטיר-תקן בערך,"},{"i":32737,"n":"משהלס הקדוש, זלמן","dt":"תמט - ג תמוז","b":"עק\"ה,דיין ומו\"ש בפרג"},{"i":32738,"n":"משה'לע טייביל'ס מוילנא","b":"מחכמי \"ישיבת הארבעים\" בוילנא-תקפז."},{"i":32739,"n":"משולם זיסל בן אליעזר ליפמן מהניפולי","dt":"ה'תקס 1800","bk":[["בוצינא קדישא",""]]},{"i":32740,"n":"משומר מתימן","f":"שמואל נסים-ראב\"ד עדן","b":"מחכמי עדן-תימן - בסוף המאה ה-19. נזכר ע\"י ר אברהם ערוסי כגדול חכמי תימן בדורו."},{"i":32741,"n":"משורר בס, מנחם מנלי","f":"בנימין וולף שוואב","dt":"תקמב - ט אלול","dp":"ברלין","b":"מחכמי ברלין. תרגם לאשכנזית יהודית (ז'רגון) את השיר שחיבר ר דוד פרנקל על הצלחת המלך פרידריך במלחמה-תקה (התרגום נעשה מתוך התרגום שנעשה קודם לכן בידי ר אהרן בן שלמה גומפריש ללשון אשכנז."},{"i":32742,"n":"משורר בס, שבתי מפרג","f":"יוסף שטרימר","k":"בעל שפתי ישנים","b":"רב ומשורר בפרג. אבי הביבליוגרפיה העברית. אחיו של ר יעקב תערמילש. הקים דפוס בדירנפורט-תמט. חיבר \"שפתי ישנים\"."},{"i":32743,"n":"משוש ן, יצחק מאלגיר","b":"רב באלגי'ר בזמן הרדבז."},{"i":32744,"n":"משיוף (מוסיוף), אפרים יצחק","f":"יעקב זבולון","bt":"תרי","bp":"ירושלים","dt":"תרפא - כח אדר","dp":"ירושלים","b":"עסקן צבור בירושלים."},{"i":32745,"n":"משיוף (מוסיוף), שמואל מירושלים","bt":"תרמו","bp":"ירושלים","b":"מנהל ועד העיר בירושלים."},{"i":32746,"n":"משיח, יהודה מפאס","b":"רב בפאס, חתם-תט על הסכמה עם ר סעדיה ן דנון."},{"i":32747,"n":"משיח, שלמה מפרס","r":"רב בוולוז'ין ומיץ ועוד, 'בעל התוספות' וולרשטין ,","dt":"תשטז - טו תמוז","dp":"ירושלים","b":"רבם של אנוסי משהד-פרס, מקובל, עלה לירושלים. ע\"ש ישיבת \"תפארת שלמה\" בירושלים. יסד את \"תיקון כרת\" שמתקיים אצל מקובלי ירושלים מדי חדש בחדשו."},{"i":32748,"n":"משיש, משה","b":"מגדולי חכמי אלג'יר-ק\"פ"},{"i":32749,"n":"משיש, משה מאלגיר","f":"יצחק","dt":"ת - בערך","b":"רב באלגיר-שסד. מתלמידיו - ר שלמה דוראן, ור שלמה בן צמח דוראן, והסכים עמם על כמה תשובות. חתם על בקשה לר חיים קנשינו מווהארן למסור את נדבת אביו ר יצחק לשלוחי צפת, וחתם על בקשה מראשי קהילת ווהארן ר חיים קנשינו ור אליהו ששפורטש בענין פדיון השבוי ר יעקב פריינטי."},{"i":32750,"n":"משיש, שלמה מאלגיר","f":"יצחק","k":"בעל פתחי שערים","b":"רב באלגיר."},{"i":32751,"n":"משכיל לאיתן, אברהם יצחק","f":"אהרן","k":"בעל זרע איתן","bt":"תר","dt":"תרסד - יד חשון","b":"רב בסמולוביץ-תרלד, חסלוביץ-תרמט, סטויפיץ(=שטויבץ)-תרסד.","bk":[["משכיל לאיתן",""]]},{"i":32752,"n":"משכיל לאיתן, אברהם מנווהרדוק","f":"אריה י\"ל מרדושקביץ","k":"בעל משכיל לאיתן","bt":"תקמח","bp":"רדושקביץ","dt":"תרח - יח תמוז","dp":"מינסק","b":"נכד ר ישראל משקלוב בעל \"אור ישראל\". אב\"ד נוברדוק(=נווהרדוק), הורודק-ליד וולוזין, רב בפטרוביץ, מינסק. חיבר גם \"אהבת איתן\", \"מצפה איתן\", \"באר אברהם\", ועוד. בניו: ר משה ניסן משומיאץ בעל \"חקרי הלכות\", ר נפתלי ממינסק בעל \"רוח חכמים\", ר נפתלי ממינסק, ר קלמן, ר אהרן, ר ליב. חתנו ר ראובן כץ אב\"ד פתח תקוה.","bk":[["מצפה איתן [על הגמרא]","מפרשי ש\"ס - אחרונים"],["באר אברהם",""],["יד אברהם",""],["יד איתן – רמב\"ם",""],["מצפה איתן",""],["נחל איתן",""],["משכיל לאיתן – מועד וקדשים",""],["מצפה איתן [על המשנה]","מפרשי ש\"ס - אחרונים"],["יד אברהם","מפרשי שו\"ע"],["נחל איתן","מפרשי רמב\"ם"]]},{"i":32753,"n":"משכיל לאיתן, אהרן","f":"אברהם מנווהרדוק"},{"i":32754,"n":"משכיל לאיתן, משה ניסן משומיאץ","f":"אברהם מנווהרדוק","k":"בעל חקרי הלכות","b":"רב בשומיאץ-תר\"כ"},{"i":32755,"n":"משכיל לאיתן, נפתלי","f":"אברהם מנווהרדוק","k":"בעל עשרה מאמרות","bt":"תקפט","bp":"רדושקביץ","dt":"תרנח - ו כסלו","dp":"מינסק","b":"אביו היה רב ברדושקביץ. עסקן ציבורי במינסק ומחבר. סידר והגיה את \"סדר הדורות\". חיבר גם פירוש על בן סירא. פרסם מאמרים ב\"האסיף\", \"כנסת ישראל\", ועוד. פרסם גם שירים ומשלי מוסר."},{"i":32756,"n":"משכיל, אברהם מאזמיר","dt":"תקלג - יז כסלו","dp":"איזמיר","b":"מחכמי אזמיר."},{"i":32757,"n":"משלו ן, סעדיה ממרוקו","b":"נזכר ב\"תקפו של יוסף\" לר יוסף אלמליח."},{"i":32758,"n":"משלם בן משה מבדריש; בלוי משה יהודה","bt":"1912","dt":"ה'תשסג 2003","bk":[["ספר ההשלמה",""],["ספר המאורות",""]]},{"i":32759,"n":"משלם הלוי מאיטליה","k":"בעל הגהות על הטור","b":"רב בפדובה-תץ, רב במודנא על מקום ר אברהם יוסף שלמה גראציאנו. חיבר הגהות על הטור בכת\"י - (היה אצל נכדו ר אליעזר הלוי מטריאסט). בנו ר נתנאל הלוי מפדובה ומודנא, ובנו היה ר צבי הלוי - שהיה בשליחות ירושלים באיטליה, ובנו ר אברהם אליעזר הלוי מירושלים. תשובות ממנו ומבנו ר נתנאל - ב\"דבר שמואל\"."},{"i":32760,"n":"משלם הלוי ממונשטיר","b":"דיין במונשטיר-שנות ה-ת' אצל ר בנימין די מדינה."},{"i":32761,"n":"משלם הלוי מקושטא","b":"רב בקושטא-ש'."},{"i":32762,"n":"משלם זוסיא מאניפולי","f":"אליעזר ליפמן","k":"בעל מנורת זהב","bt":"תפג \\ תצ","dt":"תקס - ב שבט","dp":"אניפולי","b":"אחיו הגדול של הנועם אלימלך. תלמיד המגיד ממזריטש, ונקבר לצדו. מתורתו ב\"מנורת זהב\", ותולדותיו ב\"בוצינא קדישא\".","bk":[["זהב המנורה - על התורה",""],["מנורת זהב - על התורה",""]]},{"i":32763,"n":"משלם זוסמן מזיטומיר","k":"הו\"ל בת עין","b":"תלמיד ר אברהם דב מאווריטש, וכותב דברי תורתו ב\"בת עין\"."},{"i":32764,"n":"משלם זושא מלבוב","b":"רב בלבוב-תר\"מ"},{"i":32765,"n":"משלם זלמן הכהן ממנהיים","b":"רב במנהיים-תק\"נ"},{"i":32766,"n":"משלם זלמן הכהן מפיורדא","k":"מהרז\"ך - בגדי כהונה","bt":"תצט","bp":"ראויטש-פלך פוזנא","dt":"תקפ - כט כסלו","dp":"פיורדא?","b":"תלמיד ר יונתן איבשיץ. אב\"ד קרוטושין, קעמפנא, צילץ, פיורדא-תקן. חיבר גם: \"משען המים\" פיורדא תקמא, ועוד. תלמידו - ר אברהם בנימין המבורג חיבר הספד עליו ב\"קול בוכים\". בנו - ר שלמה כץ אב\"ד שנייטוך וצילץ."},{"i":32767,"n":"משלם זלמן הכהן משווערין","f":"שלמה מצילץ","bt":"תקפב","bp":"צילץ","dt":"תרסב - כ אלול","dp":"ברסלוי","b":"תלמיד החת\"ס והכת\"ס, וחתן רבו ר יעקב עטלינגר מאלטונא. רב באפעללען-תרז, מסטריכט (הולנד)-תריג, שווערין-מקלנבורג-תרכג, ברלין-תרלו."},{"i":32768,"n":"משלם זלמן הלוי","f":"המהרש\"א","b":"רב-שנת ת'. בנו - ר יהודה ליב. י\"א ששמו יהודה ליב - (\"אגרת היחס\" שנדפס ב\"חדושי הרז\"ה\")."},{"i":32769,"n":"משלם זלמן חסיד הכהן מפרנקפורט","f":"שמעיה","bt":"תפב","dt":"תקנא - ו חשון","dp":"פפד\"מ","b":"תלמיד ר אברהם אביש מפרנקפורט, הבעש\"ט. ראש ישיבה במנהיים, פרנקפורט-תקיב כ-40 שנה. רבו של החת\"ס בפרנקפורט. נספד ע\"י ר נתן מז, ר אברהם טריר ואב\"ד פפד\"מ."},{"i":32770,"n":"משלם זלמן מבקשביץ","b":"רב בבקשביץ-תקעח"},{"i":32771,"n":"משלם זלמן מלובלין","f":"צבי הירש","b":"חתן ר חיים הכהן רפפורט מפינסק וירושלים. מחכמי לובלין-תקץ."},{"i":32772,"n":"משלם זלמן ממזריטש","f":"משה יוסף","k":"משלם זלמן מעזירטשער","bp":"מזריטש-פרבר אוסטרהא","dt":"תקכז - י סיון","dp":"אוסטרהא","b":"אחיו של ר אריה ליביש ממזריטש. תלמיד הבעשט, תלמיד ישיבת ר שלמה זלמן הכהן באוסטרהא. (היה אחד משלושת גדולי אוסטרהא בדורו שנקרא בשם זלמן והם ר אברהם משלם זלמן בן החכם צבי ונקרא - \"זלמיני\", ר שלמה זלמן בן יהודה כץ שנקרא - \"זעלמלא\", ותלמידו ר משלם ממזריטש שנקרא - \"ר זעלמילא מעזריטשער\" - ונחשב לגדול שבהם). נשא בת גביר מאוסטרהא וכיהן ללא שכר כר\"מ לתלמידים באוסטרהא, ופרנס. נספד ע\"י ר אברהם משלם זלמן ב\"דברי רב משלם\". נזכר בצוואת ר דוד הלפרין מאוסטראה. בנו ר גרשון - נפטר ו תשרי תקכח."},{"i":32773,"n":"משלם זלמן מראסיין","f":"אריה","dt":"תקצז - טז אלול","dp":"ראסיין","b":"מלמד תורה בראסיין. בנו - ר אהרן מראסיין וקובנא, וחתנו - ר משה לעדינבלאט מראסיין."},{"i":32774,"n":"משלם מבדרש","f":"משה מלוניל","k":"בעל ספר ההשלמה","dt":"ד'תתקצח","b":"מגדולי הראשונים,מחכמי פרובינצה"},{"i":32775,"n":"משלם מוולטירה","b":"חיבר קונטרס בסגולת האבנים הטובות. מובא ב\"שלטי הגבורים\" לר אברהם הרופא."},{"i":32776,"n":"משלם מוילנא","f":"יהודה","b":"רב בוילנא, שאל-שיז את המהרש\"ל יחד עם ר מנחם אליקום טרוויש."},{"i":32777,"n":"משלם מונציה","f":"קויפמן","b":"הגיה ספר בית יוסף - ונציה שנה והוסיף מפתחות."},{"i":32778,"n":"משלם מלבוב","f":"אברהם","dt":"שסב - ט ניסן","dp":"לבוב","b":"מרביץ תורה בלבוב."},{"i":32779,"n":"משלם מלבוב - ב","f":"אברהם","b":"ר\"מ בלבוב."},{"i":32780,"n":"משלם מלוניל","dt":"ד'תתקל","b":"עשיר,מגדולי הראשונים,מחכמי לוניל בצרפת"},{"i":32781,"n":"משלם מלוקה","f":"קלונימוס מלוקה","b":"מגדולי חכמי איטליה, פוסק, פייטן, מנהיג, מרביץ תורה בלוקה, מגנצא-ד'תת\"כ."},{"i":32782,"n":"משלם ממינצבורג","f":"דוד","b":"מגדולי חכמי אשכנז,פוסק-שנת כ'"},{"i":32783,"n":"משלם מפאריס","f":"נתן","bt":"ד'תתפ","b":"מגדולי בעלי התוספות,מרביץ תורה ליד פאריש"},{"i":32784,"n":"משלם מפירפיניאן","f":"אבא מרי","b":"חתן ר משה בן שמואל בן אשר - שהיה מתומכי אביו בזמן המחלוקת על הפילוסופיה. אביו ר אבא מרי שגורש ממונטפלייר רצה להתישב בפירפיניאן אצל בנו - אך מתנגדיו מנעו זאת ממנו."},{"i":32785,"n":"משלם מפרשבורג","f":"שמשון","b":"מוזכר ב\"פקודת המלך\"."},{"i":32786,"n":"משלם מקולומיאה","f":"ישעיה","b":"רב בקולומיאה(=קאלימיי) ובנו ר פישל על מקומו אחריו, דיין בלבוב, חתם-תפז על פס\"ד. מצאצאי ר משלם זלצברוג בן אברהם אשכנזי מלבוב."},{"i":32787,"n":"משלם סגל מונציה","f":"יעקב","b":"רב בונציה. הגן על הרב מן - בזמן המחלוקת כנגדו - יחד עם ר מנחם הכהן מונציה - כמובא בשו\"ת מהרמא\"י."},{"i":32788,"n":"משלם פיבוש מוילנא","f":"מנחם מנדל מראווגע","dt":"תקסט - כ סיון","dp":"וילנא","b":"חתן ר אריה ליב בן דב בער מוילנא. מחכמי וילנא."},{"i":32789,"n":"משלם פיבש מזולקוא","f":"אליעזר","b":"מחכמי זולוקא, חתם-תמה בפנקס הקהל, וכן בשנת תנב עם ראשי הקהל, ועוד."},{"i":32790,"n":"משלם פיבש מיאסי","f":"יעקב יצחק","b":"רב ביאסי-תר\"ע"},{"i":32791,"n":"משלם פיבש מלנטשא","dt":"תקמט - כ שבט","b":"רב בלענטשנא"},{"i":32792,"n":"משלם פיבש ממינסק","f":"צבי הירש","dt":"תכ? - ה כסלו","dp":"מינסק","b":"רב במינסק."},{"i":32793,"n":"משלם פיבש מקראקא","f":"ישראל שמואל","k":"בעל שמות גיטין","bt":"שח - בערך","dt":"שעח","b":"רב בבריסק?, קראקא-שנט בערך על מקום ר ישעיה מנחם ר אביגדורס. מתלמידיו - בעל הב\"ח שכיהן על מקומו אחריו בקראקא. התכתב עם גדולי דורו ובהם המהר\"ם מלובלין, בעל הסמ\"ע, בעל הב\"ח - שהזכירוהו בספריהם. בקי בחכמות ובשפות. הו\"ל שו\"ת מהר\"ם מינץ עם הסכמה ממנו. בניו - ר יוסף, ר שמואל מפרמישלא."},{"i":32794,"n":"משלם פיבש סגל מזברז","f":"מנחם מנלי","b":"רב בזברז-תקצז."},{"i":32795,"n":"משלם פייש סגל הלוי מטאהש","f":"מרדכי מדעמעטשער","k":"אדמור מטאש","bt":"תרפב","b":"נכד ר אלימלך סגל הלוי מטאהש. תלמיד דודו ר מנחם בראדי מקלוב בעל \"באר מנחם\". חתן נכדת ר אלימלך מליזנסק. ניצל מהשואה, אדמור מטאהש על מקום אבותיו, עבר לנירדהאז, עבר למונטריאול-קנדה, הקים קרית טאהש-תשכג ליד מונטריאול, והקים שם ישיבה. דודו ר צבי אביגדור פעקעטע מנאנאנש, ור חיים שלמה לוי מחוסט - שעברו לניו יורק."},{"i":32796,"n":"משלם שרגא סגל מבירז","dt":"תריט-מט","b":"מו\"צ בבירז בזמן ר שלמה זלמן זקש (באלבום ליטא - רב בבירז על מקום ר דוד בעל \"שירה לדוד\", ור אשר ניסן לוינזון על מקומו אחריו). היה מחלוקת כנגדו בבירז - מצד קנתרנים שקצרו את ימיו."},{"i":32797,"n":"משלם, אשר הלוי מפדובה","dt":"רצב","dp":"פדובה","b":"רב בפדובה. ראה גם: אשר הלוי ציון מאיטליה."},{"i":32798,"n":"משלם, מרדכי הלוי מפדובה","dt":"שנז - יט כסלו","dp":"פדובה","b":"רב בפדובה ממשפחת העדולמי וממשפחת המשולמי בזמן הרב ארקיוולאטי בעל \"ערוגת הבשם\"."},{"i":32799,"n":"משנה, יוסף מחלב","b":"מראשי קהלת הספרדים בחלב-שנות ה-ש'."},{"i":32800,"n":"משעאלי, מרדכי ממוגאדור","b":"מחכמי מוגאדור, חתם-תקמח על פס\"ד עם ר משה לוגסי, ר יוסף יעקב בנבנישתי."},{"i":32801,"n":"משעל, יהודה ממצרים","b":"רב ברשיד(=רוזיתא)-מצרים - שנות ה-ר'-ש'."},{"i":32802,"n":"משעל-סקלי, אהרן מתאזא","dt":"תכה - בערך","dp":"תאזא","b":"מושל העיר תאזא-מרוקו. כנראה בן למשפחת הכהנים סקלי שהגיעו מדיבדו-מרוקו."},{"i":32803,"n":"משען, אליהו מחלב","f":"אברהם","k":"בעל שפת אמת","dt":"תרמב - כ אד\"ב","b":"מקובל, מחכמי ארם צובה, חיבר \"שפת אמת\""},{"i":32804,"n":"משען, יהודה מצפת","k":"בעל פירוש להגדה","dt":"שע - אחרי","dp":"צפת?","b":"עשיר, מחכמי צפת ומתלמידי הארי, חתום על שטר התקשרות תלמידי הארי משנת שלה. דברים משמו בספרי חכמי דורו וביניהם ר חיים ויטאל. חיבר פירוש על הגדה של פסח בכתב יד."},{"i":32805,"n":"משען, יצחק מטריפולי","b":"רב בטריפולי-לבנון-שד, צפת-שך."},{"i":32806,"n":"משען, יצחק מלאריסה","b":"רב בפטרץ, לאריסה-תף בערך, וחזר לפטרץ."},{"i":32807,"n":"משען, מיכאל מאר\"ץ","dt":"תרעג - יח אב","b":"רב בחלב."},{"i":32808,"n":"משען, מרדכי חיים מדמשק","dt":"תרפה - כח אייר","b":"רב בדמשק."},{"i":32809,"n":"משען, משה מפטרץ ולאריסה","b":"רב בפטרץ, עבר ללאריסה-תמה לאחר כיבוש פטרץ בידי ונציה."},{"i":32810,"n":"משען, שמואל מלאריסה","f":"יצחק","b":"דיין בלאריסה-תקד אצל ר אליהו חנדלי, יחד עם ר אברהם פילוסוף."},{"i":32811,"n":"משקינה, יוסף מפורטוגל","b":"רב בפורטוגל. - חתנו בעל \"באר יצחק\" הספידו ב\"באר לחי רואי\"."},{"i":32812,"n":"משרסקי, יעקב ירוחם מלאזני","f":"ישראל הכהן","bt":"תרטז","b":"מצאצאי הבעש\"ט. עוזר הוראה בלאזני-פלך מוהילוב-תרמז אצל ר אהרן, ומו\"ץ-תרס. נסמך מאת הרידב\"ז."},{"i":32813,"n":"מתמיד, יעקב מביאליסטוק","dt":"תשג","b":"מרביץ תורה בביאליסטוק"},{"i":32814,"n":"מתקה ן, יהודה הכהן מטולדו","f":"שלמה","k":"בעל מדרש החכמה","bt":"ד'תתקעה","bp":"טולדו","b":"מחכמי ספרד, פילוסוף, ומקורב למלכות - אל הקיסר פרידריך השני, תלמיד הרמ\"ה, חיבר \"מדרש החכמה\", חיבור בתורת ההגיון, פיסיקה, מטפיסיקה, פסיכולוגיה, הנדסה, וחיבור \"משפטי הכוכבים\" באסטרולוגיה, התנגד לשיטתו הפילוסופית של הרמב\"ם."},{"i":32815,"n":"מתתיה אברהם ממונשטיר","b":"מראשי קהלת מונשטיר, היה בוינה-תקע בערך. סייע לר יהודה ן סיד בהדפסת ספרו \"נר מצוה\"."},{"i":32816,"n":"מתתיה גאון פומפודיתא","f":"ביבי","b":"גאון בפומפדיתא - ד'תרכ (880) על מקום ר אחאי, ובתקופת ר עמרם גאון בסורא. תשובות ממנו בקובץ תשובות הגאונים."},{"i":32817,"n":"מתתיה מאוטיאן והורודוק","f":"נפתלי הירש מהורודוק","b":"אב\"ד הורודוק. בנו - ר יהודה ליב שטראשון שעלה לירושלים, ונכדו - ר אברהם דוד שטראשון מוילנא."},{"i":32818,"n":"מתתיה מארטא וטריקולה","bt":"רמה","bp":"פדובה","b":"תלמיד ר יהודה מינץ ונסמך ממנו. מחכמי ארטא, בקשרי הלכה עם הרא\"ם ועם ר משה קפסלי. בנו - ר בנימין."},{"i":32819,"n":"מתתיה מבודה","f":"נתן שאול","b":"רב בבודין(=בודה)-שנות ה-ש'."},{"i":32820,"n":"מתתיה מקאבאלה","f":"נתן","b":"רב הקהלה האשכנזית בקאבאלה-שנות ה-ש'."},{"i":32821,"n":"מתתיה מקוסוב וקוצק","b":"רב בקאסובה,זרמב,קוצק-תר\"ל"},{"i":32822,"n":"מתתיהו בן יוחנן כהן גדול","dt":"טו חשון"},{"i":32823,"n":"מתתיהו הכהן משלוניקי","f":"שלמה - מהרש\"ך","b":"רב בשלוניקי - שץ בערך."},{"i":32824,"n":"מתתיהו הלוי ממגנצא","dt":"תיא - יד אד\"א","b":"רב במגנצא - למעשה היתה הקהילה כפופה לרבה של בינגן - עד שץ, עבר לפפד\"מ. חיבר הגהות ל\"תורת חטאת\"."},{"i":32825,"n":"מתתיהו מארץ ישראל","f":"חיים מפיקוב","b":"אביו היה אב\"ד פיקוב. עלה לארץ-תקמט. חתם לאחר ר אברהם מקאליסק."},{"i":32826,"n":"מתתיהו מבריגל","b":"צדיק בבריגל-תקע. ר שלמה בוכנר מקרשנוב נסע אליו."},{"i":32827,"n":"מתתיהו מלבוב","f":"סיני","dt":"תיא - ז כסלו","dp":"לבוב","b":"דיין בלבוב. חתם-תז בפנקס הקהלה."},{"i":32828,"n":"מתתיהו מפאריש","f":"יוסף","b":"מחכמי בית שאן, מוזכר ב\"כפתור ופרח\" לר אשתורי הפרחי וכנראה שהכירו ונפטר בחייו. מובא ב\"שערי ציון\" לר\"י די לאטיש."},{"i":32829,"n":"מתתיהו מפרשבורג","dt":"תקפה - כא תמוז","dp":"פרשבורג","b":"מחכמי פרשבורג."},{"i":32830,"n":"מתתיהו מקוסוב","f":"נחמן מאוזירן","k":"העילוי מוענגראווי","dt":"תריא","b":"תלמיד החוזה מלובלין, ר שמואל מקאריב שמינהו לרב בקוסוב-ליד לובלין, ואדמור אחר פטירת רבו ר שמואל. היה אדמור בקוסוב, זרומבה, ועזב לקוצק. פעל להעביר את ר מנחם מנדל מטומשוב לקוצק. בזמן שהיה אדמור עזב את חסידיו ונסע לר שמחה בונם מפשיסחא ולר מנחם מנדל מקוצק."},{"i":32831,"n":"מתתיהו משערשוב ובוטען","f":"מאיר","k":"בעל מתת ידו","b":"רב בשערשוב-תרמב, בוטען."},{"i":32832,"n":"מתתיהו נתן משלוניקי","dt":"שלא","dp":"שלוניקי","b":"רב בק\"ק אשכנזים בשלוניקי. נספד ע\"י ר שלמה הלוי הזקן."},{"i":32833,"n":"מתתיהו, מרדכי מטריפולי","dt":"תמו","dp":"טריפולי","b":"רב בטריפולי. נזכר ב\"ימות עולם\" לר אברהם כלפון."},{"i":32834,"n":"מתתיהו, מרדכי מסאבאטיטש","b":"רב בסאבאטיטש-תקי."}];
